prompt --application/shared_components/user_interface/lovs/adf_tracking_no
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(221809708863021964)
,p_lov_name=>'ADF_TRACKING_NO'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT       ',
'       wph.tracking_no,       ',
'       wph.buyer_id,       ',
'      xxpwc.pwc_master_tracking_data_func@adf (wph.tracking_no, ''BUYER_NAME'')       ',
'         customer_name,       ',
'      xxpwc.pwc_master_tracking_data_func@adf (wph.tracking_no, ''STYLE_NAME'')       ',
'         style_name,   ',
'      xxpwc.pwc_master_tracking_data_func@adf (wph.tracking_no, ''STYLE_NO'')   ',
'         style_no,   ',
'      sd.season_name,       ',
'      xxpwc.pwc_master_tracking_data_func@adf (wph.tracking_no, ''TRACKING_MODE'')       ',
'         tracking_mode,       ',
'       xxpwc.pwc_master_tracking_data_func@adf (wph.tracking_no,       ',
'                                            ''TRACKING_MODE_DESC'')       ',
'          tracking_mode_desc,       ',
'       wph.brand_name,       ',
'       wph.buyer_agent_name,       ',
'       wph.invoicing_unit_id,       ',
'       oopv.inv_org_name invoicing_unit_name,       ',
'       wph.retailer_dept,       ',
'       sd.season_status       ',
'  FROM pwc_ont_wvn_precosting_h@adf wph, pwc_mt_season_details_d@adf sd,     ',
'       xxpwc.inv_org_ou_pwc_v@adf oopv     ',
' WHERE     wph.tracking_no IS NOT NULL       ',
'       AND oopv.organization_id = wph.invoicing_unit_id        ',
'       AND sd.tracking_no = wph.tracking_no       ',
'       AND sd.season_status = ''Open''       ',
'       AND wph.tracking_no NOT IN (SELECT NVL (bom.tracking_no, ''N/A'')       ',
'                                     FROM pwc_ont_wvn_master_bom_h@adf bom)',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'TRACKING_NO'
,p_display_column_name=>'TRACKING_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'TRACKING_NO'
,p_default_sort_direction=>'ASC'
);
