prompt --application/shared_components/user_interface/lovs/adf_tracking_no_thread_head
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(227812280649363368)
,p_lov_name=>'ADF_TRACKING_NO_THREAD_HEAD'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH tracking_data AS (',
'    SELECT ac.customer_name,',
'          sl.style_name,',
'          sl.style_number,',
'          sl.style_identifier,',
'          sd.season_identifier,',
'          sd.season_name || ''.'' || sd.season_year season_name,',
'          bh.buyer_id,',
'          sl.style_category,',
'          sd.tracking_no,',
'          sd.division,',
'          bh.tracking_mode,',
'          bh.planning_mode,',
'          DECODE (bh.tracking_mode,',
'                  ''MS'', ''Master Style'',',
'                  ''CS'', ''Child Style''),',
'          DECODE (bh.planning_mode,  ''C'', ''Country'',  ''D'', ''DCPO''),',
'          bd.brand_description    ',
'     FROM pwc_mt_buyer_details_h bh,',
'          pwc_mt_brand_details_d bd,',
'          pwc_mt_style_details_l sl,',
'          pwc_mt_season_details_d sd,',
'          apps.ar_customers@adf ac',
'    WHERE     1 = 1',
'          AND bh.header_id = bd.header_id',
'          AND bd.brand_line_id = sl.brand_line_id',
'          AND sl.style_line_id = sd.style_line_id',
'          AND sd.season_identifier IS NOT NULL',
'          AND sd.tracking_no IS NOT NULL',
'          AND ac.customer_id = bh.buyer_id',
'          --AND sd.tracking_no =  p_tracking_no;',
')',
'',
'SELECT ',
'    ac.customer_name,',
'    td.style_name,',
'    td.style_number,',
'    td.season_name,',
'    h.tracking_no,',
'    td.brand_description,',
'    h.buyer_agent_name,',
'    h.buyer_id',
'',
'FROM pwc_ont_wvn_precosting_h h',
'',
'JOIN apps.ar_customers_v@adf ac',
'    ON h.buyer_id = ac.customer_id',
'JOIN tracking_data td',
'    ON td.tracking_no = h.tracking_no',
'',
'AND NOT EXISTS (',
'    SELECT 1',
'    FROM pwc_ont_wvn_thrd_consumption_h hi',
'    WHERE hi.tracking_no = h.tracking_no',
');'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'TRACKING_NO'
,p_display_column_name=>'TRACKING_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'TRACKING_NO'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(155355287779910863)
,p_query_column_name=>'CUSTOMER_NAME'
,p_heading=>'Customer Name'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(227835984992340479)
,p_query_column_name=>'TRACKING_NO'
,p_heading=>'Trancking No.'
,p_display_sequence=>10
