prompt --application/shared_components/user_interface/lovs/bundle_movement_cd_ig_populate_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(159419516822416524)
,p_lov_name=>'BUNDLE_MOVEMENT_CD_IG_POPULATE_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SUM(mmcd.cut_qty) total_pcs,',
'       mmcl.cut_no,',
'       mmch.r_plan_no ratioplan_number,',
'       DECODE(:P86_ISSUE_TO,',
'              ''Receive from Small Parts comment as on 21-12-2022'',',
'              REGEXP_SUBSTR(mmcl.bpo_no,''[^::]+'',1,1),',
'              mmcl.bpo_no) bpo_no,',
'       mmcl.country,',
'       mmcl.production_stage,',
'       mmcl.integration_cut_number,',
'       mmcl.bpo_no merge_bpo_no,',
'       NULL pattern_country,',
'       NULL batch_no,',
'       mmcl.stn_no,',
'       (SELECT DISTINCT bndl.color',
'          FROM pwc_mfg_cutlyrcntrl_bnd_l bndl',
'         WHERE bndl.line_id = mmcl.line_id) color,',
'       (SELECT DISTINCT mmcl.line_no',
'          FROM pwc_mfg_cutissuance_line mmcl,',
'               pwc_mfg_cutissuance mmc',
'         WHERE mmc.cutissue_id = mmcl.cutissue_id',
'           AND mmcl.attribute1 = mmcl.cut_no',
'           AND mmcl.line_no IS NOT NULL',
'           AND ROWNUM <= 1) receive_line_no,',
'       (SELECT DISTINCT integration_lay_number',
'          FROM pwc_mfg_ratioplan_plycfline',
'         WHERE cut_no = mmcl.cut_no) lay_number',
'  FROM pwc_mfg_cutlyrcntrl_d mmcd,',
'       pwc_mfg_cutlyrcntrl_l mmcl,',
'       pwc_mfg_cutlyrcntrl_h mmch,',
'       inv_org_ou_pwc_v inv',
' WHERE mmcd.line_id = mmcl.line_id',
'   AND mmcl.header_id = mmch.header_id',
'   AND mmcl.process_error_desc LIKE ''%Post%''',
'   AND mmch.org_id = inv.ou_id',
'   AND mmch.tracking_no = :P86_TRACKING_NO',
'   AND mmch.r_plan_no = :P86_RATION_NO',
'   AND :P86_ATTRIBUTE1 = ''DENIM''',
'   AND NOT EXISTS (',
'         SELECT 1',
'           FROM pwc_mfg_cutissuance_line mmcll,',
'                pwc_mfg_cutissuance mmc',
'          WHERE mmcll.attribute1 = mmcl.cut_no',
'            AND mmc.cutissue_id = mmcll.cutissue_id',
'            AND TRIM(REGEXP_REPLACE(mmc.issue_to,''[0-9]'','''')) =',
'                TRIM(REGEXP_REPLACE(:P86_ISSUE_TO,''[0-9]'',''''))',
'            AND mmcll.quantity - mmcll.issued_quantity = 0)',
'GROUP BY mmcl.cut_no,',
'         mmch.r_plan_no,',
'         mmcl.bpo_no,',
'         mmcl.country,',
'         mmcl.production_stage,',
'         mmcl.integration_cut_number,',
'         mmcl.stn_no,',
'         mmcl.line_id',
'',
'UNION',
'',
'SELECT SUM(mmcd.cut_qty) total_pcs,',
'       mmcl.cut_no,',
'       mmch.r_plan_no ratioplan_number,',
'       DECODE(:P86_ISSUE_TO,',
'              ''Receive from Cutting'',',
'              REGEXP_SUBSTR(mmcl.bpo_no,''[^::]+'',1,1),',
'              mmcl.bpo_no) bpo_no,',
'       mmcl.country,',
'       mmcl.production_stage,',
'       mmcl.integration_cut_number,',
'       mmcl.bpo_no merge_bpo_no,',
'       mmcl.pattern_country,',
'       RTRIM(',
'         REGEXP_REPLACE(',
'           LISTAGG(mmcd.supplier_batch_no,'', '')',
'           WITHIN GROUP(ORDER BY mmcd.supplier_batch_no),',
'           ''([^::]*)(::\1)+($|::)'',''\1\3''),',
'         ''::'') batch_no,',
'       mmcl.stn_no,',
'       (SELECT DISTINCT bndl.color',
'          FROM pwc_mfg_cutlyrcntrl_bnd_l bndl',
'         WHERE bndl.line_id = mmcl.line_id) color,',
'       NULL receive_line_no,',
'       NULL lay_number',
'  FROM pwc_mfg_cutlyrcntrl_d mmcd,',
'       pwc_mfg_cutlyrcntrl_l mmcl,',
'       pwc_mfg_cutlyrcntrl_h mmch',
' WHERE mmcd.line_id = mmcl.line_id',
'   AND mmcl.header_id = mmch.header_id',
'   AND mmcl.process_error_desc LIKE ''%Post%''',
'   AND mmch.tracking_no = :P86_TRACKING_NO',
'   AND mmch.r_plan_no = :P86_RATION_NO',
'   AND :P86_ATTRIBUTE1 <> ''DENIM''',
'   AND NOT EXISTS (',
'         SELECT 1',
'           FROM pwc_mfg_cutissuance_line mmcl,',
'                pwc_mfg_cutissuance mmc',
'          WHERE mmcl.attribute1 = mmcl.cut_no',
'            AND mmc.cutissue_id = mmcl.cutissue_id',
'            AND mmc.issue_to = :P86_ISSUE_TO',
'            AND quantity - issued_quantity = 0)',
'GROUP BY mmcl.cut_no,',
'         mmch.r_plan_no,',
'         mmcl.bpo_no,',
'         mmcl.country,',
'         mmcl.production_stage,',
'         mmcl.integration_cut_number,',
'         mmcl.pattern_country,',
'         mmcl.stn_no,',
'         mmcl.line_id;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'CUT_NO'
,p_display_column_name=>'CUT_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'CUT_NO'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(159419927226449239)
,p_query_column_name=>'CUT_NO'
,p_heading=>'Cut No.'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
wwv_flow_imp_shared.create_list_of_values_cols(
