prompt --application/shared_components/user_interface/lovs/cutting_spreading_d_remaining_roll_id_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(144121313906041603)
,p_lov_name=>'CUTTING_SPREADING_D_REMAINING_ROLL_ID_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM (SELECT ROLL_NO,',
'       SUPP_ROLL_NO,',
'       REMAINING_ROLL_LENGTH ACTUL_METER,',
'       TRACKING_NO,',
'       COLOR,',
'       SHADE,',
'       SHRINKAGE_LENGTH,',
'       SHRINKAGE_WIDTH,',
'       ''Used'' ROLL_TYPE',
'  FROM (SELECT d.d_id,',
'               d.ROLL_ID ROLL_NO,',
'               D.SUPP_ROLL_NO,',
'               d.REMAINING_ROLL_LENGTH,',
'               H.TRACKING_NO,',
'               H.COLOR,',
'               D.SHRINKAGE_WIDTH,',
'               D.SHRINKAGE_LENGTH,',
'               L.SHADE,',
'               ROW_NUMBER ()',
'                  OVER (PARTITION BY d.ROLL_ID ORDER BY d.d_id DESC)',
'                  rn',
'          FROM cutting_spreading_d d',
'               JOIN cutting_spreading_L L',
'                  ON D.L_ID = L.L_ID',
'               JOIN cutting_spreading_H H',
'                  ON L.H_ID = H.H_ID',
'        where D.WASTE_FLAG = ''N''',
'        AND H.COLOR = :P50_COLOR',
'        AND H.TRACKING_NO = :P50_TRACKING_NO',
'       )',
' WHERE rn = 1',
' AND REMAINING_ROLL_LENGTH > 0',
'',
'UNION ALL ',
'',
' SELECT FS.ROLL_NO,',
'       FS.SUPP_ROLL_NO,',
'       FS.ACTUL_METER,',
'       L.TRACKING_NO,',
'       L.COLOR,',
'       FS.SHRINKAGE_SHADE SHADE,',
'       FS.SHRINK_PRC_LENGTH,',
'       FS.SHRINK_PRC_WIDTH,',
'       ''Fresh'' ROLL_TYPE',
'  FROM PWC_MFG_FABRIC_INS_TEST_L@adf fs,',
'       PWC_MFG_FABINS_PROD_L@adf l,',
'       PWC_MFG_FABINS_FIRST_D@adf c,',
'       PWC_MFG_FABINS_SECND_D@adf b',
'WHERE     1 = 1',
'       AND l.prod_l_id = fs.prod_l_id',
'       AND c.prod_l_id = l.prod_l_id',
'       AND b.roll_no = fs.roll_no',
'       and     c.line_id = b.line_id',
'       AND b.ROL_ACPT_REJ = ''Accept''',
'       AND NOT EXISTS',
'                  (SELECT 1',
'                     FROM cutting_spreading_d d',
'                          JOIN cutting_spreading_L L2 ON d.L_ID = L2.L_ID',
'                          JOIN cutting_spreading_H H ON L2.H_ID = H.H_ID',
'                    WHERE     d.ROLL_ID = FS.ROLL_NO',
'                          AND H.TRACKING_NO = L.TRACKING_NO',
'                          AND H.COLOR = L.COLOR)',
'       AND l.tracking_no = :P50_TRACKING_NO',
'       AND l.color = :P50_COLOR',
'',
'UNION ALL',
'select ''Cut Pcs'',''0'',0,''-'',''-'',''-'',0,0,''End Cuts'' from dual',
')',
'ORDER BY ',
'    CASE ',
'        WHEN ROLL_TYPE = ''Used'' THEN 1',
'        WHEN ROLL_TYPE = ''Fresh'' THEN 2',
'    END,',
'    SUPP_ROLL_NO;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'ROLL_NO'
,p_display_column_name=>'ROLL_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
