prompt --application/shared_components/user_interface/lovs/fab_ins_2nd_d
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(145175350361206271)
,p_lov_name=>'FAB_INS_2ND_D'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'd.ROLL_NO,',
'd.ROLL_NO as rollno,',
'd.SUPP_ROLL_NO supp_roll_no,',
'l.RAW_COLOR color,',
'       l.TRACKING_NO TRACKING_NO,',
'       h.header_id,',
'       d.roll_weight,',
'       d.aloc_yard,',
'       d.aloc_inch,',
'       d.ALOC_METER aloc_mtr,',
'       d.cut_width,',
'       d.supplier_batch_no,',
'       d.supplier_pl_no,',
'       l.INVENTORY_ITEM_ID',
'  FROM PWC_MFG_FABRIC_INS_TEST_H h,',
'       PWC_MFG_FABINS_PROD_L l,',
'       PWC_MFG_FABRIC_INS_TEST_L d',
' WHERE     h.header_id = l.header_id',
'       AND l.PROD_L_ID = d.PROD_L_ID',
'       AND NOT EXISTS',
'                  (SELECT 1',
'                     FROM pwc_mfg_fabins_secnd_d pmfsd,',
'                          pwc_mfg_fabins_first_d pmffd,',
'                          pwc_mfg_fabins_prod_l mmfpl1',
'                    WHERE     pmfsd.roll_no = d.ROLL_NO',
'                          AND pmffd.line_id = pmfsd.line_id',
'                          AND pmffd.prod_l_id = mmfpl1.prod_l_id',
'                          AND mmfpl1.header_id = h.header_id)',
'       --AND h.HEADER_ID = :P23_V_HEADER_ID',
'       --AND INVENTORY_ITEM_ID = :P23_V_INV_ITEM_ID',
'       --AND l.COLOR = :P23_V_COLOR',
'       --AND 1 = :P23_V_ONE_VALUE',
'       --AND l.TRACKING_NO = :P23_TRACK'))
,p_source_type=>'SQL'
