prompt --application/shared_components/user_interface/lovs/fab_shrinkage_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(149180150910197430)
,p_lov_name=>'FAB_SHRINKAGE_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT header_id,       ',
'         color,       ',
'         roll_no,       ',
'         roll_no_new,       ',
'         roll_weight,       ',
'         ROUND (roll_length_yards, 3) roll_length,       ',
'         ROUND (roll_length_yards, 3) roll_length_y,       ',
'         ROUND(roll_length_yards * 0.9144) yard_to_meter,    ',
'         ROUND(roll_length_yards * 0.9144) yard_to_meter_Y,    ',
'         ROUND((roll_length_yards * 36),0) yard_to_inches,       ',
'         ROUND((roll_length_yards * 36),0) yard_to_inches_y,       ',
'         roll_width,       ',
'         roll_width AS roll_width_Y,       ',
'         0 roll_length2,       ',
'         roll_weight roll_mtr,       ',
'         NULL style,       ',
'         pwc_mfg_bss_master_func (tracking_no, ''BUYER_ID'') buyer_id,       ',
'         NULL bom_id,       ',
'         NULL inventory_item_id,       ',
'         tracking_no,       ',
'         supplier_batch_no,       ',
'         supplier_pl_no       ',
'    FROM (SELECT DISTINCT       ',
'                 i.header_id,       ',
'                 i.color,       ',
'                 d.roll_sr_no roll_no, ',
'                 /*d.supplier_serial_no || '' - '' || */d.roll_no roll_no_new,       ',
'                  case when d.UOM in (''Grams'', ''Kilograms'') then   ',
'                 NVL (       ',
'                    (SELECT SUM (moqd.primary_transaction_quantity)       ',
'                       FROM apps.mtl_onhand_quantities_detail@adf moqd,       ',
'                            APPS.mtl_item_locations@adf mtl       ',
'                      WHERE     moqd.lot_number = d.roll_sr_no       ',
'                            AND moqd.inventory_item_id = i.inventory_item_id       ',
'                            AND moqd.locator_id = mtl.inventory_location_id       ',
'                            AND mtl.organization_id = moqd.organization_id       ',
'                            AND mtl.subinventory_code = i.subinventory_code       ',
'                            AND mtl.disable_date IS NULL       ',
'                            AND mtl.segment5 = i.tracking_no),       ',
'                    0)    ',
'                    else   ',
'                    0   ',
'                    end   ',
'                    roll_weight,       ',
'                 d.roll_length_yards,       ',
'                 d.roll_width,       ',
'                 i.tracking_no,       ',
'                 d.supplier_batch_no,       ',
'                 d.supplier_pl_no,       ',
'                 TO_NUMBER (       ',
'                    NVL (REGEXP_REPLACE (i.fab_ounce, ''[^[:digit:]]'', ''''), 1))       ',
'                    fab_ounce,       ',
'                 d.roll_width item_fab_weight       ',
'            FROM pwc_inv_fabric_roll_l i,       ',
'                 pwc_inv_fabric_roll_d d,       ',
'                 pwc_inv_fabric_roll_h mmfih       ',
'           where     i.line_id = d.line_id       ',
'                 AND i.header_id = mmfih.header_id       ',
'                 AND d.accepted_flag = ''Y''       ',
'                 AND i.line_id = (select FABRICROL_LINEIDL from PWC_MFG_FABINS_PROD_L where PROD_L_ID=:P55_LINE_PK_VC)',
'                 AND i.color = (select RAW_COLOR from PWC_MFG_FABINS_PROD_L where PROD_L_ID=:P55_LINE_PK_VC)',
'                 --AND i.line_id = 3263',
'                 --AND i.color = :P_RAW_COLOR       ',
'                 --AND i.color = ''NONE''',
'                 and i.tracking_no = PWC_FABRIC_INSP_CONCAT_FUNC (:P55_HEADER_ID, ''TRACKING_NO'')       ',
'         ) aa       ',
'   WHERE NOT EXISTS       ',
'                (SELECT *       ',
'                   FROM pwc_mfg_fabric_ins_test_l mmfp1,       ',
'                        pwc_mfg_fabins_prod_l mmfpl1       ',
'                  WHERE     mmfp1.prod_l_id = mmfpl1.prod_l_id       ',
'                      --  AND mmfpl1.tracking_no = aa.tracking_no       ',
'                        --AND mmfp1.supp_roll_no = aa.roll_no_new       ',
'                        AND mmfp1.roll_no = aa.roll_no       ',
'                        AND mmfpl1.raw_color = aa.color)       ',
'ORDER BY roll_no;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'ROLL_NO_NEW'
,p_display_column_name=>'ROLL_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(149218775514613176)
,p_query_column_name=>'ROLL_NO_NEW'
