prompt --application/shared_components/user_interface/lovs/fri_h_po_no_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(131983050743841686)
,p_lov_name=>'FRI_H_PO_NO_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select       ',
'    distinct pha.SEGMENT1    ',
'from  APPS.po_headers_all@ADF pha,      ',
'      APPS.po_lines_all@ADF pla ,    ',
'      apps.mtl_system_items_kfv@ADF msi',
'where pha.PO_HEADER_ID = pla.PO_HEADER_ID      ',
'    and pla.item_id = msi.inventory_item_id',
'    and msi.organization_id = 91',
'    and pha.org_id = 85',
'    AND TRUNC(pha.creation_date) >= TO_DATE(''01-JAN-2025'',''DD-MON-YYYY'')',
'    AND MSI.segment1 in (300,301,302)',
'    and pha.AUTHORIZATION_STATUS = ''APPROVED''        ',
'    and not exists  (select distinct ''X'' from PWC_INV_FABRIC_ROLL_H where shipment_num = pha.segment1); '))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'SEGMENT1'
,p_display_column_name=>'SEGMENT1'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'SEGMENT1'
,p_default_sort_direction=>'ASC'
);
end;
/
