 p_id=>wwv_flow_imp.id(132741163526081674)
,p_lov_name=>'MASTER_TRACKING_NO_POC'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT bh.buyer_id,   ',
'       ac.customer_name,   ',
'       sl.style_name,   ',
'       sl.style_number,   ',
'       sd.season_name,  ',
'       sd.tracking_no,   ',
'       bd.brand_description, ',
'       sd.season_status tracking_status   ',
'  FROM pwc_mt_buyer_details_h bh,   ',
'       pwc_mt_style_details_l sl,   ',
'       pwc_mt_brand_details_d bd,   ',
'       pwc_mt_season_details_d sd,   ',
'       apps.ar_customers@adf ac   ',
' WHERE     ac.customer_id = bh.buyer_id   ',
'       AND bh.header_id = bd.header_id   ',
'       AND bd.brand_line_id = sl.brand_line_id   ',
'       AND sl.style_line_id = sd.style_line_id   ',
'       AND sd.season_status = ''Open''   ',
'       AND sd.division = ''Woven''   ',
'       AND sd.season_identifier IS NOT NULL   ',
'       AND sd.tracking_no IS NOT NULL  ',
'       AND bh.buyer_id = :p3_buyer_id ',
'       AND sd.tracking_no NOT IN (SELECT NVL (poc.tracking_no, ''N/A'')   ',
'                                    FROM pwc_ont_wvn_precosting_h poc)'))
