begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(120133775201725909)
,p_lov_name=>'MRF_CDT_POPULATE_COLOR_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT         ',
'       powpcl.style_colour colour,         ',
'       powpcl.inventory_item_id,                ',
'       PWC_BOOKING_CONSUMPTION_FUNC(powpcl.style_colour,     ',
'       mmph.tracking_no,      ',
'       line.FABRIC_ITEM_ID ) booking_consumption,         ',
'       (SELECT msib.description         ',
'        FROM apps.mtl_system_items_b@adf msib         ',
'        WHERE  msib.inventory_item_id = powpcl.inventory_item_id         ',
'               AND msib.organization_id = mmph.invoicing_unit_id) item_description,         ',
'       mmpl.child_style_no,         ',
'       mmpl.product_classification,         ',
'       line.fab_cons fabric_cons,         ',
'       line.fab_comp fabric_comp,         ',
'       fith.org_id fabric_comp_unit_id,  ',
'       line.FABRIC_ITEM_ID ,  ',
'       (SELECT msib.description         ',
'        FROM apps.mtl_system_items_b@adf msib         ',
'        WHERE  msib.inventory_item_id = line.FABRIC_ITEM_ID         ',
'               AND msib.organization_id = mmph.invoicing_unit_id)         ',
'       fab_item_description   ',
'  FROM pwc_ont_wvn_precosting_h mmph,         ',
'       pwc_ont_wvn_precosting_l mmpl,         ',
'       pwc_ont_wvn_precosting_color_l powpcl,         ',
'       pwc_mfg_fabric_ins_test_h fith,         ',
'       pwc_mfg_fabins_prod_l line         ',
' WHERE     mmph.header_id = mmpl.header_id         ',
'        AND mmph.tracking_no = :P19_TRACKING_NO   ',
'        and powpcl.style_colour = :P19_COLOR    ',
'       AND mmpl.line_id = powpcl.line_id         ',
'       AND powpcl.inventory_item_id IS NOT NULL         ',
'       AND mmpl.approval_flag = ''Y''         ',
'       AND line.header_id = fith.header_id         ',
'       AND line.tracking_no = mmph.tracking_no         ',
'       AND line.color = powpcl.style_colour      ',
'       and NOT exists (select ''X''       ',
'                               from PWC_MFG_RATIOPLAN_COLOR_L FETCHED       ',
'                               WHERE FETCHED.COLOR =  powpcl.style_colour      ',
'                               and   FETCHED.inventory_item_id =  line.inventory_item_id      ',
'                               )',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'COLOUR'
,p_display_column_name=>'COLOUR'
,p_group_sort_direction=>'ASC'
