begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(118599397221308802)
,p_lov_name=>'MRF_H_TRACKING_NO_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT bh.buyer_id,          ',
'       ac.customer_name Buyer_Name,          ',
'       sl.style_name,          ',
'       sl.style_number,          ',
'       sd.season_name,          ',
'       sd.tracking_no,          ',
'       nvl((select distinct ''Y''        ',
'            from        ',
'            PWC_MFG_OSP_DEP_ASSIGN ospd,       ',
'            pwc_mfg_osp_stn_line ospl,       ',
'            PWC_MFG_OSP_HEADER osph       ',
'            where 1=1        ',
'            and ospd.stn_line_id = ospl.stn_line_id       ',
'            and ospl.header_id = osph.header_id       ',
'            and osph.tracking_no = sd.tracking_no       ',
'            and ospd.FINAL_DEPARTMENT = ''Printing''       ',
'            and nvl(ospd.sub_unit, ''N'') = ''Y''), ''N'') printing,          ',
'       nvl((select distinct ''Y''        ',
'            from        ',
'            PWC_MFG_OSP_DEP_ASSIGN ospd,       ',
'            pwc_mfg_osp_stn_line ospl,       ',
'            PWC_MFG_OSP_HEADER osph       ',
'            where 1=1        ',
'            and ospd.stn_line_id = ospl.stn_line_id       ',
'            and ospl.header_id = osph.header_id       ',
'            and osph.tracking_no = sd.tracking_no       ',
'            and ospd.FINAL_DEPARTMENT = ''Embroidery''       ',
'            and nvl(ospd.sub_unit, ''N'') = ''Y''), ''N'') embroidery,          ',
'       mmph.fit,          ',
'       mmph.item_description,         ',
'       mmph.EXCESS_CUT_PERC ExtraCutPercent ,       ',
'       /*For OSP Scenario*/       ',
'       nvl((select distinct ''Y''        ',
'            from        ',
'            PWC_MFG_OSP_DEP_ASSIGN ospd,       ',
'            pwc_mfg_osp_stn_line ospl,       ',
'            PWC_MFG_OSP_HEADER osph       ',
'            where 1=1        ',
'            and ospd.stn_line_id = ospl.stn_line_id       ',
'            and ospl.header_id = osph.header_id       ',
'            and osph.tracking_no = sd.tracking_no       ',
'            and ospd.FINAL_DEPARTMENT = ''Cutting''       ',
'            and nvl(ospd.sub_unit, ''N'') = ''Y''), ''Y'') osp_auto_check     ',
'  FROM pwc_mt_buyer_details_h bh,          ',
'       pwc_mt_brand_details_d bd,          ',
'       pwc_mt_style_details_l sl,          ',
'       pwc_mt_season_details_d sd,          ',
'       pwc_ont_wvn_precosting_h mmph,          ',
'       apps.ar_customers@adf ac          ',
' WHERE     1 = 1          ',
'       AND bh.header_id = bd.header_id          ',
'       AND bd.brand_line_id = sl.brand_line_id          ',
'       AND sl.style_line_id = sd.style_line_id          ',
'       AND sd.season_identifier IS NOT NULL          ',
'       AND sd.tracking_no IS NOT NULL          ',
'       AND ac.customer_id = bh.buyer_id          ',
'       AND mmph.tracking_no = sd.tracking_no          ',
'       AND sd.season_status = ''Open''          ',
'       AND sd.season_identifier IS NOT NULL          ',
'       AND sd.tracking_no IS NOT NULL          ',
'       AND sd.tracking_no NOT IN (SELECT mr.tracking_no          ',
'                                   FROM pwc_mfg_ratioplan mr ',
'                                   where 1=2)',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'TRACKING_NO'
,p_display_column_name=>'TRACKING_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'TRACKING_NO'
,p_default_sort_direction=>'ASC'
);
