prompt --application/shared_components/user_interface/lovs/mrf_ibpost_bpo_line_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(122772311468180978)
,p_lov_name=>'MRF_IBPOST_BPO_LINE_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (',
'SELECT XXT.BPO_NO,',
'CASE WHEN XXT.OSP_CHECK=''N'' THEN SUM(XXT.ORDERED_QTY)',
'ELSE (SELECT NVL(SUM(OSPS.GARMENT_QTY),0)',
'      FROM PWC_MFG_OSP_HEADER OSPH,PWC_MFG_OSP_STN_LINE OSPL,PWC_MFG_OSP_STN_LINE_SIZES OSPS',
'      WHERE OSPL.STN_LINE_ID=OSPS.STN_LINE_ID',
'      AND OSPL.BPO=XXT.BPO_NO',
'      AND OSPL.STN=XXT.STN',
'      AND OSPS.GARMENT_INSEAM=XXT.INSEAM',
'      AND OSPL.COLOR=XXT.COLOR',
'      AND OSPH.HEADER_ID=OSPL.HEADER_ID',
'      AND OSPH.TRACKING_NO=XXT.TRACKING_NO)',
'END ORDERED_QTY,',
'(SELECT NVL(SUM(OSPS.GARMENT_SIZE_QTY),0)',
'FROM PWC_MFG_OSP_HEADER OSPH,PWC_MFG_OSP_STN_LINE OSPL,PWC_MFG_OSP_STN_LINE_SIZES OSPS',
'WHERE OSPL.STN_LINE_ID=OSPS.STN_LINE_ID',
'AND OSPL.BPO=XXT.BPO_NO',
'AND OSPL.STN=XXT.STN',
'AND OSPS.GARMENT_INSEAM=XXT.INSEAM',
'AND OSPL.COLOR=XXT.COLOR',
'AND OSPH.HEADER_ID=OSPL.HEADER_ID',
'AND OSPH.TRACKING_NO=XXT.TRACKING_NO) EXTRA_ORDERED_QTY,',
'XXT.STN,XXT.ORDERED_ITEM,XXT.DESCRIPTION,XXT.INVENTORY_ITEM_ID,XXT.COLOR,',
'XXT.FINAL_MFG_ORG_ID,XXT.ORG_ID,XXT.TRACKING_NO,XXT.COUNTRY,XXT.INSEAM,',
'XXT.REPLACE_BPO,XXT.BPO_OSP_UNIT_ID,',
'(SELECT H.NAME FROM apps.HR_OPERATING_UNITS@adf H WHERE H.ORGANIZATION_ID=XXT.BPO_OSP_UNIT_ID) BPO_OSP_UNIT_NAME,',
'NULL PATTERN_COUNTRY,XXT.CHILD_STYLE_NO,XXT.PRODUCT_CLASSIFICATION,XXT.OSP_CHECK',
'FROM (',
'SELECT OOHA.CUST_PO_NUMBER BPO_NO,SIZDETAIL.GARMENT_QTY ORDERED_QTY,',
'OOHA.CUST_PO_NUMBER||''/''||OOLA.LINE_NUMBER STN,OOLA.ORDERED_ITEM,MSIB.DESCRIPTION,',
'MMOSL.BPO_OSP_UNIT_ID,OOLA.INVENTORY_ITEM_ID,MMOSL.COLOR,MMODA.FINAL_MFG_ORG_ID,',
'OOHA.ORG_ID,MMOH.TRACKING_NO,SIZLINE.COUNTRY,SIZDETAIL.GARMENT_INSEAM INSEAM,',
'OOHA.ATTRIBUTE12 REPLACE_BPO,CL.CHILD_STYLE_NO,CL.PRODUCT_CLASSIFICATION,',
'NVL(MMR.OSP_CHECK,''N'') OSP_CHECK',
'FROM PWC_MFG_OSP_DEP_ASSIGN MMODA,PWC_MFG_OSP_STN_LINE MMOSL,PWC_MFG_OSP_HEADER MMOH,',
'apps.OE_ORDER_HEADERS_ALL@adf OOHA,apps.OE_ORDER_LINES_ALL@adf OOLA,apps.MTL_SYSTEM_ITEMS_B@adf MSIB,',
'PWC_ONT_WVN_PRECOSTING_H H,PWC_ONT_WVN_SIZEWISE_DETAILS_H SIZLINE,',
'PWC_ONT_WVN_SIZEWISE_DETAILS_L SIZDETAIL,PWC_MFG_RATIOPLAN MMR,',
'PWC_MFG_RATIOPLAN_COLOR_L CL',
'WHERE MMODA.STN_LINE_ID=MMOSL.STN_LINE_ID',
'AND MMOSL.HEADER_ID=MMOH.HEADER_ID',
'AND OOHA.HEADER_ID=OOLA.HEADER_ID',
'AND OOHA.SHIP_FROM_ORG_ID=MMOH.ORGANIZATION_ID',
'AND SIZLINE.HEADER_ID=SIZDETAIL.HEADER_ID',
'AND SIZLINE.INVENTORY_ITEM_ID=OOLA.ORDERED_ITEM_ID',
'AND SIZLINE.SALES_ORDER_ID=OOHA.HEADER_ID',
'AND SIZLINE.SALES_ORDER_LINE_ID=OOLA.LINE_ID',
'AND MMOSL.STN=OOHA.CUST_PO_NUMBER||''/''||OOLA.LINE_NUMBER',
'AND MSIB.INVENTORY_ITEM_ID=OOLA.INVENTORY_ITEM_ID',
'AND MSIB.ORGANIZATION_ID=PWC_ORGANIZATION_NAME(''Inventory Master Org'')',
'AND MMOSL.COLOR=REGEXP_SUBSTR(MSIB.DESCRIPTION,''[^:]+'',1,3)',
'AND MMODA.FINAL_DEPARTMENT=''Cutting''',
'AND MMOH.TRACKING_NO=OOHA.ATTRIBUTE4',
'AND MMR.RATIOPLAN_ID=CL.RATIOPLAN_ID',
'AND OOHA.ATTRIBUTE4=MMR.TRACKING_NO',
'AND CL.INVENTORY_ITEM_ID=OOLA.INVENTORY_ITEM_ID',
'AND NVL(OOLA.ATTRIBUTE4,''N/A'')=NVL(CL.CHILD_STYLE_NO,''N/A'')',
'AND MMOSL.COLOR=CL.COLOR',
'AND MMOH.TRACKING_NO=H.TRACKING_NO',
'AND MMODA.FINAL_MFG_ORG_ID IS NOT NULL',
'AND MMODA.SUPPLIER_ID IS NULL',
'AND NOT EXISTS (',
'  SELECT 1',
'  FROM PWC_MFG_RATIOPLAN_STNS_ALL STNLINE,PWC_MFG_RATIOPLAN MMR',
'  WHERE STNLINE.COUNTRY=SIZLINE.COUNTRY',
'  AND MMR.RATIOPLAN_ID=STNLINE.RATIOPLAN_ID',
'  AND STNLINE.INSEAM=SIZDETAIL.GARMENT_INSEAM',
'  AND NVL(STNLINE.CHILD_STYLE_NO,''N/A'')=NVL(CL.CHILD_STYLE_NO,''N/A'')',
'  AND STNLINE.PRODUCT_CLASSIFICATION=CL.PRODUCT_CLASSIFICATION',
'  AND STNLINE.COLOR=CL.COLOR',
'  AND MMR.TRACKING_NO=MMOH.TRACKING_NO',
'  AND STNLINE.STN_NO=OOHA.CUST_PO_NUMBER||''/''||OOLA.LINE_NUMBER',
'  AND STNLINE.BPO_NO=OOHA.CUST_PO_NUMBER)',
') XXT',
'GROUP BY XXT.BPO_NO,XXT.STN,XXT.ORDERED_ITEM,XXT.DESCRIPTION,XXT.INVENTORY_ITEM_ID,',
'XXT.COLOR,XXT.FINAL_MFG_ORG_ID,XXT.ORG_ID,XXT.TRACKING_NO,XXT.COUNTRY,',
'XXT.INSEAM,XXT.REPLACE_BPO,XXT.BPO_OSP_UNIT_ID,XXT.CHILD_STYLE_NO,',
'XXT.PRODUCT_CLASSIFICATION,XXT.OSP_CHECK',
')',
'WHERE TRACKING_NO = :P19_TRACKING_NO AND COLOR = :P19_COLOR;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'BPO_NO'
,p_display_column_name=>'BPO_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'BPO_NO'
,p_default_sort_direction=>'ASC'
);
