prompt --application/shared_components/user_interface/lovs/non_inventoryitem_id
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(132541713111276943)
,p_lov_name=>'NON_INVENTORYITEM_ID'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT POCD.QUOTED_CONS_PER_PCS CONSUMPTION,',
'       CASE',
'          WHEN POCD.ITEM_STATUS = ''Import'' THEN POCD.UNIT_PRICE_FC',
'          ELSE POCD.QUOTED_UNIT_PRICE',
'       END',
'          ACTUAL_UNIT_PRICE,',
'       POCL.CHILD_STYLE_NO,',
'       POCL.PRODUCT_CLASSIFICATION,',
'       POCD.ITEM_DESC,',
'       ''Y'' PRECOSTING_ITEM_FLAG,',
'       POCD.ITEM_UOM,',
'       POCD.PRICING_UOM,',
'       POCD.UOM_CONV_RATE,',
'       CASE',
'          WHEN :P7_ITEMTYPE = ''Thread'' AND POCD.ITEM_UOM = ''Cone''',
'          THEN',
'               POCD.BUDGETED_UNIT_PRICE  * (  POCD.BUDGETED_CONS_PER_PCS / DECODE (NVL (POCD.UOM_CONV_RATE, 1),0, 1,POCD.UOM_CONV_RATE))',
'          ELSE',
'               POCD.BUDGETED_UNIT_PRICE * (  POCD.BUDGETED_CONS_PER_PCS * DECODE (NVL (POCD.UOM_CONV_RATE, 1), 0, 1,POCD.UOM_CONV_RATE))',
'       END',
'          COST_PER_PIECE,',
'       POCL.SUBCOSTING_NO,',
'       POCL.SUBCOSTING_VERSION_NO,',
'       POCD.ITEM_SUPP_NAME,',
'       POCD.QUOTED_WASTAGE_IN_PER BUDGETED_WASTAGE_IN_PER',
'  FROM PWC_ONT_WVN_PRECOSTING_H POCH,',
'       PWC_ONT_WVN_PRECOSTING_L POCL,',
'       PWC_ONT_WVN_PRECOSTING_D POCD',
' WHERE     POCH.HEADER_ID = POCL.HEADER_ID',
'       AND POCL.LINE_ID = POCD.LINE_ID',
'    --    AND POCL.APPROVAL_FLAG = ''Y''',
'       AND POCH.TRACKING_NO = :P7_TRACKING_NO',
'       AND ((:P7_ITEMTYPE = ''Fabric'' AND ITEM_PREFIX IN (300, 301, 302)) OR (:P7_ITEMTYPE = ''Zipper/Button/Rivet'' AND ITEM_PREFIX = 450) OR (:P7_ITEMTYPE = ''Thread'' AND ITEM_PREFIX = 451))',
'',
'',
'UNION ALL',
'',
'',
'',
'SELECT POCSD.COMMON_BUDG_CONS_PER_PCS,',
'       POCSD.COMMON_BUDG_UNIT_PRICE,',
'       POCL.CHILD_STYLE_NO,',
'       POCL.PRODUCT_CLASSIFICATION,',
'       POCSD.COMMON_ITEM_DESC,',
'       ''Y'' PRECOSTING_ITEM_FLAG,',
'       POCSD.COMMON_ITEM_UOM,',
'       POCSD.COMMON_PRICING_UOM,',
'       POCSD.COMMON_UOM_CONV_RATE,',
'       CASE',
'          WHEN     POCSD.COMMON_PREFIX_SECURITY = ''52'' AND POCSD.COMMON_ITEM_UOM = ''Cone''',
'          THEN',
'               POCSD.COMMON_BUDG_UNIT_PRICE * (  POCSD.COMMON_BUDG_CONS_PER_PCS / DECODE (NVL (POCSD.COMMON_UOM_CONV_RATE, 1), 0, 1, POCSD.COMMON_UOM_CONV_RATE))',
'          ELSE',
'               POCSD.COMMON_BUDG_UNIT_PRICE * (  POCSD.COMMON_BUDG_CONS_PER_PCS * DECODE (NVL (POCSD.COMMON_UOM_CONV_RATE, 1),0, 1,POCSD.COMMON_UOM_CONV_RATE))',
'       END',
'          COST_PER_PIECE,',
'       POCL.SUBCOSTING_NO,',
'       POCL.SUBCOSTING_VERSION_NO,',
'       POCD.ITEM_SUPP_NAME,',
'       POCD.QUOTED_WASTAGE_IN_PER',
'  FROM PWC_ONT_WVN_PRECOSTING_H POCH,',
'       PWC_ONT_WVN_PRECOSTING_L POCL,',
'       PWC_ONT_WVN_PRECST_SETCOST_L PSL,',
'       PWC_ONT_WVN_PRECST_SETCOST_D PSD,',
'       PWC_ONT_WVN_PRECST_SETCST_COMM POCSD,',
'       PWC_ONT_WVN_PRECOSTING_D POCD',
' WHERE     POCH.HEADER_ID = POCL.HEADER_ID',
'       AND POCH.HEADER_ID = PSL.HEADER_ID',
'       AND PSL.LINE_ID = PSD.LINE_ID',
'       AND POCL.SUBCOSTING_NO = PSD.SETCOSTING_SUBCOSTING_NO',
'       AND PSL.LINE_ID = POCSD.LINE_ID',
'       AND PSL.LINE_ID = POCD.LINE_ID',
'    --    AND POCL.APPROVAL_FLAG = ''Y''',
'       AND PSL.SET_APPROVAL_FLAG = ''Y''',
'       AND POCSD.COMMON_INVENTORY_ITEM_ID IS NULL',
'       AND POCH.TRACKING_NO = :P7_TRACKING_NO',
'       AND POCSD.COMMON_PREFIX_SECURITY =',
'       DECODE (:P7_ITEMTYPE,''Fabric'', 51,''Thread'', 52,''Zipper/Button/Rivet'', 53,''Carton/Poly'', 54,''Others'', 55,''Yarn'', 56)',
'UNION ALL',
'SELECT 0,0,NULL,''N/A'',''None'',''Y'',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL FROM DUAL;',
'',
'',
'',
'',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'ITEM_DESC'
,p_display_column_name=>'ITEM_DESC'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(132542457017301704)
,p_query_column_name=>'CONSUMPTION'
,p_heading=>'CONSUMPTION'
,p_display_sequence=>10
,p_data_type=>'NUMBER'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(132542733763301706)
