',description,inventory_item_id,style_no,final_replaced_bpo ',
'FROM ( SELECT aaa.oc_no bpo_line_no, aaa.bpo_no final_replaced_bpo, bb.country, bb.dcpo_no,aaa.attribute4 child_style_no,',
'aaa.color, aaa.wash_name, aaa.description, aaa.inventory_item_id, pwc_master_tracking_data_func (aaa.tracking_no, ''STYLE_NO'')STYLE_NO ',
'FROM (SELECT oh.header_id,oh.cust_po_number || ''/'' || ol.line_number oc_no, mmph.item_description,',
'NVL (TRIM (oh.attribute12), oh.cust_po_number) bpo_no, ol.inventory_item_id, ol.attribute4, REGEXP_SUBSTR (description,''[^::]+'',1,3)color, ',
'TRIM (REGEXP_SUBSTR (description, ''[^::]+'', 1, 2)) wash_name, msi.description, mmph.tracking_no FROM apps.oe_order_headers_all@adf oh, ',
'apps.oe_order_lines_all@adf ol, apps.mtl_system_items@adf msi, apps.org_organization_definitions@adf ood, pwc_ont_wvn_precosting_h mmph ',
'WHERE     ol.inventory_item_id = msi.inventory_item_id AND oh.header_id = ol.header_id AND ood.organization_id = msi.organization_id AND ',
'ood.operating_unit = oh.org_id AND ood.organization_name <> ''Inventory Master Org'' ',
'--AND mmph.header_id(+) = oh.attribute5 ',
'AND mmph.header_id(+) = oh.attribute20 AND mmph.tracking_no = oh.attribute4 AND mmph.tracking_no IN ',
'(SELECT bpop.tracking_no FROM pwc_exp_packing_list_h bpop WHERE bpop.packing_list_id = :P71_PACKING_LIST_ID)) aaa, ',
'pwc_exp_packing_list_item_desc bb WHERE     aaa.header_id = bb.sales_order_id AND aaa.oc_no = bb.bpo_line_no ',
'AND aaa.inventory_item_id = bb.inventory_item_id AND bb.packing_list_id = :P71_PACKING_LIST_ID) bb ',
'UNION ',
'SELECT DISTINCT bpo_line_no,country,:P71_PACKING_LIST_ID param_val,dcpo_no, color,wash_name,child_style_no,description,',
'inventory_item_id,style_no,final_replaced_bpo FROM (SELECT aaa.oc_no bpo_line_no, aaa.bpo_no final_replaced_bpo, bb.country, bb.dcpo_no, ',
'aaa.attribute4 child_style_no, aaa.color, aaa.wash_name, aaa.description, aaa.inventory_item_id, ',
'pwc_master_tracking_data_func (aaa.tracking_no, ''STYLE_NO'') STYLE_NO ',
'FROM (SELECT oh.header_id, oh.cust_po_number || ''/'' || ol.line_number oc_no, mmph.item_description, ',
'NVL (TRIM (oh.attribute12), oh.cust_po_number) bpo_no, ol.inventory_item_id, ol.attribute4, ',
'REGEXP_SUBSTR (description, ''[^::]+'', 1, 3) color, TRIM (REGEXP_SUBSTR (description, ''[^::]+'', 1, 2)) wash_name, ',
'msi.description, mmph.tracking_no FROM apps.oe_order_headers_all@adf oh, apps.oe_order_lines_all@adf ol, apps.mtl_system_items@adf msi, ',
'apps.org_organization_definitions@adf ood, pwc_ont_swt_precosting_h mmph WHERE     ol.inventory_item_id = msi.inventory_item_id ',
'AND oh.header_id = ol.header_id AND ood.organization_id = msi.organization_id AND ood.operating_unit = oh.org_id ',
'AND ood.organization_name <> ''Inventory Master Org'' ',
'--AND mmph.header_id(+) = oh.attribute5 ',
'AND mmph.header_id(+) = oh.attribute20 AND mmph.tracking_no = oh.attribute4 AND mmph.tracking_no IN ',
'(SELECT bpop.tracking_no FROM pwc_exp_packing_list_h bpop WHERE bpop.packing_list_id = :P71_PACKING_LIST_ID)) aaa, ',
'pwc_exp_packing_list_item_desc bb WHERE     aaa.header_id = bb.sales_order_id AND aaa.oc_no = bb.bpo_line_no ',
'AND aaa.inventory_item_id = bb.inventory_item_id AND bb.packing_list_id = :P71_PACKING_LIST_ID) bb'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'BPO_LINE_NO'
,p_display_column_name=>'BPO_LINE_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'BPO_LINE_NO'
,p_default_sort_direction=>'ASC'
);
