prompt --application/shared_components/user_interface/lovs/packing_list_d_inseam_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(153608178708254477)
,p_lov_name=>'PACKING_LIST_D_INSEAM_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select packing_list_inseam,        ',
'       packing_list_size,        ',
'       packing_list_size_qty,     ',
'       --least((pack_prod - already_packed)  , (packing_list_size_qty - current_bpo_dispatch) ) pack_prod    ',
'       least((packing_list_size_qty - current_bpo_dispatch) ) pack_prod ',
'          ',
'from (    ',
'SELECT packing_list_inseam,        ',
'       packing_list_size,        ',
'       packing_list_size_qty,     ',
'       (select nvl(sum(TOTAL_PROD), 0)      ',
'            from pwc_mfg_packing_prod_l pl,     ',
'                 pwc_mfg_packing_prod_d pd     ',
'            where 1=1      ',
'            and pl.line_id = pd.line_id     ',
'            and p_stn_no like ''%''|| plid.bpo_line_no||''%''     ',
'            and p_inventory_item_id  = plid.inventory_item_id     ',
'            and P_COLOR = plid.garment_color     ',
'            and SIZE_VALUE = pls.packing_list_size) pack_prod,   ',
'            (SELECT nvl(SUM (ll.pack_qty),0)   ',
'                  FROM pwc_exp_packing_list_h hh, pwc_exp_packing_list_detail ll   ',
'                 WHERE     hh.packing_list_id = ll.packing_list_id   ',
'                       AND hh.tracking_no = ph.tracking_no--''TOP001-2211-0015''   ',
'                       and ll.size_no = packing_list_size   ',
'                       and ll.bpo_line_no = :P71_TMP_BPO_LINE_NO',
'                       AND (ll.bpo_line_no, ll.inseam, ll.size_no) IN   ',
'                              (SELECT mmrl.stn_no, mmrl.inseam, mmrls.size_val   ',
'                                 FROM pwc_mfg_ratioplan mmr,   ',
'                                      pwc_mfg_ratioplan_stns_all mmrl,   ',
'                                      pwc_mfg_ratioplan_stns_sizes mmrls,   ',
'                                      pwc_mfg_ratioplan_merge_stns mstn   ',
'                                WHERE     1 = 1   ',
'                                      AND mmr.ratioplan_id = mmrl.ratioplan_id   ',
'                                      AND mmr.tracking_no = ph.tracking_no--''TOP001-2211-0015''  ',
'                                      and mmrl.stn_no = :P71_TMP_BPO_LINE_NO  ',
'                                      AND mmrl.ratioplan_id = mstn.header_id   ',
'                                      AND mmrl.color = mstn.color   ',
'                                      AND mmrl.inseam = mstn.inseam   ',
'                                      AND mmrl.detail_id = mmrls.detail_id))  already_packed,    ',
'           (SELECT nvl(SUM (ll.pack_qty),0)   ',
'                  FROM pwc_exp_packing_list_h hh, pwc_exp_packing_list_detail ll   ',
'                 WHERE     hh.packing_list_id = ll.packing_list_id   ',
'                       AND hh.tracking_no = Ph.tracking_no--''TOP001-2211-0015''   ',
'                       and ll.bpo_line_no = plid.bpo_line_no   ',
'                       AND LL.SIZE_NO = packing_list_size   ',
'                       and ll.inseam = packing_list_inseam   ',
'                       and ll.COLOR_DETAIL = :P71_TMP_COLOR_DETAIL  ',
'                       )current_bpo_dispatch   ',
'  FROM pwc_exp_packing_list_h ph,   ',
'       pwc_exp_packing_list_sizes pls,        ',
'       pwc_exp_packing_list_item_desc plid        ',
' WHERE ph.packing_list_id = plid.packing_list_id       ',
'       and pls.item_desc_id_pk = plid.item_desc_id_pk        ',
'       AND plid.inventory_item_id = :P71_TMP_INVENTORY_ITEM_ID        ',
'       AND plid.bpo_line_no = :P71_TMP_BPO_LINE_NO       ',
'       AND plid.country = :P71_COUNTRY_NAME        ',
'       AND plid.dcpo_no = :P71_TMP_DCPO       ',
'       AND plid.packing_list_id = :P71_PACKING_LIST_ID)'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'PACKING_LIST_SIZE'
,p_display_column_name=>'PACKING_LIST_SIZE'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'PACKING_LIST_INSEAM'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(153608567831256662)
,p_query_column_name=>'PACKING_LIST_INSEAM'
,p_heading=>'Inseam'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
