prompt --application/shared_components/user_interface/lovs/poc_buyer_id
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(222680367868910440)
,p_lov_name=>'POC_BUYER_ID'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT  ',
'       ac.customer_name buyer_name,     ',
'       ac.customer_id buyer_id ',
'  FROM apex_adf.pwc_mt_buyer_details_h bh,     ',
'       apex_adf.pwc_mt_enduser_details_d ed,     ',
'       apex_adf.pwc_mt_merchandizer_details_d md,     ',
'       apps.ar_customers@adf ac,     ',
'       apps.fnd_user@adf fu,    ',
'       apps.qa_results@adf qrv    ',
' WHERE     bh.header_id = ed.header_id     ',
'       AND ed.enduser_detail_id = md.enduser_detail_id     ',
'       AND md.app_user_name  = fu.user_name     ',
'       AND bh.buyer_id = ac.customer_id     ',
'       AND qrv.character2 = ac.customer_id    ',
'--       AND qrv.name = ''PWC_OM_RETAILER_AGENT''',
'       and qrv.plan_id = 61131    ',
'       AND md.active_merch = ''Y''     ',
'       AND ed.active_enduser = ''Y''     ',
'       --AND fu.user_id = :app_user     ',
'UNION     ',
'SELECT DISTINCT  ',
'       ac.customer_name buyer_name,     ',
'       ac.customer_id buyer_id     ',
'  FROM apex_adf.pwc_mt_buyer_details_h bh,     ',
'       apex_adf.pwc_mt_enduser_details_d ed,      ',
'       apex_adf.pwc_mt_buyr_cordinat_details_d cd,     ',
'       apps.ar_customers@adf ac,     ',
'       apps.fnd_user@adf fu,    ',
'       apps.qa_results@adf qrv    ',
' WHERE     bh.header_id = ed.header_id     ',
'       AND ed.enduser_detail_id = cd.enduser_detail_id     ',
'       AND cd.app_user_name  = fu.user_name    ',
'       AND bh.buyer_id = ac.customer_id     ',
'       AND qrv.character2 = ac.customer_id    ',
'--       AND qrv.name = ''PWC_OM_RETAILER_AGENT''',
'       and qrv.plan_id = 61131    ',
'       AND ed.active_enduser = ''Y''     ',
'       AND cd.active_coordinator = ''Y''     ',
'      -- AND fu.user_id = :app_user',
'',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'BUYER_ID'
,p_display_column_name=>'BUYER_NAME'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'BUYER_NAME'
,p_default_sort_direction=>'ASC'
);
end;
