prompt --application/shared_components/user_interface/lovs/poc_tracking_no
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(222591308624056132)
,p_lov_name=>'POC_TRACKING_NO'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT bh.buyer_id,   ',
'       ac.customer_name,   ',
'       sl.style_name,   ',
'       sl.style_number,   ',
'       sd.season_name,  ',
'       sd.tracking_no,   ',
'       bd.brand_description, ',
'       sd.season_status tracking_status   ',
'  FROM pwc_mt_buyer_details_h bh,   ',
'       pwc_mt_style_details_l sl,   ',
'       pwc_mt_brand_details_d bd,   ',
'       pwc_mt_season_details_d sd,   ',
'       apps.ar_customers@adf ac   ',
' WHERE     ac.customer_id = bh.buyer_id   ',
'       AND bh.header_id = bd.header_id   ',
'       AND bd.brand_line_id = sl.brand_line_id   ',
'       AND sl.style_line_id = sd.style_line_id   ',
'       AND sd.season_status = ''Open''   ',
'       AND sd.division = ''Woven''   ',
'       AND sd.season_identifier IS NOT NULL   ',
'       AND sd.tracking_no IS NOT NULL   ',
'       AND bh.buyer_id = :P3_BUYER_ID_1   ',
'       AND sd.tracking_no NOT IN (SELECT NVL (poc.tracking_no, ''N/A'')   ',
'                                    FROM pwc_ont_wvn_precosting_h@adf poc)',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'BUYER_ID'
,p_display_column_name=>'CUSTOMER_NAME'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'CUSTOMER_NAME'
,p_default_sort_direction=>'ASC'
);
end;
