prompt --application/shared_components/user_interface/lovs/recipe_wash_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(153606820397238195)
,p_lov_name=>'RECIPE_WASH_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT REGEXP_SUBSTR (MSIB.DESCRIPTION, ',
'                               ''[^:]+'', ',
'                               1, ',
'                               2) ',
'                   WASH ',
'  FROM APPS.OE_ORDER_HEADERS_ALL@ADF OOHA, ',
'       APPS.OE_ORDER_LINES_ALL@ADF OOLA, ',
'       APPS.MTL_SYSTEM_ITEMS@ADF MSIB ',
' WHERE     OOHA.HEADER_ID = OOLA.HEADER_ID ',
'       AND MSIB.INVENTORY_ITEM_ID = OOLA.ORDERED_ITEM_ID ',
'       AND MSIB.ORGANIZATION_ID = ',
'              PWC_ORGANIZATION_NAME (''Inventory Master Org'') ',
'       AND ''Bulk'' = :P65_RECIPE_STAGE ',
'       AND OOHA.ATTRIBUTE4 = :P65_TRACKING_NO ',
'UNION ',
'SELECT DISTINCT SAMP_L.WASH_NAME ',
'  FROM PWC_ONT_WVN_SAMPLE_STATUS SAMP_H, PWC_ONT_WVN_SAMPLE_STATUS_L SAMP_L ',
' WHERE     1 = 1 ',
'       AND SAMP_L.HEADER_ID = SAMP_H.HEADER_ID ',
'       AND ''Sample'' = :P65_RECIPE_STAGE ',
'       AND :P65_SAMPLE_CODE = SAMP_L.SAMPLE_LINE_CODE ',
'ORDER BY 1'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'WASH'
,p_display_column_name=>'WASH'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(153607284953240030)
,p_query_column_name=>'WASH'
,p_heading=>'Wash'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
end;
