prompt --application/shared_components/user_interface/lovs/recipt_chalan_delv_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(164248542186800568)
,p_lov_name=>'RECIPT_CHALAN_DELV_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT      ',
'         h.receive_no challan_no, lh.tracking_no,      ',
'         pwc_master_tracking_data_func (lh.tracking_no, ''BUYER_NAME'') buyer,      ',
'         pwc_master_tracking_data_func (lh.tracking_no, ''STYLE_NAME'') style_name,      ',
'         pwc_master_tracking_data_func (lh.tracking_no, ''SEASON_NAME'') season,      ',
'       NULL organic_auth,      ',
'         (SELECT DISTINCT haou.name      ',
'            FROM apps.hr_all_organization_units@adf haou      ',
'           WHERE haou.organization_id = h.org_id)      ',
'            unit,      ',
'         l.issuance_date,      ',
'         h.org_id,      ',
'         h.washing_process,      ',
'         NULL current_style,      ',
'         NULL current_season      ',
'             FROM pwc_mfg_issue_rec_wash_h h,      ',
'         pwc_mfg_issue_rec_wash_l_h lh,      ',
'         pwc_mfg_issue_rec_wash_l l,      ',
'         (  SELECT frv.responsibility_id, ood.organization_id      ',
'              FROM apps.fnd_profile_options_vl@adf fpo,      ',
'                   apps.fnd_responsibility_vl@adf frv,      ',
'                   apps.fnd_profile_option_values@adf fpov,      ',
'                   apps.hr_organization_units@adf hou,      ',
'                   apps.org_organization_definitions@adf ood      ',
'             WHERE     fpov.profile_option_value = TO_CHAR (hou.organization_id)      ',
'                   AND fpo.profile_option_id = fpov.profile_option_id      ',
'                   AND fpo.user_profile_option_name = ''MO: Operating Unit''      ',
'                   AND frv.responsibility_id = fpov.level_value      ',
'                   AND ood.operating_unit = hou.organization_id      ',
'          ORDER BY frv.responsibility_name) a      ',
'       WHERE h.header_id = lh.header_id      ',
'         AND l.header_id = lh.line_id      ',
'         AND l.issuance_challan_no IS NOT NULL      ',
'         AND a.organization_id = h.wash_emb_print_inv      ',
'--      AND a.responsibility_id = nvl(:P_RESP_ID,a.responsibility_id)       ',
'--        AND NOT EXISTS      ',
'--                    (SELECT *      ',
'--                       FROM pwc_mfg_issue_rec_wash_h mh      ',
'--                      WHERE     h.receive_no = mh.receipt_challan_no      ',
'--                            AND lh.tracking_no = mh.tracking_no      ',
'--                            AND mh.receipt_challan_no IS NOT NULL)      ',
'--         AND (SELECT operating_unit      ',
'--                FROM apps.org_organization_definitions@adf      ',
'--               WHERE organization_id = h.wash_emb_print_inv) = :P_Org     ',
'--                AND h.update_on <= trunc(TO_DATE (SUBSTR(:P_Date, 1, 19), ''YYYY-MM-DD'' )) --TO_DATE (:P_Date, ''MM/DD/YYYY'')      ',
'        -- AND TO_CHAR(TO_DATE(h.update_on ,''MM/DD/YYYY''), ''YYYY-MM-DD'') <= TO_CHAR(TO_DATE(:P_Date ,''YYYY-MM-DD''),''YYYY-MM-DD'')--TO_DATE (:P_Date, ''MM/DD/YYYY'')      ',
'         AND h.transaction_type = ''After Stitch Issue to Wash''      ',
'         and h.receive_no=''2025/1''',
'ORDER BY TO_NUMBER (SUBSTR (h.receive_no, INSTR (h.receive_no, ''/'', -1) + 1)) ASC;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'CHALLAN_NO'
,p_display_column_name=>'CHALLAN_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(164263989893858783)
,p_query_column_name=>'CHALLAN_NO'
,p_heading=>'Challan No'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
