prompt --application/shared_components/user_interface/lovs/ss_sbom_fill_item_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(137386376437948969)
,p_lov_name=>'SS_SBOM_FILL_ITEM_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       msib.inventory_item_id,',
'       msib.concatenated_segments item_code,',
'       msib.description,',
'       (SELECT MAX (vl.attribute17)',
'          FROM apps.fnd_flex_values_vl@adf vl',
'         WHERE     vl.flex_value_set_id = 1014168',
'               AND vl.flex_value = msib.segment2',
'               AND vl.PARENT_FLEX_VALUE_LOW = msib.segment1)',
'          hanger_number,',
'       NULL M2_JOB,',
'       msib.primary_uom_code,',
'       msib.attribute3 supplier_code,',
'       (SELECT description',
'          FROM pwc_flex_values_v',
'         WHERE     flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_COLOR/SHADE''',
'               AND flex_value = msib.segment4)',
'          color,',
'       (SELECT description',
'          FROM pwc_flex_values_v',
'         WHERE     flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_STATUS''',
'               AND flex_value NOT IN (''41'', ''61'', ''71'', ''51'')',
'               AND flex_value = msib.segment3)',
'          status,',
'       fvv.description item_prefix_desc,',
'       msib.buyer_id sourcing_person_id,',
'       (SELECT ppx.full_name',
'          FROM apps.per_people_x@adf ppx',
'         WHERE ppx.person_id = msib.buyer_id)',
'          sourcing_person_name,',
'       msib.segment3 item_status',
'  FROM apps.mtl_system_items_kfv@adf msib,',
'       pwc_flex_values_v fvv,',
'       apps.mtl_item_categories@adf mic',
' WHERE     msib.organization_id = ''91''',
'       AND msib.segment1 = fvv.flex_value',
'       AND mic.inventory_item_id = msib.inventory_item_id',
'       AND mic.organization_id = msib.organization_id',
'       AND msib.inventory_item_status_code = ''Active''',
'       AND fvv.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''',
'       AND fvv.flex_value IN',
'              (''450'',',
'               ''451'',',
'               ''820'',',
'               ''452'',',
'               ''453'',',
'               ''454'',',
'               ''455'',',
'               ''456'',',
'               ''457'',',
'               ''458'',',
'               ''459'',',
'               ''460'',',
'               ''461'',',
'               ''462'',',
'               ''463'',',
'               ''464'',',
'               ''465'')',
'       AND msib.segment3 IN (''11'', ''21'', ''22'', ''31'')',
'UNION ALL',
'SELECT DISTINCT',
'       msib.inventory_item_id,',
'       msib.concatenated_segments item_code,',
'       msib.description,',
'       (SELECT MAX (vl.attribute17)',
'          FROM apps.fnd_flex_values_vl@adf vl',
'         WHERE     vl.flex_value_set_id = 1014168',
'               AND vl.flex_value = msib.segment2',
'               AND vl.PARENT_FLEX_VALUE_LOW = msib.segment1)',
'          AS hanger_number,',
'       NULL M2_JOB,',
'       msib.primary_uom_code,',
'       msib.attribute3 supplier_code,',
'       (SELECT description',
'          FROM pwc_flex_values_v',
'         WHERE     flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_COLOR/SHADE''',
'               AND flex_value = msib.segment4)',
'          color,',
'       (SELECT description',
'          FROM pwc_flex_values_v',
'         WHERE     flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_STATUS''',
'               AND flex_value = msib.segment3)',
'          status,',
'       fvv.description item_prefix_desc,',
'       msib.buyer_id sourcing_person_id,',
'       (SELECT ppx.full_name',
'          FROM apps.per_people_x@adf ppx',
'         WHERE ppx.person_id = msib.buyer_id)',
'          sourcing_person_name,',
'       msib.segment3 item_status',
'  FROM apps.mtl_system_items_kfv@adf msib,',
'       pwc_flex_values_v fvv,',
'       apps.mtl_item_categories@adf mic',
' WHERE     msib.organization_id = ''91''',
'       AND msib.segment1 = fvv.flex_value',
'       AND mic.inventory_item_id = msib.inventory_item_id',
'       AND mic.organization_id = msib.organization_id',
'       AND msib.inventory_item_status_code = ''Active''',
'       AND fvv.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''',
'       AND fvv.flex_value IN (''300'', ''301'', ''302'')',
'       AND msib.segment3 IN (''11'', ''21'', ''22'', ''31'')'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'ITEM_CODE'
,p_display_column_name=>'ITEM_CODE'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'ITEM_CODE'
,p_default_sort_direction=>'ASC'
);
