 p_id=>wwv_flow_imp.id(132685647163214687)
,p_lov_name=>'SUPPLIERNAME'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT asa.vendor_name',
'    FROM apps.ap_suppliers@adf asa, apps.ap_supplier_sites_All@adf assa',
'   WHERE     1 = 1',
'         AND assa.vendor_id = asa.vendor_id',
'         AND VENDOR_TYPE_LOOKUP_CODE IN',
'                (''ACCESSORIES SUPPLIERS'',',
'                 ''CHEMICALS'',',
'                 ''COMPANY'',',
'                 ''DYED FABRIC SUPPLIER'',',
'                 ''DYES AND CHEMICALS SUPPLIERS'',',
'                 ''ELECTRONIC MATERIAL SUPPLIERS'',',
'                 ''GREIGE  FABRIC SUPPLIER'',',
'                 ''MISC.ITEMS SUPPLIERS'',',
'                 ''OUTSOURCE PROCESSING'',',
'                 ''PACKING MATERIAL SUPPLIERS'',',
'                 ''POLY CHIPS SUPP'',',
'                 ''POLYESTER SUPPLIERS'',',
'                 ''SERVICES'',',
'                 ''STORES SUPPLIER'',',
'                 ''VENDOR'',',
'                 ''YARN SUPPLIER'')',
'         AND assa.org_id = 85',
'         AND assa.INACTIVE_DATE IS NULL',
'         AND asa.enabled_flag = ''Y''',
'ORDER BY asa.vendor_name ASC',
'',
'',
'',
'',
'-- SELECT ',
