prompt --application/shared_components/user_interface/lovs/trackingno_unit_osp_plan
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(129802173843961479)
,p_lov_name=>'TRACKINGNO_UNIT_OSP_PLAN'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT    ',
'       h.buyer_id,    ',
'       ac.customer_name,    ',
'       l.style_name,    ',
'       l.style_number,    ',
'       d.season_name,    ',
'       d.tracking_no,    ',
'       bd.brand_description brand_name,    ',
'       poc.invoicing_unit_id,    ',
'       DECODE(h.tracking_mode, ''MS'', ''Master Style'', ''CS'', ''Child Style'') tracking_mode,    ',
'       poc.retailer_dept    ',
'  FROM pwc_mt_buyer_details_h h,    ',
'       pwc_mt_brand_details_d bd,    ',
'       pwc_mt_style_details_l l,    ',
'       pwc_mt_season_details_d d,    ',
'       apps.ar_customers@adf ac,    ',
'       pwc_ont_wvn_precosting_h poc,    ',
'       pwc_ont_wvn_precosting_l pocl    ',
' WHERE ac.customer_id = h.buyer_id    ',
'   AND h.header_id = bd.header_id    ',
'   AND poc.header_id = pocl.header_id    ',
'   AND pocl.approval_flag = ''Y''    ',
'   AND bd.brand_line_id = l.brand_line_id    ',
'   AND l.style_line_id = d.style_line_id    ',
'   AND d.season_status = ''Open''    ',
'   AND d.season_identifier IS NOT NULL    ',
'   AND d.tracking_no IS NOT NULL    ',
'   AND d.division = ''Woven''    ',
'   AND d.tracking_no = poc.tracking_no    ',
'   AND poc.invoicing_unit_id = 91    ',
'   AND (:p25_organization_Id IS NOT NULL OR :p25_organization_Id IS NULL)    ',
'   AND h.tracking_mode = ''CS''    ',
'   AND NOT EXISTS (  ',
'       SELECT 1  ',
'         FROM pwc_mfg_osp_header hdr  ',
'        WHERE hdr.tracking_no = d.tracking_no  ',
'   )  ',
'  ',
'UNION ALL    ',
'  ',
'SELECT DISTINCT    ',
'       h.buyer_id,    ',
'       ac.customer_name,    ',
'       l.style_name,    ',
'       l.style_number,    ',
'       d.season_name,    ',
'       d.tracking_no,    ',
'       bd.brand_description brand_name,    ',
'       poc.invoicing_unit_id,    ',
'       DECODE(h.tracking_mode, ''MS'', ''Master Style'', ''CS'', ''Child Style'') tracking_mode,    ',
'       poc.retailer_dept    ',
'  FROM pwc_mt_buyer_details_h h,    ',
'       pwc_mt_brand_details_d bd,    ',
'       pwc_mt_style_details_l l,    ',
'       pwc_mt_season_details_d d,    ',
'        apps.ar_customers@adf ac,    ',
'       pwc_ont_wvn_precosting_h poc    ',
' WHERE ac.customer_id = h.buyer_id    ',
'   AND h.header_id = bd.header_id    ',
'   AND bd.brand_line_id = l.brand_line_id    ',
'   AND l.style_line_id = d.style_line_id    ',
'   AND d.season_status = ''Open''    ',
'   AND d.season_identifier IS NOT NULL    ',
'   AND d.tracking_no IS NOT NULL    ',
'   AND d.division = ''Woven''    ',
'   AND d.tracking_no = poc.tracking_no    ',
'   AND poc.invoicing_unit_id = 91    ',
'   AND (:p25_organization_Id IS NOT NULL OR :p25_organization_Id IS NULL)    ',
'   AND h.tracking_mode = ''MS''    ',
'   AND NOT EXISTS (  ',
'       SELECT 1  ',
'         FROM pwc_mfg_osp_header hdr  ',
'        WHERE hdr.tracking_no = d.tracking_no  ',
'   )'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'TRACKING_NO'
,p_display_column_name=>'TRACKING_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'TRACKING_NO'
,p_default_sort_direction=>'ASC'
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(130473614660629500)
,p_query_column_name=>'TRACKING_NO'
,p_heading=>'Tracking No'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
