prompt --application/shared_components/user_interface/lovs/uaosp_finalprodunit
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(131340769852470240)
,p_lov_name=>'UAOSP_FINALPRODUNIT'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT INV_ORG_NAME,',
'       INV_ORG,',
'       LOOKUP_CODE,',
'       DESCRIPTION,',
'       PRINTING,',
'       EMB,',
'       QUILTING,',
'       TYPE,',
'       VENDOR_ID,',
'       NULL OSP',
'  FROM UA_OSP_FIN_PROD_LSIT_V',
' WHERE TYPE =',
'          DECODE (:FINAL_DEPARTMENT,',
'                  ''Cutting'', ''Cutting'',',
'                  ''Sewing'', ''Sewing'',',
'                  ''Finishing'', ''Finishing'',',
'                  ''Washing - Dry'', ''Washing'',',
'                  ''Washing - Wet'', ''Washing'',',
'                  :FINAL_DEPARTMENT)',
'UNION ALL',
'SELECT DISTINCT ASA.VENDOR_NAME INV_ORG_NAME,',
'                NULL INV_ORG,',
'                NULL LOOKUP_CODE,',
'                NULL DESCRIPTION,',
'                NULL PRINTING,',
'                NULL EMB,',
'                NULL QUILTING,',
'                NULL TYPE,',
'                ASA.VENDOR_ID VENDOR_ID,',
'                ''Y'' OSP',
'  FROM APPS.AP_SUPPLIERS@ADF ASA, APPS.AP_SUPPLIER_SITES_ALL@ADF ASSA',
' WHERE     ASSA.VENDOR_ID = ASA.VENDOR_ID',
'       AND ASSA.PAY_GROUP_LOOKUP_CODE =',
'              ''CMT'' || CHR (38) || ''OUTSOURCE PROCESSING'''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'INV_ORG'
,p_display_column_name=>'INV_ORG_NAME'
,p_default_sort_column_name=>'INV_ORG_NAME'
,p_default_sort_direction=>'ASC'
);
end;
