prompt --application/shared_components/user_interface/lovs/wash_recipe_trackingno_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(153600477507189799)
,p_lov_name=>'WASH_RECIPE_TRACKINGNO_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM       ',
'(SELECT DISTINCT          ',
'       pwc_master_tracking_data_func@adf (mmoh.tracking_no, ''BUYER_ID'') buyer_id,          ',
'       pwc_master_tracking_data_func@adf (mmoh.tracking_no, ''BUYER_NAME'') buyer_name,          ',
'       pwc_master_tracking_data_func@adf (mmoh.tracking_no, ''STYLE_NAME'') style,          ',
'       pwc_master_tracking_data_func@adf (mmoh.tracking_no, ''STYLE_NO'') style_no,          ',
'       pwc_master_tracking_data_func@adf (mmoh.tracking_no, ''SEASON_NAME'') season,          ',
'       NULL organic_auth,          ',
'       mmoh.brand brand,          ',
'       mmoh.tracking_no,          ',
'       NULL current_style,          ',
'       NULL current_season          ',
'  FROM pwc_mfg_osp_dep_assign mmoda,          ',
'       pwc_mfg_osp_stn_line mmosl,          ',
'       pwc_mfg_osp_header mmoh          ',
' WHERE     mmoda.stn_line_id = mmosl.stn_line_id          ',
'       AND mmosl.header_id = mmoh.header_id          ',
'       AND final_department LIKE ''Washing%''          ',
'      -- AND ''Bulk'' = :p_recipe_stage          ',
'       --AND mmoda.final_mfg_org_id = :p_org_id       ',
'UNION ALL          ',
'SELECT DISTINCT          ',
'       pwc_master_tracking_data_func@adf (samp_h.tracking_no, ''BUYER_ID'') buyer_id,          ',
'       pwc_master_tracking_data_func@adf (samp_h.tracking_no, ''BUYER_NAME'') buyer_name,          ',
'       pwc_master_tracking_data_func@adf (samp_h.tracking_no, ''STYLE_NAME'') style,          ',
'       pwc_master_tracking_data_func@adf (samp_h.tracking_no, ''STYLE_NO'') style_no,          ',
'       pwc_master_tracking_data_func@adf (samp_h.tracking_no, ''SEASON_NAME'') season,          ',
'   NULL organic_auth,                 ',
'       samp_h.BRAND_NAME brand,          ',
'       samp_h.tracking_no,          ',
'       NULL current_style,          ',
'       NULL current_season          ',
'  FROM PWC_ONT_WVN_SAMPLE_STATUS samp_h, PWC_ONT_WVN_SAMPLE_STATUS_L samp_l          ',
' WHERE 1 = 1           ',
' --AND ''Sample'' = :p_recipe_stage           ',
' AND samp_h.tracking_no IS NOT NULL          ',
'   AND samp_l.header_id = samp_h.header_id          ',
'  -- AND samp_l.serial_no = :p_serial_no     ',
')       ',
'--WHERE UPPER(tracking_no) LIKE UPPER(''%'' || :p_tracking_no || ''%'')'))
,p_source_type=>'SQL'
