,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html lang="en">',
'<head>',
'<meta charset="UTF-8">',
'<meta name="viewport" content="width=device-width, initial-scale=1.0">',
'<title>M6-Garments Dashboard</title>',
'',
'<!-- Google Fonts -->',
'<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600;900&display=swap" rel="stylesheet">',
'',
'<style>',
'/* Body background */',
'',
'body {',
'  background-color: #1e1e2f;',
'  background-image: url(#APP_FILES#denim.jpg);',
'  /*background-image: url(#APP_FILES#garment.jpg);*/ /* Your wallpaper */',
'  background-repeat: no-repeat;',
'  background-size: cover;',
'  background-attachment: fixed;',
'  font-family: ''Poppins'', sans-serif;',
'  margin: 0;',
'  padding: 0;',
'}',
'',
'/* Heading */',
'.garment-heading {',
'  text-align: center;',
'  font-size: 60px;',
'  font-weight: 930;',
'  color: #fff;',
'  margin: 30px 0;',
'  letter-spacing: 2px;',
'  text-transform: uppercase;',
'  /* background: linear-gradient(135deg, #2563eb, #10b981); */',
'  background: linear-gradient(135deg, #ffffff, #ffffff);',
'  -webkit-background-clip: text;',
'  -webkit-text-fill-color: transparent;',
'  text-shadow: 2px 2px 10px rgba(0,0,0,0.5);',
'}',
'',
'',
'/* Dashboard grid */',
'.garment-dashboard {',
'  display: grid;',
'  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));',
'  gap: 24px;',
'  padding: 20px 40px;',
'}',
'',
'/* Glassy cards */',
'.garment-card {',
'  border-radius: 14px;',
'  padding: 42px 28px;',
'  text-align: center;',
'  font-size: 18px;',
'  font-weight: 600;',
'  color: #fff;',
'',
'  backdrop-filter: blur(10px); /* blur effect */',
'  -webkit-backdrop-filter: blur(18px);',
'  background: rgba(30, 30, 50, 0.45); /* semi-transparent for glass effect */',
'',
'  box-shadow: 0 12px 30px rgba(0,0,0,0.5);',
'  cursor: pointer;',
'  transition: all 0.3s ease;',
'}',
'',
'.garment-card:hover {',
'  transform: translateY(-6px);',
'  box-shadow: 0 18px 40px rgba(0,0,0,0.7);',
'}',
'',
'/* Icons */',
'.garment-icon {',
'  font-size: 40px;',
'  margin-bottom: 12px;',
'}',
'',
'',
'.garment-heading {',
'    text-align: center;',
'    font-size: 60px;',
'    font-weight: 900;',
'    letter-spacing: 4px;',
'    text-transform: uppercase;',
'    color: #000000 !important;',
'    font-family: Arial Black, Impact, sans-serif;',
'    background: #ffffff !important;',
'    -webkit-text-fill-color: #000000 !important;',
'    text-shadow: none !important;',
'    border-bottom: 5px solid #000000;',
'    display: inline-block;',
'    padding-bottom: 6px;',
'    padding-left: 20px;',
'    padding-right: 20px;',
'    margin: 20px auto;',
'}',
'',
'',
'/* New vibrant card colors */',
'.cutting {',
unistr('  background: linear-gradient(135deg, rgba(56,189,248,0.7), rgba(16,163,127,0.7)); /* Cyan \2192 Teal */'),
'}',
'',
'.sewing {',
unistr('  background: linear-gradient(135deg, rgba(250,204,21,0.7), rgba(251,191,36,0.7)); /* Yellow \2192 Amber */'),
'}',
'',
'.orders {',
unistr('  background: linear-gradient(135deg, rgba(236,72,153,0.7), rgba(190,24,93,0.7)); /* Pink \2192 Deep Pink */'),
'}',
'',
'.washing {',
'background: linear-gradient(135deg, rgba(236,72,153,0.85), rgba(236,72,153,0.6) 50%, rgba(190,24,93,0.85));',
'}',
'',
'.Finishing:hover {  transform: translateY(-8px) scale(1.03);  background: linear-gradient(135deg, #4ade80, #15803d);',
'  box-shadow: 0 15px 40px rgba(74,222,128,0.7);',
'}',
'',
'.reports {',
unistr('  background: linear-gradient(135deg, rgba(129,140,248,0.7), rgba(67,56,202,0.7)); /* Indigo \2192 Dark Indigo */'),
'}',
'',
'.machines {',
unistr('  background: linear-gradient(135deg, rgba(34,197,94,0.7), rgba(22,101,52,0.7)); /* Green \2192 Dark Green */'),
'}',
'</style>',
'</head>',
'                    <script>',
'                         var currentUser = "&APP_USER.";',
'                    </script>',
'<body>',
'',
