wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(222012601330508284)
,p_name=>'QUOTED_WASH_COST'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'QUOTED_WASH_COST'
,p_data_type=>'NUMBER'
,p_is_query_only=>false
,p_item_type=>'NATIVE_NUMBER_FIELD'
,p_heading=>'Wash<BR>Cost'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>250
,p_value_alignment=>'CENTER'
,p_attribute_03=>'left'
,p_attribute_04=>'decimal'
,p_item_attributes=>'[object Object]'
,p_is_required=>false
,p_enable_filter=>true
,p_filter_is_required=>false
,p_filter_lov_type=>'NONE'
,p_use_as_row_header=>false
,p_enable_sort_group=>false
,p_enable_hide=>true
,p_is_primary_key=>false
,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  (NVL(SUM(STEAM_COST),0) +NVL(SUM(ELEC_COST),0)+NVL(SUM(OH_COST),0)) WASH_COST',
'FROM (',
'SELECT ROUND(',
'        ( TO_NUMBER(CHARACTER1)',
'          * :P3_WEIGHT_INFO',
'          * :P3_WASH_TIME',
'        ) / 1000',
'        / ( :P3_WASH_LOAD_PERC / 100 )',
'    , 2) AS STEAM_COST,0 ELEC_COST,0 OH_COST',
'FROM (',
'    SELECT CHARACTER1',
'    FROM (',
'        SELECT CHARACTER1',
'        FROM APPS.QA_RESULTS@ADF',
'        WHERE PLAN_ID = 61130',
'        ORDER BY CHARACTER4 DESC',
'    )',
'    WHERE ROWNUM = 1',
')',
'UNION ALL ',
'SELECT 0 STEAM_COST,',
'    ROUND(',
'        ( TO_NUMBER(CHARACTER2)',
'          * :P3_WEIGHT_INFO',
'          * :P3_WASH_TIME',
'        ) / 1000',
'        / ( :P3_WASH_LOAD_PERC / 100 )',
'    , 2) ELEC_COST,0 OH_COST',
'FROM',
'(',
'    SELECT CHARACTER2',
'    FROM APPS.QA_RESULTS@ADF',
'    WHERE PLAN_ID = 61130',
'    ORDER BY CHARACTER4 DESC',
')',
'WHERE ROWNUM = 1',
'UNION ALL ',
'----',
'SELECT 0 STEAM_COST,0 ELEC_COST,',
'    ROUND(',
'        ( TO_NUMBER(CHARACTER3)',
'          * :P3_WEIGHT_INFO',
'          * :P3_WASH_TIME',
'        ) / 1000',
'        / ( :P3_WASH_LOAD_PERC / 100 )',
'    , 2) OH_COST',
'FROM',
'(',
'    SELECT CHARACTER3',
'    FROM APPS.QA_RESULTS@ADF',
'    WHERE PLAN_ID = 61130',
'    ORDER BY CHARACTER4 DESC',
')',
'WHERE ROWNUM = 1)',
''))
,p_duplicate_value=>false
,p_include_in_export=>false
);
end;
/
begin
