wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(222016903362508277)
,p_name=>'PRODUCT_CLASSIFICATION'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'PRODUCT_CLASSIFICATION'
,p_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_TEXT_FIELD'
,p_heading=>'Product<BR>Classification'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>130
,p_value_alignment=>'CENTER'
,p_attribute_05=>'BOTH'
,p_item_attributes=>'[object Object]'
,p_is_required=>true
,p_enable_filter=>true
,p_filter_operators=>'C:S:CASE_INSENSITIVE:REGEXP'
,p_filter_is_required=>false
,p_filter_text_case=>'MIXED'
,p_filter_exact_match=>true
,p_filter_lov_type=>'LOV'
,p_use_as_row_header=>false
,p_enable_sort_group=>false
,p_enable_hide=>true
,p_is_primary_key=>false
,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       qa_child.character3  AS product_classification,',
'       qa_child.character2  AS product_classification_desc',
'FROM apps.qa_results@adf qa_parent,',
'     apps.qa_results@adf qa_child,',
'     apps.qa_pc_results_relationship@adf qpr',
'WHERE qa_parent.occurrence      = qpr.parent_occurrence',
'  AND qa_parent.plan_id         = qpr.parent_plan_id',
'  AND qa_parent.collection_id   = qpr.parent_collection_id',
'  AND qa_child.occurrence       = qpr.child_occurrence',
'  AND qa_child.plan_id          = qpr.child_plan_id',
'  AND qa_child.collection_id    = qpr.child_collection_id',
'  AND qa_child.character1 IS NOT NULL',
'  AND qa_parent.plan_id = 61141',
'  AND qa_child.plan_id  = 61140',
'  AND qa_parent.character2 = :P3_PRODUCT_TYPE',
'  AND NVL(:P3_COSTING_UOM, ''PC'') = ''PC''',
'',
'UNION ALL',
'',
'SELECT qrv.character3  AS product_classification,',
'       qrv.character2  AS product_classification_desc',
'FROM apps.qa_results@adf qrv',
'WHERE qrv.plan_id = 61140',
'  AND NVL(:P3_COSTING_UOM, ''SET'') = ''SET'''))
,p_duplicate_value=>false
,p_include_in_export=>false
);
