,p_is_primary_key=>false
,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ROUND(',
'        ( TO_NUMBER(character1)',
'          * :P3_WEIGHT_INFO',
'          * :P3_WASH_TIME',
'        ) / 1000',
'        / ( :P3_WASH_LOAD_PERC / 100 )',
'    , 2) AS default_value',
'FROM (',
'    SELECT character1',
'    FROM (',
'        SELECT character1',
'        FROM apps.qa_results@adf',
'        WHERE plan_id = 61130',
'        ORDER BY character4 DESC',
'    )',
'    WHERE ROWNUM = 1',
');',
'',
''))
,p_duplicate_value=>false
,p_include_in_export=>false
);
