 p_id=>wwv_flow_imp.id(116862507397651326)
,p_name=>'CONVERSION_RATE_D'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'CONVERSION_RATE_D'
,p_data_type=>'NUMBER'
,p_is_query_only=>false
,p_item_type=>'NATIVE_NUMBER_FIELD'
,p_heading=>'Conv Rate'
,p_heading_alignment=>'RIGHT'
,p_display_sequence=>620
,p_value_alignment=>'RIGHT'
,p_attribute_03=>'left'
,p_attribute_04=>'decimal'
,p_is_required=>false
,p_enable_filter=>true
,p_filter_is_required=>false
,p_filter_lov_type=>'DISTINCT'
,p_use_as_row_header=>false
,p_enable_sort_group=>true
,p_enable_control_break=>true
,p_enable_hide=>true
,p_is_primary_key=>false
,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT GDR.CONVERSION_RATE  ',
'  FROM APPS.GL_DAILY_RATES@adf GDR ',
' WHERE     1 = 1   ',
'       AND GDR.CONVERSION_DATE =   ',
'              (SELECT MAX (GDRR.CONVERSION_DATE)   ',
'                 FROM APPS.GL_DAILY_RATES@adf GDRR   ',
'                WHERE     UPPER (GDRR.CONVERSION_TYPE) = ''CORPORATE''   ',
'                      AND GDRR.FROM_CURRENCY = ''USD'')   ',
'       AND UPPER (GDR.CONVERSION_TYPE) = ''CORPORATE''   ',
'       AND GDR.FROM_CURRENCY = ''USD''--) Conversion_Rate'))
,p_duplicate_value=>true
,p_include_in_export=>true
);
