 p_id=>wwv_flow_imp.id(223587596839487684)
,p_name=>'ITEM_SUPP_NAME'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'ITEM_SUPP_NAME'
,p_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_POPUP_LOV'
,p_heading=>'Supplier Name'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>90
,p_value_alignment=>'CENTER'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
,p_is_required=>false
,p_max_length=>300
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT asa.vendor_name',
'    FROM apps.ap_suppliers@adf asa, apps.ap_supplier_sites_All@adf assa',
'   WHERE     1 = 1',
'         AND assa.vendor_id = asa.vendor_id',
'         AND VENDOR_TYPE_LOOKUP_CODE IN',
'                (''ACCESSORIES SUPPLIERS'',',
'                 ''CHEMICALS'',',
'                 ''COMPANY'',',
'                 ''DYED FABRIC SUPPLIER'',',
'                 ''DYES AND CHEMICALS SUPPLIERS'',',
'                 ''ELECTRONIC MATERIAL SUPPLIERS'',',
'                 ''GREIGE  FABRIC SUPPLIER'',',
'                 ''MISC.ITEMS SUPPLIERS'',',
'                 ''OUTSOURCE PROCESSING'',',
'                 ''PACKING MATERIAL SUPPLIERS'',',
'                 ''POLY CHIPS SUPP'',',
'                 ''POLYESTER SUPPLIERS'',',
'                 ''SERVICES'',',
'                 ''STORES SUPPLIER'',',
'                 ''VENDOR'',',
'                 ''YARN SUPPLIER'')',
'         AND assa.org_id = 85',
'         AND assa.INACTIVE_DATE IS NULL',
'         AND asa.enabled_flag = ''Y''',
'ORDER BY asa.vendor_name ASC',
''))
,p_lov_display_extra=>true
,p_lov_display_null=>true
,p_enable_filter=>true
,p_filter_operators=>'C:S:CASE_INSENSITIVE:REGEXP'
,p_filter_is_required=>false
,p_filter_text_case=>'MIXED'
,p_filter_exact_match=>true
,p_filter_lov_type=>'LOV'
,p_use_as_row_header=>false
,p_enable_sort_group=>false
,p_enable_hide=>true
,p_is_primary_key=>false
,p_duplicate_value=>true
,p_include_in_export=>true
);
