wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(223589372948487702)
,p_name=>'PRICING_UOM'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'PRICING_UOM'
,p_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_POPUP_LOV'
,p_heading=>'Pricing UoM'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>130
,p_value_alignment=>'CENTER'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
,p_is_required=>false
,p_max_length=>255
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT pricing_uom, uom_conv',
'  FROM (SELECT muomv.unit_of_measure pricing_uom,',
'               ROUND ( (CASE',
'                           WHEN APPS.inv_convert.inv_um_convert@ADF (',
'                                   NVL (:INVENTORY_ITEM_ID, 0),',
'                                   (SELECT muomvi.uom_code',
'                                      FROM APPS.mtl_units_of_measure_vl@ADF muomvi',
'                                     WHERE muomvi.unit_of_measure  =',
'                                              :ITEM_UOM),',
'                                   muomv.uom_code) = ''-99999''',
'                           THEN',
'                              APPS.inv_convert.inv_um_convert@ADF (',
'                                 0,',
'                                 (SELECT muomvi.uom_code',
'                                    FROM APPS.mtl_units_of_measure_vl@ADF  muomvi',
'                                   WHERE muomvi.unit_of_measure = :ITEM_UOM),',
'                                 muomv.uom_code)',
'                           ELSE',
'                              APPS.inv_convert.inv_um_convert@ADF (',
'                                 NVL (:INVENTORY_ITEM_ID, 0),',
'                                 (SELECT muomvi.uom_code',
'                                    FROM APPS.mtl_units_of_measure_vl@ADF  muomvi',
'                                   WHERE muomvi.unit_of_measure = :ITEM_UOM),',
'                                 muomv.uom_code)',
'                        END),',
'                      6)',
'                  uom_conv',
'          FROM APPS.mtl_units_of_measure_vl@ADF muomv',
'         WHERE NVL (muomv.attribute1, ''YES'') <> ''NO'')',
' WHERE uom_conv <> ''-99999'';',
'',
'',
''))
,p_lov_display_extra=>true
,p_lov_display_null=>false
,p_lov_cascade_parent_items=>'ITEM_UOM'
,p_ajax_items_to_submit=>'ITEM_UOM'
,p_ajax_optimize_refresh=>true
,p_filter_is_required=>false
,p_use_as_row_header=>false
,p_enable_hide=>true
,p_is_primary_key=>false
,p_duplicate_value=>true
,p_include_in_export=>true
);
