'    v_season_name  VARCHAR2(200);',
'    v_style_no     VARCHAR2(100);',
'    v_brand_name   VARCHAR2(100);',
'BEGIN',
'    SELECT',
'        sl.style_name,',
'        sd.season_name,',
'        sl.style_number,',
'        bd.brand_description',
'    INTO',
'        v_style_name,',
'        v_season_name,',
'        v_style_no,',
'        v_brand_name',
'    FROM   pwc_mt_season_details_d sd',
'    JOIN   pwc_mt_style_details_l sl',
'           ON sd.style_line_id = sl.style_line_id',
'    JOIN   pwc_mt_brand_details_d bd',
'           ON sl.brand_line_id = bd.brand_line_id',
'    WHERE  sd.tracking_no = :P3_TRACKING_NO;',
'',
'    :P3_STYLE_NAME    := v_style_name;',
'    :P3_SEASON_NAME   := v_season_name;',
'    :P3_STYLE_NUMBER  := v_style_no;',
'    :P3_BRAND_NAME    := v_brand_name;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P3_STYLE_NAME    := NULL;',
'        :P3_SEASON_NAME   := NULL;',
'        :P3_STYLE_NUMBER  := NULL;',
'        :P3_BRAND_NAME    := NULL;',
'END;',
'',
'-- DECLARE',
'--     v_style_name  VARCHAR2(200);',
'--     v_season_name VARCHAR2(200);',
'--     v_style_no    VARCHAR2(100);',
'--     v_brand_name  VARCHAR2(100);',
'-- BEGIN',
'--     SELECT',
'--         pwc_master_tracking_data_func(:P3_TRACKING_NO, ''STYLE_NAME''),',
'--         pwc_master_tracking_data_func(:P3_TRACKING_NO, ''SEASON_NAME''),',
'--         pwc_master_tracking_data_func(:P3_TRACKING_NO, ''STYLE_NO''),',
'--         h.BRAND_NAME',
'--     INTO',
'--         v_style_name,',
'--         v_season_name,',
'--         v_style_no,',
'--         v_brand_name',
'--     FROM PWC_ONT_WVN_PRECOSTING_H h',
'--     WHERE h.TRACKING_NO = :P3_TRACKING_NO;',
'',
'--     -- Assign to page items',
'--     :P3_STYLE_NAME  := v_style_name;',
'--     :P3_SEASON_NAME := v_season_name;',
'--     :P3_STYLE_NUMBER    := v_style_no;',
'--     :P3_BRAND_NAME  := v_brand_name;',
'',
'-- EXCEPTION',
'--     WHEN NO_DATA_FOUND THEN',
'--         :P3_STYLE_NAME  := NULL;',
'--         :P3_SEASON_NAME := NULL;',
'--         :P3_STYLE_NUMBER    := NULL;',
'--         :P3_BRAND_NAME  := NULL;',
'-- END;',
'',
''))
,p_attribute_02=>'P3_TRACKING_NO'
,p_attribute_03=>'P3_STYLE_NUMBER,P3_SEASON_NAME,P3_STYLE_NAME,P3_BRAND_NAME'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
