,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'insert header'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_header_id NUMBER;',
'    v_user_id   NUMBER;',
'BEGIN',
unistr('    -- \D83D\DD39 Generate next HEADER_ID safely'),
'    SELECT NVL(MAX(header_id), 0) + 1',
'    INTO v_header_id',
'    FROM PWC_ONT_WVN_PRECOSTING_H;',
'',
'    :P3_HEADER_ID := v_header_id;',
'',
unistr('    -- \D83D\DD39 Get APEX User ID'),
'    BEGIN',
'        SELECT user_id',
'        INTO v_user_id',
'        FROM APEX_230200.WWV_FLOW_USERS',
'        WHERE user_name = :APP_USER;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_user_id := NULL;',
'    END;',
'',
'    :P3_CREATED_BY := v_user_id;',
'',
'END;',
'',
'',
'-- DECLARE',
'--     v_header_id NUMBER;',
'-- BEGIN',
unistr('--     -- \D83D\DD39 Generate next HEADER_ID safely'),
'--     SELECT  NVL(MAX(HEADER_ID), 0) + 1',
'--     INTO v_header_id',
'--     FROM PWC_ONT_WVN_PRECOSTING_H;',
'',
' ',
'--     :P3_HEADER_ID := v_header_id;',
'',
'-- END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P3_HEADER_ID'
,p_process_when_type=>'ITEM_IS_NULL'
,p_process_success_message=>'Save Record'
