wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(139552500670039005)
,p_plug_name=>'testing_report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>40
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html>',
'<head>',
'    <style>',
'        .report-container {',
'            width: 100%;',
'            overflow-x: auto;',
'            margin: 20px 0;',
'        }',
'        ',
'        table {',
'            border-collapse: collapse;',
'            width: 100%;',
'            font-family: Arial, sans-serif;',
'        }',
'        ',
'        th, td {',
'            border: 1px solid #ddd;',
'            padding: 12px;',
'            text-align: left;',
'            white-space: nowrap;',
'        }',
'        ',
'        th {',
'            background-color: #4CAF50;',
'            color: white;',
'            cursor: col-resize;',
'            position: relative;',
'        }',
'        ',
'        tr:nth-child(even) {',
'            background-color: #f2f2f2;',
'        }',
'        ',
'        tr:hover {',
'            background-color: #ddd;',
'        }',
'        ',
'        .resize-handle {',
'            position: absolute;',
'            right: 0;',
'            top: 0;',
'            bottom: 0;',
'            width: 5px;',
'            cursor: col-resize;',
'            background-color: transparent;',
'        }',
'        ',
'        .resize-handle:hover {',
'            background-color: #999;',
'        }',
'        ',
'        .auto-adjust-btn {',
'            margin: 10px 0;',
'            padding: 10px 20px;',
'            background-color: #4CAF50;',
'            color: white;',
'            border: none;',
'            cursor: pointer;',
'            border-radius: 4px;',
'        }',
'        ',
'        .auto-adjust-btn:hover {',
'            background-color: #45a049;',
'        }',
'    </style>',
'</head>',
'<body>',
'    <h2>Interactive Report with Auto-Adjusting Columns</h2>',
'    ',
'    <button class="auto-adjust-btn" onclick="autoAdjustColumns()">',
'        Auto-Adjust Columns',
'    </button>',
'    ',
'    <div class="report-container">',
'        <table id="dataTable">',
'            <thead>',
'                <tr id="headerRow">',
'                    <th>ID <span class="resize-handle"></span></th>',
'                    <th>Name <span class="resize-handle"></span></th>',
'                    <th>Email <span class="resize-handle"></span></th>',
'                    <th>Department <span class="resize-handle"></span></th>',
'                    <th>Salary <span class="resize-handle"></span></th>',
'                    <th>Join Date <span class="resize-handle"></span></th>',
'                </tr>',
'            </thead>',
'            <tbody id="tableBody">',
'                <!-- Data will be populated here -->',
'            </tbody>',
'        </table>',
'    </div>',
'<!-- ',
'    <script>',
'        // Sample data',
'        const employees = [',
'            { id: 1, name: ''John Doe'', email: ''john.doe@company.com'', department: ''Information Technology'', salary: ''$75,000'', joinDate: ''2023-01-15'' },',
'            { id: 2, name: ''Jane Smith'', email: ''jane.smith@verylongcompanyname.com'', department: ''Human Resources'', salary: ''$65,000'', joinDate: ''2023-02-20'' },',
'            { id: 3, name: ''Robert Johnson'', email: ''robert.j@company.com'', department: ''Research and Development'', salary: ''$95,000'', joinDate: ''2023-03-10'' },',
'            { id: 4, name: ''Maria Garcia'', email: ''maria.garcia@company.com'', department: ''Marketing'', salary: ''$70,000'', joinDate: ''2023-04-05'' }',
'        ];',
'',
'        // Populate table',
'        function populateTable() {',
'            const tbody = document.getElementById(''tableBody'');',
'            tbody.innerHTML = '''';',
'            ',
'            employees.forEach(emp => {',
'                const row = tbody.insertRow();',
'                row.innerHTML = `',
'                    <td>${emp.id}</td>',
'                    <td>${emp.name}</td>',
'                    <td>${emp.email}</td>',
'                    <td>${emp.department}</td>',
'                    <td>${emp.salary}</td>',
'                    <td>${emp.joinDate}</td>',
'                `;',
'            });',
'        }',
'',
'        // Auto-adjust columns based on content',
'        function autoAdjustColumns() {',
'            const table = document.getElementById(''dataTable'');',
'            const rows = table.rows;',
'            ',
'            for (let i = 0; i < rows[0].cells.length; i++) {',
'                let maxWidth = 0;',
'                ',
'                // Check header cell',
'                const headerCell = rows[0].cells[i];',
'                const headerText = headerCell.innerText;',
'                maxWidth = Math.max(maxWidth, getTextWidth(headerText));',
'                ',
'                // Check all data cells in this column',
'                for (let j = 1; j < rows.length; j++) {',
'                    const cell = rows[j].cells[i];',
'                    if (cell) {',
'                        const cellWidth = getTextWidth(cell.innerText);',
'                        maxWidth = Math.max(maxWidth, cellWidth);',
'                    }',
'                }',
'                ',
'                // Add padding and set width',
'                const finalWidth = maxWidth + 24; // 24px for padding',
'                for (let j = 0; j < rows.length; j++) {',
'                    if (rows[j].cells[i]) {',
'                        rows[j].cells[i].style.width = finalWidth + ''px'';',
'                        rows[j].cells[i].style.minWidth = finalWidth + ''px'';',
'                        rows[j].cells[i].style.maxWidth = finalWidth + ''px'';',
'                    }',
'                }',
'            }',
'        }',
'',
'        // Helper function to calculate text width',
'        function getTextWidth(text) {',
'            const canvas = document.createElement(''canvas'');',
'            const context = canvas.getContext(''2d'');',
'            context.font = ''16px Arial'';',
'            return context.measureText(text).width;',
'        }',
'',
'        // Column resizing functionality',
'        function makeColumnsResizable() {',
'            const headers = document.querySelectorAll(''th'');',
'            ',
'            headers.forEach(header => {',
'                let isResizing = false;',
'                let startX, startWidth;',
'                ',
'                const handle = header.querySelector(''.resize-handle'');',
'                ',
'                handle.addEventListener(''mousedown'', (e) => {',
'                    isResizing = true;',
'                    startX = e.pageX;',
'                    startWidth = header.offsetWidth;',
'                    ',
'                    document.addEventListener(''mousemove'', onMouseMove);',
'                    document.addEventListener(''mouseup'', onMouseUp);',
'                    ',
'                    e.preventDefault();',
'                });',
'                ',
'                function onMouseMove(e) {',
'                    if (!isResizing) return;',
'                    ',
'                    const width = startWidth + (e.pageX - startX);',
'                    if (width > 50) { // Minimum width',
'                        header.style.width = width + ''px'';',
'                        header.style.minWidth = width + ''px'';',
'                        header.style.maxWidth = width + ''px'';',
'                    }',
'                }',
'                ',
'                function onMouseUp() {',
'                    isResizing = false;',
'                    document.removeEventListener(''mousemove'', onMouseMove);',
'                    document.removeEventListener(''mouseup'', onMouseUp);',
'                }',
'            });',
'        }',
'',
'        // Initialize',
'        populateTable();',
'        makeColumnsResizable();',
'        ',
'        // Auto-adjust on load',
'        window.onload = function() {',
'            setTimeout(autoAdjustColumns, 100);',
'        };',
'        ',
'        // Auto-adjust when window resizes',
'        window.addEventListener(''resize'', autoAdjustColumns);',
'    </script> -->',
