wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(227718160546447619)
,p_plug_name=>'Generate Purchase Requisition'
,p_region_name=>'ir_static_id'
,p_region_template_options=>'#DEFAULT#:js-headingLevel-1:t-Form--standardPadding'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'       ''''Selection,',
'       PWMB.LINE_ID,',
'       PWMB.HEADER_ID,',
'       PWMB.ITEM_TYPE,',
'       PWMB.PURCHASE_TYPE,',
'       PWMB.ITEM_PREFIX,',
'       PWMB.INVENTORY_ITEM_ID,',
'       (SELECT MSI.CONCATENATED_SEGMENTS',
'          FROM apps.MTL_SYSTEM_ITEMS_KFV@adf MSI',
'         WHERE MSI.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'           AND MSI.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID)',
'          ITEM_CODE,',
'       PWMB.SUPPLIER_NOMINATION,',
'       PWMB.ITEM_SUPP_NAME,',
'       PWMB.ITEM_REMARKS,',
'       PWMB.UOM_CONV_RATE,',
'       PWMB.ITEM_CONSUMPTION,',
'       PWMB.ITEM_WASTAGE,',
'       PWMB.ITEM_BOM_REQ_QTY,',
'       PWMB.ITEM_BOOKING_PRCNT,',
'       PWMB.ITEM_ADDITIONAL_QTY,',
'       PWMB.ITEM_ACTUAL_PR_QTY,',
'       PWMB.ITEM_BOOKED_PRCNT,',
'       PWMB.ITEM_TOTAL_BOOKED_QTY,',
'       PWMB.ITEM_PENDING_BOOKING_QTY,',
'       PWMB.ITEM_PRICE_PER_UNIT,',
'       (SELECT NVL (MAX (LR.LAST_PUR_RATE), 0) LAST_PUR_RATE',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR',
'         WHERE LR.ORGANIZATION_ID = 91',
'           AND LR.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID) LAST_PUR_RATE,',
'       PWMB.ITEM_TOTAL_VALUE,',
'       PWMB.CREATED_BY,',
'       PWMB.CREATION_DATE,',
'       PWMB.LAST_UPDATED_BY,',
'       PWMB.LAST_UPDATE_DATE,',
'       PWMB.CHILD_STYLE_NO,',
'       PWMB.PRODUCTION_AREA,',
'       (SELECT PPX.FULL_NAME',
'          FROM apps.MTL_SYSTEM_ITEMS@adf MSI, apps.PER_PEOPLE_X@adf PPX',
'         WHERE  PPX.PERSON_ID = MSI.BUYER_ID',
'               AND MSI.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'               AND MSI.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID) AS ITEM_BUYER_NAME,',
'       (SELECT MSI.DESCRIPTION',
'          FROM apps.MTL_SYSTEM_ITEMS@adf MSI',
'         WHERE MSI.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'           AND MSI.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID) AS ITEM_DESCRIPTION,',
'       (SELECT MSI.ATTRIBUTE5',
'          FROM apps.MTL_SYSTEM_ITEMS@adf MSI',
'         WHERE MSI.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'          AND MSI.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID) AS SUPPLIER_CODE,',
'       PWMB.ITEM_ORGANIZATION_ID,',
'       PWMB.ITEM_PENDING_BOOKING_PRCNT,',
'       (SELECT FFV.DESCRIPTION',
'          FROM PWC_FLEX_VALUES_V@adf FFV',
'         WHERE FFV.FLEX_VALUE_SET_NAME = ''XXSG_INV_ITEM_PREFIX''',
'           AND LPAD (TO_NUMBER (FFV.FLEX_VALUE), 5, ''0'') = PWMB.ITEM_PREFIX) AS PREFIX_DESCRIPTION,',
'       PWMB.PRODUCT_CLASSIFICATION,',
'       PWMB.REQ_CURRENCY,',
'       PWMB.REQ_EXCESS_BUY_REASON,',
'       PWMB.REQ_MATERIAL_FLAG,',
'       --  PWMB.REQ_NEED_BY_DATE,',
'       (SELECT MAX (POCH.BEFORE_WASH_CLEARANCE_DATE)',
'          FROM PWC_ONT_WVN_MASTER_BOM_H H,',
'               PWC_ONT_WVN_MASTER_BOM_ITEMS_L L,',
'               PWC_ONT_WVN_PRECOSTING_H POCH',
'            WHERE  H.HEADER_ID = L.HEADER_ID',
'               AND POCH.TRACKING_NO = H.TRACKING_NO',
'               AND L.HEADER_ID = PWMB.HEADER_ID) REQ_NEED_BY_DATE,',
'       NVL (',
'          (SELECT SUM (MOQD.PRIMARY_TRANSACTION_QUANTITY)',
'             FROM apps.MTL_ONHAND_QUANTITIES_DETAIL@adf MOQD',
'            WHERE     MOQD.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'                  AND MOQD.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID),0) AS ON_HAND_ITEM_QUANTITY,',
'       PWMB.NON_INVENTORY_DESCRIPTION,',
'       PWMB.INVENTORY_ITEM_FLAG,',
'       PWMB.PRECOSTING_ITEM_FLAG,',
'       PWMB.COSTING_UOM,',
'       PWMB.PROCUREMENT_UOM,',
'       PWMB.POC_ITEM_PRICE_PER_UNIT,',
'       PWMB.POC_ITEM_CONSUMPTION,',
'       PWMB.POC_UOM_CONV_RATE,',
'       PWMB.POC_COST_PER_PIECE,',
'       PWMB.PRE_POD_GSM,',
'       PWMB.GARMENT_QTY,',
'       NVL (',
'          (SELECT SUM (MOQD.PRIMARY_TRANSACTION_QUANTITY)',
'             FROM apps.MTL_ONHAND_QUANTITIES_DETAIL@adf MOQD, apps.MTL_ITEM_LOCATIONS@adf MIL',
'            WHERE     MOQD.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'                  AND MOQD.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID',
'                  AND MIL.SEGMENT1 = MOQD.SUBINVENTORY_CODE',
'                  AND MIL.INVENTORY_LOCATION_ID = MOQD.LOCATOR_ID',
'                  AND MIL.SEGMENT7 = NVL (H.TRACKING_NO, ''0000'')',
'                  AND MIL.DISABLE_DATE IS NULL',
'                  AND MIL.ORGANIZATION_ID = MOQD.ORGANIZATION_ID',
'                  AND MOQD.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID),0) STYLE_WISE_STOCK,',
'         apps.PWC_ONT_WVN_MASTER_BOM_STD_PKG.GET_ONHAND_BALANCE@adf (''Archive Store'',',
'          PWMB.HEADER_ID,',
'          PWMB.LINE_ID,',
'          PWMB.INVENTORY_ITEM_ID,',
'          PWMB.CHILD_STYLE_NO) AS ARCHIVE_STORE_STOCK,',
'       NVL (',
'          (SELECT SUM (MOQD.PRIMARY_TRANSACTION_QUANTITY)',
'             FROM apps.MTL_ONHAND_QUANTITIES_DETAIL@adf MOQD, apps.MTL_ITEM_LOCATIONS@adf MIL',
'            WHERE  MOQD.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'                  AND MOQD.ORGANIZATION_ID = PWMB.ITEM_ORGANIZATION_ID',
'                  AND MIL.SEGMENT1 = MOQD.SUBINVENTORY_CODE',
'                  AND MIL.INVENTORY_LOCATION_ID = MOQD.LOCATOR_ID',
'                  AND MIL.SEGMENT7 = NVL (''MTML-TBC'', ''0000'')',
'                  AND MIL.DISABLE_DATE IS NULL',
'                  AND MIL.ORGANIZATION_ID = MOQD.ORGANIZATION_ID',
'                  AND MOQD.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID),0) LEFT_OVER_STOCK,',
'       PWMB.CONE_CONSUMPTION,',
'       CASE WHEN NVL (ITEM_ACTUAL_PR_QTY, 0) <= 0 THEN ''Y'' ELSE ''N'' END',
'          PR_VALIDATION_CHECK,',
'       PWMB.ITEM_STATUS,',
'       PWMB.SHRINKAGE_LENGTH,',
'       PWMB.SHRINKAGE_WIDTH,',
'       PWMB.REQUIRED_WIDTH,',
'--       PWC_ONT_WVN_MASTER_BOM_STD_PKG.GET_BPO_GENERIC_COLORS@adf(PWMB.LINE_ID,NULL)  BPO_GEN_COLOURS,',
'       PWMB.SIZE_WISE_MARKING,',
'       PWMB.M2_ORDER_LINE_ID,',
'       PWMB.M2_JOB_NAME,',
'       PWMB.M2_ITEM_RATE,',
'       NVL (',
'          (SELECT DISTINCT ''Y''',
'             FROM apps.PO_REQUISITION_HEADERS_ALL@adf PRHA,',
'                  apps.PO_REQUISITION_LINES_ALL@adf PRLA',
'            WHERE     PRHA.REQUISITION_HEADER_ID = PRLA.REQUISITION_HEADER_ID',
'                  AND PRHA.AUTHORIZATION_STATUS = ''APPROVED''',
'                  AND NVL (PRLA.CANCEL_FLAG, ''N'') = ''N''',
'                  AND PRHA.ATTRIBUTE_CATEGORY = ''BOM Requisition''',
'                  AND PRLA.ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'                  AND PRHA.ATTRIBUTE1 = H.TRACKING_NO',
'                  AND PRHA.ATTRIBUTE2 = H.BOM_NUMBER--  AND  (prla.attribute6) =a.line_id',
'          ),''N'') PR_FLAG,',
'       PWMB.TBC_TRACKING_NO,',
'       PWMB.TBC_POST, NVL ((SELECT ''Y''',
'             --*--start_quantity',
'             FROM apps.WIP_DISCRETE_JOBS_V@adf WDJ, apps.WIP_REQUIREMENT_OPERATIONS_V@adf OV --, pwc_mfg_cutlyrcntrl_h h',
'            WHERE     1 = 1',
'                  AND WDJ.WIP_ENTITY_ID = OV.WIP_ENTITY_ID',
'                  AND WDJ.ATTRIBUTE2 = H.TRACKING_NO          --WDJ.ATTRIBUTE2',
'                  AND OV.INVENTORY_ITEM_ID = PWMB.INVENTORY_ITEM_ID',
'                  AND WDJ.ORGANIZATION_ID = 91',
'                  AND OV.ORGANIZATION_ID = 91            --OOD.ORGANIZATION_ID',
'                  AND WDJ.STATUS_TYPE NOT IN (7)',
'                  AND ROWNUM = 1),''N'') JOB_FLAG,',
'       PWMB.SUPPLIER_FLAG',
'  FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L PWMB,',
'       PWC_ONT_WVN_MASTER_BOM_H H',
' WHERE    ( (UPPER (PWMB.ITEM_STATUS) LIKE UPPER (''%'' || :P4_ITEMTYPE || ''%'')))',
'       AND H.HEADER_ID = PWMB.HEADER_ID',
'       AND H.HEADER_ID=:P4_HEADER_ID'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Generate Purchase Requisition'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
