wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(138144834860222546)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'create_requisition'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_REQ_ID VARCHAR2(4000);',
'    V_MSG    VARCHAR2(4000);',
'BEGIN',
'',
'    -- Create Requisition',
'    apps.pwc_ont_wvn_master_bom_apex.create_requisition@adf',
'    (   p_header_id => :P4_HEADER_ID,',
'        p_user_id   => 10835 );',
'',
'    -- Get Request ID',
'SELECT MAX(h.SEGMENT1)',
'INTO V_REQ_ID',
'FROM APPS.po_requisition_headers_all@ADF h ,APPS.po_requisition_lines_all@ADF l,PWC_ONT_WVN_MASTER_BOM_H HH',
'WHERE h.REQUISITION_HEADER_ID = l.REQUISITION_HEADER_ID',
'AND h.ATTRIBUTE2 = HH.BOM_NUMBER',
'AND h.ATTRIBUTE1 = HH.TRACKING_NO',
'AND h.ATTRIBUTE1 = :P4_TRACKING_NO;',
'',
'    -- Prepare full message',
'    V_MSG := ''Requisition created successfully. Req No: '' || V_REQ_ID;',
'',
'    -- Save full message in column',
'    UPDATE PWC_ONT_WVN_MASTER_BOM_H',
'    SET TXN_MESSAGE = V_MSG',
'    WHERE HEADER_ID = :P4_HEADER_ID',
'    AND TRACKING_NO = :P4_TRACKING_NO;',
'',
'    -- Show success message on APEX page',
'    apex_application.g_print_success_message := V_MSG;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(138144797323222545)
,p_internal_uid=>138144834860222546
);
end;
