wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(221344236588982414)
,p_plug_name=>'Master BoM'
,p_region_name=>'adf_region'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--padded:t-ContentBlock--h2:t-ContentBlock--shadowBG'
,p_plug_template=>wwv_flow_imp.id(220313214896810970)
,p_plug_display_sequence=>21
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tb1.HEADER_ID, ',
'       tb1.BOM_NUMBER, ',
'       tb1.BOM_DATE, ',
'       tb1.TRACKING_NO, ',
'       tb1.RETAILER_DEPT, ',
'       tb1.COPIED_FROM_BOM, ',
'       tb1.INVOICING_UNIT_ID, ',
'       tb1.CREATED_BY, ',
'       tb1.CREATION_DATE, ',
'       tb1.LAST_UPDATED_BY, ',
'       tb1.LAST_UPDATE_DATE, ',
'       (SELECT ac.customer_name    FROM apps.ar_customers@adf ac   WHERE ac.customer_id = tb1.BUYER_ID) AS BUYER_NAME, ',
'       (select pwc_master_tracking_data_func (tb1.TRACKING_NO, ''STYLE_NAME'') from dual )AS STYLE_NAME, ',
'       (SELECT d.season_name    FROM pwc_mt_season_details_d d   WHERE d.tracking_no = tb1.TRACKING_NO) AS SEASON_NAME, ',
'       (SELECT pwc_master_tracking_data_func (tb1.TRACKING_NO, ''BRAND_DESCRIPTION'') FROM DUAL) AS BRAND , ',
'       (SELECT bh.tracking_mode    FROM pwc_mt_buyer_details_h bh   WHERE bh.buyer_id = tb1.BUYER_ID) AS TRACKING_MODE, ',
'       (SELECT d.season_status FROM pwc_mt_season_details_d d WHERE d.tracking_no = tb1.TRACKING_NO) AS TRACKING_STATUS, ',
'       (SELECT DECODE (bh.tracking_mode,''MS'', ''Master Style'',''CS'', ''Child Style'')    FROM pwc_mt_buyer_details_h bh   WHERE bh.buyer_id = tb1.BUYER_ID) AS TRACKING_MODE_DESC, ',
'        (SELECT TRIM(MAX(wph.buyer_agent_name))   FROM pwc_ont_wvn_precosting_h wph  WHERE  wph.tracking_no = tb1.TRACKING_NO) AS BUYER_AGENT_NAME, ',
'       (SELECT hou.name FROM apps.hr_organization_units@adf hou WHERE hou.organization_id = tb1.INVOICING_UNIT_ID) AS INVOICING_UNIT_NAME, ',
'       tb1.TXN_MESSAGE, ',
'       NVL (    (SELECT SUM (NVL (bom_bpo_l.final_order_quantity, 0))       FROM pwc_ont_wvn_master_bom_bpo_l bom_bpo_l      WHERE bom_bpo_l.header_id = tb1.HEADER_ID),    0) AS SUM_ASSIGNED_BPO_QUANTITY, ',
'       (SELECT COUNT (1)    FROM pwc_file_upd_dwn ff   WHERE ff.file_id = ''WBOM'' || tb1.BOM_NUMBER) AS VIEW_ATTR, ',
'       (SELECT pwc_master_tracking_data_func (tb1.TRACKING_NO, ''STYLE_NO'')FROM DUAL) AS STYLE_NO, ',
'       tb1.BUYER_ID, ',
'       tb1.PS_CODE',
'FROM  PWC_ONT_WVN_MASTER_BOM_H tb1',
'',
'',
'',
''))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
