,p_region_template_options=>'#DEFAULT#:t-IRR-region--noBorders'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT POWMB.DETAIL_ID, ',
'       POWMB.LINE_ID, ',
'       POWMB.INVENTORY_ITEM_ID, ',
'       POWMB.SALE_ORDER_ID, ',
'       POWMB.BPO_LINE_NO, ',
'       POWMB.CHILD_STYLE_NO, ',
'       POWMB.COUNTRY, ',
'       POWMB.DCPO_NAME, ',
'       POWMB.COLOUR, ',
'       POWMB.INSEAM_VAL, ',
'       POWMB.SIZE_VAL, ',
'       POWMB.SIZE_QUANTITY, ',
'       POWMB.CREATED_BY, ',
'       POWMB.CREATION_DATE, ',
'       POWMB.LAST_UPDATED_BY, ',
'       POWMB.LAST_UPDATE_DATE, ',
'      (SELECT ooha.attribute12   FROM apps.oe_order_headers_all@adf ooha  WHERE  ooha.flow_status_code <> ''CANCELLED'' AND ooha.header_id = POWMB.SALE_ORDER_ID) AS FINAL_REPLACED_BPO, ',
'       POWMB.PRODUCT_CLASSIFICATION, ',
'       POWMB.SIZE_ASSIGNMENT,',
'      (SELECT DISTINCT ooha.attribute7 FROM apps.oe_order_headers_all@adf ooha  WHERE ooha.flow_status_code <> ''CANCELLED'' AND ooha.header_id = POWMB.SALE_ORDER_ID) AS REFERENCE_TBA, ',
'      (SELECT ooha.attribute3   FROM apps.oe_order_headers_all@adf ooha  WHERE ooha.flow_status_code <> ''CANCELLED''  AND ooha.header_id = POWMB.SALE_ORDER_ID) AS CLASSIFICATION',
'FROM  PWC_ONT_WVN_MASTER_BOM_GENRC_D POWMB;'))
,p_plug_source_type=>'NATIVE_IG'
,p_master_region_id=>wwv_flow_imp.id(124202270056457010)
