wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(145989671117680850)
,p_plug_name=>'Dashboard'
,p_parent_plug_id=>wwv_flow_imp.id(221387840467045423)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html  CLOB := '''';',
'    l_count NUMBER := 0;',
'    v_header_id NUMBER := :P7_HEADER_ID; -- Current header ID from page',
'BEGIN',
'    l_html := l_html || ''',
'    <style>',
'        /* Existing styles same rahenge */',
'        :root {',
'            --primary-color: #4361ee;',
'            --primary-dark: #3a56d4;',
'            --secondary-color: #7209b7;',
'            --success-color: #2ec4b6;',
'            --warning-color: #f9c74f;',
'            --danger-color: #f94144;',
'            --light-bg: #f8f9fa;',
'            --dark-text: #2d3748;',
'            --light-text: #718096;',
'            --card-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);',
'            --hover-shadow: 0 20px 40px rgba(0, 0, 0, 0.12);',
'        }',
'        ',
'        * {',
'            margin: 0;',
'            padding: 0;',
'            box-sizing: border-box;',
'        }',
'        ',
'        body {',
'            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;',
'            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);',
'            min-height: 100vh;',
'            padding: 20px;',
'        }',
'        ',
'        .dashboard-container {',
'            max-width: 1400px;',
'            margin: 0 auto;',
'        }',
'        ',
'        /* Header Styles */',
'        .dashboard-header {',
'            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);',
'            border-radius: 20px;',
'            padding: 30px;',
'            margin-bottom: 30px;',
'            color: white;',
'            position: relative;',
'            overflow: hidden;',
'            box-shadow: var(--card-shadow);',
'        }',
'        ',
'        .header-content {',
'            position: relative;',
'            z-index: 2;',
'        }',
'        ',
'        .header-title {',
'            font-size: 36px;',
'            font-weight: 700;',
'            margin-bottom: 10px;',
'            display: flex;',
'            align-items: center;',
'            gap: 15px;',
'        }',
'        ',
'        .header-title i {',
'            font-size: 48px;',
'            background: rgba(255,255,255,0.2);',
'            padding: 15px;',
'            border-radius: 15px;',
'        }',
'        ',
'        .header-subtitle {',
'            font-size: 16px;',
'            opacity: 0.9;',
'            margin-bottom: 30px;',
'        }',
'        ',
'        .stats-grid {',
'            display: grid;',
'            grid-template-columns: repeat(4, 1fr);',
'            gap: 20px;',
'        }',
'        ',
'        .stat-card {',
'            background: rgba(255, 255, 255, 0.1);',
'            backdrop-filter: blur(10px);',
'            border-radius: 15px;',
'            padding: 20px;',
'            text-align: center;',
'            border: 1px solid rgba(255, 255, 255, 0.2);',
'            transition: transform 0.3s;',
'        }',
'        ',
'        .stat-card:hover {',
'            transform: translateY(-5px);',
'            background: rgba(255, 255, 255, 0.15);',
'        }',
'        ',
'        .stat-value {',
'            font-size: 36px;',
'            font-weight: 700;',
'            margin-bottom: 5px;',
'        }',
'        ',
'        .stat-label {',
'            font-size: 14px;',
'            opacity: 0.9;',
'        }',
'        ',
'        /* Charts Grid */',
'        .charts-grid {',
'            display: grid;',
'            grid-template-columns: repeat(2, 1fr);',
'            gap: 20px;',
'            margin-bottom: 30px;',
'        }',
'        ',
'        .chart-card {',
'            background: white;',
'            border-radius: 15px;',
'            padding: 25px;',
'            box-shadow: var(--card-shadow);',
'            transition: all 0.3s;',
'        }',
'        ',
'        .chart-card:hover {',
'            box-shadow: var(--hover-shadow);',
'        }',
'        ',
'        .chart-header {',
'            display: flex;',
'            justify-content: space-between;',
'            align-items: center;',
'            margin-bottom: 20px;',
'        }',
'        ',
'        .chart-title {',
'            font-size: 18px;',
'            font-weight: 600;',
'            color: var(--dark-text);',
'        }',
'        ',
'        .chart-subtitle {',
'            color: var(--light-text);',
'            font-size: 13px;',
'            margin-top: 5px;',
'        }',
'        ',
'        .chart-container {',
'            height: 300px;',
'            position: relative;',
'        }',
'        ',
'        /* Items Grid */',
'        .items-grid {',
'            display: grid;',
'            grid-template-columns: repeat(2, 1fr);',
'            gap: 20px;',
'            margin-top: 20px;',
'        }',
'        ',
'        .items-card {',
'            background: white;',
'            border-radius: 15px;',
'            padding: 25px;',
'            box-shadow: var(--card-shadow);',
'        }',
'        ',
'        .items-title {',
'            font-size: 18px;',
'            font-weight: 600;',
'            color: var(--dark-text);',
'            margin-bottom: 20px;',
'            display: flex;',
'            align-items: center;',
'            gap: 10px;',
'        }',
'        ',
'        .items-title i {',
'            color: var(--primary-color);',
'        }',
'        ',
'        .items-table {',
'            width: 100%;',
'            border-collapse: collapse;',
'        }',
'        ',
'        .items-table th {',
'            text-align: left;',
'            padding: 10px;',
'            background: #f8f9fa;',
'            color: var(--light-text);',
'            font-weight: 600;',
'            font-size: 12px;',
'        }',
'        ',
'        .items-table td {',
'            padding: 10px;',
'            border-bottom: 1px solid #edf2f7;',
'            color: var(--dark-text);',
'            font-size: 13px;',
'        }',
'        ',
'        .progress-bar {',
'            width: 100%;',
'            height: 8px;',
'            background: #e9ecef;',
'            border-radius: 4px;',
'            overflow: hidden;',
'        }',
'        ',
'        .progress-fill {',
'            height: 100%;',
'            background: linear-gradient(90deg, #667eea, #764ba2);',
'            border-radius: 4px;',
'            transition: width 0.3s ease;',
'        }',
'        ',
'        .loading {',
'            text-align: center;',
'            padding: 50px;',
'            color: #666;',
'        }',
'        ',
'        @media (max-width: 1024px) {',
'            .stats-grid,',
'            .charts-grid,',
'            .items-grid {',
'                grid-template-columns: 1fr;',
'            }',
'        }',
'        ',
'        /* Updated Stat Cards CSS - Fixed */',
'        .stats-grid {',
'            display: grid;',
'            grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));',
'            gap: 20px;',
'            margin: 20px 0;',
'        }',
'        ',
'        /* Base Stat Card */',
'        .stat-card {',
'            border-radius: 20px;',
'            padding: 25px;',
'            color: white;',
'            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);',
'            transition: all 0.3s ease;',
'            position: relative;',
'            overflow: hidden;',
'            display: flex;',
'            align-items: center;',
'            gap: 20px;',
'            border: 1px solid rgba(255, 255, 255, 0.1);',
'        }',
'        ',
'        /* Individual Card Colors */',
'        .stat-card:nth-child(1) {',
'            background: linear-gradient(135deg, #4361ee, #7209b7);',
'        }',
'        ',
'        .stat-card:nth-child(2) {',
'            background: linear-gradient(135deg, #f72585, #b5179e);',
'        }',
'        ',
'        .stat-card:nth-child(3) {',
'            background: linear-gradient(135deg, #4cc9f0, #4895ef);',
'        }',
'        ',
'        .stat-card:nth-child(4) {',
'            background: linear-gradient(135deg, #f8961e, #f3722c);',
'        }',
'        ',
'        /* Hover Effect */',
'        .stat-card:hover {',
'            transform: translateY(-8px) scale(1.02);',
'            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);',
'        }',
'        ',
'        /* Decorative Background */',
'        .stat-card::before {',
'            content: "";',
'            position: absolute;',
'            top: -50%;',
'            right: -50%;',
'            width: 200%;',
'            height: 200%;',
'            background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);',
'            opacity: 0;',
'            transition: opacity .5s ease;',
'            pointer-events: none;',
'        }',
'        ',
'        .stat-card:hover::before {',
'            opacity: 1;',
'        }',
'        ',
'        /* Shine Effect */',
'        .stat-card::after {',
'            content: "";',
'            position: absolute;',
'            top: -50%;',
'            left: -50%;',
'            width: 200%;',
'            height: 200%;',
'            background: linear-gradient(',
'                45deg,',
'                transparent,',
'                rgba(255,255,255,0.05),',
'                transparent',
'            );',
'            transform: rotate(45deg);',
'            animation: shine 4s infinite;',
'            pointer-events: none;',
'        }',
'        ',
'        /* Icon Styling */',
'        .stat-icon {',
'            font-size: 48px;',
'            opacity: .9;',
'            background: rgba(255,255,255,.2);',
'            width: 70px;',
'            height: 70px;',
'            border-radius: 18px;',
'            display: flex;',
'            align-items: center;',
'            justify-content: center;',
'            backdrop-filter: blur(5px);',
'            border: 1px solid rgba(255,255,255,.3);',
'            box-shadow: 0 5px 15px rgba(0,0,0,.2);',
'            transition: .3s;',
'        }',
'        ',
'        .stat-card:hover .stat-icon {',
'            transform: rotate(5deg) scale(1.1);',
'            background: rgba(255,255,255,.3);',
'        }',
'        ',
'        /* Info Container */',
'        .stat-info {',
'            flex: 1;',
'        }',
'        ',
'        /* Value Styling */',
'        .stat-value {',
'            font-size: 36px;',
'            font-weight: 800;',
'            margin-bottom: 5px;',
'            text-shadow: 2px 2px 4px rgba(0,0,0,.2);',
'        }',
'        ',
'        /* Label Styling */',
'        .stat-label {',
'            font-size: 14px;',
'            opacity: .9;',
'            text-transform: uppercase;',
'            letter-spacing: 1px;',
'        }',
'        ',
'        /* Shine animation */',
'        @keyframes shine {',
'            0% {',
'                transform: translateX(-100%) rotate(45deg);',
'            }',
'            100% {',
'                transform: translateX(100%) rotate(45deg);',
'            }',
'        }',
'        ',
'        /* Error Styles */',
'        .error-container {',
'            text-align: center;',
'            padding: 60px 20px;',
'            background: white;',
'            border-radius: 20px;',
'            box-shadow: var(--card-shadow);',
'            max-width: 500px;',
'            margin: 50px auto;',
'        }',
'        ',
'        .error-icon {',
'            font-size: 64px;',
'            margin-bottom: 20px;',
'        }',
'        ',
'        .error-title {',
'            color: var(--dark-text);',
'            margin-bottom: 10px;',
'            font-size: 24px;',
'        }',
'        ',
'        .error-message {',
'            color: var(--danger-color);',
'            margin-bottom: 15px;',
'        }',
'        ',
'        .error-detail {',
'            color: var(--light-text);',
'            font-size: 14px;',
'        }',
'    </style>',
'    ',
'    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css">',
'    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>',
'    ',
'    <div class="dashboard-container">',
'        <!-- Header with BOM Info -->',
'        <div class="dashboard-header">',
'            <div class="header-content">',
'                <div class="header-title">',
'                    <i class="fas fa-clipboard-list"></i>',
'                    BOM Dashboard <br><br> HEADER ID '' || v_header_id || ''</br></br>',
'                </div>',
'                <div class="header-subtitle">',
'                    Detailed analysis for selected Bill of Material',
'                </div>'';',
'    ',
'    -- Get BOM Header Info',
'    FOR bom_rec IN (',
'        SELECT tb1.BOM_NUMBER, tb1.TRACKING_NO, ',
'               (SELECT ac.customer_name FROM apps.ar_customers@adf ac WHERE ac.customer_id = tb1.BUYER_ID) AS BUYER_NAME,',
'               (SELECT pwc_master_tracking_data_func(tb1.TRACKING_NO, ''STYLE_NAME'') FROM dual) AS STYLE_NAME,',
'               tb1.BOM_DATE',
'        FROM PWC_ONT_WVN_MASTER_BOM_H tb1',
'        WHERE tb1.HEADER_ID = v_header_id',
'    ) LOOP',
'        l_html := l_html || ''',
'                <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 20px; background: rgba(255,255,255,0.1); padding: 20px; border-radius: 15px;">',
'                    <div><strong>BOM Number:</strong> '' || bom_rec.BOM_NUMBER || ''</div>',
'                    <div><strong>Tracking No:</strong> '' || bom_rec.TRACKING_NO || ''</div>',
'                    <div><strong>Buyer:</strong> '' || bom_rec.BUYER_NAME || ''</div>',
'                    <div><strong>Style:</strong> '' || bom_rec.STYLE_NAME || ''</div>',
'                    <div><strong>Date:</strong> '' || TO_CHAR(bom_rec.BOM_DATE, ''DD-MON-YYYY'') || ''</div>',
'                </div>'';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''',
'            </div>',
'        </div>',
'        ',
'        <!-- Stats Cards -->',
'        <div class="stats-grid" id="bomStats">'';',
'    ',
'    -- BPO Stats',
'    DECLARE',
'        v_total_bpo_qty NUMBER := 0;',
'        v_total_items NUMBER := 0;',
'        v_total_value NUMBER := 0;',
'        v_unique_items NUMBER := 0;',
'    BEGIN',
'        -- Total BPO Quantity',
'        SELECT NVL(SUM(FINAL_ORDER_QUANTITY), 0) ',
'        INTO v_total_bpo_qty',
'        FROM PWC_ONT_WVN_MASTER_BOM_BPO_L ',
'        WHERE HEADER_ID = v_header_id;',
'        ',
'        -- Total Items',
'        SELECT COUNT(*), NVL(SUM(ITEM_TOTAL_VALUE), 0), COUNT(DISTINCT INVENTORY_ITEM_ID)',
'        INTO v_total_items, v_total_value, v_unique_items',
'        FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L ',
'        WHERE HEADER_ID = v_header_id;',
'        ',
'        l_html := l_html || ''',
'        <!-- Card 1: BPO Quantity -->',
'        <div class="stat-card">',
'            <div class="stat-icon">',
'                <i class="fas fa-cubes"></i>',
'            </div>',
'            <div class="stat-info">',
'                <div class="stat-value">'' || v_total_bpo_qty || ''</div>',
'                <div class="stat-label">Total BPO Quantity</div>',
'            </div>',
'        </div>',
'        ',
'        <!-- Card 2: Total Line Items -->',
'        <div class="stat-card">',
'            <div class="stat-icon">',
'                <i class="fas fa-list-ul"></i>',
'            </div>',
'            <div class="stat-info">',
'                <div class="stat-value">'' || v_total_items || ''</div>',
'                <div class="stat-label">Total Line Items</div>',
'            </div>',
'        </div>',
'        ',
'        <!-- Card 3: Total Material Value -->',
'        <div class="stat-card">',
'            <div class="stat-icon">',
'                <i class="fas fa-dollar-sign"></i>',
'            </div>',
'            <div class="stat-info">',
'                <div class="stat-value">$'' || TO_CHAR(v_total_value, ''999,999,999'') || ''</div>',
'                <div class="stat-label">Total Material Value</div>',
'            </div>',
'        </div>',
'        ',
'        <!-- Card 4: Unique Materials -->',
'        <div class="stat-card">',
'            <div class="stat-icon">',
'                <i class="fas fa-tags"></i>',
'            </div>',
'            <div class="stat-info">',
'                <div class="stat-value">'' || v_unique_items || ''</div>',
'                <div class="stat-label">Unique Materials</div>          ',
'            </div>',
'        </div>'';',
'        ',
'    END;',
'    ',
'    l_html := l_html || ''',
'        </div>',
'        ',
'        <!-- Charts Grid -->',
'        <div class="charts-grid">',
'            <!-- Material Consumption Chart -->',
'            <div class="chart-card">',
'                <div class="chart-header">',
'                    <div>',
'                        <div class="chart-title">',
'                            <i class="fas fa-chart-pie" style="margin-right: 8px; color: #667eea;"></i>',
'                            Material Consumption by Type',
'                        </div>',
'                        <div class="chart-subtitle">Top 5 materials by consumption</div>',
'                    </div>',
'                </div>',
'                <div class="chart-container">',
'                    <canvas id="materialChart"></canvas>',
'                </div>',
'            </div>',
'            ',
'            <!-- BPO Quantity Chart -->',
'            <div class="chart-card">',
'                <div class="chart-header">',
'                    <div>',
'                        <div class="chart-title">',
'                            <i class="fas fa-chart-bar" style="margin-right: 8px; color: #764ba2;"></i>',
'                            BPO Quantities',
'                        </div>',
'                        <div class="chart-subtitle">Order quantities by BPO</div>',
'                    </div>',
'                </div>',
'                <div class="chart-container">',
'                    <canvas id="bpoChart"></canvas>',
'                </div>',
'            </div>',
'            ',
'            <!-- Size Distribution Chart -->',
'            <div class="chart-card">',
'                <div class="chart-header">',
'                    <div>',
'                        <div class="chart-title">',
'                            <i class="fas fa-chart-line" style="margin-right: 8px; color: #2ec4b6;"></i>',
'                            Size-wise Distribution',
'                        </div>',
'                        <div class="chart-subtitle">Quantity breakdown by size</div>',
'                    </div>',
'                </div>',
'                <div class="chart-container">',
'                    <canvas id="sizeChart"></canvas>',
'                </div>',
'            </div>',
'            ',
'            <!-- Item Status Chart -->',
'            <div class="chart-card">',
'                <div class="chart-header">',
'                    <div>',
'                        <div class="chart-title">',
'                            <i class="fas fa-chart-doughnut" style="margin-right: 8px; color: #f9c74f;"></i>',
'                            Material Status',
'                        </div>',
'                        <div class="chart-subtitle">Booking vs Pending</div>',
'                    </div>',
'                </div>',
'                <div class="chart-container">',
'                    <canvas id="statusChart"></canvas>',
'                </div>',
'            </div>',
'        </div>',
'        ',
'        <!-- Items Grid -->',
'        <div class="items-grid">',
'            <!-- Top Materials -->',
'            <div class="items-card">',
'                <div class="items-title">',
'                    <i class="fas fa-cubes"></i>',
'                    Top Materials by Consumption',
'                </div>',
'                <table class="items-table">',
'                    <thead>',
'                        <tr>',
'                            <th>Item Code</th>',
'                            <th>Description</th>',
'                            <th>Consumption</th>',
'                            <th>UOM</th>',
'                        </tr>',
'                    </thead>',
'                    <tbody>'';',
'    ',
'    FOR item_rec IN (',
'        SELECT * FROM (',
'            SELECT ',
'                (SELECT msi.concatenated_segments FROM apps.mtl_system_items_kfv@adf msi ',
'                 WHERE msi.inventory_item_id = pwml.INVENTORY_ITEM_ID ',
'                 AND msi.organization_id = pwml.ITEM_ORGANIZATION_ID) AS ITEM_CODE,',
'                (SELECT msi.description FROM apps.mtl_system_items@adf msi ',
'                 WHERE msi.inventory_item_id = pwml.INVENTORY_ITEM_ID ',
'                 AND msi.organization_id = pwml.ITEM_ORGANIZATION_ID) AS ITEM_DESC,',
'                pwml.ITEM_CONSUMPTION,',
'                pwml.COSTING_UOM',
'            FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'            WHERE pwml.HEADER_ID = v_header_id',
'            AND pwml.ITEM_CONSUMPTION IS NOT NULL',
'            ORDER BY pwml.ITEM_CONSUMPTION DESC',
'        ) WHERE ROWNUM <= 5',
'    ) LOOP',
'        l_html := l_html || ''',
'                        <tr>',
'                            <td>'' || item_rec.ITEM_CODE || ''</td>',
'                            <td>'' || SUBSTR(item_rec.ITEM_DESC, 1, 30) || ''...'' || ''</td>',
'                            <td>'' || item_rec.ITEM_CONSUMPTION || ''</td>',
'                            <td>'' || item_rec.COSTING_UOM || ''</td>',
'                        </tr>'';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''',
'                    </tbody>',
'                </table>',
'            </div>',
'            ',
'            <!-- Size Summary -->',
'            <div class="items-card">',
'                <div class="items-title">',
'                    <i class="fas fa-ruler"></i>',
'                    Size-wise Summary',
'                </div>',
'                <table class="items-table">',
'                    <thead>',
'                        <tr>',
'                            <th>Size</th>',
'                            <th>Quantity</th>',
'                            <th>% of Total</th>',
'                        </tr>',
'                    </thead>',
'                    <tbody>'';',
'    ',
'    DECLARE',
'        v_total_size_qty NUMBER := 0;',
'    BEGIN',
'        SELECT NVL(SUM(SIZE_QUANTITY), 0) ',
'        INTO v_total_size_qty',
'        FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D d, PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'        WHERE d.line_id = pwml.line_id',
'        AND pwml.HEADER_ID = v_header_id;',
'        ',
'        FOR size_rec IN (',
'            SELECT SIZE_VAL, SUM(SIZE_QUANTITY) as TOTAL_QTY',
'            FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D d, PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'            WHERE d.line_id = pwml.line_id',
'            AND pwml.HEADER_ID = v_header_id',
'            AND SIZE_VAL IS NOT NULL',
'            GROUP BY SIZE_VAL',
'            ORDER BY SIZE_VAL',
'        ) LOOP',
'            l_html := l_html || ''',
'                        <tr>',
'                            <td>'' || size_rec.SIZE_VAL || ''</td>',
'                            <td>'' || size_rec.TOTAL_QTY || ''</td>',
'                            <td>',
'                                <div class="progress-bar">',
'                                    <div class="progress-fill" style="width: '' || ',
'                                        ROUND((size_rec.TOTAL_QTY / v_total_size_qty * 100), 1) || ''%"></div>',
'                                </div>',
'                                '' || ROUND((size_rec.TOTAL_QTY / v_total_size_qty * 100), 1) || ''%',
'                            </td>',
'                        </tr>'';',
'        END LOOP;',
'    END;',
'    ',
'    l_html := l_html || ''',
'                    </tbody>',
'                </table>',
'            </div>',
'        </div>',
'    </div>',
'    ',
'    <script>',
'        // Material Consumption Chart',
'        new Chart(document.getElementById(''''materialChart''''), {',
'            type: ''''pie'''',',
'            data: {',
'                labels: ['';',
'    ',
'    FOR item_rec IN (',
'        SELECT * FROM (',
'            SELECT ',
'                (SELECT msi.concatenated_segments FROM apps.mtl_system_items_kfv@adf msi ',
'                 WHERE msi.inventory_item_id = pwml.INVENTORY_ITEM_ID ',
'                 AND msi.organization_id = pwml.ITEM_ORGANIZATION_ID) AS ITEM_CODE,',
'                SUM(pwml.ITEM_CONSUMPTION * pwml.ITEM_BOM_REQ_QTY) as TOTAL_CONSUMPTION',
'            FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'            WHERE pwml.HEADER_ID = v_header_id',
'            AND pwml.ITEM_CONSUMPTION IS NOT NULL',
'            GROUP BY pwml.INVENTORY_ITEM_ID, pwml.ITEM_ORGANIZATION_ID',
'            ORDER BY TOTAL_CONSUMPTION DESC',
'        ) WHERE ROWNUM <= 5',
'    ) LOOP',
'        l_html := l_html || '''''''' || item_rec.ITEM_CODE || '''''','';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''],',
'                datasets: [{',
'                    data: ['';',
'    ',
'    FOR item_rec IN (',
'        SELECT * FROM (',
'            SELECT SUM(pwml.ITEM_CONSUMPTION * pwml.ITEM_BOM_REQ_QTY) as TOTAL_CONSUMPTION',
'            FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'            WHERE pwml.HEADER_ID = v_header_id',
'            AND pwml.ITEM_CONSUMPTION IS NOT NULL',
'            GROUP BY pwml.INVENTORY_ITEM_ID, pwml.ITEM_ORGANIZATION_ID',
'            ORDER BY TOTAL_CONSUMPTION DESC',
'        ) WHERE ROWNUM <= 5',
'    ) LOOP',
'        l_html := l_html || item_rec.TOTAL_CONSUMPTION || '','';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''],',
'                    backgroundColor: [''''#4361ee'''', ''''#7209b7'''', ''''#2ec4b6'''', ''''#f9c74f'''', ''''#f94144'''']',
'                }]',
'            },',
'            options: { responsive: true, maintainAspectRatio: false }',
'        });',
'        ',
'        // BPO Chart',
'        new Chart(document.getElementById(''''bpoChart''''), {',
'            type: ''''bar'''',',
'            data: {',
'                labels: ['';',
'    ',
'    FOR bpo_rec IN (',
'        SELECT BPO_NUMBER, FINAL_ORDER_QUANTITY',
'        FROM PWC_ONT_WVN_MASTER_BOM_BPO_L ',
'        WHERE HEADER_ID = v_header_id',
'        AND ROWNUM <= 5',
'        ORDER BY FINAL_ORDER_QUANTITY DESC',
'    ) LOOP',
'        l_html := l_html || '''''''' || bpo_rec.BPO_NUMBER || '''''','';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''],',
'                datasets: [{',
'                    label: ''''Order Quantity'''',',
'                    data: ['';',
'    ',
'    FOR bpo_rec IN (',
'        SELECT FINAL_ORDER_QUANTITY',
'        FROM PWC_ONT_WVN_MASTER_BOM_BPO_L ',
'        WHERE HEADER_ID = v_header_id',
'        AND ROWNUM <= 5',
'        ORDER BY FINAL_ORDER_QUANTITY DESC',
'    ) LOOP',
'        l_html := l_html || bpo_rec.FINAL_ORDER_QUANTITY || '','';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''],',
'                    backgroundColor: ''''#764ba2''''',
'                }]',
'            },',
'            options: { responsive: true, maintainAspectRatio: false }',
'        });',
'        ',
'        // Size Chart',
'        new Chart(document.getElementById(''''sizeChart''''), {',
'            type: ''''line'''',',
'            data: {',
'                labels: ['';',
'    ',
'    FOR size_rec IN (',
'        SELECT SIZE_VAL, SUM(SIZE_QUANTITY) as TOTAL_QTY',
'        FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D d, PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'        WHERE d.line_id = pwml.line_id',
'        AND pwml.HEADER_ID = v_header_id',
'        AND SIZE_VAL IS NOT NULL',
'        GROUP BY SIZE_VAL',
'        ORDER BY SIZE_VAL',
'    ) LOOP',
'        l_html := l_html || '''''''' || size_rec.SIZE_VAL || '''''','';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''],',
'                datasets: [{',
'                    label: ''''Quantity'''',',
'                    data: ['';',
'    ',
'    FOR size_rec IN (',
'        SELECT SUM(SIZE_QUANTITY) as TOTAL_QTY',
'        FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D d, PWC_ONT_WVN_MASTER_BOM_ITEMS_L pwml',
'        WHERE d.line_id = pwml.line_id',
'        AND pwml.HEADER_ID = v_header_id',
'        AND SIZE_VAL IS NOT NULL',
'        GROUP BY SIZE_VAL',
'        ORDER BY SIZE_VAL',
'    ) LOOP',
'        l_html := l_html || size_rec.TOTAL_QTY || '','';',
'    END LOOP;',
'    ',
'    l_html := l_html || ''],',
'                    borderColor: ''''#2ec4b6'''',',
'                    tension: 0.4',
'                }]',
'            },',
'            options: { responsive: true, maintainAspectRatio: false }',
'        });',
'        ',
'        // Status Chart',
'        new Chart(document.getElementById(''''statusChart''''), {',
'            type: ''''doughnut'''',',
'            data: {',
'                labels: [''''Booked'''', ''''Pending''''],',
'                datasets: [{',
'                    data: ['';',
'    ',
'    DECLARE',
'        v_booked NUMBER := 0;',
'        v_pending NUMBER := 0;',
'    BEGIN',
'        SELECT NVL(SUM(ITEM_BOOKED_PRCNT), 0), ',
'               NVL(SUM(ITEM_PENDING_BOOKING_PRCNT), 0)',
'        INTO v_booked, v_pending',
'        FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L ',
'        WHERE HEADER_ID = v_header_id;',
'        ',
'        l_html := l_html || v_booked || '', '' || v_pending;',
'    END;',
'    ',
'    l_html := l_html || ''],',
'                    backgroundColor: [''''#2ec4b6'''', ''''#f94144'''']',
'                }]',
'            },',
'            options: { responsive: true, maintainAspectRatio: false }',
'        });',
'    </script>'';',
'    ',
'    l_count := 1;',
'    ',
'    IF l_count = 0 THEN',
'        l_html := ''',
'        <div class="error-container">',
unistr('            <div class="error-icon">\D83D\DCE6</div>'),
'            <h2 class="error-title">BOM Dashboard</h2>',
'            <p class="error-message">No data found for HEADER #'' || v_header_id || ''</p>',
'            <div class="error-detail">',
'                Verify the header ID or contact administrator',
'            </div>',
'        </div>'';',
'    END IF;',
'    ',
'    RETURN l_html;',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''<div class="error-container">',
unistr('                    <div class="error-icon">\26A0\FE0F</div>'),
'                    <h2 class="error-title">System Error</h2>',
'                    <p class="error-message">'' || SQLERRM || ''</p>',
'                    <div class="error-detail">Error Code: '' || SQLCODE || ''</div>',
'                </div>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_plug_required_role=>wwv_flow_imp.id(220539299808811584)
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>':APP_USER IN (''AMIR'',''HUSNAIN'')'
,p_plug_display_when_cond2=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(220244284919810891)
);
end;
/
begin
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(221385957017045404)
,p_plug_name=>'Assign BPOs'
,p_region_name=>'ig_static_BOP'
,p_parent_plug_id=>wwv_flow_imp.id(221387840467045423)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PWMB1.LINE_ID, ',
'       PWMB1.HEADER_ID, ',
'       PWMB1.SALE_ORDER_ID, ',
'       PWMB1.BPO_NUMBER, ',
'       PWMB1.CREATED_BY, ',
'       PWMB1.CREATION_DATE, ',
'       PWMB1.LAST_UPDATED_BY, ',
'       PWMB1.LAST_UPDATE_DATE, ',
'       (SELECT ooha.attribute12   FROM apps.oe_order_headers_all@adf ooha  WHERE     ooha.flow_status_code <> ''CANCELLED''        AND ooha.header_id = PWMB1.SALE_ORDER_ID        AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS FINAL_REPLACED_BPO_D, ',
'       (SELECT ooha.attribute3   FROM apps.oe_order_headers_all@adf ooha  WHERE     ooha.flow_status_code <> ''CANCELLED''        AND ooha.header_id = PWMB1.SALE_ORDER_ID        AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS CLASSIFICATION_D, ',
'       (SELECT SUM (oola.ordered_quantity)   FROM apps.oe_order_headers_all@adf ooha, apps.oe_order_lines_all@adf oola  WHERE     ooha.header_id = oola.header_id        AND ooha.flow_status_code <> ''CANCELLED''        AND ooha.header_id = PWMB1.SALE_O'
||'RDER_ID        AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS ORDER_QUANTITY_D, ',
'       (SELECT wph.retailer_dept   FROM apps.oe_order_headers_all@adf ooha, pwc_ont_wvn_precosting_h wph  WHERE     ooha.attribute4 = TO_CHAR (wph.tracking_no)        AND ooha.flow_status_code <> ''CANCELLED''        AND ooha.header_id = PWMB1.SALE_ORD'
||'ER_ID        AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS RETAILER_DEPT_D, ',
'       (SELECT wph.fit   FROM apps.oe_order_headers_all@adf ooha, pwc_ont_wvn_precosting_h wph  WHERE     ooha.attribute4 = TO_CHAR (wph.tracking_no)        AND ooha.flow_status_code <> ''CANCELLED''        AND ooha.header_id = PWMB1.SALE_ORDER_ID     '
||'   AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS FIT_D, ',
'       (SELECT wph.item_description   FROM apps.oe_order_headers_all@adf ooha, pwc_ont_wvn_precosting_h wph  WHERE     ooha.attribute4 = TO_CHAR (wph.tracking_no)        AND ooha.flow_status_code <> ''CANCELLED''        AND ooha.header_id = PWMB1.SALE_'
||'ORDER_ID        AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS USER_ITEM_DESCRIPTION_D, ',
'       (SELECT ooha.attribute7    FROM apps.oe_order_headers_all@adf ooha   WHERE     ooha.flow_status_code <> ''CANCELLED''         AND ooha.header_id = PWMB1.SALE_ORDER_ID         AND ooha.cust_po_number = PWMB1.BPO_NUMBER) AS REFERENCE_TBA_D, ',
'       PWMB1.FINAL_ORDER_QUANTITY, ',
'       PWMB1.BOM_ORDER_QUANTITY',
'FROM  PWC_ONT_WVN_MASTER_BOM_BPO_L PWMB1',
'WHERE  PWMB1.HEADER_ID=:P7_HEADER_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Assign BPOs'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
