wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(221345885195982417)
,p_name=>'P7_TRACKING_NO'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(221344236588982414)
,p_item_source_plug_id=>wwv_flow_imp.id(221344236588982414)
,p_prompt=>'Tracking No :'
,p_source=>'TRACKING_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'ADF_TRACK_NO_BOM'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT       ',
'       wph.tracking_no,       ',
'       wph.buyer_id,       ',
'       pwc_master_tracking_data_func@adf (wph.tracking_no, ''BUYER_NAME'')  customer_name,       ',
'       pwc_master_tracking_data_func@adf (wph.tracking_no, ''STYLE_NAME'')  style_name,   ',
'       pwc_master_tracking_data_func@adf (wph.tracking_no, ''STYLE_NO'')  style_no,   ',
'       sd.season_name,       ',
'       pwc_master_tracking_data_func@adf (wph.tracking_no, ''TRACKING_MODE'')  tracking_mode,       ',
'       pwc_master_tracking_data_func@adf (wph.tracking_no, ''TRACKING_MODE_DESC'')       ',
'       tracking_mode_desc,       ',
'       wph.brand_name,       ',
'       wph.buyer_agent_name,       ',
'       wph.invoicing_unit_id,       ',
'       oopv.inv_org_name invoicing_unit_name,       ',
'       wph.retailer_dept,       ',
'       sd.season_status       ',
'  FROM pwc_ont_wvn_precosting_h wph, pwc_mt_season_details_d sd,     ',
'       inv_org_ou_pwc_v@adf oopv     ',
' WHERE wph.tracking_no IS NOT NULL       ',
'       AND oopv.organization_id = wph.invoicing_unit_id        ',
'       AND sd.tracking_no = wph.tracking_no       ',
'       AND sd.season_status = ''Open''       ',
'       AND wph.tracking_no NOT IN (SELECT NVL (bom.tracking_no, ''N/A'')       ',
'                                     FROM pwc_ont_wvn_master_bom_h bom)'))
,p_cSize=>30
,p_colspan=>4
,p_read_only_when=>'P7_TRACKING_NO'
,p_read_only_when_type=>'ITEM_IS_NOT_NULL'
,p_field_template=>wwv_flow_imp.id(220419459940811080)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'DIALOG'
,p_attribute_02=>'NO_FETCH'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_07=>'TRACKING NO :'
,p_attribute_08=>'950'
,p_attribute_09=>'450'
,p_attribute_10=>'BUYER_AGENT_NAME:P7_BUYER_AGENT_NAME,BRAND_NAME:P7_BRAND'
);
