wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(224735742233825416)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'HEADER_ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   v_header_id   NUMBER;',
'   v_bom_number  NUMBER;',
'   v_user_id     NUMBER;',
'BEGIN',
'   /* Generate new HEADER_ID & BOM_NUMBER */',
'   SELECT NVL(MAX(header_id), 0) + 1,',
'          NVL(MAX(TO_NUMBER(bom_number)), 0) + 1',
'     INTO v_header_id,',
'          v_bom_number',
'     FROM PWC_ONT_WVN_MASTER_BOM_H;',
'',
'   /* Set Page Items */',
'   :P7_HEADER_ID  := v_header_id;',
'   :P7_BOM_NUMBER := v_bom_number;',
'',
'   /* Get APEX User ID */',
'   BEGIN',
'      SELECT user_id',
'        INTO v_user_id',
'        FROM APEX_230200.WWV_FLOW_USERS',
'       WHERE user_name = :APP_USER;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         v_user_id := NULL;',
'   END;',
'',
'   :P7_CREATED_BY := v_user_id;',
'',
'   /* Insert into Header Table */',
'   INSERT INTO PWC_ONT_WVN_MASTER_BOM_H',
'   (',
'      HEADER_ID,',
'      BOM_NUMBER,',
'      BOM_DATE,',
'      TRACKING_NO,',
'      RETAILER_DEPT,',
'      COPIED_FROM_BOM,',
'      INVOICING_UNIT_ID,',
'      CREATED_BY,',
'      CREATION_DATE,',
'      BUYER_ID,',
'      PS_CODE,',
'      TXN_MESSAGE',
'   )',
'   VALUES',
'   (',
'      v_header_id,',
'      v_bom_number,',
'      :P7_BOM_DATE,',
'      :P7_TRACKING_NO,',
'      :P7_RETAILER_DEPT,',
'      :P7_COPIED_FROM_BOM,',
'      :P7_INVOICING_UNIT_ID,',
'      v_user_id,',
'      SYSDATE,',
'      :P7_BUYER_ID,',
'      :P7_PS_CODE,',
'      ''BOM CREATED''',
'   );',
'',
'   apex_application.g_print_success_message := ''BOM created successfully. BOM No: '' || v_bom_number;',
'',
'END;',
'',
'',
'',
'',
'',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'HAVE SOME ERROR.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(221355873946982435)
,p_process_when=>'P7_HEADER_ID'
,p_process_when_type=>'ITEM_IS_NULL'
,p_internal_uid=>110168117076981140
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(225293805443026620)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(221385957017045404)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign BPOs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'CASE :APEX$ROW_STATUS',
'WHEN ''C'' THEN',
'         INSERT INTO PWC_ONT_WVN_MASTER_BOM_BPO_L ',
'                (LINE_ID, ',
'                HEADER_ID, ',
'                SALE_ORDER_ID, ',
'                BPO_NUMBER,',
'                 FINAL_ORDER_QUANTITY, ',
'                 BOM_ORDER_QUANTITY ,         ',
'                 CREATED_BY,',
'                 CREATION_DATE,',
'                 LAST_UPDATED_BY',
'                -- LAST_UPDATE_DATE',
'                )',
'                ',
'         VALUES ',
'                (NULL, ',
'                :P7_HEADER_ID, ',
'                :SALE_ORDER_ID, ',
'                :BPO_NUMBER, ',
'                 NVL(:FINAL_ORDER_QUANTITY,0), ',
'                 NVL(:BOM_ORDER_QUANTITY,:FINAL_ORDER_QUANTITY),',
'                 723155,',
'                 SYSDATE,',
'                 723155',
'                 --:LAST_UPDATE_DATE',
'                )',
'         ',
'         RETURNING LINE_ID INTO :LINE_ID;',
'',
'WHEN ''U'' THEN',
'         UPDATE PWC_ONT_WVN_MASTER_BOM_BPO_L',
'         SET HEADER_ID            = :P7_HEADER_ID,',
'             SALE_ORDER_ID        = :SALE_ORDER_ID,',
'             BPO_NUMBER           = :BPO_NUMBER,',
'             FINAL_ORDER_QUANTITY = :FINAL_ORDER_QUANTITY,',
'             BOM_ORDER_QUANTITY   = :BOM_ORDER_QUANTITY',
'         WHERE LINE_ID = :LINE_ID;',
'',
'WHEN ''D'' THEN',
'         DELETE FROM PWC_ONT_WVN_MASTER_BOM_BPO_L',
'         WHERE LINE_ID = :LINE_ID;',
'END CASE;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      RAISE_APPLICATION_ERROR(-20010,''ROWID Process Error: '' || SQLERRM );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Something Error..'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Records Saved Successfully'
,p_internal_uid=>110726180286182344
);
end;
