wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(133001880612926932)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(124202270056457010)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'M FILL MATERIAL ITEM'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  CASE :APEX$ROW_STATUS',
'    /* ========= INSERT ========= */',
'    WHEN ''C'' THEN',
'      INSERT INTO PWC_ONT_WVN_MASTER_BOM_ITEMS_L',
'      (HEADER_ID,ITEM_TYPE, PURCHASE_TYPE, ITEM_PREFIX, INVENTORY_ITEM_ID, SUPPLIER_NOMINATION, ITEM_SUPP_NAME, ITEM_REMARKS,',
'       UOM_CONV_RATE, ITEM_CONSUMPTION, ITEM_WASTAGE,ITEM_BOM_REQ_QTY,ITEM_BOOKING_PRCNT, ITEM_ADDITIONAL_QTY,',
'       ITEM_ACTUAL_PR_QTY, ITEM_BOOKED_PRCNT, ITEM_TOTAL_BOOKED_QTY, ITEM_PENDING_BOOKING_PRCNT, ITEM_PENDING_BOOKING_QTY,',
'       ITEM_PRICE_PER_UNIT, ITEM_TOTAL_VALUE, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE,',
'       CHILD_STYLE_NO, PRODUCTION_AREA, ITEM_ORGANIZATION_ID, PRODUCT_CLASSIFICATION, REQ_MATERIAL_FLAG,',
'       REQ_NEED_BY_DATE, REQ_EXCESS_BUY_REASON, REQ_CURRENCY, NON_INVENTORY_DESCRIPTION, PRECOSTING_ITEM_FLAG,',
'       INVENTORY_ITEM_FLAG, COSTING_UOM, PROCUREMENT_UOM, POC_ITEM_PRICE_PER_UNIT, POC_ITEM_CONSUMPTION,',
'       POC_UOM_CONV_RATE, POC_COST_PER_PIECE, GARMENT_QTY, PRE_POD_GSM, CONE_CONSUMPTION, ITEM_STATUS,',
'       SHRINKAGE_LENGTH, SHRINKAGE_WIDTH, REQUIRED_WIDTH, SIZE_WISE_MARKING, M2_ORDER_LINE_ID,',
'       M2_JOB_NAME, M2_ITEM_RATE, TBC_POST, TBC_TRACKING_NO, SIZE_VALUE, SUPPLIER_FLAG)',
'      VALUES',
'      (:HEADER_ID, :ITEM_TYPE, :PURCHASE_TYPE, :ITEM_PREFIX, :INVENTORY_ITEM_ID, :SUPPLIER_NOMINATION,',
'       :ITEM_SUPP_NAME, :ITEM_REMARKS, NVL(:UOM_CONV_RATE,0), NVL(:ITEM_CONSUMPTION,0), NVL(:ITEM_WASTAGE,0),',
'       NVL(:ITEM_CONSUMPTION,0) * NVL(:GARMENT_QTY,0), /*NVL(:ITEM_BOM_REQ_QTY,0),*/',
'       NVL(:ITEM_BOOKING_PRCNT,0), NVL(:ITEM_ADDITIONAL_QTY,0),NVL(:ITEM_ACTUAL_PR_QTY,0),',
'       NVL(:ITEM_BOOKED_PRCNT,0), NVL(:ITEM_TOTAL_BOOKED_QTY,0),',
'       NVL(:ITEM_PENDING_BOOKING_PRCNT,0), NVL(:ITEM_PENDING_BOOKING_QTY,0), NVL(:ITEM_PRICE_PER_UNIT,0), NVL(:ITEM_TOTAL_VALUE,0),',
'       :CREATED_BY, :CREATION_DATE, :LAST_UPDATED_BY, :LAST_UPDATE_DATE, :CHILD_STYLE_NO, :PRODUCTION_AREA, :ITEM_ORGANIZATION_ID,',
'       :PRODUCT_CLASSIFICATION, NVL(:REQ_MATERIAL_FLAG,''Y''), :REQ_NEED_BY_DATE, :REQ_EXCESS_BUY_REASON, :REQ_CURRENCY,',
'       :NON_INVENTORY_DESCRIPTION, :PRECOSTING_ITEM_FLAG, :INVENTORY_ITEM_FLAG, :COSTING_UOM, :PROCUREMENT_UOM,',
'       NVL(:POC_ITEM_PRICE_PER_UNIT,0), NVL(:POC_ITEM_CONSUMPTION,0), NVL(:POC_UOM_CONV_RATE,0), NVL(:POC_COST_PER_PIECE,0),',
'       NVL(:GARMENT_QTY,0), NVL(:PRE_POD_GSM,0), NVL(:CONE_CONSUMPTION,0), :ITEM_STATUS,NVL(:SHRINKAGE_LENGTH,0), ',
'       NVL(:SHRINKAGE_WIDTH,0), NVL(:REQUIRED_WIDTH,0), NVL(:SIZE_WISE_MARKING,''N''), :M2_ORDER_LINE_ID,',
'       :M2_JOB_NAME, NVL(:M2_ITEM_RATE,0.1), :TBC_POST, :TBC_TRACKING_NO, :SIZE_VALUE, :SUPPLIER_FLAG)',
'       ',
'      RETURNING LINE_ID INTO :LINE_ID;',
'',
'    /* ========= UPDATE ========= */',
'    WHEN ''U'' THEN',
'      UPDATE PWC_ONT_WVN_MASTER_BOM_ITEMS_L',
'',
'      SET ITEM_TYPE                     = :ITEM_TYPE,',
'          PURCHASE_TYPE                 = :PURCHASE_TYPE,',
'          ITEM_PREFIX                   = :ITEM_PREFIX,',
'          INVENTORY_ITEM_ID             = :INVENTORY_ITEM_ID,',
'          SUPPLIER_NOMINATION           = :SUPPLIER_NOMINATION,',
'          ITEM_SUPP_NAME                = :ITEM_SUPP_NAME,',
'          ITEM_REMARKS                  = :ITEM_REMARKS,',
'          UOM_CONV_RATE                 = NVL(:UOM_CONV_RATE,0),',
'          ITEM_CONSUMPTION              = :ITEM_CONSUMPTION,',
'          ITEM_WASTAGE                  = NVL(:ITEM_WASTAGE,0),',
'          ITEM_BOM_REQ_QTY              = NVL(:ITEM_CONSUMPTION,0) * NVL(:GARMENT_QTY,0),   /*NVL(:ITEM_BOM_REQ_QTY,0),*/',
'          ITEM_BOOKING_PRCNT            = NVL(:ITEM_BOOKING_PRCNT,0),',
'          ITEM_ADDITIONAL_QTY           = NVL(:ITEM_ADDITIONAL_QTY,0),',
'          ITEM_ACTUAL_PR_QTY            = NVL(:ITEM_CONSUMPTION,0) * NVL(:GARMENT_QTY,0),   /*NVL(:ITEM_ACTUAL_PR_QTY,0),*/',
'          ITEM_BOOKED_PRCNT             = NVL(:ITEM_BOOKED_PRCNT,0),',
'          ITEM_TOTAL_BOOKED_QTY         = NVL(:ITEM_TOTAL_BOOKED_QTY,0),',
'          ITEM_PENDING_BOOKING_PRCNT    = NVL(:ITEM_PENDING_BOOKING_PRCNT,0),',
'          ITEM_PENDING_BOOKING_QTY      = NVL(:ITEM_PENDING_BOOKING_QTY,0),',
'          ITEM_PRICE_PER_UNIT           = NVL(:ITEM_PRICE_PER_UNIT,0),',
'          ITEM_TOTAL_VALUE              = NVL(:ITEM_TOTAL_VALUE,0),',
'          CHILD_STYLE_NO                = :CHILD_STYLE_NO,',
'          PRODUCTION_AREA               = :PRODUCTION_AREA,',
'          ITEM_ORGANIZATION_ID          = :ITEM_ORGANIZATION_ID,',
'          PRODUCT_CLASSIFICATION        = :PRODUCT_CLASSIFICATION,',
'          REQ_MATERIAL_FLAG             = :REQ_MATERIAL_FLAG,',
'          REQ_NEED_BY_DATE              = :REQ_NEED_BY_DATE,',
'          REQ_EXCESS_BUY_REASON         = :REQ_EXCESS_BUY_REASON,',
'          REQ_CURRENCY                  = NVL(:REQ_CURRENCY,''PKR''),',
'          NON_INVENTORY_DESCRIPTION     = :NON_INVENTORY_DESCRIPTION,',
'          PRECOSTING_ITEM_FLAG          = :PRECOSTING_ITEM_FLAG,',
'          INVENTORY_ITEM_FLAG           = :INVENTORY_ITEM_FLAG,',
'          COSTING_UOM                   = :COSTING_UOM,',
'          PROCUREMENT_UOM               = :PROCUREMENT_UOM,',
'          POC_ITEM_PRICE_PER_UNIT       = NVL(:POC_ITEM_PRICE_PER_UNIT,0),',
'          POC_ITEM_CONSUMPTION          = NVL(:POC_ITEM_CONSUMPTION,0),',
'          POC_UOM_CONV_RATE             = NVL(:POC_UOM_CONV_RATE,0),',
'          POC_COST_PER_PIECE            = NVL(:POC_COST_PER_PIECE,0),',
'          GARMENT_QTY                   = NVL(:GARMENT_QTY,0),',
'          PRE_POD_GSM                   = NVL(:PRE_POD_GSM,0),',
'          CONE_CONSUMPTION              = NVL(:CONE_CONSUMPTION,0),',
'          ITEM_STATUS                   = :ITEM_STATUS,',
'          SHRINKAGE_LENGTH              = NVL(:SHRINKAGE_LENGTH,0),',
'          SHRINKAGE_WIDTH               = NVL(:SHRINKAGE_WIDTH,0),',
'          REQUIRED_WIDTH                = NVL(:REQUIRED_WIDTH,0),',
'          SIZE_WISE_MARKING             = NVL(:SIZE_WISE_MARKING,''N''),',
'          M2_ORDER_LINE_ID              = :M2_ORDER_LINE_ID,',
'          M2_JOB_NAME                   = :M2_JOB_NAME,',
'          M2_ITEM_RATE                  = :M2_ITEM_RATE,',
'          TBC_POST                      = :TBC_POST,',
'          TBC_TRACKING_NO               = :TBC_TRACKING_NO,',
'          SIZE_VALUE                    = :SIZE_VALUE,',
'          SUPPLIER_FLAG                 = :SUPPLIER_FLAG,',
'          LAST_UPDATED_BY               = :LAST_UPDATED_BY,',
'          LAST_UPDATE_DATE              = sysdate---:LAST_UPDATE_DATE',
'      WHERE LINE_ID                     = :LINE_ID;',
'',
'    /* ========= DELETE ========= */',
'    WHEN ''D'' THEN',
'      DELETE FROM PWC_ONT_WVN_MASTER_BOM_ITEMS_L',
'       WHERE LINE_ID      = :LINE_ID;',
'',
'  END CASE;',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    RAISE_APPLICATION_ERROR(',
'      -20010,',
'      ''Manual Row Process Error: '' || SQLERRM );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Something Error'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Records Saved Successfully'
,p_internal_uid=>133001880612926932
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(133001547522926929)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(131873943592157348)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'M_BPO/GENERIC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'        DECLARE',
'            l_exists NUMBER;',
'            l_dup_count NUMBER := 0;',
'        BEGIN',
'        /* ================= INSERT ================= */',
'        IF :APEX$ROW_STATUS = ''C'' THEN',
'        FOR r IN (',
'        /* ================= MASTER STYLE ================= */',
'          SELECT sdh.inventory_item_id,',
'                           sdh.sales_order_id,',
'                           sdh.country,',
'                           sdl.garment_inseam,',
'                           sdl.garment_size,',
'                           SUM(sdl.garment_size_qty) garment_size_qty,',
'                           sdh.dcpo_name,',
'                           REGEXP_SUBSTR(msib.description, ''[^:]+'', 1, 3) colour,',
'                           ''N/A'' child_style_no,',
'                           ooha.cust_po_number || ''/'' || oola.line_number bpo_line_number,',
'                           oola.attribute8 product_classification,',
'                           ooha.attribute3 classification,',
'                           ooha.attribute7 reference_tba,',
'                           sdh.ex_factory_date',
'                      FROM pwc_ont_wvn_sizewise_details_l sdl,',
'                           pwc_ont_wvn_sizewise_details_h sdh,',
'                           apps.mtl_system_items@adf msib,',
'                           apps.oe_order_headers_all@adf ooha,',
'                           apps.oe_order_lines_all@adf oola,',
'                           pwc_ont_wvn_master_bom_bpo_l mbbla',
'                     WHERE sdh.header_id = sdl.header_id',
'                       AND ooha.header_id = oola.header_id',
'                       AND oola.inventory_item_id = sdh.inventory_item_id',
'                       AND oola.ordered_quantity <> 0',
'                       AND NVL(oola.attribute2, ''No'') = ''No''',
'                       AND UPPER(NVL(oola.attribute6, ''Active'')) = ''ACTIVE''',
'                       --AND oola.line_id = sdh.sales_order_line_id      N0t Value Saved in pwc_ont_wvn_sizewise_details_h(sales_order_line_id)',
'                       AND ooha.header_id = mbbla.sale_order_id',
'                       AND msib.organization_id = :P7_INVOICING_UNIT_ID',
'                       AND mbbla.sale_order_id = sdh.sales_order_id',
'                       AND msib.inventory_item_id = sdh.inventory_item_id',
'                       AND NVL(sdl.garment_size_qty, 0) > 0',
'                       AND :P7_TRACKING_MODE = ''Master Style''',
'                       AND mbbla.header_id = :P7_HEADER_ID',
'                       AND oola.attribute8 = NVL(:PRODUCT_CLASSIFICATION, oola.attribute8)',
'                     GROUP BY sdh.inventory_item_id,',
'                              sdh.sales_order_id,',
'                              sdh.country,',
'                              sdl.garment_inseam,',
'                              sdl.garment_size,',
'                              sdh.dcpo_name,',
'                              REGEXP_SUBSTR(msib.description,''[^:]+'', 1, 3),',
'                              ooha.cust_po_number,',
'                              oola.line_number,',
'                              oola.attribute8,',
'                              ooha.attribute3,',
'                              ooha.attribute7,',
'                              sdh.ex_factory_date',
'',
'                     UNION ALL',
'',
'                     SELECT sdh.inventory_item_id,',
'                            sdh.sales_order_id,',
'                            sdh.country,',
'                            sdl.garment_inseam,',
'                            sdl.garment_size,',
'                            SUM(sdl.garment_size_qty),',
'                            sdh.dcpo_name,',
'                            REGEXP_SUBSTR(msib.description, ''[^:]+'', 1, 3),',
'                            NVL(oola.attribute4, ''N/A''),',
'                            ooha.cust_po_number || ''/'' || oola.line_number,',
'                            oola.attribute8,',
'                            ooha.attribute3,',
'                            ooha.attribute7,',
'                            sdh.ex_factory_date',
'                       FROM pwc_ont_wvn_sizewise_details_l sdl,',
'                            pwc_ont_wvn_sizewise_details_h sdh,',
'                            apps.mtl_system_items@adf msib,',
'                            apps.oe_order_headers_all@adf ooha,',
'                            apps.oe_order_lines_all@adf oola,',
'                            pwc_ont_wvn_master_bom_bpo_l mbbla',
'                      WHERE sdh.header_id = sdl.header_id',
'                        AND ooha.header_id = oola.header_id',
'                        AND oola.inventory_item_id = sdh.inventory_item_id',
'                        AND oola.ordered_quantity <> 0',
'                        AND NVL(oola.attribute2, ''No'') = ''No''',
'                        AND UPPER(NVL(oola.attribute6, ''Active'')) = ''ACTIVE''',
'                        --AND oola.line_id = sdh.sales_order_line_id             --    N0t Value Saved in pwc_ont_wvn_sizewise_details_h(sales_order_line_id)',
'                        AND ooha.header_id = mbbla.sale_order_id',
'                        AND msib.organization_id = :P7_INVOICING_UNIT_ID',
'                        AND mbbla.sale_order_id = sdh.sales_order_id',
'                        AND msib.inventory_item_id = sdh.inventory_item_id',
'                        AND NVL(sdl.garment_size_qty, 0) > 0',
'                        AND :P7_TRACKING_MODE = ''Child Style''',
'                        AND mbbla.header_id = :P7_HEADER_ID',
'                        AND oola.attribute4 = :P7_STYLE_NO',
'                        AND oola.attribute8 = NVL(:PRODUCT_CLASSIFICATION, oola.attribute8)',
'                     GROUP BY sdh.inventory_item_id,',
'                              sdh.sales_order_id,',
'                              sdh.country,',
'                              sdl.garment_inseam,',
'                              sdl.garment_size,',
'                              sdh.dcpo_name,',
'                              REGEXP_SUBSTR(msib.description,''[^:]+'', 1, 3),',
'                              oola.attribute4,',
'                              ooha.cust_po_number,',
'                              oola.line_number,',
'                              oola.attribute8,',
'                              ooha.attribute3,',
'                              ooha.attribute7,',
'                              sdh.ex_factory_date',
'',
'        ) LOOP',
'',
'',
'        /* ================= DUPLICATE CHECK ================= */',
'',
'        SELECT COUNT(*)',
'        INTO l_exists',
'        FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'',
'        WHERE LINE_ID = :LINE_ID',
'        AND INVENTORY_ITEM_ID = r.inventory_item_id',
'        AND SALE_ORDER_ID = r.sales_order_id',
'        AND SIZE_VAL = r.garment_size',
'        AND INSEAM_VAL = r.garment_inseam;',
'',
'',
'',
'        /* ================= INSERT ================= */',
'',
'        IF l_exists = 0 THEN',
'',
'        INSERT INTO PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'        (',
'        LINE_ID,',
'        INVENTORY_ITEM_ID,',
'        SALE_ORDER_ID,',
'        BPO_LINE_NO,',
'        CHILD_STYLE_NO,',
'        COUNTRY,',
'        DCPO_NAME,',
'        COLOUR,',
'        INSEAM_VAL,',
'        SIZE_VAL,',
'        SIZE_QUANTITY,',
'        CREATED_BY,',
'        CREATION_DATE,',
'        LAST_UPDATED_BY,',
'        LAST_UPDATE_DATE,',
'        PRODUCT_CLASSIFICATION,',
'        SIZE_ASSIGNMENT',
'        )',
'',
'        VALUES',
'        (',
'        :LINE_ID,',
'        r.inventory_item_id,',
'        r.sales_order_id,',
'        r.bpo_line_number,',
'        r.child_style_no,',
'        r.country,',
'        r.dcpo_name,',
'        r.colour,',
'        r.garment_inseam,',
'        r.garment_size,',
'        r.garment_size_qty,',
'        723155,',
'        SYSDATE,',
'        723155,',
'        SYSDATE,',
'        r.product_classification,',
'        ''N''',
'        );',
'',
'        ELSE',
'',
'        l_dup_count := l_dup_count + 1;',
'',
'        END IF;',
'',
'',
'        END LOOP;',
'',
'',
'        /* ================= DUPLICATE MESSAGE ================= */',
'',
'        IF l_dup_count > 0 THEN',
'',
'        APEX_ERROR.ADD_ERROR(',
'',
'        p_message => ''Duplicate Records Found : ''||l_dup_count,',
'        p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'',
'        );',
'',
'        END IF;',
'',
'',
'',
'        /* ================= UPDATE ================= */',
'',
'        ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'        UPDATE PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'',
'        SET SIZE_ASSIGNMENT = :SIZE_ASSIGNMENT,',
'        LAST_UPDATED_BY = 723155,',
'        LAST_UPDATE_DATE = SYSDATE',
'',
'        WHERE DETAIL_ID = :DETAIL_ID;',
'',
'',
'',
'        /* ================= DELETE ================= */',
'',
'        ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'        IF :SIZE_ASSIGNMENT = ''N'' THEN',
'',
'        DELETE FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'        WHERE SIZE_ASSIGNMENT=''N''',
'        AND DETAIL_ID = :DETAIL_ID;',
'',
'        ELSE',
'',
'                APEX_ERROR.ADD_ERROR(',
'                p_message => ''<span class="myError">This Record Cannot Be Deleted Because Size Assigned</span>'',',
'                p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'                );',
'        END IF;',
'',
'        END IF;',
'',
'        END;',
'',
'',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_required_patch=>wwv_flow_imp.id(220244284919810891)
,p_internal_uid=>133001547522926929
);
