begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(145989410295680848)
,p_process_sequence=>60
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Carton/Poly'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_count NUMBER := 0;',
'BEGIN',
'',
'     FOR r IN (',
'    SELECT DISTINCT',
'      msib.concatenated_segments         AS ORDERED_ITEM,',
'      msib.inventory_item_id             AS INVENTORY_ITEM_ID,',
'      CASE msib.segment3',
'         WHEN ''11'' THEN ''Local''',
'         WHEN ''21'' THEN ''Imported''',
'         ELSE ''N/A''',
'      END                                 AS STATUS,',
'      msib.description                    AS DESCRIPTION,',
'      msib.description                    AS ACC_DESC,',
'      msib.primary_unit_of_measure        AS PRIMARY_UNIT_OF_MEASURE,',
'      v.description                        AS VALUE_DESCRIPTION,',
'      msib.attribute5                     AS SUPPLIER_LEGACY_CODE,',
'      msib.segment1                        AS SEGMENT1,',
'      NULL                                 AS COLOR,',
'      ccl.consumption                      AS CONSUMPTION,',
'      (SELECT papx.full_name',
'         FROM apps.per_people_x@adf papx',
'        WHERE papx.person_id = msib.buyer_id)',
'                                           AS BUYER_NAME,',
'      msib.buyer_id                        AS BUYER_ID,',
'      msib.attribute3                       AS SUPPLIER_NAME,',
'      NULL                                  AS THREAD_LENGTH,',
'      ccl.department                        AS DEPARTMENT,',
'      NULL                                  AS THREAD_BRAND,',
'      NULL                                  AS THREAD_TKT,',
'      NULL                                  AS THREAD_TEX,',
'      NULL                                  AS THREAD_COUNT,',
'      msib.segment4                          AS SEGMENT4,',
'      NULL                                   AS THREAD_COLOR,',
'      NULL                                   AS CONE_CONSUMPTION,',
'      APPS.PWC_ITEM_STATUS_DESCRIPTION@adf(msib.segment3)',
'                                           AS ITEM_STATUS,',
'      NULL                                   AS HANGER_NO,',
'      NULL                                   AS ARTICLE_NO,',
'      NULL                                   AS ORDER_LINE_ID,',
'      NULL                                   AS JOB_M2,',
'      NULL                                   AS RATE,',
'      (SELECT pv.vendor_name',
'         FROM apps.MTML_PO_ITEM_LAST_RATE@adf lr, apps.po_vendors@adf pv',
'        WHERE pv.vendor_id = lr.vendor_id',
'          AND LR.ORGANIZATION_ID = 91',
'          AND LR.INVENTORY_ITEM_ID = msib.INVENTORY_ITEM_ID',
'          AND msib.organization_id = lr.organization_id)',
'                                           AS LAST_SUPPLIER_NAME,',
'      (SELECT NVL(MAX(LR.LAST_PUR_RATE),0)',
'         FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR',
'        WHERE LR.ORGANIZATION_ID = 91',
'          AND LR.INVENTORY_ITEM_ID = msib.INVENTORY_ITEM_ID',
'          AND msib.organization_id = lr.organization_id)',
'                                           AS LAST_PUR_RATE',
'    FROM apps.mtl_system_items_kfv@adf msib,',
'         pwc_flex_values_v@adf v,',
'         pwc_ont_wvn_cart_consumption_h cch,',
'         pwc_ont_wvn_cart_consumption_l ccl',
'    WHERE msib.organization_id = :P7_INVOICING_UNIT_ID',
'      AND msib.segment3 IN (''11'',''21'')',
'      AND msib.segment1 IN (''820'',''463'',''464'',''465'')',
'      AND msib.enabled_flag = ''Y''',
'      AND v.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''',
'      AND msib.inventory_item_status_code = ''Active''',
'      AND v.flex_value = msib.segment1',
'      AND cch.header_id = ccl.header_id',
'      AND :P7_ITEMTYPE = ''Carton/Poly''',
'      AND cch.tracking_no = :P7_TRACKING_NO',
'      AND ccl.inventory_item_id = msib.inventory_item_id',
'  ) LOOP',
'',
'    INSERT INTO PWC_ONT_WVN_MASTER_BOM_ITEMS_L',
'    (',
'      LINE_ID,',
'      HEADER_ID,',
'      ITEM_TYPE,',
'      PURCHASE_TYPE,',
'      ITEM_PREFIX,',
'      INVENTORY_ITEM_ID,',
'      SUPPLIER_NOMINATION,',
'      ITEM_SUPP_NAME,',
'      ITEM_REMARKS,',
'      UOM_CONV_RATE,',
'      ITEM_CONSUMPTION,',
'      ITEM_WASTAGE,',
'      ITEM_BOM_REQ_QTY,',
'      ITEM_BOOKING_PRCNT,',
'      ITEM_ADDITIONAL_QTY,',
'      ITEM_ACTUAL_PR_QTY,',
'      ITEM_BOOKED_PRCNT,',
'      ITEM_TOTAL_BOOKED_QTY,',
'      ITEM_PENDING_BOOKING_PRCNT,',
'      ITEM_PENDING_BOOKING_QTY,',
'      ITEM_PRICE_PER_UNIT,',
'      ITEM_TOTAL_VALUE,',
'      CREATED_BY,',
'      CREATION_DATE,',
'      LAST_UPDATED_BY,',
'      LAST_UPDATE_DATE,',
'      CHILD_STYLE_NO,',
'      PRODUCTION_AREA,',
'      ITEM_ORGANIZATION_ID,',
'      PRODUCT_CLASSIFICATION,',
'      COSTING_UOM,',
'      PROCUREMENT_UOM,',
'      POC_ITEM_PRICE_PER_UNIT,',
'      POC_ITEM_CONSUMPTION,',
'      POC_UOM_CONV_RATE,',
'      POC_COST_PER_PIECE,',
'      CONE_CONSUMPTION,',
'      ITEM_STATUS,',
'      M2_ORDER_LINE_ID,',
'      M2_JOB_NAME,',
'      M2_ITEM_RATE,',
'      TBC_TRACKING_NO',
'    )',
'    VALUES',
'    (',
'      null,',
'      :P7_HEADER_ID,',
'      :P7_ITEMTYPE,',
'      r.STATUS,',
'      r.SEGMENT1,',
'      r.INVENTORY_ITEM_ID,',
'      r.SUPPLIER_LEGACY_CODE,',
'      r.SUPPLIER_NAME,',
'      r.DESCRIPTION,',
'      NVL(r.THREAD_LENGTH,0),',
'      NVL(r.CONSUMPTION,0),',
'      0,',
'      NVL(r.CONSUMPTION,0),',
'      0,',
'      0,',
'      0,',
'      0,',
'      0,',
'      0,',
'      0,',
'      NVL(r.LAST_PUR_RATE,0),',
'      NVL(r.LAST_PUR_RATE,0)*NVL(r.CONSUMPTION,0),',
'      0,',
'      SYSDATE,',
'      0,',
'      SYSDATE,',
'      NULL,',
'      r.DEPARTMENT,',
'      :P7_INVOICING_UNIT_ID,',
'      :PRODUCT_CLASSIFICATION,',
'      r.PRIMARY_UNIT_OF_MEASURE,',
'      r.PRIMARY_UNIT_OF_MEASURE,',
'      NVL(r.LAST_PUR_RATE,0),',
'      NVL(r.CONSUMPTION,0),',
'      NVL(r.THREAD_LENGTH,0),',
'      NVL(r.CONE_CONSUMPTION,0),',
'      NVL(r.CONE_CONSUMPTION,0),',
'      r.ITEM_STATUS,',
'      r.ORDER_LINE_ID,',
'      r.JOB_M2,',
'      NVL(r.RATE,0),',
'      :P7_TRACKING_NO',
'    );',
'',
'    l_count := l_count + 1;',
'  END LOOP;',
'',
'COMMIT;',
'  :P7_INSERT_COUNT := l_count;',
'',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN NULL;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(145989158710680845)
,p_internal_uid=>145989410295680848
);
