 p_id=>8
,p_name=>'BPO/Generic Items'
,p_alias=>'BPO-GENERIC-ITEMS'
,p_page_mode=>'MODAL'
,p_step_title=>'BPO/Generic Items'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function showFeesTotal() {',
'',
'    var region = apex.region("ig_static_fmi");',
'    if (!region) {',
'        console.log("IG region not found");',
'        return;',
'    }',
'',
'    var ig$ = region.widget();',
'    var model = ig$.interactiveGrid("getViews", "grid").model;',
'',
'    var total = 0;',
'',
'    model.forEach(function (record) {',
'        var val = record.FINAL_ORDER_QUANTITY;',
'        if (!isNaN(val)) {',
'            total += Number(val);',
'        }',
'    });',
'',
'    ig$.find(".my-total-row").remove();',
'',
'    var totalRow = `',
'        <div class="my-total-row"',
'             style="padding:10px;',
'                    background:#e8f5e9;',
'                    font-weight:bold;',
'                    text-align:right;">',
'            TOTAL FINAL_ORDER_QUANTITY : ${total.toLocaleString()}',
'        </div>',
'    `;',
'',
'    ig$.append(totalRow);',
'}',
''))
,p_step_template=>wwv_flow_imp.id(220252595899810904)
,p_page_template_options=>'#DEFAULT#:ui-dialog--stretch'
,p_protection_level=>'C'
,p_page_component_map=>'21'
