wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(167496866675569447)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(228215250899140810)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BPO/Generic Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'                DECLARE',
'                    l_exists NUMBER;',
'                BEGIN',
'',
'                /* ================= INSERT / PROCESS ================= */',
'                IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'                FOR r IN (',
unistr('                    -- \D83D\DD01 YOUR SAME UNION QUERY (unchanged)'),
'                      SELECT msib.inventory_item_id,',
'                           sdh.sales_order_id,',
'                           sdh.country,',
'                           sdl.garment_inseam,',
'                           sdl.garment_size,',
'                           SUM(sdl.garment_size_qty) garment_size_qty,',
'                           sdh.dcpo_name,',
'                           REGEXP_SUBSTR(msib.description, ''[^:]+'', 1, 3) colour,',
'                           ''N/A'' child_style_no,',
'                           ooha.cust_po_number || ''/'' || oola.line_number bpo_line_number,',
'                           oola.attribute8 product_classification,',
'                           ooha.attribute3 classification,',
'                           ooha.attribute7 reference_tba,',
'                           sdh.ex_factory_date',
'                      FROM pwc_ont_wvn_sizewise_details_l sdl,',
'                           pwc_ont_wvn_sizewise_details_h sdh,',
'                           apps.mtl_system_items@adf msib,',
'                           apps.oe_order_headers_all@adf ooha,',
'                           apps.oe_order_lines_all@adf oola,',
'                           pwc_ont_wvn_master_bom_bpo_l mbbla',
'                     WHERE sdh.header_id = sdl.header_id',
'                       AND ooha.header_id = oola.header_id',
'                       AND oola.inventory_item_id = msib.inventory_item_id',
'                       AND oola.ordered_quantity <> 0',
'                       AND NVL(oola.attribute2, ''No'') = ''No''',
'                       AND UPPER(NVL(oola.attribute6, ''Active'')) = ''ACTIVE''',
'                       --AND oola.line_id = sdh.sales_order_line_id      N0t Value Saved in pwc_ont_wvn_sizewise_details_h(sales_order_line_id)',
'                       AND ooha.header_id = mbbla.sale_order_id',
'                       AND msib.organization_id = :P7_INVOICING_UNIT_ID',
'                       AND mbbla.sale_order_id = sdh.sales_order_id',
'--                       AND msib.inventory_item_id = sdh.inventory_item_id',
'                       AND NVL(sdl.garment_size_qty, 0) > 0',
'                       AND :P7_TRACKING_MODE = ''Master Style''',
'                       AND mbbla.header_id = :P7_HEADER_ID',
'                       AND oola.attribute8 = NVL(:PRODUCT_CLASSIFICATION, oola.attribute8)',
'                     GROUP BY msib.inventory_item_id,',
'                              sdh.sales_order_id,',
'                              sdh.country,',
'                              sdl.garment_inseam,',
'                              sdl.garment_size,',
'                              sdh.dcpo_name,',
'                             REGEXP_SUBSTR(msib.description,''[^:]+'', 1, 3),',
'                              ooha.cust_po_number,',
'                              oola.line_number,',
'                              oola.attribute8,',
'                              ooha.attribute3,',
'                              ooha.attribute7,',
'                              sdh.ex_factory_date',
'',
'                     UNION ALL',
'',
'                     SELECT msib.inventory_item_id,',
'                            sdh.sales_order_id,',
'                            sdh.country,',
'                            sdl.garment_inseam,',
'                            sdl.garment_size,',
'                            SUM(sdl.garment_size_qty),',
'                            sdh.dcpo_name,',
'                            REGEXP_SUBSTR(msib.description, ''[^:]+'', 1, 3),',
'                            NVL(oola.attribute4, ''N/A''),',
'                            ooha.cust_po_number || ''/'' || oola.line_number,',
'                            oola.attribute8,',
'                            ooha.attribute3,',
'                            ooha.attribute7,',
'                            sdh.ex_factory_date',
'                       FROM pwc_ont_wvn_sizewise_details_l sdl,',
'                            pwc_ont_wvn_sizewise_details_h sdh,',
'                            apps.mtl_system_items@adf msib,',
'                            apps.oe_order_headers_all@adf ooha,',
'                            apps.oe_order_lines_all@adf oola,',
'                            pwc_ont_wvn_master_bom_bpo_l mbbla',
'                      WHERE sdh.header_id = sdl.header_id',
'                        AND ooha.header_id = oola.header_id',
'                        AND oola.inventory_item_id = msib.inventory_item_id',
'                       AND oola.ordered_quantity <> 0',
'                        AND NVL(oola.attribute2, ''No'') = ''No''',
'                        AND UPPER(NVL(oola.attribute6, ''Active'')) = ''ACTIVE''',
'                        --AND oola.line_id = sdh.sales_order_line_id             --    N0t Value Saved in pwc_ont_wvn_sizewise_details_h(sales_order_line_id)',
'                        AND ooha.header_id = mbbla.sale_order_id',
'                        AND msib.organization_id = :P7_INVOICING_UNIT_ID',
'                        AND mbbla.sale_order_id = sdh.sales_order_id',
'--                        AND msib.inventory_item_id = sdh.inventory_item_id',
'                        AND NVL(sdl.garment_size_qty, 0) > 0',
'                        AND :P7_TRACKING_MODE = ''Child Style''',
'                        AND mbbla.header_id = :P7_HEADER_ID',
'                        AND oola.attribute4 = :P7_STYLE_NO',
'                        AND oola.attribute8 = NVL(:PRODUCT_CLASSIFICATION, oola.attribute8)',
'                     GROUP BY msib.inventory_item_id,',
'                              sdh.sales_order_id,',
'                              sdh.country,',
'                              sdl.garment_inseam,',
'                              sdl.garment_size,',
'                              sdh.dcpo_name,',
'                              REGEXP_SUBSTR(msib.description,''[^:]+'', 1, 3),',
'                              oola.attribute4,',
'                              ooha.cust_po_number,',
'                              oola.line_number,',
'                              oola.attribute8,',
'                              ooha.attribute3,',
'                              ooha.attribute7,',
'                              sdh.ex_factory_date',
'',
'                ) LOOP',
'',
'                /* ================= CHECK EXIST (WITHOUT QUANTITY) ================= */',
'                SELECT COUNT(*)',
'                INTO l_exists',
'                FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'                WHERE LINE_ID = :P8_LINE_ID',
'                AND INVENTORY_ITEM_ID = r.inventory_item_id',
'                AND SALE_ORDER_ID = r.sales_order_id',
'                AND SIZE_VAL = r.garment_size',
'                AND INSEAM_VAL = r.garment_inseam;',
'',
'',
'                /* ================= LOGIC ================= */',
'',
'                IF l_exists = 0 THEN',
unistr('                    -- \2705 NEW RECORD \2192 INSERT'),
'',
'                    INSERT INTO PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'                    (',
'                        LINE_ID,',
'                        INVENTORY_ITEM_ID,',
'                        SALE_ORDER_ID,',
'                        BPO_LINE_NO,',
'                        CHILD_STYLE_NO,',
'                        COUNTRY,',
'                        DCPO_NAME,',
'                        COLOUR,',
'                        INSEAM_VAL,',
'                        SIZE_VAL,',
'                        SIZE_QUANTITY,',
'                        CREATED_BY,',
'                        CREATION_DATE,',
'                        LAST_UPDATED_BY,',
'                        LAST_UPDATE_DATE,',
'                        PRODUCT_CLASSIFICATION,',
'                        SIZE_ASSIGNMENT',
'                    )',
'                    VALUES',
'                    (',
'                        :P8_LINE_ID,',
'                        r.inventory_item_id,',
'                        r.sales_order_id,',
'                        r.bpo_line_number,',
'                        r.child_style_no,',
'                        r.country,',
'                        r.dcpo_name,',
'                        r.colour,',
'                        r.garment_inseam,',
'                        r.garment_size,',
'                        r.garment_size_qty,',
'                        :CREATED_BY,',
'                        :CREATION_DATE,',
'                        :LAST_UPDATED_BY,',
'                        :LAST_UPDATE_DATE,',
'                        r.product_classification,',
'                        ''N''',
'                    );',
'',
'                ELSE',
unistr('                    -- \2705 RECORD EXIST \2192 UPDATE (ONLY IF QUANTITY DIFFERENT)'),
'',
'                    UPDATE PWC_ONT_WVN_MASTER_BOM_GENRC_D d',
'                    SET d.SIZE_QUANTITY   = r.garment_size_qty,',
'                        d.LAST_UPDATED_BY = :LAST_UPDATED_BY,',
'                        d.LAST_UPDATE_DATE = SYSDATE',
'                    WHERE d.LINE_ID = :P8_LINE_ID',
'                    AND d.INVENTORY_ITEM_ID = r.inventory_item_id',
'                    AND d.SALE_ORDER_ID = r.sales_order_id',
'                    AND d.SIZE_VAL = r.garment_size',
'                    AND d.INSEAM_VAL = r.garment_inseam',
'                    AND NVL(d.SIZE_QUANTITY,0) <> NVL(r.garment_size_qty,0);',
'',
'                END IF;',
'',
'                END LOOP;',
'',
'',
'                /* ================= UPDATE ================= */',
'                ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'                UPDATE PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'                SET SIZE_ASSIGNMENT = :SIZE_ASSIGNMENT,',
'                    LAST_UPDATED_BY = 723155,   --:LAST_UPDATED_BY,',
'                    LAST_UPDATE_DATE = SYSDATE',
'                WHERE DETAIL_ID = :DETAIL_ID;',
'',
'',
'                /* ================= DELETE ================= */',
'                ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'                IF :SIZE_ASSIGNMENT = ''N'' THEN',
'',
'                    DELETE FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'                    WHERE DETAIL_ID = :DETAIL_ID;',
'',
'                ELSE',
'                    APEX_ERROR.ADD_ERROR(',
'                        p_message => ''This Record Cannot Be Deleted Because Size Assigned'',',
'                        p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'                    );',
'                END IF;',
'',
'                END IF;',
'',
'                END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>167496866675569447
);
