'                   apps.mtl_system_items@adf msib,',
'                   apps.oe_order_headers_all@adf ooha,',
'                   apps.oe_order_lines_all@adf oola,',
'                   pwc_ont_wvn_master_bom_bpo_l mbbla',
'             WHERE sdh.header_id = sdl.header_id',
'               AND ooha.header_id = oola.header_id',
'               AND oola.inventory_item_id = msib.inventory_item_id',
'               AND oola.ordered_quantity <> 0',
'               AND NVL(oola.attribute2, ''No'') = ''No''',
'               AND UPPER(NVL(oola.attribute6, ''Active'')) = ''ACTIVE''',
'               AND ooha.header_id = mbbla.sale_order_id',
'               AND msib.organization_id = :P8_INVOICING_UNIT_ID',
'               AND mbbla.sale_order_id = sdh.sales_order_id',
'               AND NVL(sdl.garment_size_qty, 0) > 0',
'               AND :P7_TRACKING_MODE = ''Master Style''',
'               AND mbbla.header_id = :P8_HEADER_ID',
'',
'             GROUP BY msib.inventory_item_id,',
'                      sdh.sales_order_id,',
'                      sdh.country,',
'                      sdl.garment_inseam,',
'                      sdl.garment_size,',
'                      sdh.dcpo_name,',
'                      REGEXP_SUBSTR(msib.description,''[^:]+'', 1, 3),',
'                      ooha.cust_po_number,',
'                      oola.line_number,',
'                      oola.attribute8,',
'                      ooha.attribute3,',
'                      ooha.attribute7,',
'                      sdh.ex_factory_date',
'',
'        ) LOOP',
'',
'            /* ================= CHECK EXIST ================= */',
'',
'            SELECT COUNT(*)',
'            INTO l_exists',
'            FROM PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'            WHERE LINE_ID = :P8_LINE_ID',
'              AND INVENTORY_ITEM_ID = r.inventory_item_id',
'              AND SALE_ORDER_ID = r.sales_order_id',
'              AND SIZE_VAL = r.garment_size',
'              AND INSEAM_VAL = r.garment_inseam;',
'',
'            /* ================= INSERT / UPDATE ================= */',
'',
'            IF l_exists = 0 THEN',
'',
'                INSERT INTO PWC_ONT_WVN_MASTER_BOM_GENRC_D',
'                (',
'                    LINE_ID,',
'                    INVENTORY_ITEM_ID,',
'                    SALE_ORDER_ID,',
'                    BPO_LINE_NO,',
'                    CHILD_STYLE_NO,',
'                    COUNTRY,',
'                    DCPO_NAME,',
'                    COLOUR,',
'                    INSEAM_VAL,',
'                    SIZE_VAL,',
'                    SIZE_QUANTITY,',
'                    CREATED_BY,',
'                    CREATION_DATE,',
'                    LAST_UPDATED_BY,',
'                    LAST_UPDATE_DATE,',
'                    PRODUCT_CLASSIFICATION,',
'                    SIZE_ASSIGNMENT',
'                )',
'                VALUES',
'                (',
'                    :P8_LINE_ID,',
'                    r.inventory_item_id,',
'                    r.sales_order_id,',
'                    r.bpo_line_number,',
'                    r.child_style_no,',
'                    r.country,',
'                    r.dcpo_name,',
'                    r.colour,',
'                    r.garment_inseam,',
'                    r.garment_size,',
'                    r.garment_size_qty,',
'                    :CREATED_BY,',
'                    :CREATION_DATE,',
'                    :LAST_UPDATED_BY,',
'                    :LAST_UPDATE_DATE,',
