wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(119967170583411637)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch_Orders'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'CURSOR C_ORDERS IS ',
'SELECT T.TRACKING_NO',
'        FROM APEX_ADF.PWC_MT_STYLE_DETAILS_L S,',
'             APEX_ADF.PWC_MT_SEASON_DETAILS_D T',
'            ',
'       WHERE 1=1',
'         AND S.STYLE_LINE_ID = T.STYLE_LINE_ID',
'         AND T.TRACKING_NO IS NOT NULL',
'         AND S.STYLE_NUMBER = :P11_STYLE_NUMBER',
'         AND NOT EXISTS (',
'                SELECT 1',
'                  FROM APEX_ADF.PWC_ONT_WVN_PRECOSTING_H H',
'                 WHERE H.TRACKING_NO = T.TRACKING_NO',
'             )         ',
'         AND NOT EXISTS (',
'                SELECT 1',
'                  FROM MTML_M6_STYLE_GROUP_APPROVAL_L L',
'                 WHERE L.HEADER_GROUP_ID = :P11_HEADER_GROUP_ID',
'                   AND L.TRACKING_NO = T.TRACKING_NO',
'             ) ;',
'             BEGIN',
'             FOR REC IN C_ORDERS LOOP',
'             --:TRACKING_NO:=REC.TRACKING_NO;',
'            INSERT INTO MTML_M6_STYLE_GROUP_APPROVAL_L (',
'                HEADER_GROUP_ID,',
'         TRACKING_NO,        ',
'         CREATION_DATE,',
'         LAST_UPDATE_DATE',
'      )',
'      VALUES (',
'   ',
'     :P11_HEADER_GROUP_ID,',
'         REC.TRACKING_NO,         ',
'         SYSDATE,',
'         SYSDATE',
'      );',
'             --NEXT_RECORD;',
'             END LOOP;',
'             END;  '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(119966458314411630)
,p_internal_uid=>119967170583411637
);
