wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(120801052416688620)
,p_plug_name=>'Sample Lines'
,p_region_name=>'LINES_IG'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>70
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  L.LINE_ID, ',
'  L.HEADER_ID, ',
'  L.SAMPLE_LINE_CODE, ',
'  L.FABRIC_REF_NO, ',
'  L.SHRIKAGE_WARP, ',
'  L.SHRINKAGE_WEFT, ',
'  L.COMPOSITION, ',
'  L.CONSTRUCTION, ',
'  L.CUTTABLE_WIDTH_VALUE, ',
'  L.CUTTABLE_WIDTH_TYPE, ',
'  L.WEIGHT_VALUE, ',
'  L.WEIGHT_TYPE, ',
'  L.FABRIC_BATCH_ROLL_NO, ',
'  L.SAMPLE_FABRIC_ROLL, ',
'  L.FINISH_GARMENTS_COLOR, ',
'  L.COLOR_NUMBER, ',
'  L.WASH_NAME, ',
'  L.FTD_FDS_RECEIVED_DATE, ',
'  L.TARGET_SAMPLE_SUBMISSION_DATE, ',
'  L.REQUISITION_DATE_TIME, ',
'  L.FINAL_SAMPLE_CODE, ',
'  L.SAMPLE_LINE_STATUS, ',
'  L.FG_ITEM_CODE, ',
'  L.WASH_SAMPLE_CODE, ',
'  L.TARGET_SUBMISSION_DATE, ',
'  L.TOTAL_SAMPLE_QUANTITY, ',
'  L.EXPECTED_ORDER_QUANTITY, ',
'  L.FABRIC_REQUEST_DATE, ',
'  L.FABRIC_SEND_DATE, ',
'  L.FABRIC_RECVD_DATE, ',
'  L.SAMPLE_RECVD_DATE, ',
'  L.COMMENT_DATE, ',
'  L.DROP_CANCEL_DATE, ',
'  L.COMMENT_STATUS, ',
'  L.SAMPLE_LINE_REMARKS, ',
'  L.SAMPLE_RETURN_DATE, ',
'  L.SELECTED_SAMPLE_BUYER_NAME, ',
'  L.SAMPLE_HANDOVER_TO_MERCH, ',
'  L.CREATION_DATE, ',
'  L.CREATED_BY, ',
'  L.LAST_UPDATE_DATE, ',
'  L.LAST_UPDATED_BY, ',
'  L.SAMPLE_HANDOVER_TO_MERCH_DATE, ',
'  L.VENDOR_ID, ',
'  (',
'    SELECT ',
'      ass.vendor_name ',
'    FROM ',
'      apps.ap_suppliers@adf ass ',
'    WHERE ',
'      ass.vendor_id = L.VENDOR_ID',
'  ) AS SUPPLIER_NAME, ',
'  L.PRODUCTION_UNIT_ID, ',
'  NVL (',
'    (',
'      SELECT ',
'        CASE WHEN l.approval_flag = ''Y'' THEN ''Confirmed'' ELSE ''Not Confirmed'' END ',
'      FROM ',
'        pwc_ont_wvn_precosting_h h, ',
'        pwc_ont_wvn_precosting_l l ',
'      WHERE ',
'        h.header_id = l.header_id ',
'        AND l.sample_line_code IS NOT NULL ',
'        AND h.tracking_no IS NOT NULL ',
'        AND l.sample_line_code = L.SAMPLE_LINE_CODE ',
'        AND EXISTS (',
'          SELECT ',
'            1 ',
'          FROM ',
'            pwc_ont_wvn_sample_status ssh ',
'          WHERE ',
'            ssh.header_id = L.HEADER_ID ',
'            AND ssh.tracking_no IS NULL',
'        ) ',
'        AND l.subcosting_version_no = (',
'          SELECT ',
'            MAX (li.subcosting_version_no) ',
'          FROM ',
'            pwc_ont_wvn_precosting_l li ',
'          WHERE ',
'            l.subcosting_no = li.subcosting_no ',
'            AND l.sample_line_code = li.sample_line_code',
'        ) ',
'      UNION ',
'      SELECT ',
'        ''Confirmed'' ',
'      FROM ',
'        pwc_ont_wvn_sample_status ssh ',
'      WHERE ',
'        ssh.header_id = L.HEADER_ID ',
'        AND ssh.tracking_no IS NOT NULL',
'    ), ',
'    ''Not Confirmed''',
'  ) AS ORDER_STATUS, ',
'  L.PRINTING_PRICE, ',
'  L.EMBROIDERY_PRICE, ',
'  L.M2_JOB_NUMBER,',
'  L.inventory_item_id ',
'FROM PWC_ONT_WVN_SAMPLE_STATUS_L L ',
'where L.HEADER_ID = :P13_HEADER_ID',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P13_HEADER_ID'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Sample Lines'
,p_prn_page_header_font_color=>'#000000'
