,p_max_length=>255
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT fvv.flex_value process_name       ',
'  FROM pwc_flex_values_v fvv       ',
' WHERE     fvv.flex_value_set_name = ''PWC_OM_DYEING_PROCESS''       ',
'       AND ''Dye'' = ''Wet''     ',
'UNION      ',
'SELECT fvv.description        ',
'  FROM pwc_flex_values_v fvv       ',
' WHERE     fvv.flex_value_set_name = ''PWC_OM_POC_WASH_WET_PROCESS'' AND UPPER(FVV.DESCRIPTION) NOT LIKE ''%DYE%''       ',
'       AND ''Wet'' = ''Wet''       ',
'UNION       ',
'SELECT fvv.flex_value process_name       ',
'  FROM pwc_flex_values_v fvv       ',
' WHERE     fvv.flex_value_set_name = ''PWC_OM_DRY_PROCESS''       ',
'       AND ''Dry'' = ''Wet'''))
,p_lov_display_extra=>true
,p_lov_display_null=>true
