,p_is_primary_key=>false
,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'     NVL (                ',
'          (SELECT SUM (moq.transaction_quantity)                ',
'             FROM apps.mtl_system_items@adf msi,                ',
'                  apps.mtl_onhand_quantities@adf moq                ',
'            WHERE     msi.inventory_item_id = moq.inventory_item_id                ',
'                  AND msi.organization_id = moq.organization_id                ',
'--                  AND moq.subinventory_code IN                ',
'  --                       (''D.Fabric'', ''D.F.GMT'', ''Staging'')                ',
'--                  AND msi.segment1 IN (300, 301)                ',
'                  AND moq.organization_id in (89,91)                ',
'                  AND msi.inventory_item_id =                ',
'                         :INVENTORY_ITEM_ID),                ',
'          0) AS STOCK_QTY  FROM DUAL',
''))
,p_duplicate_value=>true
,p_include_in_export=>true
);
