wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(120869414885834676)
,p_name=>'P13_SEASON_NAME'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(120866638601834663)
,p_item_source_plug_id=>wwv_flow_imp.id(120866638601834663)
,p_prompt=>'Season Name'
,p_source=>'SEASON_NAME'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT season_name',
'FROM (SELECT DISTINCT qa_child.character1 season_name       ',
'  FROM apps.qa_results_v@adf qa_parent,       ',
'       apps.qa_results_v@adf qa_child,    ',
'       apps.qa_pc_results_relationship@adf qpr       ',
' WHERE     qa_parent.occurrence = qpr.parent_occurrence       ',
'       AND qa_parent.plan_id = qpr.parent_plan_id       ',
'       AND qa_parent.collection_id = qpr.parent_collection_id       ',
'       AND qa_child.occurrence = qpr.child_occurrence       ',
