wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(138432524529578149)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(120801052416688620)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Sample Lines - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN ',
'            INSERT INTO PWC_ONT_WVN_SAMPLE_STATUS_L (',
'                HEADER_ID,FABRIC_REF_NO,CUTTABLE_WIDTH_VALUE,CUTTABLE_WIDTH_TYPE,FINISH_GARMENTS_COLOR',
'                ,PRINTING_PRICE,EMBROIDERY_PRICE,WASH_NAME,TARGET_SAMPLE_SUBMISSION_DATE,SAMPLE_LINE_STATUS',
'                ,TARGET_SUBMISSION_DATE,TOTAL_SAMPLE_QUANTITY,EXPECTED_ORDER_QUANTITY',
'            ) VALUES (',
'                :P13_HEADER_ID, :FABRIC_REF_NO,:CUTTABLE_WIDTH_VALUE, :CUTTABLE_WIDTH_TYPE, :FINISH_GARMENTS_COLOR',
'                , :PRINTING_PRICE, :EMBROIDERY_PRICE, :WASH_NAME, :TARGET_SAMPLE_SUBMISSION_DATE, :SAMPLE_LINE_STATUS',
'                , :TARGET_SUBMISSION_DATE, :TOTAL_SAMPLE_QUANTITY, :EXPECTED_ORDER_QUANTITY',
'            ) RETURNING LINE_ID INTO :LINE_ID;',
'',
'',
'        WHEN ''U'' THEN ',
'            UPDATE PWC_ONT_WVN_SAMPLE_STATUS_L',
'            SET ',
'                FABRIC_REF_NO                 = :FABRIC_REF_NO,',
'                CUTTABLE_WIDTH_VALUE          = :CUTTABLE_WIDTH_VALUE,',
'                CUTTABLE_WIDTH_TYPE           = :CUTTABLE_WIDTH_TYPE,',
'                FINISH_GARMENTS_COLOR         = :FINISH_GARMENTS_COLOR,',
'                PRINTING_PRICE                = :PRINTING_PRICE,',
'                EMBROIDERY_PRICE              = :EMBROIDERY_PRICE,',
'                WASH_NAME                     = :WASH_NAME,',
'                TARGET_SAMPLE_SUBMISSION_DATE = :TARGET_SAMPLE_SUBMISSION_DATE,',
'                SAMPLE_LINE_STATUS            = :SAMPLE_LINE_STATUS,',
'                TARGET_SUBMISSION_DATE        = :TARGET_SUBMISSION_DATE,',
'                TOTAL_SAMPLE_QUANTITY         = :TOTAL_SAMPLE_QUANTITY,',
'                EXPECTED_ORDER_QUANTITY       = :EXPECTED_ORDER_QUANTITY',
'            WHERE LINE_ID = :LINE_ID;',
'',
'        WHEN ''D'' THEN',
'            DELETE FROM PWC_ONT_WVN_SAMPLE_STATUS_L',
'            WHERE LINE_ID = :LINE_ID;',
'            ',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>138432524529578149
);
wwv_flow_imp_page.create_page_process(
