'            ) RETURNING DETAIL_ID INTO :DETAIL_ID;',
'',
'        WHEN ''U'' THEN',
'            UPDATE PWC_ONT_WVN_SAMPLE_ITEMS_D',
'            SET ',
'                HANGER_QTY                = :HANGER_QTY,',
'                INVENTORY_ITEM_ID         = :INVENTORY_ITEM_ID,',
