'                SOURCING_PERSON_ID        = :SOURCING_PERSON_ID,',
'                ALERT_FLAG                = :ALERT_FLAG,',
'                ITEM_CODE                 = :ITEM_CODE,',
'                M2_JOB                    = :M2_JOB,',
'                SAMPLE_BUYER_ID           = :SAMPLE_BUYER_ID,',
'                STOCK_UNIT_ID             = :STOCK_UNIT_ID,',
'                INVENTORY_ITEM_STATUS     = :INVENTORY_ITEM_STATUS,',
'                MATERIAL_RECVNG_DATE_TIME = :MATERIAL_RECVNG_DATE_TIME,',
'                UPPER_THREAD              = :UPPER_THREAD,',
'                UNDER_THREAD              = :UNDER_THREAD,',
'                REMARKS                   = :REMARKS',
'            WHERE DETAIL_ID = :DETAIL_ID;',
'',
'',
'        WHEN ''D'' THEN',
'            DELETE FROM PWC_ONT_WVN_SAMPLE_ITEMS_D',
