wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148250756449363438)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(121299896845528443)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate PO '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    V_TOTAL_QUANTITY   NUMBER;',
'BEGIN',
'     SELECT EXPECTED_ORDER_QUANTITY INTO V_TOTAL_QUANTITY FROM PWC_ONT_WVN_SAMPLE_STATUS_L WHERE LINE_ID = :LINE_ID;',
' ',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN ',
'            INSERT INTO PWC_ONT_WVN_SAMPLE_PO_TMP_LINE (',
'                INVENTORY_ITEM_ID,',
'                INVENTORY_ITEM_STATUS,',
'                PO_QUANTITY,',
'                PO_CURRENCY,',
'                PO_UNIT_PRICE,',
'                PO_OPERATING_UNIT_ID,',
'                HEADER_ID,',
'                SAMPLE_LINE_CODE,',
'                VERSION_NO',
'            ) VALUES (',
'                :INVENTORY_ITEM_ID,',
'                :INVENTORY_ITEM_STATUS,',
'                V_TOTAL_QUANTITY * :ESTIMATED_CONSUMPTION,',
'                ''PKR'',',
'                :UNIT_PRICE,',
'                85,',
'                :P13_HEADER_ID,',
'                :P13_SAMPLE_CODE,',
'                1',
'            );',
'',
'        WHEN ''U'' THEN ',
'            UPDATE PWC_ONT_WVN_SAMPLE_PO_TMP_LINE',
'            SET',
'                INVENTORY_ITEM_ID     = :INVENTORY_ITEM_ID,',
'                INVENTORY_ITEM_STATUS = :INVENTORY_ITEM_STATUS,',
'                PO_QUANTITY           = V_TOTAL_QUANTITY * :ESTIMATED_CONSUMPTION,',
'                PO_UNIT_PRICE         = :UNIT_PRICE',
'            WHERE INVENTORY_ITEM_ID = :INVENTORY_ITEM_ID',
'            AND HEADER_ID = :P13_HEADER_ID;',
'',
'        WHEN ''D'' THEN',
'            DELETE FROM PWC_ONT_WVN_SAMPLE_PO_TMP_LINE',
'            WHERE INVENTORY_ITEM_ID = :INVENTORY_ITEM_ID',
'            AND HEADER_ID = :P13_HEADER_ID;',
'',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>148250756449363438
);
