wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(141989886669685722)
,p_process_sequence=>130
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(137501909543142220)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SRD to PD - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'    CURSOR c_source IS',
'        SELECT item_type, size_val',
'        FROM pwc_ont_wvn_sample_to_smp_dep',
'        WHERE line_id = :LINE_ID;',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'',
'        WHEN ''C'' THEN',
'            FOR rec IN c_source LOOP',
'                INSERT INTO PWC_ONT_WVN_SAMPLE_TO_PRI_DEP ( LINE_ID, ITEM_TYPE, SIZE_VAL ) ',
'                VALUES (:LINE_ID, rec.item_type, rec.size_val)',
'                RETURNING PRINT_REQ_DETAIL_ID INTO :PRINT_REQ_DETAIL_ID;  ',
'            END LOOP;',
'            commit;',
'',
'        WHEN ''U'' THEN',
'',
'            SELECT COUNT(*)',
'            INTO v_count',
'            FROM PWC_ONT_WVN_SAMPLE_FRM_PRI_DEP',
'            WHERE PRINT_REQ_DETAIL_ID = :PRINT_REQ_DETAIL_ID;',
'',
'            IF v_count > 0 THEN',
'                RAISE_APPLICATION_ERROR(-20001,',
'                ''Row already sent to Printing Department. Update not allowed.'');',
'            END IF;',
'',
'            UPDATE PWC_ONT_WVN_SAMPLE_TO_PRI_DEP',
'            SET',
'                ITEM_TYPE             = :ITEM_TYPE,',
'                SIZE_VAL              = :SIZE_VAL,',
'                SENT_TO_PRINTING_QTY  = :SENT_TO_PRINTING_QTY,',
'                SENT_TO_PRINTING_DATE = :SENT_TO_PRINTING_DATE,',
'                TO_PRINTING_REMARKS   = :TO_PRINTING_REMARKS               ',
'            WHERE PRINT_REQ_DETAIL_ID = :PRINT_REQ_DETAIL_ID;',
'',
'        WHEN ''D'' THEN',
'',
'            SELECT COUNT(*)',
'            INTO v_count',
'            FROM PWC_ONT_WVN_SAMPLE_FRM_PRI_DEP',
'            WHERE PRINT_REQ_DETAIL_ID = :PRINT_REQ_DETAIL_ID;',
'',
'            IF v_count > 0 THEN',
'                RAISE_APPLICATION_ERROR(-20002,',
'                ''Row already sent to Printing Department. Delete not allowed.'');',
'            END IF;',
'',
'            DELETE FROM PWC_ONT_WVN_SAMPLE_TO_PRI_DEP',
'            WHERE PRINT_REQ_DETAIL_ID = :PRINT_REQ_DETAIL_ID;',
'',
'    END CASE;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>141989886669685722
);
