wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(139490151593701404)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CREATE_ITEM_AJAX_CALL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_status VARCHAR2(4000);',
'BEGIN',
'    -- Call the main creation procedure (remote)',
'    apps.pwc_ont_item_create_pkg_apex.sample_item_creation@adf(',
'        p_header_id    => apex_application.g_x01,',
'        p_user_id      => 0,',
'        p_resp_id      => 20634,',
'        p_resp_appl_id => 401',
'    );',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        v_status := REGEXP_REPLACE(SQLERRM, ''ORA-[0-9]+:?\s?'', '''');',
'        v_status := REPLACE(v_status, ''Unexpected Error:'', '''');',
'        v_status := REPLACE(v_status, ''Error:'', '''');',
'        htp.p(''ERROR: '' || TRIM(v_status));',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(121298160426528426)
,p_internal_uid=>139490151593701404
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(139493018962701433)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ITEM_ASSIGN_TO_ORG'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- Loop over inventory items',
'    FOR rec IN (',
'        SELECT inventory_item_id',
'        FROM pwc_ont_wvn_sample_status_l',
'        WHERE header_id = :P13_HEADER_ID',
'    ) LOOP',
'        BEGIN',
'            -- Call the assignment procedure for each item',
'            pwc_item_org_assignemnt_apex(',
'                p_organization_id   => 91,',
'                p_inventory_item_id => rec.inventory_item_id,',
'                p_user_id           => 0,',
'                p_resp_id           => 20634,',
'                p_resp_appl_id      => 401',
'            );',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                htp.p(''ERROR for item '' || rec.inventory_item_id || '': '' || SQLERRM);',
'        END;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>139493018962701433
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148250377492363434)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GENERATE_PRECOSTING_AJAX_CALL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result VARCHAR2(4000);',
'BEGIN',
'',
'    v_result := pwc_ont_wvn_sample_status_pkg.generate_precosting(',
'                    p_header_id => apex_application.g_x01,',
'                    p_user_id   => 0',
'                );',
'',
'    htp.p(v_result);',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>148250377492363434
);
end;
