wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(225913218379508696)
,p_plug_name=>'Operation Bulletin'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PWCMFGOPERATIONMASTERH.HEADER_ID,',
'       PWCMFGOPERATIONMASTERH.SALE_ORDER_ID,',
'       PWCMFGOPERATIONMASTERH.SALE_ORDER_LINE_ID,',
'       PWCMFGOPERATIONMASTERH.INVENTORY_ITEM_ID,',
'       PWCMFGOPERATIONMASTERH.ORG_ID,',
'       PWCMFGOPERATIONMASTERH.SAMPLE_TYPE,',
'       PWCMFGOPERATIONMASTERH.CREATED_BY,',
'       PWCMFGOPERATIONMASTERH.LAST_UDATED_BY,',
'       PWCMFGOPERATIONMASTERH.LAST_UPDATE_DATE,',
'       PWCMFGOPERATIONMASTERH.CREATION_DATE,',
'       PWCMFGOPERATIONMASTERH.EFFECTIVE_START_DATE,',
'       PWCMFGOPERATIONMASTERH.EFFECTIVE_END_DATE,',
'       PWCMFGOPERATIONMASTERH.HEADER_NO,',
'       PWCMFGOPERATIONMASTERH.STN_NO,',
'       (SELECT OOHA.CUST_PO_NUMBER',
'          FROM APPS.OE_ORDER_HEADERS_ALL@ADF OOHA',
'         WHERE OOHA.HEADER_ID = PWCMFGOPERATIONMASTERH.SALE_ORDER_ID)',
'          ORDER_NO,',
'       (SELECT OOHA.ORDER_NUMBER || ''/'' || OOLA.LINE_NUMBER',
'          FROM APPS.OE_ORDER_LINES_ALL@ADF OOLA, APPS.OE_ORDER_HEADERS_ALL@ADF OOHA',
'         WHERE     OOHA.HEADER_ID = OOLA.HEADER_ID',
'               AND OOLA.LINE_ID = PWCMFGOPERATIONMASTERH.SALE_ORDER_LINE_ID)',
'          STN,',
'       NULL SEARCH_STN,',
'       NULL HEADER_ID_TEMP,',
'       XXPWC.PWC_MASTER_TRACKING_DATA_FUNC@ADF (',
'          PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'          ''BUYER_ID'')',
'          CUSTOMER_ID,',
'       XXPWC.PWC_MASTER_TRACKING_DATA_FUNC@ADF (',
'          PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'          ''BUYER_NAME'')',
'          BUYER,',
'       XXPWC.PWC_MASTER_TRACKING_DATA_FUNC@ADF (',
'          PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'          ''STYLE_NAME'')',
'          STYLE_NAME,',
'       XXPWC.PWC_MASTER_TRACKING_DATA_FUNC@ADF (',
'          PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'          ''STYLE_NO'')',
'          STYLE_NO,',
'       XXPWC.PWC_MASTER_TRACKING_DATA_FUNC@ADF (',
'          PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'          ''SEASON_NAME'')',
'          SEASON,',
'       PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'       PWCMFGOPERATIONMASTERH.BRAND,',
'       PWCMFGOPERATIONMASTERH.DEVISION,',
'       PWCMFGOPERATIONMASTERH.WASH_NAME,',
'       PWCMFGOPERATIONMASTERH.COLOR_NAME,',
'       PWCMFGOPERATIONMASTERH.FABRIC_TYPE,',
'       (SELECT MSIB.DESCRIPTION',
'          FROM APPS.MTL_SYSTEM_ITEMS_B@ADF MSIB',
'         WHERE     MSIB.INVENTORY_ITEM_ID =',
'                      PWCMFGOPERATIONMASTERH.INVENTORY_ITEM_ID',
'               AND MSIB.ORGANIZATION_ID =',
'                      XXPWC.PWC_ORGANIZATION_NAME@ADF (''Inventory Master Org''))',
'          ITEM_DESC,',
'       NULL CURRENT_STYLE,',
'       NULL CURRENT_SEASON,',
'       (SELECT LISTAGG (PWCMFGOPERATIONMASTERL.REMARKS, '', '')',
'                  WITHIN GROUP (ORDER BY PWCMFGOPERATIONMASTERL.REMARKS DESC)',
'          FROM PWC_MFG_OPERATION_MASTER_L@ADF PWCMFGOPERATIONMASTERL',
'         WHERE PWCMFGOPERATIONMASTERL.HEADER_ID =',
'                  PWCMFGOPERATIONMASTERH.HEADER_ID)',
'          HEADER_REMARKS,',
'       PWCMFGOPERATIONMASTERH.CHILD_STYLE_NO,',
'       NULL ORGANIC_AUTH,',
'       (SELECT H.NAME',
'          FROM APPS.HR_OPERATING_UNITS@ADF H',
'         WHERE     H.ORGANIZATION_ID = PWCMFGOPERATIONMASTERH.ORG_ID',
'               AND ROWNUM = 1)',
'          ORG_NAME,',
'       --PWCMFGOPERATIONMASTERH.IMAGE_DATA,',
'       PWCMFGOPERATIONMASTERH.ORGANIZATION_ID,',
'       (SELECT NAME',
'          FROM XXPWC.INV_ORG_OU_PWC_V@ADF',
'         WHERE ORGANIZATION_ID = PWCMFGOPERATIONMASTERH.ORGANIZATION_ID)',
'          INV_ORGANIZATION_NAME,',
'       PWCMFGOPERATIONMASTERH.READ_ONLY_FLAG,',
'       PWCMFGOPERATIONMASTERH.RETAILER_DEPT,',
'       PWCMFGOPERATIONMASTERH.DROP_PERIOD,',
'       PWCMFGOPERATIONMASTERH.PLANNING_GROUP,',
'       PWCMFGOPERATIONMASTERH.BRAND_NAME,',
'       PWCMFGOPERATIONMASTERH.BUYER_AGENT_NAME,',
'       PWCMFGOPERATIONMASTERH.BUYER_ID,',
'       XXPWC.PWC_MASTER_TRACKING_DATA_FUNC@ADF (',
'          PWCMFGOPERATIONMASTERH.TRACKING_NO,',
'          ''TRACKING_MODE_DESC'')',
'          TRACKING_MODE,',
'       (SELECT DISTINCT ''Y''',
'          FROM PWC_MFG_OPERATION_MASTER_H@ADF H, PWC_MFG_RATIOPLAN@ADF RP',
'         WHERE     1 = 1',
'               AND H.TRACKING_NO = RP.TRACKING_NO',
'               AND H.TRACKING_NO = PWCMFGOPERATIONMASTERH.TRACKING_NO)',
'          DEL_VAL_FLAG,',
'       PWCMFGOPERATIONMASTERH.OB_REMARKS',
'  FROM PWC_MFG_OPERATION_MASTER_H PWCMFGOPERATIONMASTERH',
' WHERE PWCMFGOPERATIONMASTERH.ORG_ID = ''85''; '))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Operation Bulletin'
);
