,p_value_alignment=>'LEFT'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
,p_is_required=>true
,p_max_length=>250
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT qa_child.character1 as retailer_dept,',
'                qa_child.character1 as retailer_dept_r',
'  FROM apps.qa_results_v@adf qa_parent,   ',
'       apps.qa_results_v@adf qa_child,  ',
'       apps.qa_pc_results_relationship@adf qpr   ',
' WHERE     qa_parent.occurrence = qpr.parent_occurrence   ',
'       AND qa_parent.plan_id = qpr.parent_plan_id   ',
'       AND qa_parent.collection_id = qpr.parent_collection_id   ',
'       AND qa_child.occurrence = qpr.child_occurrence   ',
'       AND qa_child.plan_id = qpr.child_plan_id   ',
'       AND qa_child.character1 IS NOT NULL   ',
'       AND qa_child.collection_id = qpr.child_collection_id   ',
'       AND qa_parent.name = ''PWC_OM_RETAILER_AGENT''   ',
'       AND qa_child.name = ''PWC_OM_RETAILER_DEPARTMENT''   ',
'       AND qa_parent.character2 = :STORE_BUYER_ID',
'       /*',
'      AND NOT EXISTS (',
'    SELECT 1',
'    FROM PWC_MT_ENDUSER_DETAILS_D d',
'    WHERE d.STORE_BUYER_ID = :STORE_BUYER_ID',
'      AND TRIM(UPPER(d.END_USER)) = TRIM(UPPER(qa_child.character1)));',
'      */'))
,p_lov_display_extra=>true
,p_lov_display_null=>true
,p_lov_cascade_parent_items=>'STORE_BUYER_ID'
,p_ajax_items_to_submit=>'STORE_BUYER_ID'
