,p_named_lov=>'BUYER_LOV_MT'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT ',
' ---ac.customer_id,    ',
'                ac.customer_name',
'                ,    ',
'                 hca.attribute6 retailer_code',
'                 ,    ',
'                qrv.character3 agent_name    ',
'  FROM apps.hz_cust_accounts@adf hca,    ',
'       apps.hz_parties@adf hp,    ',
'       apps.ar_customers@adf ac,    ',
'       apps.qa_results_v@adf qrv    ',
' WHERE     hp.party_id = hca.party_id    ',
'       AND hca.cust_account_id = ac.customer_id    ',
'       AND ac.status = ''A''    ',
'       AND qrv.character2 = ac.customer_id     ',
'       AND hca.attribute6 IS NOT NULL    ',
'       AND hp.attribute3 = ''Yes''    ',
'       AND qrv.name = ''PWC_OM_RETAILER_AGENT''    ',
'       AND NOT EXISTS    ',
'              (SELECT *    ',
'                 FROM pwc_mt_buyer_details_h@adf pmbbh    ',
'                WHERE pmbbh.buyer_id = ac.customer_id);'))
,p_lov_display_null=>'YES'
