 p_id=>wwv_flow_imp.id(117608933048857409)
,p_tabular_form_region_id=>wwv_flow_imp.id(221823906684055312)
,p_validation_name=>'ValidateAlreadyExit'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_count NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO l_count',
'    FROM PWC_MT_STYLE_DETAILS_L',
'    WHERE BRAND_LINE_ID = :BRAND_LINE_ID',
'      AND STYLE_NUMBER  = :STYLE_NUMBER',
'      AND ( :STYLE_LINE_ID IS NULL',
'            OR STYLE_LINE_ID != :STYLE_LINE_ID );',
'',
'    -- TRUE = no duplicate, FALSE = duplicate',
'    RETURN l_count = 0;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Already Exist'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
