wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(116813197694201429)
,p_event_id=>wwv_flow_imp.id(116813080958201428)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_buyname VARCHAR2(200);',
'BEGIN',
'    IF :P18_BUYER_ID IS NULL THEN',
'        SELECT DISTINCT hca.attribute6',
'        INTO   l_buyname',
'        FROM   apps.hz_cust_accounts@adf hca',
'             , apps.hz_parties@adf       hp',
'             , apps.ar_customers@adf     ac',
'             , apps.qa_results_v@adf     qrv',
'        WHERE  hp.party_id = hca.party_id',
'        AND    hca.cust_account_id = ac.customer_id',
'        AND    ac.status = ''A''',
'        AND    qrv.character2 = ac.customer_id',
'        AND    hca.attribute6 IS NOT NULL',
'        AND    hp.attribute3 = ''Yes''',
'        AND    qrv.name = ''PWC_OM_RETAILER_AGENT''',
'        AND    ac.customer_name = :P18_BUYER_NAME;',
'',
'        -- Assign value to APEX page item',
'        :P18_SHORT_NAME := l_buyname;',
'    END IF;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P18_SHORT_NAME := NULL;',
'    WHEN TOO_MANY_ROWS THEN',
'        -- Optional: handle as needed',
'        RAISE_APPLICATION_ERROR(-20001, ''Multiple buyers found.'');',
'END;',
''))
,p_attribute_02=>'P18_BUYER_NAME'
,p_attribute_03=>'P18_SHORT_NAME'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
