 p_id=>wwv_flow_imp.id(169165440746473807)
,p_name=>'StopDuplicationBrandCode'
,p_event_sequence=>300
,p_triggering_element_type=>'BUTTON'
,p_triggering_button_id=>wwv_flow_imp.id(224399720987527707)
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'click'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(169165589219473808)
,p_event_id=>wwv_flow_imp.id(169165440746473807)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var region = apex.region("B_STATIC_ID");',
'var grid = region.widget().interactiveGrid("getViews", "grid");',
'var model = grid.model;',
'',
'var seen = {};',
'var hasDuplicate = false;',
'',
'model.forEach(function(record) {',
'',
'    var brandCode = model.getValue(record, "BRAND_CODE");',
'    var brandDesc = model.getValue(record, "BRAND_DESCRIPTION");',
'',
'    // ignore empty rows',
'    if (brandCode) {',
'',
'        var key = brandCode + "|" + brandDesc;',
'',
'        if (seen[key]) {',
'',
'            hasDuplicate = true;',
'',
'            // mark error on BOTH create + modify rows',
'            model.setValidity(record, "BRAND_CODE",',
'                "Duplicate not allowed (CREATE/MODIFY)");',
'',
'        } else {',
'            seen[key] = true;',
'        }',
'    }',
'});',
'',
'if (hasDuplicate) {',
'    apex.message.alert(',
'        "Duplicate records found in CREATE/MODIFY rows. Please fix before saving."',
'    );',
'',
'    return false; // STOP SAVE',
'}'))
);
