'        :P18_UPDATED_DATE := SYSDATE;',
'        :P18_CREATED_DATE := SYSDATE;',
'    ELSE',
'        -- Existing Record (Update Mode)',
'       --- :P18_UPDATED_BY   := NVL(V(''APP_USER''), USER);',
'        :P18_UPDATED_DATE := SYSDATE;',
'       -- :P18_CREATED_BY   := NVL(V(''APP_USER''), USER);',
'        :P18_CREATED_DATE := SYSDATE;',
'    END IF;',
'END;',
''))
