wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(246955357327884853)
,p_plug_name=>'Insert BPO 1st Row Master'
,p_region_name=>'R1M'
,p_parent_plug_id=>wwv_flow_imp.id(247115063337099981)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PwcMfgRatioplanStnsAll.DETAIL_ID,                 ',
'       PwcMfgRatioplanStnsAll.LINE_ID,                 ',
'       PwcMfgRatioplanStnsAll.BPO_NO,                 ',
'       PwcMfgRatioplanStnsAll.STN_NO,                 ',
'       PwcMfgRatioplanStnsAll.INVENTORY_ITEM_ID,                 ',
'       (SELECT concatenated_segments                 ',
'          FROM  apps.mtl_system_items_kfv@adf                 ',
'         WHERE     inventory_item_id =                 ',
'                      PwcMfgRatioplanStnsAll.INVENTORY_ITEM_ID                 ',
'               AND organization_id =                 ',
'                      pwc_organization_name (''Inventory Master Org''))                 ',
'          ITEM_CODE,                 ',
'       (SELECT description                 ',
'          FROM apps.mtl_system_items_b@adf                 ',
'         WHERE     inventory_item_id =                 ',
'                      PwcMfgRatioplanStnsAll.INVENTORY_ITEM_ID                 ',
'               AND organization_id =                 ',
'                      pwc_organization_name (''Inventory Master Org''))                 ',
'          ITEM_DESCRIPTION,                 ',
'       PwcMfgRatioplanStnsAll.ORG_ID,                 ',
'       PwcMfgRatioplanStnsAll.STN_QTY,                 ',
'       PwcMfgRatioplanStnsAll.JOB_STATUS,                 ',
'       PwcMfgRatioplanStnsAll.RATIOPLAN_ID,                 ',
'       apps.GET_PWC_JOB_NAME@adf((SELECT DISTINCT TRACKING_NO         ',
'                              FROM pwc_mfg_ratioplan SMR         ',
'                              WHERE SMR.RATIOPLAN_ID = PwcMfgRatioplanStnsAll.RATIOPLAN_ID),        ',
'                              PwcMfgRatioplanStnsAll.ORG_ID,        ',
'                              ''Cutting'',        ',
'                              PwcMfgRatioplanStnsAll.COLOR ,        ',
'                              (SELECT DISTINCT        ',
'                                      ATTRIBUTE1         ',
'                                    FROM apps.MTL_SYSTEM_ITEMS_KFV@adf MSIK         ',
'                                    WHERE MSIK.INVENTORY_ITEM_ID = PwcMfgRatioplanStnsAll.INVENTORY_ITEM_ID) ,       ',
'                                   PwcMfgRatioplanStnsAll.RATIOPLAN_ID        ',
'                              ) JOB_NAME,                 ',
'       PwcMfgRatioplanStnsAll.STN_SEQUENCE,                 ',
'       PwcMfgRatioplanStnsAll.CREATION_DATE,                 ',
'       --PwcMfgRatioplanStnsAll.CREATED_BY,                 ',
'       --PwcMfgRatioplanStnsAll.LAST_UPDATED_BY,                 ',
'       PwcMfgRatioplanStnsAll.LAST_UPDATE_DATE,                 ',
'       PwcMfgRatioplanStnsAll.COUNTRY,                 ',
'       PwcMfgRatioplanStnsAll.INSEAM,                 ',
'       PwcMfgRatioplanStnsAll.CLUBBING_NO,                 ',
'       PwcMfgRatioplanStnsAll.MERGE_FLAG,                 ',
'       PwcMfgRatioplanStnsAll.BPO_OSP_UNIT_ID,                 ',
'       PwcMfgRatioplanStnsAll.PATTERN_COUNTRY,                 ',
'       (SELECT DISTINCT ooha.attribute12                 ',
'          FROM apps.oe_order_headers_all@adf ooha, apps.oe_order_lines_all@adf oola                 ',
'         WHERE     ooha.attribute12 IS NOT NULL                 ',
'               AND ooha.header_id = oola.header_id                 ',
'               AND ooha.attribute4 =                 ',
'                      (SELECT h.tracking_no                 ',
'                         FROM pwc_mfg_ratioplan h                 ',
'                        WHERE h.ratioplan_id =                 ',
'                                 PwcMfgRatioplanStnsAll.RATIOPLAN_ID)                 ',
'               AND ooha.cust_po_number = PwcMfgRatioplanStnsAll.BPO_NO                 ',
'               AND oola.inventory_item_id =                 ',
'                      PwcMfgRatioplanStnsAll.INVENTORY_ITEM_ID)                 ',
'          replace_bpo,                 ',
'       (SELECT h.name                 ',
'          FROM apps.hr_operating_units@adf h                 ',
'         WHERE h.organization_id = PwcMfgRatioplanStnsAll.BPO_OSP_UNIT_ID)                 ',
'          BPO_OSP_UNIT_NAME,         ',
'       PwcMfgRatioplanStnsAll.CHILD_STYLE_NO,         ',
'       PwcMfgRatioplanStnsAll.PRODUCT_CLASSIFICATION,         ',
'       PwcMfgRatioplanStnsAll.COLOR,      ',
'       PwcMfgRatioplanStnsAll.EXTRA_STN_QTY,      ',
'          NVL((select DISTINCT ''Y''       ',
'                    from PWC_MFG_RATIOPLAN_MERGE_STNS L      ',
'                    where L.BPO_NO = PwcMfgRatioplanStnsAll.BPO_NO      ',
'                    AND L.INSEAM = PwcMfgRatioplanStnsAll.INSEAM ), ''N'') mergebpo_del_check          ,   ',
'       pwc_mfg_marker_ratio_pkg.get_poc_dcpo_remars(PwcMfgRatioplanStnsAll.ratioplan_id,    ',
'                                                    PwcMfgRatioplanStnsAll.STN_NO,   ',
'                                                    PwcMfgRatioplanStnsAll.COLOR,   ',
'                                                    PwcMfgRatioplanStnsAll.INVENTORY_ITEM_ID,   ',
'                                                    PwcMfgRatioplanStnsAll.COUNTRY,   ',
'                                                    ''DCPO_REMARKS'')  DCPO_REMARKS  ',
'  FROM PWC_MFG_RATIOPLAN_STNS_ALL PwcMfgRatioplanStnsAll',
'  where PwcMfgRatioplanStnsAll.RATIOPLAN_ID = :P19_RATIOPLAN_ID',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Insert BPO 1st Row Master'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
end;
