wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(247283110244425859)
,p_plug_name=>'Insert BPO 2nd Row Master'
,p_region_name=>'R2M'
,p_parent_plug_id=>wwv_flow_imp.id(247115063337099981)
,p_region_template_options=>'#DEFAULT#:margin-top-lg'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PwcMfgRatioplanMergeStns.MERGE_STN_ID,         ',
'       PwcMfgRatioplanMergeStns.HEADER_ID,         ',
'       PwcMfgRatioplanMergeStns.CLUBBING_NO,         ',
'       PwcMfgRatioplanMergeStns.BPO_NO,         ',
'       PwcMfgRatioplanMergeStns.STN_NO,         ',
'       PwcMfgRatioplanMergeStns.COUNTRY,         ',
'       PwcMfgRatioplanMergeStns.INSEAM,         ',
'       PwcMfgRatioplanMergeStns.SIZE_QTY,         ',
'       PwcMfgRatioplanMergeStns.CREATED_BY,         ',
'       PwcMfgRatioplanMergeStns.CREATION_DATE,         ',
'       PwcMfgRatioplanMergeStns.LAST_UPDATED_BY,         ',
'       PwcMfgRatioplanMergeStns.LAST_UPDATE_DATE,        ',
'       PwcMfgRatioplanMergeStns.INTEGRATION_ORDER_NUMBER,        ',
'       PwcMfgRatioplanMergeStns.ACHIEVED_CONSUMPTION,        ',
'       PwcMfgRatioplanMergeStns.BPO_OSP_UNIT_ID,        ',
'       PwcMfgRatioplanMergeStns.PATTERN_COUNTRY,        ',
'       (SELECT h.name        ',
'          FROM apps.hr_operating_units@adf h        ',
'         WHERE h.organization_id = PwcMfgRatioplanMergeStns.BPO_OSP_UNIT_ID)        ',
'          BPO_OSP_UNIT_NAME,       ',
'          PwcMfgRatioplanMergeStns.READY_FLAG ,      ',
'          PwcMfgRatioplanMergeStns.RESEND_FLAG,   ',
'          PwcMfgRatioplanMergeStns.EXTRA_SIZE_QTY,   ',
'          NVL((select distinct ''Y''    ',
'                    from PWC_MFG_RATIOPLAN_PLYLINE L    ',
'                    where L.BPO_NO = PwcMfgRatioplanMergeStns.BPO_NO   ',
'                    and L.INSEAM = PwcMfgRatioplanMergeStns.INSEAM ',
'                    and l.ratioplan_id = PwcMfgRatioplanMergeStns.header_id), ''N'') stn_del_check       ',
'FROM PWC_MFG_RATIOPLAN_MERGE_STNS PwcMfgRatioplanMergeStns',
'where PwcMfgRatioplanMergeStns.HEADER_ID = :P19_RATIOPLAN_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Insert BPO 2nd Row Master'
