wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(250035202337654875)
,p_plug_name=>'Color Details'
,p_region_name=>'CD'
,p_parent_plug_id=>wwv_flow_imp.id(246854809543982148)
,p_region_template_options=>'#DEFAULT#:margin-top-md'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT --cd.rowid,',
'       cd.RATIOPLAN_COLOR_ID,',
'       cd.RATIOPLAN_ID,',
'       cd.PRODUCT_CLASSIFICATION,',
'       cd.CHILD_STYLE_NO,',
'       cd.COLOR,',
'       msib2.description AS FABRIC_ITEM_DESC,',
'       cd.BOOKING_CONSUMPTION,',
'       cd.FABRIC_COMP,',
'       cd.FABRIC_CONS,',
'       msib1.description AS INVENTORY_ITEM_DESC,',
'       cd.FABRIC_COMP_UNIT_ID,',
'       cd.INVENTORY_ITEM_ID,',
'       --cd.CREATED_BY,',
'       --cd.CREATION_DATE,',
'       --cd.LAST_UPDATED_BY,',
'       --cd.LAST_UPDATE_DATE,      ',
'       cd.FABRIC_ITEM_ID,      ',
'       NVL(L.COLOR_FLAG, ''N'') AS COLOR_DEL_CHECK',
'FROM PWC_MFG_RATIOPLAN_COLOR_L cd',
'LEFT JOIN apps.mtl_system_items_b@adf msib1',
'       ON msib1.inventory_item_id = cd.INVENTORY_ITEM_ID',
'      AND msib1.organization_id = pwc_organization_name(''Inventory Master Org'')',
'LEFT JOIN apps.mtl_system_items_b@adf msib2',
'       ON msib2.inventory_item_id = cd.FABRIC_ITEM_ID',
'      AND msib2.organization_id = pwc_organization_name(''Inventory Master Org'')',
'LEFT JOIN (',
'   SELECT DISTINCT RATIOPLAN_ID, COLOR, ''Y'' AS COLOR_FLAG',
'   FROM PWC_MFG_RATIOPLAN_STNS_ALL',
') L',
'  ON L.RATIOPLAN_ID = cd.RATIOPLAN_ID',
' AND L.COLOR = cd.COLOR',
'WHERE cd.RATIOPLAN_ID = :P19_RATIOPLAN_ID;',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P19_RATIOPLAN_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
