wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(246957171128884871)
,p_plug_name=>'RP_IG'
,p_region_name=>'RP_IG'
,p_parent_plug_id=>wwv_flow_imp.id(255588232279298265)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>7
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT RP.DIVISION_ID,  ',
'       RP.RATIOPLAN_ID,  ',
'       RP.RATIOPLAN_NUMBER,',
'       RP.PLYLINE_ID,',
'       RP.BPO_NO,  ',
'       RP.FG_COLOR COLOR,',
'       RP.FAB_UNIQUE_CODE FABRIC_DESCRIPTION,',
'       RP.INSEAM,',
'       RP.COUNTRY,',
'       RP.CUT_NO RATIO_PLAN_NO,',
'       RP.INTEGRATION_MARKER_NUMBER MARKER_NUMBER,',
'       RP.PLY LAY,',
'       (SELECT MIN (blnc_ply)  ',
'          FROM pwc_mfg_ratioplan_plycfline  ',
'         WHERE plyline_id = RP.PLYLINE_ID)  ',
'          BALANCE_PLIES,',
'       RP.TOTALPCS TOTAL_PIECES,',
'       RP.RP_FOR_ID REMARKS,           ',
'       RP.CUTTING_RATIO,  ',
'       RP.SIZE_RATIO,  ',
'       RP.TOTAL_RATIOS,  ',
'       RP.MARKERREAD,  ',
'       RP.MARKERPOST,         ',
'       RP.LAST_UPDATE_DATE,  ',
'       RP.LAST_UPDATED_BY,  ',
'       RP.CREATION_DATE,  ',
'       RP.CREATED_BY,          ',
'       RP.CUT_SR_NO,  ',
'       RP.SHIP_PRIORITY,  ',
'       RP.PATTERN,  ',
'       RP.INSEAM_PATTERN,  ',
'       RP.TOTAL_INSEAM_QTY,  ',
'       RP.BLNC_INSEAM_QTY,                    ',
'       RP.MERGE_STN_ID,                         ',
'       RP.FAB_ITEM_CODE,           ',
'       NVL ( (SELECT DISTINCT ''Y''  ',
'                FROM PWC_MFG_MARKER_INFO_L  ',
'               WHERE MARKER_PLAN_NUMBER = RP.CUT_NO),  ',
'            ''N'')  ',
'          raioplan_del_check,  ',
'       NVL (  ',
'          (SELECT DISTINCT ''Y''  ',
'             FROM PWC_MFG_RATIOPLAN_PLYCFLINE  ',
'            WHERE     RATIOPLAN_ID = RP.RATIOPLAN_ID  ',
'                  AND PLYLINE_ID = RP.PLYLINE_ID),  ',
'          ''N'')  ',
'          sizes_del_check,          ',
'       (SELECT NVL (SUM (EXTRA_STN_QTY), 0)  ',
'          FROM PWC_MFG_RATIOPLAN_STNS_ALL ll  ',
'         WHERE     ll.ratioplan_id = RP.RATIOPLAN_ID  ',
'               AND ll.color = RP.FG_COLOR)  ',
'          color_wise_total_order_qty,  ',
'       (SELECT NVL (SUM (TOTALPCS), 0)  ',
'          FROM PWC_MFG_RATIOPLAN_PLYLINE ll  ',
'         WHERE     ll.ratioplan_id = RP.RATIOPLAN_ID  ',
'               AND ll.fg_color = RP.FG_COLOR)  ',
'          color_wise_total_cut_qty,  ',
'       (  (SELECT NVL (SUM (EXTRA_STN_QTY), 0)  ',
'             FROM PWC_MFG_RATIOPLAN_STNS_ALL ll  ',
'            WHERE     ll.ratioplan_id = RP.RATIOPLAN_ID  ',
'                  AND ll.color = RP.FG_COLOR)  ',
'        - (SELECT NVL (SUM (TOTALPCS), 0)  ',
'             FROM PWC_MFG_RATIOPLAN_PLYLINE ll  ',
'            WHERE     ll.ratioplan_id = RP.RATIOPLAN_ID  ',
'                  AND ll.fg_color = RP.FG_COLOR))  ',
'          wip_balance , ',
'          RP.inventory_item_id ',
'  FROM PWC_MFG_RATIOPLAN_PLYLINE RP',
'  WHERE RP.RATIOPLAN_ID = :P19_RATIOPLAN_ID',
''))
