wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(246266794603784121)
,p_name=>'P19_COLOR'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(246121020929783912)
,p_item_source_plug_id=>wwv_flow_imp.id(246121020929783912)
,p_prompt=>'Color'
,p_source=>'COLOR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT          ',
'       powpcl.style_colour display_value,',
'       powpcl.style_colour return_value  ',
'       --mmph.tracking_no  ',
'  FROM pwc_ont_wvn_precosting_h mmph,          ',
'       pwc_ont_wvn_precosting_l mmpl,          ',
'       pwc_ont_wvn_precosting_color_l powpcl,          ',
'       pwc_mfg_fabric_ins_test_h fith,          ',
'       pwc_mfg_fabins_prod_l line          ',
' WHERE     mmph.header_id = mmpl.header_id          ',
'       AND mmph.tracking_no = :P19_TRACKING_NO         ',
'       AND mmpl.line_id = powpcl.line_id          ',
'       AND powpcl.inventory_item_id IS NOT NULL          ',
'       AND mmpl.approval_flag = ''Y''          ',
'       AND line.header_id = fith.header_id          ',
'       AND line.tracking_no = mmph.tracking_no          ',
'       AND line.color = powpcl.style_colour       ',
'       and NOT exists (select ''X''        ',
'                               from PWC_MFG_RATIOPLAN FETCHED        ',
'                               WHERE FETCHED.COLOR =  powpcl.style_colour       ',
'                               and   FETCHED.tracking_no =  mmph.tracking_no       ',
'                               )',
''))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P19_TRACKING_NO'
,p_ajax_items_to_submit=>'P19_TRACKING_NO'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_begin_on_new_line=>'N'
,p_field_template=>wwv_flow_imp.id(220418559820811079)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
