wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(246274853286784130)
,p_name=>'P19_TRACKING_NO'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(246121020929783912)
,p_item_source_plug_id=>wwv_flow_imp.id(246121020929783912)
,p_prompt=>'Tracking No.'
,p_source=>'TRACKING_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'MRF_H_TRACKING_NO_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT bh.buyer_id,          ',
'       ac.customer_name Buyer_Name,          ',
'       sl.style_name,          ',
'       sl.style_number,          ',
'       sd.season_name,          ',
'       sd.tracking_no,          ',
'       nvl((select distinct ''Y''        ',
'            from        ',
'            PWC_MFG_OSP_DEP_ASSIGN ospd,       ',
'            pwc_mfg_osp_stn_line ospl,       ',
'            PWC_MFG_OSP_HEADER osph       ',
'            where 1=1        ',
'            and ospd.stn_line_id = ospl.stn_line_id       ',
'            and ospl.header_id = osph.header_id       ',
'            and osph.tracking_no = sd.tracking_no       ',
'            and ospd.FINAL_DEPARTMENT = ''Printing''       ',
'            and nvl(ospd.sub_unit, ''N'') = ''Y''), ''N'') printing,          ',
'       nvl((select distinct ''Y''        ',
'            from        ',
'            PWC_MFG_OSP_DEP_ASSIGN ospd,       ',
'            pwc_mfg_osp_stn_line ospl,       ',
'            PWC_MFG_OSP_HEADER osph       ',
'            where 1=1        ',
'            and ospd.stn_line_id = ospl.stn_line_id       ',
'            and ospl.header_id = osph.header_id       ',
'            and osph.tracking_no = sd.tracking_no       ',
'            and ospd.FINAL_DEPARTMENT = ''Embroidery''       ',
'            and nvl(ospd.sub_unit, ''N'') = ''Y''), ''N'') embroidery,          ',
'       mmph.fit,          ',
'       mmph.item_description,         ',
'       mmph.EXCESS_CUT_PERC ExtraCutPercent ,       ',
'       /*For OSP Scenario*/       ',
'       nvl((select distinct ''Y''        ',
'            from        ',
'            PWC_MFG_OSP_DEP_ASSIGN ospd,       ',
'            pwc_mfg_osp_stn_line ospl,       ',
'            PWC_MFG_OSP_HEADER osph       ',
'            where 1=1        ',
'            and ospd.stn_line_id = ospl.stn_line_id       ',
'            and ospl.header_id = osph.header_id       ',
'            and osph.tracking_no = sd.tracking_no       ',
'            and ospd.FINAL_DEPARTMENT = ''Cutting''       ',
'            and nvl(ospd.sub_unit, ''N'') = ''Y''), ''Y'') osp_auto_check     ',
'  FROM pwc_mt_buyer_details_h bh,          ',
'       pwc_mt_brand_details_d bd,          ',
'       pwc_mt_style_details_l sl,          ',
'       pwc_mt_season_details_d sd,          ',
'       pwc_ont_wvn_precosting_h mmph,          ',
'       apps.ar_customers@adf ac          ',
' WHERE     1 = 1          ',
'       AND bh.header_id = bd.header_id          ',
'       AND bd.brand_line_id = sl.brand_line_id          ',
'       AND sl.style_line_id = sd.style_line_id          ',
'       AND sd.season_identifier IS NOT NULL          ',
'       AND sd.tracking_no IS NOT NULL          ',
'       AND ac.customer_id = bh.buyer_id          ',
'       AND mmph.tracking_no = sd.tracking_no          ',
'       AND sd.season_status = ''Open''          ',
'       AND sd.season_identifier IS NOT NULL          ',
'       AND sd.tracking_no IS NOT NULL          ',
'       AND sd.tracking_no NOT IN (SELECT mr.tracking_no          ',
'                                   FROM pwc_mfg_ratioplan mr ',
'                                   where 1=2)',
''))
,p_cSize=>32
,p_cMaxlength=>250
,p_begin_on_new_line=>'N'
,p_read_only_when=>'P19_TRACKING_NO'
,p_read_only_when_type=>'ITEM_IS_NOT_NULL'
,p_field_template=>wwv_flow_imp.id(220418663148811079)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_attribute_01=>'DIALOG'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_07=>'Search and Select: Tracking No.'
,p_attribute_08=>'1000'
,p_attribute_10=>'EXTRACUTPERCENT:P19_EXTRA_CUT_PERCENT,STYLE_NAME:P19_STYLE,BUYER_NAME:P19_D_BUYER_NAME,SEASON_NAME:P19_D_SEASON,PRINTING:P19_PRINTING,EMBROIDERY:P19_EMBRIODRY,OSP_AUTO_CHECK:P19_OSP_CHECK,ITEM_DESCRIPTION:P19_POC_ITEM_DESC,FIT:P19_FIT'
);
