wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(129022750110394032)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(250035202337654875)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Color Detail Process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'v_user_id NUMBER := -1;',
'',
'-- lov values ',
'V_BC	NUMBER;',
'V_FCP	VARCHAR2(255);',
'V_FCN	VARCHAR2(255);',
'V_CSN	VARCHAR2(255);',
'V_PC	VARCHAR2(255); ',
'V_COLOR VARCHAR2(255);',
'',
'-- DEL CHECK',
'V_DEL_CHECK NUMBER := 0;',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'             -- set User id ',
'            SELECT user_id INTO v_user_id FROM APEX_230200.WWV_FLOW_USERS  ',
'            WHERE user_name = :APP_USER;',
'            ',
'            --Set LOV Value to remove enduser modification',
'            BEGIN',
'                select * ',
'                into V_PC,V_CSN,V_COLOR,V_BC,V_FCN,V_FCP',
'                from (',
'                    SELECT DISTINCT         ',
'                           mmpl.product_classification,mmpl.child_style_no,powpcl.style_colour colour,                       ',
'                           PWC_BOOKING_CONSUMPTION_FUNC(powpcl.style_colour,mmph.tracking_no,line.FABRIC_ITEM_ID) booking_consumption,                               ',
'                           line.fab_cons fabric_cons,line.fab_comp fabric_comp                  ',
'                    FROM   pwc_ont_wvn_precosting_h mmph,pwc_ont_wvn_precosting_l mmpl,pwc_ont_wvn_precosting_color_l powpcl,         ',
'                           pwc_mfg_fabric_ins_test_h fith,pwc_mfg_fabins_prod_l line         ',
'                    WHERE   mmph.header_id = mmpl.header_id AND mmph.tracking_no = :P19_TRACKING_NO   ',
'                           and powpcl.style_colour = :P19_COLOR AND mmpl.line_id = powpcl.line_id         ',
'                           AND powpcl.inventory_item_id IS NOT NULL AND mmpl.approval_flag = ''Y''         ',
'                           AND line.header_id = fith.header_id AND line.tracking_no = mmph.tracking_no         ',
'                           AND line.color = powpcl.style_colour and NOT exists (select ''X''       ',
'                                                   from PWC_MFG_RATIOPLAN_COLOR_L FETCHED       ',
'                                                   WHERE FETCHED.COLOR =  powpcl.style_colour      ',
'                                                   and   FETCHED.inventory_item_id =  line.inventory_item_id      ',
'                        )) where colour = :COLOR;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    raise_application_error(-20001, ''Fill Color Details not Found: '' || :COLOR);',
'            END;',
'',
'            ',
'            INSERT INTO PWC_MFG_RATIOPLAN_COLOR_L (',
'                RATIOPLAN_ID,COLOR,BOOKING_CONSUMPTION,FABRIC_COMP,',
'                FABRIC_CONS,FABRIC_COMP_UNIT_ID,CHILD_STYLE_NO,PRODUCT_CLASSIFICATION,',
'                INVENTORY_ITEM_ID,FABRIC_ITEM_ID,',
'                CREATED_BY,CREATION_DATE,',
'                LAST_UPDATED_BY,LAST_UPDATE_DATE',
'            )VALUES (',
'                :P19_RATIOPLAN_ID,:COLOR,V_BC,V_FCP,',
'                V_FCN,:FABRIC_COMP_UNIT_ID,V_CSN,V_PC,',
'                :INVENTORY_ITEM_ID,:FABRIC_ITEM_ID,',
'                v_user_id,sysdate,',
'                v_user_id,sysdate',
'            ) return RATIOPLAN_COLOR_ID into :RATIOPLAN_COLOR_ID;',
'',
'        WHEN ''D'' THEN',
'',
'            select COUNT(*) INTO V_DEL_CHECK from PWC_MFG_RATIOPLAN_STNS_ALL  ',
'            where RATIOPLAN_ID = :P19_RATIOPLAN_ID AND COLOR = :COLOR;',
'',
'            IF V_DEL_CHECK > 0 THEN',
'                 raise_application_error(-20001, ''Cannot delete: related record exists.'');',
'            END IF;',
'',
'            DELETE FROM PWC_MFG_RATIOPLAN_COLOR_L',
'            WHERE RATIOPLAN_COLOR_ID = :RATIOPLAN_COLOR_ID;',
'    END CASE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>129022750110394032
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(129023156468394033)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(250035202337654875)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Header After Add Entry in CD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_Count_CL Number;',
'    v_user_id NUMBER;',
'    v_cut_qty   NUMBER;',
'    v_order_qty NUMBER;',
'    V_Plan_Dev  NUMBER;',
'    V_PLAN_DEV_PRCNT Number;',
'    V_RATIO_PLAN_QTY	NUMBER;',
'    V_DEVIATION	NUMBER;',
'    V_DEVIATON_PRCNT	NUMBER;',
'BEGIN',
'    -- Set UserId',
'    SELECT user_id INTO v_user_id FROM APEX_230200.WWV_FLOW_USERS WHERE user_name = :APP_USER;',
'',
'    -- Check Color Details Entry',
'    select count(rowid) into V_Count_CL from PWC_MFG_RATIOPLAN_COLOR_L',
'    where RATIOPLAN_ID =:P19_RATIOPLAN_ID;',
'',
'    --Calculation After Color Details Modication',
'    IF V_Count_CL = 0 then',
'        V_Count_CL := 0;',
'        v_cut_qty   := 0;',
'        v_order_qty := 0;',
'        V_Plan_Dev  := 0;',
'        V_PLAN_DEV_PRCNT := 0;',
'        V_RATIO_PLAN_QTY := 0;',
'        V_DEVIATION :=0;',
'        V_DEVIATON_PRCNT :=0;',
'    ELSE  ',
'        v_cut_qty :=',
'            nvl(pwc_mfg_marker_ratio_pkg.getCutQty(:P19_TRACKING_NO),0);',
'',
'        v_order_qty :=',
'            nvl(pwc_mfg_marker_ratio_pkg.getOrderQty(91, :P19_TRACKING_NO),0);',
'        ',
'        V_Plan_Dev := nvl((v_cut_qty - v_order_qty),0);',
'        ',
'        IF v_order_qty > 0 THEN ',
'          V_PLAN_DEV_PRCNT := nvl((V_Plan_Dev / v_order_qty) * 100,0);   ',
'        END IF;',
'',
'        V_RATIO_PLAN_QTY :=',
'            nvl(pwc_mfg_marker_ratio_pkg.getRatioPlanQty(91, :P19_TRACKING_NO),0);',
'',
'        V_DEVIATION := nvl((V_RATIO_PLAN_QTY - v_order_qty),0);',
'',
'        IF (V_DEVIATION <> 0 AND v_order_qty <> 0) THEN',
'            V_DEVIATON_PRCNT := nvl(((V_DEVIATION / v_order_qty) * 100),0); ',
'        END IF;       ',
'    END IF;',
'',
'    -- Update Header ',
'    UPDATE PWC_MFG_RATIOPLAN',
'    SET CUT_QTY   = v_cut_qty,',
'        ORDER_QTY = v_order_qty,',
'        PLAN_DEV = V_Plan_Dev,',
'        PLAN_DEV_PRCNT = V_PLAN_DEV_PRCNT,',
'        RATIO_PLAN_QTY = V_RATIO_PLAN_QTY,',
'        DEVIATION = V_DEVIATION,',
'        DEVIATON_PRCNT = V_DEVIATON_PRCNT,',
'        LAST_UPDATE_DATE = sysdate,',
'        LAST_UPDATED_BY = v_user_id       ',
'    WHERE RATIOPLAN_ID = :P19_RATIOPLAN_ID;',
'',
'    -- -- Used for code Debug',
'    -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'    --     ''User ID: '' || :P0_USER_ID ||',
'    --     ''Cut Qty: '' || v_cut_qty ||',
'    --     '' | Order Qty: '' || v_order_qty;',
'END;',
'',
'',
'-- Notes',
'    --get order quantity function (db column : Order_Qty) ',
'        -- pwc_mfg_marker_ratio_pkg.getOrderQty(p_org_id NUMBER, p_tracking_no VARCHAR2)',
'',
'    --get cut qty function  (db column : Cut_Qty)',
'        -- pwc_mfg_marker_ratio_pkg.getCutQty(p_tracking_no VARCHAR2) ',
'',
'',
'    -- cut deviation formula (db column : Plan_Dev )',
'        -- cutDeviation = totalCutQty - orderQty; ',
'',
'',
'    --cut deviation % formula (db column : Plan_Dev_Prcnt)',
'        -- if (orderQty > 0) {',
'        --   cutDeviationPrcnt = cutDeviation / orderQty * 100;   ',
'        -- }',
'',
'',
'     -- get ratioplan qty formula (db column : Ratio_Plan_Qty)',
'        -- pwc_mfg_marker_ratio_pkg.getRatioPlanQty(p_org_id NUMBER, p_tracking_no VARCHAR2)',
'',
'    --deviation value formula (db column : Deviation)',
'        -- deviationVal = raioPlaQty - orderQty  ',
'',
'    --deviation % formula (db column : DeviatonPrcnt)',
'        -- if (deviationVal != 0 && orderQty != 0)',
'        --   deviationPrcntVal = (deviationVal / orderQty) * 100;  ',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_only_for_changed_rows=>'N'
,p_internal_uid=>129023156468394033
);
