'        WHEN ''C'' THEN',
'             -- set User id ',
'            SELECT user_id INTO v_user_id FROM APEX_230200.WWV_FLOW_USERS  ',
'            WHERE user_name = :APP_USER;',
'   ',
'            INSERT INTO PWC_MFG_RATIOPLAN_STNS_ALL (',
'                BPO_NO,RATIOPLAN_ID,CREATED_BY,CREATION_DATE,LAST_UPDATE_DATE,LAST_UPDATED_BY',
'            )VALUES (',
'                :BPO_NO,:RATIOPLAN_ID,v_user_id,sysdate,sysdate,v_user_id',
'            ) return DETAIL_ID into :DETAIL_ID;',
'',
'        WHEN ''U'' THEN',
'            UPDATE PWC_MFG_RATIOPLAN_STNS_ALL SET ',
'                MERGE_FLAG = :MERGE_FLAG,',
'                LAST_UPDATE_DATE = SYSDATE,',
'                LAST_UPDATED_BY = v_user_id',
'            WHERE DETAIL_ID = :DETAIL_ID;',
'',
'        WHEN ''D'' THEN',
'            ',
'            -- -- DELETE DISABLE LOGIC',
'            -- select count(*) into   V_DEL_CHECK',
'            -- from PWC_MFG_RATIOPLAN_MERGE_STNS     ',
'            -- where BPO_NO LIKE ''%'' || :BPO_NO || ''%''  AND INSEAM = :INSEAM AND HEADER_ID = :P19_RATIOPLAN_ID;',
'            ',
'            -- IF V_DEL_CHECK > 0 THEN',
'            --      raise_application_error( -20001, ''You cannot delete this record because child data exists.'' );',
'            -- END IF;    ',
'            DELETE FROM PWC_MFG_RATIOPLAN_STNS_ALL',
'            WHERE DETAIL_ID = :DETAIL_ID;',
'    END CASE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>129002169347394009
);
end;
/
begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(130121476126411622)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(246955357327884853)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Header After Add Entry  in Insert BPO R1M'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_COUNT_R Number;',
'    v_user_id NUMBER;',
'    V_TOTAL_QTY   NUMBER;',
'    v_order_qty NUMBER;',
'    V_Plan_Dev  NUMBER;',
'    V_PLAN_DEV_PRCNT Number;',
'    V_RATIO_PLAN_QTY	NUMBER;',
'    V_DEVIATION	NUMBER;',
'    V_DEVIATON_PRCNT	NUMBER;',
'BEGIN',
'    -- Set UserId',
'    SELECT user_id INTO v_user_id FROM APEX_230200.WWV_FLOW_USERS WHERE user_name = :APP_USER;',
'',
'    -- Check Color Details Entry',
'    select count(rowid) into V_COUNT_R from PWC_MFG_RATIOPLAN_STNS_ALL',
'    where RATIOPLAN_ID =:P19_RATIOPLAN_ID;',
'',
'    --Calculation After Color Details Modication',
'    IF V_COUNT_R = 0 then',
'        V_TOTAL_QTY := 0;',
'    ELSE  ',
'        select sum(EXTRA_STN_QTY) INTO V_TOTAL_QTY  from PWC_MFG_RATIOPLAN_STNS_ALL',
'        where RATIOPLAN_ID = :P19_RATIOPLAN_ID',
'        and COLOR = :P19_COLOR;',
'        ',
'    END IF;',
'',
'    -- Update Header ',
'    UPDATE PWC_MFG_RATIOPLAN',
'    SET TOTAL_QTY   = V_TOTAL_QTY,',
'        LAST_UPDATE_DATE = sysdate,',
'        LAST_UPDATED_BY = v_user_id       ',
'    WHERE RATIOPLAN_ID = :P19_RATIOPLAN_ID;',
'',
'    -- -- Used for code Debug',
'    -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'    --     ''User ID: '' || v_user_id ||',
'    --     ''TOTAL_QTY: '' || V_TOTAL_QTY;',
'END;',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_only_for_changed_rows=>'N'
,p_internal_uid=>130121476126411622
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(128970125712393977)
,p_process_sequence=>90
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(254485482418923885)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert BPO R1C - Fatch Fill Sizes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_EXTRA_QTY NUMBER := 0;',
'    V_STN_NO PWC_MFG_RATIOPLAN_STNS_ALL.STN_NO%TYPE;',
'    V_COUNTRY PWC_MFG_RATIOPLAN_STNS_ALL.COUNTRY%TYPE;',
'    CURSOR C_FILL_SIZES IS',
'        SELECT garment_size, garment_size_qty FROM (',
'            SELECT DISTINCT',
'                mmosl.stn oc_no, sizline.country, sizdetail.garment_inseam inseam, oh.attribute4,',
'                NULL inseam_size_concat,',
'                --sizdetail.GARMENT_SIZE_QTY,',
'                CASE',
'                  WHEN NVL (mmr.osp_check, ''N'') = ''N''',
'                  THEN',
'                     sizdetail.garment_qty',
'                  ELSE',
'                     osps.garment_qty',
'                END',
'                garment_size_qty,',
'                --sizdetail.garment_qty GARMENT_SIZE_QTY,',
'                sizdetail.garment_size',
'                --, to_number(sv.size_seq) size_seq',
'            FROM pwc_ont_wvn_sizewise_details_h sizline,',
'                pwc_ont_wvn_sizewise_details_l sizdetail,',
'                apps.oe_order_headers_all@adf oh,',
'                apps.oe_order_lines_all@adf ol,',
'                apps.mtl_system_items@adf msi,',
'                apps.org_organization_definitions@adf ood,',
'                pwc_mfg_osp_header osph,',
'                pwc_mfg_osp_stn_line mmosl,',
'                pwc_mfg_osp_stn_line_sizes osps,',
'                pwc_mfg_ratioplan mmr',
'                --, pwc_om_buyer_wise_sizes_v sv',
'            WHERE   1 = 1',
'                AND sizline.header_id = sizdetail.header_id',
'                AND ol.inventory_item_id = msi.inventory_item_id',
'                AND oh.header_id = ol.header_id',
'                AND ood.organization_id = msi.organization_id',
'                AND ood.operating_unit = oh.org_id',
'                --and mmosl.stn = ''1235/1''',
'                AND oh.flow_status_code <> ''CANCELLED''',
'                AND ood.organization_name <> ''Inventory Master Org''',
'                AND oh.header_id = sizline.sales_order_id',
'                AND ol.inventory_item_id = sizline.inventory_item_id',
'                AND sizline.sales_order_line_id = ol.line_id              --new',
'                AND mmosl.stn = oh.cust_po_number || ''/'' || ol.line_number',
'                AND mmosl.inventory_item_id = msi.inventory_item_id',
'                AND osph.header_id = mmosl.header_id',
'                AND osph.organization_id = ol.ship_from_org_id',
'                --and mmosl.bpo = ''PLOI-0875476''',
'                AND mmr.tracking_no = osph.tracking_no',
'                AND mmosl.stn_line_id = osps.stn_line_id',
'                AND sizdetail.garment_inseam = osps.garment_inseam',
'                AND sizdetail.garment_size = osps.garment_size--AND oh.sold_to_org_id = sv.buyer_id',
'                                                             --AND sizdetail.garment_size = sv.sizes_val',
'                                                             /*order by to_number(sv.size_seq)*/',
'               )',
'        WHERE     OC_NO = V_STN_NO',
'               AND COUNTRY = V_COUNTRY',
'               AND ATTRIBUTE4 = :P19_TRACKING_NO;',
'',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            -- DELETE BEFOR INSERT NEW ALL ENTRIES',
'            DELETE from PWC_MFG_RATIOPLAN_STNS_SIZES where DETAIL_ID = :DETAIL_ID;',
'            commit;',
'            ',
'            -- GET MASTER TABLE VALUE & SET INTO VARIABLES',
'            SELECT STN_NO,COUNTRY INTO V_STN_NO,V_COUNTRY FROM PWC_MFG_RATIOPLAN_STNS_ALL WHERE DETAIL_ID = :DETAIL_ID;',
'            ',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''STN_NO: '' || V_STN_NO ||',
'            -- ''COUNTRY: '' || V_COUNTRY ||',
'            -- ''DETAIL_ID: '' || :DETAIL_ID;',
'',
'            FOR R IN C_FILL_SIZES LOOP',
'                V_EXTRA_QTY := R.garment_size_qty+ROUND(R.garment_size_qty*(:QTY_EXTRA/100));',
'                INSERT INTO PWC_MFG_RATIOPLAN_STNS_SIZES (DETAIL_ID,SIZE_VAL,QTY,QTY_EXTRA) ',
'                VALUES (:DETAIL_ID,R.garment_size,R.garment_size_qty,V_EXTRA_QTY)',
'                RETURNING STN_SIZE_ID INTO :STN_SIZE_ID;                ',
'            END LOOP;',
'            commit;',
'        WHEN ''D'' THEN',
'            delete from PWC_MFG_RATIOPLAN_STNS_SIZES',
'            where STN_SIZE_ID = :STN_SIZE_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_only_for_changed_rows=>'N'
,p_internal_uid=>128970125712393977
);
