wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(129014850927394024)
,p_process_sequence=>130
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(246857433197982175)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fabric Relaxation Tab'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR C_POPULATE_FABRIC IS',
'        SELECT DISTINCT     ',
'           --fith.org_id,     ',
'           --fith.unit_id,     ',
'            (SELECT msi.concatenated_segments FROM apps.mtl_system_items_kfv@adf msi     ',
'            WHERE  msi.inventory_item_id = line.fabric_item_id ',
'                    AND msi.organization_id = pwc_organization_name (''Inventory Master Org'')) FAB_ITEM_CODE,     ',
'            (SELECT msi.description  FROM apps.mtl_system_items@adf msi     ',
'            WHERE   msi.inventory_item_id = line.fabric_item_id     ',
'                   AND msi.organization_id = pwc_organization_name (''Inventory Master Org'')) FAB_ITEM_DESC,     ',
'           sdd.roll_no FACTORY_ROLL_NO,     ',
'           sdd.supplier_roll_no SUPPLIER_ROLLNO,     ',
'           shdl.shade SHADE_RELAXATION,     ',
'            (SELECT DISTINCT pl.shrink_pattern  FROM pwc_mfg_fabins_ptrnaloc_l pl, pwc_mfg_fabins_ptrnaloc_d pld     ',
'            WHERE  pl.prod_l_id = line.prod_l_id  AND pld.aloc_line_id = pl.aloc_line_id     ',
'                   AND pld.roll_no = sdd.roll_no) PATTERN_NO_RELAXATION,     ',
'           --line.tracking_no,     ',
'           line.color FG_COLOR,     ',
'           --pwc_master_tracking_data_func (line.tracking_no, ''STYLE_NAME'')  style_name,     ',
'           det.shrink_prc_length || ''-'' || det.shrink_prc_width SHRINKAGE_GROUP,     ',
'           (det.shrink_length || ''-'' || det.shrink_width) shrinkage_group_inches,  ',
'           --fith.vendor_name,     ',
'           fith.invoice_no COMM_INVOICE_RELAXATION    ',
'           --, fith.version_no,     ',
'           --fith.unit_name,     ',
'           --det.roll_length2,     ',
'           --det.cut_width,     ',
'        --    (SELECT DISTINCT rsh.shipment_num     ',
'        --       FROM apps.rcv_shipment_headers@adf rsh,     ',
'        --            apps.rcv_shipment_lines@adf rsl,     ',
'        --            apps.po_headers_all@adf pha     ',
'        --      WHERE     rsl.shipment_header_id = rsh.shipment_header_id     ',
'        --            AND pha.po_header_id = rsl.po_header_id     ',
'        --            AND rsh.ship_to_org_id = fith.unit_id     ',
'        --            AND rsl.item_id =     ',
'        --                   (SELECT msi.inventory_item_id     ',
'        --                      FROM apps.mtl_system_items_kfv@adf msi     ',
'        --                     WHERE     msi.inventory_item_id = line.fabric_item_id     ',
'        --                           AND msi.organization_id =     ',
'        --                                  pwc_organization_name (     ',
'        --                                     ''Inventory Master Org''))     ',
'        --            AND pha.org_id = fith.org_id     ',
'        --            AND rsh.shipment_num IS NOT NULL     ',
'        --            AND rsh.shipment_num = pl.shipment_num     ',
'        --            AND ROWNUM = 1)     ',
'        --       shipment_num,     ',
'        --    (SELECT DISTINCT pha.segment1     ',
'        --       FROM apps.rcv_shipment_headers@adf rsh,     ',
'        --            apps.rcv_shipment_lines@adf rsl,     ',
'        --            apps.po_headers_all@adf pha     ',
'        --      WHERE     rsl.shipment_header_id = rsh.shipment_header_id     ',
'        --            AND pha.po_header_id = rsl.po_header_id     ',
'        --            AND rsh.ship_to_org_id = fith.unit_id     ',
'        --            AND rsl.item_id =     ',
'        --                   (SELECT msi.inventory_item_id     ',
'        --                      FROM apps.mtl_system_items_kfv@adf msi     ',
'        --                     WHERE     msi.inventory_item_id = line.fabric_item_id     ',
'        --                           AND msi.organization_id =     ',
'        --                                  pwc_organization_name (     ',
'        --                                     ''Inventory Master Org''))     ',
'        --            AND pha.org_id = fith.org_id     ',
'        --            AND rsh.shipment_num IS NOT NULL     ',
'        --            AND rsh.shipment_num = pl.shipment_num     ',
'        -- --            AND ROWNUM = 1)     ',
'        --       po_number,     ',
'        --   NULL supplier     ',
'      FROM pwc_mfg_fabric_ins_test_h fith,     ',
'           pwc_mfg_fabric_ins_test_shd_l shdl,     ',
'           pwc_mfg_fabric_ins_test_l det,     ',
'           pwc_mfg_fabins_prod_l line,     ',
'           pwc_mfg_fabinstest_shd_ld sdd,     ',
'           pwc_inv_fabric_roll_h pl,     ',
'           pwc_mfg_ratioplan mmr,     ',
'           pwc_mfg_ratioplan_color_l cl     ',
'     WHERE     1 = 1     ',
'           AND shdl.line_id = sdd.line_id     ',
'           AND sdd.roll_no = det.roll_no     ',
'           AND line.prod_l_id = det.prod_l_id     ',
'           AND mmr.ratioplan_id = cl.ratioplan_id     ',
'           AND line.prod_l_id = shdl.prod_l_id     ',
'           AND line.header_id = fith.header_id     ',
'           --AND pl.comm_invoice_no = fith.invoice_no     ',
'           AND pl.shipment_num = fith.invoice_no    ',
'           AND pl.organization_id = fith.unit_id     ',
'           AND line.tracking_no = mmr.tracking_no     ',
'           AND line.inventory_item_id = cl.inventory_item_id     ',
'           AND cl.color = line.color   ',
'           AND NOT EXISTS (SELECT ''X'' FROM PWC_MFG_RATPLAN_FAB_RELAXATION FETCHED WHERE FETCHED.FACTORY_ROLL_NO = sdd.roll_no)  ',
'           and exists (select ''X'' from PWC_MFG_FABINS_SECND_D insp where insp.roll_no = sdd.roll_no and nvl(insp.ROL_ACPT_REJ, ''N'')= ''Accept'')',
'           AND line.tracking_no = :P19_TRACKING_NO AND line.color = :P19_COLOR;',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            -- DELETE BEFOR INSERT NEW ALL ENTRIES',
'            DELETE from PWC_MFG_RATPLAN_FAB_RELAXATION where FAB_RELAXATION_ID = :FAB_RELAXATION_ID;',
'            commit;',
' ',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''P19_TRACKING_NO: '' || :P19_TRACKING_NO ||',
'            -- ''P19_COLOR: '' || :P19_COLOR;',
'',
'            FOR R IN C_POPULATE_FABRIC LOOP',
'                INSERT INTO PWC_MFG_RATPLAN_FAB_RELAXATION ',
'                    (RATIOPLAN_ID,FAB_ITEM_CODE,FAB_ITEM_DESC,FACTORY_ROLL_NO,SUPPLIER_ROLLNO,',
'                     SHADE_RELAXATION,PATTERN_NO_RELAXATION,SHRINKAGE_GROUP, COMM_INVOICE_RELAXATION,                     ',
'                     FG_COLOR,SHRINKAGE_GROUP_INCHES',
'                    ) ',
'                VALUES ',
'                    (:RATIOPLAN_ID,R.FAB_ITEM_CODE,R.FAB_ITEM_DESC,R.FACTORY_ROLL_NO,R.SUPPLIER_ROLLNO,',
'                     R.SHADE_RELAXATION, R.PATTERN_NO_RELAXATION, R.SHRINKAGE_GROUP, R.COMM_INVOICE_RELAXATION,                     ',
'                     R.FG_COLOR, R.SHRINKAGE_GROUP_INCHES',
'                    )',
'                RETURNING FAB_RELAXATION_ID INTO :FAB_RELAXATION_ID;                ',
'            END LOOP;',
'            commit;',
'        ',
'        WHEN ''U'' THEN',
'            UPDATE PWC_MFG_RATPLAN_FAB_RELAXATION',
'                SET RELAXATION_END_DATE = :RELAXATION_END_DATE,',
'                    RELAXATION_START_DATE = :RELAXATION_START_DATE',
'            where FAB_RELAXATION_ID = :FAB_RELAXATION_ID;',
'        ',
'        WHEN ''D'' THEN',
'            delete from PWC_MFG_RATPLAN_FAB_RELAXATION',
'            where FAB_RELAXATION_ID = :FAB_RELAXATION_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>129014850927394024
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(128918964165393926)
,p_process_sequence=>140
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(246957171128884871)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RP_IG - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_INSEAM	VARCHAR2(10);',
'  V_COUNTRY	VARCHAR2(255);',
'  V_COLOR	VARCHAR2(250);',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''RATIOPLAN_ID: '' || :RATIOPLAN_ID ||',
'            -- ''P19_COLOR: '' || :P19_COLOR;',
'',
'',
'            -- SET BPO LOV VALUE TO AVOID MODIFICATION',
'            select  ms.inseam, ms.country ,ms.color',
'            INTO V_INSEAM,V_COUNTRY,V_COLOR    ',
'            from pwc_mfg_ratioplan_merge_stns ms      ',
'            where 1=1      ',
'            --and ready_flag = ''Y''    ',
'            and ms.merge_stn_id is not null -- Just to bring only those BPO which are merged    ',
'            and ms.header_id = :P19_RATIOPLAN_ID;',
'',
'            INSERT INTO PWC_MFG_RATIOPLAN_PLYLINE ',
'                (DIVISION_ID,RATIOPLAN_ID,RATIOPLAN_NUMBER,PLYLINE_ID,PLY,TOTALPCS,CUTTING_RATIO,SIZE_RATIO,',
'                TOTAL_RATIOS,MARKERREAD,MARKERPOST,RP_FOR_ID,CUT_NO,CUT_SR_NO,SHIP_PRIORITY,PATTERN,',
'                INSEAM_PATTERN,TOTAL_INSEAM_QTY,BLNC_INSEAM_QTY,INSEAM,BPO_NO,MERGE_STN_ID,',
'                INTEGRATION_MARKER_NUMBER,FAB_UNIQUE_CODE,COUNTRY,FAB_ITEM_CODE,',
'                FG_COLOR,INVENTORY_ITEM_ID',
'                ) ',
'            VALUES ',
'                (:DIVISION_ID,:P19_RATIOPLAN_ID,:RATIOPLAN_NUMBER,:PLYLINE_ID,:LAY,:TOTAL_PIECES,:CUTTING_RATIO,:SIZE_RATIO,',
'                :TOTAL_RATIOS,:MARKERREAD,:MARKERPOST,:REMARKS,:RATIO_PLAN_NO,:CUT_SR_NO,:SHIP_PRIORITY,:PATTERN,',
'                :INSEAM_PATTERN,:TOTAL_INSEAM_QTY,:BLNC_INSEAM_QTY,V_INSEAM,:BPO_NO,:MERGE_STN_ID,',
'                :MARKER_NUMBER,:FABRIC_DESCRIPTION,V_COUNTRY,:FAB_ITEM_CODE,',
'                V_COLOR,:INVENTORY_ITEM_ID',
'                )',
'            RETURNING PLYLINE_ID INTO :PLYLINE_ID;                ',
'            ',
'            commit;',
'        ',
'        WHEN ''U'' THEN',
'            UPDATE PWC_MFG_RATIOPLAN_PLYLINE',
'                SET RP_FOR_ID = :REMARKS,',
'                    PLY = :LAY,',
'                    INTEGRATION_MARKER_NUMBER = :MARKER_NUMBER',
'            where PLYLINE_ID = :PLYLINE_ID;',
'        ',
'        WHEN ''D'' THEN',
'            delete from PWC_MFG_RATIOPLAN_PLYLINE',
'            where PLYLINE_ID = :PLYLINE_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>128918964165393926
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(128901018666393899)
,p_process_sequence=>150
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(255589588910298278)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SD_IG - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_M_id VARCHAR2(500 BYTE);',
'    V_M_LAY NUMBER;',
'    CURSOR C_FILL_SIZES IS',
'        SELECT ',
'            mstns.size_val SIZE_ID, mstns.qty SIZE_QTY, mstns.qty_extra PLAN_QTY            ',
'            --mstn.bpo_no,mstn.header_id ratioplan_id, mstn.country, mstn.inseam, mstn.color    ',
'        FROM PWC_ONT_WVN_PRECOSTING_H poch, ',
'            PWC_MFG_RATIOPLAN rm, ',
'            apps.pwc_om_buyer_wise_sizes_v@adf sv, ',
'            pwc_mfg_ratioplan_merge_stns mstn,             ',
'            pwc_mfg_ratio_merge_stns_sizes mstns             ',
'        WHERE mstn.merge_stn_id = mstns.merge_stn_id   ',
'            and rm.ratioplan_id = mstn.header_id ',
'            and poch.tracking_no = rm.tracking_no    ',
'            --and mstn.bpo_no = ''Test 1122::test 0000'' ',
'            and sv.buyer_id = poch.buyer_id ',
'            and sv.SIZES_VAL =  mstns.size_val ',
'            -- and mstn.country = ''',
'            and mstn.color = :P19_COLOR',
'            and mstn.header_id = :P19_RATIOPLAN_ID',
'            -- and mstn.bpo_no = ''H24-4276CP''',
'            and mstn.bpo_no  not in          ',
'            (SELECT h.BPO_NO  ',
'            from  PWC_MFG_RATIOPLAN_PLYLINE h,           ',
'                PWC_MFG_RATIOPLAN_SIZLINE l            ',
'            where h.PLYLINE_ID =l.PLYLINE_ID           ',
'                and h.BPO_NO = mstn.bpo_no           ',
'                and mstns.size_val = l.SIZE_ID           ',
'                AND H.INSEAM =   mstn.INSEAM          ',
'                AND H.COUNTRY = mstn.country          ',
'                and mstn.header_id = l.RATIOPLAN_ID      ',
'                and CUT_NO = V_M_id )',
'        order by sv.SIZE_SEQ;',
'',
'BEGIN',
'        SELECT CUT_NO,PLY INTO V_M_id,V_M_LAY FROM PWC_MFG_RATIOPLAN_PLYLINE WHERE PLYLINE_ID = :PLYLINE_ID;',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'',
'            --SELECT CUT_NO,PLY INTO V_M_id,V_M_LAY FROM PWC_MFG_RATIOPLAN_PLYLINE WHERE PLYLINE_ID = :PLYLINE_ID;',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''RATIOPLAN_ID: '' || :RATIOPLAN_ID ||',
'            -- ''P19_COLOR: '' || :P19_COLOR;',
'',
'            FOR R IN C_FILL_SIZES LOOP',
'                INSERT INTO PWC_MFG_RATIOPLAN_SIZLINE (SIZE_ID,SIZE_QTY,PLAN_QTY,RATIOPLAN_ID,PLYLINE_ID) ',
'                VALUES (R.SIZE_ID,R.SIZE_QTY,R.PLAN_QTY,:RATIOPLAN_ID,:PLYLINE_ID)',
'                RETURNING SIZLINE_ID INTO :SIZLINE_ID;                ',
'            END LOOP;',
'            commit;',
'',
'        ',
'        WHEN ''U'' THEN',
'            UPDATE PWC_MFG_RATIOPLAN_SIZLINE',
'                SET CUTTING_RATIO = :CUTTING_RATIO,',
'                    PCS = V_M_LAY * :CUTTING_RATIO,',
'                    BAL_QTY = :PLAN_QTY - (V_M_LAY * :CUTTING_RATIO),                                      ',
'                    REMARKS = :REMARKS',
'            where SIZLINE_ID = :SIZLINE_ID;',
'        ',
'        WHEN ''D'' THEN',
'            delete from PWC_MFG_RATIOPLAN_SIZLINE',
'            where SIZLINE_ID = :SIZLINE_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>128901018666393899
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(128901445481393900)
,p_process_sequence=>160
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(255589588910298278)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update RP_IG After SD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_SUM number;',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            NULL;',
'        WHEN ''U'' THEN',
'            SELECT SUM(PCS) INTO V_SUM FROM PWC_MFG_RATIOPLAN_SIZLINE WHERE PLYLINE_ID = :PLYLINE_ID;',
'            UPDATE PWC_MFG_RATIOPLAN_PLYLINE',
'                SET TOTALPCS = V_SUM',
'            where PLYLINE_ID = :PLYLINE_ID;',
'        ',
'        WHEN ''D'' THEN',
'            NULL;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>128901445481393900
);
