wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(129673972835389745)
,p_process_sequence=>190
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(129175356217911826)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Lay Plan - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_TRACKING_NO VARCHAR2(250) := :P19_TRACKING_NO;',
'    V_M_ID NUMBER := :PLYLINE_ID;',
'    V_M_COLOR VARCHAR2(250) := :P19_COLOR;',
'',
'    CURSOR POPULATE IS',
'        SELECT DISTINCT  ',
'            line.fab_comp,  ',
'            line.tracking_no,  ',
'            line.color,  ',
'            sdd.roll_no,  ',
'            shdl.shade,  ',
'            pwc_master_tracking_data_func (line.tracking_no, ''STYLE_NAME'')  ',
'            style_name,  ',
'            det.shrink_prc_length || ''-'' || det.shrink_prc_width SHRINK_PRCNT,   ',
'            NVL (det.ACTUL_METER, 0) roll_length,  ',
'            det.roll_length2,  ',
'            det.cut_width,  ',
'            (',
'                SELECT DISTINCT pl.shrink_pattern  ',
'                FROM pwc_mfg_fabins_ptrnaloc_l pl, pwc_mfg_fabins_ptrnaloc_d pld  ',
'                WHERE     pl.prod_l_id = line.prod_l_id  ',
'                AND pld.aloc_line_id = pl.aloc_line_id  ',
'                AND pld.roll_no = sdd.roll_no',
'            ) shrink_pattern,  ',
'            sdd.supplier_roll_no supplier_roll_no,  ',
'            NULL supplier_batch_no,  ',
'            NULL supplier_pl_no,  ',
'            0 roll_weight,  ',
'            NULL skewing,  ',
'            NULL actual_gsm,  ',
'            (det.SHRINK_LENGTH || ''-'' || det.SHRINK_WIDTH) shrinkage_group_inches,  ',
'            pal.CUTABLE_SHRINKAHE  ',
'        FROM pwc_mfg_fabric_ins_test_shd_l shdl,  ',
'            pwc_mfg_fabric_ins_test_l det,  ',
'            pwc_mfg_fabins_prod_l line,  ',
'            pwc_mfg_fabinstest_shd_ld sdd,  ',
'            pwc_mfg_ratioplan mmr,  ',
'            pwc_mfg_ratioplan_color_l cl,  ',
'            apps.mtl_lot_numbers@adf mln,  ',
'            --       xxpwc.inv_org_ou_pwc_v v,  ',
'            pwc_mfg_fabins_ptrnaloc_l pal,  ',
'            pwc_mfg_fabins_ptrnaloc_d pald  ',
'        WHERE     1 = 1  ',
'            AND shdl.line_id = sdd.line_id  ',
'            AND sdd.roll_no = det.roll_no  ',
'            AND mmr.ratioplan_id = cl.ratioplan_id  ',
'            AND line.tracking_no = mmr.tracking_no  ',
'            --AND line.fab_comp = cl.fabric_comp  ',
'            AND line.inventory_item_id = cl.inventory_item_id  ',
'            AND line.color = cl.color  ',
'            AND mmr.DIVISION_ID = 85  ',
'            -- AND MLN.LOT_NUMBER = CASE WHEN SDD.SUPPLIER_ROLL_NO LIKE ''%-%'' THEN SDD.ROLL_NO ELSE  SDD.SUPPLIER_ROLL_NO END  ',
'            AND MLN.LOT_NUMBER =  ',
'                CASE  ',
'                    WHEN MLN.LOT_NUMBER LIKE ''%F%'' THEN SDD.ROLL_NO  ',
'                    ELSE SDD.SUPPLIER_ROLL_NO  ',
'                END  ',
'            -- and mln.LOT_NUMBER =  sdd.roll_no  ',
'            AND mln.organization_id = 91  ',
'            /*check if rolls are inspected then only accepted will come*/  ',
'            AND det.roll_no =  ',
'                CASE  ',
'                    WHEN det.roll_no IN  ',
'                        (SELECT DISTINCT ROLL_NO FROM PWC_MFG_FABINS_SECND_D)  ',
'                    THEN  ',
'                        (',
'                            SELECT DISTINCT roll_insp.ROLL_NO  ',
'                            FROM PWC_MFG_FABINS_SECND_D roll_insp  ',
'                            WHERE     roll_insp.ROL_ACPT_REJ <> ''Reject''  ',
'                                AND roll_insp.roll_no = det.roll_no)  ',
'                    ELSE  ',
'                        det.roll_no  ',
'                END  ',
'            AND line.prod_l_id = det.prod_l_id  ',
'            AND line.prod_l_id = shdl.prod_l_id  ',
'            AND line.prod_l_id = pal.prod_l_id  ',
'            AND pal.aloc_line_id = pald.aloc_line_id  ',
'            AND pald.ROLL_NO = sdd.roll_no  ',
'            and line.tracking_no = V_TRACKING_NO ',
'            AND NOT EXISTS  ',
'                (',
'                    SELECT ''X''  ',
'                    FROM PWC_MFG_MARKER_LAYPLAN_DET fetched  ',
'                    WHERE fetched.roll_no = sdd.roll_no',
'                )  ',
'            AND EXISTS  ',
'                (',
'                    SELECT 1  ',
'                    FROM apps.mtml_fabric_roll_onhand@adf stk  ',
'                    WHERE     stk.tracking_no = line.tracking_no  ',
'                        AND stk.lot_no = sdd.roll_no',
'                )  ',
'            AND EXISTS  ',
'                (',
'                    SELECT 1  ',
'                    FROM apps.mtl_system_items@adf msi  ',
'                    WHERE     1 = 1  ',
'                        AND msi.organization_id = 91  ',
'                        AND msi.inventory_item_id = line.fabric_item_id  ',
'                        AND msi.description = (',
'                            select FAB_UNIQUE_CODE from PWC_MFG_RATIOPLAN_PLYLINE ',
'                            where PLYLINE_ID = V_M_ID)',
'                )',
'            AND line.color = V_M_COLOR;                 ',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''PLYLINE_ID: '' || V_M_ID  ||',
'            -- '' V_TRACKING_NO: '' || :P19_TRACKING_NO ||',
'            -- '' COLOR: '' || V_M_COLOR;',
'',
'            FOR R IN POPULATE LOOP',
'                INSERT INTO PWC_MFG_MARKER_LAYPLAN_DET ',
'                    (',
'                        PLYLINE_ID,MARK_LENGTH_UOM,MARK_WIDTH_UOM,ROLL_NO,FAB_CONT_UOM,SHRINK_PRCNT',
'                        ,SHADE,END_BIT_UOM,CUT_QTY_UOM,CUT_REM_QTY_UOM ,RATIOPLAN_ID,MARK_LENGTH_UOM2',
'                        ,END_BIT_UOM2,FAB_CON_INCH_UOM,CUT_WIDTH,SHRINK_PATTERN,SUPPLIER_ROLL_NO',
'                        ,ROLL_WEIGHT_UOM,ROLL_LENGTH,SHRINKAGE_GROUP_INCHES,CUTABLE_SHRINKAHE',
'                    ) ',
'                VALUES ',
'                    (',
'                        :PLYLINE_ID, ''Yard'', ''Inch'', R.ROLL_NO, ''Yard'', R.SHRINK_PRCNT',
'                        , R.SHADE, ''Yard'', ''Piece'', ''Piece'' ,:RATIOPLAN_ID, ''Inch''',
'                        , ''Inch'', ''Inch'', R.CUT_WIDTH, R.SHRINK_PATTERN, R.SUPPLIER_ROLL_NO',
'                        , ''Kilogram'', R.ROLL_LENGTH, R.SHRINKAGE_GROUP_INCHES, R.CUTABLE_SHRINKAHE',
'                    )',
'                RETURNING DETAIL_ID INTO :DETAIL_ID;                ',
'            END LOOP;',
'            commit;',
'        WHEN ''U'' THEN',
'            UPDATE  PWC_MFG_MARKER_LAYPLAN_DET SET',
'                CUT_WIDTH = :CUT_WIDTH,',
'                SHRINK_PATTERN = :SHRINK_PATTERN',
'            where DETAIL_ID = :DETAIL_ID;   ',
'        WHEN ''D'' THEN',
'            delete from PWC_MFG_MARKER_LAYPLAN_DET',
'            where DETAIL_ID = :DETAIL_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>129673972835389745
);
end;
/
