wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(125369132035598539)
,p_plug_name=>'Size Wise Header'
,p_region_template_options=>'#DEFAULT#:t-Region--accent14:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
'SELECT DISTINCT        ',
'         mmph.tracking_no,             ',
'         ac.customer_name buyer_name,             ',
'         pwc_master_tracking_data_func (mmph.tracking_no, ''SEASON_NAME'')             ',
'            season,             ',
'         pwc_master_tracking_data_func (mmph.tracking_no, ''STYLE_NAME'')             ',
'            style_name,             ',
'         pwc_master_tracking_data_func (mmph.tracking_no, ''STYLE_NO'')             ',
'            style_no,             ',
'         pwc_master_tracking_data_func (mmph.tracking_no,             ',
'                                              ''TRACKING_MODE_DESC'')             ',
'            tracking_mode_desc,             ',
'         mmph.buyer_agent_name,             ',
'         mmph.drop_period,             ',
'         mmph.brand_name,             ',
'         mmph.fit,             ',
'         mmph.retailer_dept,             ',
'         mmph.item_description,             ',
'         oh.cust_po_number bpo_no,             ',
'         msi.description,             ',
'         SUM (ol.ordered_quantity) ordered_quantity,             ',
'         order_quantity_uom,             ',
'         ol.line_number,             ',
'         oh.cust_po_number || ''/'' || ol.line_number bpo_line_number,             ',
'         ol.inventory_item_id,             ',
'         ac.customer_id buyer_id,             ',
'         oh.attribute12 replace_bpo,             ',
'         oh.header_id,             ',
'         pwc_master_tracking_data_func (mmph.tracking_no,             ',
'                                              ''TRACKING_MODE'')             ',
'            tracking_mode,            ',
'         ol.line_id,   ',
'         ol.attribute3 classification   ',
'    FROM APPS.oe_order_headers_all@ADF oh,             ',
'         APPS.oe_order_lines_all@ADF ol,             ',
'         APPS.mtl_system_items@ADF msi,             ',
'         APPS.org_organization_definitions@ADF ood,             ',
'         pwc_ont_wvn_precosting_h mmph,             ',
'         APPS.ar_customers@ADF ac             ',
'   WHERE     ol.inventory_item_id = msi.inventory_item_id             ',
'         AND oh.header_id = ol.header_id             ',
'         AND ood.organization_id = msi.organization_id             ',
'         AND ood.operating_unit = oh.org_id             ',
'         AND oh.flow_status_code <> ''CANCELLED''             ',
'         AND ood.organization_name <> ''Inventory Master Org''                 ',
'         AND mmph.tracking_no = oh.attribute4     ',
'         AND ol.attribute3 = :P20_BPO_CLASSIFICATION  ',
'         AND mmph.header_id = :P20_HEADER_ID     ',
'         AND oh.cust_po_number = :P20_BPO_NUMBER  ',
'         AND ol.orig_sys_document_ref =NVL(:P20_SUBCOSTING_NO,ol.orig_sys_document_ref)   ',
'         AND ac.customer_id = oh.sold_to_org_id             ',
'         AND mmph.buyer_id || mmph.retailer_dept IN             ',
'                (SELECT bh.buyer_id || ed.end_user             ',
'                   FROM pwc_mt_buyer_details_h bh,             ',
'                        pwc_mt_enduser_details_d ed             ',
'                       -- APPS.fnd_user@ADF fu             ',
'                  WHERE  1=1   --fu.user_name = ed.team_leader             ',
'                        AND bh.header_id = ed.header_id             ',
'                        AND ed.active_enduser = ''Y''             ',
'                       -- AND fu.user_id = :p_UserId             ',
'                 UNION             ',
'                 SELECT bh.buyer_id || ed.end_user             ',
'                   FROM pwc_mt_buyer_details_h bh,             ',
'                        pwc_mt_enduser_details_d ed,             ',
'                        pwc_mt_merchandizer_details_d md            ',
'                       -- APPS.fnd_user@ADF fu             ',
'                  WHERE     bh.header_id = ed.header_id             ',
'                        AND ed.enduser_detail_id = md.enduser_detail_id             ',
'                       -- AND fu.user_name = md.app_user_name             ',
'                        AND ed.active_enduser = ''Y''             ',
'                        AND md.active_merch = ''Y''             ',
'                       -- AND fu.user_id = :p_UserId             ',
'                 UNION             ',
'                 SELECT bh.buyer_id || ed.end_user             ',
'                   FROM pwc_mt_buyer_details_h bh,             ',
'                        pwc_mt_enduser_details_d ed,             ',
'                        pwc_mt_buyr_cordinat_details_d cd             ',
'                        --APPS.fnd_user@ADF fu             ',
'                  WHERE     bh.header_id = ed.header_id             ',
'                        AND ed.enduser_detail_id = cd.enduser_detail_id             ',
'                       -- AND fu.user_name = cd.app_user_name             ',
'                        AND ed.active_enduser = ''Y''             ',
'                        AND cd.active_coordinator = ''Y''  )           ',
'                        --AND fu.user_id = :p_UserId)             ',
'GROUP BY oh.header_id,             ',
'         order_quantity_uom,             ',
'         msi.description,             ',
'         ol.line_number,             ',
'         ac.customer_name,             ',
'         mmph.drop_period,             ',
'         mmph.brand_name,             ',
'         mmph.fit,             ',
'         mmph.retailer_dept,             ',
'         mmph.item_description,             ',
'         mmph.tracking_no,             ',
'         oh.cust_po_number,             ',
'         ol.inventory_item_id,             ',
'         ac.customer_id,             ',
'         mmph.header_id,             ',
'         mmph.buyer_agent_name,             ',
'         oh.attribute12,            ',
'         ol.line_id,   ',
'         ol.attribute3',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P20_HEADER._ID,P20_BPO_CLASSIFICATION,P20_BPO_NUMBER'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Size Wise Header'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
