wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(178153306644911209)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(125367787150598525)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Grmt Qty not excd to ord qty'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_total_qty NUMBER := 0;',
'    l_order_qty NUMBER := 0;',
'BEGIN',
'',
'    -- Get Order Qty from header table',
'    SELECT NVL(ORDER_QUANTITY, 0)',
'    INTO l_order_qty',
'    FROM PWC_ONT_WVN_PRECOSTING_H',
'    WHERE HEADER_ID = :P20_HEADER_ID;',
'',
'    -- Get total garment qty from detail table',
'    SELECT NVL(SUM(NVL(GARMENT_QTY, 0)), 0)',
'    INTO l_total_qty',
'    FROM PWC_ONT_WVN_SIZEWISE_DETAILS_L',
'    WHERE header_id = :header_id;',
'',
'    -- Validation',
'    IF l_total_qty > l_order_qty THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Total Garment Qty exceeded! Total='' || l_total_qty || '' Order='' || l_order_qty',
'        );',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>178153306644911209
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(140076657050213205)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_BUYER_ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   BEGIN',
'      SELECT ac.customer_id',
'      INTO   :P20_BUYER_ID',
'      FROM   APPS.oe_order_headers_all@ADF oh',
'      JOIN   APPS.ar_customers@ADF ac',
'             ON ac.customer_id = oh.sold_to_org_id',
'      JOIN   pwc_ont_wvn_precosting_h mmph',
'             ON mmph.tracking_no = oh.attribute4',
'      WHERE  oh.cust_po_number = :P20_BPO_NUMBER',
'      AND    mmph.header_id   = :P20_HEADER_ID',
'      AND    ROWNUM = 1;',
'',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         :P20_BUYER_ID := NULL;',
'   END;',
'END;',
'',
'-- SELECT ac.customer_id',
'-- INTO   :P20_BUYER_ID',
'-- FROM   APPS.oe_order_headers_all@ADF oh',
'-- JOIN   APPS.ar_customers@ADF ac',
'--        ON ac.customer_id = oh.sold_to_org_id',
'-- JOIN   pwc_ont_wvn_precosting_h mmph',
'--        ON mmph.tracking_no = oh.attribute4',
'-- WHERE  oh.cust_po_number = :P20_BPO_NUMBER',
'-- AND    mmph.header_id   = :P20_HEADER_ID',
'-- AND    ROWNUM = 1;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>140076657050213205
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(140077219929213211)
,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'EXCESS_CUT_PERC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   SELECT h.EXCESS_CUT_PERC,',
'          h.ORDER_QUANTITY',
'   INTO   :P20_EXCESS_CUT_PERC,',
'          :P20_ORDER_QUANTITY',
'   FROM   PWC_ONT_WVN_PRECOSTING_H h',
'   WHERE  h.HEADER_ID = :P20_HEADER_ID;',
'',
'EXCEPTION',
'   WHEN NO_DATA_FOUND THEN',
'      :P20_EXCESS_CUT_PERC := NULL;',
'      :P20_ORDER_QUANTITY  := NULL;',
'',
'   WHEN TOO_MANY_ROWS THEN',
'      NULL; -- ya ROWNUM=1 laga do',
'END;',
'',
'--30-4-26',
'-- BEGIN',
'--    -- Excess Cut Percentage fetch',
'--    SELECT h.EXCESS_CUT_PERC, h.ORDER_QUANTITY',
'--    INTO   :P20_EXCESS_CUT_PERC, :P20_ORDER_QUANTITY',
'--    FROM   PWC_ONT_WVN_PRECOSTING_H h',
'--    WHERE  h.EXCESS_CUT_PERC = :P3_EXCESS_CUT_PERC',
'--      AND  h.ORDER_QUANTITY = :P3_ORDER_QUANTITY;  -- optional: agar dono criteria chahiye',
'',
'-- EXCEPTION',
'--    WHEN NO_DATA_FOUND THEN',
'--       :P20_EXCESS_CUT_PERC := NULL;',
'--       :P20_ORDER_QUANTITY := NULL;',
'--    WHEN TOO_MANY_ROWS THEN',
'--       -- multiple rows ka risk ho',
'--      :P20_EXCESS_CUT_PERC := :P3_EXCESS_CUT_PERC;',
'--       :P20_ORDER_QUANTITY := :P3_ORDER_QUANTITY;',
'-- END;',
'',
'',
'',
'-- BEGIN',
'--    SELECT h.EXCESS_CUT_PERC',
'--    INTO   :P20_EXCESS_CUT_PERC',
'--    FROM   PWC_ONT_WVN_PRECOSTING_H h',
'--    WHERE  h.EXCESS_CUT_PERC = :P3_EXCESS_CUT_PERC;',
'-- EXCEPTION',
'--    WHEN NO_DATA_FOUND THEN',
'--       :P20_EXCESS_CUT_PERC := NULL;',
'--    WHEN TOO_MANY_ROWS THEN',
'--       -- agar multiple rows ka risk ho',
'--       :P20_EXCESS_CUT_PERC := :P3_EXCESS_CUT_PERC;',
'      ',
'-- END;',
'',
'-- --P3_EXCESS_CUT_PERC'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>140077219929213211
);
end;
