 p_id=>wwv_flow_imp.id(223456539978279524)
,p_plug_name=>'Fabric Header Informations'
,p_region_name=>'HEADER_STATIC_ID'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT HEADER_ID,INVOICE_NO, BW_WIDTH_CM, BW_LENGTH_CM, HEADER_NO, VERSION_NO,ORG_ID,UNIT_ID,',
'--CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE,',
'PWC_FABRIC_INSP_CONCAT_FUNC(HEADER_ID,''TRACKING_NO'')                 ',
'            TRACKING_NO_L,',
'UNIT_NAME',
' FROM PWC_MFG_FABRIC_INS_TEST_H',
' where',
' UNIT_ID=91',
'   AND ',
'  (',
'     INVOICE_NO=:P23_SEARCH_INV ',
'  OR ',
'  PWC_FABRIC_INSP_CONCAT_FUNC(HEADER_ID,''TRACKING_NO'')=:P23_TRACK',
'  )',
