'// Get IG region',
'var ig$ = apex.region("LINE_INFO_STATIC_ID").widget();',
'',
'// Make sure IG exists',
'if (!ig$) {',
'  console.error("Interactive Grid not found!");',
'  return;',
'}',
'',
'// Get Grid view',
'var grid = ig$.interactiveGrid("getViews", "grid");',
'if (!grid) {',
'  console.error("Grid view not available!");',
'  return;',
'}',
'',
'// Get model and selected row',
'var model = grid.model;',
'var records = grid.getSelectedRecords();',
'',
'// Exit if nothing selected',
'if (!records || records.length === 0) {',
'  return;',
'}',
'',
'// Grab column values from selected row',
'',
'var trackingNo = model.getValue(records[0], "TRACKING_NO");',
'if (typeof trackingNo === ''object'') { trackingNo = trackingNo.v; }',
'',
'',
'',
'',
'',
'',
'// Set page items',
'',
'',
'var headerId   = model.getValue(records[0], "HEADER_ID");',
'var rawColor   = model.getValue(records[0], "RAW_COLOR");',
'var prodLId   = model.getValue(records[0], "PROD_L_ID");',
'',
'',
'',
'',
'// Set page items',
'apex.item("P23_V_TR_NO").setValue(trackingNo);',
'apex.item("P23_V_COLOR").setValue(rawColor);',
'apex.item("P23_V_L_ID").setValue(prodLId);',
'',
'',
'',
'',
'',
'/*',
'const ig$ = apex.region("LINE_INFO_STATIC_ID").widget();',
