'                VERSION_NO,',
'                ORG_ID,',
'                UNIT_ID,',
'                UNIT_NAME',
'            )',
'            VALUES',
'            (',
'                :HEADER_ID,',
'                :INVOICE_NO,',
'                :BW_WIDTH_CM,',
'                :BW_LENGTH_CM,',
'                :HEADER_NO,',
'                :VERSION_NO,',
'                :ORG_ID,',
'                :UNIT_ID,',
'                :UNIT_NAME',
'            )',
'            RETURNING HEADER_ID INTO :HEADER_ID;',
'',
