wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(131081933557262605)
,p_plug_name=>'New'
,p_region_name=>'FABRIC_IG'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--noBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    roll_no,',
'    roll_no_new supp_roll_no,',
'    roll_weight,',
'    roll_width as cut_width,',
'    ROUND (roll_length_yards, 3) roll_length,       ',
'    ROUND(roll_length_yards * 0.9144) aloc_yard,       ',
'    (roll_length_yards * 36) aloc_inch,    ',
'    0 as aw_length,',
'    0 as aw_width,',
'    roll_width,',
'    color,',
'    shade AS shrinkage_shade,',
'    tracking_no,',
'    supplier_batch_no,',
'    supplier_pl_no,',
'    fab_ounce,',
'    item_fab_weight',
'FROM (',
'  ',
'',
'SELECT DISTINCT       ',
'                 i.header_id,       ',
'                 i.color,       ',
'                 d.shade,',
'                 d.roll_sr_no roll_no,       ',
'                 d.roll_no roll_no_new,       ',
'                  case when d.UOM in (''Grams'', ''Kilograms'') then   ',
'                 NVL (       ',
'                    (SELECT SUM (moqd.primary_transaction_quantity)       ',
'                       FROM apps.mtl_onhand_quantities_detail@adf moqd,       ',
'                            apps.mtl_item_locations@adf mtl       ',
'                      WHERE     moqd.lot_number = d.roll_sr_no       ',
'                            AND moqd.inventory_item_id = i.inventory_item_id       ',
'                            AND moqd.locator_id = mtl.inventory_location_id       ',
'                            AND mtl.organization_id = moqd.organization_id       ',
'                            AND mtl.subinventory_code = i.subinventory_code       ',
'                            AND mtl.disable_date IS NULL       ',
'                            AND mtl.segment5 = i.tracking_no),       ',
'                    0)    ',
'                    else   ',
'                    0   ',
'                    end   ',
'                    roll_weight,       ',
'                 d.roll_length_yards,       ',
'                 d.roll_width,       ',
'                 i.tracking_no,       ',
'                 d.supplier_batch_no,       ',
'                 d.supplier_pl_no,       ',
'                 TO_NUMBER (       ',
'                    NVL (REGEXP_REPLACE (i.fab_ounce, ''[^[:digit:]]'', ''''), 1))       ',
'                    fab_ounce,       ',
'                 d.roll_width item_fab_weight ',
'',
'',
'',
'',
'    FROM pwc_inv_fabric_roll_l i,',
'         pwc_inv_fabric_roll_d d,',
'         pwc_inv_fabric_roll_h mmfih',
'    WHERE i.line_id = d.line_id',
'      AND i.header_id = mmfih.header_id',
'     -- AND d.accepted_flag = ''Y''',
'      AND i.color = ''NONE''',
'      AND i.tracking_no = :P24_TRACKING_NO ',
') ',
'',
'aa',
'',
'   WHERE NOT EXISTS       ',
'                (SELECT *       ',
'                   FROM pwc_mfg_fabric_ins_test_l mmfp1,       ',
'                        pwc_mfg_fabins_prod_l mmfpl1       ',
'                  WHERE     mmfp1.prod_l_id = mmfpl1.prod_l_id       ',
'                      --  AND mmfpl1.tracking_no = aa.tracking_no       ',
'                        --AND mmfp1.supp_roll_no = aa.roll_no_new       ',
'                        AND mmfp1.roll_no = aa.roll_no       ',
'                        AND mmfpl1.raw_color = aa.color)    ',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'New'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
