,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var region = apex.region("FABRIC_IG");',
'var ig = region.widget();',
'var gridView = ig.interactiveGrid("getViews","grid");',
'var model = gridView.model;',
'',
'var selectedRecords = gridView.getSelectedRecords();',
'',
'if (!selectedRecords.length) {',
'    apex.message.alert("Select at least one row");',
'    return;',
'}',
'',
'var rows = [];',
'',
'selectedRecords.forEach(function(record){',
'',
'    var roll_no = model.getValue(record,"ROLL_NO");',
'    var roll_width = model.getValue(record,"ROLL_WIDTH");',
'    var roll_length = model.getValue(record,"ROLL_LENGTH");',
'    var aw_length = model.getValue(record,"AW_LENGTH");',
'    var aw_width = model.getValue(record,"AW_WIDTH");',
'    var aloc_inch = model.getValue(record,"ALOC_INCH");',
'    var aloc_yard = model.getValue(record,"ALOC_YARD");',
'    var supp_roll_no = model.getValue(record,"SUPP_ROLL_NO");',
'    var shrinkage_shade = model.getValue(record,"SHRINKAGE_SHADE");',
'    var cut_width = model.getValue(record,"CUT_WIDTH");',
'    ',
'    ',
'    ',
'    ',
'    ',
'    //var roll_length_yards = model.getValue(record,"ROLL_LENGTH_YARDS");',
'    ',
'   // var item_Fab_Weight = model.getValue(record,"ITEM_FAB_WEIGHT");',
'    ',
'',
'    console.log("roll_no:", roll_no);',
'    console.log("roll_widtha:", roll_width);',
'    console.log("cut_widtha:", cut_width);',
'    console.log("SHRINKAGE_SHADE:", shrinkage_shade);',
'  ',
'',
'    rows.push({',
'        roll_no: roll_no,',
'        roll_width: Number(roll_width),',
'        roll_length: Number(roll_length),',
'        aw_length: Number(aw_length),',
'        aw_width: Number(aw_width),',
'        aloc_inch: Number(aloc_inch),',
'        aloc_yard: Number(aloc_yard),',
'        supp_roll_no: supp_roll_no,',
'        shrinkage_shade: shrinkage_shade,',
'        cut_width: Number(cut_width),',
'        ',
'        ',
'    });',
'',
'});',
'',
'//console.log("FINAL JSON:", JSON.stringify(rows));',
'',
'',
'// AJAX CALL ',
' apex.server.process(',
'    "INSERT_ROWS",',
'    {',
'        x01: JSON.stringify(rows)',
'    },',
'    {',
'        dataType: "text",',
'        success: function (pData) {',
'',
'            if (pData && pData.startsWith("ERROR")) {',
'                apex.message.alert(pData);',
'                return;',
'            }',
'',
'            apex.message.showPageSuccess(pData);',
'',
'            ',
'',
'            //apex.region("FABRIC_IG").refresh();',
'            safeRefreshIG("FABRIC_IG");',
'            apex.navigation.dialog.close(true);',
'',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            apex.message.alert("AJAX failed: " + errorThrown);',
'        }',
'    });',
'',
''))
);
