wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(135045321259663705)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_ROWS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_rows CLOB := APEX_APPLICATION.G_X01;',
'    l_count NUMBER;',
'',
'BEGIN',
'    ',
'     APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'             ''User ID: '' || l_rows ;',
'',
'    ',
'    ',
'    apex_json.parse(l_rows);',
'',
'    -- Fixed: Added p_path => ''.'' to count root elements',
'    l_count := apex_json.get_count(p_path => ''.'');',
'',
'    FOR i IN 1 .. l_count LOOP',
'        INSERT INTO PWC_MFG_FABRIC_INS_TEST_L (roll_no, roll_width, roll_length, aw_length, aw_width, aloc_inch, roll_length2, ',
'        aloc_mtr, roll_mtr, line_type, aloc_yard, supp_roll_no, SHRINKAGE_SHADE, cut_width, aloc_meter, actul_meter, PROD_L_ID)',
'        ',
'        VALUES (',
'            -- Use %d for safer index handling',
'            apex_json.get_varchar2(p_path => ''[%d].roll_no'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].roll_width'', p0 => i), ',
'            apex_json.get_number(p_path => ''[%d].roll_length'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].aw_length'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].aw_width'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].aloc_inch'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].aloc_inch'', p0 => i), -- same data inserted in roll_length2 column',
'            0,',
'            0,',
'           ''P'',',
'            apex_json.get_number(p_path => ''[%d].aloc_yard'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].supp_roll_no'', p0 => i),',
'            apex_json.get_varchar2(p_path => ''[%d].shrinkage_shade'', p0 => i),',
'            apex_json.get_number(p_path => ''[%d].cut_width'', p0 => i), ',
'            apex_json.get_number(p_path => ''[%d].aloc_yard'', p0 => i), -- SAME DATA IN ALOC METER',
'            apex_json.get_number(p_path => ''[%d].aloc_yard'', p0 => i), -- SAME DATA IN ACTUAL METER',
'            ',
'            ',
'',
'            ',
'            ',
'',
'          ',
'            v(''P24_V_L_ID'')',
'        );',
'    END LOOP;',
'     htp.p(l_count||'' Rows Inserted'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        htp.p(''ERROR: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>135045321259663705
);
