'       ITEM_CREATED,',
'       FIN_ITEM_CREATED,',
'       WASH,',
'       INVENTORY_ITEM_ID,',
'       BPO_OSP_UNIT_ID,',
'       CHILD_STYLE_NO,',
'       STYLE_CATEGORY,',
'       EMBRDRY_FLAG,',
'       PRINTING_FLAG,',
