'       SPLIT_COLOR,',
'       replace_bpo,',
'       tracking_no,',
'       requisition_numbers,',
'       item_sub_inv,',
'       job_number',
'  FROM PWC_MFG_OSP_STN_LINE MOSTL',
' WHERE Header_id = :p25_header_id',
'',
'',
'',
' /*',
'',
' (SELECT DISTINCT ooha.attribute12           ',
'            FROM apps.oe_order_headers_all@adf ooha, apps.oe_order_lines_all@adf oola           ',
'           WHERE     ooha.attribute12 IS NOT NULL           ',
'                 AND ooha.header_id = oola.header_id           ',
'                 AND MOSTL.inventory_item_id = oola.inventory_item_id           ',
'                 AND ooha.cust_po_number = MOSTL.bpo           ',
'                 AND ooha.attribute4 =           ',
'                        (SELECT h.tracking_no           ',
'                           FROM pwc_mfg_osp_header h           ',
'                          WHERE h.header_id = MOSTL.header_id))           ',
'            replace_bpo,           ',
'',
'',
'       (SELECT TRACKING_NO FROM ',
'PWC_MFG_OSP_HEADER WHERE HEADER_ID = MOSTL.header_id)',
'       TRACKING_NO,',
' (select listagg(prha.segment1, '', '') within group (order by prha.segment1)      ',
'            from pwc_mfg_osp_header osph,     ',
'                 apps.po_requisition_headers_all@adf prha      ',
'                 where header_id = MOSTL.header_id     ',
'                 and osph.org_id = prha.org_id     ',
'                 and osph.doc_no ||'':''|| REGEXP_SUBSTR (prha.interface_source_code,''[^:]+'',1, 2)= osph.doc_no ||'':''|| MOSTL.stn_line_id     ',
'        ) Requisition_numbers ,',
' ',
'(select  apps.pwc_mfg_osp_items_func@ADF(MOSTL.ORG_ID,(SELECT TRACKING_NO FROM ',
'PWC_MFG_OSP_HEADER WHERE HEADER_ID = MOSTL.header_id),MOSTL.COLOR) from dual)',
'       ITEM_SUB_INV,',
'       (',
'SELECT LISTAGG (j.wip_entity_name, '' | '')         ',
'                    WITHIN GROUP (ORDER BY j.wip_entity_name) ',
'            FROM apps.wip_discrete_jobs_v@adf j, pwc_mfg_osp_header h           ',
'           WHERE     1 = 1           ',
'                 AND j.attribute4 = MOSTL.COLOR           ',
'                 AND j.attribute6 = ''Yes'' ',
'                 AND h.header_id = MOSTL.header_id',
'                 AND h.tracking_no = j.attribute2       ',
'               ---  and nvl(:SPLIT_CHECK, ''N'') <> ''Y''      ',
'                AND j.status_type NOT IN (7, 12)      ',
'',
'',
'       )',
'       JOB_NUMBER',
'',
' */'))
