wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(128005866270237736)
,p_name=>'P25_TRACKING_NO'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(128004050043237718)
,p_item_source_plug_id=>wwv_flow_imp.id(128004050043237718)
,p_prompt=>'Tracking No'
,p_source=>'TRACKING_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'TRACKINGNO_UNIT_OSP_PLAN'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT    ',
'       h.buyer_id,    ',
'       ac.customer_name,    ',
'       l.style_name,    ',
'       l.style_number,    ',
'       d.season_name,    ',
'       d.tracking_no,    ',
'       bd.brand_description brand_name,    ',
'       poc.invoicing_unit_id,    ',
'       DECODE(h.tracking_mode, ''MS'', ''Master Style'', ''CS'', ''Child Style'') tracking_mode,    ',
'       poc.retailer_dept    ',
'  FROM pwc_mt_buyer_details_h h,    ',
'       pwc_mt_brand_details_d bd,    ',
'       pwc_mt_style_details_l l,    ',
'       pwc_mt_season_details_d d,    ',
'       apps.ar_customers@adf ac,    ',
'       pwc_ont_wvn_precosting_h poc,    ',
'       pwc_ont_wvn_precosting_l pocl    ',
' WHERE ac.customer_id = h.buyer_id    ',
'   AND h.header_id = bd.header_id    ',
'   AND poc.header_id = pocl.header_id    ',
'   AND pocl.approval_flag = ''Y''    ',
'   AND bd.brand_line_id = l.brand_line_id    ',
'   AND l.style_line_id = d.style_line_id    ',
'   AND d.season_status = ''Open''    ',
'   AND d.season_identifier IS NOT NULL    ',
'   AND d.tracking_no IS NOT NULL    ',
'   AND d.division = ''Woven''    ',
'   AND d.tracking_no = poc.tracking_no    ',
'   AND poc.invoicing_unit_id = 91    ',
'   AND (:p25_organization_Id IS NOT NULL OR :p25_organization_Id IS NULL)    ',
'   AND h.tracking_mode = ''CS''    ',
'   AND NOT EXISTS (  ',
'       SELECT 1  ',
'         FROM pwc_mfg_osp_header hdr  ',
'        WHERE hdr.tracking_no = d.tracking_no  ',
'   )  ',
'  ',
'UNION ALL    ',
'  ',
'SELECT DISTINCT    ',
'       h.buyer_id,    ',
'       ac.customer_name,    ',
'       l.style_name,    ',
'       l.style_number,    ',
'       d.season_name,    ',
'       d.tracking_no,    ',
'       bd.brand_description brand_name,    ',
'       poc.invoicing_unit_id,    ',
'       DECODE(h.tracking_mode, ''MS'', ''Master Style'', ''CS'', ''Child Style'') tracking_mode,    ',
'       poc.retailer_dept    ',
'  FROM pwc_mt_buyer_details_h h,    ',
'       pwc_mt_brand_details_d bd,    ',
'       pwc_mt_style_details_l l,    ',
'       pwc_mt_season_details_d d,    ',
'        apps.ar_customers@adf ac,    ',
'       pwc_ont_wvn_precosting_h poc    ',
' WHERE ac.customer_id = h.buyer_id    ',
'   AND h.header_id = bd.header_id    ',
'   AND bd.brand_line_id = l.brand_line_id    ',
'   AND l.style_line_id = d.style_line_id    ',
'   AND d.season_status = ''Open''    ',
'   AND d.season_identifier IS NOT NULL    ',
'   AND d.tracking_no IS NOT NULL    ',
'   AND d.division = ''Woven''    ',
'   AND d.tracking_no = poc.tracking_no    ',
'   AND poc.invoicing_unit_id = 91    ',
'   AND (:p25_organization_Id IS NOT NULL OR :p25_organization_Id IS NULL)    ',
'   AND h.tracking_mode = ''MS''    ',
'   AND NOT EXISTS (  ',
'       SELECT 1  ',
'         FROM pwc_mfg_osp_header hdr  ',
'        WHERE hdr.tracking_no = d.tracking_no  ',
'   )'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_cMaxlength=>250
,p_field_template=>wwv_flow_imp.id(220420025889811081)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_07=>'List'
,p_attribute_08=>'900'
,p_attribute_09=>'500'
);
