,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  CURSOR c_stn IS       ',
'    SELECT',
'      BPO_NO,',
'      STN,',
'      CHILD_STYLE_NO,',
'      COLOR,',
'      STYLE_CATEGORY,',
'      ORDERED_QTY,',
'      EXCESS_QUANTITY',
'    FROM StnVo where TRACKING_NO = :P25_TRACKING_NO and  INVOICING_UNIT_ID = 91;',
'',
'',
'BEGIN',
'  FOR rec IN c_stn LOOP',
'    INSERT INTO PWC_MFG_OSP_STN_LINE',
'      (HEADER_ID,',
'       STN_LINE_ID,',
'       BPO,',
'       STN,',
'       CHILD_STYLE_NO,',
'       COLOR,',
'       STYLE_CATEGORY,',
'       STN_QTY,',
'       EXCESS_ORDER_QTY,CREATION_DATE,LAST_UPDATED_DATE,CREATED_BY,LAST_UPDATED_BY)',
'    VALUES',
'      (:P25_HEADER_ID,                -- HEADER_ID (replace if sequence needed)',
'       (select nvl(max(STN_LINE_ID),0)+1 from  PWC_MFG_OSP_STN_LINE),    -- STN_LINE_ID (replace if sequence needed)',
'       rec.BPO_NO,',
'       rec.STN,',
'       rec.CHILD_STYLE_NO,',
'       rec.COLOR,',
'       rec.STYLE_CATEGORY,',
'       rec.ORDERED_QTY,',
'       rec.EXCESS_QUANTITY,',
'       sysdate,sysdate,1274,1274);',
'  END LOOP;',
'',
'  COMMIT;',
'END;',
' ins_osp_dep_assign(:P25_HEADER_ID);',
' PWC_INS_STN_LINE_SIZES_PROC(:P25_HEADER_ID,:P25_TRACKING_NO);',
'',
''))
,p_attribute_02=>'P25_HEADER_ID,P25_TRACKING_NO'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
