 p_id=>wwv_flow_imp.id(144583286439682525)
,p_event_id=>wwv_flow_imp.id(144583153266682524)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT LISTAGG(prha.segment1, '', '') ',
'           WITHIN GROUP (ORDER BY prha.segment1)',
'    INTO :REQUISITION_NUMBERS',
'    FROM pwc_mfg_osp_header osph',
'         JOIN apps.po_requisition_headers_all@adf prha',
'           ON osph.org_id = prha.org_id',
'    WHERE osph.header_id = :header_id',
'      AND osph.doc_no || '':'' || ',
'          REGEXP_SUBSTR(prha.interface_source_code, ''[^:]+'', 1, 2)',
'          = osph.doc_no || '':'' || :STN_LINE_ID;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :REQUISITION_NUMBERS := NULL;',
'',
'    WHEN TOO_MANY_ROWS THEN',
'        -- unlikely with LISTAGG, but included for safety',
'        :REQUISITION_NUMBERS := NULL;',
'',
'    WHEN OTHERS THEN',
'        -- log error if needed',
'        :REQUISITION_NUMBERS := ''ERROR: '' || SQLERRM;',
'END;'))
,p_attribute_02=>'HEADER_ID,STN_LINE_ID'
,p_attribute_03=>'REQUISITION_NUMBERS'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
