wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144582764202682520)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'OSP_ITEM_SUBINV_AJAX'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   v_error_msg   CLOB := NULL;',
'BEGIN',
'    APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'	''HEADER_ID: '' || :P25_HEADER_ID;',
'',
'   FOR rec IN (',
'       SELECT STN_LINE_ID',
'       FROM PWC_MFG_OSP_STN_LINE',
'       WHERE HEADER_ID = TO_NUMBER(apex_application.g_x01)',
'   )',
'   LOOP',
'      BEGIN',
'         APPS.PWC_MFG_OSP_PKG_COMBINED_APEX.osp_item_subinventory@ADF (',
'            p_resp_id => 20634,',
'            p_user    => 0,',
'            p_app_id  => 401,',
'            p_line    => rec.STN_LINE_ID',
'         );',
'',
'      EXCEPTION',
'         WHEN OTHERS THEN',
'            v_error_msg := v_error_msg || ',
'                           ''Line ID '' || rec.STN_LINE_ID || ',
'                           '' Error: '' || SQLERRM || CHR(10);',
'      END;',
'   END LOOP;',
'',
'   IF v_error_msg IS NULL THEN',
'      htp.p(''SUCCESS'');',
'   ELSE',
'      htp.p(''PARTIAL_SUCCESS:'' || v_error_msg);',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      htp.p(''FATAL_ERROR: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>144582764202682520
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144583369285682526)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PROCESS_OSP_BULK'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result VARCHAR2(4000);',
'    v_errors  CLOB;',
'BEGIN',
'    v_errors := '''';',
'',
'    FOR rec IN (',
'        SELECT HEADER_ID, STN_LINE_ID, COLOR, CHILD_STYLE_NO',
'        FROM PWC_MFG_OSP_STN_LINE',
'        WHERE HEADER_ID = :P25_HEADER_ID',
'    )',
'    LOOP',
'        BEGIN',
'            APPS.PWC_MFG_OSP_PKG_COMBINED_APEX.OSP_JOB_CREATION_BULK@ADF(',
'                rec.HEADER_ID,',
'                rec.STN_LINE_ID,',
'                rec.COLOR,',
'                rec.CHILD_STYLE_NO,',
'                1574,',
'                ''999'',',
'                ''999'',',
'                ''DENIM''',
'            );',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                -- collect errors for front-end',
'                v_errors := v_errors || ''STN_LINE_ID '' || rec.STN_LINE_ID || '': '' || SQLERRM || CHR(10);',
'        END;',
'    END LOOP;',
'',
'    -- Return JSON to JS',
'    apex_json.open_object;',
'    apex_json.write(''status'', ''completed'');',
'    IF v_errors IS NOT NULL AND v_errors != '''' THEN',
'        apex_json.write(''errors'', v_errors);',
'    END IF;',
'    apex_json.close_object;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''ERROR'');',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>144583369285682526
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144583823813682531)
,p_process_sequence=>30
