,p_process_name=>'CREATE_REQUISITION'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER := 0;',
'BEGIN',
'    FOR rec IN (',
'        SELECT STN_LINE_ID',
'        FROM PWC_MFG_OSP_STN_LINE',
'        WHERE HEADER_ID = :P25_HEADER_ID',
'    )',
'    LOOP',
'        apps.PWC_MFG_OSP_PKG_APEX.create_requisition@adf(rec.STN_LINE_ID, 0);',
'        v_count := v_count + 1;',
'    END LOOP;',
'',
'    htp.p(''{"status":"success","count":'' || v_count || ''}'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        htp.p(''{"status":"error","message":"'' || REPLACE(SQLERRM,''"'','''') || ''"}'');',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>144583823813682531
);
end;
