wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226833335021187081)
,p_name=>'P26_TRACKING_NO'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(226832579211187084)
,p_item_source_plug_id=>wwv_flow_imp.id(226832579211187084)
,p_prompt=>'Tracking No'
,p_source=>'TRACKING_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'ADF_TRACKING_NO_THREAD_HEAD'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH tracking_data AS (',
'    SELECT ac.customer_name,',
'          sl.style_name,',
'          sl.style_number,',
'          sl.style_identifier,',
'          sd.season_identifier,',
'          sd.season_name || ''.'' || sd.season_year season_name,',
'          bh.buyer_id,',
'          sl.style_category,',
'          sd.tracking_no,',
'          sd.division,',
'          bh.tracking_mode,',
'          bh.planning_mode,',
'          DECODE (bh.tracking_mode,',
'                  ''MS'', ''Master Style'',',
'                  ''CS'', ''Child Style''),',
'          DECODE (bh.planning_mode,  ''C'', ''Country'',  ''D'', ''DCPO''),',
'          bd.brand_description    ',
'     FROM pwc_mt_buyer_details_h bh,',
'          pwc_mt_brand_details_d bd,',
'          pwc_mt_style_details_l sl,',
'          pwc_mt_season_details_d sd,',
'          apps.ar_customers@adf ac',
'    WHERE     1 = 1',
'          AND bh.header_id = bd.header_id',
'          AND bd.brand_line_id = sl.brand_line_id',
'          AND sl.style_line_id = sd.style_line_id',
'          AND sd.season_identifier IS NOT NULL',
'          AND sd.tracking_no IS NOT NULL',
'          AND ac.customer_id = bh.buyer_id',
'          --AND sd.tracking_no =  p_tracking_no;',
')',
'',
'SELECT ',
'    ac.customer_name,',
'    td.style_name,',
'    td.style_number,',
'    td.season_name,',
'    h.tracking_no,',
'    td.brand_description,',
'    h.buyer_agent_name,',
'    h.buyer_id',
'',
'FROM pwc_ont_wvn_precosting_h h',
'',
'JOIN apps.ar_customers_v@adf ac',
'    ON h.buyer_id = ac.customer_id',
'JOIN tracking_data td',
'    ON td.tracking_no = h.tracking_no',
'',
'AND NOT EXISTS (',
'    SELECT 1',
'    FROM pwc_ont_wvn_thrd_consumption_h hi',
'    WHERE hi.tracking_no = h.tracking_no',
');'))
,p_lov_display_null=>'YES'
,p_cSize=>32
,p_cMaxlength=>255
,p_read_only_when=>'P26_HEADER_ID'
,p_read_only_when_type=>'ITEM_IS_NOT_NULL'
,p_field_template=>wwv_flow_imp.id(220419459940811080)
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--stretchInputs'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'DIALOG'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_07=>'Search and Select: Tracking No.'
,p_attribute_08=>'1100'
,p_attribute_10=>'CUSTOMER_NAME:P26_BUYER_NAME,BUYER_AGENT_NAME:P26_BUYER_AGENT_NAME,STYLE_NUMBER:P26_STYLE_NO,STYLE_NAME:P26_STYLE_NAME,SEASON_NAME:P26_SEASON_NAME,BRAND_DESCRIPTION:P26_BRAND_DESCRIPTION,BUYER_ID:P26_BUYER_ID'
);
