,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_name=>'set value'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    SELECT ',
'        ac.customer_name,',
'        pwc_master_tracking_data_func (h.tracking_no, ''STYLE_NAME'') style_name,',
'        pwc_master_tracking_data_func (h.tracking_no, ''STYLE_NO'') style_number,',
