,p_attribute_02=>'P26_TRACKING_NO'
,p_attribute_03=>'P26_VC_STYLE_NAME,P26_VC_BUYER_NAME,P26_VC_SEASON_NAME,P26_VC_BUYER_AGENT_NAME,P26_VC_BRAND_DESCRIPTION,P26_VC_STYLE_NO,P26_BUYER_ID'
