wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(227213731020037304)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(227211080532037277)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Item Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_duplicat_count NUMBER := 0;',
'    v_master_bom_Item_count NUMBER := 0;',
'    v_line_id NUMBER;',
'    v_thread_brand VARCHAR2(255);',
'    v_thread_shade VARCHAR2(255);',
'    v_thread_color VARCHAR2(255);',
'    v_thread_tkt VARCHAR2(255);',
'    v_thread_tex VARCHAR2(255);',
'    v_thread_count VARCHAR2(255);',
'    v_length VARCHAR2(50);',
'    v_meters VARCHAR2(50);',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN  -- Create',
'            -- Get Item Details from INVENTORY_ITEM_CODE',
'            BEGIN',
'                SELECT msi.attribute1, msi.attribute14, msi.attribute13, ',
'                       msi.attribute17, msi.attribute9, NVL(msi.attribute8,''N/A''),',
'                       msi.attribute11, msi.attribute27',
'                INTO v_thread_brand, v_thread_shade, v_thread_color, v_thread_tkt,',
'                     v_thread_tex, v_thread_count, v_length, v_meters',
'                FROM apps.mtl_system_items_kfv@adf msi',
'                JOIN pwc_flex_values_v fvv',
'                  ON msi.segment1 = fvv.flex_value',
'                JOIN apps.mtl_item_categories@adf mic',
'                  ON mic.inventory_item_id = msi.inventory_item_id',
'                 AND mic.organization_id = msi.organization_id',
'                WHERE msi.organization_id = pwc_organization_name(''Inventory Master Org'')',
'                  AND msi.inventory_item_status_code = ''Active''',
'                  AND fvv.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''',
'                  AND fvv.flex_value = ''451''',
'                  AND msi.segment3 IN (''11'',''21'',''31'')',
'                  AND msi.concatenated_segments = :INVENTORY_ITEM_CODE;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    raise_application_error(-20001, ''Item not found for code: '' || :INVENTORY_ITEM_CODE);',
'            END;',
'',
'            -- Check duplicate in grid',
'            SELECT COUNT(*)',
'            INTO v_duplicat_count',
'            FROM PWC_ONT_WVN_THRD_CONSUMPTION_L',
'            WHERE HEADER_ID = :P26_HEADER_ID',
'              AND INVENTORY_ITEM_ID = :INVENTORY_ITEM_ID;',
'',
'            IF v_duplicat_count > 0 THEN',
'                raise_application_error(-20001, ''This item is already tagged here: '' || :INVENTORY_ITEM_CODE);',
'            END IF;',
'',
'            -- Insert only if no duplicate',
'            INSERT INTO PWC_ONT_WVN_THRD_CONSUMPTION_L(',
'                LINE_ID, HEADER_ID, INVENTORY_ITEM_ID, CONSUMPTION,',
'                DEPARTMENT, STATUS_FLAG, THREAD_BRAND, THREAD_TKT, THREAD_TEX,',
'                THREAD_COUNT, THREAD_SHADE, THREAD_COLOR, LENGTH, METERS,',
'                CREATION_DATE, LAST_UPDATE_DATE',
'            ) VALUES (',
'                v_line_id, :P26_HEADER_ID, :INVENTORY_ITEM_ID, :CONSUMPTION,',
'                :DEPARTMENT, :STATUS_FLAG, v_thread_brand, v_thread_tkt, v_thread_tex,',
'                v_thread_count, v_thread_shade, v_thread_color, v_length, v_meters,',
'                :CREATION_DATE, :LAST_UPDATE_DATE',
'            ) return LINE_ID into :LINE_ID;',
'',
'        WHEN ''U'' THEN  -- Update',
'            UPDATE PWC_ONT_WVN_THRD_CONSUMPTION_L',
'            SET CONSUMPTION = :CONSUMPTION,',
'                DEPARTMENT = :DEPARTMENT,',
'                STATUS_FLAG = :STATUS_FLAG,',
'                LAST_UPDATE_DATE = :LAST_UPDATE_DATE',
'            WHERE LINE_ID = :LINE_ID;',
'',
'        WHEN ''D'' THEN  -- Delete',
'            -- Check if item exists in Master BOM',
'            SELECT COUNT(*)',
'            INTO v_master_bom_Item_count',
'            FROM PWC_ONT_WVN_MASTER_BOM_H h',
'            JOIN PWC_ONT_WVN_MASTER_BOM_ITEMS_L l',
'              ON h.HEADER_ID = l.HEADER_ID',
'            WHERE h.TRACKING_NO = (SELECT TRACKING_NO FROM  PWC_ONT_WVN_THRD_CONSUMPTION_H where HEADER_ID = :HEADER_ID)',
'              AND l.INVENTORY_ITEM_ID = :INVENTORY_ITEM_ID;',
'',
'            IF v_master_bom_Item_count > 0 THEN',
'                raise_application_error(-20001, ''Unable to delete this Line because this Item is tagged on Master BoM'');',
'            END IF;',
'',
'            DELETE FROM PWC_ONT_WVN_THRD_CONSUMPTION_L',
'            WHERE LINE_ID = :LINE_ID;',
'',
'    END CASE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>112646105863193028
);
