wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(228290337860826095)
,p_plug_name=>'Fill Material Items'
,p_region_name=>'your_ig_static_id'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-------------------1--------------------',
'SELECT *               ',
'  FROM (SELECT DISTINCT               ',
'               msib.concatenated_segments ordered_item,               ',
'               msib.inventory_item_id,               ',
'               CASE msib.segment3               ',
'                  WHEN ''01'' THEN ''Purchased''               ',
'                  WHEN ''02'' THEN ''Refabricated''               ',
'                  WHEN ''04'' THEN ''Manufactured''               ',
'                  ELSE ''Sample''               ',
'               END               ',
'                  status,               ',
'               msib.description,              ',
'               msib.description acc_desc,             ',
'               msib.primary_unit_of_measure,               ',
'               v.description prefix_description,               ',
'               msib.attribute5 supplier_legacy_code,               ',
'               msib.segment1,               ',
'               NULL color,               ',
'               0 consumption,               ',
'               (SELECT papx.full_name               ',
'                  FROM apps.per_people_x@adf papx               ',
'                 WHERE papx.person_id = msib.buyer_id)               ',
'                  buyer_name,               ',
'               msib.buyer_id,               ',
'               msib.attribute3 supplier_name,               ',
'               NULL thread_length,               ',
'               NULL department,               ',
'               NULL thread_brand,               ',
'               NULL thread_tkt,               ',
'               NULL thread_tex,               ',
'               NULL thread_count,               ',
'               msib.segment4,               ',
'               NULL thread_color,               ',
'               NULL cone_consumption,               ',
'               apps.PWC_ITEM_STATUS_DESCRIPTION@adf (msib.segment3) item_status,               ',
'               NULL hanger_no,               ',
'               NULL article_no,               ',
'               NULL order_line_id,               ',
'               NULL Job_M2,            ',
'               NULL RATE   ,          ',
'                        (SELECT  pv.vendor_name          ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR  , apps.po_vendors@adf pv          ',
'         WHERE     1 = 1            ',
'         and pv.vendor_id = lr.vendor_id          ',
'                    ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id)           ',
'          Last_supplier_name ,          ',
'               (SELECT NVL (MAX (LR.LAST_PUR_RATE), 0) LAST_PUR_RATE            ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR            ',
'         WHERE     1 = 1            ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id)           ',
'          LAST_PUR_RATE             ',
'          FROM apps.mtl_system_items_kfv@adf msib,               ',
'               pwc_flex_values_v@adf v,               ',
'               apps.mtl_item_categories@adf mic               ',
'         WHERE     msib.organization_id = :p27_ItemOrganizationId               ',
'               AND (msib.segment3 = ''11'' OR msib.segment3 = ''21'')               ',
'               AND msib.enabled_flag = ''Y''               ',
'               AND mic.inventory_item_id = msib.inventory_item_id               ',
'               AND mic.organization_id = msib.organization_id               ',
'               AND mic.category_set_id = 1               ',
'               AND v.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''               ',
'               AND msib.inventory_item_status_code = ''Active''               ',
'               AND v.flex_value = msib.segment1               ',
'               AND v.value_category = ''Item Prefix Security''               ',
'                AND (   :p_PrefixSecurity IS NOT NULL               ',
'                    OR :p_PrefixSecurity IS NULL)               ',
'               AND 1 = 2               ',
'               AND :p27_ItemType NOT IN (''Carton/Poly'', ''Thread'') ',
'------------------------2----------------------------              ',
'        UNION ALL               ',
'        SELECT DISTINCT               ',
'               msib.concatenated_segments ordered_item,               ',
'               msib.inventory_item_id,               ',
'                CASE msib.segment3               ',
'                  WHEN ''11'' THEN ''Local''               ',
'                  WHEN ''21'' THEN ''Imported''               ',
'                  ELSE ''N/A''               ',
'               END               ',
'                  status,               ',
'               msib.description,               ',
'               msib.description acc_desc,            ',
'               msib.primary_unit_of_measure,               ',
'               v.description value_description,               ',
'               msib.attribute5 supplier_legacy_code,               ',
'               msib.segment1,               ',
'               tcl.finish_garment_colour color,               ',
'               tcl.consumption,               ',
'               (SELECT papx.full_name               ',
'                  FROM apps.per_people_x@adf papx               ',
'                 WHERE papx.person_id = msib.buyer_id)               ',
'                  buyer_name,               ',
'               msib.buyer_id,               ',
'               msib.attribute3 supplier_name,               ',
'               REGEXP_REPLACE (msib.attribute11, ''[^0-9]'', '''') thread_length,               ',
'               tcl.department,               ',
'               tcl.thread_brand,               ',
'               tcl.thread_tkt,               ',
'               tcl.thread_tex,               ',
'               tcl.thread_count,               ',
'               tcl.thread_shade,               ',
'               tcl.thread_color,               ',
'               ROUND(tcl.consumption / msib.attribute27, 5)  cone_consumption,               ',
'               APPS.PWC_ITEM_STATUS_DESCRIPTION@adf (msib.segment3) item_status,               ',
'               NULL hanger_no,               ',
'               NULL article_no,               ',
'               NULL order_line_id,               ',
'               NULL Job_M2,            ',
'               NULL RATE    ,          ',
'               null Last_supplier_name,          ',
'                     (SELECT NVL (MAX (LR.LAST_PUR_RATE), 0) LAST_PUR_RATE            ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR            ',
'         WHERE     1 = 1            ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id)           ',
'          LAST_PUR_RATE                  ',
'          FROM apps.mtl_system_items_kfv@adf msib,               ',
'               pwc_flex_values_v@adf v,               ',
'               pwc_ont_wvn_thrd_consumption_h@adf tch,               ',
'               pwc_ont_wvn_thrd_consumption_l@adf tcl               ',
'         WHERE     msib.organization_id = :p27_ItemOrganizationId               ',
'               AND (msib.segment3 = ''11'' OR msib.segment3 = ''21'')               ',
'               AND msib.enabled_flag = ''Y''               ',
'               AND v.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''               ',
'               AND msib.inventory_item_status_code = ''Active''               ',
'               AND v.flex_value = msib.segment1               ',
'               AND NVL (tcl.status_flag, ''N'') = ''Y''               ',
'               AND tch.header_id = tcl.header_id               ',
'               AND tch.tracking_no = :p27_Tracking_No               ',
'               AND tcl.inventory_item_id = msib.inventory_item_id               ',
'               AND (   :p_PrefixSecurity IS NOT NULL               ',
'                    OR :p_PrefixSecurity IS NULL)               ',
'               AND msib.segment1 = ''451''               ',
'               AND :p27_ItemType = ''Thread''             ',
'               ---------------------------3----------------------------  ',
'               ',
'        UNION ALL               ',
'        SELECT DISTINCT               ',
'               msib.concatenated_segments ordered_item,               ',
'               msib.inventory_item_id,               ',
'               CASE msib.segment3               ',
'                  WHEN ''11'' THEN ''Local''               ',
'                  WHEN ''21'' THEN ''Imported''               ',
'                  ELSE ''N/A''               ',
'               END               ',
'                  status,               ',
'               msib.description,              ',
'               msib.description acc_desc,             ',
'               msib.primary_unit_of_measure,               ',
'               v.description value_description,               ',
'               msib.attribute5 supplier_legacy_code,               ',
'               msib.segment1,               ',
'               NULL color,               ',
'               ccl.consumption,               ',
'               (SELECT papx.full_name               ',
'                  FROM apps.per_people_x@adf papx               ',
'                 WHERE papx.person_id = msib.buyer_id)               ',
'                  buyer_name,               ',
'               msib.buyer_id,               ',
'               msib.attribute3 supplier_name,               ',
'               NULL thread_length,               ',
'               ccl.department,               ',
'               NULL thread_brand,               ',
'               NULL thread_tkt,               ',
'               NULL thread_tex,               ',
'               NULL thread_count,               ',
'               msib.segment4,               ',
'               NULL thread_color,               ',
'               NULL cone_consumption,               ',
'               APPS.PWC_ITEM_STATUS_DESCRIPTION@adf (msib.segment3) item_status,               ',
'               NULL hanger_no,               ',
'               NULL article_no,               ',
'               NULL order_line_id,               ',
'               NULL Job_M2,            ',
'               NULL RATE    ,          ',
'               (SELECT  pv.vendor_name          ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR  , apps.po_vendors@adf pv          ',
'         WHERE     1 = 1            ',
'         and pv.vendor_id = lr.vendor_id          ',
'                    ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id)           ',
'          Last_supplier_name ,          ',
'               (SELECT NVL (MAX (LR.LAST_PUR_RATE), 0) LAST_PUR_RATE            ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR            ',
'         WHERE     1 = 1            ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id) LAST_PUR_RATE          ',
'          FROM apps.mtl_system_items_kfv@adf msib,               ',
'               pwc_flex_values_v@adf v,               ',
'               pwc_ont_wvn_cart_consumption_h@adf cch,               ',
'               pwc_ont_wvn_cart_consumption_l@adf ccl               ',
'         WHERE     msib.organization_id = :p27_ItemOrganizationId               ',
'               AND (msib.segment3 = ''11'' OR msib.segment3 = ''21'')               ',
'               AND msib.segment1 IN (''820'',''463'',''464'',''465'')               ',
'               AND msib.enabled_flag = ''Y''               ',
'               AND v.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''               ',
'               AND msib.inventory_item_status_code = ''Active''               ',
'               AND v.flex_value = msib.segment1               ',
'               AND cch.header_id = ccl.header_id               ',
'               AND :p27_ItemType = ''Carton/Poly''               ',
'               AND cch.tracking_no = :p27_Tracking_No               ',
'               AND ccl.inventory_item_id = msib.inventory_item_id               ',
'               AND (   :p_PrefixSecurity IS NOT NULL               ',
'                    OR :p_PrefixSecurity IS NULL)  ',
'                     ',
'                    ---------------------------4----------------------------            ',
'         UNION ALL               ',
'                       SELECT DISTINCT               ',
'                       msib.concatenated_segments ordered_item,               ',
'                       msib.inventory_item_id,               ',
'                       CASE msib.segment3               ',
'                          WHEN ''11'' THEN ''Local''               ',
'                          WHEN ''21'' THEN ''Imported''               ',
'                          ELSE ''N/A''               ',
'                       END               ',
'                          status,               ',
'                       msib.description,             ',
'                       null acc_desc,              ',
'                       msib.primary_unit_of_measure,               ',
'                       v.description prefix_description,               ',
'                       msib.attribute5 supplier_legacy_code,               ',
'                       msib.segment1,               ',
'                       NULL color,               ',
'                       0 consumption,               ',
'                       (SELECT papx.full_name               ',
'                          FROM apps.per_people_x@adf papx               ',
'                         WHERE papx.person_id = msib.buyer_id)               ',
'                          buyer_name,               ',
'                       msib.buyer_id,               ',
'                       msib.attribute3 supplier_name,               ',
'                       NULL thread_length,               ',
'                       NULL department,               ',
'                       NULL thread_brand,               ',
'                       NULL thread_tkt,               ',
'                       NULL thread_tex,               ',
'                       NULL thread_count,               ',
'                       msib.segment4,               ',
'                       NULL thread_color,               ',
'                       NULL cone_consumption,               ',
'                       APPS.PWC_ITEM_STATUS_DESCRIPTION@adf (msib.segment3)               ',
'                          item_status,               ',
'                       (SELECT DISTINCT ffv.ATTRIBUTE17               ',
'                          FROM apps.fnd_flex_value_sets@adf ffvs,               ',
'                               apps.fnd_flex_values@adf ffv,               ',
'                               apps.fnd_flex_values_tl@adf ffvt               ',
'                         WHERE     ffvs.flex_value_set_id =               ',
'                                      ffv.flex_value_set_id               ',
'                               AND ffv.flex_value_id = ffvt.flex_value_id               ',
'                               AND ffvs.flex_value_set_name =               ',
'                                      ''MTML_K_INV_SYSTEM_ITEM_CODE''               ',
'                               AND ffv.flex_value = msib.segment2               ',
'                               AND ffv.parent_flex_value_low = msib.segment1)               ',
'                          hanger_no,               ',
'                       (SELECT DISTINCT ATTRIBUTE42               ',
'                          FROM apps.fnd_flex_value_sets@adf ffvs,               ',
'                               apps.fnd_flex_values@adf ffv,               ',
'                               apps.fnd_flex_values_tl@adf ffvt               ',
'                         WHERE     ffvs.flex_value_set_id =               ',
'                                      ffv.flex_value_set_id               ',
'                               AND ffv.flex_value_id = ffvt.flex_value_id               ',
'                               AND ffvs.flex_value_set_name =               ',
'                                      ''MTML_K_INV_SYSTEM_ITEM_CODE''               ',
'                               AND ffv.flex_value = msib.segment2               ',
'                               AND ffv.parent_flex_value_low = msib.segment1)               ',
'                          article_no,               ',
'                       olid.order_line_id order_line_id,               ',
'                     olid.ORDER_NUM  Job_M2  ,            ',
'                       olid.RATE   ,null Last_supplier_name ,          ',
'                       0 LAST_PUR_RATE          ',
'                  FROM apps.mtl_system_items_kfv@adf msib,               ',
'                       pwc_flex_values_v@adf v,               ',
'                       apps.mtl_item_categories@adf mic,               ',
'                       (SELECT order_line_id, mscl.inventory_item_id , mshl.ORDER_NUM,  mscl.rate            ',
'                          FROM mtml_sales_contract_lines_all@adf mscl, mtml_sales_contract_all@adf mshl where mscl.order_id = mshl.order_id) olid               ',
'                 WHERE     msib.organization_id = :p27_ItemOrganizationId               ',
'                       AND (   msib.segment3 = ''11''               ',
'                            OR msib.segment3 = ''21''               ',
'                            OR msib.segment3 = ''31''      ',
'                            OR msib.segment3 = ''22'' OR msib.segment3 =''61'')               ',
'                       AND msib.enabled_flag = ''Y''               ',
'                       AND mic.inventory_item_id = msib.inventory_item_id               ',
'                       AND mic.organization_id = msib.organization_id               ',
'                       AND msib.inventory_item_id = olid.inventory_item_id(+)               ',
'                      AND v.flex_value_set_name =  ''MTML_K_INV_SYSTEM_ITEM_PREFIX''               ',
'                       AND msib.inventory_item_status_code = ''Active''               ',
'                       AND v.flex_value = msib.segment1               ',
'                       AND msib.segment1 IN (''300'', ''301'', ''302'')               ',
'                       AND (   :p_PrefixSecurity IS NOT NULL               ',
'                            OR :p_PrefixSecurity IS NULL)               ',
'                       AND :p27_ItemType = ''Fabric''     ',
'                       ',
'                                 ',
'        UNION ALL      ',
'        ',
'        --------------------------------------5------------------------------------------         ',
'        SELECT DISTINCT               ',
'               msib.concatenated_segments ordered_item,               ',
'               msib.inventory_item_id,               ',
'                CASE msib.segment3               ',
'                  WHEN ''11'' THEN ''Local''               ',
'                  WHEN ''21'' THEN ''Imported''               ',
'                  ELSE ''N/A''               ',
'               END               ',
'                  status,               ',
'               msib.description,               ',
'               msib.description acc_desc,            ',
'               msib.primary_unit_of_measure,               ',
'               v.description prefix_description,               ',
'               msib.attribute5 supplier_legacy_code,               ',
'               msib.segment1,               ',
'               NULL color,               ',
'               0 consumption,               ',
'               (SELECT papx.full_name               ',
'                  FROM apps.per_people_x@adf papx               ',
'                 WHERE papx.person_id = msib.buyer_id)               ',
'                  buyer_name,               ',
'               msib.buyer_id,               ',
'               msib.attribute3 supplier_name,               ',
'               NULL thread_length,               ',
'               NULL department,               ',
'               NULL thread_brand,               ',
'               NULL thread_tkt,               ',
'               NULL thread_tex,               ',
'               NULL thread_count,               ',
'               msib.segment4,               ',
'               NULL thread_color,               ',
'               NULL cone_consumption,               ',
'               APPS.PWC_ITEM_STATUS_DESCRIPTION@adf (msib.segment3) item_status,               ',
'               NULL hanger_no,               ',
'               NULL article_no,               ',
'               NULL order_line_id,               ',
'               NULL Job_M2,            ',
'               NULL RATE     ,          ',
'               (SELECT  pv.vendor_name          ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR  , apps.po_vendors@adf pv          ',
'         WHERE     1 = 1            ',
'         and pv.vendor_id = lr.vendor_id          ',
'                    ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id)           ',
'          Last_supplier_name ,          ',
'               (SELECT NVL (MAX (LR.LAST_PUR_RATE), 0) LAST_PUR_RATE            ',
'          FROM apps.MTML_PO_ITEM_LAST_RATE@adf LR            ',
'         WHERE     1 = 1            ',
'               AND LR.ORGANIZATION_ID = 91            ',
'               AND LR.INVENTORY_ITEM_ID =            ',
'                      msib.INVENTORY_ITEM_ID          ',
'                      and msib.organization_id = lr.organization_id)           ',
'          LAST_PUR_RATE          ',
'                    ',
'          FROM apps.mtl_system_items_kfv@adf msib,               ',
'               pwc_flex_values_v@adf v,               ',
'               apps.mtl_item_categories@adf mic               ',
'         WHERE     msib.organization_id = :p27_ItemOrganizationId               ',
'               AND (msib.segment3 = ''11'' OR msib.segment3 = ''21'')               ',
'               AND msib.enabled_flag = ''Y''               ',
'               AND mic.inventory_item_id = msib.inventory_item_id               ',
'               AND mic.organization_id = msib.organization_id               ',
'                AND v.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''               ',
'               AND msib.inventory_item_status_code = ''Active''               ',
'               AND v.flex_value = msib.segment1               ',
'               AND (   :p_PrefixSecurity IS NOT NULL               ',
'                    OR :p_PrefixSecurity IS NULL)               ',
'               AND msib.segment1 IN (''450'',''452'',''453'',''454'',''455'',''456'',''457'',''458'',''459'',''460'',''461'',''462'')               ',
'               AND :p27_ItemType = ''Zipper/Button/Rivet'')',
'',
'',
'',
