wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(224733206742825390)
,p_plug_name=>'Fill BOP Information'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT Null line_id,  ',
'       bpo_info.header_id,        ',
'       bpo_info.bpo_number,        ',
'       bpo_info.classification,        ',
'       bpo_info.fit,        ',
'       bpo_info.retailer_dept,        ',
'       bpo_info.item_description,        ',
'       nvl(sum(bpo_info.ordered_qty), 0) ordered_qty,         ',
'       bpo_info.tracking_no,        ',
'       bpo_info.final_replace_bpo,        ',
'       bpo_info.ref_tba,        ',
'        (CASE        ',
'           WHEN nvl(sum(bpo_info.adjusted_quantity), 0) >= 0        ',
'           THEN        ',
'              nvl(sum(bpo_info.adjusted_quantity),0)        ',
'           ELSE        ',
'              0        ',
'        END)        ',
'          adjusted_quantity,     ',
'          nvl(sum(Extra_Cut_Quantity), 0)  Extra_Cut_Quantity      ',
'  FROM (  SELECT ooha.header_id,        ',
'                 ooha.cust_po_number bpo_number,        ',
'                 ooha.attribute3 classification,        ',
'                 wph.fit,        ',
'                 wph.retailer_dept,        ',
'                 wph.item_description,        ',
'                 SUM (oola.ordered_quantity) ordered_qty,        ',
'                 wph.tracking_no,        ',
'                 ooha.attribute12 final_replace_bpo,        ',
'                 ooha.attribute7 ref_tba,        ',
'                 (  SUM (oola.ordered_quantity)        ',
'                  - (NVL (        ',
'                        (SELECT SUM (oolai.ordered_quantity)        ',
'                           FROM apps.oe_order_headers_all@adf oohai,        ',
'                                apps.oe_order_lines_all@adf oolai        ',
'                          WHERE     oohai.header_id = oolai.header_id        ',
'                                AND oohai.flow_status_code <> ''CANCELLED''        ',
'                                AND oohai.attribute7 = ooha.cust_po_number        ',
'                                AND oohai.attribute4 = wph.tracking_no),        ',
'                        0)))        ',
'                    adjusted_quantity,     ',
'                         ',
'                    (select nvl(sum(SHIPMENT_QTY) , 0)     ',
'                        from XXPWC.PWC_ONT_WVN_SIZEWISE_DETAILS_H@adf      ',
'                        where sales_order_line_id = oola.line_id     ',
'                        and SALES_ORDER_ID = ooha.header_id)      ',
'                        Extra_Cut_Quantity       ',
'            FROM apps.oe_order_headers_all@adf ooha,        ',
'                 apps.oe_order_lines_all@adf oola,        ',
'                 pwc_ont_wvn_precosting_h@adf wph        ',
'           WHERE     ooha.attribute4 = TO_CHAR (wph.tracking_no)        ',
'                 AND ooha.header_id = oola.header_id        ',
'                 AND ooha.flow_status_code <> ''CANCELLED''        ',
'                 AND oola.ordered_quantity <> 0        ',
'                 AND NVL(oola.attribute2, ''No'') = ''No''       ',
'                 AND NVL (oola.attribute6, ''Active'') = ''Active''        ',
'                 AND wph.tracking_no = nvl(:P28_TRACKING_NO,wph.tracking_no)',
'                 AND NOT EXISTS        ',
'                            (SELECT 1        ',
'                               FROM pwc_ont_wvn_master_bom_bpo_l@adf bbl,        ',
'                                    pwc_ont_wvn_master_bom_h@adf mbh        ',
'                              WHERE     mbh.header_id = bbl.header_id        ',
'                                    AND ooha.cust_po_number = bbl.bpo_number        ',
'                                    AND ooha.header_id = bbl.sale_order_id        ',
'                                    AND mbh.tracking_no = wph.tracking_no)        ',
'        GROUP BY ooha.cust_po_number,        ',
'                 ooha.attribute3,        ',
'                 wph.fit,        ',
'                 wph.retailer_dept,        ',
'                 wph.tracking_no,        ',
'                 wph.item_description,        ',
'                 ooha.header_id,        ',
'                 ooha.attribute12,        ',
'                 ooha.attribute7,   ',
'                 oola.line_id   ',
'                 ) bpo_info  ',
'                 ',
' WHERE bpo_info.adjusted_quantity > 0   ',
' group by bpo_info.header_id,        ',
'       bpo_info.bpo_number,        ',
'       bpo_info.classification,        ',
'       bpo_info.fit,        ',
'       bpo_info.retailer_dept,        ',
'       bpo_info.item_description,   ',
'       bpo_info.tracking_no,        ',
'       bpo_info.final_replace_bpo,        ',
'       bpo_info.ref_tba',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P28_BPO_INFORMATION'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Fill BOP Information'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
