wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(127261184114310084)
,p_plug_name=>'Unit Allocation and OSP Planinng'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT HeaderEO.HEADER_ID,                ',
'       HeaderEO.OSP_DOC_NO,               ',
'---       pwc_master_tracking_data_func(HeaderEO.tracking_no, ''BUYER_ID'') BUYER_D,               ',
'---       pwc_master_tracking_data_func(HeaderEO.tracking_no, ''STYLE_NAME'') STYLE,               ',
'--       pwc_master_tracking_data_func(HeaderEO.tracking_no, ''SEASON_NAME'') SEASON,               ',
'       pmtd.buyer_id,',
'       pmtd.STYLE_NAME STYLE,',
'       pmtd.SEASON_NAME SEASON,',
'       HeaderEO.OSP_DATE,                ',
'       HeaderEO.TRACKING_NO,               ',
'       HeaderEO.REMARKS,                ',
'       HeaderEO.CREATION_DATE,                ',
'       HeaderEO.CREATED_BY,                ',
'       HeaderEO.LAST_UPDATED_BY,                ',
'       HeaderEO.ORG_ID,                ',
'       HeaderEO.LAST_UPDATED_DATE,                ',
'       HeaderEO.USERID,                ',
'       HeaderEO.RESPID,                ',
'       HeaderEO.RESPAPPLID,               ',
'   ---    pwc_master_traCking_data_func(HeaderEO.tracking_no, ''BUYER_NAME'') BUYER_NAME,  ',
'       pmtd.customer_name BUYER_NAME,              ',
'       HeaderEO.BRAND,                ',
'       HeaderEO.DOC_NO,                ',
'       NULL CURRENT_STYLE,               ',
'       NULL CURRENT_SEASON,               ',
'       HeaderEO.CLOSED_STYLE,               ',
'       HeaderEO.CLOSING_DATE,               ',
'      null  ORGANIC_AUTH,       ',
'      HeaderEO.ORGANIZATION_ID,      ',
'      org.name,',
'      --(SELECT  name  FROM inv_org_ou_pwc_v  WHERE organization_id = HeaderEO.ORGANIZATION_ID) INV_ORGANIZATION_NAME,     ',
'      HeaderEO.RETAILER_DEPT,     ',
'       pwc_master_tracking_data_func (HeaderEO.TRACKING_NO, ''STYLE_NO'') STYLE_NO,     ',
'       pwc_master_tracking_data_func (HeaderEO.TRACKING_NO, ''BRAND_DESCRIPTION'') BRAND_NAME,     ',
'       pwc_master_tracking_data_func (HeaderEO.tracking_no, ''TRACKING_MODE_DESC'') TRACKING_MODE,    ',
'       HeaderEO.DELETEFLAG,   ',
'       HeaderEO.CHILD_STYLE_NO_H   ',
'FROM PWC_MFG_OSP_HEADER HeaderEO',
'      LEFT JOIN inv_org_ou_pwc_v org',
'  ON org.organization_id = HeaderEO.ORGANIZATION_ID    ',
'  LEFT JOIN (   SELECT ac.customer_name,',
'          sl.style_name,',
'          sl.style_number,',
'          sl.style_identifier,',
'          sd.season_identifier,',
'          sd.season_name || ''.'' || sd.season_year SEASON_NAME,',
'          bh.buyer_id,',
'          sd.tracking_no,',
'          sl.style_category,',
'          sd.division,',
'          bh.tracking_mode,',
'          bh.planning_mode,',
'          DECODE (bh.tracking_mode,',
'                  ''MS'', ''Master Style'',',
'                  ''CS'', ''Child Style''),',
'          DECODE (bh.planning_mode,  ''C'', ''Country'',  ''D'', ''DCPO''),',
'          bd.brand_description',
'     FROM pwc_mt_buyer_details_h bh,',
'          pwc_mt_brand_details_d bd,',
'          pwc_mt_style_details_l sl,',
'          pwc_mt_season_details_d sd,',
'          apps.ar_customers@adf ac',
'    WHERE     1 = 1',
'          AND bh.header_id = bd.header_id',
'          AND bd.brand_line_id = sl.brand_line_id',
'          AND sl.style_line_id = sd.style_line_id',
'          AND sd.season_identifier IS NOT NULL',
'          AND sd.tracking_no IS NOT NULL',
'          AND ac.customer_id = bh.buyer_id',
'          --AND sd.tracking_no = p_tracking_no;',
'          ) pmtd',
'          on pmtd.tracking_no = HeaderEO.tracking_no ',
'        ---  and header_id > 3796',
'',
''))
