,p_plug_name=>'Fabric Roll Inventory'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    H.HEADER_ID,',
'    H.HEADER_NO,',
'    L.TRACKING_NO,',
'    H.VERSION_NO,',
'    H.SHIPMENT_NUM,',
'    H.SHIPMENT_NUM AS SHIPMENT_NUM_SEARCH,',
'    H.COMM_INVOICE_NO,',
'    H.CHALLAN_NO,',
'    H.DOCUMENT_DATE,',
'    H.LOAN_PROVIDER,',
'    /* Organization Name */',
'    (SELECT NAME FROM INV_ORG_OU_PWC_V WHERE ORGANIZATION_ID = H.ORGANIZATION_ID ) AS INV_ORGANIZATION_NAME,',
'    H.ORGANIZATION_ID,',
'    /* View Attribute */',
'    (SELECT NVL(HOU.TYPE, ''01'') FROM APPS.HR_ORGANIZATION_UNITS@ADF HOU WHERE HOU.ORGANIZATION_ID = H.ORGANIZATION_ID AND HOU.TYPE IS NOT NULL ) AS VIEW_ATTR,',
'    H.DOC_TYPE,',
'    H.CONSIGNMENT_NUMBER,',
'    H.CREATED_BY,',
'    H.CREATION_DATE,',
'    H.LAST_UPDATED_BY,',
'    H.LAST_UPDATE_DATE',
'FROM PWC_INV_FABRIC_ROLL_H H',
'LEFT JOIN PWC_INV_FABRIC_ROLL_L L',
'       ON H.HEADER_ID = L.HEADER_ID',
'',
'ORDER BY H.CREATION_DATE DESC;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Fabric Roll Inventory'
);
