wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(341501847901606215)
,p_name=>'PRODUCT_CLASSIFICATION'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'PRODUCT_CLASSIFICATION'
,p_data_type=>'VARCHAR2'
,p_session_state_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_POPUP_LOV'
,p_heading=>'Prod. Classification'
,p_heading_alignment=>'LEFT'
,p_display_sequence=>140
,p_value_alignment=>'LEFT'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
,p_is_required=>false
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT ',
'       qa_child.character3 product_classification, ',
'       qa_child.character2 product_classification_desc ',
'  FROM apps.qa_results_v@adf qa_parent, ',
'       apps.qa_results_v@adf qa_child, ',
'       apps.qa_pc_results_relationship@adf qpr ',
' WHERE     qa_parent.occurrence = qpr.parent_occurrence ',
'       AND qa_parent.plan_id = qpr.parent_plan_id ',
'       AND qa_parent.collection_id = qpr.parent_collection_id ',
'       AND qa_child.occurrence = qpr.child_occurrence ',
'       AND qa_child.plan_id = qpr.child_plan_id ',
'       AND qa_child.character1 IS NOT NULL ',
'       AND qa_child.collection_id = qpr.child_collection_id ',
'       AND qa_parent.name = ''PWC_OM_WVN_PRODUCT_TYPE'' ',
'       AND qa_child.name = ''PWC_OM_WVN_PRODUCT_CLASSI'' ',
'       AND qa_parent.character2 = :P32_PRODUCT_TYPE ',
'       AND :P32_COSTING_UOM = ''PC'' ',
'UNION ',
'SELECT qrv.character3 product_classification, ',
'       qrv.character2 product_classification_desc ',
'  FROM apps.qa_results_v@adf qrv ',
