,p_plug_display_sequence=>50
,p_plug_grid_column_span=>6
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * from (SELECT PwcOntWovenPreCostingEmbelis1.DETAIL_ID, ',
'       PwcOntWovenPreCostingEmbelis1.LINE_ID, ',
'       PwcOntWovenPreCostingEmbelis1.PROCESS_TYPE, ',
'       PwcOntWovenPreCostingEmbelis1.PROCESS_ID, ',
'       PwcOntWovenPreCostingEmbelis1.QUOTED_PRICE, ',
'       PwcOntWovenPreCostingEmbelis1.BUDGETED_PRICE, ',
'       PwcOntWovenPreCostingEmbelis1.CREATED_BY, ',
'       PwcOntWovenPreCostingEmbelis1.CREATION_DATE, ',
'       PwcOntWovenPreCostingEmbelis1.LAST_UPDATE_DATE, ',
'       PwcOntWovenPreCostingEmbelis1.LAST_UPDATED_BY, ',
'      /* (SELECT ffv.description   FROM pwc_flex_values_v ffv  WHERE     ffv.flex_value_Set_name = ''PWC_OM_POC_EMBROIDERY_PROCESS''   ',
'            AND ''Embroidery'' = PwcOntWovenPreCostingEmbelis1.PROCESS_TYPE    ',
'             AND ffv.flex_value =    LPAD (PwcOntWovenPreCostingEmbelis1.PROCESS_ID, 3, ''0'')',
'             UNION ',
'             SELECT ffv.description  ',
'             FROM pwc_flex_values_v ffv  ',
'            WHERE     ffv.flex_value_Set_name = ''PWC_OM_POC_PRINTING_PROCESS'' ',
'           AND ''Printing'' = PwcOntWovenPreCostingEmbelis1.PROCESS_TYPE ',
'            AND ffv.flex_value =   LPAD (PwcOntWovenPreCostingEmbelis1.PROCESS_ID, 3, ''0'')) AS PROCESS_NAME, */',
'       PwcOntWovenPreCostingEmbelis1.PROCESS_DESCRIPTION',
'FROM  PWC_ONT_WVN_PRECOSTING_PRNT_D PwcOntWovenPreCostingEmbelis1)',
'where PROCESS_TYPE = ''Printing''',
''))
