'select * from (SELECT PwcOntWovenPreCostingEmbelis1.DETAIL_ID, ',
'       PwcOntWovenPreCostingEmbelis1.LINE_ID, ',
'       PwcOntWovenPreCostingEmbelis1.PROCESS_TYPE, ',
