'DECLARE',
'    v_style_name  VARCHAR2(200);',
'    v_season_name VARCHAR2(200);',
'    v_style_no    VARCHAR2(100);',
'    v_brand_name  VARCHAR2(100);',
'BEGIN',
'    SELECT',
'        pwc_master_tracking_data_func(:P32_TRACKING_NO, ''STYLE_NAME''),',
'        pwc_master_tracking_data_func(:P32_TRACKING_NO, ''SEASON_NAME''),',
'        pwc_master_tracking_data_func(:P32_TRACKING_NO, ''STYLE_NO''),',
'        h.BRAND_NAME',
'    INTO',
'        v_style_name,',
'        v_season_name,',
'        v_style_no,',
'        v_brand_name',
'    FROM PWC_ONT_WVN_PRECOSTING_H h',
'    WHERE h.TRACKING_NO = :P32_TRACKING_NO;',
'',
'    -- Assign to page items',
'    :P32_STYLE_NAME  := v_style_name;',
'    :P32_SEASON_NAME := v_season_name;',
'    :P32_STYLE_NUMBER    := v_style_no;',
'    :P32_BRAND_NAME  := v_brand_name;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P32_STYLE_NAME  := NULL;',
'        :P32_SEASON_NAME := NULL;',
'        :P32_STYLE_NUMBER    := NULL;',
'        :P32_BRAND_NAME  := NULL;',
'END;',
'',
''))
