wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(130122508828411633)
,p_plug_name=>'Line IG'
,p_region_name=>'FRI_LINE'
,p_parent_plug_id=>wwv_flow_imp.id(131919358778883548)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    LINE.LINE_ID,',
'    LINE.HEADER_ID,',
'    LINE.COLOR,',
'    LINE.TOTAL_ROLLS,',
'    LINE.TOTAL_YARDS,',
'    LINE.FAB_CONST,',
'    LINE.FAB_COMP,',
'    LINE.FAB_OUNCE,',
'    LINE.INVENTORY_ITEM_ID,',
'    LINE.TOTAL_QTY,',
'    LINE.SUBINVENTORY_CODE,',
'    LINE.TRACKING_NO,',
'    LINE.INVOICE_QTY,',
'    LINE.ACCUMULATED_BLANKET_ISSUANCE,',
'    LINE.TOTAL_LENGTH,',
'    LINE.ROLL_SHIP_NUMBER,',
'    LINE.LINE_REMARKS,',
'    LINE.CHILD_TRACKING_NO,',
'    LINE.UOM_LINE,',
'    LINE.PHYSICAL_LOCATION,',
'    LINE.CREATED_BY,',
'    LINE.CREATION_DATE,',
'    LINE.LAST_UPDATE_DATE,',
'    LINE.LAST_UPDATED_BY,',
'    PWC_MASTER_TRACKING_DATA_FUNC (LINE.tracking_no, ''BUYER_NAME'') AS BUYER_NAME,',
'    PWC_MASTER_TRACKING_DATA_FUNC (LINE.tracking_no, ''STYLE_NAME'') AS STYLE,',
'    PWC_MASTER_TRACKING_DATA_FUNC (LINE.tracking_no, ''STYLE_NO'') AS STYLE_NO,',
'    PWC_MASTER_TRACKING_DATA_FUNC (LINE.tracking_no, ''SEASON_NAME'')  AS SEASON,',
'    (',
'        SELECT MSI.DESCRIPTION',
'        FROM APPS.MTL_SYSTEM_ITEMS@adf MSI',
'        WHERE     MSI.ORGANIZATION_ID = pwc_organization_name (''Inventory Master Org'')',
'            AND MSI.INVENTORY_ITEM_ID = LINE.INVENTORY_ITEM_ID',
'    ) AS ITEM_DESC,',
'    (',
'        SELECT COUNT (*)',
'        FROM PWC_INV_FABRIC_ROLL_D d',
'        WHERE     d.transfer_selection = ''Y''',
'            AND d.line_id = LINE.LINE_ID',
'    ) AS SELECTED_ROLLS_COUNT,',
'    NVL(',
'        (SELECT SUM (d.Roll_Length_Yards)',
'        FROM PWC_INV_FABRIC_ROLL_D d',
'        WHERE     d.transfer_selection = ''Y''',
'        AND d.line_id = LINE.LINE_ID)',
'        , 0',
'    ) AS SELECTED_ROLLS_L_YARDS,',
'    NVL(',
'        (SELECT SUM (d.blanket_issuance)',
'        FROM PWC_INV_FABRIC_ROLL_D d',
'        WHERE     d.transfer_selection = ''Y''',
'            AND d.line_id = LINE.LINE_ID)',
'        , 0',
'    ) AS SELECTED_ROLLS_BL_ISSUE,',
'    NVL(',
'        (SELECT SUM (d.balance_qty)',
'        FROM PWC_INV_FABRIC_ROLL_D d',
'        WHERE     d.transfer_selection = ''Y''',
'        AND d.line_id = LINE.LINE_ID),',
'    0) AS SELECTED_ROLLS_BAL_QTY,',
'    (',
'        SELECT MSI.DESCRIPTION',
'        FROM APPS.MTL_SYSTEM_ITEMS@adf MSI',
'        WHERE     MSI.ORGANIZATION_ID = pwc_organization_name (''Inventory Master Org'')',
'            AND MSI.INVENTORY_ITEM_ID = LINE.INVENTORY_ITEM_ID',
'    ) AS ITEM_DESC_FAB,',
'    (SELECT uom_class',
'    FROM apps.mtl_units_of_measure@adf',
'    WHERE unit_of_measure = LINE.UOM_LINE)',
'    AS ITEM_UOM_CLASS,',
'    get_grn_number ( LINE.LINE_ID) AS ROLL_GRN_NUMBER,',
'    LINE.transfer_tracking_no,',
'    LINE.transfer_subinventory,',
'    get_on_handqty ( LINE.LINE_ID) AS ONHAND_QUANTITY,',
'    (  LINE.TOTAL_QTY - get_on_handqty ( LINE.LINE_ID)) balance_qty,',
'    LINE.hanger_no,',
'    LINE.job_name',
'FROM PWC_INV_FABRIC_ROLL_L LINE',
'where HEADER_ID = :P33_HEADER_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Line IG'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
