wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(133106425407526101)
,p_event_id=>wwv_flow_imp.id(131919554806883550)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Ajax Call'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Start - Auto Update Select value and Save Roll IG */',
'var region = apex.region("ROLL_IG");',
'var ig = region.widget();',
'var gridView = ig.interactiveGrid("getViews", "grid");',
'var model = gridView.model;',
'var selectedRecords = gridView.getSelectedRecords();',
'//console.log(''ROLL IG CODE DEBUG'');',
'',
'// Update selected rows',
'if (selectedRecords.length > 0) {',
'    selectedRecords.forEach(function(record) {',
'        model.setValue(record, "TRANSFER_SELECTION", "Y"); // Column name',
'    });',
'',
'    // Mark changes and save automatically',
'    region.call("getActions").invoke("save");',
'}',
'/* End - Auto Update Select value and Save Roll IG */',
'',
'',
'/* Start - Call Process GRN AJAX CALL ON SELECED LINE IG ROW*/',
'var ig$ = apex.region("FRI_LINE").widget();',
'var grid = ig$.interactiveGrid("getViews", "grid");',
'var model = grid.model;',
'',
'// Selected records',
'var selectedRecords = grid.view$.grid("getSelectedRecords");',
'//console.log(''LINE IG CODE DEBUG'');',
'',
'if (selectedRecords.length === 0) {',
'    apex.message.alert("Please add or select at least one Record in Line.");',
'    return;',
'} ',
'',
'if (selectedRecords.length > 1) {',
'    apex.message.alert("Please select only one record to apply GRN.");',
'    return;',
'}',
'',
'// Function to process one record at a time',
'function processRow(index) {',
'    var record = selectedRecords[index];',
'    //console.log(''debug code'');',
'',
'    // Get values from IG columns',
'    var itemId   = model.getValue(record, "INVENTORY_ITEM_ID");',
'    //var lineId   = model.getValue(record, "LINE_ID");',
'    console.log(''itemId: ''+ itemId);',
'',
'    // Call AJAX process',
'    apex.server.process(',
'    "PROCESS_GRN_AJAX_CALL",',
'    {',
'        x01: itemId',
'    },',
'    {',
'        dataType: "text",',
'        success: function (pData) {',
'',
'            if (pData && pData.startsWith("ERROR")) {',
'                apex.message.alert(pData);',
'                return;',
'            }',
'',
'            apex.message.showPageSuccess(pData);',
'',
unistr('            // \2705 Safe refresh (delay + guard)'),
'            safeRefreshIG("FRI_LINE");',
'',
'            // setTimeout(function () {',
'            //     var line = apex.region("FRI_LINE");',
'',
'            //     if (line) {',
'            //         line.refresh();',
'            //     }               ',
'            // }, 300);',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            apex.message.alert("AJAX failed: " + errorThrown);',
'        }',
'    });',
'}',
'',
'// Start processing first row',
'processRow(0);',
'',
'/* USED FOR DEBUG */',
'//apex.message.alert("DA CALL SUCCFULLY " + $v("P19_RATIOPLAN_ID"));'))
);
