wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(133106903873526106)
,p_event_id=>wwv_flow_imp.id(133106831587526105)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var ig$ = apex.region("FRI_LINE").widget();',
'var grid = ig$.interactiveGrid("getViews", "grid");',
'var model = grid.model;',
'',
'// Selected records',
'var selectedRecords = grid.view$.grid("getSelectedRecords");',
'console.log(''debug code'');',
'',
'if (selectedRecords.length === 0) {',
'    apex.message.alert("Please add or select at least one Record in Line.");',
'    return;',
'}',
'',
'if (selectedRecords.length > 1) {',
'    apex.message.alert("Please select only one record for ''Style to Style Transfer''");',
'    return;',
'}',
'',
'',
'var record = selectedRecords[0];',
'//console.log(''debug code'');',
'',
'// Get values from IG columns',
'var transferTrackingNo = model.getValue(record, "TRANSFER_TRACKING_NO");',
'//var transferTrackingNo = model.getDisplayValue(record, "TRANSFER_TRACKING_NO");',
'if (!transferTrackingNo.d) {',
'    apex.message.alert("Transfer Tracking Number field is blank.");',
'    return;',
'}',
'',
'var transferSubInventory = model.getValue(record, "TRANSFER_SUBINVENTORY");',
'if (!transferSubInventory.d) {',
'    apex.message.alert("Transfer Sub Inventory field is blank.");',
'    return;',
'}',
'',
'var itemId   = model.getValue(record, "INVENTORY_ITEM_ID");',
'console.log(''Item Id: ''+ itemId);',
'var lineId   = model.getValue(record, "LINE_ID");',
'console.log(''line Id: ''+ lineId);',
'var headerId = apex.item("P33_HEADER_ID").getValue();',
'console.log(''header Id: ''+ headerId);',
'',
'//console.log(''debug code'');',
'',
'// Call AJAX process',
'apex.server.process(',
'    "STYLE_TRANSFER_AJAX",',
'    {',
'        x01: itemId,',
'        x02: lineId,',
'        x03: headerId',
'    },',
'    {',
'        dataType: "text",',
'        success: function (pData) {',
'',
'            if (pData && pData.startsWith("ERROR")) {',
'                apex.message.alert(pData);',
'                return;',
'            }',
'            apex.message.showPageSuccess(pData);',
unistr('            // \2705 Safe refresh (delay + guard)'),
'            safeRefreshIG("FRI_LINE");',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            apex.message.alert("AJAX failed: " + errorThrown);',
'        }',
'    }',
');',
''))
);
