wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(131915213493883507)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(130122508828411633)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Line'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_SHIPMENT_NUM NUMBER := :P33_SHIPMENT_NUM;',
'    CURSOR C_FILL_DATA IS',
'        SELECT ',
'            aa.hanger_no ,   ',
'            aa.job_name,',
'            aa.color,                   ',
'            aa.construction fab_const,                   ',
'            aa.composition fab_comp,                   ',
'            aa.fab_ounce,                   ',
'            aa.inventory_item_id,                   ',
'            aa.quantity TOTAL_QTY,                   ',
'            aa.quantity invoice_quantity,                   ',
'            aa.tracking_no,                   ',
'            child_tracking_no,                ',
'            --aa.ship_number,                   ',
'            aa.description item_desc,                   ',
'            aa.primary_unit_of_measure,                   ',
'            aa.uom_class,                   ',
'            pwc_master_tracking_data_func (aa.tracking_no, ''BUYER_NAME'') buyer_name,                   ',
'            pwc_master_tracking_data_func (aa.tracking_no, ''STYLE_NAME'') style_name,                   ',
'            pwc_master_tracking_data_func (aa.tracking_no, ''STYLE_NO'')   style_no,                   ',
'            pwc_master_tracking_data_func (aa.tracking_no, ''SEASON_NAME'')season_name    ',
'',
'        FROM ',
'            (',
'                SELECT DISTINCT                                  ',
'                    pla.quantity,                   ',
'                    pha.segment1 po_number,                   ',
'                    msi.inventory_item_id,                   ',
'                    msi.primary_unit_of_measure,                   ',
'                    msi.description,                   ',
'                    msi.attribute9 construction,                   ',
'                    msi.attribute8 composition,                   ',
'                    msi.attribute12 fab_ounce,                   ',
'                    (',
'                        SELECT description                   ',
'                        FROM pwc_flex_values_v                   ',
'                        WHERE     flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_COLOR/SHADE''                   ',
'                            AND flex_value = msi.segment4',
'                    ) color,                   ',
'                    pla.VENDOR_PRODUCT_NUM tracking_no,                   ',
'                    null child_tracking_no,                 ',
'                    muom.uom_class,    ',
'                    (',
'                        SELECT distinct ffv.ATTRIBUTE17    ',
'                        FROM apps.fnd_flex_value_sets@adf ffvs ,    ',
'                             apps.fnd_flex_values@adf ffv,    ',
'                             apps.fnd_flex_values_tl@adf ffvt    ',
'                        WHERE  ffvs.flex_value_set_id     = ffv.flex_value_set_id    ',
'                            and ffv.flex_value_id      = ffvt.flex_value_id    ',
'                            --and ffv.flex_value_set_id = 1014168     ',
'                            --and PARENT_FLEX_VALUE_LOW in (''300'',''301'') --prefix    ',
'                            and ffvs.flex_value_set_name =  ''MTML_K_INV_SYSTEM_ITEM_CODE''    ',
'                            and ffv.flex_value = msi.segment2 --item code param    ',
'                            and ffv.parent_flex_value_low = msi.segment1 -- prefix param    ',
'                    )hanger_no,   ',
'                    --pla.attribute1 job_name ',
'                    (',
'                        select ',
'                            LISTAGG(M2_JOB_NAME, '', '') WITHIN GROUP (ORDER BY M2_JOB_NAME) AS Concatenated_M2_JOB_NAME ',
'                        from PWC_ONT_WVN_MASTER_BOM_ITEMS_L bl,PWC_ONT_WVN_MASTER_BOM_H bh ',
'                        where BL.HEADER_ID = BH.HEADER_ID ',
'                        and BH.TRACKING_NO = pla.VENDOR_PRODUCT_NUM ',
'                        --and BL.HEADER_ID = 1165 ',
'                        and BL.ITEM_TYPE = ''Fabric''  ',
'                        and ITEM_PREFIX in (300,301) ',
'                        and BL.INVENTORY_ITEM_ID = msi.inventory_item_id',
'                    )  job_name ',
'                FROM apps.po_line_locations_all@adf plla,                   ',
'                    apps.org_organization_definitions@adf ood,                   ',
'                    apps.po_headers_all@adf pha,                   ',
'                    pwc_flex_values_v fvv,                   ',
'                    apps.mtl_system_items@adf msi,                   ',
'                    apps.ap_suppliers@adf ap,                   ',
'                    apps.mtl_units_of_measure@adf muom,            ',
'                    apps.po_lines_all@adf pla            ',
'                WHERE 1=1               ',
'                    and pha.po_header_id = plla.po_header_id            ',
'                    and pha.po_header_id = pla.PO_header_id            ',
'                    and plla.po_line_id = pla.po_line_id                 ',
'                    AND fvv.flex_value_set_name = ''MTML_K_INV_SYSTEM_ITEM_PREFIX''                   ',
'                    --AND fvv.value_category = ''Item Prefix Security''                   ',
'                    --AND fvv.attribute1 IS NOT NULL                   ',
'                    AND ap.vendor_id = pha.vendor_id             ',
'                    and msi.segment1 in (300,301)                  ',
'                    AND pha.org_id = ood.operating_unit                   ',
'                    AND msi.organization_id = ood.organization_id                   ',
'                    AND muom.unit_of_measure = msi.primary_unit_of_measure                   ',
'                    AND ood.organization_id = 91             ',
'                    and pha.AUTHORIZATION_STATUS = ''APPROVED''              ',
'                    and pha.segment1 = V_SHIPMENT_NUM              ',
'                    --AND isha.ship_num || ''.'' || islg.ship_line_group_num = V_SHIPMENT_NUM                  ',
'                    AND msi.segment1 = fvv.flex_value                   ',
'                    AND msi.inventory_item_id = PLA.ITEM_ID             ',
'                    and NVL(pla.CANCEL_FLAG, ''N'') <> ''Y''        ',
'                    --   and msi.attribute9 is not null                   ',
'                    --  and msi.attribute8 is not null     ',
'                    --AND fvv.attribute1 = ''51''                 ',
'            ) aa                   ',
'        WHERE NOT EXISTS                   ',
'            (',
'                SELECT DISTINCT 1                   ',
'                FROM pwc_inv_fabric_roll_h mmh, pwc_inv_fabric_roll_l mml                   ',
'                WHERE     mmh.header_id = mml.header_id                 ',
'                    AND mml.color = TRIM (aa.color)                   ',
'                    AND mmh.shipment_num = V_SHIPMENT_NUM                   ',
'                    AND mmh.organization_id = 91                   ',
'                    AND NVL (mml.fab_const, ''N/A'') =                   ',
'                         NVL (aa.construction, ''N/A'')                   ',
'                    AND mml.fab_comp = aa.composition                   ',
'                    AND mml.tracking_no = aa.tracking_no                   ',
'                    AND NVL (mml.child_tracking_no, ''N/A'') =               ',
'                         NVL (aa.child_tracking_no, ''N/A'')               ',
'                    /*AND NVL (mml.roll_ship_number, ''N/A'') = aa.ship_number        ',
'                    Aamir and Hamza 28-06-2022*/        ',
'            );',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''P19_TRACKING_NO: '' || :P19_TRACKING_NO ||',
'            -- ''P19_COLOR: '' || :P19_COLOR;',
'',
'            FOR R IN C_FILL_DATA LOOP',
'                INSERT INTO PWC_INV_FABRIC_ROLL_L ',
'                    (',
'                        HEADER_ID,HANGER_NO,JOB_NAME,TOTAL_QTY,COLOR,TOTAL_ROLLS,TOTAL_LENGTH,TOTAL_YARDS',
'                        ,UOM_LINE,TRACKING_NO,SUBINVENTORY_CODE,FAB_CONST,FAB_COMP,FAB_OUNCE,INVENTORY_ITEM_ID',
'                        ,INVOICE_QTY,ROLL_SHIP_NUMBER,LINE_REMARKS',
'                        ,CHILD_TRACKING_NO,PHYSICAL_LOCATION,TRANSFER_TRACKING_NO,TRANSFER_SUBINVENTORY                   ',
'                    ) ',
'                VALUES ',
'                    (',
'                        :P33_HEADER_ID,R.HANGER_NO,R.JOB_NAME,R.TOTAL_QTY,R.COLOR,0,0,0',
'                        ,''Meters'',R.TRACKING_NO,''Fabric'',R.FAB_CONST,R.FAB_COMP,R.FAB_OUNCE,R.INVENTORY_ITEM_ID',
'                        ,R.TOTAL_QTY,:ROLL_SHIP_NUMBER,:LINE_REMARKS',
'                        ,:CHILD_TRACKING_NO,:PHYSICAL_LOCATION,:TRANSFER_TRACKING_NO,:TRANSFER_SUBINVENTORY                    ',
'                    )',
'                RETURNING LINE_ID INTO :LINE_ID;                ',
'            END LOOP;',
'            commit;',
'        ',
'        WHEN ''U'' THEN',
'            UPDATE PWC_INV_FABRIC_ROLL_L',
'                SET LINE_REMARKS = :LINE_REMARKS,',
'                    TRANSFER_TRACKING_NO = :TRANSFER_TRACKING_NO,',
'                    TRANSFER_SUBINVENTORY = :TRANSFER_SUBINVENTORY',
'            where LINE_ID = :LINE_ID;',
'        ',
'        WHEN ''D'' THEN',
'            delete from PWC_INV_FABRIC_ROLL_L',
'            where LINE_ID = :LINE_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>131915213493883507
);
end;
