,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Rolls - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            -- USED FOR DEBUG CODE',
'            -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            -- ''P19_TRACKING_NO: '' || :P19_TRACKING_NO ||',
'            -- ''P19_COLOR: '' || :P19_COLOR;',
'            INSERT INTO PWC_INV_FABRIC_ROLL_D ',
'                (',
'                    LINE_ID,TRANSFER_SELECTION,ACCEPTED_FLAG,ROLL_NO,ROLL_SR_NO,UOM,ROLL_WIDTH,',
'                    SHRINK_LENGTH,SHRINK_WIDTH,SHADE,REMARKS,SUPPLIER_SERIAL_NO,ROLL_LENGTH',
'                ) ',
'            VALUES ',
'                (',
'                    :LINE_ID,:TRANSFER_SELECTION,:ACCEPTED_FLAG,:ROLL_NO,:ROLL_SR_NO,:UOM,:ROLL_WIDTH,',
'                    :SHRINK_LENGTH,:SHRINK_WIDTH,:SHADE,:REMARKS,:SUPPLIER_SERIAL_NO,:ROLL_LENGTH',
'                )',
'            RETURNING DETAIL_ID INTO :DETAIL_ID;                        ',
'        WHEN ''U'' THEN',
'            UPDATE PWC_INV_FABRIC_ROLL_D',
'                SET TRANSFER_SELECTION = :TRANSFER_SELECTION,',
'                    ACCEPTED_FLAG = :ACCEPTED_FLAG,',
'                    UOM = :UOM,',
'                    REMARKS = :REMARKS',
'            where DETAIL_ID = :DETAIL_ID;',
'        ',
