wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(131918003214883535)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'IMPORT_ROLL_INVENTORY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob        BLOB;',
'    l_filename    VARCHAR2(200);',
'',
'    v_success     NUMBER := 0;',
'    v_failed      NUMBER := 0;',
'BEGIN',
'    /* 1. Get Uploaded File */',
'    SELECT blob_content, filename',
'      INTO l_blob, l_filename',
'      FROM apex_application_temp_files',
'     WHERE name = :P33_FILE;',
'',
'    /* 2. Parse File Row by Row */',
'    FOR rec IN (',
'        SELECT col001, col002, col003, col004, col005,',
'               col006, col007, col008, col009, col010, col011',
'          FROM TABLE(',
'              apex_data_parser.parse(',
'                  p_content   => l_blob,',
'                  p_file_name => l_filename,',
'                  p_skip_rows => 1',
'              )',
'          )',
'    )',
'    LOOP',
'        BEGIN',
'            /* 3. Insert One Record at a Time */',
'            INSERT INTO PWC_INV_FABRIC_ROLL_D (',
'                supplier_serial_no,',
'                roll_no,',
'                roll_length,',
'                uom,',
'                roll_width,',
'                shrink_length,',
'                shrink_width,',
'                shade,',
'                remarks,',
'                delivery_no,',
'                barcode_no,',
'                line_id',
'            )',
'            VALUES (',
'                rec.col001,',
'                rec.col002,',
'                TO_NUMBER(rec.col003),',
'                rec.col004,',
'                TO_NUMBER(rec.col005),',
'                TO_NUMBER(rec.col006),',
'                TO_NUMBER(rec.col007),',
'                rec.col008,',
'                rec.col009,',
'                rec.col010,',
'                rec.col011,',
'                :P33_LINE_PK_ID',
'            );',
'',
'            v_success := v_success + 1;',
'',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                v_failed := v_failed + 1;',
'        END;',
'    END LOOP;',
'',
'    Commit;',
'    update_fabric_roll_line(:P33_LINE_PK_ID); ',
'',
'    /* 4. Final Message */',
'    apex_application.g_print_success_message :=',
'        ''Upload Completed. Success Rows = '' || v_success ||',
'        '', Failed Rows = '' || v_failed;',
'     ',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(131917940968883534)
,p_internal_uid=>131918003214883535
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(133106676243526103)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Mark Roll Status'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_updated_count NUMBER := 0;',
'',
'    CURSOR c_rolls IS',
'        SELECT TRIM(ROLL_NO) AS roll_no,',
'               ROL_ACPT_REJ  AS roll_status',
'        FROM PWC_MFG_FABINS_SECND_D',
'        WHERE TRIM(ROLL_NO) LIKE ''F/'' || :P33_SHIPMENT_NUM || ''/%'';',
'',
'BEGIN',
'    FOR r IN c_rolls LOOP',
'',
'        UPDATE PWC_INV_FABRIC_ROLL_D d',
'        SET d.ROLL_STATUS = r.roll_status',
'        WHERE TRIM(d.ROLL_SR_NO) = r.roll_no;',
'',
'        v_updated_count := v_updated_count + SQL%ROWCOUNT;',
'',
'    END LOOP;',
'',
'    COMMIT;',
'',
'    IF v_updated_count = 0 THEN',
'        apex_error.add_error (',
'            p_message          => ''No rolls were updated. Fabric Roll Inspection may be pending!'',',
'            p_display_location => apex_error.c_inline_in_notification',
'        );       ',
'    ELSE',
'        apex_application.g_print_success_message :=',
'            v_updated_count || '' Rolls Status Updated Successfully!'';',
'    END IF;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(131919296009883547)
,p_internal_uid=>133106676243526103
);
