'',
'    -- return plain text',
'    htp.p(''SUCCESS: '' || v_status);',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'        DECLARE',
'            l_msg VARCHAR2(4000);',
'        BEGIN',
'            -- Sirf actual error text nikale ga',
'            l_msg := SQLERRM;',
'',
'            -- ORA-xxxxx remove',
