'',
'            -- Extra unwanted text remove',
'            l_msg := REPLACE(l_msg, ''Unexpected Error:'', '''');',
'            l_msg := REPLACE(l_msg, ''Error:'', '''');',
'',
'            htp.p(TRIM(l_msg));',
'        END;',
'END;                             '))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>133106500402526102
);
