wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(134498429129063805)
,p_plug_name=>'Carton/Poly Detail'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT dt2.LINE_ID,   ',
'       dt2.HEADER_ID,   ',
'       dt2.INVENTORY_ITEM_ID,   ',
'       dt2.CONSUMPTION,   ',
'       dt2.CREATED_BY,   ',
'       dt2.CREATION_DATE,   ',
'       dt2.LAST_UPDATE_DATE,   ',
'       dt2.LAST_UPDATED_BY,   ',
'       dt2.DEPARTMENT,   ',
'       dt2.PCS_PER_CARTON,   ',
'               (SELECT msi.concatenated_segments ',
'                FROM apps.mtl_system_items_kfv@adf msi  ',
'                WHERE msi.organization_id = pwc_organization_name (''Inventory Master Org'') ',
'                AND msi.inventory_item_id = dt2.INVENTORY_ITEM_ID) AS ITEM_CODE,   ',
'               (SELECT msi.description ',
'               FROM Apps.mtl_system_items@adf msi  ',
'               WHERE msi.organization_id =  pwc_organization_name (''Inventory Master Org'') ',
'               AND msi.inventory_item_id =  dt2.INVENTORY_ITEM_ID) AS ITEM_DESC,   ',
'               (SELECT msi.primary_unit_of_measure  ',
'               FROM apps.mtl_system_items@adf msi ',
'               WHERE  msi.organization_id = pwc_organization_name (''Inventory Master Org'') ',
'               AND msi.inventory_item_id =  dt2.INVENTORY_ITEM_ID) AS ITEM_UOM, ',
'               ',
'            nvl((SELECT  ''Y'' FROM PWC_ONT_WVN_MASTER_BOM_H H ,PWC_ONT_WVN_MASTER_BOM_ITEMS_L L   ',
'       WHERE H.HEADER_ID = L.HEADER_ID and item_type = ''Carton/Poly''  ',
'        and h.tracking_no = hh.tracking_no  ',
'        and l.inventory_item_id = dt2.INVENTORY_ITEM_ID) , ''N'') CONS_FLAG  ',
'FROM  PWC_ONT_WVN_CART_CONSUMPTION_L dt2 , PWC_ONT_WVN_CART_CONSUMPTION_H hh  ',
'WHERE dt2.HEADER_ID = hh.HEADER_ID',
'AND dt2.header_id=:P35_HEADER_ID',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P35_HEADER_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
