wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(134888573965454364)
,p_plug_name=>'Carton/Poly Consumption Form'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--padded:t-ContentBlock--h2:t-ContentBlock--shadowBG:t-ContentBlock--headingFontAlt'
,p_plug_template=>wwv_flow_imp.id(220313214896810970)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tb1.HEADER_ID, ',
'       tb1.TRACKING_NO, ',
'       tb1.CREATED_BY, ',
'       tb1.CREATION_DATE, ',
'       tb1.LAST_UPDATE_DATE, ',
'       tb1.LAST_UPDATED_BY, ',
'       pwc_master_tracking_data_func (tb1.TRACKING_NO, ''BUYER_NAME'') AS BUYER_NAME, ',
'       pwc_master_tracking_data_func (tb1.TRACKING_NO, ''STYLE_NAME'') AS STYLE_NAME, ',
'       pwc_master_tracking_data_func (tb1.TRACKING_NO, ''STYLE_NO'') AS STYLE_NO, ',
'       pwc_master_tracking_data_func (tb1.TRACKING_NO, ''SEASON_NAME'') AS SEASON_NAME, ',
'       (SELECT h.buyer_agent_name   FROM pwc_ont_wvn_precosting_h h  WHERE ROWNUM = 1 AND h.tracking_no = tb1.TRACKING_NO) AS BUYER_AGENT_NAME, ',
'       pwc_master_tracking_data_func (tb1.TRACKING_NO, ''BRAND_DESCRIPTION'') AS BRAND_DESCRIPTION, ',
'       tb1.BUYER_ID',
'FROM   PWC_ONT_WVN_CART_CONSUMPTION_H tb1',
'',
''))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
