 p_id=>wwv_flow_imp.id(134500632849063827)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Carton_Poly header'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_header_id NUMBER;',
'BEGIN',
'    SELECT NVL(MAX(header_id),0) + 1',
'    INTO v_header_id',
'    FROM pwc_ont_wvn_cart_consumption_h;',
'',
'    INSERT INTO pwc_ont_wvn_cart_consumption_h',
'        (header_id,',
'         tracking_no,',
'         created_by,',
'         creation_date,',
'         last_update_date,',
'         last_updated_by,',
'         buyer_id)',
'    VALUES',
'        (v_header_id,',
'         :P35_TRACKING_NO,',
'         :P35_CREATED_BY,',
'         :P35_CREATION_DATE,',
'         :P35_LAST_UPDATE_DATE,',
'         :P35_LAST_UPDATED_BY,',
'         :P35_BUYER_ID);',
'',
'    :P35_HEADER_ID := v_header_id;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        raise_application_error(',
'            -20001,',
'            ''ERROR=''||SQLERRM||',
'            '' TRACKING=''||NVL(:P35_TRACKING_NO,''NULL'')||',
'            '' BUYER=''||NVL(TO_CHAR(:P35_BUYER_ID),''NULL'')',
'        );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(134899401756454398)
,p_internal_uid=>134500632849063827
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(134501246882063833)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(134498429129063805)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Carton/Poly Consumption IG'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   v_consumption NUMBER;',
'BEGIN',
'   -- ================= VALIDATION =================',
'   IF :PCS_PER_CARTON IS NULL OR :PCS_PER_CARTON = 0 THEN',
'      RAISE_APPLICATION_ERROR(-20001, ''PCS_PER_CARTON required hai aur 0 nahi ho sakta'');',
'   END IF;',
'',
'--    -- ================= CALCULATION =================',
'   v_consumption := ROUND(1 / :PCS_PER_CARTON, 6);',
'',
'   -- ================= INSERT =================',
'   IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'      INSERT INTO pwc_ont_wvn_cart_consumption_l',
'      (',
'         line_id,',
'         header_id,',
'         inventory_item_id,',
'         consumption,',
'         department,',
'         pcs_per_carton,',
'         created_by,',
'         creation_date',
'      )',
'      VALUES',
'      (',
'         NULL,                 -- trigger generate karega',
'         :P35_HEADER_ID,',
'         :INVENTORY_ITEM_ID,',
unistr('         v_consumption,        -- \2705 kabhi NULL nahi hoga'),
'         :DEPARTMENT,',
'         :PCS_PER_CARTON,',
'         723155,',
'         SYSDATE',
'      )',
'RETURNING line_id INTO :LINE_ID;',
'   -- ================= UPDATE =================',
'   ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'      UPDATE pwc_ont_wvn_cart_consumption_l',
'         SET inventory_item_id = :INVENTORY_ITEM_ID,',
'             consumption       = :consumption,',
'             department        = :DEPARTMENT,',
'             pcs_per_carton    = :PCS_PER_CARTON,',
'             last_updated_by   = 723155,',
'             last_update_date  = SYSDATE',
'       WHERE line_id = :LINE_ID;',
'',
'   -- ================= DELETE =================',
'   ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'      DELETE',
'        FROM pwc_ont_wvn_cart_consumption_l',
'       WHERE line_id = :LINE_ID;',
'',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      -- Proper error return to APEX (IG crash avoid)',
'      RAISE_APPLICATION_ERROR(-20002, ''Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>134501246882063833
);
