wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(257102105264151691)
,p_plug_name=>'Sample Bom'
,p_parent_plug_id=>wwv_flow_imp.id(257101970370151690)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT   ',
'       PwcOntWovenSampleItemsDetail1.DETAIL_ID,                ',
'       PwcOntWovenSampleItemsDetail1.LINE_ID,                ',
'       PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_ID,                ',
'       PwcOntWovenSampleItemsDetail1.ESTIMATED_CONSUMPTION,                ',
'       PwcOntWovenSampleItemsDetail1.ACTUAL_CONSUMPTION,                ',
'       PwcOntWovenSampleItemsDetail1.UNIT_PRICE,                ',
'       PwcOntWovenSampleItemsDetail1.TOTAL_QUANTITY,                 ',
'       PwcOntWovenSampleItemsDetail1.SAMPLE_SUBINVENTORY_CODE,                ',
'       PwcOntWovenSampleItemsDetail1.SOURCING_PERSON_ID,                ',
'       PwcOntWovenSampleItemsDetail1.ALERT_FLAG,                ',
'       PwcOntWovenSampleItemsDetail1.CREATION_DATE,                ',
'       PwcOntWovenSampleItemsDetail1.CREATED_BY,                ',
'       PwcOntWovenSampleItemsDetail1.LAST_UPDATE_DATE,                ',
'       PwcOntWovenSampleItemsDetail1.LAST_UPDATED_BY,         ',
'       PwcOntWovenSampleItemsDetail1.ITEM_CODE,        ',
'       PwcOntWovenSampleItemsDetail1.M2_JOB,       ',
'       --(SELECT msib.concatenated_segments                ',
'          --FROM mtl_system_items_kfv msib                ',
'        -- WHERE     msib.organization_id =                ',
'                    --  xxpwc.pwc_organization_name (''Inventory Master Org'')                ',
'              -- AND PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_ID =                ',
'                   --   msib.INVENTORY_ITEM_ID)                ',
'          --AS ITEM_CODE,                ',
'       (SELECT msib.description                ',
'          FROM apps.mtl_system_items_kfv@adf msib                ',
'         WHERE     msib.organization_id =                ',
'                      pwc_organization_name@adf (''Inventory Master Org'')                ',
'               AND PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_ID =                ',
'                      msib.INVENTORY_ITEM_ID)                ',
'          AS ITEM_DESCRIPTION,                ',
'       (SELECT ppx.full_name                ',
'          FROM apps.per_people_x@adf ppx                ',
'         WHERE ppx.person_id =                ',
'                  PwcOntWovenSampleItemsDetail1.SOURCING_PERSON_ID)                ',
'          AS SOURCING_PERSON_NAME,                ',
'       (SELECT SUM (moq.transaction_quantity)                ',
'          FROM apps.mtl_onhand_quantities_detail@adf moq, apps.ar_customers@adf ac                ',
'         WHERE     moq.inventory_item_id =                ',
'                      PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_ID                ',
'               AND moq.organization_id =                ',
'                      PwcOntWovenSampleItemsDetail1.STOCK_UNIT_ID                ',
'               AND ac.customer_id =                ',
'                      PwcOntWovenSampleItemsDetail1.SAMPLE_BUYER_ID                ',
'               AND moq.locator_id =                ',
'                      pwc_find_stock_locators (                ',
'                         PwcOntWovenSampleItemsDetail1.SAMPLE_SUBINVENTORY_CODE,                ',
'                         ac.attribute6,                ',
'                         moq.organization_id))                ',
'          AS SAMPLE_STORE_STOCK,                ',
'       (SELECT msib.primary_unit_of_measure                ',
'          FROM apps.mtl_system_items@adf msib                ',
'         WHERE     msib.organization_id =                ',
'                      pwc_organization_name@adf (''Inventory Master Org'')                ',
'               AND PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_ID =                ',
'                      msib.INVENTORY_ITEM_ID)                ',
'          AS ITEM_UOM_DESCRIPTION,                ',
'       PwcOntWovenSampleItemsDetail1.SAMPLE_BUYER_ID,                ',
'       PwcOntWovenSampleItemsDetail1.STOCK_UNIT_ID,                ',
'       PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_STATUS,                ',
'       PwcOntWovenSampleItemsDetail1.MATERIAL_RECVNG_DATE_TIME,                ',
'                       ',
'                       ',
'                       ',
'       NVL (                ',
'          (SELECT SUM (moq.transaction_quantity)                ',
'             FROM apps.mtl_system_items@adf msi,                ',
'                  apps.mtl_onhand_quantities@adf moq                ',
'            WHERE     msi.inventory_item_id = moq.inventory_item_id                ',
'                  AND msi.organization_id = moq.organization_id                ',
'--                  AND moq.subinventory_code IN                ',
'  --                       (''D.Fabric'', ''D.F.GMT'', ''Staging'')                ',
'--                  AND msi.segment1 IN (300, 301)                ',
'                  AND moq.organization_id in (89,91)                ',
'                  AND msi.inventory_item_id =                ',
'                         PwcOntWovenSampleItemsDetail1.INVENTORY_ITEM_ID),                ',
'          0)                ',
'          AS STOCK_QTY ,     ',
'          PwcOntWovenSampleItemsDetail1.UPPER_THREAD,     ',
'          PwcOntWovenSampleItemsDetail1.UNDER_THREAD,   ',
'          PwcOntWovenSampleItemsDetail1.REMARKS ,  ',
'          NVL((SELECT DISTINCT ''Y''  ',
'                FROM apps.po_headers_all@adf pha, apps.po_lines_all@adf pla  ',
'                WHERE     pha.po_header_id = pla.po_header_id  ',
'                    AND pha.authorization_status = ''APPROVED''  ',
'                    --AND NVL (pla.cancel_flag, ''N'') = ''N''  ',
'                    AND NVL (pha.cancel_flag, ''N'') = ''N''  ',
'                    AND pha.attribute_category = ''Trade PO''  ',
'                    AND pla.ITEM_ID = PwcOntWovenSampleItemsDetail1.inventory_item_id  ',
'                    AND pla.vendor_product_num = H.SAMPLE_CODE    ',
'  ',
'                    AND pha.attribute2 = h.version_no),''N'') PO_FLAG  ',
'                          ',
'                          ',
'  FROM PWC_ONT_WVN_SAMPLE_ITEMS_D PwcOntWovenSampleItemsDetail1 , PWC_ONT_WVN_SAMPLE_STATUS H , PWC_ONT_WVN_SAMPLE_STATUS_L L   ',
'  WHERE L.HEADER_ID = H.HEADER_ID AND  PwcOntWovenSampleItemsDetail1.LINE_ID = L.LINE_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
