wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(261507986401397159)
,p_name=>'STOCK_QTY'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'STOCK_QTY'
,p_data_type=>'NUMBER'
,p_session_state_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_NUMBER_FIELD'
,p_heading=>'Stock Qty'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>120
,p_value_alignment=>'CENTER'
,p_attribute_03=>'left'
,p_attribute_04=>'decimal'
,p_is_required=>false
,p_enable_filter=>true
,p_filter_is_required=>false
,p_filter_lov_type=>'NONE'
,p_use_as_row_header=>false
,p_enable_sort_group=>true
,p_enable_control_break=>true
,p_enable_hide=>true
,p_is_primary_key=>false
,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'     NVL (                ',
'          (SELECT SUM (moq.transaction_quantity)                ',
'             FROM apps.mtl_system_items@adf msi,                ',
'                  apps.mtl_onhand_quantities@adf moq                ',
'            WHERE     msi.inventory_item_id = moq.inventory_item_id                ',
'                  AND msi.organization_id = moq.organization_id                ',
'--                  AND moq.subinventory_code IN                ',
'  --                       (''D.Fabric'', ''D.F.GMT'', ''Staging'')                ',
'--                  AND msi.segment1 IN (300, 301)                ',
'                  AND moq.organization_id in (89,91)                ',
'                  AND msi.inventory_item_id =                ',
'                         :INVENTORY_ITEM_ID),                ',
'          0) AS STOCK_QTY  FROM DUAL',
''))
,p_duplicate_value=>true
,p_include_in_export=>true
);
