wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(256693359462458003)
,p_name=>'P37_SEASON_YEAR'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(256668847020457911)
,p_item_source_plug_id=>wwv_flow_imp.id(256668847020457911)
,p_prompt=>'Season Year'
,p_source=>'SEASON_YEAR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT TO_CHAR (generated_dates, ''YYYY'') season_year   ',
'  FROM (SELECT DISTINCT   ',
'               LAST_DAY (TO_DATE (''01-01-2020'', ''dd-mm-yyyy'') + lvl)   ',
'                  generated_dates   ',
'          FROM (    SELECT LEVEL - 1 lvl   ',
'                      FROM DUAL   ',
'                CONNECT BY LEVEL <=   ',
'                                (  ADD_MONTHS (TRUNC (SYSDATE), 108)   ',
'                                 - TO_DATE (''01-01-2020'', ''dd-mm-yyyy''))   ',
'                              + 1))'))
,p_lov_display_null=>'YES'
,p_cSize=>32
,p_cMaxlength=>10
,p_begin_on_new_line=>'N'
,p_field_template=>wwv_flow_imp.id(220418559820811079)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
);
