wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(256694960443458004)
,p_name=>'P37_BUYER_NAME'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(256668847020457911)
,p_item_source_plug_id=>wwv_flow_imp.id(256668847020457911)
,p_prompt=>'Buyer Name'
,p_source=>'BUYER_NAME'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'SS_BUYER_NAME'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT DISTINCT',
'       ac.customer_id buyer_id,',
'       ac.customer_name buyer_name,',
'       qrv.character3 buyer_agent_name',
'  FROM pwc_mt_buyer_details_h bh,',
'       pwc_mt_enduser_details_d ed,',
'       pwc_mt_merchandizer_details_d md,',
'       APPS.ar_customers@ADF ac,',
'       --fnd_user fu,',
'       APPS.qa_results_v@ADF qrv',
' WHERE     bh.header_id = ed.header_id',
'       AND ed.enduser_detail_id = md.enduser_detail_id',
'       -- AND fu.user_name = md.app_user_name',
'       AND bh.buyer_id = ac.customer_id',
'       AND qrv.character2 = ac.customer_id',
'       AND qrv.name = ''PWC_OM_RETAILER_AGENT''',
'       AND md.active_merch = ''Y''',
'       AND ed.active_enduser = ''Y''',
'-- AND fu.user_id = :p_userId',
'UNION',
'SELECT DISTINCT',
'       ac.customer_id buyer_id,',
'       ac.customer_name buyer_name,',
'       qrv.character3 buyer_agent_name',
'  FROM pwc_mt_buyer_details_h bh,',
'       pwc_mt_enduser_details_d ed,',
'       pwc_mt_buyr_cordinat_details_d cd,',
'       APPS.ar_customers@ADF ac,',
'       --fnd_user fu,',
'       APPS.qa_results_v@ADF qrv',
' WHERE     bh.header_id = ed.header_id',
'       AND ed.enduser_detail_id = cd.enduser_detail_id',
'       -- AND fu.user_name = cd.app_user_name',
'       AND bh.buyer_id = ac.customer_id',
'       AND qrv.character2 = ac.customer_id',
'       AND qrv.name = ''PWC_OM_RETAILER_AGENT''',
'       AND ed.active_enduser = ''Y''',
'       AND cd.active_coordinator = ''Y''',
'--AND fu.user_id = :p_userId'))
,p_lov_display_null=>'YES'
,p_cSize=>32
,p_cMaxlength=>255
,p_begin_on_new_line=>'N'
,p_field_template=>wwv_flow_imp.id(220418559820811079)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
