wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(135886317878623460)
,p_name=>'iNSERT BUYER_ID + BUYER AGENT'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P37_BUYER_NAME'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(135886834959623461)
,p_event_id=>wwv_flow_imp.id(135886317878623460)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P37_BUYER_ID,P37_BUYER_AGENT_NAME'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT BUYER_ID , BUYER_AGENT_NAME FROM (SELECT DISTINCT ',
'       ac.customer_id buyer_id, ',
'       ac.customer_name buyer_name, ',
'       qrv.character3 buyer_agent_name ',
'  FROM pwc_mt_buyer_details_h bh, ',
'       pwc_mt_enduser_details_d ed, ',
'       pwc_mt_merchandizer_details_d md, ',
'       APPS.ar_customers@ADF ac, ',
'       --fnd_user fu, ',
'       APPS.qa_results_v@ADF qrv ',
' WHERE     bh.header_id = ed.header_id ',
'       AND ed.enduser_detail_id = md.enduser_detail_id ',
'       --AND fu.user_name = md.app_user_name ',
'       AND bh.buyer_id = ac.customer_id ',
'       AND qrv.character2 = ac.customer_id ',
'       AND qrv.name = ''PWC_OM_RETAILER_AGENT'' ',
'       AND md.active_merch = ''Y'' ',
'       AND ed.active_enduser = ''Y'' ',
'       --AND fu.user_id = :p_userId ',
'UNION ',
'SELECT DISTINCT ',
'       ac.customer_id buyer_id, ',
'       ac.customer_name buyer_name, ',
'       qrv.character3 buyer_agent_name ',
'  FROM pwc_mt_buyer_details_h bh, ',
'       pwc_mt_enduser_details_d ed, ',
'       pwc_mt_buyr_cordinat_details_d cd, ',
'       APPS.ar_customers@ADF ac, ',
'       --fnd_user fu, ',
'       APPS.qa_results_v@ADF qrv ',
' WHERE     bh.header_id = ed.header_id ',
'       AND ed.enduser_detail_id = cd.enduser_detail_id ',
'       --AND fu.user_name = cd.app_user_name ',
'       AND bh.buyer_id = ac.customer_id ',
'       AND qrv.character2 = ac.customer_id ',
'       AND qrv.name = ''PWC_OM_RETAILER_AGENT'' ',
'       AND ed.active_enduser = ''Y'' ',
'       AND cd.active_coordinator = ''Y'' ',
'       --AND fu.user_id = :p_userId',
')WHERE BUYER_NAME = :P37_BUYER_NAME'))
,p_attribute_07=>'P37_BUYER_NAME'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
