 p_id=>wwv_flow_imp.id(135883876344623457)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set header id '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   if :P37_HEADER_ID is null then ',
'        SELECT PWC_ONT_WVN_SAMPLE_STATUS_s.NEXTVAL',
'        INTO   :P37_HEADER_ID',
'        FROM   dual;',
'   end if;    ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(135852539252623388)
,p_internal_uid=>135883876344623457
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(135885014147623457)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAMPLE_CODE_GENERATION'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_next_no        NUMBER := 1;',
'    v_formatted_no   VARCHAR2(20);',
'    v_sample_code    VARCHAR2(50);',
'    v_buyer_prefix   VARCHAR2(20);',
'BEGIN',
unistr('    -- 1\FE0F\20E3 If Sample Code already exists \2192 skip'),
'    IF :P37_SAMPLE_CODE IS NOT NULL THEN',
'        RETURN;',
'    END IF;',
'',
unistr('    -- 2\FE0F\20E3 Design Department & Buyer NULL'),
'    IF :P37_BUYER_ID IS NULL',
'       AND :P37_SAMPLE_DEVELOPMENT = ''Design Department''',
'    THEN',
'        SELECT NVL(MAX(TO_NUMBER(REGEXP_SUBSTR(sample_code, ''[0-9]+$''))), 0) + 1',
'        INTO v_next_no',
'        FROM pwc_ont_wvn_sample_status',
'        WHERE buyer_id IS NULL;',
'',
'        IF v_next_no < 1000 THEN',
'            v_formatted_no := LPAD(v_next_no, 3, ''0'');',
'        ELSE',
'            v_formatted_no := TO_CHAR(v_next_no);',
'        END IF;',
'',
'        :P37_SAMPLE_CODE := ''SAM-'' || v_formatted_no;',
'',
'    ELSE',
unistr('        -- 3\FE0F\20E3 Buyer based sample code'),
'        IF :P37_BUYER_ID IS NULL THEN',
'            raise_application_error(-20001, ''Buyer ID is missing.'');',
'        END IF;',
'',
'        -- Fetch buyer prefix',
'        SELECT attribute6',
'        INTO v_buyer_prefix',
'        FROM apps.ar_customers@ADF',
'        WHERE customer_id = :P37_BUYER_ID;',
'',
'        IF v_buyer_prefix IS NULL THEN',
'            raise_application_error(-20002, ''Buyer prefix not found.'');',
'        END IF;',
'',
'        SELECT NVL(MAX(TO_NUMBER(REGEXP_SUBSTR(sample_code, ''[0-9]+$''))), 0) + 1',
'        INTO v_next_no',
'        FROM pwc_ont_wvn_sample_status',
'        WHERE buyer_id = :P37_BUYER_ID;',
'',
'        IF v_next_no < 1000 THEN',
'            v_formatted_no := LPAD(v_next_no, 3, ''0'');',
'        ELSE',
'            v_formatted_no := TO_CHAR(v_next_no);',
'        END IF;',
'',
'        :P37_SAMPLE_CODE := v_buyer_prefix || ''-'' || v_formatted_no;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(135852539252623388)
,p_internal_uid=>135885014147623457
);
