,p_process_name=>'Set Last Updated By'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Get current APEX user ID safely',
'DECLARE',
'v_user_id NUMBER;',
'   BEGIN',
'      SELECT user_id',
'      INTO v_user_id',
'      FROM APEX_230200.WWV_FLOW_USERS  ',
'      WHERE user_name = :APP_USER;',
'      ',
'      ',
'      if (:P37_CREATED_BY is not null) then',
'      :P37_LAST_UPDATED_BY := v_user_id;',
'      end if;',
'',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         v_user_id := NULL;  -- agar user exist na kare',
'      ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>135884678653623457
);
end;
