'       PwcOntWovenSamplePurchaseOrd1.PO_OPERATING_UNIT_ID, ',
'       PwcOntWovenSamplePurchaseOrd1.PO_SUPPLIER_ID, ',
'       PwcOntWovenSamplePurchaseOrd1.PO_UOM, ',
'       (SELECT msi.concatenated_segments           FROM apps.mtl_system_items_kfv@adf msi          WHERE     msi.organization_id =                       pwc_organization_name (''Inventory Master Org'')                AND msi.inventory_item_id =        '
||'               PwcOntWovenSamplePurchaseOrd1.INVENTORY_ITEM_ID) AS INVENTORY_ITEM_CODE, ',
'       (SELECT msi.description           FROM apps.mtl_system_items@adf msi          WHERE     msi.organization_id =                       pwc_organization_name (''Inventory Master Org'')                AND msi.inventory_item_id =                      '
||' PwcOntWovenSamplePurchaseOrd1.INVENTORY_ITEM_ID) AS INVENTORY_ITEM_DESCRIPTION, ',
'       (SELECT msi.primary_unit_of_measure           FROM apps.mtl_system_items@adf msi          WHERE     msi.organization_id =                       pwc_organization_name (''Inventory Master Org'')                AND msi.inventory_item_id =          '
||'             PwcOntWovenSamplePurchaseOrd1.INVENTORY_ITEM_ID) AS INVENTORY_ITEM_UNIT_MEASURE, ',
'       (SELECT hou.name FROM apps.hr_operating_units@adf hou WHERE hou.organization_id = PwcOntWovenSamplePurchaseOrd1.PO_OPERATING_UNIT_ID) AS PO_OPERATING_UNIT_NAME, ',
'       (SELECT pv.vendor_name FROM apps.po_vendors@adf pv WHERE pv.vendor_id = PwcOntWovenSamplePurchaseOrd1.PO_SUPPLIER_ID) AS PO_SUPPLIER_NAME, ',
'       PwcOntWovenSamplePurchaseOrd1.HEADER_ID, ',
'       PwcOntWovenSamplePurchaseOrd1.PO_SUPPLIER_SITE_ID, ',
'       PwcOntWovenSamplePurchaseOrd1.SAMPLE_LINE_CODE, ',
'       PwcOntWovenSamplePurchaseOrd1.SELECT_FLAG, ',
'       PwcOntWovenSamplePurchaseOrd1.VERSION_NO, ',
'       PwcOntWovenSamplePurchaseOrd1.SALES_TAX_PERC',
'FROM  PWC_ONT_WVN_SAMPLE_PO_TMP_LINE PwcOntWovenSamplePurchaseOrd1',
'where PwcOntWovenSamplePurchaseOrd1.header_id = :P39_HEADER_ID;'))
