,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'	var region = apex.region("GPO_IG");',
'	var ig = region.widget();',
'	var gridView = ig.interactiveGrid("getViews", "grid");',
'	var model = gridView.model;',
'	var selectedRecords = gridView.getSelectedRecords();',
'	//console.log(''ROLL IG CODE DEBUG'');',
'',
'	// Update selected rows',
'	if (selectedRecords.length > 0) {',
'		selectedRecords.forEach(function(record) {',
'			model.setValue(record, "SELECT_FLAG", "Y"); // Column name',
'		});',
'',
'		// Mark changes and save automatically',
'		region.call("getActions").invoke("save");',
'	}',
'	else {',
'		apex.message.alert("Please select at least one row.");',
'		return;',
'	}',
'',
'',
'    // Ajax Call',
'// apex.server.process(',
'//     "GENERATE_PO",',
'//     { x01: $v("P39_HEADER_ID") },',
'//     {',
'//         dataType: "text",',
'//         success: function(pData) {',
'',
'//             if (pData && pData.startsWith("ERROR")) {',
'',
'//                 apex.message.showDialog(',
'//                     pData,',
'//                     function(){},',
'//                     {',
'//                         title: "Database Error",',
'//                         style: "danger",',
'//                         dialogClasses: "custom-error-dialog"',
'//                     }',
'//                 );',
'',
'//             } else {',
'//                 apex.message.showPageSuccess("PO Generated Successfully");',
'//             }',
'',
'//         },',
'//         error: function(xhr, status, error) {',
'//             apex.message.alert("AJAX Error: " + error);',
'//         }',
'//     }',
'// );',
'',
'',
'    apex.server.process(',
'    "GENERATE_PO",        // Process name',
'    { x01: $v("P39_HEADER_ID") },  // Parameters',
'    {',
'        dataType: "text",  // <<< Important: plain text',
'        success: function(pData) {',
'            if (pData && pData.startsWith("ERROR")) {',
'                //apex.message.alert(''Database error has occurred.'');  // Show DB error',
'                apex.message.alert(pData);  // Show DB error',
'',
'            } else {',
'                apex.message.showPageSuccess("PO Generated Successfully.");',
'            }',
'        },',
'        error: function(xhr, status, error) {',
'            apex.message.alert("AJAX Error: " + error);',
'        }',
'    }',
');',
''))
);
