begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(142282260364974403)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(139494221497701445)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate Purchase Order - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    CASE :APEX$ROW_STATUS   ',
'        WHEN ''U'' THEN ',
'            UPDATE PWC_ONT_WVN_SAMPLE_PO_TMP_LINE',
'            SET ',
'                PO_QUANTITY           = :PO_QUANTITY,',
'                PO_CURRENCY           = :PO_CURRENCY,',
'                PO_UNIT_PRICE         = :PO_UNIT_PRICE,',
'                PO_OPERATING_UNIT_ID  = :PO_OPERATING_UNIT_ID,',
'                PO_SUPPLIER_ID        = :PO_SUPPLIER_ID,',
'                PO_UOM                = :PO_UOM,',
'                PO_SUPPLIER_SITE_ID   = :PO_SUPPLIER_SITE_ID,',
'                SELECT_FLAG           = :SELECT_FLAG,',
'                SALES_TAX_PERC        = :SALES_TAX_PERC',
'            WHERE SAMPLE_PO_TEMP_ID = :SAMPLE_PO_TEMP_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>142282260364974403
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(150496974374856902)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GENERATE_PO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    apps.pwc_ont_wvn_sample_std_apex. generate_po_from_sample_status@adf(',
'      p_header_id    => :P39_HEADER_ID,',
'      p_user_id      => 0,',
'      p_resp_id      => 20707,',
'      p_resp_appl_id => 201',
'   );',
'     -- Return plain text result',
'    htp.p(''PO Generated Successfully'');',
'EXCEPTION',
'    WHEN OTHERS THEN',
'    htp.p(''ERROR: '' || SQLERRM);',
'    --     htp.p(',
'    --      ''ERROR: '' || ',
'    --      REGEXP_REPLACE(SQLERRM, ''ORA-\d+: '', '''')',
'    --   );',
'        ',
'        -- Optional: log error (recommended)',
'      --apex_debug.message(''Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>150496974374856902
);
end;
