'          sample_code,           ',
'        -- h.Version_no,   ',
'       pla.vendor_product_num sample_line_code,           ',
'       pha.segment1 po_number,           ',
'       msi.concatenated_segments item_code,           ',
'       msi.description,           ',
'       pla.unit_price,           ',
'       msi.inventory_item_id,           ',
'       pha.currency_code,           ',
'       pha.creation_date booking_date,           ',
'       INITCAP (pha.authorization_status) authorization_status,           ',
'       pav.agent_name,           ',
'       pla.quantity,           ',
'       hou.name org_name,           ',
'       ap.vendor_name,   ',
'       NVL(pha.attribute2,1) version_no           ',
'  FROM apps.po_headers_all@adf pha,           ',
'       apps.po_lines_all@adf pla,           ',
'       apps.mtl_system_items_kfv@adf msi,           ',
'       apps.po_agents_v@adf pav,           ',
'       apps.hr_operating_units@adf hou,           ',
'       apps.po_vendors@adf ap   ',
'      ',
'                 ',
' WHERE     pha.po_header_id = pla.po_header_id           ',
'       AND msi.inventory_item_id = pla.item_id           ',
'       AND ap.vendor_id = pha.vendor_id           ',
'       AND pav.agent_id = pha.agent_id           ',
'       AND hou.organization_id = pha.org_id           ',
'       AND NVL(pha.attribute10, ''N/A'') = ''Woven''         ',
'       AND msi.organization_id =           ',
'              pwc_organization_name (''Inventory Master Org'')           ',
'       AND pla.vendor_product_num IS NOT NULL        ',
'       AND PHA.CANCEL_FLAG != ''Y''    ',
'     ',
'       )         ',
'               ',
'       WHERE AUTHORIZATION_STATUS != ''REJECTED''',
'       AND SAMPLE_LINE_CODE = :P42_SAMPLE_LINE_CODE;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P42_SAMPLE_LINE_CODE'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
