,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT qa_child.character1 d_size,qa_child.character1 r_size',
'FROM APPS.qa_results_v@ADF qa_parent',
'JOIN APPS.qa_pc_results_relationship@ADF qpr',
'  ON qa_parent.occurrence = qpr.parent_occurrence',
' AND qa_parent.plan_id = qpr.parent_plan_id',
' AND qa_parent.collection_id = qpr.parent_collection_id',
'JOIN APPS.qa_results_v@ADF qa_child',
'  ON qa_child.occurrence = qpr.child_occurrence',
' AND qa_child.plan_id = qpr.child_plan_id',
' AND qa_child.collection_id = qpr.child_collection_id',
'WHERE qa_child.character1 IS NOT NULL',
'  AND qa_parent.name = ''PWC_OM_RETAILER_AGENT''',
'  AND qa_child.name = ''PWC_OM_SIZES''',
'  AND qa_parent.character2 = :CUSTOMER_ID',
'ORDER BY qa_child.character1            '))
