 p_id=>wwv_flow_imp.id(140081178162213250)
,p_event_id=>wwv_flow_imp.id(140081033047213249)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_total_qty NUMBER := 0;',
'BEGIN',
'  FOR rec IN (',
'      SELECT round(NVL(SUM(EXCESS_BPO_PLAN_QTY), 0)) AS ORDER_QTY',
'      FROM APPS.MTML_COLOR_BPO_WISE_PLAN_QTY_V@ADF V',
'      WHERE V.TRACKING_NO = :P44_TRACKING_NO',
'        AND V.GARMENT_COLOR IN (',
'           SELECT column_value FROM TABLE(apex_string.split(:P44_COLOR, '':''))',
'       )',
'  )',
'  LOOP',
'    v_total_qty := v_total_qty + rec.ORDER_QTY;',
'  END LOOP;',
'',
'  :P44_ORDER_QTY := v_total_qty;',
'',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    :P44_ORDER_QTY := 0;',
'',
'  WHEN OTHERS THEN',
'    :P44_ORDER_QTY := NULL;',
'END;'))
,p_attribute_02=>'P44_TRACKING_NO,P44_COLOR'
,p_attribute_03=>'P44_ORDER_QTY'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(220244284919810891)
);
