,p_plug_name=>'Issue to Wash'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  SELECT HeaderEO.HEADER_ID,            ',
'         HeaderEO.RECEIVE_NO,            ',
'         HeaderEO.INVOICE_NO, ',
'          HeaderEO.WASHING_PROCESS,            ',
'        nvl( ',
'        (select max(l.ATTRIBUTE3)  ',
'                from PWC_MFG_ISSUE_REC_WASH_L_H h , PWC_MFG_ISSUE_REC_WASH_L l  ',
'                where H.LINE_ID = l.header_id  ',
'                and h.header_id = HeaderEO.header_id) ,',
'        (select max(l.ATTRIBUTE3)  ',
'                from PWC_MFG_ISSUE_REC_WASH_L_H h , PWC_MFG_ISSUE_REC_WASH_D l  ',
'                where H.LINE_ID = l.header_id  ',
'                and h.header_id = HeaderEO.header_id)) COLOR,            ',
'         HeaderEO.DATE_OF_GRN,            ',
'         HeaderEO.CREATED_BY,            ',
'         HeaderEO.CREATION_DATE,            ',
'         HeaderEO.LAST_UPDATED_BY,            ',
'         HeaderEO.LAST_UPDATE_DATE,            ',
'         HeaderEO.ORG_ID,            ',
'         HeaderEO.HEADER_NO,            ',
'         HeaderEO.LOT_NUMBER,            ',
'         HeaderEO.ATTRIBUTE1,            ',
'         HeaderEO.ATTRIBUTE2,            ',
'         HeaderEO.ATTRIBUTE3,            ',
'         HeaderEO.ATTRIBUTE4,            ',
'         HeaderEO.ATTRIBUTE5,            ',
'         HeaderEO.ATTRIBUTE6,            ',
'         HeaderEO.ATTRIBUTE7,            ',
'         HeaderEO.ATTRIBUTE8,            ',
'         HeaderEO.ATTRIBUTE9,            ',
'         HeaderEO.ATTRIBUTE10,            ',
'         HeaderEO.ATTRIBUTE11,            ',
'         HeaderEO.ATTRIBUTE12,            ',
'         HeaderEO.ATTRIBUTE13,            ',
'         HeaderEO.ATTRIBUTE14,            ',
'         HeaderEO.ATTRIBUTE15,            ',
'         HeaderEO.SALESORDER_ID,            ',
'         HeaderEO.TRANSACTION_TYPE,            ',
'         HeaderEO.TRANSACTION,            ',
'         HeaderEO.UPDATE_ON,            ',
'         HeaderEO.Delivered_By,            ',
'         HeaderEO.Received_By,            ',
'         HeaderEO.WASH_EMB_PRINT_INV,            ',
'         HeaderEO.WASH_EMB_PRINT_INVORG,            ',
'         HeaderEO.REMARKS,',
'         HeaderEO.unit,',
'         PWC_WASH_ISSUEREC_PAD_FUNC(''TRACKING_NO_N'', HeaderEO.HEADER_ID) TRACKING_NO_N,            ',
'         PWC_WASH_ISSUEREC_PAD_FUNC(''BUYER_N'', HeaderEO.HEADER_ID) BUYER_N,            ',
'         PWC_WASH_ISSUEREC_PAD_FUNC(''SEASON_N'', HeaderEO.HEADER_ID)  SEASON_N,            ',
'         PWC_WASH_ISSUEREC_PAD_FUNC(''STYLE_NAME_N'', HeaderEO.HEADER_ID)STYLE_NAME_N,       ',
'         HeaderEO.OSP_CHECK,    ',
'         HeaderEO.TAB_VIEW_CONTROL,   ',
'         nvl((select distinct ''Y''    ',
'                from PWC_MFG_ISSUE_REC_WASH_L_H    ',
'                where header_id = HeaderEO.HEADER_ID), ''N'') head_upd_check , ',
'        HeaderEO.SUB_TRANS_TYPE ',
'    FROM PWC_MFG_ISSUE_REC_WASH_H HeaderEO            ',
'   WHERE HeaderEO.ORG_ID = NVL(:p_org  , ''85'')         ',
'ORDER BY HeaderEO.HEADER_ID DESC',
''))
