begin
wwv_flow_imp_page.create_page(
 p_id=>47
,p_name=>'Fabric Inspection Lookup'
,p_alias=>'FABRIC-INSPECTION-LOOKUP'
,p_step_title=>'Fabric Inspection Lookup'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
