);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(263213191476083411)
,p_plug_name=>'Fabric Inspection Lookup'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_grid_column_css_classes=>'apex-bold-header'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'       h.HEADER_ID,',
'       h.INVOICE_NO,',
'       h.CREATED_BY,',
'       h.CREATION_DATE,',
'       h.LAST_UPDATED_BY,',
'       h.LAST_UPDATE_DATE,',
'       h.HEADER_NO,',
'',
'       PWC_FABRIC_INSP_CONCAT_FUNC(h.HEADER_ID,''TRACKING_NO'')  AS TRACKING_NO_L,',
'       PWC_FABRIC_INSP_CONCAT_FUNC(h.HEADER_ID,''BUYER_NAME'')   AS BUYER_NAME,',
'       PWC_FABRIC_INSP_CONCAT_FUNC(h.HEADER_ID,''STYLE_NAME'')   AS STYLE_L,',
'       PWC_FABRIC_INSP_CONCAT_FUNC(h.HEADER_ID,''SEASON_NAME'')  AS SEASON_L,',
'',
'       h.COMM_INVOICE_NO,',
'       h.LOT,',
'       h.VERSION_NO,',
'',
'    --    CASE ',
'    --        WHEN EXISTS (',
'    --             SELECT 1',
'    --             FROM PWC_MFG_FABINS_PROD_L p',
'    --                  JOIN PWC_MFG_FABRIC_INS_TEST_L l',
'    --                    ON p.PROD_L_ID = l.PROD_L_ID',
'    --             WHERE p.HEADER_ID = h.HEADER_ID',
'    --        )',
'    --        THEN ''Entered''',
'    --        ELSE ''Not Entered''',
'    --    END AS SHRINK_RESULTS,',
'',
'       h.UNIT_ID',
'',
'FROM PWC_MFG_FABRIC_INS_TEST_H h',
'WHERE h.ORG_ID = 85',
'ORDER BY h.HEADER_ID DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Thread Consumption Form'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
