wwv_flow_imp_page.create_page(
 p_id=>48
,p_name=>'Issue To  Finishing Form'
,p_alias=>'M6-ISSUE-TO-SEWING-FORM'
,p_step_title=>'Issue To  Finishing Form'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function($){',
'  $(function(){',
'',
'    // Set your Interactive Grid STATIC ID here (NO #)',
'    var igStaticId = "IG_STATIC_ID";    ',
'',
'    $("#" + igStaticId).on("interactivegridviewmodelcreate", function(event, ui){',
'      if (ui.viewId !== "grid") return;',
'',
'      var model = ui.model;',
'',
'      function updateTotals() {',
'',
'        // New totals',
'        var totalQACheck  = 0;',
'       // var totalDefects  = 0;',
'       // var totalOK       = 0;',
'',
'        var recordCount   = 0;',
'',
'        // Get field keys',
'        var colQACheck  = model.getFieldKey("ISSUED_QTY");',
'       // var colDefects  = 0;',
'        //model.getFieldKey("DEFECTS");',
'       // var colOK       = 0;',
'        //model.getFieldKey("OK");',
'',
'        model.forEach(function(rec, i, id){',
'',
'          var meta = model.getRecordMetadata(id);',
'          if (meta.deleted || meta.agg) return;',
'',
'          recordCount++;',
'',
'          // NEW TOTALS',
'          var qaVal = parseFloat(rec[colQACheck]);',
'          if (!isNaN(qaVal)) totalQACheck += qaVal;',
'',
'         // var defectVal = parseFloat(rec[colDefects]);',
'         // if (!isNaN(defectVal)) totalDefects += defectVal;',
'',
'         // var okVal = parseFloat(rec[colOK]);',
'         // if (!isNaN(okVal)) totalOK += okVal;',
'',
'        });',
'',
'        // Assign values to page items',
'        apex.item("P48_TOT_QTY").setValue(totalQACheck);',
'        //apex.item("P6_DEF_QTY").setValue(totalDefects);',
'        //apex.item("P6_OK").setValue(totalOK);',
'      }',
'',
'      model.subscribe({',
'        onChange: function(type, change){',
'          if (',
'            (',
'              type === "set" &&',
'              (change.field === "ISSUED_QTY" ',
'              //||',
'              // change.field === "DEFECTS" ||',
'               //change.field === "OK"',
'               )',
'            )',
'            || type === "insert"',
'            || type === "delete"',
'          ) {',
'            updateTotals();',
'          }',
'        }',
'      });',
'',
'      model.fetchAll(function(){',
'        updateTotals();',
'      });',
'',
'      apex.region(igStaticId).widget().on("apexafterrefresh", function(){',
'        updateTotals();',
'      });',
'',
'    });',
'',
'  });',
'})(apex.jQuery);',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.align-right input {',
'  text-align: right;',
'}',
'',
'.align-center input {',
'  text-align: center;',
'}',
'',
'.highlight-qty input {',
'    background-color: #b9d3e9;',
'    color: #9f0452;',
'    font-weight: bold;',
'    font-size: 16px;',
'}',
'',
'/* Change Interactive Grid header (title + toolbar) background */',
'#IG_STATIC_ID .a-IG-header {',
'    background-color: #b9d3e9; /* Light blue */',
'    color: white;               /* White text for contrast */',
'    font-weight: bold;          /* Optional */',
'}',
'',
'/* Optional: change button/icon colors in the IG header */',
'#IG_STATIC_ID .a-IG-header .t-Button {',
'    color: white;',
'}'))
