 p_id=>wwv_flow_imp.id(142798161679038224)
,p_name=>'P50_COLOR'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(369552895788160555)
,p_item_source_plug_id=>wwv_flow_imp.id(369552895788160555)
,p_prompt=>'Color'
,p_source=>'COLOR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT BPO.STYLE_COLOUR, BPO.STYLE_COLOUR ID ',
'FROM PWC_ONT_WVN_PRECOSTING_H@ADF H,',
'     PWC_ONT_WVN_PRECOSTING_L@ADF POCL,',
'     PWC_ONT_WVN_PRECOSTING_COLOR_L@ADF BPO',
'     WHERE 1=1',
'     AND H.HEADER_ID = POCL.HEADER_ID',
'     AND POCL.LINE_ID = BPO.LINE_ID',
'     AND H.TRACKING_NO      = :P50_TRACKING_NO',
'    --  and NOT exists (select ''X''        ',
'    --                            from CUTTING_SPREADING_H FETCHED        ',
'    --                            WHERE FETCHED.COLOR =  BPO.STYLE_COLOUR       ',
'    --                            and   FETCHED.tracking_no =  H.TRACKING_NO       ',
'    --                            ) ',
''))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P50_TRACKING_NO'
,p_ajax_items_to_submit=>'P50_TRACKING_NO'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_begin_on_new_line=>'N'
,p_read_only_when=>':P50_H_ID IS NOT NULL '
,p_read_only_when2=>'PLSQL'
