 p_id=>wwv_flow_imp.id(142798237857038225)
,p_name=>'P50_TRACKING_NO'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>140
,p_item_plug_id=>wwv_flow_imp.id(369552895788160555)
,p_item_source_plug_id=>wwv_flow_imp.id(369552895788160555)
,p_prompt=>'Tracking No.'
,p_source=>'TRACKING_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'CUTTING_SPREADING_H_TRACKING_NO_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'-- tracking no lov',
'SELECT DISTINCT ',
'       bh.buyer_id,',
'       ac.customer_name,',
'       sl.style_name,',
'       sl.style_number,',
'       sd.season_name,',
'       sd.tracking_no',
'FROM pwc_mt_buyer_details_h@ADF bh',
'JOIN pwc_mt_brand_details_d@ADF bd ',
'     ON bh.header_id = bd.header_id',
'JOIN pwc_mt_style_details_l@ADF sl ',
'     ON bd.brand_line_id = sl.brand_line_id',
'JOIN pwc_mt_season_details_d@ADF sd ',
'     ON sl.style_line_id = sd.style_line_id',
'JOIN pwc_ont_wvn_precosting_h@ADF mmph ',
'     ON mmph.tracking_no = sd.tracking_no',
'JOIN APPS.ar_customers@ADF ac ',
'     ON ac.customer_id = bh.buyer_id',
'WHERE sd.season_status = ''Open''',
'  AND sd.season_identifier IS NOT NULL',
'  AND sd.tracking_no IS NOT NULL'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_cMaxlength=>250
,p_read_only_when=>':P50_H_ID IS NOT NULL '
,p_read_only_when2=>'PLSQL'
,p_read_only_when_type=>'EXPRESSION'
