wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(165733553060651150)
,p_tabular_form_region_id=>wwv_flow_imp.id(369931397109010748)
,p_validation_name=>'check duplicate'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    -- Check if the combination exists',
'    SELECT count(*)',
'      INTO v_count',
'      FROM CUTTING_SPREADING_L l',
'      JOIN CUTTING_SPREADING_H h ON h.H_ID = l.H_ID',
'     WHERE h.TRACKING_NO = :P50_TRACKING_NO',
'       AND h.COLOR       = :P50_COLOR',
'       AND l.CUT_ID      = :CUT_ID;',
'',
'    -- Agar count 0 se zyada hai, iska matlab duplicate hai',
'    IF v_count > 0 AND :APEX$ROW_STATUS != ''D'' THEN',
'        RETURN ''Cut # Value '' || :CUT_ID || '' is already used for Tracking No ('' || :P50_TRACKING_NO || '') and Color ('' || :P50_COLOR || '').'';',
'    END IF;',
'',
'    -- Agar sab theek hai toh null return karein',
'    RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_associated_column=>'CUT_ID'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(169106433182728901)
,p_tabular_form_region_id=>wwv_flow_imp.id(142761121908032710)
,p_validation_name=>'validation not > total ply'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_required_ply      NUMBER := 0;',
'    v_total_entry_ply   NUMBER := 0;',
'BEGIN',
unistr('    -- \D83D\DD39 Required ply from Line table'),
'    SELECT NVL(MAX(NO_OF_PILE),0)',
'    INTO v_required_ply',
'    FROM CUTTING_SPREADING_L',
'    WHERE L_ID = :L_ID;',
'',
unistr('    -- \D83D\DD39 Total entered ply (including current row value)'),
'    SELECT NVL(SUM(EXTRACT_PLY),0)',
'    INTO v_total_entry_ply',
'    FROM CUTTING_SPREADING_D',
'    WHERE L_ID = :L_ID;',
'      ',
'',
'    -- Add current value',
'    v_total_entry_ply := v_total_entry_ply + NVL(:EXTRACT_PLY,0);',
'',
unistr('    -- \D83D\DD25 Validation'),
'    IF v_total_entry_ply > v_required_ply AND :APEX$ROW_STATUS != ''D'' THEN',
'        RETURN ''Total Ply ('' || v_total_entry_ply || '') cannot exceed Required Ply ('' || v_required_ply || '')'';',
'    END IF;',
'',
'    RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_associated_column=>'EXTRACT_PLY'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_required_patch=>wwv_flow_imp.id(220244284919810891)
);
