,p_name=>'Calculate used & remaing roll lenght'
,p_event_sequence=>30
,p_triggering_element_type=>'COLUMN'
,p_triggering_region_id=>wwv_flow_imp.id(142761121908032710)
,p_triggering_element=>'ROLL_LENGTH'
