wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(142800762617038250)
,p_event_id=>wwv_flow_imp.id(142800681991038249)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var total_roll_length=($v("ROLL_LENGTH") !=='''')? parseFloat($v("ROLL_LENGTH")) : 0;',
'var lay_length=($v("LAY_LENGTH") !=='''')? parseFloat($v("LAY_LENGTH")) : 0;',
'var extract_ply=($v("EXTRACT_PLY") !=='''')? parseFloat($v("EXTRACT_PLY")) : 0;',
'',
'// auto calculate extract ply',
'extract_ply =  parseInt(total_roll_length / lay_length);',
'$s(''EXTRACT_PLY'',extract_ply);',
'',
'var usedRollLength = 0;',
'if (!isNaN(lay_length) && !isNaN(extract_ply)){',
'    usedRollLength = lay_length * extract_ply;',
'}',
'',
'$s(''USED_ROLL_LENGTH'',usedRollLength);',
'',
'var remaningRollLength = 0;',
'',
'if(total_roll_length === 0){',
'    remaningRollLength = 0;',
'}else if (!isNaN(total_roll_length) && !isNaN(usedRollLength)){',
'    remaningRollLength = total_roll_length - usedRollLength;',
'}',
'',
'$s(''REMAINING_ROLL_LENGTH'',remaningRollLength);',
'',
''))
);
