wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(121928750478941849)
,p_event_id=>wwv_flow_imp.id(121928641447941848)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//   Read Page Item Values',
'var v_carton_id    = $v("P51_MASTER_BARCODE");',
'var v_cust_carton_bc    = $v("P51_CUSTOMER_BARCODE");',
'',
'',
'',
'//   Utility Functions',
'function resetAndFocusScanner(itemName) {',
'    $s(itemName, "");',
'    apex.item(itemName).refresh();',
'    apex.item(itemName).setFocus();',
'}',
'',
'',
'',
'',
'function showError(msg,pID) {',
'    apex.message.alert(msg, function () {',
'        resetAndFocusScanner(pID);',
'    });',
'}',
'',
'',
'//   Validation',
'if (!v_carton_id) {',
'    showError("Please scan Master Barcode Sticker.","P51_MASTER_BARCODE");',
'    return;',
'}',
'',
'if (!v_cust_carton_bc) {',
'    showError("Please scan Customer Barcode Sticker.","P51_CUSTOMER_BARCODE");',
'    return;',
'}',
'',
'//   AJAX Call',
'apex.server.process(',
'    "INSERT_CUST_CARTON_BC_AJAX_CALL",',
'    {',
'        x01: v_carton_id,',
'        x02: v_cust_carton_bc',
'    },',
'    {',
'        dataType: "text",',
'        success: function (pData) {',
'',
'            if (pData && pData.trim() === "SUCCESS") {',
'                resetAndFocus2NDScanner();',
'                // apex.message.showPageSuccess("Customer Barcode inserted successfully");',
'            } else {',
'                apex.message.alert(pData || "Unknown server response");',
'            }',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            apex.message.alert("AJAX Error: " + errorThrown);',
'        }',
'    }',
');',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(121928332864941845)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_CARTON_ID_AJAX_CALL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  ',
'    V_DUPLICATE     NUMBER := 0;',
'    ',
'BEGIN',
'',
'',
' ',
'    SELECT COUNT(*)',
'    INTO V_DUPLICATE',
'    FROM M6_PACK_CUSTOMER_BC_MAPPING',
'    WHERE CARTON_ID = apex_application.g_x01;',
'',
'    IF V_DUPLICATE > 0 THEN',
'        HTP.P(''DUPLICATE BARCODE - ALREADY SCANNED'');',
'        RETURN;',
'    END IF;',
'',
'',
'',
'',
'    INSERT INTO M6_PACK_CUSTOMER_BC_MAPPING (',
'        CARTON_ID       ',
'    ) VALUES (',
'        apex_application.g_x01  ',
'    );',
'',
'    COMMIT;',
'',
'    HTP.P(''MASTER BARCODE SCANNED SUUCESSFULLY'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(''ERROR: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>121928332864941845
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(121928853677941850)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_CUST_CARTON_BC_AJAX_CALL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_MASTER_DUPLICATE     NUMBER := 0;',
'    V_CUSTOMER_DUPLICATE     NUMBER := 0;',
'    ',
'    V_USER_ID               NUMBER;      ',
'BEGIN',
'',
'',
'    BEGIN',
'        SELECT user_id ',
'        INTO V_USER_ID  ',
'        FROM APEX_230200.WWV_FLOW_USERS ',
'        WHERE UPPER(user_name) = UPPER(V(''APP_USER''));',
'    EXCEPTION ',
'        WHEN OTHERS THEN ',
'            V_USER_ID := NULL; ',
'    END; ',
'      SELECT COUNT(*)',
'    INTO V_MASTER_DUPLICATE ',
'    FROM M6_PACK_CUSTOMER_BC_MAPPING',
'    WHERE CARTON_ID = apex_application.g_x01;',
'     ',
'',
'   IF V_MASTER_DUPLICATE > 0 THEN',
'        HTP.P(''DUPLICATE BARCODE FOR MASTER BARCODE STICKER - ALREADY SCANNED'');',
'        RETURN;',
'    END IF;',
'    ',
'    SELECT COUNT(*)',
'    INTO V_CUSTOMER_DUPLICATE',
'    FROM M6_PACK_CUSTOMER_BC_MAPPING',
'    WHERE CUST_CARTON_BC = apex_application.g_x02;',
'',
' ',
'',
'    IF V_CUSTOMER_DUPLICATE > 0 THEN',
'        HTP.P(''DUPLICATE BARCODE FOR CUSTOMER BARCODE STICKER - ALREADY SCANNED'');',
'        RETURN;',
'    END IF;',
'',
'',
'',
'',
'    INSERT INTO M6_PACK_CUSTOMER_BC_MAPPING (',
'       CARTON_ID,',
'       PACKING_CARTON_NO,',
'       CUST_CARTON_BC,',
'       CREATED_BY,',
'       CREATION_DATE',
'',
'    ) VALUES (',
'        apex_application.g_x01,',
'        :P51_PACKING_CARTON_NO,',
'        apex_application.g_x02,',
'        v_user_id,',
'        SYSDATE   ',
'    );',
'',
'    COMMIT;',
'',
'    HTP.P(''CUSTOMER BARCODE SCANNED & INTEGRATE WITH MASTER BARCODE SUUCESSFULLY'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(''ERROR: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>121928853677941850
);
end;
