,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DETAIL_ID2, ',
'       DETAIL_ID, ',
'       DEFECT_CODE, ',
'       POINT1, ',
'       POINT2, ',
'       POINT3, ',
'       POINT4, ',
'       TOTAL_POINT, ',
'       DEFECT_NAME',
'FROM PWC_MFG_FABINS_SECND_D2',
'/*',
'UNION ALL',
'',
'-- Add one empty row only if no real data exists',
'SELECT ',
'       1 AS DETAIL_ID2,',
'       1 AS DETAIL_ID,',
'       NULL AS DEFECT_CODE,',
'       null    AS POINT1,',
'       null    AS POINT2,',
'       null    AS POINT3,',
'       null    AS POINT4,',
'       0    AS TOTAL_POINT,',
'       NULL AS DEFECT_NAME',
'FROM DUAL',
'WHERE NOT EXISTS (',
'    SELECT 1 ',
'    FROM PWC_MFG_FABINS_SECND_D2',
')',
'*/'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
