,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT L.CUT_ID D, L.CUT_ID R',
'FROM CUTTING_SPREADING_L L',
'JOIN CUTTING_SPREADING_H H',
'    ON H.H_ID = L.H_ID',
'WHERE H.tracking_no = :P54_TRACKING_NO',
'AND H.COLOR = :P54_COLOR',
'AND H.POSTED = ''Y''',
'AND NOT EXISTS (',
'    SELECT 1',
'    FROM CUTTING_INSPECTION_H I',
'    WHERE I.CUT_NO = L.CUT_ID',
'    AND I.tracking_no = H.tracking_no',
'    AND I.COLOR = H.COLOR',
')',
'order by l.cut_id asc;'))
