,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT L.BLNC_ROLLS,        ',
'       L.BLNC_YRDS,               ',
'       L.COLOR,        ',
'       L.DJ_CUT_WIDTH,        ',
'       L.FAB_COMP,        ',
'       L.FAB_CONS,        ',
'       L.HEADER_ID,        ',
'       L.INSPECTION,        ',
'       L.PROD_L_ID,        ',
'       pwc_master_tracking_data_func(L.tracking_no, ''BUYER_ID'') BUYER_ID,        ',
'       pwc_master_tracking_data_func(L.tracking_no, ''BUYER_NAME'') BUYER_NAME,        ',
'       pwc_master_tracking_data_func(L.tracking_no, ''STYLE_NAME'') STYLE,        ',
'       pwc_master_tracking_data_func(L.tracking_no, ''STYLE_NO'') STYLE_NO,        ',
'       pwc_master_tracking_data_func(L.tracking_no, ''SEASON_NAME'') SEASON,        ',
'       L.TOTAL_ALOC_ROLLS,        ',
'       L.TOTAL_ALOC_YRDS,        ',
'       L.TOTAL_ALOC_INCH,        ',
'       L.BLNC_INCH,        ',
'       L.RAW_COLOR,        ',
'       L.REMARKS,        ',
'       L.TRACKING_NO,        ',
'       L.FAB_OUNCE,        ',
'       L.CREATION_DATE,        ',
'       L.CREATED_BY,        ',
'       L.LAST_UPDATED_BY,        ',
'       L.LAST_UPDATE_DATE,        ',
'       L.INVENTORY_ITEM_ID,        ',
'       L.LOT_NUMBER,        ',
'       L.READY_FLAG,        ',
'       L.STYLE_CATEGORY,        ',
'       pwc_master_tracking_data_func(L.tracking_no, ''WASH_TYPE'') WASH_TYPE,        ',
'       L.CHILD_STYLE_NO,        ',
'       L.FABRIC_ITEM_ID,        ',
'       L.TOTAL_ALOC_WEIGHT,        ',
'       L.BLNC_WEIGHT,        ',
'       L.SHRINK_PRCNT,        ',
'       (SELECT msi.description        ',
'          FROM apps.mtl_system_items@adf msi        ',
'         WHERE msi.inventory_item_id = L.FABRIC_ITEM_ID        ',
'           AND msi.organization_id = pwc_organization_name(''Inventory Master Org'')) FABRIC_ITEM_DESC,        ',
'    null ORGANIC_AUTH,       ',
'    L.FABRICROL_LINEIDL,      ',
'    L.TOTAL_ALOC_METER,      ',
'    L.TOTAL_BLNC_METER ,     ',
'    L.TRANSFER_TRACKING_NO,    ',
'    L.TRANSFER_SUBINVENTORY,    ',
'    L.TRANSFER_INVENTORY_ITEM_ID,   ',
'    L.TRANSFER_COLOR,   ',
'    L.HANGER_NO, ',
'    L.JOB_NAME, ',
'    (select distinct description   ',
'            from apps.mtl_system_items@adf   ',
'            where inventory_item_id = L.TRANSFER_INVENTORY_ITEM_ID) transfer_item_description,  ',
'    (select distinct ''Y''      ',
'            from PWC_MFG_FABRIC_INS_TEST_L      ',
'            where prod_l_id = L.PROD_L_ID)line_upd_val_flag     ',
'  FROM PWC_MFG_FABINS_PROD_L L',
'  where header_id=:P55_HEADER_ID;'))
