wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(146619354301308212)
,p_name=>'COLOR'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'COLOR'
,p_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_SELECT_LIST'
,p_heading=>'Color'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>140
,p_value_alignment=>'CENTER'
,p_is_required=>true
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT   ',
'       NVL (bll.COLOUR, ''-'') color,   ',
'       NVL (bll.COLOUR, ''-'') color_R',
'       --bll.inventory_item_id,   ',
'       --NULL poc_style_category   ',
'  FROM PWC_ONT_WVN_MASTER_BOM_H bh,   ',
'       PWC_ONT_WVN_MASTER_BOM_ITEMS_L bl,   ',
'       apps.mtl_system_items_b@adf msib,   ',
'       PWC_ONT_WVN_MASTER_BOM_GENRC_D bll,   ',
'       apps.oe_order_headers_all@adf OOHA   ',
' WHERE     bl.HEADER_ID = bh.HEADER_ID   ',
'       AND msib.inventory_item_id = bl.inventory_item_id   ',
'       AND bl.LINE_ID = bll.LINE_ID   ',
'       AND ooha.header_id = bll.SALE_ORDER_ID   ',
'       AND msib.organization_id =   ',
'              pwc_organization_name (''Inventory Master Org'')   ',
'       AND bh.tracking_no = :TRACKING_NO   ',
'       AND bl.inventory_item_id = :FABRIC_ITEM_ID   ',
'       AND NVL (ooha.attribute2, 1) = 1  ',
'       AND NOT EXISTS ',
'                  (SELECT ''X''  ',
'                     FROM PWC_MFG_FABINS_PROD_L ll  , ',
'                     PWC_MFG_FABRIC_INS_TEST_H hh ',
'                    WHERE     ll.color = bll.COLOUR   ',
'                          AND ll.tracking_no = bh.tracking_no   ',
'                          AND ll.fabric_item_id = bl.inventory_item_id   ',
'                          and hh.header_id = ll.header_id ',
'                           and hh.version_no = 2 ',
'                          and ll.header_id = :P55_HEADER_ID)',
''))
,p_lov_display_extra=>true
,p_lov_display_null=>true
,p_lov_cascade_parent_items=>'TRACKING_NO,FABRIC_ITEM_ID'
,p_ajax_items_to_submit=>'TRACKING_NO,FABRIC_ITEM_ID'
,p_ajax_optimize_refresh=>true
,p_filter_is_required=>false
,p_use_as_row_header=>false
,p_enable_hide=>true
,p_is_primary_key=>false
,p_duplicate_value=>true
,p_include_in_export=>true
);
