,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT L.LINE_ID,          ',
'       L.HEADER_ID,          ',
'       L.ROLL_NO,          ',
'       L.ROLL_LENGTH,          ',
'       L.ROLL_WIDTH,          ',
'       L.AW_LENGTH,          ',
