'       L.CUT_WIDTH,          ',
'       L.ALOC_YARD,          ',
'       L.ROLL_LENGTH2,          ',
'       L.BLNC_INCH,          ',
'       L.BLNC_YARDS,          ',
'       L.ALOC_INCH,          ',
'       L.RAW_ITEM_ID,          ',
'       L.SUPP_ROLL_NO,         ',
'       L.CREATION_DATE,         ',
'       L.CREATED_BY,         ',
'       L.LAST_UPDATED_BY,         ',
'       L.LAST_UPDATE_DATE,         ',
'       L.ALOC_MTR,         ',
'       L.BLNC_MTR,         ',
'       L.ROLL_MTR,         ',
'       L.IS_TRANSFERRED,         ',
'       L.SKEWING,         ',
'       L.OPENING_ROLL_NO,         ',
'       L.SUPPLIER_BATCH_NO,         ',
'       L.SUPPLIER_PL_NO,         ',
'       L.ROLL_WEIGHT,         ',
'       L.ALOC_WEIGHT,         ',
'       L.BLNC_WEIGHT,         ',
'       L.LEFT_CENTER_RIGHT,       ',
'       L.ALOC_METER,       ',
'        L.BLNC_METER,       ',
'        L.ACTUL_METER,      ',
'        L.LW_FIRST,      ',
'  L.LW_SECOND ,      ',
'  L.LW_THIRD ,      ',
'  L.WW_FIRST   ,      ',
'  L.WW_SECOND   ,      ',
'  L.WW_THIRD   ,      ',
'  L.BW_REQUIRED    ,      ',
'  L.BW_ACTUAL   ,      ',
'  L.AW_REQUIRED   ,      ',
'  L.AW_ACTUAL  ,      ',
'  L.BLANKET_SEND_TO_WASHDATE ,      ',
'  L.BLANKET_RECEIVED_FROM_WASHDAT ,     ',
'  L.TRANSFER_SELECTION,   ',
'  nvl((select distinct ''Y''     ',
'            from PWC_MFG_FABINS_PTRNALOC_D     ',
'            where 1=1     ',
'            and ROLL_NO = L.ROLL_NO), ''N'') upd_insp_val   ,    ',
'  nvl((select distinct ''Y''    ',
'            from PWC_MFG_FABINSTEST_SHD_LD d    ',
'            where d.roll_no =  L.ROLL_NO), ''N'') shrink_del_check  ,  ',
'            L.shade,  ',
'            L.shrinkage_shade ',
'FROM PWC_MFG_FABRIC_INS_TEST_L L         ',
'WHERE LINE_TYPE= ''P''',
';'))
