'       SD.CREATED_BY,  ',
'       SD.LAST_UPDATED_BY,  ',
'       SD.LAST_UPDATE_DATE,  ',
'       SD.ACTUAL_LENGTH_METER,  ',
'       SD.SUPPLIER_PL_NO,  ',
'       SD.ACTUAL_ROLL_WEIGHT,  ',
'       nvl((select distinct  ''Y''   ',
'            from PWC_INV_FABRIC_ROLL_D   ',
'            where roll_status is not null  ',
'            and roll_sr_no = SD.ROLL_NO), ''N'') FRI_Status , ',
'       nvl((select distinct ''Y''  ',
'                from PWC_MFG_FABINS_PTRNALOC_D d ',
'                where d.roll_no = SD.ROLL_NO),''N'') fab_insp_roll_del_check ',
'FROM PWC_MFG_FABINS_SECND_D SD;'))
