wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(146765333185866212)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ASSIGN_INV_ITEM_ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :COLOR IS NOT NULL THEN',
'BEGIN',
'SELECT DISTINCT   ',
'       bll.inventory_item_id INTO :INVENTORY_ITEM_ID',
'  FROM PWC_ONT_WVN_MASTER_BOM_H bh,   ',
'       PWC_ONT_WVN_MASTER_BOM_ITEMS_L bl,   ',
'       apps.mtl_system_items_b@adf msib,   ',
'       PWC_ONT_WVN_MASTER_BOM_GENRC_D bll,   ',
'       apps.oe_order_headers_all@adf OOHA   ',
' WHERE     bl.HEADER_ID = bh.HEADER_ID   ',
'       AND msib.inventory_item_id = bl.inventory_item_id   ',
'       AND bl.LINE_ID = bll.LINE_ID   ',
'       AND ooha.header_id = bll.SALE_ORDER_ID   ',
'       AND msib.organization_id =   ',
'              pwc_organization_name (''Inventory Master Org'')   ',
'       AND bh.tracking_no = :TRACKING_NO   ',
'       AND bl.inventory_item_id = :FABRIC_ITEM_ID   ',
'       AND NVL (ooha.attribute2, 1) = 1  ',
'              --NVL (NVL (:P_CHILD_STYLE, ooha.attribute2), 1)   ',
'       AND NOT EXISTS ',
'                  (SELECT ''X''  ',
'                     FROM PWC_MFG_FABINS_PROD_L ll  , ',
'                     PWC_MFG_FABRIC_INS_TEST_H hh ',
'                    WHERE     ll.color = bll.COLOUR   ',
'                          AND ll.tracking_no = bh.tracking_no   ',
'                          AND ll.fabric_item_id = bl.inventory_item_id   ',
'                          and hh.header_id = ll.header_id ',
'                           and hh.version_no = 2 ',
'                          and ll.header_id = :P55_HEADER_ID);',
'',
'EXCEPTION',
'WHEN NO_DATA_FOUND THEN NULL;',
'END;',
'END IF;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>146765333185866212
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(146764668720866205)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(373801158374278210)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Line Detail - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'',
'',
'IF :COLOR IS NOT NULL THEN',
'   BEGIN',
'      SELECT bll.inventory_item_id',
'      INTO :INVENTORY_ITEM_ID',
'      FROM PWC_ONT_WVN_MASTER_BOM_H bh,',
'           PWC_ONT_WVN_MASTER_BOM_ITEMS_L bl,',
'           apps.mtl_system_items_b@adf msib,',
'           PWC_ONT_WVN_MASTER_BOM_GENRC_D bll,',
'           apps.oe_order_headers_all@adf ooha',
'      WHERE bl.header_id = bh.header_id',
'        AND msib.inventory_item_id = bl.inventory_item_id',
'        AND bl.line_id = bll.line_id',
'        AND ooha.header_id = bll.sale_order_id',
'        AND msib.organization_id = pwc_organization_name(''Inventory Master Org'')',
'        AND bh.tracking_no = :TRACKING_NO',
'        AND bl.inventory_item_id = :FABRIC_ITEM_ID',
'        AND NVL(ooha.attribute2,1) = 1',
'        AND NOT EXISTS',
'            (',
'              SELECT 1',
'              FROM PWC_MFG_FABINS_PROD_L ll,',
'                   PWC_MFG_FABRIC_INS_TEST_H hh',
'              WHERE ll.color = bll.colour',
'                AND ll.tracking_no = bh.tracking_no',
'                AND ll.fabric_item_id = bl.inventory_item_id',
'                AND hh.header_id = ll.header_id',
'                AND hh.version_no = 2',
'                AND ll.header_id = :P55_HEADER_ID',
'            )',
'        AND ROWNUM = 1;',
'',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         :INVENTORY_ITEM_ID := NULL;',
'      WHEN TOO_MANY_ROWS THEN',
'         NULL;',
'   END;',
'END IF;',
'',
'',
'',
'    CASE :APEX$ROW_STATUS',
'',
'        WHEN ''C'' THEN',
'        ',
'            INSERT INTO PWC_MFG_FABINS_PROD_L',
'            (',
'                BLNC_ROLLS,',
'                BLNC_YRDS,',
'                COLOR,',
'                DJ_CUT_WIDTH,',
'                FAB_COMP,',
'                FAB_CONS,',
'                HEADER_ID,',
'                INSPECTION,',
'               -- PROD_L_ID,',
'                TOTAL_ALOC_ROLLS,',
'                TOTAL_ALOC_YRDS,',
'                TOTAL_ALOC_INCH,',
'                BLNC_INCH,',
'                RAW_COLOR,',
'                REMARKS,',
'                TRACKING_NO,',
'                FAB_OUNCE,',
'                INVENTORY_ITEM_ID,',
'                LOT_NUMBER,',
'                READY_FLAG,',
'                STYLE_CATEGORY,',
'                CHILD_STYLE_NO,',
'                FABRIC_ITEM_ID,',
'                TOTAL_ALOC_WEIGHT,',
'                BLNC_WEIGHT,',
'                SHRINK_PRCNT,',
'                FABRICROL_LINEIDL,',
'                TOTAL_ALOC_METER,',
'                TOTAL_BLNC_METER,',
'                TRANSFER_TRACKING_NO,',
'                TRANSFER_SUBINVENTORY,',
'                TRANSFER_INVENTORY_ITEM_ID,',
'                TRANSFER_COLOR,',
'                HANGER_NO,',
'                JOB_NAME',
'',
'            )',
'            VALUES',
'            (',
'                :BLNC_ROLLS,',
'                :BLNC_YRDS,',
'                :COLOR,',
'                :DJ_CUT_WIDTH,',
'                :FAB_COMP,',
'                :FAB_CONS,',
'                :P55_HEADER_ID,',
'                :INSPECTION,',
'              --  :PROD_L_ID,',
'                :TOTAL_ALOC_ROLLS,',
'                :TOTAL_ALOC_YRDS,',
'                :TOTAL_ALOC_INCH,',
'                :BLNC_INCH,',
'                :RAW_COLOR,',
'                :REMARKS,',
'                :TRACKING_NO,',
'                :FAB_OUNCE,',
'                :INVENTORY_ITEM_ID,',
'                :LOT_NUMBER,',
'                :READY_FLAG,',
'                :STYLE_CATEGORY,',
'                :CHILD_STYLE_NO,',
'                :FABRIC_ITEM_ID,',
'                :TOTAL_ALOC_WEIGHT,',
'                :BLNC_WEIGHT,',
'                :SHRINK_PRCNT,',
'                :FABRICROL_LINEIDL,',
'                :TOTAL_ALOC_METER,',
'                :TOTAL_BLNC_METER,',
'                :TRANSFER_TRACKING_NO,',
'                :TRANSFER_SUBINVENTORY,',
'                :TRANSFER_INVENTORY_ITEM_ID,',
'                :TRANSFER_COLOR,',
'                :HANGER_NO,',
'                :JOB_NAME',
'            )',
'            RETURNING PROD_L_ID INTO :PROD_L_ID;',
'',
'        WHEN ''U'' THEN',
'        ',
'            UPDATE PWC_MFG_FABINS_PROD_L',
'               SET BLNC_ROLLS = :BLNC_ROLLS,',
'                   BLNC_YRDS = :BLNC_YRDS,',
'                   COLOR = :COLOR,',
'                   DJ_CUT_WIDTH = :DJ_CUT_WIDTH,',
'                   FAB_COMP = :FAB_COMP,',
'                   FAB_CONS = :FAB_CONS,',
'                   INSPECTION = :INSPECTION,',
'                   TOTAL_ALOC_ROLLS = :TOTAL_ALOC_ROLLS,',
'                   TOTAL_ALOC_YRDS = :TOTAL_ALOC_YRDS,',
'                   TOTAL_ALOC_INCH = :TOTAL_ALOC_INCH,',
'                   BLNC_INCH = :BLNC_INCH,',
'                   RAW_COLOR = :RAW_COLOR,',
'                   REMARKS = :REMARKS,',
'                   TRACKING_NO = :TRACKING_NO,',
'                   FAB_OUNCE = :FAB_OUNCE,',
'                   INVENTORY_ITEM_ID = :INVENTORY_ITEM_ID,',
'                   LOT_NUMBER = :LOT_NUMBER,',
'                   READY_FLAG = :READY_FLAG,',
'                   STYLE_CATEGORY = :STYLE_CATEGORY,',
'                   CHILD_STYLE_NO = :CHILD_STYLE_NO,',
'                   FABRIC_ITEM_ID = :FABRIC_ITEM_ID,',
'                   TOTAL_ALOC_WEIGHT = :TOTAL_ALOC_WEIGHT,',
'                   BLNC_WEIGHT = :BLNC_WEIGHT,',
'                   SHRINK_PRCNT = :SHRINK_PRCNT,',
'                   FABRICROL_LINEIDL = :FABRICROL_LINEIDL,',
'                   TOTAL_ALOC_METER = :TOTAL_ALOC_METER,',
'                   TOTAL_BLNC_METER = :TOTAL_BLNC_METER,',
'                   TRANSFER_TRACKING_NO = :TRANSFER_TRACKING_NO,',
'                   TRANSFER_SUBINVENTORY = :TRANSFER_SUBINVENTORY,',
'                   TRANSFER_INVENTORY_ITEM_ID = :TRANSFER_INVENTORY_ITEM_ID,',
'                   TRANSFER_COLOR = :TRANSFER_COLOR,',
'                   HANGER_NO = :HANGER_NO,',
'                   JOB_NAME = :JOB_NAME',
'                   ',
'             WHERE PROD_L_ID = :PROD_L_ID;',
'',
'        WHEN ''D'' THEN',
'        ',
'            DELETE FROM PWC_MFG_FABINS_PROD_L',
'             WHERE PROD_L_ID = :PROD_L_ID;',
'',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
