 p_id=>wwv_flow_imp.id(148248592272363416)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(402817166912209791)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'FI 2nd IG - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'    CURSOR c_source IS',
'        SELECT ',
'       l.TRACKING_NO TRACKING_NO,',
'       h.header_id,',
'       d.ROLL_NO,',
'       d.SUPP_ROLL_NO supp_roll_no,',
'       d.roll_weight,',
'       d.aloc_yard,',
'       d.aloc_inch,',
'       d.ALOC_METER aloc_mtr,',
'       d.cut_width,',
'       d.supplier_batch_no,',
'       d.supplier_pl_no,',
'       l.INVENTORY_ITEM_ID',
'  FROM PWC_MFG_FABRIC_INS_TEST_H h,',
'       PWC_MFG_FABINS_PROD_L l,',
'       PWC_MFG_FABRIC_INS_TEST_L d',
' WHERE     h.header_id = l.header_id',
'       AND l.PROD_L_ID = d.PROD_L_ID',
'       AND h.header_id = :P55_HEADER_ID',
'       AND d.roll_no NOT IN (SELECT roll_no FROM PWC_MFG_FABINS_SECND_D where line_id=:LINE_ID);',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'',
'        WHEN ''C'' THEN',
'           FOR rec IN c_source LOOP',
'INSERT INTO PWC_MFG_FABINS_SECND_D',
'            (',
'                LINE_ID,ROLL_NO,ACTUAL_LENGTH,CUT_WIDTH,',
'                ACTUAL_LENGTH_INCH,ROL_ACPT_REJ,',
'                SUPPLIER_ROLL_NO,ACTUAL_LENGTH_METER,ACTUAL_ROLL_WEIGHT',
'            )',
'            VALUES',
'            (',
'                ',
'                :LINE_ID,',
'                 rec.ROLL_NO,',
'                 rec.aloc_yard,',
'                 rec.cut_width,',
'                 rec.aloc_inch,',
'                 :ROL_ACPT_REJ,',
'                 rec.supp_roll_no,',
'                 rec.aloc_mtr,',
'                 rec.roll_weight',
'            );',
'/*',
'            INSERT INTO PWC_MFG_FABINS_SECND_D',
'            (',
'                LINE_ID,',
'                ROLL_NO,',
'                ACTUAL_LENGTH,',
'                CUT_WIDTH,',
'                TOT_PEN_POINTS,',
'                TOT_POINTS,',
'                SHADE_VAR,',
'                BOWING,',
'                SKEWING,',
'                ROL_ACPT_REJ,',
'                REMARKS,',
'                HEADER_ID,',
'                PROD_L_ID,',
'                ACTUAL_LENGTH_INCH,',
'                SUPPLIER_ROLL_NO,',
'                ACTUAL_LENGTH_METER,',
'                SUPPLIER_PL_NO,',
'                ACTUAL_ROLL_WEIGHT',
'            )',
'            VALUES',
'            (',
'                ',
'                :LINE_ID,',
'                :ROLL_NO,',
'                :ACTUAL_LENGTH,',
'                :CUT_WIDTH,',
'                :TOT_PEN_POINTS,',
'                :TOT_POINTS,',
'                :SHADE_VAR,',
'                :BOWING,',
'                :SKEWING,',
'                :ROL_ACPT_REJ,',
'                :REMARKS,',
'                :HEADER_ID,',
'                :PROD_L_ID,',
'                :ACTUAL_LENGTH_INCH,',
'                :SUPPLIER_ROLL_NO,',
'                :ACTUAL_LENGTH_METER,',
'                :SUPPLIER_PL_NO,',
'                :ACTUAL_ROLL_WEIGHT',
'            )',
'*/',
'',
'            END LOOP;',
'',
'           ',
'        WHEN ''U'' THEN',
'            UPDATE PWC_MFG_FABINS_SECND_D',
'            SET LINE_ID            = :LINE_ID,',
'                ROLL_NO            = :ROLL_NO,',
'                ACTUAL_LENGTH      = :ACTUAL_LENGTH,',
'                CUT_WIDTH          = :CUT_WIDTH,',
'                TOT_PEN_POINTS     = :TOT_PEN_POINTS,',
'                TOT_POINTS         = :TOT_POINTS,',
'                SHADE_VAR          = :SHADE_VAR,',
'                BOWING             = :BOWING,',
'                SKEWING            = :SKEWING,',
'                ROL_ACPT_REJ       = :ROL_ACPT_REJ,',
'                REMARKS            = :REMARKS,',
'                HEADER_ID          = :HEADER_ID,',
'                PROD_L_ID          = :PROD_L_ID,',
'                ACTUAL_LENGTH_INCH = :ACTUAL_LENGTH_INCH,',
'                SUPPLIER_ROLL_NO   = :SUPPLIER_ROLL_NO,',
'                ACTUAL_LENGTH_METER= :ACTUAL_LENGTH_METER,',
'                SUPPLIER_PL_NO     = :SUPPLIER_PL_NO,',
'                ACTUAL_ROLL_WEIGHT = :ACTUAL_ROLL_WEIGHT',
'            WHERE DETAIL_ID = :DETAIL_ID;',
'',
'        WHEN ''D'' THEN',
'            DELETE FROM PWC_MFG_FABINS_SECND_D',
'            WHERE DETAIL_ID = :DETAIL_ID;',
'',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>148248592272363416
);
end;
