wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148250493852363435)
,p_process_sequence=>90
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(402817166912209791)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Cal. Base on FI 2nd IG In F1 1st IG '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_COUNT_R           NUMBER;',
'    V_TOTAL_QTY         NUMBER;',
'    V_AVG_CUT_WIDTH     NUMBER;',
'    V_TOT_PNLTY_PNTS    NUMBER;',
'    V_TOT_POINTS        NUMBER;',
'    V_QTY_INCH          NUMBER;',
'    V_QTY_MTR           NUMBER;',
'    V_TOTAL_WEIGHT      NUMBER;',
'BEGIN',
'    -- Get values from detail table',
'    SELECT ',
'        COUNT(*),',
'        SUM(ACTUAL_LENGTH),',
'        NVL(SUM(CUT_WIDTH)/NULLIF(COUNT(*),0),0),',
'        SUM(TOT_PEN_POINTS),',
'        SUM(TOT_POINTS),',
'        SUM(ACTUAL_LENGTH_INCH),',
'        SUM(ACTUAL_LENGTH_METER),',
'        SUM(ACTUAL_ROLL_WEIGHT)',
'    INTO',
'        V_COUNT_R,',
'        V_TOTAL_QTY,',
'        V_AVG_CUT_WIDTH,',
'        V_TOT_PNLTY_PNTS,',
'        V_TOT_POINTS,',
'        V_QTY_INCH,',
'        V_QTY_MTR,',
'        V_TOTAL_WEIGHT',
'    FROM PWC_MFG_FABINS_SECND_D',
'    WHERE LINE_ID = :LINE_ID;',
'',
'    -- Update Header',
'    UPDATE PWC_MFG_FABINS_FIRST_D',
'    SET ',
'        AVG_CUT_WIDTH     = V_AVG_CUT_WIDTH,',
'        NO_CHKD_QTY       = V_TOTAL_QTY,',
'        NO_OF_ROL_CHKD    = V_COUNT_R,',
'        TOT_PNLTY_PNTS    = V_TOT_PNLTY_PNTS,',
'        TOT_POINTS        = V_TOT_POINTS,',
'        TOTAL_RCV_QTY     = V_TOTAL_QTY,',
'        TOTAL_ROL_RCV     = V_COUNT_R,',
'        NO_CHKD_QTY_INCH  = V_QTY_INCH,',
'        NO_CHKD_QTY_MTR   = V_QTY_MTR,',
'        TOTAL_ROLL_WEIGHT = V_TOTAL_WEIGHT',
'    WHERE LINE_ID = :LINE_ID;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>148250493852363435
);
