wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148599180305338722)
,p_process_sequence=>140
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(147655331536134811)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Auto Insertion in PA 2nd IG'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'    CURSOR c_source IS',
'        SELECT ',
'       d.roll_no,        ',
'       d.supp_roll_no,        ',
'       d.opening_roll_no,        ',
'       d.cut_width,        ',
'       d.ACTUL_METER roll_length,      ',
'       d.shrink_length,        ',
'       d.shrink_width,        ',
'       l.color,        ',
'       l.raw_color,        ',
'       pwc_mfg_bss_master_func (l.tracking_no, ''STYLE_NAME'') style,        ',
'       l.Prod_l_id header_id,        ',
'       d.shrink_prc_length,        ',
'       d.shrink_prc_width,        ',
'       d.supplier_batch_no,        ',
'       d.supplier_pl_no,        ',
'       d.roll_weight,   ',
'       shadel.shade        ',
'  FROM pwc_mfg_fabric_ins_test_l d,    ',
'       pwc_mfg_fabins_prod_l l ,   ',
'       pwc_mfg_fabric_ins_test_shd_l shadel,   ',
'       pwc_mfg_fabinstest_shd_ld shaded      ',
' WHERE     line_type = ''P''        ',
'       AND d.prod_l_id = l.prod_l_id    ',
'       and shadel.prod_l_id =  l.prod_l_id    ',
'       and shaded.line_id = shadel.line_id   ',
'       and shaded.roll_no = d.roll_no  ',
'       and shadel.SHADE = NVL(DECODE (:shade, ''null'', null, :shade), shadel.SHADE)   ',
'       AND NOT EXISTS        ',
'                  (SELECT *        ',
'                     FROM pwc_mfg_fabins_ptrnaloc_d sld,        ',
'                          pwc_mfg_fabins_ptrnaloc_l ld,        ',
'                          pwc_mfg_fabins_prod_l ll        ',
'                    WHERE     sld.roll_no = d.roll_no        ',
'                          AND sld.aloc_line_id = ld.aloc_line_id        ',
'                          AND ld.prod_l_id = ll.prod_l_id        ',
'                          AND l.tracking_no = ll.tracking_no        ',
'                          AND l.color = ll.color        ',
'                          AND l.header_id = ll.header_id        ',
'                          AND l.raw_color = ll.raw_color);',
'begin',
' FOR rec IN c_source LOOP',
'',
'INSERT INTO PWC_MFG_FABINS_PTRNALOC_D',
'            (',
'                ROLL_NO,',
'                ALOC_LINE_ID,',
'                SHRINK_LENGTH,',
'                SHRINK_WIDTH,',
'                ROLL_LENGTH,',
'                SUPPLIER_ROLL_NO,',
'                ROLL_WEIGHT,',
