wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144167361021383743)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR c_cutting_data IS',
'        SELECT L.BDL_NO,',
'               H.CUT_NO,',
'               L.SIZE_NAME,',
'               L.BDL_QTY',
'        FROM CUTTING_INSPECTION_H H',
'        JOIN CUTTING_INSPECTION_BUNDLE L',
'          ON H.H_ID = L.H_ID',
'        WHERE H.TRACKING_NO = :P57_TRACKING_NO',
'          AND H.COLOR = :P57_COLOR;',
'BEGIN',
'',
'',
'    -- Pehle purane records delete kar dein taake duplicates na aayein',
'    DELETE FROM M6_ISSUE_TO_SEWING_L',
'    WHERE DOCUMENT_NO = :P57_DOCUMENT_NO;',
'',
'    -- Cursor loop ke through line table me insert',
'    FOR rec IN c_cutting_data LOOP',
'        INSERT INTO M6_ISSUE_TO_SEWING_L',
'        (',
'            DOCUMENT_NO,',
'            CUT_NO,',
'            BUNDLE,',
'            SIZE_WISE,',
'            QTY',
'  ',
'        )',
'        VALUES',
'        (',
'            :P57_DOCUMENT_NO,',
'            rec.CUT_NO,',
'            rec.BDL_NO,',
'            rec.SIZE_NAME,',
'            rec.BDL_QTY',
'       ',
'        );',
'    END LOOP;',
'',
'END;',
'',
'-- DECLARE',
'--     CURSOR c_cutting_data IS',
'--         SELECT L.BDL_NO,',
'--                H.CUT_NO,',
'--                L.SIZE_NAME,',
'--                L.BDL_QTY',
'--         FROM CUTTING_INSPECTION_H H',
'--         JOIN CUTTING_INSPECTION_BUNDLE L',
'--           ON H.H_ID = L.H_ID',
'--         WHERE H.TRACKING_NO = :P57_TRACKING_NO',
'--           AND H.COLOR = :P57_COLOR;',
'-- BEGIN',
'--     FOR rec IN c_cutting_data LOOP',
'--         INSERT INTO M6_ISSUE_TO_SEWING_L (',
'--             DOCUMENT_NO,',
'--             CUT_NO,',
'--             BUNDLE,',
'--             SIZE_WISE,',
'--             QTY',
'--         )',
'--         VALUES (',
'--             :P57_DOCUMENT_NO,',
'--             rec.CUT_NO,',
'--             rec.BDL_NO,',
'--             rec.SIZE_NAME,',
'--             rec.BDL_QTY',
'--         );',
'--     END LOOP;',
'-- END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(145860481197248958)
,p_internal_uid=>144167361021383743
);
