'DECLARE',
'V_MAX_DOC NUMBER;',
'BEGIN',
'-- SELECT  NVL(MAX(header_id),0) +1',
'-- INTO V_MAX_DOC',
'-- from PWC_MFG_ISSUE_TO_WASH_H;',
'-- :P60_header_id:=V_MAX_DOC;',
'',
'INSERT INTO PWC_MFG_ISSUE_TO_WASH_H(',
'       header_id,',
'       CUSTOMER_NAME,',
'       TRACKING_NO,',
'       COLOR,',
'       ISSUE_QTY,',
'       ORDER_QTY,',
'       UNIT,',
'       RECEIVED_BY,',
'       ISSUED_BY,',
'       DOC_DATE,',
'       CREATED_BY,',
'       CREATION_DATE,',
'       LAST_UPDATE_DATE,',
'       LAST_UPDATED_BY',
'       )',
' ',
'VALUES ',
'(',
'        V_MAX_DOC,',
'       :P60_CUSTOMER_NAME,',
'       :P60_TRACKING_NO,',
'       :P60_COLOR,',
'       :P60_ISSUE_QTY,',
'       :P60_ORDER_QTY,',
'       :P60_UNIT,',
'       :P60_RECEIVED_BY,',
'       :P60_ISSUED_BY,',
'       :P60_DOC_DATE,',
'       :P60_CREATED_BY,',
'       :P60_CREATION_DATE,',
'       :P60_LAST_UPDATE_DATE,',
'       :P60_LAST_UPDATED_BY',
');',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(146127924325255142)
