,p_plug_name=>'Search'
,p_region_template_options=>'#DEFAULT#:t-Region--accent2:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>11
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(152258080159427260)
,p_plug_name=>'Washing Recipe'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>21
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tb1.HEADER_ID,              ',
'         tb1.DOC_NUMBER,              ',
'         tb1.DOC_DATE,              ',
'         tb1.SALE_ORDER_ID,              ',
'         tb1.SO_LINE_ID,              ',
'         tb1.TRACKING_NO,              ',
'        --  APPS.pwc_master_tracking_data_func@ADF (tb1.tracking_no,''SEASON_NAME'') SEASON,              ',
'         --tb1.RECIPE_STAGE,              ',
'         ''Bulk'', ',
'        --  to_number(APPS.pwc_master_tracking_data_func@ADF (tb1.tracking_no,''BUYER_ID'')) CUSTOMER_ID,              ',
'         tb1.BRAND,              ',
'        --  APPS.pwc_master_tracking_data_func@ADF (tb1.tracking_no,''STYLE_NAME'') STYLE_NAME,              ',
'        --  APPS.pwc_master_tracking_data_func@ADF (tb1.tracking_no,''STYLE_NO'') STYLE_NO,              ',
'         tb1.QTY,              ',
'         tb1.RECIPE_TYPE,              ',
'         tb1.SAMPLE_TYPE,              ',
'         tb1.SHADE,              ',
'         tb1.Stn_No,              ',
'         tb1.ORG_ID,              ',
'         tb1.Per_Batch_Weight,              ',
'         tb1.Workable_Quantity,              ',
'         tb1.Excess_Cutting_Percent,              ',
'         tb1.Color,              ',
'         tb1.Wash,              ',
'         tb1.Febric_Type,              ',
'         (SELECT ooha.cust_po_number              ',
'            FROM APPS.OE_ORDER_HEADERS_ALL@ADF OOHA              ',
'           WHERE OOHA.HEADER_ID = tb1.Sale_Order_Id)              ',
'            ORDER_NUMBER,              ',
'         DECODE (              ',
'            tb1.RECIPE_STAGE,              ',
'            ''Bulk'', APPS.pwc_master_tracking_data_func@ADF (tb1.tracking_no,''BUYER_NAME''),              ',
'            (SELECT DISTINCT              ',
'                    APPS.pwc_master_tracking_data_func@ADF (samp_h.tracking_no, ''BUYER_NAME'')              ',
'                FROM PWC_ONT_WVN_SAMPLE_STATUS samp_h,              ',
'                     PWC_ONT_WVN_SAMPLE_STATUS_L samp_l              ',
'              WHERE     1 = 1              ',
'                    AND samp_h.tracking_no IS NOT NULL              ',
'                    AND samp_l.header_id = samp_h.header_id              ',
'                    AND samp_l.FINAL_SAMPLE_CODE = tb1.sample_code))              ',
'            CUSTOMER_NAME,              ',
'         tb1.Number_Batches,              ',
'         tb1.Per_Batch_Quantity,              ',
'         tb1.Division,              ',
'         NULL search_stn,              ',
'         NULL header_id_temp,              ',
'         tb1.BP0,              ',
'         tb1.VERSION_NO,              ',
'         tb1.VERSION_DATE,              ',
'         tb1.actual_receipt_qty,              ',
'         CASE              ',
'            WHEN tb1.VERSION_NO IS NULL THEN ''Original''              ',
'            ELSE TO_CHAR (tb1.VERSION_NO)              ',
'         END              ',
'            VARSION_NEW,              ',
'         (SELECT LISTAGG (sl.shades, '','') WITHIN GROUP (ORDER BY sl.shades)              ',
'            FROM PWC_MFG_WASH_RECIPE_SHADE sl              ',
'           WHERE sl.header_id = tb1.HEADER_ID)              ',
'            Shades_L,              ',
'         tb1.Remarks,              ',
'         tb1.LAST_UPDATE_DATE,              ',
'         tb1.LAST_UPDATED_BY,              ',
'         tb1.CREATION_DATE,              ',
'         tb1.CREATED_BY,              ',
'         tb1.Unit_Name,              ',
'         tb1.Comments,              ',
'         tb1.Recipe_Preparer,              ',
'         tb1.INVENTORY_ITEM_ID,              ',
'         tb1.RECIPE_STAGE,              ',
'         tb1.SAMPLE_CODE,              ',
'         tb1.SAMPLE_ITEM,              ',
'         tb1.FABRIC_COMP,              ',
'         tb1.FAB_CONS,              ',
'         tb1.FAB_WEIGHT,              ',
'         tb1.FAB_RECEIVING_DATE,              ',
'         tb1.TOTAL_SMV,              ',
'         tb1.GARMENT_PIECE_WEIGHT,              ',
'         tb1.TOTAL_WEIGHT,              ',
'         tb1.BOM_QTY,              ',
'         tb1.SMV,              ',
'         tb1.WATER_RATIO,              ',
'         tb1.TOTAL_PRODUCTIVITY,              ',
'         tb1.FOR_PRODUCTION,              ',
'         tb1.FOR_SAMPLE,              ',
'         tb1.EIM_SCORE,              ',
'         tb1.DRY_SMV,              ',
'         tb1.TOTAL_DRY_SMV,              ',
'         tb1.BOM_CREATION_DATE,              ',
'         tb1.COPY_TO_ORG_ID,              ',
'         tb1.PER_DAY_PRODUCT,              ',
'         tb1.MACHINE_SMV,              ',
'         tb1.PRODUCTION_STYLE_TYPE,              ',
'         tb1.TOT_WATER_CONS,              ',
'         tb1.PER_PCS_WATER_CONS,              ',
'         (SELECT name               ',
'            FROM apps.hr_operating_units@ADF               ',
'           WHERE organization_id = tb1.COPY_TO_ORG_ID) COPY_TO_ORG_NAME,              ',
'         NULL Current_Style,              ',
'         NULL Current_Season,              ',
'         NULL ORGANIC_AUTH,             ',
'            tb1.PROFILE_VALUE_FLAG,            ',
'            tb1.REFERENCE_NUMBER,            ',
'            tb1.WATER,            ',
'            tb1.STEAM,            ',
'            tb1.ENERGY, ',
'            tb1.STATUS,',
'            tb1.bpo_no             ',
'    FROM PWC_MFG_WASH_RECIPE_H tb1              ',
'   WHERE tb1.ORG_ID = :P64_ORG              ',
'     AND    (''Y'' = pwc_washing_recipe.get_recipe_security_role(tb1.CREATED_BY, :P64_user_id))              ',
'         OR (''N'' <> :P64_key_flag',
'            )              ',
'ORDER BY tb1.HEADER_ID DESC, tb1.DOC_NUMBER DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Washing Recipe'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
