,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tb2.LINE_ID,  ',
'       tb2.HEADER_ID,  ',
'       tb2.MINOR_OPERATIONS,  ',
'       tb2.MAJOR_OPERATIONS,  ',
'       tb2.MAJOR_OP_ID,  ',
'       tb2.SMV,  ',
'       tb2.TEMPERATURE,  ',
'       tb2.WATER,  ',
'       tb2.MIN_TIME,  ',
'       tb2.SEQ,  ',
'       tb2.INTENSITY,  ',
'       tb2.WASH_TYPE, ',
'       tb2.RECIPE_PREPARER,',
'       tb2.EIM_SCORE,',
'       tb2.REMARKS, ',
'       tb2.Number_Batches, ',
'       tb2.Per_Batch_Quantity, ',
'       tb2.Comments, ',
'       tb2.CREATION_DATE, ',
'       tb2.CREATED_BY, ',
'       tb2.LAST_UPDATED_BY, ',
'       tb2.LAST_UPDATE_DATE, ',
'       tb2.NONOPERATION_TIME, ',
'       tb2.DRY_PROCESS_SMV, ',
'       tb2.WATER_RATIO, ',
'       NVL((SELECT DISTINCT qr.character9 ',
'          FROM apps.qa_results_v@adf qr ',
'         WHERE     qr.name = ''PWC_OPERATION_BULLETIN_DETAILS'' ',
'               AND qr.character2 = tb2.MAJOR_OPERATIONS ',
'               AND qr.character3 = tb2.MINOR_OPERATIONS), ''Yes'') ',
'          MACHINE_SMV_CHECK ',
'FROM PWC_MFG_WASH_RECIPE_L tb2',
'where tb2.HEADER_ID=:P65_HEADER_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P65_HEADER_ID'
