,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tb3.DETAIL_ID,  ',
'       tb3.LINE_ID,  ',
'       tb3.INVENTORY_ITEM_ID,  ',
'       tb3.UOM,  ',
'       tb3.PER_BATCH_QTY,  ',
'       tb3.PER_BATCH_CONS,  ',
'       apps.PWC_ITEM_CODE@adf(MSIB.INVENTORY_ITEM_ID, MSIB.ORGANIZATION_ID) ITEM_CODE,  ',
'       MSIB.DESCRIPTION,  ',
'       nvl(tb3.PER_BATCH_QTY,0) * nvl(tb3.PER_BATCH_CONS,0) total_cons,  ',
'       tb3.DOSAGE,  ',
'       tb3.DOSAGE_PERC,  ',
'       tb3.PH_VALUE,  ',
'       tb3.WATER_RATIO,  ',
'       tb3.PCS_PER_ITEM,  ',
'       tb3.Remarks,  ',
'       tb3.Total_Consumption,  ',
'       tb3.CREATION_DATE,  ',
'       tb3.CREATED_BY,  ',
'       tb3.LAST_UPDATED_BY,  ',
'       tb3.LAST_UPDATE_DATE,  ',
'       tb3.ML_PER_LITRE,  ',
'       tb3.SOLUTION_PERC,  ',
'       tb3.SPRAY_QTY,  ',
'       tb3.WEIGHT_KG,  ',
'       tb3.STONE_BAG_WEIGHT,  ',
'       tb3.sequence_no  ',
'  FROM PWC_MFG_WASH_RECIPE_D tb3, apps.mtl_system_items_b@adf msib  ',
' WHERE MSIB.INVENTORY_ITEM_ID = tb3.INVENTORY_ITEM_ID  ',
'   and msib.organization_id = pwc_organization_name(''Inventory Master Org'') ',
'  ',
'   '))
