wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(152206566183427185)
,p_name=>'P65_COLOR'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>470
,p_item_plug_id=>wwv_flow_imp.id(152197427914427157)
,p_item_source_plug_id=>wwv_flow_imp.id(152197427914427157)
,p_prompt=>'Color'
,p_source=>'COLOR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'WASH_RECIPE_COLOR_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select color,   ',
'       inventory_item_id,   ',
'       listagg(cust_po_number, '', '') within group (order by cust_po_number) cust_po_number   ',
'       from (   ',
'select distinct trim (regexp_substr (msib.description,    ',
'                                     ''[^:]+'',    ',
'                                     1,    ',
'                                     3))    ',
'                   color,    ',
'                msib.inventory_item_id,   ',
'                ooha.cust_po_number   ',
'                   ',
'  from apps.oe_order_headers_all@adf ooha,    ',
'       apps.oe_order_lines_all@adf oola,    ',
'       apps.mtl_system_items@adf msib    ',
' where     ooha.header_id = oola.header_id    ',
'       and msib.inventory_item_id = oola.ordered_item_id    ',
'       and msib.organization_id =    ',
'              pwc_organization_name (''Inventory Master Org'')    ',
'       AND ''Bulk'' = :p65_recipe_stage    ',
'       and ooha.attribute4 = :p65_tracking_no    ',
'       and regexp_substr (msib.description,    ',
'                          ''[^:]+'',    ',
'                          1,    ',
'                          2) = :P65_Wash   ',
'       and   trim (regexp_substr (msib.description,    ',
'                                     ''[^:]+'',    ',
'                                     1,    ',
'                                     3)) NOT IN (SELECT     ',
'                       ',
'         PwcMfgWashRecipeH.Color               ',
'          ',
'    FROM PWC_MFG_WASH_RECIPE_H PwcMfgWashRecipeH ',
'    where PwcMfgWashRecipeH.TRACKING_NO = :p65_tracking_no ) ',
'UNION    ',
'select distinct samp_l.FINISH_GARMENTS_COLOR, msi.inventory_item_id , null cust_po_number   ',
'  from PWC_ONT_WVN_SAMPLE_STATUS samp_h, PWC_ONT_WVN_SAMPLE_STATUS_L samp_l, apps.mtl_system_items_kfv@adf msi    ',
' where 1 = 1     ',
'   and samp_l.header_id = samp_h.header_id    ',
'   AND ''Sample'' = :p65_recipe_stage    ',
'   AND msi.organization_id =    ',
'              pwc_organization_name (''Inventory Master Org'')    ',
'   AND msi.concatenated_segments = samp_l.fg_item_code    ',
'   AND :p65_sample_code = samp_l.SAMPLE_LINE_CODE)   ',
'   group by color,   ',
'       inventory_item_id'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_colspan=>4
,p_field_template=>wwv_flow_imp.id(220419589411811080)
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--indicatorAsterisk'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'DIALOG'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'Y'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_08=>'450'
,p_attribute_09=>'350'
);
end;
