'SELECT SAMPLE_LINE_CODE serial_no, ',
'       COMPOSITION, ',
'       CONSTRUCTION, ',
'       MSI.DESCRIPTION ITEM_DESC_SAMPLE, ',
'       SAMP_H.BRAND_NAME BRAND_SAMPLE, ',
'       SAMP_H.BUYER_ID BUYER_ID_SAMPLE, ',
'       (SELECT AC.CUSTOMER_NAME ',
'          FROM apps.AR_CUSTOMERS@adf AC ',
'         WHERE AC.CUSTOMER_ID = SAMP_H.BUYER_ID) ',
'          BUYER_NAME_SAMPLE, ',
'       SAMP_H.STYLE_NAME STYLE_NAME_SAMPLE, ',
'       SAMP_H.SEASON_NAME SEASON_SAMPLE, ',
'       SAMP_H.SAMPLE_TYPE, ',
'       SAMP_LINE.WEIGHT_VALUE FAB_WEIGHT ',
'  FROM PWC_ONT_WVN_SAMPLE_STATUS_L SAMP_LINE, ',
'       apps.MTL_SYSTEM_ITEMS_KFV@adf MSI, ',
'       PWC_ONT_WVN_SAMPLE_STATUS SAMP_H ',
' WHERE     SAMP_LINE.FG_ITEM_CODE = MSI.CONCATENATED_SEGMENTS ',
'       AND SAMP_H.HEADER_ID = SAMP_LINE.HEADER_ID ',
'       AND MSI.ORGANIZATION_ID = ',
'              PWC_ORGANIZATION_NAME (''Inventory Master Org'') ',
'       AND SAMP_LINE.SAMPLE_LINE_CODE IS NOT NULL'))
