wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(152257073351427244)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Washing Recipe'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_HEADER_ID NUMBER;',
'    V_DOC_NUMBER VARCHAR2(50);',
'    V_MAX_NUM NUMBER;',
'BEGIN',
'',
' IF :P65_HEADER_ID IS NULL THEN',
'     -------------------------------------------------',
'     -- INSERT',
'     -------------------------------------------------',
'     -- HEADER_ID generate',
'    SELECT NVL(MAX(HEADER_ID),0) + 1',
'    INTO V_HEADER_ID',
'    FROM PWC_MFG_WASH_RECIPE_H;',
'',
'    SELECT NVL(MAX(TO_NUMBER(SUBSTR(DOC_NUMBER,3))),0) + 1',
'    INTO V_MAX_NUM',
'    FROM PWC_MFG_WASH_RECIPE_H',
'    WHERE DOC_NUMBER LIKE ''B-%'';',
'    V_DOC_NUMBER := ''B-'' || V_MAX_NUM;',
'',
'    INSERT INTO PWC_MFG_WASH_RECIPE_H(',
'        HEADER_ID,',
'        DOC_NUMBER,',
'        DOC_DATE,',
'        SALE_ORDER_ID,',
'        SO_LINE_ID,',
'        BRAND,',
'        QTY,',
'        RECIPE_TYPE,',
'        SAMPLE_TYPE,',
'        SHADE,',
'        STN_NO,',
'        ORG_ID,',
'        NUMBER_BATCHES,',
'        PER_BATCH_QUANTITY,',
'        DIVISION,',
'        PER_BATCH_WEIGHT,',
'        WORKABLE_QUANTITY,',
'        EXCESS_CUTTING_PERCENT,',
'        WASH,',
'        COLOR,',
'        FEBRIC_TYPE,',
'        BP0,',
'        VERSION_NO,',
'        VERSION_DATE,',
'        ACTUAL_RECEIPT_QTY,',
'        REMARKS,',
'        LAST_UPDATE_DATE,',
'        LAST_UPDATED_BY,',
'        CREATION_DATE,',
'        CREATED_BY,',
'        UNIT_NAME,',
'        COMMENTS,',
'        RECIPE_PREPARER,',
'        TRACKING_NO,',
'        INVENTORY_ITEM_ID,',
'        RECIPE_STAGE,',
'        SAMPLE_CODE,',
'        SAMPLE_ITEM,',
'        FABRIC_COMP,',
'        FAB_CONS,',
'        FAB_WEIGHT,',
'        FAB_RECEIVING_DATE,',
'        TOTAL_SMV,',
'        GARMENT_PIECE_WEIGHT,',
'        TOTAL_WEIGHT,',
'        BOM_QTY,',
'        TOTAL_PRODUCTIVITY,',
'        WATER_RATIO,',
'        SMV,',
'        FOR_PRODUCTION,',
'        FOR_SAMPLE,',
'        EIM_SCORE,',
'        DRY_SMV,',
'        TOTAL_DRY_SMV,',
'        BOM_CREATION_DATE,',
'        COPY_TO_ORG_ID,',
'        PER_DAY_PRODUCT,',
'        MACHINE_SMV,',
'        PRODUCTION_STYLE_TYPE,',
'        TOT_WATER_CONS,',
'        PER_PCS_WATER_CONS,',
'        STATUS,',
'        PROFILE_VALUE_FLAG,',
'        WATER,',
'        ENERGY,',
'        STEAM,',
'        REFERENCE_NUMBER,',
'        BPO_NO',
'    )',
'    VALUES (',
unistr('        V_HEADER_ID,          -- \2714 generated'),
unistr('        V_DOC_NUMBER,         -- \2714 generated'),
'        :P65_DOC_DATE,',
'        :P65_SALE_ORDER_ID,',
'        :P65_SO_LINE_ID,',
'        :P65_BRAND,',
'        :P65_QTY,',
'        :P65_RECIPE_TYPE,',
'        :P65_SAMPLE_TYPE,',
'        :P65_SHADE,',
'        :P65_STN_NO,',
'        nvl(:P65_ORG_ID,85),',
'        :P65_NUMBER_BATCHES,',
'        :P65_PER_BATCH_QUANTITY,',
'        :P65_DIVISION,',
'        :P65_PER_BATCH_WEIGHT,',
'        :P65_WORKABLE_QUANTITY,',
'        :P65_EXCESS_CUTTING_PERCENT,',
'        :P65_WASH,',
'        :P65_COLOR,',
'        :P65_FEBRIC_TYPE,',
'        :P65_BP0,',
'        :P65_VERSION_NO,',
'        :P65_VERSION_DATE,',
'        :P65_ACTUAL_RECEIPT_QTY,',
'        :P65_REMARKS,',
'        SYSDATE,              -- better',
'        723155,',
'        SYSDATE,              -- better',
'        723155,',
'        :P65_UNIT_NAME,',
'        :P65_COMMENTS,',
'        :P65_RECIPE_PREPARER,',
'        :P65_TRACKING_NO,',
'        :P65_INVENTORY_ITEM_ID,',
'        :P65_RECIPE_STAGE,',
'        :P65_SAMPLE_CODE,',
'        :P65_SAMPLE_ITEM,',
'        :P65_FABRIC_COMP,',
'        :P65_FAB_CONS,',
'        :P65_FAB_WEIGHT,',
'        :P65_FAB_RECEIVING_DATE,',
'        :P65_TOTAL_SMV,',
'        :P65_GARMENT_PIECE_WEIGHT,',
'        :P65_TOTAL_WEIGHT,',
'        :P65_BOM_QTY,',
'        :P65_TOTAL_PRODUCTIVITY,',
'        :P65_WATER_RATIO,',
'        :P65_SMV,',
'        :P65_FOR_PRODUCTION,',
'        :P65_FOR_SAMPLE,',
'        :P65_EIM_SCORE,',
'        :P65_DRY_SMV,',
'        :P65_TOTAL_DRY_SMV,',
'        :P65_BOM_CREATION_DATE,',
'        :P65_COPY_TO_ORG_ID,',
'        :P65_PER_DAY_PRODUCT,',
'        :P65_MACHINE_SMV,',
'        :P65_PRODUCTION_STYLE_TYPE,',
'        :P65_TOT_WATER_CONS,',
'        :P65_PER_PCS_WATER_CONS,',
'        :P65_STATUS,',
'        :P65_PROFILE_VALUE_FLAG,',
'        :P65_WATER,',
'        :P65_ENERGY,',
'        :P65_STEAM,',
'        :P65_REFERENCE_NUMBER,',
'        :P65_BPO_NO);',
'     -- Set page item (important for next update)',
'        :P65_HEADER_ID := V_HEADER_ID;',
'ELSE',
'        UPDATE PWC_MFG_WASH_RECIPE_H',
'        SET',
'        DOC_DATE                = :P65_DOC_DATE,',
'        SALE_ORDER_ID           = :P65_SALE_ORDER_ID,',
'        SO_LINE_ID              = :P65_SO_LINE_ID,',
'        BRAND                   = :P65_BRAND,',
'        QTY                     = :P65_QTY,',
'        RECIPE_TYPE             = :P65_RECIPE_TYPE,',
'        SAMPLE_TYPE             = :P65_SAMPLE_TYPE,',
'        SHADE                   = :P65_SHADE,',
'        STN_NO                  = :P65_STN_NO,',
'        ORG_ID                  = nvl(:P65_ORG_ID,85),',
'        NUMBER_BATCHES          = :P65_NUMBER_BATCHES,',
'        PER_BATCH_QUANTITY      = :P65_PER_BATCH_QUANTITY,',
'        DIVISION                = :P65_DIVISION,',
'        PER_BATCH_WEIGHT        = :P65_PER_BATCH_WEIGHT,',
'        WORKABLE_QUANTITY       = :P65_WORKABLE_QUANTITY,',
'        EXCESS_CUTTING_PERCENT  = :P65_EXCESS_CUTTING_PERCENT,',
'        WASH                    = :P65_WASH,',
'        COLOR                   = :P65_COLOR,',
'        FEBRIC_TYPE             = :P65_FEBRIC_TYPE,',
'        BP0                     = :P65_BP0,',
'        VERSION_NO              = :P65_VERSION_NO,',
'        VERSION_DATE            = :P65_VERSION_DATE,',
'        ACTUAL_RECEIPT_QTY      = :P65_ACTUAL_RECEIPT_QTY,',
'        REMARKS                 = :P65_REMARKS,',
'        UNIT_NAME               = :P65_UNIT_NAME,',
'        COMMENTS                = :P65_COMMENTS,',
'        RECIPE_PREPARER         = :P65_RECIPE_PREPARER,',
'        TRACKING_NO             = :P65_TRACKING_NO,',
'        INVENTORY_ITEM_ID       = :P65_INVENTORY_ITEM_ID,',
'        RECIPE_STAGE            = :P65_RECIPE_STAGE,',
'        SAMPLE_CODE             = :P65_SAMPLE_CODE,',
'        SAMPLE_ITEM             = :P65_SAMPLE_ITEM,',
'        FABRIC_COMP             = :P65_FABRIC_COMP,',
'        FAB_CONS                = :P65_FAB_CONS,',
'        FAB_WEIGHT              = :P65_FAB_WEIGHT,',
'        FAB_RECEIVING_DATE      = :P65_FAB_RECEIVING_DATE,',
'        TOTAL_SMV               = :P65_TOTAL_SMV,',
'        GARMENT_PIECE_WEIGHT    = :P65_GARMENT_PIECE_WEIGHT,',
'        TOTAL_WEIGHT            = :P65_TOTAL_WEIGHT,',
'        BOM_QTY                 = :P65_BOM_QTY,',
'        TOTAL_PRODUCTIVITY      = :P65_TOTAL_PRODUCTIVITY,',
'        WATER_RATIO             = :P65_WATER_RATIO,',
'        SMV                     = :P65_SMV,',
'        FOR_PRODUCTION          = :P65_FOR_PRODUCTION,',
'        FOR_SAMPLE              = :P65_FOR_SAMPLE,',
'        EIM_SCORE               = :P65_EIM_SCORE,',
'        DRY_SMV                 = :P65_DRY_SMV,',
'        TOTAL_DRY_SMV           = :P65_TOTAL_DRY_SMV,',
'        BOM_CREATION_DATE       = :P65_BOM_CREATION_DATE,',
'        COPY_TO_ORG_ID          = :P65_COPY_TO_ORG_ID,',
'        PER_DAY_PRODUCT         = :P65_PER_DAY_PRODUCT,',
'        MACHINE_SMV             = :P65_MACHINE_SMV,',
'        PRODUCTION_STYLE_TYPE   = :P65_PRODUCTION_STYLE_TYPE,',
'        TOT_WATER_CONS          = :P65_TOT_WATER_CONS,',
'        PER_PCS_WATER_CONS      = :P65_PER_PCS_WATER_CONS,',
'        STATUS                  = :P65_STATUS,',
'        PROFILE_VALUE_FLAG      = :P65_PROFILE_VALUE_FLAG,',
'        WATER                   = :P65_WATER,',
'        ENERGY                  = :P65_ENERGY,',
'        STEAM                   = :P65_STEAM,',
'        REFERENCE_NUMBER        = :P65_REFERENCE_NUMBER,',
'        BPO_NO                  = :P65_BPO_NO,',
'        LAST_UPDATED_BY         = 723155,',
'        LAST_UPDATE_DATE        = SYSDATE',
'        WHERE HEADER_ID         = :P65_HEADER_ID;',
'    END IF;',
'',
'EXCEPTION ',
