wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(152386831758225234)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(152384092631225206)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Operations Detail'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'v_line_id number;',
'BEGIN',
'  CASE :APEX$ROW_STATUS',
'    /* ========= INSERT ========= */',
'    WHEN ''C'' THEN',
'     ',
'	 select NVL(MAX(LINE_ID),0)+1',
'	 INTO	v_line_id',
'	 FROM PWC_MFG_WASH_RECIPE_L;',
'	 ',
'            INSERT INTO PWC_MFG_WASH_RECIPE_L (',
'            ',
'			',
'				LINE_ID,',
'				HEADER_ID,',
'				MINOR_OPERATIONS,',
'				MAJOR_OPERATIONS,',
'				MAJOR_OP_ID,',
'				SMV,',
'				TEMPERATURE,',
'				WATER,',
'				MIN_TIME,',
'				SEQ,',
'				INTENSITY,',
'				WASH_TYPE,',
'				REMARKS,',
'				PER_BATCH_QUANTITY,',
'				NUMBER_BATCHES,',
'				COMMENTS,',
'				RECIPE_PREPARER,',
'				LAST_UPDATE_DATE,',
'				LAST_UPDATED_BY,',
'				CREATION_DATE,',
'				CREATED_BY,',
'				NONOPERATION_TIME,',
'				EIM_SCORE,',
'				DRY_PROCESS_SMV,',
'				WATER_RATIO)',
'      VALUES (',
'	  		',
'            v_line_id,',
'			:HEADER_ID,',
'			:MINOR_OPERATIONS,',
'			:MAJOR_OPERATIONS,',
'			:MAJOR_OP_ID,',
'			:SMV,',
'			:TEMPERATURE,',
'			:WATER,',
'			:MIN_TIME,',
'			:SEQ,',
'			:INTENSITY,',
'			:WASH_TYPE,',
'			:REMARKS,',
'			:PER_BATCH_QUANTITY,',
'			:NUMBER_BATCHES,',
'			:COMMENTS,',
'			:RECIPE_PREPARER,',
'			:LAST_UPDATE_DATE,',
'			:LAST_UPDATED_BY,',
'			:CREATION_DATE,',
'			:CREATED_BY,',
'			:NONOPERATION_TIME,',
'			:EIM_SCORE,',
'			:DRY_PROCESS_SMV,',
'			:WATER_RATIO)',
'            RETURNING LINE_ID INTO :LINE_ID;',
'',
'     ',
'    /* ========= UPDATE ========= */',
'    WHEN ''U'' THEN',
'',
'      UPDATE PWC_MFG_WASH_RECIPE_L',
'      SET ',
