wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(152493781052752302)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(444263312662509758)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Weight Details - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN  -- Create (Insert)',
'            INSERT INTO PWC_EXP_PACKING_LIST_WEIGHT (',
'                WEIGHT_DETAIL_ID,',
'                PACKING_LIST_ID,',
'                SIZE_DETAILS,',
'                NET_WEIGHT,',
'                NET_NET_WEIGHT,',
'                COLOR,',
'                DCPI_NO,',
'                REMARKS_WEIGHT,',
'                INVENTORY_ITEM,',
'                ITEM_DESCRIPTION,',
'                SIZE_COLOR,',
'                WEIGHT_INSEAM,',
'                CREATED_BY,',
'                CREATION_DATE',
'            ) VALUES (',
'                PWC_EXP_PACKING_LIST_WEIGHT_S.NEXTVAL,',
'                :P67_PACKING_LIST_ID,',
'                :SIZE_DETAILS,',
'                :NET_WEIGHT,',
'                :NET_NET_WEIGHT,',
'                :COLOR,',
'                :DCPI_NO,',
'                :REMARKS_WEIGHT,',
'                :INVENTORY_ITEM,',
'                :ITEM_DESCRIPTION,',
'                :SIZE_COLOR,',
'                :WEIGHT_INSEAM,',
'                :APP_USER,',
'                SYSDATE',
'            );',
'',
'        WHEN ''U'' THEN  -- Update',
'            UPDATE PWC_EXP_PACKING_LIST_WEIGHT',
'               SET SIZE_DETAILS        = :SIZE_DETAILS,',
'                   NET_WEIGHT          = :NET_WEIGHT,',
'                   NET_NET_WEIGHT      = :NET_NET_WEIGHT,',
'                   COLOR               = :COLOR,',
'                   DCPI_NO             = :DCPI_NO,',
'                   REMARKS_WEIGHT      = :REMARKS_WEIGHT,',
'                   INVENTORY_ITEM      = :INVENTORY_ITEM,',
'                   ITEM_DESCRIPTION    = :ITEM_DESCRIPTION,',
'                   SIZE_COLOR          = :SIZE_COLOR,',
'                   WEIGHT_INSEAM       = :WEIGHT_INSEAM,',
'                   LAST_UPDATED_BY     = :APP_USER,',
'                   LAST_UPDATE_DATE    = SYSDATE',
'             WHERE WEIGHT_DETAIL_ID = :WEIGHT_DETAIL_ID;',
'',
'        WHEN ''D'' THEN  -- Delete',
'            DELETE FROM PWC_EXP_PACKING_LIST_WEIGHT',
'             WHERE WEIGHT_DETAIL_ID = :WEIGHT_DETAIL_ID;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>152493781052752302
);
