 p_id=>wwv_flow_imp.id(150678538797077242)
,p_plug_name=>'Washing Operation Plan'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h2:t-ContentBlock--shadowBG'
,p_plug_template=>wwv_flow_imp.id(220313214896810970)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  SELECT HederEO.GWP_GE_ID,  ',
'         HederEO.GWP_GE_NUMBER,  ',
'         HederEO.GE_DATE,  ',
'         HederEO.SALESORDER_ID,  ',
'         HederEO.DOUBLE_WASH,  ',
'         HederEO.AVG_GARMENT_DAY,  ',
'         HederEO.REMARKS,  ',
'         HederEO.LAST_UPDATE_DATE,  ',
'         HederEO.LAST_UPDATED_BY,  ',
'         HederEO.CREATION_DATE,  ',
'         HederEO.CREATED_BY,  ',
'         HederEO.GE_STATUS,  ',
'         HederEO.SO_HEADER_ID,  ',
'         HederEO.ORG_ID,  ',
'         pwc_master_tracking_data_func@adf (HederEO.tracking_no, ''BUYER_ID'') Customer_Id,  ',
'         HederEO.Quantity,  ',
'         (SELECT ooha.ORDER_NUMBER  ',
'            FROM apps.oe_order_headers_all@adf ooha  ',
'           WHERE ooha.HEADER_ID = HederEO.SALESORDER_ID)  ',
'            order_number, HederEO.tracking_no,  ',
'         pwc_master_tracking_data_func@adf (HederEO.tracking_no, ''BUYER_NAME'') customer_name,  ',
'         pwc_master_tracking_data_func@adf (HederEO.tracking_no, ''SEASON_NAME'') SEASON,  ',
'         HederEO.BRAND,  ',
'         HederEO.DIVISION,  ',
'         pwc_master_tracking_data_func@adf (HederEO.tracking_no, ''STYLE_NAME'') STYLE,  ',
'         pwc_master_tracking_data_func@adf (HederEO.tracking_no, ''STYLE_NO'') STYLE_NO,  ',
'         HederEO.WASH,            ',
'         HederEO.INVENTORY_ITEM_ID,  ',
'         HederEO.VERSION_NO,  ',
'         HederEO.VERSION_DATE,  ',
'         CASE  ',
'            WHEN HederEO.VERSION_NO IS NULL THEN ''Original''  ',
'            ELSE TO_CHAR (HederEO.VERSION_NO)  ',
'         END  ',
'            VARSION_NEW,  ',
'         (SELECT prha.segment1  ',
'            FROM apps.po_requisition_headers_all@adf prha  ',
'           WHERE     prha.org_id = HederEO.ORG_ID  ',
'                 AND prha.attribute14 = to_char(HederEO.GWP_GE_ID ) ',
'                 AND ROWNUM = 1)  ',
'            PR_Num,  ',
'         HederEO.Color,  ',
'         HederEO.Transaction_Date,  ',
'         round(HederEO.SMV,6) AS SMV ,',
'         HederEO.OSP,',
'         HederEO.RANGE_POSTED,',
'         HederEO.TOTAL_ORDER_QUANTITY,  ',
'         HederEO.RECIPE_VERSION_NO,  ',
'         HederEO.FETCHED_RECIPE_VERSION_NO,  ',
'         NULL CURRENT_STYLE,  ',
'         NULL CURRENT_SEASON,  ',
'         null ORGANIC_AUTH  ',
'    FROM PWC_GWP_MFG_GEVALUATION HederEO  ',
'   --WHERE HederEO.ORG_ID = 85--:p_org  ',
'   ORDER BY HederEO.GWP_GE_ID DESC'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
