wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(148106205235980231)
,p_plug_name=>'StyleDetail'
,p_parent_plug_id=>wwv_flow_imp.id(151168785543482823)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tb2.GWP_GE_ID,              ',
'         tb2.GWP_GE_WASLINE_ID,              ',
'         tb2.GWP_GE_OBID,              ',
'         tb2.SALESORDER,              ',
'         tb2.SO_LINE,              ',
'         tb2.GWP_UNIT_ID,              ',
'         tb2.LAST_UPDATE_DATE,              ',
'         tb2.LAST_UPDATED_BY,              ',
'         tb2.CREATION_DATE,              ',
'         tb2.WASHING_END_DATE,              ',
'         tb2.CREATED_BY,              ',
'         tb2.OBS_NO,              ',
'         tb2.QUANTITY,              ',
'         tb2.POST_STATUS,              ',
'         tb2.JOB_STATUS,              ',
'         tb2.WIP_ENTITY_ID,              ',
'         tb2.JOB_RELEASED_DATE,              ',
'         tb2.WASH_NAME,              ',
'         tb2.WASHING_UNIT_NAME,              ',
'         tb2.WASHING_START_DATE,              ',
'         tb2.STITCHING_UNIT,              ',
'         tb2.STITCHING_START_DATE,              ',
'         tb2.VIEW_SHIPMENT_DETAIL,              ',
'         tb2.Tem_Code,              ',
'         tb2.REMARKS,              ',
'         (SELECT MSI.description              ',
'            FROM apps.MTL_SYSTEM_ITEMS_KFV@adf MSI              ',
'           WHERE     MSI.INVENTORY_ITEM_ID = tb2.item_id              ',
'                 AND MSI.ORGANIZATION_ID =              ',
'                        pwc_organization_name (''Inventory Master Org''))              ',
'            Description,              ',
'         tb2.Shipment_Qty,              ',
'         tb2.Shipment_Date,              ',
'         tb2.Country_Change,              ',
'         tb2.item_id,              ',
'         tb2.CURRENT_PLAN_QTY,              ',
'        (SELECT j.wip_entity_name             ',
'          FROM apps.wip_discrete_jobs_v@adf j, pwc_gwp_mfg_gevaluation wop             ',
'         WHERE     wop.gwp_ge_id = tb2.gwp_ge_id             ',
'               AND j.attribute2 = wop.tracking_no             ',
'               AND j.status_type NOT IN (7)             ',
'               and j.class_code = ''Washing''            ',
'               AND j.attribute6 = wop.gwp_ge_id            ',
'               AND j.attribute_category = ''Discrete Job - M6''             ',
'               AND ROWNUM = 1)  Job_Name,              ',
'         tb2.Balance_Qty,              ',
'         ROUND (              ',
'              tb2.quantity              ',
'            * (  (  (SELECT AVG (EXTRA_CUT_PERCENT) EXTRA_CUT_PERCENT              ',
'                       FROM PWC_MFG_RATIOPLAN mmr, PWC_GWP_MFG_GEVALUATION smr              ',
'                      WHERE     smr.gwp_ge_id = tb2.gwp_ge_id              ',
'                            AND mmr.tracking_no = smr.tracking_no              ',
'                            AND mmr.COLOR = smr.color)              ',
'                  / 100)              ',
'               + 1))              ',
'            Ordered_Quantity,              ',
'       (SELECT DISTINCT ooha.attribute12              ',
'          FROM apps.oe_order_headers_all@adf ooha, apps.oe_order_lines_all@adf oola              ',
'         WHERE     ooha.attribute12 IS NOT NULL              ',
'               AND ooha.header_id = oola.header_id              ',
'               AND ooha.attribute4 =              ',
'                      (SELECT h.tracking_no              ',
'                         FROM pwc_gwp_mfg_gevaluation h              ',
'                        WHERE h.gwp_ge_id = tb2.gwp_ge_id)              ',
'               AND ooha.cust_po_number || ''/'' || oola.line_number =              ',
'                      tb2.OBS_NO              ',
'               AND oola.inventory_item_id = tb2.item_id)              ',
'          replace_bpo,         ',
'          tb2.extra_quantity,              ',
'        nvl((SELECT distinct ''Y''           ',
'          FROM apps.wip_discrete_jobs_v@adf j, pwc_gwp_mfg_gevaluation wop             ',
'         WHERE     wop.gwp_ge_id = tb2.gwp_ge_id             ',
'               AND j.attribute2 = wop.tracking_no             ',
'               AND j.status_type NOT IN (7)             ',
'               and j.class_code = ''Washing''            ',
'               AND j.attribute6 = wop.gwp_ge_id            ',
'               AND j.attribute_category = ''Discrete Job - M6''             ',
'               AND ROWNUM = 1), ''N'')  upd_del_check  ,   ',
'               tb2.EXTRA_QUANTITY TOTAL_ORDER_QTY,   ',
'               (tb2.EXTRA_QUANTITY - tb2.BALANCE_QTY)COLOR_WISE_QTY,   ',
'               tb2.BALANCE_QTY WIP_BALANCE_QTY       ',
'    FROM PWC_GWP_MFG_GE_OBSLINE tb2',
'    where tb2.GWP_GE_ID=:P69_GWP_GE_ID;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P69_GWP_GE_ID'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'StyleDetail'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
