wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(150708002002077298)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Washing Operation Plan'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_header_id       NUMBER;',
'    v_gwp_number      VARCHAR2(20);',
'    v_count           NUMBER;',
'BEGIN',
'       ',
'        -- Only generate new ID if INSERT',
'        IF :P69_GWP_GE_ID IS NULL  THEN',
'            SELECT NVL(MAX(GWP_GE_ID),0) + 1',
'              INTO v_header_id',
'              FROM PWC_GWP_MFG_GEVALUATION;',
'',
'            -- Build GWP_GE_NUMBER as ''YYYY/ID''',
'            v_gwp_number := TO_CHAR(SYSDATE,''YYYY'') || ''/'' || v_header_id;',
'',
'            -- Assign to page items',
'            :P69_GWP_GE_ID     := v_header_id;',
'            :P69_GWP_GE_NUMBER := v_gwp_number;',
'        END IF;',
'',
'        -- Check if record exists',
'        SELECT COUNT(*) ',
'          INTO v_count',
'          FROM PWC_GWP_MFG_GEVALUATION',
'         WHERE GWP_GE_ID = :P69_GWP_GE_ID;',
'',
'        IF v_count > 0 THEN',
'            -- UPDATE existing record',
'            UPDATE PWC_GWP_MFG_GEVALUATION',
'               SET GWP_GE_NUMBER          = :P69_GWP_GE_NUMBER,',
'                   GE_DATE                = :P69_GE_DATE,',
'                   SALESORDER_ID          = :P69_SALESORDER_ID,',
'                   DOUBLE_WASH            = :P69_DOUBLE_WASH,',
'                   AVG_GARMENT_DAY        = :P69_AVG_GARMENT_DAY,',
'                   REMARKS                = :P69_REMARKS,',
'                   LAST_UPDATE_DATE       = :P69_LAST_UPDATE_DATE,',
'                   LAST_UPDATED_BY        = :P69_LAST_UPDATED_BY,',
'                   CREATION_DATE          = :P69_CREATION_DATE,',
'                   CREATED_BY             = :P69_CREATED_BY,',
'                   GE_STATUS              = :P69_GE_STATUS,',
'                   QUANTITY               = :P69_QUANTITY,',
'                   BRAND                  = :P69_BRAND,',
'                   DIVISION               = :P69_DIVISION,',
'                   OSP                    = :P69_OSP,',
'                   WASH                   = :P69_WASH,',
'                   VERSION_NO             = :P69_VERSION_NO,',
'                   VERSION_DATE           = :P69_VERSION_DATE,',
'                   COLOR                  = :P69_COLOR,',
'                   RANGE_POSTED           = :P69_RANGE_POSTED,',
'                   TRANSACTION_DATE       = :P69_TRANSACTION_DATE,',
'                   TOTAL_ORDER_QUANTITY   = :P69_TOTAL_ORDER_QUANTITY,',
'                   TRACKING_NO            = :P69_TRACKING_NO,',
'                   INVENTORY_ITEM_ID      = :P69_INVENTORY_ITEM_ID,',
'                   SMV                    = :P69_SMV,',
'                   RECIPE_VERSION_NO      = :P69_RECIPE_VERSION_NO,',
'                   FETCHED_RECIPE_VERSION_NO = :P69_FETCHED_RECIPE_VERSION_NO',
'             WHERE GWP_GE_ID                 = :P69_GWP_GE_ID;',
'',
'            apex_application.g_print_success_message := ''Header updated: '' || :P69_GWP_GE_ID;',
'',
'        ELSE',
'            -- INSERT new record',
'            INSERT INTO PWC_GWP_MFG_GEVALUATION (',
'                GWP_GE_ID, GWP_GE_NUMBER, GE_DATE, SALESORDER_ID, DOUBLE_WASH,',
'                AVG_GARMENT_DAY, REMARKS, LAST_UPDATE_DATE, LAST_UPDATED_BY,',
'                CREATION_DATE, CREATED_BY, GE_STATUS, SO_HEADER_ID, ORG_ID,',
'                QUANTITY, BRAND, DIVISION, OSP, WASH, VERSION_NO, VERSION_DATE,',
'                COLOR, RANGE_POSTED, TRANSACTION_DATE, TOTAL_ORDER_QUANTITY,',
'                TRACKING_NO, INVENTORY_ITEM_ID, SMV, RECIPE_VERSION_NO, FETCHED_RECIPE_VERSION_NO',
'            )',
'            VALUES (',
'                :P69_GWP_GE_ID, :P69_GWP_GE_NUMBER, :P69_GE_DATE, :P69_SALESORDER_ID, :P69_DOUBLE_WASH,',
'                :P69_AVG_GARMENT_DAY, :P69_REMARKS, :P69_LAST_UPDATE_DATE, :P69_LAST_UPDATED_BY,',
'                :P69_CREATION_DATE, :P69_CREATED_BY, :P69_GE_STATUS, :P69_SO_HEADER_ID, :P69_ORG_ID,',
'                :P69_QUANTITY, :P69_BRAND, :P69_DIVISION, :P69_OSP, :P69_WASH, :P69_VERSION_NO, :P69_VERSION_DATE,',
'                :P69_COLOR, :P69_RANGE_POSTED, :P69_TRANSACTION_DATE, :P69_TOTAL_ORDER_QUANTITY,',
'                :P69_TRACKING_NO, :P69_INVENTORY_ITEM_ID, :P69_SMV, :P69_RECIPE_VERSION_NO, :P69_FETCHED_RECIPE_VERSION_NO',
'            );',
'',
'            apex_application.g_print_success_message := ''Header inserted: '' || :P69_GWP_GE_ID;',
'        END IF;',
'   ',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>150708002002077298
);
