'			:HELPER_SMV, ',
'			:OPERAT_OBLINE_ID, ',
'			:EMB_NO_STITCH, ',
'			:S_NO, ',
'			:HEADER_ID, ',
'			--:OP_LINE_ID, ',
'			:OB_LINES_ID, ',
'			:GWP_GE_OBID, ',
'			:MINOR_OPERATIONS, ',
'			:MAJOR_OPERATIONS, ',
'			:WATER, ',
'			:TIME, ',
'			:SEQUENCE, ',
'			:WASH_TYPE, ',
'			:SEQ,',
'			:EIM_SCORE,',
'			:NONOPERATION_TIME)',
'            RETURNING OP_LINE_ID INTO :OP_LINE_ID;',
'',
'     ',
'    /* ========= UPDATE ========= */',
'    WHEN ''U'' THEN',
'',
'      UPDATE PWC_MFG_ROUTING_PLAN_DET',
'      SET ',
'            OPERATION_ID      =:OPERATION_ID, ',
'			OPERAT_LINE_ID          =:OPERAT_LINE_ID, ',
'			COMPANY_ID              =:COMPANY_ID, ',
'			DIVISION_ID             =:DIVISION_ID, ',
'			PLAN_ID                 =:PLAN_ID, ',
'			PROCESS_ID              =:PROCESS_ID, ',
'			OC_ID                   =:OC_ID, ',
'			TC_TOPSIDE              =:TC_TOPSIDE, ',
'			TC_INSIDE               =:TC_INSIDE, ',
'			MACHINE_TYPE            =:MACHINE_TYPE, ',
'			NO_OF_MACHINES          =:NO_OF_MACHINES, ',
'			FOOT_ID                 =:FOOT_ID, ',
'			GUAGE_ID                =:GUAGE_ID, ',
'			NO_OF_WP                =:NO_OF_WP, ',
'			SMV                     =:SMV, ',
'			USER_ID                 =:USER_ID, ',
'			USER_DATE               =:USER_DATE, ',
'			TERMINAL_ID             =:TERMINAL_ID, ',
'			LINE_NUM                =:LINE_NUM, ',
'			TARGET                  =:TARGET, ',
'			POINTS                  =:POINTS, ',
'			NDL_TIME                =:NDL_TIME, ',
'			TOT_TIME                =:TOT_TIME, ',
'			SP_INST                 =:SP_INST, ',
'			RESOURCE_ID             =:RESOURCE_ID, ',
'			P_MACHINE_TYPE          =:P_MACHINE_TYPE, ',
'			RESOURCE_VAL            =:RESOURCE_VAL, ',
'			RESOURCE_ID2            =:RESOURCE_ID2, ',
'			RESOURCE_VAL2           =:RESOURCE_VAL2, ',
'			DPOSTED                 =:DPOSTED, ',
'			TRGT_GWP                =:TRGT_GWP, ',
'			CMT_QTY                 =:CMT_QTY, ',
'			CMT_JOBRATE             =:CMT_JOBRATE, ',
'			LAST_UPDATE_DATE        =:LAST_UPDATE_DATE, ',
'			LAST_UPDATED_BY         =:LAST_UPDATED_BY, ',
'			CREATION_DATE           =:CREATION_DATE, ',
'			CREATED_BY              =:CREATED_BY, ',
'			OC_TYPE                 =:OC_TYPE, ',
'			MEN_POWER               =:MEN_POWER, ',
'			WORKER_TYPE             =:WORKER_TYPE, ',
'			SQ_NUM                  =:SQ_NUM, ',
'			PARENT_OPR_ID           =:PARENT_OPR_ID, ',
'			OC_ERP_CODE             =:OC_ERP_CODE, ',
'			COMPONENT_ID            =:COMPONENT_ID, ',
'			STANDARD_OPERATION_CODE =:STANDARD_OPERATION_CODE, ',
'			PROCESS_FLOW         =:PROCESS_FLOW, ',
'			HELPER_SMV           =:HELPER_SMV, ',
'			OPERAT_OBLINE_ID     =:OPERAT_OBLINE_ID, ',
'			EMB_NO_STITCH        =:EMB_NO_STITCH, ',
'			S_NO                 =:S_NO, ',
'			HEADER_ID            =:HEADER_ID, ',
'			OP_LINE_ID           =:OP_LINE_ID, ',
'			OB_LINES_ID          =:OB_LINES_ID, ',
'			GWP_GE_OBID          =:GWP_GE_OBID, ',
'			MINOR_OPERATIONS     =:MINOR_OPERATIONS, ',
'			MAJOR_OPERATIONS     =:MAJOR_OPERATIONS, ',
'			WATER                =:WATER, ',
'			TIME                 =:TIME, ',
'			SEQUENCE             =:SEQUENCE, ',
'			WASH_TYPE            =:WASH_TYPE, ',
'			SEQ                  =:SEQ,',
'			EIM_SCORE            =:EIM_SCORE,',
'			NONOPERATION_TIME    =:NONOPERATION_TIME',
'',
'      WHERE OP_LINE_ID = :OP_LINE_ID;',
'',
'    /* ========= DELETE ========= */',
'    WHEN ''D'' THEN',
'',
'      DELETE FROM PWC_MFG_ROUTING_PLAN_DET',
'      WHERE OP_LINE_ID = :OP_LINE_ID;',
'',
'  END CASE;',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    RAISE_APPLICATION_ERROR(-20010,',
'      ''IG Process Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>150869039535204443
);
end;
