'             ',
'			:S_NO, ',
'			:OP_LINE_ID, ',
'			:ITEM_CODE, ',
'			:PER_BATCH_QUANTITY, ',
'			:PER_BATCH_CONSUMPTION, ',
'			:TOTAL_CONSUMPTION, ',
'			:ON_HAND_QTY, ',
'			:EXCESS_SHORTAGE, ',
'			:Item_Description,',
'			:CREATION_DATE,',
'			:CREATED_BY,',
'			:LAST_UPDATED_BY,',
'			:LAST_UPDATE_DATE',
'			)',
'            RETURNING CHEMICAL_ID INTO :CHEMICAL_ID;',
'',
'     ',
'    /* ========= UPDATE ========= */',
'    WHEN ''U'' THEN',
'',
'      UPDATE PWC_MFG_CHEMICAL_DET',
'      SET ',
'			CHEMICAL_ID             =:CHEMICAL_ID, ',
'			S_NO                    =:S_NO, ',
'			OP_LINE_ID              =:OP_LINE_ID, ',
'			ITEM_CODE               =:ITEM_CODE, ',
'			PER_BATCH_QUANTITY      =:PER_BATCH_QUANTITY, ',
'			PER_BATCH_CONSUMPTION   =:PER_BATCH_CONSUMPTION, ',
'			TOTAL_CONSUMPTION       =:TOTAL_CONSUMPTION, ',
'			ON_HAND_QTY             =:ON_HAND_QTY, ',
'			EXCESS_SHORTAGE         =:EXCESS_SHORTAGE, ',
'			Item_Description        =:Item_Description,',
'			CREATION_DATE           =:CREATION_DATE,',
'			CREATED_BY              =:CREATED_BY,',
'			LAST_UPDATED_BY         =:LAST_UPDATED_BY,',
'			LAST_UPDATE_DATE        =:LAST_UPDATE_DATE',
'',
'',
'      WHERE CHEMICAL_ID = :CHEMICAL_ID;',
'',
'    /* ========= DELETE ========= */',
'    WHEN ''D'' THEN',
'',
'      DELETE FROM PWC_MFG_CHEMICAL_DET',
'      WHERE CHEMICAL_ID = :CHEMICAL_ID;',
'',
'  END CASE;',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    RAISE_APPLICATION_ERROR(-20010,',
'      ''IG Process Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>151167752291482813
);
