wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(152575362828080234)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_region_id=>wwv_flow_imp.id(148106205235980231)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch BPO Line'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'BEGIN',
'   IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'      FOR r IN (',
'      SELECT DISTINCT        ',
'       ooha.cust_po_number || ''/'' || oola.line_number stn,        ',
'       oola.ordered_item item_code,        ',
'       msib.description item_description,        ',
'       msib.inventory_item_id item_id,        ',
'       oola.ordered_quantity quantity,     ',
'       apps.pwc_poc_extra_quantity_func@adf(ooha.attribute4, oola.ordered_quantity )  EXTRA_QTY,     ',
'    ',
'                ( SELECT NVL (SUM (TOTAL_CUT_QTY), 0)      ',
'                 FROM PWC_MFG_CUTLYRCNTRL_H CH, PWC_MFG_CUTLYRCNTRL_L CL   ',
'                 WHERE     1 = 1   ',
'                 AND CH.HEADER_ID = CL.HEADER_ID   ',
'                 AND CH.TRACKING_NO = :p69_TRACKING_NO  ',
'                 AND CH.ORG_ID = :p69_ORG_ID   ',
'                 AND CL.BPO_NO = ooha.cust_po_number   ',
'                 AND CL.COLOR = :p69_COLOR ) current_plan_qty,   ',
'',
'       ooha.attribute12 replace_bpo        ',
'  FROM apps.oe_order_headers_all@adf ooha,        ',
'       apps.oe_order_lines_all@adf oola,        ',
'       apps.mtl_system_items_b@adf msib ',
'    --   PWC_ONT_WVN_MASTER_BOM_GENRC_D l        ',
' WHERE     ooha.header_id = oola.header_id        ',
'       AND msib.inventory_item_id = oola.ordered_item_id        ',
'       AND msib.organization_id = pwc_organization_name (''Inventory Master Org'')        ',
'       AND ooha.attribute4 = :P69_TRACKING_NO    ',
'       ',
'       AND REGEXP_SUBSTR (msib.description,        ',
'                          ''[^:]+'', 1, 3) = :P69_ORG_ID       ',
'       ',
'       AND REGEXP_SUBSTR (msib.description,        ',
'                          ''[^:]+'',1, 2) = :P69_COLOR        ',
'',
'       AND ooha.cust_po_number || ''/'' || oola.line_number IN        ',
'              (SELECT l.stn        ',
'                 FROM pwc_mfg_osp_header h, pwc_mfg_osp_stn_line l        ',
'                WHERE h.header_id = l.header_id AND h.tracking_no = nvl(:p69_TRACKING_NO,h.tracking_no))       ',
'       ',
'       AND NOT EXISTS        ',
'                  (SELECT *        ',
'                     FROM pwc_gwp_mfg_gevaluation h, pwc_gwp_mfg_ge_obsline l        ',
'                    WHERE     h.gwp_ge_id = l.gwp_ge_id        ',
'                          AND ooha.cust_po_number || ''/'' || oola.line_number =        ',
'                                 l.obs_no        ',
'                          AND h.tracking_no = :p69_tracking_no       ',
'                          AND h.color = :p69_color        ',
'                          AND h.wash = :p69_wash       ',
'                          AND h.org_id = :p69_org_id)                                     ',
'      ',
'      and exists (select ''X''     ',
'                    from pwc_mfg_osp_header osph,     ',
'                         pwc_mfg_osp_stn_line ospl,     ',
'                         pwc_mfg_osp_dep_assign ospd     ',
'                        where 1=1     ',
'                        and osph.header_id = ospl.header_id     ',
'                        and ospl.stn_line_id = ospd.stn_line_id      ',
'                        and osph.tracking_no = ooha.attribute4     ',
'                        and ospl.stn = ooha.cust_po_number || ''/'' || oola.line_number     ',
'                        and upper(ospd.FINAL_DEPARTMENT) like upper(''%Washing%'')     ',
'                        and nvl(ospd.SUB_UNIT, ''N'') <> ''Y''))',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'      LOOP',
'',
'         INSERT INTO PWC_GWP_MFG_GE_OBSLINE (',
'            GWP_GE_ID,',
'            GWP_GE_WASLINE_ID,',
'            GWP_GE_OBID,',
'            SALESORDER,',
'            SO_LINE,',
'            GWP_UNIT_ID,',
'            LAST_UPDATE_DATE,',
'            LAST_UPDATED_BY,',
'            CREATION_DATE,',
'            CREATED_BY,',
'            OBS_NO,',
'            QUANTITY,',
'            POST_STATUS,',
'            JOB_STATUS,',
'            WIP_ENTITY_ID,',
'            JOB_RELEASED_DATE,',
'            WASH_NAME,',
'            WASHING_UNIT_NAME,',
'            WASHING_START_DATE,',
'            STITCHING_UNIT,',
'            STITCHING_START_DATE,',
'            VIEW_SHIPMENT_DETAIL,',
'            TEM_CODE,',
'            SHIPMENT_QTY,',
'            SHIPMENT_DATE,',
'            COUNTRY_CHANGE,',
'            INVENTORY_ITEM_ID,',
'            RECIPE_NO,',
'            NUMBER_BATCHES,',
'            PER_BATCH_QUANTITY,',
'            COLOR,',
'            WASH,',
'            WORKABLE_QUANTITY,',
'            STITCHING_FINISH_DATE,',
'            PRODUCTION_PER_DAY,',
'            WASH_SENDING_STARTDATE,',
'            WASH_SENDING_FINISHDATE,',
'            NUMBER_STITCHINGLINES,',
'            WASHING_FINISH_DATE,',
'            FEBRIC_TYPE,',
'            PER_BATCH_WEIGHT,',
'            SHADE_BAND_SEND_DATE,',
'            SHADE_BAND_SUB_DATE,',
'            SHADE_BAND_APPRO_DATE,',
'            ITEM_ID,',
'            JOB_NAME,',
'            JOB_QTY,',
'            JOB_ID,',
'            CURRENT_PLAN_QTY,',
'            JOB_CREATED,',
'            OB_POSTED,',
'            COMPLETION_POSTED,',
'            ERROR_MESSAGE,',
'            BALANCE_QTY,',
'            WASHING_END_DATE,',
'            REMARKS,',
'            EXTRA_QUANTITY',
'         )',
'    ',
'    VALUES (',
'    ',
'    NVL(:P69_GWP_GE_ID, NULL),',
'    NVL(:GWP_GE_WASLINE_ID, NULL),',
'    NVL(:GWP_GE_OBID, NULL),',
'    NVL(:order_number, NULL),',
'    NVL(:line_id, NULL),',
'    NVL(:GWP_UNIT_ID, NULL),',
'    SYSDATE,',
'    723155,',
'    SYSDATE,',
'    723155,',
'    NVL(r.stn, NULL),',
'    NVL(:shipped_quantity, 0),',
'    NVL(:POST_STATUS, NULL),',
'    NVL(:JOB_STATUS, NULL),',
'    NVL(:WIP_ENTITY_ID, NULL),',
'    NVL(:JOB_RELEASED_DATE, NULL),',
'    NVL(:WASH_NAME, NULL),',
'    NVL(:WASHING_UNIT_NAME, NULL),',
'    NVL(:WASHING_START_DATE, NULL),',
'    NVL(:STITCHING_UNIT, NULL),',
'    NVL(:STITCHING_START_DATE, NULL),',
'    NVL(:VIEW_SHIPMENT_DETAIL, NULL),',
'    NVL(:TEM_CODE, NULL),',
'    NVL(:shipped_quantity, 0),',
'    NVL(:schedule_ship_date, NULL),',
'    :country_change,',
'    NVL(r.item_id, NULL),',
'    NVL(:RECIPE_NO, NULL),',
'    NVL(:NUMBER_BATCHES, 0),',
'    NVL(:PER_BATCH_QUANTITY, 0),',
'    NVL(:COLOR, NULL),',
'    NVL(:WASH, NULL),',
'    NVL(:WORKABLE_QUANTITY, 0),',
'    NVL(:STITCHING_FINISH_DATE, NULL),',
'    NVL(:PRODUCTION_PER_DAY, 0),',
'    NVL(:WASH_SENDING_STARTDATE, NULL),',
'    NVL(:WASH_SENDING_FINISHDATE, NULL),',
'    NVL(:NUMBER_STITCHINGLINES, 0),',
'    NVL(:WASHING_FINISH_DATE, NULL),',
'    NVL(:FEBRIC_TYPE, NULL),',
'    NVL(:PER_BATCH_WEIGHT, 0),',
'    NVL(:SHADE_BAND_SEND_DATE, NULL),',
'    NVL(:SHADE_BAND_SUB_DATE, NULL),',
'    NVL(:SHADE_BAND_APPRO_DATE, NULL),',
'    NVL(r.item_id, NULL),',
'    NVL(:JOB_NAME, NULL),',
'    NVL(:JOB_QTY, 0),',
'    NVL(:JOB_ID, NULL),',
'    NVL(r.current_plan_qty, 0),',
'    NVL(:JOB_CREATED, NULL),',
'    NVL(:OB_POSTED, NULL),',
'    NVL(:COMPLETION_POSTED, NULL),',
'    NVL(:ERROR_MESSAGE, NULL),',
'    NVL(:BALANCE_QTY, 0),',
'    NVL(:WASHING_END_DATE, NULL),',
'    NVL(:REMARKS, NULL),',
'    NVL(r.extra_qty, 0)',
'    );',
'    END LOOP;',
'',
'   ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'      UPDATE PWC_GWP_MFG_GE_OBSLINE',
'         SET SALESORDER        = :SALESORDER,',
'             SO_LINE           = :SO_LINE,',
'             OBS_NO            = :OBS_NO,',
'             QUANTITY          = :QUANTITY,',
'             SHIPMENT_QTY      = :SHIPMENT_QTY,',
'             SHIPMENT_DATE     = :SHIPMENT_DATE,',
'             COUNTRY_CHANGE    = :COUNTRY_CHANGE,',
'             INVENTORY_ITEM_ID = :INVENTORY_ITEM_ID,',
'             CURRENT_PLAN_QTY  = :CURRENT_PLAN_QTY,',
'             EXTRA_QUANTITY    = :EXTRA_QUANTITY,',
'             LAST_UPDATED_BY   = 723155,',
'             LAST_UPDATE_DATE  = SYSDATE',
'       WHERE GWP_GE_WASLINE_ID = :GWP_GE_WASLINE_ID;',
'',
'   ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'      DELETE FROM PWC_GWP_MFG_GE_OBSLINE',
'       WHERE GWP_GE_WASLINE_ID = :GWP_GE_WASLINE_ID;',
'',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      DBMS_OUTPUT.PUT_LINE(''ERROR: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(151170322347482839)
,p_internal_uid=>152575362828080234
);
end;
/
