wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(378221646371389006)
,p_plug_name=>'Packing List Detail'
,p_region_name=>'PLD_IG'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PLD.PACKING_DETAIL_ID,',
'       PLD.PACKING_LIST_ID,',
'       PLD.PACK_TYPE,',
'       PLD.CARTON_QUANTITY,',
'       PLD.CARTON_TYPE,',
'       PLD.COMBO_NORMAL,',
'       PLD.BPO_LINE_NO,',
'       PLD.DCPO,',
'       PLD.COUNTRY,',
'       PLD.WASH_DETAIL,',
'       PLD.COLOR_DETAIL,',
'       PLD.WASH_NAME,',
'       PLD.ORDER_QUANTITY,',
'       PLD.INSEAM,',
'       PLD.SIZE_NO,',
'       PLD.RAITO_QTY,',
'       PLD.PRE_PACK_CTN,',
'       PLD.PACK_QTY,',
'       PLD.LAST_UPDATE_DATE,',
'       PLD.LAST_UPDATED_BY,',
'       PLD.CREATION_DATE,',
'       PLD.CREATED_BY,',
'       PLD.SERIAL_NO,',
'       PLD.INVENTORY_ITEM_ID,',
'       PLD.CHILD_STYLE_NUMBER,',
'       PLD.available_to_pack_qty,',
'       /*(',
'           SELECT             LISTAGG(STYLE_NO,'','')                          WITHIN GROUP (ORDER BY STYLE_NO)         FROM(SELECT xxpwc.pwc_master_tracking_data_func (bpo.tracking_no, ''STYLE_NO'') STYLE_NO    FROM pwc_exp_packing_list_bpo bpo   WHERE '
||'    bpo.packing_list_id = PLD.packing_list_id         AND bpo.CUST_PO_NO =                LTRIM (                   RTRIM (                      REGEXP_SUBSTR (PLD.BPO_LINE_NO,                                     ''[^/]+'',                             '
||'        1,                                     1)))         AND PLD.BPO_LINE_NO IS NOT NULL         AND bpo.country_code = PLD.country)) By Aamir Majeed to remove 11g error*/',
'       (SELECT LISTAGG (',
'                  pwc_master_tracking_data_func (bpo.tracking_no, ''STYLE_NO''),',
'                  '','')',
'               WITHIN GROUP (ORDER BY',
'                                pwc_master_tracking_data_func (',
'                                   bpo.tracking_no,',
'                                   ''STYLE_NO''))',
'                  STYLE_NO',
'          FROM pwc_exp_packing_list_bpo bpo',
'         WHERE     bpo.packing_list_id = PLD.packing_list_id',
'               AND bpo.CUST_PO_NO =',
'                      LTRIM (RTRIM (REGEXP_SUBSTR (PLD.BPO_LINE_NO,',
'                                                   ''[^/]+'',',
'                                                   1,',
'                                                   1)))',
'               AND PLD.BPO_LINE_NO IS NOT NULL',
'               AND bpo.country_code = PLD.country)',
'          AS Style_Number,',
'       PLD.LEFTOVER_REGULAR_QTY,',
'       PLD.BII_PROMO,',
'       PLD.BII_C,',
'       PLD.BII_D',
'  FROM PWC_EXP_PACKING_LIST_DETAIL PLD',
'  where PLD.PACKING_LIST_ID = :P71_PACKING_LIST_ID;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P71_PACKING_LIST_ID'
