,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct ftt.TERRITORY_SHORT_NAME ',
'  FROM apps.hz_parties@adf             hp, ',
'       apps.hz_party_sites@adf         hps, ',
'       apps.hz_locations@adf           hl, ',
'       apps.hz_cust_accounts_all@adf   hca, ',
'       apps.hz_cust_acct_sites_all@adf hcsa, ',
'       apps.hz_cust_site_uses_all@adf  hcsu, ',
'       apps.fnd_territories_tl@adf     ftt, ',
'       apps.fnd_territories@adf        ft ',
' WHERE hp.party_id = hps.party_id ',
'   AND hps.location_id = hl.location_id ',
'   AND hp.party_id = hca.party_id ',
'   AND hcsa.party_site_id = hps.party_site_id ',
'   AND hcsu.cust_acct_site_id = hcsa.cust_acct_site_id ',
'   AND hca.cust_account_id = hcsa.cust_account_id ',
'   and hcsu.site_use_code = ''SHIP_TO'' ',
'   and hps.status = ''A'' ',
'   and ftt.territory_code = hl.country ',
'   and ft.territory_code = ftt.territory_code  ',
'   AND ft.obsolete_flag = ''N'''))
,p_lov_display_null=>'YES'
,p_cSize=>30
