wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(151041703996370721)
,p_name=>'P71_BPO'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(377843145050538813)
,p_item_source_plug_id=>wwv_flow_imp.id(377843145050538813)
,p_prompt=>'BPO'
,p_source=>'BPO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'PACKING_LIST_H_BPO_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       OH.CUST_PO_NUMBER BPO_NO,',
'       OH.CUST_PO_NUMBER REPLACE_BPO,',
'       POC.TRACKING_NO,',
'       POC.BRAND_NAME BUYER_NAME,',
'       POC.BUYER_AGENT_NAME,',
'       POC.COSTING_UOM,',
'       SL.STYLE_NAME,',
'       SL.STYLE_NUMBER,',
'       SD.SEASON_NAME || ''.'' || SD.SEASON_YEAR SEASON,',
'       OH.ATTRIBUTE9 PO_TYPE,',
'       (SELECT RTRIM (',
'                  REGEXP_REPLACE (',
'                     LISTAGG (L.FABRIC_CONSTRUCTION, '':: '')',
'                        WITHIN GROUP (ORDER BY L.FABRIC_CONSTRUCTION),',
'                     ''([^::]*)(::\1)+($|::)'',',
'                     ''\1\3''),',
'                  ''::'')',
'          FROM PWC_ONT_WVN_PRECOSTING_L L,',
'               PWC_ONT_WVN_PRECOSTING_H H,',
'               PWC_ONT_WVN_PRECOSTING_COLOR_L D',
'         WHERE     L.HEADER_ID = H.HEADER_ID',
'               AND L.LINE_ID = D.LINE_ID',
'               AND D.BPO_TBA_NO = OH.CUST_PO_NUMBER',
'               AND H.TRACKING_NO = POC.TRACKING_NO)',
'          FABRIC_DESC,',
'       oh.attribute10 inco_term,',
'       OH.ORG_ID,',
'       HOU.NAME factory_name,',
'       POC.FIT,',
'       POC.FIRST_DELIVERY_DATE,',
'       SIZ_LINE.COUNTRY,',
'       SIZ_LINE.INDC_DATE,',
'       SIZ_LINE.BUYER_WAREHOUSE_DATE,',
'       SIZ_LINE.DELIVERY_TERM,',
'       SIZ_LINE.SHIP_MODE,',
'       POC.CURRENCY_CODE,',
'       (SELECT character2 address4',
'          FROM apps.qa_results@adf qr, apps.qa_plans@adf qp',
'         WHERE     qp.plan_id = qr.plan_id',
'               AND qp.name = ''PWC_OM_COUNTRY_DCPO''',
'               AND qr.character1 = SIZ_LINE.COUNTRY',
'               AND ROWNUM <= 1)',
'          DCPO,',
'       poc.BUYER_ID',
'  FROM                                        --APPS.OE_ORDER_HEADERS_ALL OOH,',
'      PWC_ONT_WVN_PRECOSTING_H POC,',
'       APPS.HR_ORGANIZATION_UNITS@adf HOU,',
'       PWC_MT_BUYER_DETAILS_H BH,',
'       PWC_MT_BRAND_DETAILS_D BD,',
'       PWC_MT_STYLE_DETAILS_L SL,',
'       PWC_MT_SEASON_DETAILS_D SD,',
'       APPS.AR_CUSTOMERS@adf AC,',
'       apps.OE_ORDER_HEADERS_ALL@adf OH,',
'       apps.OE_ORDER_LINES_ALL@adf OL,',
'       apps.MTL_SYSTEM_ITEMS@adf MSI,',
'       apps.ORG_ORGANIZATION_DEFINITIONS@adf OOD,',
'       --PWC_ONT_WVN_PRECOSTING_H OOH,',
'       --AR_CUSTOMERS AC,',
'       PWC_ONT_WVN_SIZEWISE_DETAILS_H SIZ_LINE',
' WHERE                                                                   --1st',
'      OH   .ATTRIBUTE3 != ''TBA''',
'       AND OH.ATTRIBUTE4 = POC.TRACKING_NO',
'       AND OH.FLOW_STATUS_CODE <> ''CANCELLED''',
'       AND HOU.ORGANIZATION_ID = OH.ORG_ID',
'       AND BH.HEADER_ID = BD.HEADER_ID',
'       AND BD.BRAND_LINE_ID = SL.BRAND_LINE_ID',
'       AND SL.STYLE_LINE_ID = SD.STYLE_LINE_ID',
'       AND SD.SEASON_IDENTIFIER IS NOT NULL',
'       AND SD.TRACKING_NO IS NOT NULL',
'       AND AC.CUSTOMER_ID = BH.BUYER_ID',
'       AND SD.TRACKING_NO = POC.TRACKING_NO',
'       ---2nd',
'       AND OL.INVENTORY_ITEM_ID = MSI.INVENTORY_ITEM_ID',
'       AND OH.HEADER_ID = OL.HEADER_ID',
'       AND OOD.ORGANIZATION_ID = MSI.ORGANIZATION_ID',
'       AND OOD.OPERATING_UNIT = OH.ORG_ID',
'       AND OH.FLOW_STATUS_CODE <> ''CANCELLED''',
'       AND NVL (OL.ATTRIBUTE6, ''Active'') = ''Active''',
'       AND OOD.ORGANIZATION_NAME <> ''Inventory Master Org''',
'       AND TO_CHAR (POC.HEADER_ID(+)) = OH.ATTRIBUTE20 --change only for prod for test it is ATTRIBUTE5 07-JAN-2023',
'       AND POC.TRACKING_NO = OH.ATTRIBUTE4',
'       AND NVL (SIZ_LINE.SHIPMENT_QTY, 0) > 0',
'       AND AC.CUSTOMER_ID = OH.SOLD_TO_ORG_ID',
'       AND OH.HEADER_ID = SIZ_LINE.SALES_ORDER_ID',
'       --AND poc.TRACKING_NO = ''OYK-2301-0001''            --remove this for prod',
'       AND OL.LINE_ID = SIZ_LINE.SALES_ORDER_LINE_ID',
'       AND OL.INVENTORY_ITEM_ID = SIZ_LINE.INVENTORY_ITEM_ID',
'       --  and APPS.pwc_pack_list_bpo_qty_check(OH.CUST_PO_NUMBER) > 0',
'       AND EXISTS',
'              (SELECT DISTINCT 1',
'                 FROM PWC_MFG_FINISH_PROD_L l',
'                WHERE l.tracking_no = POC.TRACKING_NO)',
'       AND 1 = 1'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_cMaxlength=>100
,p_read_only_when=>'P71_PACKING_LIST_ID'
,p_read_only_when_type=>'ITEM_IS_NOT_NULL'
,p_field_template=>wwv_flow_imp.id(220419589411811080)
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--indicatorAsterisk'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_08=>'1000'
,p_attribute_10=>'TRACKING_NO:P71_TRACKING_NO,REPLACE_BPO:P71_REPLACE_BPO,BUYER_NAME:P71_VC_BUYER,BUYER_AGENT_NAME:P71_BUYER_AGENT_NAME,COSTING_UOM:P71_PACKING_LIST_UOM,STYLE_NUMBER:P71_STYLE_NUMBER,STYLE_NAME:P71_STYLE_NAME,PO_TYPE:P71_PO_TYPE,FABRIC_DESC:P71_FABRIC_'
||'DESC,INCO_TERM:P71_INCO_TERMS,ORG_ID:P71_ORG_ID,FIRST_DELIVERY_DATE:P71_BPO_DELIVERY_DATE,COUNTRY:P71_COUNTRY_NAME,DELIVERY_TERM:P71_INCO_TERMS,SHIP_MODE:P71_SHIP_MODE,DCPO:P71_DCPO,BUYER_ID:P71_BUYER_ID'
);
end;
/
