wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(151033783976351788)
,p_event_id=>wwv_flow_imp.id(151033236238351785)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var igRegion = apex.region("PLD_IG");',
'var gridView = igRegion.call("getViews", "grid");',
'var model    = gridView.model;',
'// Get the selected records',
'var selected = gridView.getSelectedRecords();',
'',
'if (selected.length > 0) {',
'    var inventoryItemId = model.getValue(selected[0], "INVENTORY_ITEM_ID");',
'    var bpoLineNo = model.getValue(selected[0], "BPO_LINE_NO");',
'    var colorDetail = model.getValue(selected[0], "COLOR_DETAIL");',
'    var dcpo = model.getValue(selected[0], "DCPO");',
'',
'    $s("P71_TMP_INVENTORY_ITEM_ID", inventoryItemId);',
'    $s("P71_TMP_DCPO", dcpo);',
'    $s("P71_TMP_BPO_LINE_NO", bpoLineNo.d);',
'    $s("P71_TMP_COLOR_DETAIL", colorDetail);',
'}'))
);
