'var noOfPrePackCTN=($v("PRE_PACK_CTN") !=='''')? parseFloat($v("PRE_PACK_CTN")) : 0;',
'var ratioQty=($v("RAITO_QTY") !=='''')? parseFloat($v("RAITO_QTY")) : 0;',
'',
'var totalPackQty=0;',
'',
'if (!isNaN(noOfPrePackCTN) && !isNaN(ratioQty)){',
'    totalPackQty=noOfPrePackCTN*ratioQty;',
'}',
'',
'$s(''PACK_QTY'',totalPackQty);'))
);
