wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(151708698708094418)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(378221646371389006)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Packing List Detail - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        ',
'        WHEN ''C'' THEN',
'            INSERT INTO PWC_EXP_PACKING_LIST_DETAIL (',
'                PACKING_LIST_ID,',
'                PACK_TYPE,',
'                CARTON_QUANTITY,',
'                CARTON_TYPE,',
'                COMBO_NORMAL,',
'                BPO_LINE_NO,',
'                DCPO,',
'                COUNTRY,',
'                WASH_DETAIL,',
'                COLOR_DETAIL,',
'                WASH_NAME,',
'                ORDER_QUANTITY,',
'                INSEAM,',
'                SIZE_NO,',
'                RAITO_QTY,',
'                PRE_PACK_CTN,',
'                PACK_QTY,',
'                SERIAL_NO,',
'                INVENTORY_ITEM_ID,',
'                CHILD_STYLE_NUMBER,',
'                AVAILABLE_TO_PACK_QTY,',
'                LEFTOVER_REGULAR_QTY,',
'                BII_PROMO,',
'                BII_C,',
'                BII_D',
'      ',
'            )',
'            VALUES (',
'                :PACKING_LIST_ID,',
'                :PACK_TYPE,',
'                :CARTON_QUANTITY,',
'                :CARTON_TYPE,',
'                :COMBO_NORMAL,',
'                :BPO_LINE_NO,',
'                :DCPO,',
'                :COUNTRY,',
'                :WASH_DETAIL,',
'                :COLOR_DETAIL,',
'                :WASH_NAME,',
'                :ORDER_QUANTITY,',
'                :INSEAM,',
'                :SIZE_NO,',
'                :RAITO_QTY,',
'                :PRE_PACK_CTN,',
'                :PACK_QTY,',
'                :SERIAL_NO,',
'                :INVENTORY_ITEM_ID,',
'                :CHILD_STYLE_NUMBER,',
'                :AVAILABLE_TO_PACK_QTY,',
'                :LEFTOVER_REGULAR_QTY,',
'                :BII_PROMO,',
'                :BII_C,',
'                :BII_D',
'            )',
'            return PACKING_DETAIL_ID into :PACKING_DETAIL_ID;',
'',
'        WHEN ''U'' THEN',
'            UPDATE PWC_EXP_PACKING_LIST_DETAIL',
'               SET PACK_TYPE              = :PACK_TYPE,',
'                   CARTON_QUANTITY       = :CARTON_QUANTITY,',
'                   CARTON_TYPE           = :CARTON_TYPE,',
'                   COMBO_NORMAL          = :COMBO_NORMAL,',
'                   BPO_LINE_NO           = :BPO_LINE_NO,',
'                   DCPO                  = :DCPO,',
'                   COUNTRY               = :COUNTRY,',
'                   WASH_DETAIL           = :WASH_DETAIL,',
'                   COLOR_DETAIL          = :COLOR_DETAIL,',
'                   WASH_NAME             = :WASH_NAME,',
'                   ORDER_QUANTITY        = :ORDER_QUANTITY,',
'                   INSEAM                = :INSEAM,',
'                   SIZE_NO               = :SIZE_NO,',
'                   RAITO_QTY             = :RAITO_QTY,',
'                   PRE_PACK_CTN          = :PRE_PACK_CTN,',
'                   PACK_QTY              = :PACK_QTY,',
'                   SERIAL_NO             = :SERIAL_NO,',
'                   INVENTORY_ITEM_ID     = :INVENTORY_ITEM_ID,',
'                   CHILD_STYLE_NUMBER    = :CHILD_STYLE_NUMBER,',
'                   AVAILABLE_TO_PACK_QTY = :AVAILABLE_TO_PACK_QTY,',
'                   LEFTOVER_REGULAR_QTY  = :LEFTOVER_REGULAR_QTY,',
'                   BII_PROMO             = :BII_PROMO,',
'                   BII_C                 = :BII_C,',
'                   BII_D                 = :BII_D',
'             WHERE PACKING_DETAIL_ID = :PACKING_DETAIL_ID;',
'',
'        WHEN ''D'' THEN',
'            DELETE FROM PWC_EXP_PACKING_LIST_DETAIL',
'             WHERE PACKING_DETAIL_ID = :PACKING_DETAIL_ID;',
'',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>151708698708094418
);
