wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(152140887281814448)
,p_plug_name=>'Production'
,p_region_template_options=>'#DEFAULT#:t-Region--accent14:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * FROM PWC_MFG_CUTLYRCNTRL_L tb1    ',
'where tb1.header_id=:P73_HEADER_ID   ',
'',
'',
'-- SELECT tb1.HEADER_ID,                                           ',
'--        tb1.LINE_ID,                                           ',
'--        tb1.CUT_NO,                                           ',
'--        tb1.MARKER_ID,                                           ',
'--        tb1.START_TIME,                                           ',
'--        tb1.END_TIME,                 ',
'--       /* (select DISTINCT ''Y'' from      ',
'--        PWC_MFG_CUTLYRCNTRL_L ctrl , PWC_MFG_CUTLYRCNTRL_d ctrd     ',
'--        where tb1.LINE_ID = ctrd.line_id) END_DATE_FLAG,         */                   ',
'--        tb1.MIN_END_BIT,                                           ',
'--        tb1.MIN_BUN_QTY,                                           ',
'--        tb1.MAX_BUN_QTY,                                          ',
'--        tb1.Time_Cal,                                          ',
'--        tb1.Actual_Consumption,                                          ',
'--        tb1.CREATED_BY,                                          ',
'--        tb1.CREATION_DATE,                                          ',
'--        tb1.LAST_UPDATE_DATE,                                          ',
'--        tb1.LAST_UPDATED_BY,                                          ',
'--        tb1.BPO_NO,                                          ',
'--        tb1.PRODUCTION_STAGE,                                          ',
'--        tb1.COUNTRY,                                          ',
'--        tb1.INTEGRATION_LAY_NUMBER,                                          ',
'--        tb1.INTEGRATION_ORDER_NUMBER,                                          ',
'--        tb1.NUMBERING_PRODUCTION,                                          ',
'--        tb1.INTEGRATION_CUT_NUMBER,                                          ',
'--        tb1.NUMBERING_COMPLETION_DATE,                                          ',
'--        tb1.REJECTED_PCS,                                          ',
'--        tb1.MOVE_ORDER_NUMBER,                                          ',
'--        tb1.PATTERN_COUNTRY,                                          ',
'--        tb1.TOTAL_CUT_QTY,                                          ',
'--        (SELECT DISTINCT ooha.attribute12                                          ',
'--         FROM apps.oe_order_headers_all@adf ooha,apps.oe_order_lines_all@adf oola,apps.mtl_system_items@adf msi                                          ',
'--            WHERE     ooha.attribute12 IS NOT NULL                                          ',
'--                  AND ooha.header_id = oola.header_id                                          ',
'--                  AND msi.inventory_item_id = oola.inventory_item_id                                          ',
'--                  AND msi.organization_id = ooha.org_id                                          ',
'--                  AND REGEXP_SUBSTR (msi.description,                                          ',
'--                                     ''[^:]+'',                                          ',
'--                                     1,                                          ',
'--                                     3) =                                          ',
'--                         REGEXP_SUBSTR (                                          ',
'--                            tb1.INTEGRATION_ORDER_NUMBER,                                          ',
'--                            ''[^$]+'',                                          ',
'--                            1,                                          ',
'--                            3)                                          ',
'--                  AND ooha.attribute4 =                                          ',
'--                         (SELECT h.tracking_no                                          ',
'--                            FROM pwc_mfg_cutlyrcntrl_h h                                          ',
'--                           WHERE h.header_id = tb1.HEADER_ID)                                          ',
'--                  AND ooha.cust_po_number = tb1.BPO_NO)                                          ',
'--             replace_bpo,                                          ',
'--        (SELECT DISTINCT ''Move Transaction is in error Please Check Pending Move Transaction Form''                                          ',
'--             FROM apps.wip_txn_interface_errors@adf wtie, apps.wip_move_txn_interface@adf wmti                                          ',
'--            WHERE     wmti.transaction_id = wtie.transaction_id                                          ',
'--                  AND wmti.process_status = 3                                          ',
'--                  AND wmti.attribute14 = tb1.LINE_ID                                          ',
'--                  AND wmti.attribute13 = ''AUTO MOVE TXN CUT'')                                          ',
'--             move_txn_error,                                          ',
'--             tb1.SIDE_WAIST,                                        ',
'--             tb1.Pattern_Master ,                                      ',
'--             tb1.stn_no,                                     ',
'--             tb1.COLOR,                                    ',
'--             tb1.INSEAM,                                  ',
'--             tb1.PROCESS_FLAG ,                                 ',
'--             tb1.cut_no_shade,             ',
'--             tb1.PROCESS_ERROR_DESC ,        ',
'--             tb1.IE_POST ,        ',
'--            /* (SELECT CASE WHEN COUNT (0) <> 0 THEN                            ',
'--                             ''Y''                            ',
'--                             ELSE ''N''                            ',
'--                             END                           ',
'--                   FROM mtl_material_transactions a                           ',
'--                  WHERE a.attribute12 = ''Auto Completion''                            ',
'--                  AND a.attribute11 = tb1.CUT_NO) */                     ',
'--                  null comp_status,                    ',
'--             nvl(tb1.material_issuance_flag, ''N'') line_del_check                   ',
'--                     ,       ',
'--             --nvl(tb1.ie_post, ''N'') ie_check   ',
'--             CASE  ',
'--         WHEN PROCESS_ERROR_DESC IS NULL OR TRIM(PROCESS_ERROR_DESC) = '''' THEN ''''  ',
'--         ELSE ''Y''  ',
'--     END AS IE_CHECK,      ',
'--             nvl((select distinct ''Y''                   ',
'--                     from PWC_MFG_CUTLYRCNTRL_D d                  ',
'--                     where d.line_id = tb1.LINE_ID                  ',
'--                     union                  ',
'--                 select distinct ''Y''                   ',
'--                     from PWC_MFG_CUTLYRCNTRL_BND_L l                  ',
'--                     where l.line_id = tb1.LINE_ID                ',
'--                     ), ''N'') line_upd_check  ,              ',
'--             (SELECT DISTINCT INTEGRATION_LAY_NUMBER              ',
'--                    FROM pwc_mfg_ratioplan_plycfline              ',
'--                   WHERE cut_no = tb1.CUT_NO)  LAY_NUMBER,          ',
'--             /*************Total Production************/          ',
'--             (SELECT NVL (SUM (rml.totalpcs), 0)          ',
'--                FROM pwc_mfg_ratioplan rm,          ',
'--                     pwc_mfg_ratioplan_plyline rml,          ',
'--                     pwc_mfg_cutlyrcntrl_h h          ',
'--               WHERE     rm.ratioplan_id = rml.ratioplan_id          ',
'--                     AND rm.tracking_no = h.tracking_no          ',
'--                     AND rml.fg_color = tb1.color          ',
'--                     AND h.tracking_no = rm.tracking_no          ',
'--                     AND h.header_id = tb1.header_id)  total_order_qty   ,          ',
'--             /*************Color Wise Production*********/          ',
'--             (SELECT NVL (SUM (L.TOTAL_CUT_QTY), 0)          ',
'--                   FROM  PWC_MFG_CUTLYRCNTRL_L L          ',
'--                  WHERE   1=1          ',
'--                        AND L.COLOR = tb1.color          ',
'--                        AND L.HEADER_ID = tb1.header_id) color_wise_production  ,          ',
'--             /********************WIP Balance************/          ',
'--              (SELECT NVL (SUM (rml.totalpcs), 0)          ',
'--                FROM pwc_mfg_ratioplan rm,          ',
'--                     pwc_mfg_ratioplan_plyline rml,          ',
'--                     pwc_mfg_cutlyrcntrl_h h          ',
'--               WHERE     rm.ratioplan_id = rml.ratioplan_id          ',
'--                     AND rm.tracking_no = h.tracking_no          ',
'--                     AND rml.fg_color = tb1.color          ',
'--                     AND h.tracking_no = rm.tracking_no          ',
'--                     AND h.header_id = tb1.header_id)-          ',
'                              ',
'--                     (SELECT NVL (SUM (L.TOTAL_CUT_QTY), 0)          ',
'--                           FROM  PWC_MFG_CUTLYRCNTRL_L L          ',
'--                          WHERE   1=1          ',
'--                                AND L.COLOR = tb1.color          ',
'--                                AND L.HEADER_ID = tb1.header_id) wip_balance ,         ',
'--      tb1.completion_interfaced, ',
'--      tb1.INVENTORY_ITEM_ID ',
'-- FROM PWC_MFG_CUTLYRCNTRL_L tb1    ',
'-- where tb1.header_id=:P73_HEADER_ID                                      ',
'-- --ORDER BY tb1.LINE_ID ASC                  ',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
