,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'                    SELECT PwcMfgCutlyrcntrlH.HEADER_ID,           ',
'       PwcMfgCutlyrcntrlH.HEADER_NO,           ',
'       PwcMfgCutlyrcntrlH.TABLE_NO,           ',
'       PwcMfgCutlyrcntrlH.DOC_DATE,           ',
'       PwcMfgCutlyrcntrlH.ADD_LAY_LENGTH,           ',
'       PwcMfgCutlyrcntrlH.R_PLAN_NO,           ',
'       PwcMfgCutlyrcntrlH.CREATION_DATE,           ',
'       PwcMfgCutlyrcntrlH.CREATED_BY,           ',
'       PwcMfgCutlyrcntrlH.LAST_UPDATED_BY,           ',
'       PwcMfgCutlyrcntrlH.ORG_ID,           ',
'       PwcMfgCutlyrcntrlH.LAST_UPDATED_DATE,           ',
'       PwcMfgCutlyrcntrlH.USERID,           ',
'       PwcMfgCutlyrcntrlH.RESPID,           ',
'       PwcMfgCutlyrcntrlH.RESPAPPLID,           ',
'       PwcMfgCutlyrcntrlH.TRACKING_NO,           ',
'       PwcMfgCutlyrcntrlH.FABRIC_TYPE,           ',
'       pwc_master_tracking_data_func (PwcMfgCutlyrcntrlH.TRACKING_NO,           ',
'                                            ''BUYER_NAME'')           ',
'          BUYER_NAME,           ',
'       pwc_master_tracking_data_func (PwcMfgCutlyrcntrlH.TRACKING_NO,           ',
'                                            ''BUYER_ID'')           ',
'          BUYER_ID,           ',
'       pwc_master_tracking_data_func (PwcMfgCutlyrcntrlH.TRACKING_NO,           ',
'                                            ''STYLE_NAME'')           ',
'          STYLE,           ',
'       pwc_master_tracking_data_func (PwcMfgCutlyrcntrlH.TRACKING_NO,           ',
'                                            ''STYLE_NO'')           ',
'          STYLE_NO,           ',
'       pwc_master_tracking_data_func (PwcMfgCutlyrcntrlH.TRACKING_NO,           ',
'                                            ''SEASON_NAME'')           ',
'          SEASON,           ',
'           ',
'                    ',
'       (SELECT LISTAGG (marker_id, '','') WITHIN GROUP (ORDER BY marker_id)           ',
'          FROM pwc_mfg_cutlyrcntrl_l mcl           ',
'         WHERE PwcMfgCutlyrcntrlH.HEADER_ID = mcl.header_id)           ',
'          MARKER_ID_LINE,           ',
'       PwcMfgCutlyrcntrlH.AVG_ACTUAL_CONSUMPTION,           ',
'       PwcMfgCutlyrcntrlH.CUTTING_MASTER,           ',
'       PwcMfgCutlyrcntrlH.SHIFT_CUTLYR,        ',
'  ',
'       PwcMfgCutlyrcntrlH.PS_CODE ,    ',
'       PwcMfgCutlyrcntrlH.HEADER_REMARKS    ',
'  FROM PWC_MFG_CUTLYRCNTRL_H@adf PwcMfgCutlyrcntrlH           ',
' ',
''))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
,p_ajax_items_to_submit=>'P73_HEADER_ID'
);
