 p_id=>wwv_flow_imp.id(155457600479253713)
,p_plug_name=>'Bundle Details'
,p_region_name=>'ig_bundle_details'
,p_parent_plug_id=>wwv_flow_imp.id(155457551245253712)
,p_region_template_options=>'#DEFAULT#:t-TabsRegion-mod--simple'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220353010735811010)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT PwcMfgCutlyrcntrlBndLEO.BUNDLE_NO,          ',
'       PwcMfgCutlyrcntrlBndLEO.DETAIL_ID,          ',
'       PwcMfgCutlyrcntrlBndLEO.FROM_PIECE_NO,          ',
'       PwcMfgCutlyrcntrlBndLEO.HEADER_ID,          ',
'       PwcMfgCutlyrcntrlBndLEO.LINE_ID,          ',
'       PwcMfgCutlyrcntrlBndLEO.SEQ_NO,          ',
'       PwcMfgCutlyrcntrlBndLEO.SHADE,          ',
'       PwcMfgCutlyrcntrlBndLEO.SIZE_VALUE,          ',
'       PwcMfgCutlyrcntrlBndLEO.SIZLINE_ID,          ',
'       PwcMfgCutlyrcntrlBndLEO.TO_PIECE_NO,         ',
'       PwcMfgCutlyrcntrlBndLEO.Remarks,         ',
'       PwcMfgCutlyrcntrlBndLEO.TOTAL_BUNDLE_QUANTITY,         ',
'       PwcMfgCutlyrcntrlBndLEO.CREATION_DATE,         ',
'       PwcMfgCutlyrcntrlBndLEO.CREATED_BY,         ',
'       PwcMfgCutlyrcntrlBndLEO.LAST_UPDATE_DATE,         ',
'       PwcMfgCutlyrcntrlBndLEO.LAST_UPDATED_BY,         ',
'       PwcMfgCutlyrcntrlBndLEO.TRACKING_NO,         ',
'       PwcMfgCutlyrcntrlBndLEO.NUMBERING_PROD,         ',
'       PwcMfgCutlyrcntrlBndLEO.COUNTRY,         ',
'       PwcMfgCutlyrcntrlBndLEO.SHRINKAGE_GROUP,         ',
'       PwcMfgCutlyrcntrlBndLEO.COLOR,         ',
'       PwcMfgCutlyrcntrlBndLEO.INSEAM,         ',
'       NVL((select DISTINCT ''Y''          ',
'                from PWC_MFG_CUTISSUANCE_LINE L,         ',
'                     PWC_MFG_CUTISSUANCE_SZLINE S,         ',
'                     PWC_MFG_CUTLYRCNTRL_L CL       ',
'                     --,PWC_MFG_CUTLYRCNTRL_BND_L CLD         ',
'                    where 1=1          ',
'                    --AND L.attribute1 = ''2022/49/1/1''          ',
'                    --and L.BPO_NO = ''PKLM-35124''         ',
'                    AND L.CUTISSUE_LINE_ID = S.CUTISSUE_LINE_ID         ',
'                    AND L.BPO_NO = CL.BPO_NO         ',
'                    AND L.attribute1 = CL.CUT_NO         ',
'                    --AND CL.LINE_ID = CLD.LINE_ID         ',
'                    --AND CLD.BUNDLE_NO = S.BANDEL_NO         ',
'                    AND S.BANDEL_NO = PwcMfgCutlyrcntrlBndLEO.BUNDLE_NO        ',
'                    and cl.line_id = PwcMfgCutlyrcntrlBndLEO.line_id       ',
'                    --and CLD.line_id = PwcMfgCutlyrcntrlBndLEO.line_id       ',
'                    ) , ''N'') bndl_del_check ,      ',
'                    decode(PwcMfgCutlyrcntrlBndLEO.is_barcode_generated, ''Y'', ''Yes'', ''No'' )is_barcode_generated  ,    ',
'                    PwcMfgCutlyrcntrlBndLEO.CUTTING_GROUP,    ',
'                    PwcMfgCutlyrcntrlBndLEO.RATIO_SERIAL ',
'FROM PWC_MFG_CUTLYRCNTRL_BND_L PwcMfgCutlyrcntrlBndLEO         ',
'/*ORDER BY TO_NUMBER (         ',
'            SUBSTR (PwcMfgCutlyrcntrlBndLEO.BUNDLE_NO,         ',
'                    INSTR (PwcMfgCutlyrcntrlBndLEO.BUNDLE_NO, ''-'') + 1)) ASC*/',
''))
