,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT   ',
'         mr.ratioplan_number,   ',
'        --  pwc_master_tracking_data_func (mr.tracking_no, ''BUYER_NAME'')   ',
'        --     customer_name,   ',
'        --  pwc_master_tracking_data_func (mr.tracking_no, ''STYLE_NAME'')   ',
'        --     style,   ',
'        --  pwc_master_tracking_data_func (mr.tracking_no, ''STYLE_NO'')   ',
'        --     style_no,   ',
'        --  d.season_name || ''.'' || d.season_year season,   ',
