'',
'if (!lineId) {',
'    apex.message.alert("LINE_ID not found!");',
'    return;',
'}',
'',
unistr('// \D83D\DC49 AJAX call'),
'apex.server.process("AJAX_CAL_PLIES", {',
'    x01: $v("P73_HEADER_ID"),',
