wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(153750671457200168)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Cut Layer Control'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   v_header_id NUMBER;',
'BEGIN',
'',
unistr('   -- \D83D\DD34 DELETE'),
'   IF :REQUEST = ''DELETE'' THEN',
'   ',
'      DELETE FROM PWC_MFG_CUTLYRCNTRL_H',
'       WHERE HEADER_ID = :P73_HEADER_ID;',
'',
'',
unistr('   -- \D83D\DFE2 INSERT'),
'   ELSIF :P73_HEADER_ID IS NULL THEN',
'',
unistr('      -- \D83D\DD11 Generate ID (tumhara logic)'),
'      SELECT NVL(MAX(HEADER_ID), 0) + 1',
'      INTO v_header_id',
'      FROM PWC_MFG_CUTLYRCNTRL_H;',
'',
'      :P73_HEADER_ID := v_header_id;',
'',
'      INSERT INTO PWC_MFG_CUTLYRCNTRL_H',
'      (',
'         HEADER_ID,',
'         HEADER_NO,',
'         TABLE_NO,',
'         DOC_DATE,',
'         ADD_LAY_LENGTH,',
'         R_PLAN_NO,',
'         CREATION_DATE,',
'         CREATED_BY,',
'         TRACKING_NO,',
'         FABRIC_TYPE,',
'         AVG_ACTUAL_CONSUMPTION,',
'         CUTTING_MASTER,',
'         SHIFT_CUTLYR,',
'         PS_CODE,',
'         HEADER_REMARKS',
'      )',
'      VALUES',
'      (',
'         :P73_HEADER_ID,',
'         :P73_HEADER_NO,',
'         :P73_TABLE_NO,',
'         :P73_DOC_DATE,',
'         :P73_ADD_LAY_LENGTH,',
'         :P73_R_PLAN_NO,',
'         SYSDATE,',
'         :0,--APP_USER,',
'         :P73_TRACKING_NO,',
'         :P73_FABRIC_TYPE,',
'         :P73_AVG_ACTUAL_CONSUMPTION,',
'         :P73_CUTTING_MASTER,',
'         :P73_SHIFT_CUTLYR,',
'         :P73_PS_CODE,',
'         :P73_HEADER_REMARKS',
'      );',
'',
'',
unistr('   -- \D83D\DD35 UPDATE'),
'   ELSE',
'',
'      UPDATE PWC_MFG_CUTLYRCNTRL_H',
'         SET HEADER_NO              = :P73_HEADER_NO,',
'             TABLE_NO               = :P73_TABLE_NO,',
'             DOC_DATE               = :P73_DOC_DATE,',
'             ADD_LAY_LENGTH         = :P73_ADD_LAY_LENGTH,',
'             R_PLAN_NO              = :P73_R_PLAN_NO,',
'             LAST_UPDATED_DATE      = SYSDATE,',
'             LAST_UPDATED_BY        = :0,--APP_USER,',
'             TRACKING_NO            = :P73_TRACKING_NO,',
'             FABRIC_TYPE            = :P73_FABRIC_TYPE,',
'             AVG_ACTUAL_CONSUMPTION = :P73_AVG_ACTUAL_CONSUMPTION,',
'             CUTTING_MASTER         = :P73_CUTTING_MASTER,',
'             SHIFT_CUTLYR           = :P73_SHIFT_CUTLYR,',
'             PS_CODE                = :P73_PS_CODE,',
'             HEADER_REMARKS         = :P73_HEADER_REMARKS',
'       WHERE HEADER_ID = :P73_HEADER_ID;',
'',
'   END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>153750671457200168
);
end;
