,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_line_id NUMBER;',
'    v_user_id NUMBER;',
'BEGIN',
'    v_line_id := apex_application.g_x02;',
'',
'    BEGIN',
'        SELECT user_id',
'        INTO v_user_id',
'        FROM APEX_230200.WWV_FLOW_USERS',
'        WHERE user_name = :APP_USER;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_user_id := NULL;',
'    END;',
'    ',
'',
'',
'     pwc_cutlayrcntrl_pkg.make_bundles(',
'        p_lineid   => v_line_id,',
'        p_user_id   => v_user_id',
'',
' );',
'',
'',
'    COMMIT;',
'',
'    htp.p(''{"status":"SUCCESS","message":"Copy successfully"}'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        htp.p(''{"status":"ERROR","message":"'' || SQLERRM || ''"}'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>158558055600475027
);
