wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(163748088417869936)
,p_plug_name=>'Fill Cut Numbers'
,p_region_name=>'FILL_CUT_NUMBER_IG'
,p_region_template_options=>'#DEFAULT#:t-Region--accent14:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>111
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT  ',
'       cfl.cut_no,                          ',
'       cfl.production_type,                          ',
'       l.marker_id,                          ',
'       pl.bpo_no,                          ',
'       ms.country,                          ',
'',
'       ROUND (',
'           (cfl.ACTUAL_METER)                 ',
'          / (SELECT SUM (sl.cutting_ratio)                          ',
'               FROM pwc_mfg_ratioplan_sizline@adf sl                          ',
'              WHERE     sl.ratioplan_id = mh.ratioplan_id                          ',
'                    AND sl.plyline_id = pl.plyline_id),                          ',
'          4) actual_consumption,                          ',
'',
'       NULL pattern_country,                          ',
'       ms.integration_order_number,                        ',
'       ms.stn_no,                     ',
'       pl.fg_color AS color,                   ',
'       pl.inseam,            ',
'       pl.cut_no AS ratio_plan_number,          ',
'       cfl.integration_lay_number AS lay_number,         ',
'       cfl.cut_no_shade,  ',
'       pl.inventory_item_id                  ',
'',
'FROM pwc_mfg_ratioplan@adf mh                          ',
'JOIN pwc_mfg_ratioplan_plyline@adf pl',
'     ON pl.ratioplan_id = mh.ratioplan_id                          ',
'JOIN pwc_mfg_ratioplan_plycfline@adf cfl',
'     ON pl.plyline_id = cfl.plyline_id                          ',
'JOIN pwc_mfg_ratioplan_merge_stns@adf ms',
'     ON ms.merge_stn_id = pl.merge_stn_id                          ',
'JOIN pwc_mfg_marker_info_l@adf l',
'     ON l.marker_plan_number = pl.cut_no            ',
'',
'WHERE mh.ratioplan_number = :P74_RATIO_PLAN                          ',
'  AND ms.bpo_no = pl.bpo_no               ',
'  AND ms.stn_no = ms.stn_no                   ',
'',
'  AND NOT EXISTS                          ',
'      (SELECT 1                          ',
'         FROM pwc_mfg_cutlyrcntrl_l mmr                          ',
'        WHERE mmr.cut_no = cfl.cut_no)       ',
'',
'GROUP BY ',
'       mh.tracking_no,',
'       mh.color,',
'       cfl.cut_no,         ',
'       pl.ratioplan_id,        ',
'       mh.ratioplan_number,                  ',
'       cfl.production_type,                          ',
'       l.marker_id,                          ',
'       pl.bpo_no,                          ',
'       ms.country,        ',
'       ms.integration_order_number,                        ',
'       ms.stn_no,                     ',
'       pl.fg_color,                   ',
'       pl.inseam,            ',
'       pl.cut_no,          ',
'       cfl.integration_lay_number,         ',
'       cfl.cut_no_shade,  ',
'       cfl.actual_meter,',
'       mh.ratioplan_id,',
'       pl.plyline_id,',
'       cfl.total_pcs,',
'       ',
'       pl.inventory_item_id       ',
'',
'',
'-- SELECT DISTINCT                          ',
'--        cfl.cut_no,                          ',
'--        cfl.production_type,                          ',
'--        l.marker_id,                          ',
'--        pl.bpo_no,                          ',
'--        ms.country,                          ',
'--        ROUND (                          ',
'--             --(mmst.actual_yds + (mmst.actual_inch / 36))                          ',
'--             -- (mmst.actual_yds)                  ',
'--            --(mmst.ACTUAL_METER)                        ',
'--            (cfl.ACTUAL_METER)                 ',
'--           / (SELECT SUM (sl.cutting_ratio)                          ',
'--                FROM pwc_mfg_ratioplan_sizline sl                          ',
'--               WHERE     sl.ratioplan_id = mh.ratioplan_id                          ',
'--                     AND sl.plyline_id = pl.plyline_id),                          ',
'--           4)                          ',
'--           actual_consumption,                          ',
'--        null                          ',
'--           pattern_country,                          ',
'--         ms.integration_order_number ,                        ',
'--         ms.stn_no ,                     ',
'--         --insert_bpo.color,  close for merge bpo           ',
'--         pl.fg_color color,                   ',
'--         pl.INSEAM    ,            ',
'--         pl.CUT_NO Ratio_plan_number,          ',
'--         cfl.INTEGRATION_LAY_NUMBER lay_number  ,         ',
'--         cfl.cut_no_shade,  ',
'--         pl.INVENTORY_ITEM_ID                  ',
'                       ',
'--   FROM pwc_mfg_ratioplan mh,                          ',
'--        pwc_mfg_ratioplan_plyline pl,                          ',
'--        pwc_mfg_ratioplan_plycfline cfl,                          ',
'--        pwc_mfg_ratioplan_merge_stns ms,                          ',
'--        --pwc_mfg_spreading_t_l mmst,                          ',
'--        --pwc_mfg_marher_info_h h,                          ',
'--        --pwc_mfg_marher_info_l l,                 ',
'--        PWC_MFG_MARKER_INFO_L l--,          ',
'                         ',
'--        --PWC_MFG_RATIOPLAN_STNS_ALL insert_bpo  close for merge bpo                          ',
'--  WHERE     pl.ratioplan_id = mh.ratioplan_id                          ',
'--        AND pl.plyline_id = cfl.plyline_id                          ',
'--        --AND mmst.cut_number = pl.cut_no                          ',
'--        AND ms.merge_stn_id = pl.merge_stn_id                          ',
'--        --AND h.header_id = l.header_id                          ',
'--        --AND l.brand = mh.ratioplan_number                          ',
'--        --AND mmst.attribute1 = cfl.cut_no                          ',
'--        AND l.marker_plan_number = pl.cut_no            ',
'--        and ms.BPO_NO =  pl.bpo_no --new for merge bpo              ',
'--        and ms.STN_NO = ms.stn_no --new  for merge bpo                  ',
'--        --and insert_bpo.BPO_NO =  pl.bpo_no close   for merge bpo                     ',
'--        --and insert_bpo.STN_NO = ms.stn_no close   for merge bpo                   ',
'--        AND mh.ratioplan_number =:P74_RATIO_PLAN                          ',
'--        AND NOT EXISTS                          ',
'--               (SELECT *                          ',
'--                  FROM pwc_mfg_cutlyrcntrl_l mmr                          ',
'--                 WHERE mmr.cut_no = cfl.cut_no)       ',
'--                  group by mh.tracking_no,mh.color, cfl.cut_no,         ',
'--                   pl.ratioplan_id,        ',
'--        mh.tracking_no,        ',
'--        mh.color,           ',
'--        mh.ratioplan_number,                  ',
'--        cfl.production_type,                          ',
'--        l.marker_id,                          ',
'--        pl.bpo_no,                          ',
'--        ms.country,        ',
'--        ms.integration_order_number ,                        ',
'--         ms.stn_no ,                     ',
'--         --insert_bpo.color,  close for merge bpo           ',
'--         pl.fg_color ,                   ',
'--         pl.INSEAM    ,            ',
'--         pl.CUT_NO ,          ',
'--         cfl.INTEGRATION_LAY_NUMBER   ,         ',
'--         cfl.cut_no_shade  ,  cfl.ACTUAL_METER, mh.ratioplan_id ,pl.plyline_id,CFL.TOTAL_PCS,CFL.CUT_NO,CFL.plyline_id,pl.INVENTORY_ITEM_ID  ',
'             '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P74_CUT_NUMBER'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Fill Cut Numbers'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
