,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
'',
'var region = apex.region("FILL_CUT_NUMBER_IG");',
'var grid = region.widget().interactiveGrid("getViews", "grid");',
'var model = grid.model;',
'',
'var selectedRecords = grid.getSelectedRecords();',
'',
unistr('var cutSet = new Set(); // \D83D\DD25 prevents duplicates automatically'),
'',
'selectedRecords.forEach(function (r) {',
'    var val = model.getValue(r, "CUT_NO"); // case-sensitive',
'    if (val) {',
'        cutSet.add(val);',
'    }',
'});',
'',
'var selectedCUTNOList = Array.from(cutSet).join(",");',
'',
'console.log("CUT NO LIST:", selectedCUTNOList);',
'',
'if (cutSet.size === 0) {',
'    apex.message.alert("Please select at least one row.");',
'    return;',
'}',
'',
'apex.server.process(',
'    "FILL_CUT_NUMBER_INSERT",',
'    {',
'        x01: selectedCUTNOList',
'    },',
'    {',
'        dataType: "text",',
'        success: function (data) {',
'            apex.message.showPageSuccess("Data inserted successfully.");',
'        },',
'        error: function (xhr, status, error) {',
'            apex.message.alert("AJAX Error: " + error);',
'        }',
'    }',
');'))
);
