wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(165516308807614010)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'FILL_CUT_NUMBER_INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_ids VARCHAR2(4000) := apex_application.g_x01;',
'',
'    CURSOR c_data IS',
'       SELECT DISTINCT ',
'       cfl.cut_no,                          ',
'       cfl.production_type,                          ',
'       l.marker_id,                          ',
'       pl.bpo_no,                          ',
'       ms.country,                          ',
'',
'       ROUND (',
'           (cfl.ACTUAL_METER)                 ',
'          / (SELECT SUM (sl.cutting_ratio)                          ',
'               FROM pwc_mfg_ratioplan_sizline@adf sl                          ',
'              WHERE sl.ratioplan_id = mh.ratioplan_id                          ',
'                AND sl.plyline_id = pl.plyline_id),                          ',
'          4) actual_consumption,                          ',
'',
'       ms.integration_order_number,                        ',
'       ms.stn_no,                     ',
'       pl.fg_color AS color,                   ',
'       pl.inseam,            ',
'       pl.cut_no AS ratio_plan_number,          ',
'       cfl.integration_lay_number AS lay_number,         ',
'       cfl.cut_no_shade,  ',
'       pl.inventory_item_id',
'',
unistr('       -- \2705 YAHAN ADD KIYA'),
'       --MIN_BUN_QTY,',
'      -- MAX_BUN_QTY                  ',
'',
'FROM pwc_mfg_ratioplan@adf mh                          ',
'JOIN pwc_mfg_ratioplan_plyline@adf pl',
'     ON pl.ratioplan_id = mh.ratioplan_id                          ',
'JOIN pwc_mfg_ratioplan_plycfline@adf cfl',
'     ON pl.plyline_id = cfl.plyline_id                          ',
'JOIN pwc_mfg_ratioplan_merge_stns@adf ms',
'     ON ms.merge_stn_id = pl.merge_stn_id                          ',
'JOIN pwc_mfg_marker_info_l@adf l',
'     ON l.marker_plan_number = pl.cut_no            ',
'',
'WHERE mh.ratioplan_number = :P74_RATIO_PLAN                          ',
'  AND ms.bpo_no = pl.bpo_no               ',
'',
'  AND NOT EXISTS                          ',
'      (SELECT 1                          ',
'         FROM pwc_mfg_cutlyrcntrl_l mmr                          ',
'        WHERE mmr.cut_no = cfl.cut_no)       ',
'',
'GROUP BY ',
'       cfl.cut_no,         ',
'       cfl.production_type,                          ',
'       l.marker_id,                          ',
'       pl.bpo_no,                          ',
'       ms.country,        ',
'       ms.integration_order_number,                        ',
'       ms.stn_no,                     ',
'       pl.fg_color,                   ',
'       pl.inseam,            ',
'       pl.cut_no,          ',
'       cfl.integration_lay_number,         ',
'       cfl.cut_no_shade,  ',
'       cfl.actual_meter,',
'       mh.ratioplan_id,',
'       pl.plyline_id,',
'       pl.inventory_item_id',
'       ',
'     -- MIN_BUN_QTY,',
'     -- MAX_BUN_QTY',
'    ;',
'',
'BEGIN',
'',
'    FOR rec IN c_data LOOP',
'        INSERT INTO PWC_MFG_CUTLYRCNTRL_L (',
'    HEADER_ID,',
'    CUT_NO,',
'    MARKER_ID,',
'    COUNTRY,',
'    BPO_NO,',
'    COLOR,',
'    INSEAM,',
'    INVENTORY_ITEM_ID,',
'    ACTUAL_CONSUMPTION,',
'    INTEGRATION_ORDER_NUMBER,',
'    STN_NO',
')',
'VALUES (',
'    :P74_HEADER_ID,',
'    rec.cut_no,',
'    rec.marker_id,',
'    rec.country,',
'    rec.bpo_no,',
'    rec.color,',
'    rec.inseam,',
'    rec.inventory_item_id,',
'    rec.actual_consumption,',
'    rec.integration_order_number,',
'    rec.stn_no',
');',
'    END LOOP;',
'',
'    COMMIT;',
'',
'END;',
'',
'',
'-- DECLARE',
'--     l_ids VARCHAR2(4000) := apex_application.g_x01;',
'',
'--     CURSOR c_data IS',
'--        SELECT DISTINCT                          ',
'--        cfl.cut_no,                          ',
'--        cfl.production_type,                          ',
'--        l.marker_id,                          ',
'--        pl.bpo_no,                          ',
'--        ms.country,                          ',
'',
'--        ROUND (',
'--            (cfl.ACTUAL_METER)                 ',
'--           / (SELECT SUM (sl.cutting_ratio)                          ',
'--                FROM pwc_mfg_ratioplan_sizline@adf sl                          ',
'--               WHERE     sl.ratioplan_id = mh.ratioplan_id                          ',
'--                     AND sl.plyline_id = pl.plyline_id),                          ',
'--           4) actual_consumption,                          ',
'',
'--        NULL pattern_country,                          ',
'--        ms.integration_order_number,                        ',
'--        ms.stn_no,                     ',
'--        pl.fg_color AS color,                   ',
'--        pl.inseam,            ',
'--        pl.cut_no AS ratio_plan_number,          ',
'--        cfl.integration_lay_number AS lay_number,         ',
'--        cfl.cut_no_shade,  ',
'--        pl.inventory_item_id                  ',
'',
'-- FROM pwc_mfg_ratioplan@adf mh                          ',
'-- JOIN pwc_mfg_ratioplan_plyline@adf pl',
'--      ON pl.ratioplan_id = mh.ratioplan_id                          ',
'-- JOIN pwc_mfg_ratioplan_plycfline@adf cfl',
'--      ON pl.plyline_id = cfl.plyline_id                          ',
'-- JOIN pwc_mfg_ratioplan_merge_stns@adf ms',
'--      ON ms.merge_stn_id = pl.merge_stn_id                          ',
'-- JOIN pwc_mfg_marker_info_l@adf l',
'--      ON l.marker_plan_number = pl.cut_no            ',
'',
'-- WHERE mh.ratioplan_number = :P74_RATIO_PLAN                          ',
'--   AND ms.bpo_no = pl.bpo_no               ',
'--   AND ms.stn_no = ms.stn_no                   ',
'',
'--   AND NOT EXISTS                          ',
'--       (SELECT 1                          ',
'--          FROM pwc_mfg_cutlyrcntrl_l mmr                          ',
'--         WHERE mmr.cut_no = cfl.cut_no)       ',
'',
'-- GROUP BY ',
'--        mh.tracking_no,',
'--        mh.color,',
'--        cfl.cut_no,         ',
'--        pl.ratioplan_id,        ',
'--        mh.ratioplan_number,                  ',
'--        cfl.production_type,                          ',
'--        l.marker_id,                          ',
'--        pl.bpo_no,                          ',
'--        ms.country,        ',
'--        ms.integration_order_number,                        ',
'--        ms.stn_no,                     ',
'--        pl.fg_color,                   ',
'--        pl.inseam,            ',
'--        pl.cut_no,          ',
'--        cfl.integration_lay_number,         ',
'--        cfl.cut_no_shade,  ',
'--        cfl.actual_meter,',
'--        mh.ratioplan_id,',
'--        pl.plyline_id,',
'--        cfl.total_pcs,',
'--        pl.inventory_item_id  ;',
'    ',
'-- begin',
'',
'--         FOR rec IN c_data LOOP',
'--         INSERT INTO PWC_MFG_CUTLYRCNTRL_L (',
'--             HEADER_ID,',
'--             CUT_NO,',
'--             MARKER_ID,',
'--             COUNTRY,',
'--             BPO_NO,',
'--             COLOR,',
'--             INSEAM,',
'--             INVENTORY_ITEM_ID',
'--         )',
'--         VALUES (',
'--             :P74_HEADER_ID,',
'--             rec.cut_no,',
'--             rec.marker_id,',
'--             rec.country,',
'--             rec.bpo_no,',
'--             rec.color,',
'--             rec.inseam,',
'--             rec.inventory_item_id',
'--         );',
'',
'--     END LOOP;',
'',
'--     COMMIT;',
'',
'-- END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(155503519038284348)
,p_internal_uid=>165516308807614010
);
end;
/
