wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(155503620472284349)
,p_plug_name=>'Fill Rolls'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>21
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--FILL ROLLS',
'SELECT *',
'  FROM (SELECT NULL cut_no,',
'               roll_no,',
'               supplier_batch_no,',
'               supplier_pl_no,',
'               mark_weight,',
'               ( (mark_weight * 1550000) / (36 * actual_gsm * cut_width))',
'                  mark_length,',
'               mark_length2,',
'               shrink_prcnt,',
'               shrinkage_group_inches,',
'               cutable_shrinkahe cutable_shrinkage,',
'               shade,',
'               NULL lay,',
'               NULL lay_rem_qty,',
'               NULL fabric_contain,',
'               NULL cut_qty,',
'               NULL end_bit,',
'               NULL end_bit2,',
'               cut_width,',
'               tracking_no,',
'               supp_roll_no,',
'               shrink_pattern,',
'               skewing,',
'               actual_gsm,',
'               child_style_no,',
'               ALOC_YARD,',
'               ALOC_INCH,',
'               (ALOC_METER - PWC_GET_ROLL_USED_QTY (roll_no)) ALOC_METER',
'          FROM (SELECT NULL cut_no,',
'                       det.roll_no roll_no,',
'                       det.supplier_batch_no,',
'                       det.supplier_pl_no,',
'                       pwc_cutlayrcntrl_pkg.get_roll_weight (',
'                          line.tracking_no,',
'                          line.child_style_no,',
'                          line.color,',
'                          det.roll_no,',
'                          line.fabric_item_id,',
'                          :P75_ORG_ID)',
'                          mark_weight,',
'                       det.roll_length mark_length,',
'                       det.roll_length2 mark_length2,',
'                       det.shrink_prc_length || det.shrink_prc_width',
'                          shrink_prcnt,',
'                       (det.SHRINK_LENGTH || ''-'' || det.SHRINK_WIDTH)',
'                          shrinkage_group_inches,',
'                       (SELECT DISTINCT patl.cutable_shrinkahe',
'                          FROM pwc_mfg_fabins_ptrnaloc_l patl,',
'                               pwc_mfg_fabins_ptrnaloc_d patd',
'                         WHERE     patl.aloc_line_id = patd.aloc_line_id',
'                               AND patd.roll_no = det.roll_no)',
'                          cutable_shrinkahe,',
'                       shdl.shade shade,',
'                       NULL lay,',
'                       NULL lay_rem_qty,',
'                       NULL fabric_contain,',
'                       NULL cut_qty,',
'                       NULL end_bit,',
'                       NULL end_bit2,',
'                       det.cut_width,',
'                       line.tracking_no,',
'                       det.supp_roll_no,',
'                       (SELECT DISTINCT pl.shrink_pattern',
'                          FROM pwc_mfg_fabins_ptrnaloc_l pl,',
'                               pwc_mfg_fabins_ptrnaloc_d pld',
'                         WHERE     pl.prod_l_id = line.prod_l_id',
'                               AND pld.aloc_line_id = pl.aloc_line_id',
'                               AND pld.roll_no = sdd.roll_no)',
'                          shrink_pattern,',
'                       det.skewing,',
'                       (SELECT d.actual_gsm',
'                          FROM pwc_mfg_fabins_gsm_test_l l,',
'                               pwc_mfg_fabins_gsm_test_d d',
'                         WHERE     l.gsm_line_id = d.gsm_line_id',
'                               AND l.prod_l_id = line.prod_l_id',
'                               AND l.supplier_batch_no =',
'                                      det.supplier_batch_no',
'                               AND (CASE',
'                                       WHEN d.supplier_pl_no IS NULL',
'                                       THEN',
'                                          ''N/A''',
'                                       ELSE',
'                                          d.supplier_pl_no',
'                                    END) =',
'                                      (CASE',
'                                          WHEN det.supplier_pl_no IS NULL',
'                                          THEN',
'                                             ''N/A''',
'                                          ELSE',
'                                             det.supplier_pl_no',
'                                       END)',
'                               AND d.roll_no = det.roll_no)',
'                          actual_gsm,',
'                       line.child_style_no,',
'                       DET.ALOC_YARD,',
'                       DET.ALOC_INCH,',
'                       DET.ALOC_METER',
'                  FROM pwc_mfg_fabric_ins_test_l det,',
'                       pwc_mfg_fabins_prod_l line,',
'                       pwc_mfg_fabric_ins_test_shd_l shdl,',
'                       pwc_mfg_fabinstest_shd_ld sdd,',
'                       --   mtl_onhand_quantities moq,    BY AQIB INSTRUCTION ONHAND STOCK CONDITION CHANGED',
'',
'                       (SELECT RM.TRACKING_NO,',
'                               SIZES_OTHERS.BPO_NO,',
'                               --CUTS.CUT_NO,',
'                               LAY_PLAN.ROLL_NO',
'                          FROM PWC_MFG_RATIOPLAN RM,',
'                               PWC_MFG_RATIOPLAN_PLYLINE SIZES_OTHERS,',
'                               ---PWC_MFG_RATIOPLAN_PLYCFLINE CUTS,',
'                               PWC_MFG_MARKER_LAYPLAN_DET LAY_PLAN',
'                         WHERE     1 = 1',
'                               --AND RM.TRACKING_NO = ''RE012SG11092''',
'                               AND RM.RATIOPLAN_ID =',
'                                      SIZES_OTHERS.RATIOPLAN_ID',
'                               ---AND CUTS.RATIOPLAN_ID =  RM.RATIOPLAN_ID',
'                               --AND CUTS.PLYLINE_ID = SIZES_OTHERS.PLYLINE_ID',
'                               AND LAY_PLAN.RATIOPLAN_ID = RM.RATIOPLAN_ID',
'                               AND LAY_PLAN.PLYLINE_ID =',
'                                      SIZES_OTHERS.PLYLINE_ID--AND LAY_PLAN.PLYLINE_ID = CUTS.PLYLINE_ID',
'                                                             --AND LAY_PLAN.PLYCFLINE_ID = CUTS.PLYCFLINE_ID',
'                       ) MARKER_RATIO',
'                 WHERE     1 = 1',
'                       AND line.prod_l_id = det.prod_l_id',
'                       AND line.prod_l_id = shdl.prod_l_id',
'                       AND shdl.line_id = sdd.line_id',
'                       AND det.is_transferred = ''N''',
'                       AND line.tracking_no = :P75_TRACKING_NO',
'                       AND LINE.TRACKING_NO = MARKER_RATIO.TRACKING_NO',
'                       --and MARKER_RATIO.CUT_NO = :p_cut_number',
'                      /* AND (   :p_cut_number IS NULL',
'                            OR :p_cut_number IS NOT NULL)',
'                       AND (   :p_bpo_number IS NULL',
'                            OR :p_bpo_number IS NOT NULL)*/',
'                       AND det.roll_no = MARKER_RATIO.ROLL_NO',
'                       AND sdd.roll_no = det.roll_no',
'                       AND line_type = ''P''',
'                                   AND NOT EXISTS',
'                                  (SELECT *',
'                                     FROM pwc_mfg_cutlyrcntrl_d mmc',
'                                    WHERE     mmc.roll_no = det.roll_no',
'                                          AND MMC.SHRINKAGE =',
'                                                 (SELECT DISTINCT',
'                                                         pl.shrink_pattern',
'                                                    FROM pwc_mfg_fabins_ptrnaloc_l pl,',
'                                                         pwc_mfg_fabins_ptrnaloc_d pld',
'                                                   WHERE     pl.prod_l_id =',
'                                                                line.prod_l_id',
'                                                         AND pld.aloc_line_id =',
'                                                                pl.aloc_line_id',
'                                                         AND pld.roll_no =',
'                                                                sdd.roll_no)',
'                                          AND MMC.SUPP_ROLL_NO =',
'                                                 det.supp_roll_no',
'                                          AND MMC.SHADE = shdl.shade',
'                                          AND mmc.end_bit_yds IS NULL',
'                                          AND mmc.end_bit_inch IS NULL))) aa',
'WHERE     1 = 1',
'       AND PWC_GET_ROLL_BALANCE_QTY (roll_no) <> 0',
'       AND aa.roll_no NOT IN',
'              (SELECT DISTINCT PwcMfgCutlyrcntrlD.ROLL_NO',
'                 FROM PWC_MFG_CUTLYRCNTRL_H PwcMfgCutlyrcntrlH,',
'                      PWC_MFG_CUTLYRCNTRL_L PwcMfgCutlyrcntrlL,',
'                      PWC_MFG_CUTLYRCNTRL_D PwcMfgCutlyrcntrlD',
'                WHERE     1 = 1',
'                      AND PwcMfgCutlyrcntrlH.TRACKING_NO = :P75_TRACKING_NO',
'                      AND PwcMfgCutlyrcntrlH.HEADER_ID =',
'                             PwcMfgCutlyrcntrlL.HEADER_ID',
'                      AND PwcMfgCutlyrcntrlL.LINE_ID =',
'                             PwcMfgCutlyrcntrlD.LINE_ID',
'                      AND PwcMfgCutlyrcntrlL.cut_no = :P75_CUT_NUMBER)',
'                      ',
'                      ',
'                      ',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Fill Rolls'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
