wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(156276487865217933)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_cut_no   VARCHAR2(50);',
'    v_bpo_no   VARCHAR2(50);',
'BEGIN',
'    SELECT l.CUT_NO,',
'           l.BPO_NO',
'    INTO   v_cut_no,',
'           v_bpo_no',
'    FROM PWC_MFG_CUTLYRCNTRL_L l',
'    WHERE (:P75_BPO_NUMBER IS NULL OR l.BPO_NO = :P75_BPO_NUMBER)',
'      AND (:P75_CUT_NUMBER IS NULL OR l.CUT_NO = :P75_CUT_NUMBER)',
'      AND ROWNUM = 1;  -- single record ke liye',
'',
'    -- APEX items set',
'    :P75_CUT_NUMBER := v_cut_no;',
'    :P75_BPO_NUMBER := v_bpo_no;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        NULL;',
'    WHEN TOO_MANY_ROWS THEN',
'        NULL;',
'END;',
'',
'-- DECLARE',
'--    -- v_header_id   NUMBER;',
'--     v_cut_no      VARCHAR2(50);',
'--     v_bpo_no      VARCHAR2(50);',
'-- BEGIN',
'--     SELECT-- h.HEADER_ID,',
'--            l.CUT_NO,',
'--            l.BPO_NO',
'--     INTO   --v_header_id,',
'--            v_cut_no,',
'--            v_bpo_no',
'--     FROM PWC_MFG_CUTLYRCNTRL_H h',
'--     JOIN PWC_MFG_CUTLYRCNTRL_L l',
'--       ON h.HEADER_ID = l.HEADER_ID',
'--     WHERE (:P75_ORG_ID IS NULL OR h.ORG_ID = :P75_ORG_ID)',
'--       AND (:P75_BPO_NUMBER IS NULL OR l.BPO_NO = :P75_BPO_NUMBER)',
'--       AND (:P75_TRACKING_NO IS NULL OR h.TRACKING_NO = :P75_TRACKING_NO)',
'--       AND (:P75_CUT_NUMBER IS NULL OR l.CUT_NO = :P75_CUT_NUMBER);',
'--      -- AND ROWNUM = 1;  -- single record ke liye',
'',
'--     -- APEX items me set karna ho to:',
'--     :P75_HEADER_ID := v_header_id;',
'--     :P75_CUT_NUMBER    := v_cut_no;',
'--     :P75_BPO_NUMBER    := ''INLINE'';--v_bpo_no;',
'',
'-- EXCEPTION',
'--     WHEN NO_DATA_FOUND THEN',
'--         NULL;',
'--     WHEN TOO_MANY_ROWS THEN',
'--         NULL;',
'-- END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>156276487865217933
);
end;
