begin
wwv_flow_imp_page.create_page(
 p_id=>76
,p_name=>'Order Details'
,p_alias=>'ORDER-DETAILS'
,p_step_title=>'Order Details'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
,p_last_updated_by=>'AMIR'
,p_last_upd_yyyymmddhh24miss=>'20260406103521'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(157226766938996602)
,p_plug_name=>'New'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>11
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html   CLOB;',
'',
'    v_total_orders   NUMBER := 0;',
'    v_completed      NUMBER := 0;',
'    v_in_progress    NUMBER := 0;',
'    v_pending        NUMBER := 0;',
'',
'BEGIN',
'    DBMS_LOB.CREATETEMPORARY(l_html, TRUE);',
'',
'    /* COUNTS */',
'    SELECT COUNT(*) INTO v_total_orders FROM PWC_ONT_WVN_PRECOSTING_H;',
'',
'   ',
'    SELECT DISTINCT COUNT(*)  INTO v_completed ',
'    FROM PWC_ONT_WVN_PRECOSTING_H',
'    WHERE ORDER_STATUS = ''Actual''',
'    GROUP BY ORDER_STATUS;',
'    ',
'',
'    SELECT COUNT(*) INTO v_in_progress ',
'    FROM PWC_ONT_WVN_PRECOSTING_H',
'    WHERE ORDER_STATUS = ''Fabric Booking''',
'    GROUP BY ORDER_STATUS;',
'',
'    SELECT COUNT(*) INTO v_pending ',
'    FROM PWC_ONT_WVN_PRECOSTING_H',
'    WHERE ORDER_STATUS IS NULL OR ORDER_STATUS = ''NULL''',
'    GROUP BY ORDER_STATUS;',
'',
'',
'    /* HTML START */',
'    DBMS_LOB.APPEND(l_html, ''',
'',
'<style>',
'.section{background:#fff;padding:20px;margin:20px;border-radius:12px;}',
'.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:15px;}',
'.card{padding:20px;border-radius:12px;color:#fff;text-align:center;}',
'.blue{background:#3b82f6;}',
'.green{background:#10b981;}',
'.orange{background:#f59e0b;}',
'.red{background:#ef4444;}',
'</style>',
'',
'<div class="section">',
'<h2>Order Details</h2>',
'',
'<div class="cards">',
'<div class="card blue"><h3>''||v_total_orders||''</h3><p>Total</p></div>',
'<div class="card green"><h3>''||v_completed||''</h3><p>Completed</p></div>',
'<div class="card orange"><h3>''||v_in_progress||''</h3><p>In Progress</p></div>',
'<div class="card red"><h3>''||v_pending||''</h3><p>Pending</p></div>',
'</div>',
'</div>',
''');',
'',
'',
'    /* TABLE START */',
'    DBMS_LOB.APPEND(l_html, ''',
'<div class="section">',
'<table border="1" width="100%">',
'<tr>',
'<th>Doc</th><th>Brand</th><th>Qty</th><th>Status</th>',
'</tr>',
''');',
'',
'',
'    FOR rec IN (',
'        SELECT DOCUMENT_NO, BRAND_NAME, ORDER_QUANTITY, ORDER_STATUS',
'        FROM PWC_ONT_WVN_PRECOSTING_H',
'        WHERE ROWNUM <= 50',
'    ) LOOP',
'',
'        DBMS_LOB.APPEND(l_html,',
'        ''<tr>',
'            <td>''||NVL(rec.DOCUMENT_NO,''-'')||''</td>',
'            <td>''||NVL(rec.BRAND_NAME,''-'')||''</td>',
'            <td>''||NVL(rec.ORDER_QUANTITY,0)||''</td>',
'            <td>''||NVL(rec.ORDER_STATUS,''_'')||''</td>',
'        </tr>'');',
'',
'    END LOOP;',
'',
'    DBMS_LOB.APPEND(l_html, ''</table></div>'');',
'',
'    RETURN l_html;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''<h3 style="color:red;">Error: ''||SQLERRM||''</h3>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
end;
/
