 p_id=>wwv_flow_imp.id(526334610459958818)
,p_plug_name=>'Commercial Invoice'
,p_region_name=>'CI_IR'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_plug_grid_column_css_classes=>'custom-ir-style'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  SELECT CIH.EXP_CI_HEADER_ID,',
'         CIH.DOC_NO,',
'         CIH.VERSION_NO,',
'         CIH.SYS_INVOICE_NO,',
'         CIH.INVOICE_NO,',
'         CIH.MANUFACTURER_NAME,',
'         CIH.INVOICE_DATE,',
'         CIH.EX_FACTORY_DATE,',
'         CIH.BILL_LADING_DATE,',
'         CIH.TRX_NUMBER,',
'         CIH.BUYER_NAME,',
'         CIH.DOCUMENT_TYPE,',
'         CIH.CONTRACT_LC_NUMBER,',
'         CIH.CONTRACT_LC_DATE,',
'         CIH.EXPORT_LC_NO,',
'         CIH.EXPORT_LC_DATE,',
'         CIH.NEGOTIATION_BANK,',
'         CIH.BANK_BRANCH,',
'         CIH.BANK_ADDRESS,',
'         CIH.NEGOTIATION_BANK_SWIFT_CODE,',
'         CIH.INVOICE_STATUS,',
'         (SELECT LISTAGG (PwcExpCommercialInvoiceLEO.TRACKING_NO, '', '')',
'                    WITHIN GROUP (ORDER BY CIH.DOC_NO DESC)',
'            FROM PWC_EXP_COMMERCIAL_INVOICE_L PwcExpCommercialInvoiceLEO',
'           WHERE PwcExpCommercialInvoiceLEO.EXP_CI_HEADER_ID =',
'                    CIH.EXP_CI_HEADER_ID)',
'            tracking_no,',
'         (SELECT LISTAGG (PwcExpCommercialInvoiceLEO.PACK_LIST_NO, '', '')',
'                    WITHIN GROUP (ORDER BY CIH.DOC_NO DESC)',
'            FROM PWC_EXP_COMMERCIAL_INVOICE_L PwcExpCommercialInvoiceLEO',
'           WHERE PwcExpCommercialInvoiceLEO.EXP_CI_HEADER_ID =',
'                    CIH.EXP_CI_HEADER_ID)',
'            PACK_LIST,',
'         (SELECT LISTAGG (PwcExpCommercialInvoiceLEO.ORDER_BPO, '', '')',
'                    WITHIN GROUP (ORDER BY CIH.DOC_NO DESC)',
'            FROM PWC_EXP_COMMERCIAL_INVOICE_L PwcExpCommercialInvoiceLEO',
'           WHERE PwcExpCommercialInvoiceLEO.EXP_CI_HEADER_ID =',
'                    CIH.EXP_CI_HEADER_ID)',
'            bpo_no',
'    FROM PWC_EXP_COMMERCIAL_INVOICE_H CIH',
'ORDER BY CIH.DOC_NO DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
