wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(551493312400660224)
,p_plug_name=>'Invoice Details'
,p_region_name=>'FI_FS'
,p_parent_plug_id=>wwv_flow_imp.id(548312919606987497)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CIL.EXP_CI_LINE_ID,               ',
'       CIL.EXP_CI_HEADER_ID,               ',
'       CIL.PACK_LIST_NO,               ',
'       CIL.TRACKING_NO,               ',
'       CIL.ORDER_BPO,               ',
'       CIL.COUNTRY,               ',
'       CIL.DCPO,               ',
'       CIL.DELIVERY_DATE,               ',
'       CIL.ARTICLE_NO,               ',
'       CIL.ITEM_NO,               ',
'       CIL.ITEM_DESCRIPTION,               ',
'       CIL.COLOR,               ',
'       CIL.SHIP_QTY,               ',
'       CIL.UOM,               ',
'       CIL.UNIT_PRICE,               ',
'       CIL.FINAL_UNIT_PRICE,               ',
'       CIL.CURRENCY,               ',
'       CIL.GOODS_VALUE,               ',
'       CIL.TRADE_DISCOUNT_COMMISSION,               ',
'       CIL.INVOICE_VALUE,               ',
'       CIL.HTS_CODE,               ',
'       CIL.CARTON_NO,               ',
'       CIL.INCO_TERMS,               ',
'       CIL.CARTON_QUANTITY,               ',
'       CIL.NET_NET_WEIGHT,               ',
'       CIL.NET_WEIGHT,               ',
'       CIL.GROSS_WEIGHT,               ',
'       CIL.CHARGABLE_GROSS_WEIGHT,               ',
'       CIL.CBM_M,               ',
'       CIL.EXCESS_SHORT_QTY,               ',
'       CIL.PERC_EXCESS_SHORT_QTY,               ',
'       CIL.SHIPMENT_MODE,               ',
'       CIL.SHIPMENT_TYPE,               ',
'       CIL.FREIGHT_CHARGE,               ',
'       CIL.ITEM_CODE,               ',
'       CIL.ITEM_NAME,               ',
'       CIL.CARTON_WEIGHT,               ',
'       CIL.ORDERED_ITEM_ID,               ',
'       CIL.ORG_ID,               ',
'       CIL.ORGANIZATION_ID,               ',
'       CIL.LAST_UPDATE_DATE,               ',
'       CIL.LAST_UPDATED_BY,               ',
'       CIL.CREATION_DATE,               ',
'       CIL.CREATED_BY,               ',
'       PWC_MASTER_TRACKING_DATA_FUNC (CIL.TRACKING_NO, ''SEASON_NAME'') AS SEASON,               ',
'       CIL.PAYMENT_TERMS,               ',
'       CIL.REPLACE_BPO ,             ',
'       (select ogpl.OGP_NO from apps.MTML_M6_GMT_OGP_L@adf ogpl  ,apps.MTML_M6_GMT_OGP_H@adf ogplh         ',
'        where CIL.TRACKING_NO = ogpl.TRACKING_NO          ',
'        and CIL.ORDER_BPO = ogpl.BPO_NO          ',
'        and CIL.PACK_LIST_NO = ogpl.PACKING_LIST_NO          ',
'        and CIL.COLOR =  ogpl.COLOR ',
'        and ogplh.OGP_NO = ogpl.OGP_NO ',
'        and ogplh.OGP_STATUS != ''C'') OGP_NO,            ',
'        CIL.STYLE_NAME,         ',
'        (select DISPATCH_CARTONS from apps.MTML_M6_GMT_OGP_L@adf ogpl ,apps.MTML_M6_GMT_OGP_H@adf ogplh       ',
'where CIL.TRACKING_NO = ogpl.TRACKING_NO        ',
'and CIL.ORDER_BPO = ogpl.BPO_NO        ',
'and CIL.PACK_LIST_NO = ogpl.PACKING_LIST_NO        ',
'and CIL.COLOR =  ogpl.COLOR ',
'and ogplh.OGP_NO = ogpl.OGP_NO ',
'        and ogplh.OGP_STATUS != ''C'') CARTON_QTY,       ',
'(select ogpl.DISPATCH_PCS from apps.MTML_M6_GMT_OGP_L@adf ogpl,apps.MTML_M6_GMT_OGP_H@adf ogplh              ',
'        where CIL.TRACKING_NO = ogpl.TRACKING_NO              ',
'        and CIL.ORDER_BPO = ogpl.BPO_NO              ',
'        and CIL.PACK_LIST_NO = ogpl.PACKING_LIST_NO              ',
'        and CIL.COLOR =  ogpl.COLOR ',
'        and ogplh.OGP_NO = ogpl.OGP_NO ',
'        and ogplh.OGP_STATUS != ''C'') DISPATCH_PCS,      ',
'        CIL.INVOICE_QTY,     ',
'        (SELECT SUM(l.INVOICE_QTY)       ',
'        FROM pwc_exp_commercial_invoice_h h, pwc_exp_packing_list_h  hedereo, pwc_exp_commercial_invoice_l l       ',
'        WHERE       ',
'            h.exp_ci_header_id = l.exp_ci_header_id       ',
'            AND l.pack_list_no = hedereo.PACKING_LIST_NO       ',
'            AND l.pack_list_no = CIL.PACK_LIST_NO       ',
'    )  INVOICE_QT_AL_BOOKED,    ',
'    (SELECT SUM(l.CARTON_QUANTITY)       ',
'        FROM pwc_exp_commercial_invoice_h h, pwc_exp_packing_list_h  hedereo, pwc_exp_commercial_invoice_l l       ',
'        WHERE       ',
'            h.exp_ci_header_id = l.exp_ci_header_id       ',
'            AND l.pack_list_no = hedereo.PACKING_LIST_NO       ',
'            AND l.pack_list_no = CIL.PACK_LIST_NO       ',
'    )  CARTON_QT_AL_BOOKED,  ',
'    CIL.COMPOSITION,  ',
'    CIL.USER_UNIT_PRICE  ',
'FROM  PWC_EXP_COMMERCIAL_INVOICE_L CIL',
'where CIL.EXP_CI_HEADER_ID = :P79_EXP_CI_HEADER_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P79_EXP_CI_HEADER_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Invoice Details'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
