wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(154148311709047623)
,p_name=>'PACK_LIST_NO'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'PACK_LIST_NO'
,p_data_type=>'NUMBER'
,p_is_query_only=>false
,p_item_type=>'NATIVE_POPUP_LOV'
,p_heading=>'Packing List No.'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>60
,p_value_alignment=>'CENTER'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_is_required=>true
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  DISTINCT hedereo.packing_list_no--, hedereo.*        ',
'  FROM pwc_exp_packing_list_h hedereo   ,     ',
'  MTML_MAIN_CUSTOMER main,       ',
'                 MTML_MAIN_CUSTOMER_BRANDS brands       ',
'       --, pwc_exp_packing_list_bpo line         ',
' WHERE 1=1             ',
'       --and hedereo.packing_list_id = line.packing_list_id         ',
'      AND hedereo.submitstatus = ''Submitted''         ',
'        AND main.HEADER_ID = brands.HEADER_ID       ',
'                  AND main.STATUS = ''A''       ',
'                 AND brands.STATUS = ''A''       ',
'                 AND main.POSTED_YN = ''Y''       ',
'                 AND hedereo.BUYER_ID = brands.CUSTOMER_ID       ',
'       AND hedereo.org_id = 85         ',
'      and  main.CUSTOMER_NAME = :P79_BUYER_NAME         ',
'       AND hedereo.version_no =         ',
'              (SELECT MAX (h.version_no)         ',
'                 FROM pwc_exp_packing_list_h h         ',
'                WHERE     hedereo.packing_list_no = h.packing_list_no         ',
'                      AND h.submitstatus = hedereo.submitstatus)         ',
'       /*AND NOT EXISTS         ',
'                  (SELECT 1         ',
'                     FROM pwc_exp_commercial_invoice_h h,         ',
'                          pwc_exp_commercial_invoice_l l         ',
'                    WHERE     h.exp_ci_header_id = l.exp_ci_header_id         ',
'                          AND pack_list_no = hedereo.packing_list_no);*/       ',
'                                 ',
'  AND ((select ogpl.DISPATCH_PCS from apps.MTML_M6_GMT_OGP_L@adf ogpl ,apps.MTML_M6_GMT_OGP_H@adf ogplh          ',
'        where hedereo.TRACKING_NO = ogpl.TRACKING_NO          ',
'        and hedereo.BPO = ogpl.BPO_NO          ',
'        and hedereo.PACKING_LIST_NO = ogpl.PACKING_LIST_NO       ',
'        AND hedereo.PACKING_LIST_NO = hedereo.packing_list_no   ',
'        and ogplh.OGP_NO = ogpl.OGP_NO   ',
'        and ogplh.OGP_STATUS != ''C'' ) >                              ',
'           ',
'        ',
'  (SELECT SUM(INVOICE_QTY)       ',
'                     FROM pwc_exp_commercial_invoice_h h,         ',
'                          pwc_exp_commercial_invoice_l l         ',
'                    WHERE     h.exp_ci_header_id = l.exp_ci_header_id         ',
'                          AND pack_list_no = hedereo.packing_list_no)       ',
'                          OR  NOT EXISTS         ',
'                  (SELECT 1         ',
'                     FROM pwc_exp_commercial_invoice_h h,         ',
'                          pwc_exp_commercial_invoice_l l         ',
'                    WHERE     h.exp_ci_header_id = l.exp_ci_header_id         ',
'                          AND pack_list_no = hedereo.packing_list_nO))',
''))
,p_lov_display_extra=>true
,p_lov_display_null=>true
,p_enable_filter=>true
,p_filter_operators=>'C:S:CASE_INSENSITIVE:REGEXP'
,p_filter_is_required=>false
,p_filter_text_case=>'MIXED'
,p_filter_exact_match=>true
,p_filter_lov_type=>'LOV'
,p_use_as_row_header=>false
,p_enable_sort_group=>true
,p_enable_control_break=>true
,p_enable_hide=>true
,p_is_primary_key=>false
,p_duplicate_value=>true
,p_include_in_export=>true
