wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(154137988567043419)
,p_name=>'P79_SHIP_TO_ADDRESS'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>300
,p_item_plug_id=>wwv_flow_imp.id(531900607208573496)
,p_item_source_plug_id=>wwv_flow_imp.id(531900607208573496)
,p_prompt=>'Ship To Address'
,p_source=>'SHIP_TO_ADDRESS'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'COMMERCIAL_INVOCE_H_ADDRESS_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT customer_number,   ',
'       customer_name,   ',
'       site_number,   ',
'       address1 || address2 || address3 || CITY || POSTAL_CODE || STATE Address,  ',
'       country,   ',
'       SHIP_TO_LOCATION,   ',
'       CUST_ACCOUNT_ID,   ',
'       CUST_ACCT_SITE_ID,   ',
'       ORG_ID       ',
'FROM (   ',
'SELECT hca.account_number customer_number,    ',
'       hp.party_name customer_name,   ',
'       hps.party_site_number site_number,   ',
'       (SELECT address1   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) address1,   ',
'       (SELECT address2   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) address2,   ',
'       (SELECT address3   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) address3,   ',
'       (SELECT address4   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) address4,   ',
'       (SELECT city   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) city,   ',
'       (SELECT postal_code   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) postal_code,   ',
'       (SELECT state   ',
'          FROM APPS.hz_locations@ADF   ',
'         WHERE location_id = hps.location_id) state,   ',
'       (SELECT ftt.territory_short_name   ',
'          FROM APPS.fnd_territories_tl@ADF ftt, APPS.hz_locations@ADF hl   ',
'         WHERE hl.country = ftt.territory_code   ',
'           AND hl.location_id = hps.location_id) country,   ',
'       (SELECT DISTINCT hcsua.LOCATION   ',
'                   FROM APPS.hz_cust_site_uses_all@ADF hcsua   ',
'                  WHERE hcsua.cust_acct_site_id =   ',
'                                     hcasa.cust_acct_site_id   ',
'                    AND hcsua.site_use_code = ''BILL_TO'') bill_to_location,   ',
'       (SELECT DISTINCT hcsua.LOCATION   ',
'                   FROM APPS.hz_cust_site_uses_all@ADF hcsua   ',
'                  WHERE hcsua.cust_acct_site_id =   ',
'                                     hcasa.cust_acct_site_id   ',
'                    AND hcsua.site_use_code = ''SHIP_TO''   ',
'        and hcsua.status=''A'') ship_to_location,   ',
'        HCA.CUST_ACCOUNT_ID,   ',
'        HCASA.CUST_ACCT_SITE_ID,   ',
'        hcasa.org_id   ',
'  FROM APPS.hz_parties@ADF hp,   ',
'       APPS.hz_party_sites@ADF hps,   ',
'       APPS.hz_cust_accounts_all@ADF hca,   ',
'       APPS.hz_cust_acct_sites_all@ADF hcasa   ',
' WHERE hp.party_id = hps.party_id   ',
'   AND hp.party_id = hca.party_id   ',
'   AND hcasa.party_site_id = hps.party_site_id   ',
'   AND hca.cust_account_id = hcasa.cust_account_id   ',
'   AND Ship_to_flag IS NOT NULL   ',
'   )   ',
'   ',
'  where CUST_ACCOUNT_ID= :P79_BUYER_ID   ',
'   and ORG_ID = 85 ',
''))
