 p_id=>wwv_flow_imp.id(154452542365132339)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(551493312400660224)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Invoice Details - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C'' THEN',
'            INSERT INTO PWC_EXP_COMMERCIAL_INVOICE_L (',
'                EXP_CI_HEADER_ID,',
'                PACK_LIST_NO',
'            )',
'            VALUES (',
'                :EXP_CI_HEADER_ID,',
'                :PACK_LIST_NO',
'            )',
'            RETURNING EXP_CI_LINE_ID INTO :EXP_CI_LINE_ID;',
'',
'        WHEN ''U'' THEN',
'            UPDATE PWC_EXP_COMMERCIAL_INVOICE_L',
'            SET DELIVERY_DATE = :DELIVERY_DATE,     ',
'            --ITEM_DESCRIPTION = :ITEM_DESCRIPTION,  ',
'            UOM = :UOM,',
'            INVOICE_QTY = :INVOICE_QTY,   ',
'            INVOICE_VALUE = :INVOICE_VALUE,',
'            HTS_CODE = :HTS_CODE,',
'            CARTON_NO = :CARTON_NO,',
'            INCO_TERMS = :INCO_TERMS,',
'            CARTON_QUANTITY = :CARTON_QUANTITY,    ',
'            SHIPMENT_MODE = :SHIPMENT_MODE,',
'            SHIPMENT_TYPE = :SHIPMENT_TYPE,',
'            FREIGHT_CHARGE = :FREIGHT_CHARGE,',
'            CARTON_WEIGHT = :CARTON_WEIGHT,',
'            --ORDERED_ITEM_ID = :ORDERED_ITEM_ID,',
'            PAYMENT_TERMS = :PAYMENT_TERMS,',
'            COMPOSITION = :COMPOSITION,',
'            USER_UNIT_PRICE = :USER_UNIT_PRICE',
'            WHERE EXP_CI_LINE_ID = :EXP_CI_LINE_ID;',
'',
'        WHEN ''D'' THEN',
'            DELETE FROM PWC_EXP_COMMERCIAL_INVOICE_L',
'            WHERE EXP_CI_LINE_ID = :EXP_CI_LINE_ID;',
'',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>154452542365132339
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(156063922867189743)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(551493312400660224)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Invoice Details Calculations'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    V_SUM_INVOICE_QTY        NUMBER := 0;',
'    V_SUM_GOODS_VALUE        NUMBER := 0;',
'    V_SUM_INVOICE_VALUE      NUMBER := 0;',
'    V_SUM_CARTON_QUANTITY    NUMBER := 0;',
'    V_SUM_ADJUSTMENTS        NUMBER := 0;',
'',
'    V_NET_WEIGHT             NUMBER := 0;',
'    V_GROSS_WEIGHT           NUMBER := 0;',
'',
'BEGIN',
'   SELECT ',
'        SUM(INVOICE_QTY), ',
'        SUM(GOODS_VALUE), ',
'        SUM(INVOICE_VALUE), ',
'        SUM(CARTON_QUANTITY) ',
'   INTO  ',
'        V_SUM_INVOICE_QTY,',
'        V_SUM_GOODS_VALUE, ',
'        V_SUM_INVOICE_VALUE, ',
'        V_SUM_CARTON_QUANTITY ',
'   FROM PWC_EXP_COMMERCIAL_INVOICE_L',
'   WHERE EXP_CI_HEADER_ID = :P79_EXP_CI_HEADER_ID;',
'',
'   SELECT SUM(LINE_ADJUSTMENT_AMOUNT) ',
'   INTO V_SUM_ADJUSTMENTS',
'   FROM PWC_EXP_COMM_INVOICE_ADJUST_L',
'   WHERE EXP_CI_HEADER_ID = :P79_EXP_CI_HEADER_ID;',
'',
'   APEX_ADF.pwc_exp_ci_weight_calculation (',
'       p_header_id    => :P79_EXP_CI_HEADER_ID,',
'       p_net_weight   => V_NET_WEIGHT,',
'       p_gross_weight => V_GROSS_WEIGHT',
'   );',
'',
'   UPDATE PWC_EXP_COMMERCIAL_INVOICE_H',
'   SET TOTAL_EXPORTED_VALUE = NVL(V_SUM_GOODS_VALUE,0),',
'       INVOICE_AMOUNT       = NVL(V_SUM_INVOICE_VALUE,0),',
'       NET_INVOICE_AMOUNT   = NVL(V_SUM_INVOICE_VALUE,0) - NVL(V_SUM_ADJUSTMENTS,0),',
'       TOTAL_CARTON_QTY     = NVL(V_SUM_CARTON_QUANTITY,0),',
'       TOTAL_NET_WT           = NVL(V_NET_WEIGHT,0),',
'       TOTAL_NET_NET_WT         = NVL(V_GROSS_WEIGHT,0)',
'',
'   WHERE EXP_CI_HEADER_ID = :P79_EXP_CI_HEADER_ID;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>156063922867189743
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(154452292406132336)
