,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(548413467390890202)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Adjustment Details - Save Interactive Grid Data'
,p_attribute_01=>'REGION_SOURCE'
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_attribute_08=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>154452292406132336
