wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(157229648337996631)
,p_plug_name=>'Issuance'
,p_parent_plug_id=>wwv_flow_imp.id(157392404657056314)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LineEO.HEADER_ID,    -----foreign key with detail line_id---- ',
'       LineEO.LINE_ID,   -----pk  -----',
'       LineEO.QUANTITY,     ',
'       LineEO.CUT_DATE,     ',
'       LineEO.STITCH_PREP_DATE,     ',
'       LineEO.WASHING_PLANT,     ',
'       LineEO.SEND_WASH_DATE,     ',
'       LineEO.SEND_BY,     ',
'       LineEO.CARRIED_BY,     ',
'       LineEO.DEL_CHALLAN_NO,     ',
'       LineEO.REMARKS,     ',
'       LineEO.ATTRIBUTE1,     ',
'       LineEO.ATTRIBUTE2,     ',
'       LineEO.ATTRIBUTE3,     ',
'       LineEO.ATTRIBUTE4,     ',
'       LineEO.ATTRIBUTE5,     ',
'       LineEO.ATTRIBUTE6,     ',
'       LineEO.ATTRIBUTE7,     ',
'       LineEO.ATTRIBUTE8,     ',
'       LineEO.ATTRIBUTE9,     ',
'       LineEO.ATTRIBUTE10,     ',
'       LineEO.ATTRIBUTE11,     ',
'       LineEO.ATTRIBUTE12,     ',
'       LineEO.ATTRIBUTE13,     ',
'       LineEO.ATTRIBUTE14,     ',
'       LineEO.ATTRIBUTE15,     ',
'       LineEO.SALESORDER_ID,     ',
'       LineEO.LAST_UPDATE_DATE,     ',
'       LineEO.LAST_UPDATED_BY,     ',
'       LineEO.CREATION_DATE,     ',
'       LineEO.CREATED_BY,     ',
'       LineEO.ORG_ID,     ',
'       LineEO.CHALLAN_NO,     ',
'       LineEO.WASH_TYPE,     ',
'       LineEO.PRODUCTION_TYPE,     ',
'       LineEO.WASH_EMD_PRINT_INV,     ',
'       LineEO.WASH_EMD_PRINT_INVORG,     ',
'       LineEO.ISSUANCE_CHALLAN_NO,     ',
'       LineEO.ISSUANCE_DATE,     ',
'       LineEO.Received_By,    ',
'       LineEO.ROPE_COLOR,    ',
'       LineEO.COUNTRY,    ',
'       LineEO.CHILD_STYLE_NO,    ',
'       LineEO.STYLE_CATEGORY,    ',
'       (SELECT DISTINCT ooha.attribute12    ',
'            FROM apps.oe_order_headers_all@adf ooha,    ',
'                 apps.oe_order_lines_all@adf oola,    ',
'                 apps.mtl_system_items@adf msi    ',
'           WHERE     ooha.attribute12 IS NOT NULL    ',
'                 AND ooha.header_id = oola.header_id    ',
'                 AND msi.inventory_item_id = oola.inventory_item_id    ',
'                 AND msi.organization_id = ooha.org_id    ',
'                 AND REGEXP_SUBSTR (msi.description,    ',
'                                    ''[^:]+'',    ',
'                                    1,    ',
'                                    3) = LineEO.ATTRIBUTE3    ',
'                 AND ooha.attribute4 = (SELECT h.TRACKING_NO    ',
'                                          FROM PWC_MFG_ISSUE_REC_WASH_L_H h    ',
'                                         WHERE h.LINE_ID = LineEO.HEADER_ID)    ',
'                 AND ooha.cust_po_number = LineEO.ATTRIBUTE1)    ',
'            replace_bpo,    ',
'            LineEO.SHADE_REC_WASH ,    ',
'            CASE WHEN PWC_ISSUANCE_WASH_PAD_TRANS(LineEO.LINE_ID) IN (''After Stitch Issue to Wash'')   ',
'                    then   ',
'                        NVL((select distinct ''Y''    ',
'                                from PWC_ISSUE_REC_WASH_REC_L l    ',
'                                where l.ATTRIBUTE1 = LineEO.ATTRIBUTE1), ''N'')  ',
'             WHEN PWC_ISSUANCE_WASH_PAD_TRANS(LineEO.LINE_ID) IN (''Ready For Finish Department'')  ',
'                    THEN  ',
'                        NVL((SELECT DISTINCT  ''Y''   ',
'                            FROM PWC_MFG_ISSUE_TO_FINISH_L L   ',
'                            WHERE L.ATTRIBUTE1 =  LineEO.ATTRIBUTE1), ''N'')  ',
'                ELSE   ',
'                ''N''   ',
'                END issu_si_del_check   ',
'FROM PWC_MFG_ISSUE_REC_WASH_L LineEO    -----PWC_MFG_ISSUE_REC_WASH_L',
'',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_master_region_id=>wwv_flow_imp.id(157226917129996604)
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Issuance'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
