'       ReceiveDetailEO.ATTRIBUTE11,      ',
'       ReceiveDetailEO.ATTRIBUTE12,      ',
'       ReceiveDetailEO.ATTRIBUTE13,      ',
'       ReceiveDetailEO.ATTRIBUTE14,      ',
'       ReceiveDetailEO.ATTRIBUTE15,      ',
'       ReceiveDetailEO.SALESORDER_ID,      ',
'       ReceiveDetailEO.LAST_UPDATE_DATE,      ',
'       ReceiveDetailEO.LAST_UPDATED_BY,      ',
'       ReceiveDetailEO.CREATION_DATE,      ',
'       ReceiveDetailEO.CREATED_BY,      ',
'       ReceiveDetailEO.ORG_ID,      ',
'       ReceiveDetailEO.WASH_EMD_PRINT_INVORG,      ',
'       ReceiveDetailEO.WASH_EMD_PRINT_INV,      ',
'       ReceiveDetailEO.WASH_TYPE,      ',
'       ReceiveDetailEO.PRODUCTION_TYPE,      ',
'       ReceiveDetailEO.RECEVING_DATE,      ',
'       ReceiveDetailEO.COUNTRY,     ',
'       ReceiveDetailEO.CHILD_STYLE_NO,     ',
'       ReceiveDetailEO.STYLE_CATEGORY,     ',
'       (SELECT DISTINCT ooha.attribute12     ',
'            FROM APPS.oe_order_headers_all@ADF ooha,     ',
'                 APPS.oe_order_lines_all@ADF oola,     ',
'                 APPS.mtl_system_items@ADF msi     ',
'           WHERE     ooha.attribute12 IS NOT NULL     ',
'                 AND ooha.header_id = oola.header_id     ',
'                 AND msi.inventory_item_id = oola.inventory_item_id     ',
'                 AND msi.organization_id = ooha.org_id     ',
'                 AND REGEXP_SUBSTR (msi.description,     ',
'                                    ''[^:]+'',     ',
'                                    1,     ',
'                                    3) = ReceiveDetailEO.ATTRIBUTE3     ',
'                 AND ooha.attribute4 = (SELECT h.TRACKING_NO     ',
'                                          FROM PWC_MFG_ISSUE_REC_WASH_L_H h     ',
'                                         WHERE h.LINE_ID = ReceiveDetailEO.HEADER_ID)     ',
'                 AND ooha.cust_po_number = ReceiveDetailEO.ATTRIBUTE1)     ',
'            replace_bpo,   ',
'            CASE WHEN PWC_ISSUE_REC_WASH_PAD_TRANS(RECEVING_DETAIL) IN (''Receive from Sewing'')   ',
'                THEN   ',
'                    NVL((select DISTINCT ''Y''   ',
'                        from PWC_MFG_ISSUE_REC_WASH_H H,   ',
'                             PWC_MFG_ISSUE_REC_WASH_L_H TRK,   ',
'                             PWC_MFG_ISSUE_REC_WASH_L BPO    ',
'                        where H.TRANSACTION_TYPE = ''After Stitch Issue to Wash''   ',
'                        AND H.HEADER_ID = TRK.HEADER_ID   ',
'                        --AND TRK.TRACKING_NO = ''KIAB002-2207-1174''   ',
'                        AND BPO.HEADER_ID = TRK.LINE_ID   ',
'                        AND BPO.ATTRIBUTE1 = ReceiveDetailEO.ATTRIBUTE1) , ''N'')   ',
'                WHEN PWC_ISSUE_REC_WASH_PAD_TRANS(RECEVING_DETAIL) IN (''Receive from Washing'')   ',
'                then ',
'                    NVL((select DISTINCT ''Y''  ',
'                            from PWC_ISSUE_REC_WASH_DEL_L l ',
'                            where l.ATTRIBUTE1 = ReceiveDetailEO.ATTRIBUTE1), ''N'') ',
'                ELSE   ',
'                ''N''   ',
'                END si_del_check     ',
'FROM PWC_MFG_ISSUE_REC_WASH_D ReceiveDetailEO',
'--WHERE ReceiveDetailEO.HEADER_ID=''45322'';',
''))
