,p_prompt=>'Transaction Type'
,p_source=>'TRANSACTION_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'ISSUE&RECEIVE_TRANS_TYPE_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''After Stitch Issue to Embroidery'' transaction_type, ''Sewing'' t_type , ''IssuanceTab''  tab_control     ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''    ',
' and 1=2     ',
'UNION ALL      ',
'SELECT ''After Stitch Issue to Print'' transaction_type, ''Sewing'' t_type    , ''IssuanceTab''  tab_control  ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''     ',
' and 1=2    ',
'UNION ALL      ',
'SELECT ''After Stitch Issue to 3rd Party'' transaction_type, ''Sewing'' t_type , ''IssuanceTab''  tab_control     ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''    ',
' and 1=2     ',
'UNION ALL      ',
'SELECT ''After Stitch Issue to Dyeing'' transaction_type, ''Sewing'' t_type   , ''IssuanceTab''  tab_control   ',
'  FROM DUAL  where 1=2    ',
'UNION ALL      ',
'SELECT ''After Stitch Issue to Stock Lot'' transaction_type, ''Sewing'' t_type   , ''IssuanceTab''  tab_control   ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''     ',
' and 1=2    ',
' UNION ALL      ',
' SELECT ''Receive from Sewing'' transaction_type, ''Sewing'' t_type   , ''ReceivingTab'' tab_control   ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''      ',
'UNION ALL      ',
'SELECT ''After Stitch Issue to Wash'' transaction_type, ''Sewing'' t_type  , ''IssuanceTab''  tab_control    ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''      ',
'UNION ALL      ',
'SELECT ''Ready For Finish Department'' transaction_type, ''Sewing'' t_type    , ''IssuanceTab''  tab_control  ',
'  FROM DUAL      ',
'UNION ALL      ',
'SELECT ''After Finish Issue to Embroidery'' transaction_type,      ',
'       ''Finishing'' t_type    , ''IssuanceTab''  tab_control  ',
'  FROM DUAL      ',
' WHERE :p_OrgType = ''DENIM''      ',
' and 1=2   ',
'UNION ALL      ',
'SELECT ''After Finish Issue to Print'' transaction_type, ''Finishing'' t_type   , ''IssuanceTab''  tab_control   ',
'  FROM DUAL      ',
' WHERE NVL(:p_OrgType,''X'') = ''DENIM''    ',
' and 1=2     ',
'UNION ALL      ',
'SELECT ''After Finish Issue to 3rd party'' transaction_type, ''Finishing'' t_type , ''IssuanceTab''  tab_control     ',
'  FROM DUAL   ',
' WHERE NVL(:p_OrgType,''X'') = ''DENIM''   ',
' and 1=2      ',
'UNION ALL      ',
'SELECT ''Non-Wash, Issue to Finish'' transaction_type, ''Sewing'' t_type  , ''IssuanceTab''  tab_control  ',
'  FROM DUAL      ',
'  UNION ALL      ',
'SELECT ''Receive from Washing'' transaction_type, ''Sewing'' t_type , ''ReceivingTab'' tab_control     ',
'  FROM DUAL    ',
'  UNION ALL      ',
'SELECT ''Allocation to Scrap after Sewing'' transaction_type, ''Sewing'' t_type , ''IssuanceTab'' tab_control     ',
'  FROM DUAL   ',
'  UNION ALL      ',
'SELECT ''Allocation to Sample after Sewing'' transaction_type, ''Sewing'' t_type , ''IssuanceTab'' tab_control     ',
'  FROM DUAL   ',
'  UNION ALL      ',
'SELECT ''Allocation to Scrap after Washing'' transaction_type, ''Sewing'' t_type , ''IssuanceTab'' tab_control     ',
'  FROM DUAL   ',
'  UNION ALL      ',
'SELECT ''Allocation to Sample after Washing'' transaction_type, ''Sewing'' t_type , ''IssuanceTab'' tab_control     ',
'  FROM DUAL        ',
'ORDER BY transaction_type'))
,p_lov_display_null=>'YES'
,p_cSize=>32
,p_cMaxlength=>250
,p_colspan=>4
,p_read_only_when=>'P80_TRANSACTION_TYPE'
