wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158936566926985003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Issue and Receive Form'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_HEADER     NUMBER;',
'    V_RECEIVE_NO VARCHAR2(50);',
'    V_SEQ        NUMBER;',
'BEGIN',
'    -- ================= TRY UPDATE =================',
'    IF :P80_HEADER_ID IS NOT NULL THEN',
'',
'        UPDATE PWC_MFG_ISSUE_REC_WASH_H',
'        SET INVOICE_NO       = :P80_INVOICE_NO,',
'            COLOR            = :P80_COLOR,',
'            DATE_OF_GRN      = :P80_DATE_OF_GRN,',
'            UPDATE_ON        = :P80_UPDATE_ON,',
'            LAST_UPDATED_BY  = 723155,',
'            LAST_UPDATE_DATE = SYSDATE,',
'            ORG_ID      = :P80_ORG_ID,',
'            HEADER_NO   = :P80_HEADER_NO,',
'            LOT_NUMBER  = :P80_LOT_NUMBER,',
'            ATTRIBUTE1  = :P80_ATTRIBUTE1,',
'            ATTRIBUTE2  = :P80_ATTRIBUTE2,',
'            ATTRIBUTE3  = :P80_ATTRIBUTE3,',
'            ATTRIBUTE4  = :P80_ATTRIBUTE4,',
'            ATTRIBUTE5  = :P80_ATTRIBUTE5,',
'            ATTRIBUTE6  = :P80_ATTRIBUTE6,',
'            ATTRIBUTE7  = :P80_ATTRIBUTE7,',
'            ATTRIBUTE8  = :P80_ATTRIBUTE8,',
'            ATTRIBUTE9  = :P80_ATTRIBUTE9,',
'            ATTRIBUTE10 = :P80_ATTRIBUTE10,',
'            ATTRIBUTE11 = :P80_ATTRIBUTE11,',
'            ATTRIBUTE12 = :P80_ATTRIBUTE12,',
'            ATTRIBUTE13 = :P80_ATTRIBUTE13,',
'            ATTRIBUTE14 = :P80_ATTRIBUTE14,',
'            ATTRIBUTE15 = :P80_ATTRIBUTE15,',
'            SALESORDER_ID         = :P80_SALESORDER_ID,',
'            TRANSACTION_TYPE      = :P80_TRANSACTION_TYPE,',
'            TRANSACTION           = :P80_TRANSACTION,',
'            DELIVERED_BY          = NVL(:P80_DELIVERED_BY,:APP_USER),',
'            RECEIVED_BY           = :P80_RECEIVED_BY,',
'            WASH_EMB_PRINT_INV    = :P80_WASH_EMB_PRINT_INV,',
'            WASH_EMB_PRINT_INVORG = :P80_WASH_EMB_PRINT_INVORG,',
'            WASHING_PROCESS       = :P80_WASHING_PROCESS,',
'            OSP_CHECK             = :P80_OSP_CHECK,',
'            TAB_VIEW_CONTROL      = :P80_TAB_VIEW_CONTROL,',
'            SUB_TRANS_TYPE        = :P80_SUB_TRANS_TYPE',
'        WHERE HEADER_ID = :P80_HEADER_ID;',
'',
unistr('        -- \2705 Agar update ho gaya to exit'),
'        IF SQL%ROWCOUNT > 0 THEN',
'            apex_debug.message(''UPDATE SUCCESS'');',
'            RETURN;',
'        ELSE',
'            apex_debug.message(''UPDATE FAILED - NO ROW FOUND'');',
'        END IF;',
'',
'    END IF;',
'',
'',
'    -- ================= INSERT =================',
'',
'    -- HEADER_ID generate',
'    SELECT NVL(MAX(HEADER_ID),0) + 1',
'    INTO V_HEADER',
'    FROM PWC_MFG_ISSUE_REC_WASH_H;',
'    :P80_HEADER_ID := V_HEADER;',
'',
'    -- RECEIVE_NO generate',
'    SELECT NVL(MAX(TO_NUMBER(REGEXP_SUBSTR(RECEIVE_NO, ''[^/]+$'', 1, 1))),0) + 1',
'    INTO V_SEQ',
'    FROM PWC_MFG_ISSUE_REC_WASH_H',
'    WHERE REGEXP_LIKE(RECEIVE_NO, ''^\d{4}/\d+$'')',
'    AND SUBSTR(RECEIVE_NO,1,4) = TO_CHAR(SYSDATE,''YYYY'');',
'    V_RECEIVE_NO := TO_CHAR(SYSDATE,''YYYY'') || ''/'' || V_SEQ;',
'    :P80_RECEIVE_NO := V_RECEIVE_NO;',
'',
'    INSERT INTO PWC_MFG_ISSUE_REC_WASH_H (',
'        HEADER_ID, RECEIVE_NO, INVOICE_NO, COLOR, DATE_OF_GRN,',
'        UPDATE_ON, CREATED_BY, CREATION_DATE,',
'        LAST_UPDATED_BY, LAST_UPDATE_DATE,',
'        ORG_ID, HEADER_NO, LOT_NUMBER,',
'        ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5,',
'        ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10,',
'        ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15,',
'        SALESORDER_ID, TRANSACTION_TYPE, TRANSACTION,',
'        DELIVERED_BY, RECEIVED_BY,',
'        WASH_EMB_PRINT_INV, WASH_EMB_PRINT_INVORG,',
'        WASHING_PROCESS, OSP_CHECK,',
'        TAB_VIEW_CONTROL, SUB_TRANS_TYPE',
'    )',
'    VALUES (',
'        V_HEADER, V_RECEIVE_NO,',
'        :P80_INVOICE_NO, :P80_COLOR, :P80_DATE_OF_GRN,',
'        :P80_UPDATE_ON, 723155, SYSDATE,',
'        723155, SYSDATE,',
'        :P80_ORG_ID, :P80_HEADER_NO, :P80_LOT_NUMBER,',
'        :P80_ATTRIBUTE1, :P80_ATTRIBUTE2, :P80_ATTRIBUTE3, :P80_ATTRIBUTE4, :P80_ATTRIBUTE5,',
'        :P80_ATTRIBUTE6, :P80_ATTRIBUTE7, :P80_ATTRIBUTE8, :P80_ATTRIBUTE9, :P80_ATTRIBUTE10,',
'        :P80_ATTRIBUTE11, :P80_ATTRIBUTE12, :P80_ATTRIBUTE13, :P80_ATTRIBUTE14, :P80_ATTRIBUTE15,',
'        :P80_SALESORDER_ID, :P80_TRANSACTION_TYPE, :P80_TRANSACTION,',
'        NVL(:P80_DELIVERED_BY,:APP_USER), :P80_RECEIVED_BY,',
'        :P80_WASH_EMB_PRINT_INV, :P80_WASH_EMB_PRINT_INVORG,',
'        :P80_WASHING_PROCESS, :P80_OSP_CHECK,',
'        :P80_TAB_VIEW_CONTROL, :P80_SUB_TRANS_TYPE',
'    );',
'',
'    apex_debug.message(''INSERT SUCCESS'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_error.add_error(',
'            p_message => ''Error: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>158936566926985003
);
