'                TRACKING_NO          = :TRACKING_NO',
'            WHERE LINE_ID = :LINE_ID;',
'',
'',
'        -- ================= DELETE =================',
'        WHEN ''D'' THEN',
'        ',
'            DELETE FROM PWC_MFG_ISSUE_REC_WASH_L_H',
'            WHERE LINE_ID = :LINE_ID;',
'',
'    END CASE;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
