'                CHILD_STYLE_NO      = :CHILD_STYLE_NO,',
'                STYLE_CATEGORY      = :STYLE_CATEGORY',
'            WHERE LINE_ID = :LINE_ID;',
'',
'',
'        -- ================= DELETE =================',
'        WHEN ''D'' THEN',
'        ',
'            DELETE FROM PWC_MFG_ISSUE_REC_WASH_D',
'            WHERE LINE_ID = :LINE_ID;',
'',
