,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    ',
'  SELECT NewHeader.DIVISION_ID,     ',
'         NewHeader.HEADER_ID,     ',
'         NewHeader.DOC_NUMBER,     ',
'         NewHeader.DOC_DATE,     ',
'         NewHeader.SHIFT,     ',
'         NewHeader.REMARKS,     ',
'         NewHeader.LAST_UPDATE_DATE,     ',
'         NewHeader.LAST_UPDATED_BY,     ',
'         NewHeader.CREATION_DATE,     ',
'         NewHeader.CREATED_BY,     ',
'         NewHeader.DIVISION,     ',
'         (SELECT DISTINCT     ',
'                 CASE     ',
'                    WHEN NewHeader.HEADER_ID = l.header_id THEN ''Y''     ',
'                    ELSE ''N''     ',
'                 END     ',
'            FROM PWC_MFG_GWPPRODUCTION l     ',
'           WHERE NewHeader.HEADER_ID = l.header_id)     ',
'            Flag,     ',
'         PWC_WASH_PRODUCTION_FUNC(''STN'',NewHeader.HEADER_ID)STN,     ',
'         PWC_WASH_PRODUCTION_FUNC(''TRACKING_NO'',NewHeader.HEADER_ID) Tracking_No,     ',
'         PWC_WASH_PRODUCTION_FUNC(''BUYER'',NewHeader.HEADER_ID)  Buyer,     ',
'         PWC_WASH_PRODUCTION_FUNC(''STYLE'',NewHeader.HEADER_ID) Style,     ',
'         PWC_WASH_PRODUCTION_FUNC(''SEASON'',NewHeader.HEADER_ID) Season,     ',
'         PWC_WASH_PRODUCTION_FUNC(''WET_TRACKING_NO'',NewHeader.HEADER_ID) Wet_Tracking_No,     ',
'         PWC_WASH_PRODUCTION_FUNC(''DRY_COLOR'',NewHeader.HEADER_ID) Dry_Color,     ',
'         PWC_WASH_PRODUCTION_FUNC(''WET_COLOR'',NewHeader.HEADER_ID) Wet_Color,     ',
'         NULL Current_Style,     ',
'         NULL Current_Season,   ',
'         CASE   ',
'        WHEN EXTRACT(DAY FROM SYSDATE) > 3   ',
'            AND TRUNC(SYSDATE, ''MONTH'') > ADD_MONTHS(TRUNC(DOC_DATE, ''MONTH''), 0)   ',
'            THEN ''Y''  ',
'            WHEN EXTRACT(DAY FROM SYSDATE) <= 3        ',
'            AND TRUNC(SYSDATE, ''MONTH'') > ADD_MONTHS(TRUNC(DOC_DATE, ''MONTH''), 0)+ INTERVAL ''1'' MONTH        ',
'            THEN ''Y'' ',
'        ELSE ''''   ',
'    END AS DATE_FLAG   ',
'    FROM PWC_MFG_GWPPRODUCTION_H NewHeader     ',
'   WHERE NewHeader.DIVISION_ID = 85--:p_org',
'   and NewHeader.DOC_NUMBER in (''2025/947'' ,''2025/946'',''2025/945'',''2025/944'',''2025/943'',''2025/942'',''2025/941'') OR TRUNC(NewHeader.DOC_DATE) = TRUNC(SYSDATE)',
'--   and (:p_doc_no is null or :p_doc_no is not null)    ',
'ORDER BY NewHeader.HEADER_ID DESC'))
