'         HederEO.JOB_ID,            ',
'         HederEO.OBNO,            ',
'         HederEO.INSEAM_ID,            ',
'         HederEO.REMARKS,            ',
'         HederEO.TRANS_STATUS,            ',
'         HederEO.LAST_UPDATE_DATE,            ',
'         HederEO.LAST_UPDATED_BY,            ',
'         HederEO.CREATION_DATE,            ',
'         HederEO.CREATED_BY,            ',
'         HederEO.PROCESS_ID,            ',
'         HederEO.INVENTORY_ITEM_ID,            ',
'         HederEO.WASH_DEPT_ID,            ',
'         HederEO.SHIFT,            ',
'         '''' STYLE_REF,            ',
'         (SELECT description            ',
'            FROM apps.mtl_system_items_b@adf msib            ',
'           WHERE     msib.ORGANIZATION_ID = 353            ',
'                 AND msib.INVENTORY_ITEM_ID = HederEO.INVENTORY_ITEM_ID)            ',
'            ITEM_NAME,            ',
'         '''' WASH_DEPT_ID_DI,            ',
'         '''' JOB_ID_DI,  ',
'         '''' Show_Balance,          ',
'         (SELECT wdj.WIP_ENTITY_NAME            ',
'            FROM apps.wip_discrete_jobs_v@adf wdj            ',
'           WHERE wdj.WIP_ENTITY_ID = HederEO.job_id)            ',
'            job_name,            ',
'         (SELECT ooha.cust_po_number            ',
'            FROM apps.oe_order_headers_all@adf ooha            ',
'           WHERE ooha.HEADER_ID = HederEO.SALESORDER_ID)            ',
'            order_number,            ',
'         (SELECT wdj.START_QUANTITY            ',
'            FROM apps.wip_discrete_jobs_v@adf wdj            ',
'           WHERE wdj.WIP_ENTITY_ID = HederEO.job_id) job_qty,            ',
'         pwc_master_tracking_data_func(HederEO.tracking_no, ''BUYER_ID'') Buyer_Id,            ',
'         pwc_master_tracking_data_func(HederEO.tracking_no, ''BUYER_NAME'') Buyer_NAME,            ',
'         pwc_master_tracking_data_func(HederEO.tracking_no, ''STYLE_NAME'') Style_Name,            ',
'         pwc_master_tracking_data_func(HederEO.tracking_no, ''SEASON_NAME'') Season,            ',
'         HederEO.Brand,            ',
'         HederEO.tracking_no,            ',
'         HederEO.job_status,            ',
'         HederEO.Division,            ',
'         DECODE (TRANS_STATUS, ''Y'', ''Posted'', ''Not Posted'') status,            ',
'         HederEO.BALANCE_QTY,            ',
'         HederEO.PRODUCTION_QTY,            ',
'         HederEO.STN,            ',
'         HederEO.HEADER_ID,            ',
'         HederEO.JOB_QUANTITY,            ',
'         HederEO.Minor_Operations,            ',
'         HederEO.Wash,            ',
'         HederEO.Color,            ',
'         HederEO.OSP_Qty,            ',
'         HederEO.Completed_Qty,            ',
'         (SELECT NAME FROM apps.HR_OPERATING_UNITS@adf WHERE ORGANIZATION_ID = HederEO.OSP_UNIT_ID) OSP_UNIT_NAME,            ',
'         HederEO.OSP_UNIT_ID,            ',
'         HederEO.DRY_REWORK_QTY,            ',
'         HederEO.PREVIOUS_COMPLETED_QTY,            ',
'         HederEO.CURRENT_PLAN_QTY,            ',
'         apps.GET_PWC_OPRETN_PLAN_DOC_DATE@adf (            ',
'                                       HederEO.COLOR,            ',
'                                       HederEO.TRACKING_NO,                                                   ',
'                                       HederEO.Wash) OPRETN_PLAN_DOC_DATE,            ',
'         (SELECT NewHeader.DOC_DATE            ',
'            FROM PWC_MFG_GWPPRODUCTION_H NewHeader            ',
'           WHERE NewHeader.HEADER_ID = HederEO.HEADER_ID)            ',
'            DOC_DATE,            ',
'          NULL CURRENT_STYLE,            ',
'          NULL CURRENT_SEASON,            ',
'         HederEO.BPO_ENTRY_STATUS,            ',
'        null Organic_Auth            ',
'         ,HederEO.SMV,    ',
'         HederEO.SHIFT_WPPRODUCTION,   ',
'         nvl((select distinct ''Y''    ',
'                    from PWC_MFG_GWPPRODUCTION_BPO_PROD prod, PWC_ISSUE_REC_WASH_DEL_L delv    ',
'                    where prod.prod_trans_id = HederEO.PROD_TRANS_ID   ',
'                    and nvl(prod.DRY_PROD_QTY, 0) > 0   ',
'                    and prod.BPO_LINE_NO = delv.ATTRIBUTE2), ''N'') del_save_check  , ',
'            nvl(HederEO.CURRENT_PLAN_QTY, 0) total_order_qty,  ',
'            (SELECT nvl(sum(HederEO.Completed_Qty),0)  ',
'                    FROM PWC_MFG_GWPPRODUCTION HH  ',
'                    WHERE HH.TRACKING_no = HederEO.tracking_no  ',
'                    and hh.color = HederEO.color) color_wise_total , ',
'            (nvl(HederEO.CURRENT_PLAN_QTY, 0) - ',
'            (SELECT nvl(sum(HederEO.Completed_Qty),0)  ',
'                    FROM PWC_MFG_GWPPRODUCTION HH  ',
'                    WHERE HH.TRACKING_no = HederEO.tracking_no  ',
'                    and hh.color = HederEO.color) ) total_wip_balance  ',
'    FROM PWC_MFG_GWPPRODUCTION HederEO            ',
'    WHERE  HederEO.HEADER_ID =:P82_HEADER_ID',
'    -- h.TRACKING_NO            ',
'    --  and hederEO.INVENTORY_ITEM_ID = h.INVENTORY_ITEM_ID            ',
'    -- ORDER BY HederEO.PROD_TRANS_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
