wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(158939877268985036)
,p_plug_name=>'Production_lines'
,p_parent_plug_id=>wwv_flow_imp.id(157755858444218743)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LineEO.DIVISION_ID, ',
'       LineEO.PROD_TRANS_ID, ----fk',
'       LineEO.OUT_SUBLINE_ID, -----pk',
'       LineEO.PRSNO, ',
'       LineEO.OPERATION_ID, ',
'       LineEO.PRODUCTION_QTY, ',
'       LineEO.LAST_UPDATE_DATE, ',
'       LineEO.LAST_UPDATED_BY, ',
'       LineEO.CREATION_DATE, ',
'       LineEO.CREATED_BY, ',
'       LineEO.PARENT_OPR_ID, ',
'       LineEO.WASH_DEPT_ID, ',
'       LineEO.Size_Id, ',
'       LineEO.Minor_Operation, ',
'       LineEO.Major_Operation, ',
'       LineEO.Insem, ',
'       LineEO.Shift, ',
'       LineEO.Machine, ',
'       LineEO.Operator, ',
'       LineEO.No_Of_Batches, ',
'       LineEO.Workinng_Hours, ',
'       LineEO.Actual_Hours, ',
'       LineEO.INSEAM_ID, ',
'       '''' PARENT_OPR_ID_DI, ',
'       '''' ACTUAL_RECEIVED, ',
'       '''' PREVIOUS_RECEIVED, ',
'       '''' BALANCE, ',
'       '''' CURRENT_BALANCE, ',
'       '''' TOTAL_PROCESS_BALANCE, ',
'       (select v.OPERATION_DESCRIPTION ',
'          from apps.BOM_STANDARD_OPERATIONS_V@adf v ',
'         where v.STANDARD_OPERATION_ID = LineEO.PARENT_OPR_ID) OPERATION_DESC, ',
'       (select wp.QUANTITY_IN_QUEUE ',
'          from APPS.wip_operations_v@ADF          wp, ',
'               APPS.wip_discrete_jobs_v@ADF       wdj, ',
'               apps.BOM_STANDARD_OPERATIONS_V@ADF v, ',
'               PWC_MFG_GWPPRODUCTION     h ',
'         where wp.WIP_ENTITY_ID = wdj.WIP_ENTITY_ID ',
'           and wp.ORGANIZATION_ID = wdj.ORGANIZATION_ID ',
'           and v.STANDARD_OPERATION_ID = wp.STANDARD_OPERATION_ID ',
'           and wdj.WIP_ENTITY_ID = H.JOB_ID ',
'           AND LineEO.PROD_TRANS_ID = H.PROD_TRANS_ID ',
'           and LineEO.PARENT_OPR_ID = wp.STANDARD_OPERATION_ID) Queue_qty, ',
'       (select wp.QUANTITY_WAITING_TO_MOVE ',
'          from APPS.wip_operations_v@ADF          wp, ',
'               APPS.wip_discrete_jobs_v@ADF       wdj, ',
'               APPS.BOM_STANDARD_OPERATIONS_V@ADF v, ',
'               PWC_MFG_GWPPRODUCTION     h ',
'         where wp.WIP_ENTITY_ID = wdj.WIP_ENTITY_ID ',
'           and wp.ORGANIZATION_ID = wdj.ORGANIZATION_ID ',
'           and v.STANDARD_OPERATION_ID = wp.STANDARD_OPERATION_ID ',
'           and wdj.WIP_ENTITY_ID = H.JOB_ID ',
'           AND LineEO.PROD_TRANS_ID = H.PROD_TRANS_ID ',
'           and LineEO.PARENT_OPR_ID = wp.STANDARD_OPERATION_ID) to_move, ',
'       LineEO.to_minor_operation, ',
' LineEO.To_Major_Operation, ',
'       LineEO.From_Step, ',
'       LineEO.To_Step, ',
'       LineEO.Efficiency, ',
'       LineEO.Balanceqty, ',
'       LineEO.TO_MAJOR_OPERATION_ID, ',
'       LineEO.Remarks, ',
'       LineEO.Balance_Before, ',
'       (select v.OPERATION_DESCRIPTION ',
'          from APPS.BOM_STANDARD_OPERATIONS_V@ADF v ',
'         where v.STANDARD_OPERATION_ID = LineEO.To_Major_Operation_Id) to_operation_major, ',
'         LineEO.DESIGNATION         , ',
'         LineEO.TARGET              , ',
'         LineEO.EIGHT_NINE_AM       , ',
'         LineEO.NINE_TEN_AM         , ',
'         LineEO.TEN_ELEVEN_AM       , ',
'         LineEO.ELEVEN_TWELEEVE_AM  , ',
'         LineEO.TWELEEVE_ONE_PM     , ',
'         LineEO.ONE_TWO_PM          , ',
'         LineEO.TWO_THREE_PM        , ',
'         LineEO.THREE_FOUR_PM       , ',
'         LineEO.FOUR_FIVE_PM        , ',
'         LineEO.FIVE_SIX_PM         , ',
'         LineEO.SIX_SEVEN_PM        , ',
'         LineEO.SEVEN_EIGHT_PM      , ',
'         LineEO.TOTAL          , ',
'         LineEO.minor_operations      , ',
'         LineEO.operator_id, ',
'          LineEO.WORKING_HOUR, ',
'           LineEO.OVERTIME ',
'  FROM PWC_MFG_GWPPRODUCTION_LINE LineEO'))
,p_plug_source_type=>'NATIVE_IG'
,p_master_region_id=>wwv_flow_imp.id(157755858444218743)
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Production_lines'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
