wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(157870063657090307)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Production'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_HEADER     NUMBER;',
'    V_DOC_NO     VARCHAR2(50);',
'    V_SEQ        NUMBER;',
'BEGIN',
'',
'    -- ================= TRY UPDATE =================',
'    IF :P82_HEADER_ID IS NOT NULL THEN',
'',
'        UPDATE PWC_MFG_GWPPRODUCTION_H',
'        SET ',
'            DIVISION_ID      = :P82_DIVISION_ID,',
'            DOC_DATE         = :P82_DOC_DATE,',
'            SHIFT            = :P82_SHIFT,',
'            REMARKS          = :P82_REMARKS,',
'            LAST_UPDATE_DATE = :P82_LAST_UPDATE_DATE,',
'            LAST_UPDATED_BY  = :P82_LAST_UPDATED_BY,',
'            DIVISION         = :P82_DIVISION',
'        WHERE HEADER_ID = :P82_HEADER_ID;',
'',
'        IF SQL%ROWCOUNT > 0 THEN',
'            apex_debug.message(''UPDATE SUCCESS'');',
'            RETURN;',
'        END IF;',
'',
'    END IF;',
'',
'',
'    -- ================= INSERT =================',
'',
'    -- HEADER_ID generate',
'    SELECT NVL(MAX(HEADER_ID),0) + 1',
'    INTO V_HEADER',
'    FROM PWC_MFG_GWPPRODUCTION_H;',
'',
'    :P82_HEADER_ID := V_HEADER;',
'',
'',
'    -- ================= DOC_NUMBER GENERATE =================',
'    SELECT NVL(MAX(TO_NUMBER(REGEXP_SUBSTR(DOC_NUMBER, ''[^/]+$'', 1, 1))),0) + 1',
'    INTO V_SEQ',
'    FROM PWC_MFG_GWPPRODUCTION_H',
'    WHERE REGEXP_LIKE(DOC_NUMBER, ''^\d{4}/\d+$'')',
'      AND SUBSTR(DOC_NUMBER,1,4) = TO_CHAR(SYSDATE,''YYYY'');',
'',
'    V_DOC_NO := TO_CHAR(SYSDATE,''YYYY'') || ''/'' || V_SEQ;',
'',
'    :P82_DOC_NUMBER := V_DOC_NO;',
'',
'',
'    -- ================= INSERT =================',
'    INSERT INTO PWC_MFG_GWPPRODUCTION_H ',
'    (',
'        DIVISION_ID,',
'        HEADER_ID,',
'        DOC_NUMBER,',
'        DOC_DATE,',
'        SHIFT,',
'        REMARKS,',
'        LAST_UPDATE_DATE,',
'        LAST_UPDATED_BY,',
'        CREATION_DATE,',
'        CREATED_BY,',
'        DIVISION',
'    )',
'    VALUES (',
'        NVL(:P82_DIVISION_ID,85),',
'        :P82_HEADER_ID,',
'        V_DOC_NO,',
'        :P82_DOC_DATE,',
'        :P82_SHIFT,',
'        :P82_REMARKS,',
'        :P82_LAST_UPDATE_DATE,',
'        :P82_LAST_UPDATED_BY,',
'        :P82_CREATION_DATE,',
'        :P82_CREATED_BY,',
'        :P82_DIVISION',
'    );',
'',
'    apex_debug.message(''INSERT SUCCESS'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_error.add_error(',
'            p_message => ''Error: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>157870063657090307
);
end;
