wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162691886865701209)
,p_plug_name=>'Rec_Lines'
,p_parent_plug_id=>wwv_flow_imp.id(157919583715403646)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT wshl.HEADER_ID,',
'       wshl.LINE_ID,',
'       wshl.RECEVING_CHALLAN_NO,',
'       wshl.RCV_FROM_WASH_DATE,',
'       wshl.WASH_RCV_QTY,',
'       wshl.MAJOR_ISSUES,',
'       wshl.ACTION_TAKEN,',
'       wshl.CURRECTION_REQ_AREA,',
'       wshl.REMARKS,',
'       wshl.ATTRIBUTE1,',
'       wshl.ATTRIBUTE2,',
'       wshl.ATTRIBUTE3,',
'       wshl.ATTRIBUTE4,',
'       wshl.ATTRIBUTE5,',
'       wshl.ATTRIBUTE6,',
'       wshl.ATTRIBUTE7,',
'       wshl.ATTRIBUTE8,',
'       wshl.ATTRIBUTE9,',
'       wshl.ATTRIBUTE10,',
'       wshl.ATTRIBUTE11,',
'       wshl.ATTRIBUTE12,',
'       wshl.ATTRIBUTE13,',
'       wshl.ATTRIBUTE14,',
'       wshl.ATTRIBUTE15,',
'       wshl.SALESORDER_ID,',
'       wshl.LAST_UPDATE_DATE,',
'       wshl.LAST_UPDATED_BY,',
'       wshl.CREATION_DATE,',
'       wshl.CREATED_BY,',
'       wshl.ORG_ID,',
'       wshl.RECEVING_DATE,',
'       wshl.WASH_EMD_PRINT_INV,',
'       wshl.WASH_TYPE,',
'       wshl.PRODUCTION_TYPE,',
'       wshl.WASH_EMD_PRINT_INVORG,',
'       wshl.ROPE_COLOR,',
'       wshl.COUNTRY,',
'       (SELECT haou.name',
'          FROM apps.hr_all_organization_units@adf haou',
'         WHERE haou.organization_id = wshl.WASH_EMD_PRINT_INV)',
'          Unit,',
'       NVL (',
'          (SELECT DISTINCT ooha.attribute12',
'             FROM apps.oe_order_headers_all@adf ooha,',
'                  apps.oe_order_lines_all@adf oola,',
'                  apps.mtl_system_items@adf msi',
'            WHERE     ooha.attribute12 IS NOT NULL',
'                  AND ooha.header_id = oola.header_id',
'                  AND msi.inventory_item_id = oola.inventory_item_id',
'                  AND msi.organization_id = ooha.org_id',
'                  AND REGEXP_SUBSTR (msi.description,',
'                                     ''[^:]+'',',
'                                     1,',
'                                     3) = wshl.ATTRIBUTE3',
'                  AND ooha.attribute4 = (SELECT h.tracking_no',
'                                           FROM PWC_MFG_ISSUE_REC_WASH_H h',
'                                          WHERE h.header_id = wshl.HEADER_ID)',
'                  AND ooha.cust_po_number = wshl.ATTRIBUTE1),',
'          wshl.ATTRIBUTE1)',
'          CURRENT_BPO,',
'       wshl.SHADE_WASH_REC,',
'       NVL ( (SELECT DISTINCT ''Y''',
'                FROM PWC_GWP_MFG_GE_OBSLINE L',
'               WHERE L.OBS_NO = wshl.ATTRIBUTE2),',
'            ''N'')',
'          rec_si_del_check',
'  FROM PWC_ISSUE_REC_WASH_REC_L wshl',
'  --where wshl.header_id=37067;'))
,p_plug_source_type=>'NATIVE_IG'
