wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(158115324758882243)
,p_plug_name=>'Delivery'
,p_parent_plug_id=>wwv_flow_imp.id(158115231623882242)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT TB1.IR_HEADER_ID,  ',
'       TB1.LINE_ID,  ',
'       TB1.QUANTITY,  ',
'       TB1.CUT_DATE,  ',
'       TB1.STITCH_PREP_DATE,  ',
'       TB1.WASHING_PLANT,  ',
'       TB1.SEND_WASH_DATE,  ',
'       TB1.SEND_BY,  ',
'       TB1.CARRIED_BY,  ',
'       TB1.DEL_CHALLAN_NO,  ',
'       TB1.REMARKS,  ',
'       TB1.ATTRIBUTE1,  ',
'       TB1.ATTRIBUTE2,  ',
'       TB1.ATTRIBUTE3,  ',
'       TB1.ATTRIBUTE4,  ',
'       TB1.ATTRIBUTE5,  ',
'       TB1.ATTRIBUTE6,  ',
'       TB1.ATTRIBUTE7,  ',
'       TB1.ATTRIBUTE8,  ',
'       TB1.ATTRIBUTE9,  ',
'       TB1.ATTRIBUTE10,  ',
'       TB1.ATTRIBUTE11,  ',
'       TB1.ATTRIBUTE12,  ',
'       TB1.ATTRIBUTE13,  ',
'       TB1.ATTRIBUTE14,  ',
'       TB1.ATTRIBUTE15,  ',
'       TB1.SALESORDER_ID,  ',
'       TB1.LAST_UPDATE_DATE,  ',
'       TB1.LAST_UPDATED_BY,  ',
'       TB1.CREATION_DATE,  ',
'       TB1.CREATED_BY,  ',
'       TB1.ORG_ID,  ',
'       TB1.CHALLAN_NO,  ',
'       TB1.WASH_TYPE,  ',
'       TB1.PRODUCTION_TYPE,  ',
'       TB1.WASH_EMD_PRINT_INV,  ',
'       TB1.ISSUANCE_DATE,  ',
'       TB1.ISSUANCE_CHALLAN_NO,  ',
'       TB1.WASH_EMD_PRINT_INVORG,  ',
'       TB1.Delivery_Date,  ',
'       TB1.TRACKING_NO,  ',
'       TB1.COUNTRY,  ',
'       TB1.ROPE_COLOR,  ',
'       pwc_master_tracking_data_func@ADF (TB1.tracking_no,''BUYER_ID'') Buyer_Id,  ',
'       pwc_master_tracking_data_func@ADF (TB1.tracking_no,''BUYER_NAME'') BUYER,  ',
'       pwc_master_tracking_data_func@ADF (TB1.tracking_no, ''STYLE_NAME'') STYLE,  ',
'       pwc_master_tracking_data_func (TB1.tracking_no, ''SEASON_NAME'')  SEASON,  ',
'       NULL Current_Style,  ',
'       NULL Current_Season,  ',
'       NVL (  ',
'          (SELECT DISTINCT ooha.attribute12  ',
'             FROM APPS.oe_order_headers_all@ADF ooha,  ',
'                  APPS.oe_order_lines_all@ADF oola,  ',
'                  APPS.mtl_system_items@ADF msi  ',
'            WHERE     ooha.attribute12 IS NOT NULL  ',
'                  AND ooha.header_id = oola.header_id  ',
'                  AND msi.inventory_item_id = oola.inventory_item_id  ',
'                  AND msi.organization_id = ooha.org_id  ',
'                  AND ooha.cust_po_number =  ',
'                         TB1.ATTRIBUTE1  ',
'                  AND ooha.attribute4 =  ',
'                         TB1.tracking_no  ',
'                  AND REGEXP_SUBSTR (msi.description,  ',
'                                     ''[^:]+'',  ',
'                                     1,  ',
'                                     3) =  ',
'                         TB1.ATTRIBUTE3),  ',
'          TB1.ATTRIBUTE1)  ',
'          CURRENT_BPO,  ',
'    NULL  ',
'          ORGANIC_AUTH, ',
'          nvl((select distinct ''Y''      ',
'                    from PWC_MFG_GWPPRODUCTION dtrk,      ',
'                         PWC_MFG_GWPPRODUCTION_BPO_PROD dbpo      ',
'                    where dtrk.tracking_no = TB1.tracking_no       ',
'                    and substr(dbpo.BPO_LINE_NO, 1, length(TB1.ATTRIBUTE1)) = TB1.ATTRIBUTE1      ',
'                    and dtrk.PROD_TRANS_ID = dbpo.PROD_TRANS_ID   ',
'                    union     ',
'               select distinct ''Y''    ',
'                    from PWC_MFG_GWPPROD_WET_D wtrk,    ',
'                         PWC_MFG_GWPPROD_WET_BPO_PROD wbpo     ',
'                    where wtrk.TRACKING_NO = TB1.tracking_no    ',
'                    and substr(wbpo.BPO_LINE_NO, 1, length(TB1.ATTRIBUTE1)) = TB1.ATTRIBUTE1    ',
'                    and wtrk.WET_D_TRANS_ID = wbpo.WET_D_TRANS_ID), ''N'') prod_si_upd_check  ',
'  FROM PWC_ISSUE_REC_WASH_DEL_L TB1',
'  WHERE TB1.IR_HEADER_ID=:P84_IR_HEADER_ID',
'',
'  '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P84_IR_HEADER_ID'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Delivery'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
end;
