wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(158084585925855961)
,p_plug_name=>'Wash Receive & Delivery'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'   ',
'  SELECT newheadereo.ir_header_id,    ',
'         newheadereo.process_detail_id,    ',
'         newheadereo.receive_no,    ',
'         newheadereo.document_date,    ',
'         newheadereo.created_by,    ',
'         newheadereo.creation_date,    ',
'         newheadereo.last_updated_by,    ',
'         newheadereo.last_update_date,    ',
'         newheadereo.resp_id,    ',
'         newheadereo.resp_appl_id,    ',
'         newheadereo.org_id,    ',
'         newheadereo.unit_name,    ',
'         newheadereo.receipt_challan_no,    ',
'         newheadereo.remarks,    ',
'         newheadereo.master_challan_no,    ',
'         newheadereo.master_challan_date,    ',
'        PWC_WASH_DELIVERY_FUNC(''DEL_TRACKING_NO'', newheadereo.ir_header_id) del_tracking_no,    ',
'        PWC_WASH_DELIVERY_FUNC(''TRACKING_NO'', newheadereo.ir_header_id) tracking_no,    ',
'        PWC_WASH_DELIVERY_FUNC(''BUYER_NAME'', newheadereo.ir_header_id) buyer_name,    ',
'        PWC_WASH_DELIVERY_FUNC(''STYLE'', newheadereo.ir_header_id) style,    ',
'        PWC_WASH_DELIVERY_FUNC(''SEASON'', newheadereo.ir_header_id) season,    ',
'        PWC_WASH_DELIVERY_FUNC(''STN'', newheadereo.ir_header_id)stn,    ',
'         newheadereo.delivery_date,    ',
'         newheadereo.unit,    ',
'         newheadereo.unit_id,',
'        PWC_WASH_DELIVERY_FUNC(''RECEIPT_CHALLAN_NO_H'', newheadereo.ir_header_id) receipt_challan_no_h,    ',
'        PWC_WASH_DELIVERY_FUNC(''DELIVERY_CHALLAN_NO'', newheadereo.ir_header_id) delivery_challan_no,    ',
'        PWC_WASH_DELIVERY_FUNC(''UNIT_H'', newheadereo.ir_header_id) unit_h,    ',
'        PWC_WASH_DELIVERY_FUNC(''RECEIPT_COLOR_H'', newheadereo.ir_header_id) receipt_color_h,    ',
'        PWC_WASH_DELIVERY_FUNC(''DELIVERY_COLOR'', newheadereo.ir_header_id) delivery_color    ',
'    FROM pwc_mfg_wash_ir_h newheadereo    ',
'   --WHERE newheadereo.org_id = 85--:p_org   ',
'   --and (:Doc is null or :Doc is not null)  ',
'ORDER BY newheadereo.ir_header_id DESC'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
