wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158100710647855987)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Wash Receive & Delivery'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_IR_HEADER_ID NUMBER;',
'    v_RECEIVE_NO   VARCHAR2(50);',
'    v_seq_no       NUMBER;',
'    v_user_id       NUMBER;',
'BEGIN',
'    -- Generate IR_HEADER_ID',
'    SELECT NVL(MAX(IR_HEADER_ID),0) + 1',
'    INTO V_IR_HEADER_ID ',
'    FROM pwc_mfg_wash_ir_h;',
'',
'    -- Generate running number (last part)',
'    SELECT NVL(MAX(TO_NUMBER(SUBSTR(RECEIVE_NO, INSTR(RECEIVE_NO,''/'')+1))),0) + 1',
'    INTO v_seq_no',
'    FROM pwc_mfg_wash_ir_h',
'    WHERE SUBSTR(RECEIVE_NO,1,4) = TO_CHAR(SYSDATE,''YYYY'');',
'',
'    -- Generate RECEIVE_NO like 2025/3262',
'    v_RECEIVE_NO := TO_CHAR(SYSDATE,''YYYY'') || ''/'' || v_seq_no;',
'',
'    -- Assign to page items',
'    :P84_RECEIVE_NO := v_RECEIVE_NO;',
'    :P84_IR_HEADER_ID := V_IR_HEADER_ID;',
'  /* Get APEX User ID */',
'   BEGIN',
'      SELECT user_id',
'        INTO v_user_id',
'        FROM APEX_230200.WWV_FLOW_USERS',
'       WHERE user_name = :APP_USER;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         v_user_id := NULL;',
'   END;',
'',
'   :P84_CREATED_BY := v_user_id;',
'',
'    INSERT INTO PWC_MFG_WASH_IR_H (',
'       IR_HEADER_ID,',
'       PROCESS_DETAIL_ID,',
'       RECEIVE_NO,',
'       DOCUMENT_DATE,',
'       CREATED_BY,',
'       CREATION_DATE,',
'       LAST_UPDATED_BY,',
'       LAST_UPDATE_DATE,',
'       RESP_ID,',
'       RESP_APPL_ID,',
'       ORG_ID,',
'       UNIT_NAME,',
'       RECEIPT_CHALLAN_NO,',
'       REMARKS,',
'       MASTER_CHALLAN_NO,',
'       MASTER_CHALLAN_DATE,',
'       DELIVERY_DATE,',
'       UNIT,',
'       UNIT_ID',
'',
'    )',
'',
'    VALUES',
'    (',
'        V_IR_HEADER_ID,',
'        :P84_PROCESS_DETAIL_ID,',
'        :P84_RECEIVE_NO,',
'        :P84_DOCUMENT_DATE,',
'        v_user_id,',
'        SYSDATE,',
'        v_user_id,',
'        SYSDATE,',
'        :P84_RESP_ID,',
'        :P84_RESP_APPL_ID,',
'        NVL(:P84_ORG_ID,85),',
'        :P84_UNIT_NAME,',
'        :P84_RECEIPT_CHALLAN_NO,',
'        :P84_REMARKS,',
'        :P84_MASTER_CHALLAN_NO,',
'        :P84_MASTER_CHALLAN_DATE,',
'        :P84_DELIVERY_DATE,',
'        :P84_UNIT,',
'        :P84_UNIT_ID',
'    );',
'',
'        apex_application.g_print_success_message := ''Header ID created successfully.: '' || V_IR_HEADER_ID;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(158099586700855986)
,p_internal_uid=>158100710647855987
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158328886443305736)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(157919583715403646)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Receive'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS ',
'    WHEN ''C'' THEN',
'',
'    -- INSERT RECORD',
'    INSERT INTO PWC_MFG_ISSUE_REC_WASH_H',
'               (           ',
'                HEADER_ID, ',
'                RECEIVE_NO, ',
'                INVOICE_NO, ',
'                COLOR, ',
'                DATE_OF_GRN, ',
'                UPDATE_ON,  ',
'                ORG_ID, ',
'                HEADER_NO, ',
'                LOT_NUMBER, ',
'                ATTRIBUTE1, ',
'                ATTRIBUTE2, ',
'                ATTRIBUTE3, ',
'                ATTRIBUTE4, ',
'                ATTRIBUTE5, ',
'                ATTRIBUTE6, ',
'                ATTRIBUTE7, ',
'                ATTRIBUTE8, ',
'                ATTRIBUTE9, ',
'                ATTRIBUTE10, ',
'                ATTRIBUTE11, ',
'                ATTRIBUTE12, ',
'                ATTRIBUTE13, ',
'                ATTRIBUTE14, ',
'                ATTRIBUTE15, ',
'                SALESORDER_ID, ',
'                TRANSACTION_TYPE, ',
'                TRANSACTION, ',
'                IR_HEADER_ID, ',
'                REMARKS, ',
'                RECEIPT_CHALLAN_NO, ',
'                UNIT, ',
'                TRACKING_NO, ',
'                WASHING_PROCESS, ',
'                 CREATED_BY, ',
'                CREATION_DATE, ',
'                LAST_UPDATED_BY, ',
'                LAST_UPDATE_DATE',
'                )',
'    VALUES',
'                (',
'                :HEADER_ID,',
'                :P84_RECEIVE_NO,',
'                :INVOICE_NO, ',
'                :COLOR, ',
'                :DATE_OF_GRN, ',
'                :UPDATE_ON, ',
'                :ORG_ID, ',
'                :HEADER_NO, ',
'                :LOT_NUMBER, ',
'                :ATTRIBUTE1, ',
'                :ATTRIBUTE2, ',
'                :ATTRIBUTE3, ',
'                :ATTRIBUTE4, ',
'                :ATTRIBUTE5, ',
'                :ATTRIBUTE6, ',
'                :ATTRIBUTE7, ',
'                :ATTRIBUTE8, ',
'                :ATTRIBUTE9, ',
'                :ATTRIBUTE10, ',
'                :ATTRIBUTE11, ',
'                :ATTRIBUTE12, ',
'                :ATTRIBUTE13, ',
'                :ATTRIBUTE14, ',
'                :ATTRIBUTE15, ',
'                :SALESORDER_ID, ',
'                :TRANSACTION_TYPE, ',
'                :TRANSACTION, ',
'                :IR_HEADER_ID, ',
'                :REMARKS, ',
'                :RECEIPT_CHALLAN_NO, ',
'                :UNIT, ',
'                :TRACKING_NO, ',
'                :WASHING_PROCESS, ',
'                :CREATED_BY, ',
'                :CREATION_DATE, ',
'                :LAST_UPDATED_BY, ',
'                :LAST_UPDATE_DATE',
'                )',
'    RETURNING HEADER_ID INTO :HEADER_ID;',
'',
'    WHEN ''U'' THEN ',
'    UPDATE PWC_MFG_ISSUE_REC_WASH_H',
'    SET        ',
'        HEADER_ID           =:HEADER_ID, ',
'        RECEIVE_NO          =:RECEIVE_NO, ',
'        INVOICE_NO          =:INVOICE_NO, ',
'        COLOR               =:COLOR, ',
'        DATE_OF_GRN         =:DATE_OF_GRN, ',
'        UPDATE_ON           =:UPDATE_ON, ',
'        CREATED_BY          =:CREATED_BY, ',
'        CREATION_DATE       =:CREATION_DATE, ',
'        LAST_UPDATED_BY     =:LAST_UPDATED_BY, ',
'        LAST_UPDATE_DATE    =:LAST_UPDATE_DATE, ',
'        ORG_ID              =:ORG_ID, ',
'        HEADER_NO           =:HEADER_NO, ',
'        LOT_NUMBER          =:LOT_NUMBER, ',
'        ATTRIBUTE1          =:ATTRIBUTE1, ',
'        ATTRIBUTE2          =:ATTRIBUTE2, ',
'        ATTRIBUTE3          =:ATTRIBUTE3, ',
'        ATTRIBUTE4          =:ATTRIBUTE4, ',
'        ATTRIBUTE5          =:ATTRIBUTE5, ',
