wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(536879853313323812)
,p_plug_name=>'Cut Details'
,p_region_name=>'PLD_IG'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LineEO.CUTISSUE_LINE_ID,         ',
'       LineEO.DIVISION_ID,         ',
'       LineEO.CUTISSUE_ID,         ',
'       LineEO.REMARKS,         ',
'       LineEO.CUT_NUMBER,         ',
'       LineEO.QUANTITY,         ',
'       LineEO.ATTRIBUTE1,         ',
'       LineEO.ATTRIBUTE2,         ',
'       LineEO.ATTRIBUTE3,         ',
'       LineEO.ATTRIBUTE4,         ',
'       LineEO.ATTRIBUTE5,         ',
'       LineEO.ATTRIBUTE6,         ',
'       LineEO.ATTRIBUTE7,         ',
'       LineEO.ATTRIBUTE8,         ',
'       LineEO.ATTRIBUTE9,         ',
'       LineEO.ATTRIBUTE10,         ',
'       LineEO.ATTRIBUTE11,         ',
'       LineEO.ATTRIBUTE12,         ',
'       LineEO.ATTRIBUTE13,         ',
'       LineEO.ATTRIBUTE14,         ',
'       LineEO.ATTRIBUTE15,        ',
'       LineEO.Cut_Qty,        ',
'       LineEO.Issued_Quantity,        ',
'       LineEO.Belanc_Qty,        ',
'       LineEO.CREATED_BY,        ',
'       LineEO.CREATION_DATE,        ',
'       LineEO.LAST_UPDATE_DATE,        ',
'       LineEO.LAST_UPDATED_BY,        ',
'       LineEO.PROD_STAGE,        ',
'       LineEO.BPO_NO,        ',
'       LineEO.COUNTRY,        ',
'       LineEO.INTEGRATION_CUT_NUMBER,        ',
'       LineEO.MERGE_BPO_NO,        ',
'       LineEO.PATTERN_COUNTRY,        ',
'       LineEO.BATCH_NO,        ',
'       (SELECT DISTINCT ooha.attribute12        ',
'          FROM apps.oe_order_headers_all@adf ooha,        ',
'               apps.oe_order_lines_all@adf oola,        ',
'               apps.mtl_system_items@adf msi        ',
'         WHERE     ooha.attribute12 IS NOT NULL        ',
'               AND ooha.header_id = oola.header_id        ',
'               AND msi.inventory_item_id = oola.inventory_item_id        ',
'               AND msi.organization_id = ooha.org_id        ',
'               AND REGEXP_SUBSTR (msi.description,        ',
'                                  ''[^:]+'',        ',
'                                  1,        ',
'                                  3) =        ',
'                      (SELECT h.color        ',
'                         FROM pwc_mfg_cutissuance h        ',
'                        WHERE h.cutissue_id = LineEO.CUTISSUE_ID)        ',
'               AND ooha.attribute4 =        ',
'                      (SELECT h.tracking_no        ',
'                         FROM pwc_mfg_cutissuance h        ',
'                        WHERE h.cutissue_id = LineEO.CUTISSUE_ID)        ',
'               AND ooha.cust_po_number = LineEO.BPO_NO)        ',
'          replace_bpo,        ',
'          LineEO.COLOR,        ',
'          LineEO.STN_NO,       ',
'          LineEO.line_NO,       ',
'          nvl((select distinct ''Y''        ',
'                    from PWC_MFG_CUTISSUANCE cm,       ',
'                         PWC_MFG_CUTISSUANCE_LINE cml       ',
'                    where cm.CUTISSUE_ID  = cml.CUTISSUE_ID       ',
'                    and cm.ISSUE_TO = ''Issued to Sewing''--''Receive from Cutting''       ',
'                    and cml.bpo_no = LineEO.BPO_NO     ',
'                    and cm.tracking_no = (select max(tracking_no) from PWC_MFG_LINEOUTPUT_SBLINE ccl where ccl.BPO_NO = LineEO.BPO_NO     ',
'                   AND ccl.COLOR = LineEO.COLOR)  ), ''N'') del_bndl_check ,    ',
'            (SELECT DISTINCT INTEGRATION_LAY_NUMBER       ',
'                   FROM pwc_mfg_ratioplan_plycfline       ',
'                  WHERE cut_no = LineEO.ATTRIBUTE1)  LAY_NUMBER        ',
'FROM PWC_MFG_CUTISSUANCE_LINE LineEO',
'where LineEO.CUTISSUE_ID = :P86_CUTISSUE_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P86_CUTISSUE_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Cut Details'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
