wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(158737651863936943)
,p_name=>'P86_ISSUE_TO'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(536501351992473619)
,p_item_source_plug_id=>wwv_flow_imp.id(536501351992473619)
,p_prompt=>'Transaction Type	'
,p_source=>'ISSUE_TO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT Issuedtostich            ',
'  FROM (SELECT 1 SEQ_TYP, ''Issued to Sewing'' Issuedtostich FROM DUAL            ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Sewing'' Issuedtostich FROM DUAL            ',
'        UNION     ',
'        SELECT 1 SEQ_TYP, ''Issued to Printing'' FROM DUAL            ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Embroidery'' FROM DUAL            ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Receive from Embroidery'' FROM DUAL           ',
'        UNION           ',
'        SELECT 2 SEQ_TYP, ''Receive from Small Parts'' FROM DUAL            ',
'        UNION           ',
'--        SELECT 1 SEQ_TYP, ''Receive from Small Parts 1'' FROM DUAL            ',
'--        UNION           ',
'--        SELECT 1 SEQ_TYP, ''Receive from Small Parts 2'' FROM DUAL            ',
'--        UNION           ',
'--        SELECT 1 SEQ_TYP, ''Receive from Small Parts 3'' FROM DUAL            ',
'--        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Small Parts'' FROM DUAL             ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Small Parts 1'' FROM DUAL             ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Small Parts 2'' FROM DUAL         ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Small Parts 3'' FROM DUAL         ',
'        UNION    ',
'        SELECT 1 SEQ_TYP, ''Issued to Small Parts 4'' FROM DUAL  ',
'        UNION    ',
'        SELECT 1 SEQ_TYP, ''Issued to Small Parts 5'' FROM DUAL         ',
'        UNION       ',
'        SELECT 1 SEQ_TYP, ''Allocation to Sample'' FROM DUAL         ',
'        UNION       ',
'        SELECT 1 SEQ_TYP, ''Allocation to Scrap'' FROM DUAL         ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Receive from Printing'' FROM DUAL             ',
'        --WHERE :p_OrgType = ''DENIM''            ',
'                    ',
'        UNION            ',
'        SELECT 2 SEQ_TYP, ''Receive from Printing'' FROM DUAL             ',
'         --WHERE :p_OrgType <> ''DENIM''            ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Issued to Third Party'' FROM DUAL where 1=2            ',
'        UNION            ',
'        SELECT 1 SEQ_TYP, ''Receive from Third Party'' FROM DUAL where 1=2            ',
'        UNION            ',
'        --SELECT 2 SEQ_TYP, ''Receive from Cutting'' FROM DUAL  20-dec-2022          ',
'        SELECT 2 SEQ_TYP, ''Receive from Small Parts'' FROM DUAL        ',
'                  ',
'        UNION            ',
'        SELECT 3 SEQ_TYP, ''Receive from Cutting for Printing'' FROM DUAL            ',
'        UNION            ',
'        SELECT 3 SEQ_TYP, ''After Printing Issue to Sewing'' FROM DUAL)            ',
' WHERE seq_typ =            ',
'             NVL (            ',
'             (SELECT DECODE (qr.character2, ''Sew'', 2, ''Print'', 3, 1)            ',
'                FROM APPS.qa_plans@ADF qp, APPS.qa_results@ADF qr, APPS.fnd_responsibility@ADF fr            ',
'               WHERE     qr.plan_id = qp.plan_id            ',
'                     AND qp.name = ''BUNDLE MOVEMENT CUT AND SEW''            ',
'                     AND qr.character1 = fr.responsibility_key            ',
'                     AND responsibility_id = 55444),            ',
'             1)'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_cMaxlength=>500
,p_begin_on_new_line=>'N'
,p_read_only_when=>'P86_CUTISSUE_ID'
,p_read_only_when_type=>'ITEM_IS_NOT_NULL'
,p_field_template=>wwv_flow_imp.id(220419589411811080)
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--stretchInputs:t-Form-fieldContainer--indicatorAsterisk:margin-top-sm'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'Y'
,p_attribute_06=>'0'
,p_attribute_08=>'300'
);
