,p_item_source_plug_id=>wwv_flow_imp.id(536501351992473619)
,p_prompt=>'Cut Plan No	'
,p_source=>'RATION_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct h.ratioplan_number      ',
'  from PWC_MFG_RATIOPLAN           h,       ',
'       --PWC_MFG_MARHER_INFO_H       hhh,       ',
'       --PWC_MFG_MARHER_INFO_L       l,       ',
'       PWC_MFG_RATIOPLAN_PLYLINE   ply,       ',
'       pwc_mfg_cutissuance ci       ',
' where h.ratioplan_id = ply.ratioplan_id       ',
'   --and hhh.header_id = l.header_id       ',
