,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(536501351992473619)
,p_item_source_plug_id=>wwv_flow_imp.id(536501351992473619)
,p_prompt=>'Receive Document No.'
,p_source=>'REC_DOC_NO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'BUNDLE_MOVEMENT_RECEIVE_DOCUMENT_NO_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 4/9/2026 9:56:46 AM (QP5 v5.215.12089.38647) */',
'SELECT MMC.CUTISSUE_NO ISSUE_DOC,',
'       DECODE (MMC.ISSUE_TO,',
'               ''Issued to Third Party'', ''Receive from Third Party'',',
'               ''Issued to Embroidery'', ''Receive from Embroidery'',',
'               ''Issued to Printing'', ''Receive from Printing'',',
'               --''Issued to Sewing'', ''Receive from Cutting'',  23-dec-2022',
'               ''Issued to Sewing'', ''Receive from Small Parts'',',
'               --''Issued to Small Parts'', ''Receive from Small Parts'',',
'               ''Issued to Small Parts 4'', ''Receive from Small Parts 4'',',
'               ''Issued to Small Parts 1'', ''Issued to Small Parts 1'',',
'               ''Issued to Small Parts 2'', ''Issued to Small Parts 2'',',
'               ''Issued to Small Parts 3'', ''Issued to Small Parts 3'',',
'               ''Issued to Small Parts 5'', ''Issued to Small Parts 5'')',
'          REC_TYPE,',
'       MMC.LINE_NO',
'  FROM PWC_MFG_CUTISSUANCE MMC',
' WHERE     :P86_SUB_TRANS_TYPE = ''DENIM''',
'       AND MMC.TRACKING_NO = :P86_TRACKING_NO',
'       AND MMC.ISSUE_TO IN',
'              (''Issued to Third Party'',',
'               ''Issued to Embroidery'',',
'               ''Issued to Printing'',',
'               ''Issued to Sewing'',',
'               --''Issued to Small Parts'', 02-01-2023',
'               ''Issued to Small Parts 1'',',
'               ''Issued to Small Parts 2'',',
'               ''Issued to Small Parts 3'',',
'               ''Issued to Small Parts 4'',',
'               ''Issued to Small Parts 5'')',
'       AND DECODE (MMC.ISSUE_TO,',
'                   ''Issued to Third Party'', ''Receive from Third Party'',',
'                   ''Issued to Embroidery'', ''Receive from Embroidery'',',
'                   ''Issued to Printing'', ''Receive from Printing'',',
'                   --''Issued to Small Parts'', ''Receive from Small Parts'' , 12-JAN-2023',
'',
'                   ''Issued to Small Parts 1'', ''Receive from Small Parts 1'',',
'                   ''Issued to Small Parts 2'', ''Receive from Small Parts 2'',',
'                   ''Issued to Small Parts 3'', ''Receive from Small Parts 3'',',
'                   ''Issued to Small Parts 4'', ''Receive from Small Parts 4'',',
'                   ''Issued to Small Parts 5'', ''Receive from Small Parts 5'',',
'                   --''Issued to Sewing'', ''Receive from Cutting'',23-dec-2022',
'                   ''Issued to Sewing'', ''Receive from Small Parts'') =',
'              :P86_ISSUE_TO',
'UNION',
'SELECT MMC.CUTISSUE_NO ISSUE_DOC,',
'       DECODE (MMC.ISSUE_TO,',
'               ''Issued to Third Party'', ''Receive from Third Party'',',
'               ''Issued to Embroidery'', ''Receive from Embroidery'',',
'               ''After Printing Issue to Sewing'', ''Receive from Printing'',',
'               ''Issued to Sewing'', ''Receive from Cutting'',',
'               ''Issued to Printing'', ''Receive from Cutting for Printing'')',
'          REC_TYPE,',
'       MMC.LINE_NO',
'  FROM PWC_MFG_CUTISSUANCE MMC',
' WHERE     :P86_SUB_TRANS_TYPE <> ''DENIM''',
'       AND MMC.TRACKING_NO = :P86_TRACKING_NO',
'       AND MMC.ISSUE_TO IN',
'              (''Issued to Third Party'',',
'               ''Issued to Embroidery'',',
'               ''Issued to Printing'',',
'               ''Issued to Sewing'',',
'               ''After Printing Issue to Sewing'')',
'       AND DECODE (MMC.ISSUE_TO,',
'                   ''Issued to Third Party'', ''Receive from Third Party'',',
'                   ''Issued to Embroidery'', ''Receive from Embroidery'',',
'                   ''After Printing Issue to Sewing'', ''Receive from Printing'',',
'                   ''Issued to Sewing'', ''Receive from Cutting'',',
'                   ''Issued to Printing'', ''Receive from Cutting for Printing'') =',
'              :P86_ISSUE_TO'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_cMaxlength=>100
,p_begin_on_new_line=>'N'
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P86_ISSUE_TO IS NULL ',
'OR UPPER(:P86_ISSUE_TO) NOT LIKE ''RECEIVE FROM %'''))
,p_read_only_when2=>'PLSQL'
,p_read_only_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(220419459940811080)
