,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cut Details - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'        -- INSERT',
'        INSERT INTO PWC_MFG_CUTISSUANCE_LINE (',
'            DIVISION_ID,',
'            CUTISSUE_ID,',
'            REMARKS,',
'            CUT_NUMBER,',
'            QUANTITY,',
'            ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5,',
'            ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10,',
'            ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15,',
'            CUT_QTY,',
'            ISSUED_QUANTITY,',
'            BELANC_QTY,',
'            PROD_STAGE,',
'            BPO_NO,',
'            COUNTRY,',
'            INTEGRATION_CUT_NUMBER,',
'            MERGE_BPO_NO,',
'            PATTERN_COUNTRY,',
'            BATCH_NO,',
'            COLOR,',
'            STN_NO,',
'            LINE_NO',
'        )',
'        VALUES (',
'            :DIVISION_ID,',
'            :CUTISSUE_ID,',
'            :REMARKS,',
'            :CUT_NUMBER,',
'            :QUANTITY,',
'            :ATTRIBUTE1, :ATTRIBUTE2, :ATTRIBUTE3, :ATTRIBUTE4, :ATTRIBUTE5,',
'            :ATTRIBUTE6, :ATTRIBUTE7, :ATTRIBUTE8, :ATTRIBUTE9, :ATTRIBUTE10,',
'            :ATTRIBUTE11, :ATTRIBUTE12, :ATTRIBUTE13, :ATTRIBUTE14, :ATTRIBUTE15,',
'            :CUT_QTY,',
'            :ISSUED_QUANTITY,',
'            :BELANC_QTY,',
'            :PROD_STAGE,',
'            :BPO_NO,',
'            :COUNTRY,',
'            :INTEGRATION_CUT_NUMBER,',
'            :MERGE_BPO_NO,',
'            :PATTERN_COUNTRY,',
'            :BATCH_NO,',
'            :COLOR,',
'            :STN_NO,',
'            :LINE_NO',
'        ) return CUTISSUE_LINE_ID into :CUTISSUE_LINE_ID;',
'',
'    ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'        -- UPDATE',
'        UPDATE PWC_MFG_CUTISSUANCE_LINE',
'        SET',
'            REMARKS = :REMARKS,                 ',
'            ISSUED_QUANTITY = :ISSUED_QUANTITY,',
'            BELANC_QTY = :BELANC_QTY,',
'            LINE_NO = :LINE_NO',
'        WHERE CUTISSUE_LINE_ID = :CUTISSUE_LINE_ID;',
'',
'    ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'        -- DELETE',
'        DELETE FROM PWC_MFG_CUTISSUANCE_LINE',
'        WHERE CUTISSUE_LINE_ID = :CUTISSUE_LINE_ID;',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>159171463192820706
);
end;
