wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(161772576394374334)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BULK_ITEMS_INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_ids VARCHAR2(4000) := apex_application.g_x01;',
'',
'    CURSOR c_data IS',
'        SELECT mmoda.final_mfg_org_id,',
'         ooha.cust_po_number bpo_no,',
'         ooha.attribute12 current_bpo,',
'         ooha.cust_po_number || ''/'' || oola.line_number stn,',
'         ooha.order_number,',
'         ooha.header_id,',
'         ooha.org_id,',
'         msib.description item_description,',
'         oola.ordered_item,',
'         SUM (oola.ordered_quantity) ordered_qty,',
'         rp.extra_cut_percent,',
'         ROUND (',
'            SUM (oola.ordered_quantity) * (1 + (rp.extra_cut_percent / 100)))',
'            extra_per,',
'         oola.inventory_item_id,',
'         TRIM (REGEXP_SUBSTR (msib.description,',
'                              ''[^:]+'',',
'                              1,',
'                              3))',
'            color,',
'         ooha.attribute4 tracking_no,',
'         TRIM (',
'            SUBSTR (',
'               msib.description,',
'               INSTR (msib.description, '':'') + 1,',
'                 INSTR (',
'                    SUBSTR (msib.description,',
'                            INSTR (msib.description, '':'') + 1),',
'                    '':'',',
'                    1,',
'                    1)',
'               - 1))',
'            wash,',
'         NULL child_style_no',
'    FROM apps.oe_order_headers_all@adf ooha,',
'         apps.oe_order_lines_all@adf oola,',
'         pwc_mfg_ratioplan rp,',
'         pwc_mfg_osp_dep_assign mmoda,',
'         pwc_mfg_osp_stn_line mmosl,',
'         pwc_mfg_osp_header mmoh,',
'         apps.mtl_system_items_b@adf msib',
'   WHERE     1 = 1',
'         AND ooha.header_id = oola.header_id',
'         AND msib.inventory_item_id = oola.inventory_item_id',
'         AND ooha.attribute4 = rp.tracking_no',
'         AND rp.tracking_no = mmoh.tracking_no',
'         AND mmoda.stn_line_id = mmosl.stn_line_id',
'         AND mmosl.header_id = mmoh.header_id',
'         AND ooha.flow_status_code IN (''ENTERED'', ''BOOKED'')',
'         AND mmosl.stn = ooha.cust_po_number || ''/'' || oola.line_number',
'         AND msib.organization_id =',
'                pwc_organization_name (''Inventory Master Org'')',
'         AND mmoda.final_department = ''Sewing''',
'         AND NVL (mmoda.sub_unit, ''N'') <> ''Y''',
'         AND mmosl.color = REGEXP_SUBSTR (msib.description,',
'                                          ''[^:]+'',',
'                                          1,',
'                                          3)',
'         AND REGEXP_SUBSTR (msib.description,',
'                            ''[^:]+'',',
'                            1,',
'                            3) = :P89_COLOR',
'         AND REGEXP_SUBSTR (msib.description,',
'                            ''[^:]+'',',
'                            1,',
'                            2) = :P89_WASH',
'         AND EXISTS',
'                (SELECT *',
'                   FROM pwc_mfg_ratioplan_stns_all bb',
'                  WHERE     1 = 1',
'                        AND rp.ratioplan_id = bb.ratioplan_id',
'                        AND ooha.cust_po_number = bb.bpo_no',
'                        AND mmosl.stn = bb.stn_no)',
'         AND EXISTS',
'                (SELECT DISTINCT 1',
'                   FROM PWC_ONT_WVN_PRECOSTING_color_l color,',
'                        PWC_ONT_WVN_PRECOSTING_L line',
'                  WHERE     color.line_id = line.line_id',
'                        AND ooha.cust_po_number = color.BPO_TBA_NO)',
'         AND ooha.attribute4 = :P89_TRACKING_NO                  --''BSA-2512-0031''',
'         AND ooha.cust_po_number NOT IN',
'                (SELECT ddd.bpo_no',
'                   FROM pwc_mfg_routing_plan_obdet ddd',
'                  WHERE header_id = NVL (:P89_HEADER_ID, 0))',
'        AND ooha.header_id IN (',
'                SELECT TO_NUMBER(REGEXP_SUBSTR(l_ids, ''[^,]+'', 1, LEVEL))',
'                FROM dual',
'                CONNECT BY REGEXP_SUBSTR(l_ids, ''[^,]+'', 1, LEVEL) IS NOT NULL',
'          )',
'GROUP BY ooha.cust_po_number,',
'         ooha.order_number,',
'         ooha.header_id,',
'         ooha.cust_po_number || ''/'' || oola.line_number,',
'         oola.ordered_item,',
'         rp.extra_cut_percent,',
'         oola.user_item_description,',
'         msib.inventory_item_id,',
'         ooha.org_id,',
'         TRIM (REGEXP_SUBSTR (msib.description,',
'                              ''[^:]+'',',
'                              1,',
'                              3)),',
'         mmoda.primary_mfg_org_id,',
'         mmoda.final_mfg_org_id,',
'         msib.description,',
'         oola.inventory_item_id,',
'         ooha.attribute4,',
'         ooha.attribute12,',
'         msib.organization_id;',
'',
'BEGIN',
'    FOR rec IN c_data LOOP',
'        INSERT INTO PWC_MFG_ROUTING_PLAN_OBDET (',
'            header_id,',
'            DIVISION_ID,',
'            OBS_REFNO,',
'            OB_QTY,',
'            PROD_TYPE,',
'            INVENTORY_ITEM_ID,',
'            bpo_no,',
'            EXTRA_CUT_PERCENT,',
'            ITEM_CODE,',
'            SALESORDER_ID,',
'            EXTRA_QTY_STITCH',
'        )',
'        VALUES (',
'            :P89_HEADER_ID,',
'            rec.org_id,',
'            rec.STN,',
'            rec.ORDERED_QTY,',
'            ''Bulk'',',
'            rec.INVENTORY_ITEM_ID,',
'            rec.bpo_no,',
'            rec.EXTRA_CUT_PERCENT,',
'            rec.ORDERED_ITEM,',
'            rec.HEADER_ID,',
'            rec.EXTRA_PER',
'        );',
'    END LOOP;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>161772576394374334
);
end;
/
