,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'            /* Formatted on 11/14/2018 2:58:25 PM (QP5 v5.215.12089.38647) */  ',
'SELECT HeaderEO.HEADER_ID,  ',
'       HeaderEO.RECEIVE_NO,  ',
'       HeaderEO.INVOICE_NO,  ',
'       HeaderEO.COLOR,  ',
'       HeaderEO.TRACKING_NO,  ',
'       pwc_master_tracking_data_func (HeaderEO.tracking_no, ''BUYER_ID'') BUYER_ID,  ',
'       pwc_master_tracking_data_func (HeaderEO.tracking_no, ''STYLE_NAME'')  ',
'          STYLE_NAME,  ',
'       pwc_master_tracking_data_func (HeaderEO.tracking_no, ''SEASON_NAME'') SEASON,  ',
'       HeaderEO.DATE_OF_GRN,  ',
'       HeaderEO.UPDATE_ON,  ',
'       HeaderEO.CREATED_BY,  ',
'       HeaderEO.CREATION_DATE,  ',
'       HeaderEO.LAST_UPDATED_BY,  ',
'       HeaderEO.LAST_UPDATE_DATE,  ',
'       HeaderEO.ORG_ID,  ',
'       HeaderEO.HEADER_NO,  ',
'       HeaderEO.LOT_NUMBER,  ',
'       HeaderEO.ATTRIBUTE1,  ',
'       HeaderEO.ATTRIBUTE2,  ',
'       HeaderEO.ATTRIBUTE3,  ',
'       HeaderEO.ATTRIBUTE4,  ',
'       HeaderEO.ATTRIBUTE5,  ',
'       HeaderEO.ATTRIBUTE6,  ',
'       HeaderEO.ATTRIBUTE7,  ',
'       HeaderEO.ATTRIBUTE8,  ',
'       HeaderEO.ATTRIBUTE9,  ',
'       HeaderEO.ATTRIBUTE10,  ',
'       HeaderEO.ATTRIBUTE11,  ',
'       HeaderEO.ATTRIBUTE12,  ',
'       HeaderEO.ATTRIBUTE13,  ',
'       HeaderEO.ATTRIBUTE14,  ',
'       HeaderEO.ATTRIBUTE15,  ',
'       pwc_master_tracking_data_func (HeaderEO.tracking_no, ''BUYER_NAME'') buyer_name,  ',
'       HeaderEO.SALESORDER_ID,  ',
'       HeaderEO.LINE_NO,  ',
'       HeaderEO.CHILD_STYLE_NO,  ',
'       HeaderEO.STYLE_CATEGORY,  ',
'       NULL CURRENT_STYLE,  ',
'       NULL CURRENT_SEASON,  ',
'       (SELECT RTRIM (  ',
'          REGEXP_REPLACE (  ',
'                LISTAGG (LineEO.ATTRIBUTE3, ''::'')  ',
'                    WITHIN GROUP (ORDER BY LineEO.ATTRIBUTE3),  ',
'                 ''([^::]*)(::\1)+($|::)'',  ',
'                ''\1\3''),  ',
'              ''::'')  ',
'         FROM PWC_MFG_ISSUE_TO_FINISH_L LineEO  ',
'        WHERE LineEO.HEADER_ID = HeaderEO.HEADER_ID) COLOR_L,  ',
'     null ORGANIC_AUTH, ',
'     nvl((select distinct ''Y''  ',
'                from PWC_MFG_ISSUE_TO_FINISH_L l  ',
'                where l.header_id = HeaderEO.header_id), ''N'') head_upd_check  ',
'  FROM PWC_MFG_ISSUE_TO_FINISH_H HeaderEO  ',
' WHERE HeaderEO.ORG_ID = 85--:p_Org_Id'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Receive from PAD (Finishing)'
);
