,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>20
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162527885467910401)
,p_plug_name=>'Fill BPO Production Lines'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT obs_no,  ',
'       order_qty,  ',
'       received_qty,  ',
'       NVL (prev_completed_qty, 0) prev_completed_qty,  ',
'       received_qty - NVL (prev_completed_qty, 0) available_for_prod  ',
'  FROM (SELECT DISTINCT  ',
'               l.obs_no,  ',
'               l.quantity order_qty,  ',
'               l.current_plan_qty received_qty,  ',
'               (SELECT SUM (prod_d.dry_prod_qty)  ',
'                  FROM pwc_mfg_gwpproduction prod_l,  ',
'                       pwc_mfg_gwpproduction_bpo_prod prod_d  ',
'                 WHERE     prod_l.prod_trans_id = prod_d.prod_trans_id  ',
'                       AND prod_l.tracking_no = :p_tracking_no  ',
'                       AND prod_l.color = :p_color  ',
'                       AND prod_l.wash = :p_wash  ',
'                       AND prod_l.minor_operations = :p_minor_operation  ',
'                       AND prod_d.bpo_line_no = l.obs_no)  ',
'                  prev_completed_qty  ',
'          FROM pwc_gwp_mfg_gevaluation h,   ',
'               pwc_gwp_mfg_ge_obsline l,  ',
'               pwc_mfg_ratioplan rm,  ',
'               pwc_mfg_ratioplan_merge_stns mstn  ',
'         WHERE     h.gwp_ge_id = l.gwp_ge_id  ',
'               AND h.tracking_no = :p_tracking_no  ',
'               AND h.color = :P92_COLOR  ',
'               AND h.wash = :P92_WASH',
'               and rm.ratioplan_id = mstn.header_id  ',
'               and h.tracking_no = rm.tracking_no  ',
'               and l.obs_no = mstn.stn_no  ',
'               and h.color = mstn.color  ',
'               and mstn.bpo_no not like ''%::%'')  ',
'/***********************************************/  ',
'union all---scenario of merge BPO  ',
'/***********************************************/  ',
'SELECT xt.obs_no,  ',
'       xt.order_qty,  ',
'       xt.received_qty,  ',
'       NVL (xt.prev_completed_qty, 0) prev_completed_qty,  ',
'       xt.received_qty - NVL (xt.prev_completed_qty, 0) available_for_prod  ',
'  FROM (SELECT l.ATTRIBUTE2 obs_no,  ',
'               mstn.SIZE_QTY order_qty,  ',
'               to_number(l.ATTRIBUTE5) received_qty,  ',
'               (SELECT SUM (prod_d.dry_prod_qty)  ',
'                  FROM pwc_mfg_gwpproduction prod_l,  ',
'                       pwc_mfg_gwpproduction_bpo_prod prod_d  ',
'                 WHERE     prod_l.prod_trans_id = prod_d.prod_trans_id  ',
'                       AND prod_l.tracking_no = :p_tracking_no  ',
'                       AND prod_l.color = :p_color  ',
'                       --AND prod_l.wash = :p_wash  ',
'                       AND prod_l.minor_operations = :p_minor_operation  ',
'                       AND prod_d.bpo_line_no = l.ATTRIBUTE2)  ',
'                  prev_completed_qty  ',
'          FROM PWC_MFG_WASH_IR_H h,  ',
'               PWC_MFG_ISSUE_REC_WASH_H hl,  ',
'               PWC_ISSUE_REC_WASH_REC_L l,  ',
'               PWC_MFG_RATIOPLAN rm,  ',
'               PWC_MFG_RATIOPLAN_MERGE_STNS mstn  ',
'         WHERE     1=1  ',
'               --and h.RECEIVE_NO = ''2022/54''  ',
'               AND h.IR_HEADER_ID = hl.IR_HEADER_ID  ',
'               AND l.header_id = hl.header_id  ',
'               AND rm.tracking_no = hl.TRACKING_NO  ',
'               AND rm.ratioplan_id = mstn.header_id  ',
'               AND l.ATTRIBUTE1 = mstn.bpo_no  ',
'               AND l.ATTRIBUTE2 = mstn.STN_NO  ',
'               AND l.ATTRIBUTE3 = mstn.color  ',
'               and l.ATTRIBUTE1 like ''%::%''  ',
'               and hl.tracking_no = NVL(:P92_TRACKING_NO,hl.tracking_no)  ',
'               and l.attribute3 = NVL(:P92_COLOR,l.attribute3)) xt'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_page_header=>'Fill BPO Production Lines'
);
