,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select FLEX_VALUE--, ffvl.description line_description            ',
' from apps.fnd_flex_value_sets@adf ffvs, apps.fnd_flex_values_vl@adf ffvl            ',
' where ffvs.flex_value_set_id = ffvl.flex_value_set_id            ',
