'                         FROM pwc_mfg_routing_plan_line_plan sopdetails ,     ',
'                         pwc_mfg_routing_plan h              ',
'                        WHERE     sopdetails.header_id = h.header_id    ',
'                        and    h.header_id = :P93_HEADER_ID   ',
