wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(711687922298979351)
,p_plug_name=>'BPO Details'
,p_region_name=>'FI_FS'
,p_parent_plug_id=>wwv_flow_imp.id(708507529505306624)
,p_region_template_options=>'#DEFAULT#:margin-top-lg'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT pwcmfgroutingplanobdet.operation_id,     ',
'       pwcmfgroutingplanobdet.operat_obline_id,     ',
'       pwcmfgroutingplanobdet.company_id,     ',
'       pwcmfgroutingplanobdet.division_id,     ',
'       pwcmfgroutingplanobdet.plan_id,     ',
'       pwcmfgroutingplanobdet.process_id,     ',
'       pwcmfgroutingplanobdet.so_line_id,     ',
'       pwcmfgroutingplanobdet.obs_refno,     ',
'       pwcmfgroutingplanobdet.ob_qty,     ',
'       pwcmfgroutingplanobdet.job_working,     ',
'       pwcmfgroutingplanobdet.wark_area,     ',
'       pwcmfgroutingplanobdet.last_update_date,     ',
'       pwcmfgroutingplanobdet.last_updated_by,     ',
'       pwcmfgroutingplanobdet.creation_date,     ',
'       pwcmfgroutingplanobdet.created_by,     ',
'       pwcmfgroutingplanobdet.prod_type,     ',
'       pwcmfgroutingplanobdet.gohead_dt,     ',
'       pwcmfgroutingplanobdet.POST,     ',
'       pwcmfgroutingplanobdet.inventory_item_id,     ',
'       pwcmfgroutingplanobdet.extra_cut_percent,     ',
'       pwcmfgroutingplanobdet.extra_ob_qty,     ',
'       pwcmfgroutingplanobdet.job_status,     ',
'       pwcmfgroutingplanobdet.wip_entity_id,     ',
'       pwcmfgroutingplanobdet.inseam_id,     ',
'       pwcmfgroutingplanobdet.printing_status,     ',
'       pwcmfgroutingplanobdet.emb_status,     ',
'       pwcmfgroutingplanobdet.emb_no_stitch,     ',
'       pwcmfgroutingplanobdet.rec_status,     ',
'       pwcmfgroutingplanobdet.header_id,     ',
'       pwcmfgroutingplanobdet.ob_lines_id,     ',
'       pwcmfgroutingplanobdet.size_id,     ',
'       NULL extra,     ',
'       pwcmfgroutingplanobdet.item_code,     ',
'       pwcmfgroutingplanobdet.ordered_quantity,     ',
'       pwcmfgroutingplanobdet.schedule_ship_date,     ',
'       pwcmfgroutingplanobdet.country,     ',
'       pwcmfgroutingplanobdet.dcpo,     ',
'       (SELECT lk.meaning     ',
'          FROM apps.fnd_lookup_values@adf lk     ',
'         WHERE     lk.lookup_type = ''CUST_PWC_JOB_WORKING_LK''     ',
'               AND pwcmfgroutingplanobdet.job_working = lk.lookup_code)     ',
'          working_dec,     ',
'       (SELECT msib.description     ',
'          FROM apps.mtl_system_items_b@adf msib     ',
'         WHERE     msib.inventory_item_id =     ',
'                      pwcmfgroutingplanobdet.inventory_item_id     ',
'               AND msib.organization_id =     ',
'                      pwc_organization_name (''Inventory Master Org''))     ',
'          item_desc,     ',
'       pwcmfgroutingplanobdet.bpo_no,     ',
'       pwcmfgroutingplanobdet.salesorder_id,     ',
'       pwcmfgroutingplanobdet.process_error_desc,     ',
'       pwcmfgroutingplanobdet.last_operation,     ',
'       (SELECT j.wip_entity_name     ',
'          FROM apps.wip_discrete_jobs_v@adf j, pwc_mfg_routing_plan mmrp     ',
'         WHERE     mmrp.header_id = pwcmfgroutingplanobdet.header_id     ',
'               AND j.attribute2 = mmrp.tracking_no     ',
'               AND j.status_type NOT IN (7)     ',
'               and j.attribute6 = mmrp.header_id     ',
'               and j.class_code  = ''Sewing''    ',
'               AND j.attribute_category = ''Discrete Job - M6''     ',
'               AND ROWNUM = 1)     ',
'          job_name,     ',
'       pwcmfgroutingplanobdet.extra_qty_stitch,     ',
'       (SELECT DISTINCT ooha.attribute12     ',
'          FROM apps.oe_order_headers_all@adf ooha     ',
'         WHERE     ooha.attribute12 IS NOT NULL     ',
'               AND ooha.header_id = pwcmfgroutingplanobdet.salesorder_id     ',
'               AND ooha.cust_po_number = pwcmfgroutingplanobdet.bpo_no)     ',
'          replace_bpo ,   ',
'          ',
'       nvl((SELECT distinct ''Y''   ',
'          FROM apps.wip_discrete_jobs_v@adf j, pwc_mfg_routing_plan mmrp     ',
'         WHERE     mmrp.header_id = pwcmfgroutingplanobdet.header_id     ',
'               AND j.attribute2 = mmrp.tracking_no     ',
'               AND j.status_type NOT IN (7)     ',
'               and j.attribute6 = mmrp.header_id     ',
'               and j.class_code  = ''Sewing''    ',
'               AND j.attribute_category = ''Discrete Job - M6''     ',
'               AND ROWNUM = 1)   , ''N'')  ',
'          bpo_del_check     ',
'  FROM pwc_mfg_routing_plan_obdet pwcmfgroutingplanobdet',
'  where pwcmfgroutingplanobdet.header_id = :P93_HEADER_ID;     ',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P93_HEADER_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'BPO Details'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
