wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(160610902190634932)
,p_event_id=>wwv_flow_imp.id(160610813001634931)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P93_CHILD_STYLE_NO'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT mmosl.child_style_no                 ',
'  FROM pwc_mfg_osp_dep_assign mmoda,         ',
'       pwc_mfg_osp_stn_line mmosl,         ',
'       pwc_mfg_osp_header mmoh,         ',
'       pwc_mt_season_details_d d         ',
' WHERE     mmoda.stn_line_id = mmosl.stn_line_id         ',
'       AND mmosl.header_id = mmoh.header_id         ',
'       AND mmoda.final_department = ''Sewing''         ',
'       AND d.tracking_no = mmoh.tracking_no    ',
'       and mmoda.final_mfg_org_id is not null',
'       AND mmoh.tracking_no =:P93_TRACKING_NO;'))
,p_attribute_07=>'P93_TRACKING_NO'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(160611235544634935)
,p_event_id=>wwv_flow_imp.id(160610813001634931)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT ',
'        pwc_master_tracking_data_func (:P93_TRACKING_NO, ''STYLE_NAME'') ,         ',
'        pwc_master_tracking_data_func (:P93_TRACKING_NO, ''SEASON_NAME'') ,         ',
'        pwc_master_tracking_data_func (:P93_TRACKING_NO, ''BUYER_NAME'') ',
'    INTO :P93_VC_STYLE, :P93_VC_SEASON, :P93_VC_BUYER_NAME',
'    FROM DUAL;         ',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P93_VC_STYLE    := NULL;',
'        :P93_VC_SEASON  := NULL;',
'        :P93_VC_BUYER_NAME  := NULL;',
'END;'))
,p_attribute_02=>'P93_TRACKING_NO'
,p_attribute_03=>'P93_VC_BUYER_NAME,P93_VC_STYLE,P93_VC_SEASON'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
