wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(160611196116634934)
,p_event_id=>wwv_flow_imp.id(160611078122634933)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT ordered_qty,           ',
'           wash,            ',
'          inventory_item_id,             ',
'          style_category ',
'          INTO :P93_QUANTITY, :P93_WASH,:P93_INVENTORY_ITEM_ID,:P93_STYLE_CATEGORY',
'    FROM (    ',
'      ',
'    SELECT colour,            ',
'            ordered_qty,           ',
'           wash,            ',
'          inventory_item_id,             ',
'          style_category            ',
'    FROM (',
'        SELECT DISTINCT',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3)) colour,',
'            mmoda.final_mfg_org_id,',
'            ooha.sold_to_org_id,',
'            ooha.shipping_instructions,',
'            ooha.attribute4,',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,2)) wash,',
'            msib.inventory_item_id,',
'            NULL style_category,',
'            (',
'                SELECT NVL(SUM(NVL(oola.ordered_quantity,0)),0)',
'                FROM apps.oe_order_headers_all@adf ooha,',
'                     apps.oe_order_lines_all@adf oola',
'                WHERE ooha.header_id = oola.header_id',
'                  AND ooha.org_id = 85',
'                  AND ooha.attribute4 = :P93_TRACKING_NO',
'                  AND msib.inventory_item_id = oola.inventory_item_id',
'                  AND ooha.attribute3 = ''BPO''',
'                  AND ooha.flow_status_code IN (''ENTERED'')',
'            ) ordered_qty',
'        FROM apps.oe_order_headers_all@adf ooha,',
'             apps.oe_order_lines_all@adf oola,',
'             apps.mtl_system_items@adf msib,',
'             pwc_mfg_osp_dep_assign mmoda,',
'             pwc_mfg_osp_stn_line mmosl,',
'             pwc_mfg_osp_header mmoh',
'        WHERE ooha.header_id = oola.header_id',
'          AND msib.organization_id = pwc_organization_name(''Inventory Master Org'')',
'          AND msib.inventory_item_id = oola.inventory_item_id',
'          AND mmoda.stn_line_id = mmosl.stn_line_id',
'          AND mmosl.header_id = mmoh.header_id',
'          AND mmoda.final_department = ''Sewing''',
'          AND mmosl.color = TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3))',
'          AND ooha.attribute4 = mmoh.tracking_no',
'          AND mmoh.tracking_no = :P93_TRACKING_NO',
'          AND ooha.cust_po_number = mmosl.bpo',
'          AND NOT EXISTS (',
'                SELECT ''X''',
'                FROM PWC_MFG_ROUTING_PLAN fetched',
'                WHERE fetched.TRACKING_NO = mmoh.tracking_no',
'                  AND fetched.process_id = 2',
'                  AND fetched.INVENTORY_ITEM_ID = msib.inventory_item_id',
'                  AND fetched.COLOR = TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3))',
'                  AND fetched.WASH = TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,2))',
'          )',
'        GROUP BY',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3)),',
'            mmoda.final_mfg_org_id,',
'            ooha.sold_to_org_id,',
'            ooha.shipping_instructions,',
'            ooha.attribute4,',
'            msib.inventory_item_id,',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,2))',
'    ))',
'    WHERE colour = :P93_COLOR;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P93_QUANTITY    := NULL;',
'        :P93_WASH  := NULL;',
'        :P93_INVENTORY_ITEM_ID  := NULL;',
'        :P93_STYLE_CATEGORY    := NULL;',
'END;'))
,p_attribute_02=>'P93_COLOR'
,p_attribute_03=>'P93_WASH,P93_INVENTORY_ITEM_ID,P93_STYLE_CATEGORY,P93_QUANTITY'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
