wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(160611845867634941)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(711687922298979351)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BPO Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    CASE :APEX$ROW_STATUS ',
'        WHEN ''U'' THEN   -- UPDATE',
'            UPDATE pwc_mfg_routing_plan_obdet',
'               SET PROD_TYPE               = :PROD_TYPE,',
'                   GOHEAD_DT         = :GOHEAD_DT',
'                --    wark_area           = :WARK_AREA,                 ',
'                --    extra_cut_percent   = :EXTRA_CUT_PERCENT,',
'                --    extra_ob_qty        = :EXTRA_OB_QTY,',
'                --    job_status          = :JOB_STATUS,',
'                --    printing_status     = :PRINTING_STATUS,',
'                --    emb_status          = :EMB_STATUS,',
'                --    emb_no_stitch       = :EMB_NO_STITCH,',
'                --    rec_status          = :REC_STATUS,',
'                --    ordered_quantity    = :ORDERED_QUANTITY,',
'                --    schedule_ship_date  = :SCHEDULE_SHIP_DATE,',
'                --    process_error_desc  = :PROCESS_ERROR_DESC,',
'                --    last_operation      = :LAST_OPERATION,',
'                --    extra_qty_stitch    = :EXTRA_QTY_STITCH',
'             WHERE OB_LINES_ID = :OB_LINES_ID;',
'',
'        WHEN ''D'' THEN   -- DELETE',
'            DELETE FROM pwc_mfg_routing_plan_obdet',
'             WHERE OB_LINES_ID = :OB_LINES_ID;',
'',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>160611845867634941
);
