,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(708608077289209329)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Operations Detail - Save Interactive Grid Data'
,p_attribute_01=>'REGION_SOURCE'
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_attribute_08=>'Y'
