wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(161815846829959922)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch Operation Process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR c_data IS',
'        SELECT DISTINCT ',
'                        d.minor_operation,',
'                        d.major_op_id,',
'                        ROUND(d.smv, 3) smv,',
'                        d.operation_code,',
'                        d.major_operation,',
'                        d.machine_type,',
'                        l.option_no,',
'                        l.version_no,',
'                        h.tracking_no,',
'                        d.process_target_qty target,',
'                        NULL child_style_no',
'          FROM pwc_mfg_operation_master_h h,',
'               pwc_mfg_operation_master_l l,',
'               pwc_mfg_operation_master_d d',
'         WHERE h.header_id = l.header_id',
'           AND l.line_id = d.line_id',
'           AND l.dept_name = ''SEWING''',
'           AND NVL(:p_OrgType,''DENIM'') = ''DENIM''',
'           AND h.tracking_no = :P93_TRACKING_NO',
'           AND l.option_no = :P93_OPTION_NO',
'           AND l.version_no = :P93_VERSION_NO',
'',
'        UNION',
'',
'        SELECT DISTINCT ',
'                        d.minor_operation,',
'                        d.major_op_id,',
'                        ROUND(d.smv, 3) smv,',
'                        d.operation_code,',
'                        d.major_operation,',
'                        d.machine_type,',
'                        l.option_no,',
'                        l.version_no,',
'                        h.tracking_no,',
'                        d.process_target_qty target,',
'                        h.child_style_no',
'          FROM pwc_mfg_operation_master_h h,',
'               pwc_mfg_operation_master_l l,',
'               pwc_mfg_operation_master_d d',
'         WHERE h.header_id = l.header_id',
'           AND l.line_id = d.line_id',
'           AND l.dept_name = ''SEWING''',
'           AND :p_OrgType <> ''DENIM''',
'           AND h.tracking_no = :P93_TRACKING_NO',
'           AND l.option_no = :P93_OPTION_NO',
'           AND l.version_no = :P93_VERSION_NO;',
'',
'BEGIN',
'    FOR rec IN c_data LOOP',
'        ',
'        INSERT INTO PWC_MFG_ROUTING_PLAN_DET (',
'            header_id,                       ',
'            minor_operations,',
'            DPOSTED,',
