wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(159961794708094245)
,p_event_id=>wwv_flow_imp.id(159961632304094244)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var regionId = "IG_SPLIT"; ',
'var igRegion = apex.region(regionId);',
'var gridView = igRegion.widget().interactiveGrid("getViews", "grid");',
'var model = gridView.model;',
'var selectedRecords = gridView.view$.grid("getSelectedRecords");',
'',
'if (selectedRecords.length > 0) {',
'    var record = selectedRecords[0]; ',
'    var stnId  = model.getValue(record, "STN_LINE_ID");',
'    var sizeId = model.getValue(record, "SIZE_LINE_ID");',
'    var qty    = model.getValue(record, "SPLIT_QTY");',
'',
'    console.log("Step 1: Variables loaded. ID is " + stnId);',
'',
'    // Call the server',
'    apex.server.process("SPLIT_BPO", ',
'        {',
'            x01: stnId,',
'            x02: sizeId,',
'            x03: qty',
'        }, ',
'        {',
'            dataType: "text",',
'            success: function(pData) {',
'                console.log("Step 2: Server responded!");',
'                apex.message.showPageSuccess(pData);',
'                igRegion.refresh();',
'                apex.navigation.dialog.close(true); ',
'            },',
'            error: function(jqXHR, textStatus, errorThrown) {',
'                console.log("Step 3: AJAX failed", textStatus, errorThrown);',
'            }',
'        }',
'    );',
'} else {',
'    console.log("Step 0: No records selected");',
'}',
''))
);
