wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(159961812503094246)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SPLIT_BPO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_stn_line_id NUMBER := apex_application.g_x01; -- Passed from JS',
'    v_size_line_id NUMBER := apex_application.g_x02; -- Passed from JS',
'    v_split_qty    NUMBER := apex_application.g_x03; -- Passed from JS',
'BEGIN',
'',
'    -- 1. Perform the Update',
'    UPDATE PWC_MFG_OSP_STN_LINE_SIZES',
'    SET   SPLIT_QTY    = v_split_qty',
'    WHERE STN_LINE_ID = v_stn_line_id',
'    and   SIZE_LINE_ID = v_size_line_id; -- Ensure you have a WHERE clause!',
'commit;',
'    -- 2. Call the Package via DB Link',
'    ',
'    apps.pwc_mfg_osp_pkg_apex.osp_split_bpo_size_break_down@adf(',
'        v_stn_line_id,',
'        0,',
'        1225',
'    );',
'',
'    -- 3. Return success message to JavaScript',
'    htp.p(''Update Successful for ID: '' || v_stn_line_id);',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        htp.p(''Error: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>159961812503094246
);
end;
