wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(616144990968743066)
,p_plug_name=>'Fill Operations'
,p_region_name=>'SOP_Find_Operations_IG'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       mmrp.doc_number,',
'       ac.customer_name AS buyer_name,',
'       sl.style_name AS style,',
'       sd.season_name || ''.'' || sd.season_year AS season,',
'       mmrp.tracking_no,',
'       mmrp.wash,',
'       mmrp.color,',
'       mmrp.header_id,',
'       NVL(mmrp.option_no, ''-'') option_no,',
'       NVL(mmrp.version_no, ''-'') version_no,',
'       NVL(mmrp.operatin_version_no, NULL) operation_version_no',
'FROM pwc_mfg_routing_plan mmrp',
'JOIN pwc_mt_season_details_d sd ',
'     ON sd.tracking_no = mmrp.tracking_no',
'JOIN pwc_mt_style_details_l sl ',
'     ON sl.style_line_id = sd.style_line_id',
'JOIN pwc_mt_brand_details_d bd ',
'     ON bd.brand_line_id = sl.brand_line_id',
'JOIN pwc_mt_buyer_details_h bh ',
'     ON bh.header_id = bd.header_id',
'JOIN apps.ar_customers@adf ac ',
'     ON ac.customer_id = bh.buyer_id',
'WHERE mmrp.process_id = 2',
'  AND mmrp.division_id = 85',
'  AND EXISTS (',
'        SELECT 1',
'        FROM pwc_mfg_routing_plan_det mmrpd',
'        WHERE mmrp.header_id = mmrpd.header_id',
'      )',
'',
'UNION',
'',
'SELECT ',
'       mmrp.doc_number,',
'       ac.customer_name AS buyer_name,',
'       sl.style_name AS style,',
'       sd.season_name || ''.'' || sd.season_year AS season,',
'       history.tracking_no,',
'       history.wash,',
'       history.color,',
'       history.header_id,',
'       NVL(history.option_no, ''-'') option_no,',
'       NVL(history.version_no, ''-'') version_no,',
'       NVL(history.operation_version_no, NULL) operation_version_no',
'FROM pwc_stiop_plan_operations_hist history',
'JOIN pwc_mfg_routing_plan mmrp ',
'     ON mmrp.header_id = history.header_id',
'JOIN pwc_mt_season_details_d sd ',
'     ON sd.tracking_no = history.tracking_no',
'JOIN pwc_mt_style_details_l sl ',
'     ON sl.style_line_id = sd.style_line_id',
'JOIN pwc_mt_brand_details_d bd ',
'     ON bd.brand_line_id = sl.brand_line_id',
'JOIN pwc_mt_buyer_details_h bh ',
'     ON bh.header_id = bd.header_id',
'JOIN apps.ar_customers@adf ac ',
'     ON ac.customer_id = bh.buyer_id;'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Generate Purchase Order'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
,p_plug_header=>'<b>Fill Operations</b>'
);
