wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(162594869919551635)
,p_event_id=>wwv_flow_imp.id(162593316079551633)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'auto save and call ajax'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'	var region = apex.region("SOP_Find_Operations_IG");',
'	var ig = region.widget();',
'	var gridView = ig.interactiveGrid("getViews", "grid");',
'	var model = gridView.model;',
'	var selectedRecordsHeaderIdsList = gridView.getSelectedRecords()',
'    .map(r => model.getValue(r, "HEADER_ID"));',
'',
'    // console.log(''Array Length:'', selectedRecordsHeaderIdsList.length);',
'    // console.log(''Header IDs:'', selectedRecordsHeaderIdsList);',
'',
'// At least one',
'if (selectedRecordsHeaderIdsList.length === 0) {',
'    apex.message.alert("Please select at least one row.");',
'    return;',
'}',
'',
'// Only one',
'if (selectedRecordsHeaderIdsList.length > 1) {',
'    apex.message.alert("Please select only one row in Fill Operations Table.");',
'    return;',
'}',
'',
'',
'    // Ajax Call',
'    apex.server.process(',
'    "BULK_ITEMS_INSERT",',
'    { x01: selectedRecordsHeaderIdsList },',
'    {',
'        dataType: "text",  // <<< Important: plain text',
'        success: function(pData) {',
'            if (pData && pData.startsWith("ERROR")) {',
'                //apex.message.alert(''Database error has occurred.'');  // Show DB error',
'                apex.message.alert(pData);  // Show DB error',
'',
'            } else {',
'                apex.message.showPageSuccess("Items Insert Successfully.");',
'                setTimeout(function () {',
'                apex.navigation.dialog.close(true, {',
'                    success: true',
'                    });',
'                }, 1000);',
'            }',
'        },',
'        error: function(xhr, status, error) {',
'            apex.message.alert("AJAX Error: " + error);',
'        }',
'    }',
');',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(162592081584551626)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BULK_ITEMS_INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_ids VARCHAR2(4000) := apex_application.g_x01;',
'',
'    CURSOR c_data IS',
'        SELECT   mmrpd.header_id, mmrpd.op_line_id,  ',
'             NVL (mmrpd.operation_code, ''-'') operation_code,  ',
'             NVL (mmrpd.minor_operations, ''-'') minor_operations,  ',
'             NVL (mmrpd.major_operations, ''-'') major_operations,  ',
'             NVL (mmrpd.tot_time, 0) sam,  ',
'             NVL (mmrpd.machine_type, ''-'') machine_type,  ',
'             NVL (mmrpd.no_of_machines, 0) no_of_machines,  ',
'             NVL (mmrpd.MACHINE, 0) MACHINE, ',
'             NVL (mmrpd.LOT_NUMBER, 0) lot_number, ',
'             NVL (mmrpd.MACHINE_WEIGHT, 0) machine_weight, ',
'             NVL (mmrpd.LOT_SIZE, 0) lot_size, ',
'             NVL (mmrpd.target, 0) target,  ',
'             NVL (mmrp.option_no, ''-'') option_no,  ',
'             NVL (mmrp.version_no, ''-'') version_no,  ',
'             NVL (mmrp.operatin_version_no, 0) operation_version_no  ',
'        FROM pwc_mfg_routing_plan mmrp, pwc_mfg_routing_plan_det mmrpd  ',
'       WHERE mmrp.header_id = mmrpd.header_id',
'       AND   mmrpd.header_id = apex_application.g_x01;',
'',
'',
'BEGIN',
'    FOR rec IN c_data LOOP',
'        INSERT INTO PWC_MFG_ROUTING_PLAN_DET (',
'            header_id,                       ',
'            minor_operations,',
'            DPOSTED,',
'            TOT_TIME, ',
'            operation_code,',
'            major_operations,',
'            machine_type,',
'            NO_OF_MACHINES,',
'            target',
'        )',
'        VALUES (',
'            :P96_HEADER_ID,',
'            rec.minor_operations,',
'            ''N'',',
'            rec.sam,',
'            rec.operation_code,',
'            rec.major_operations,',
'            rec.machine_type,',
'            rec.NO_OF_MACHINES,',
'            rec.target',
'',
'        );',
'    END LOOP;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>162592081584551626
);
end;
