wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(872021482013516918)
,p_plug_name=>'Line Output Sub Line'
,p_region_name=>'SLO_1T_1IG'
,p_parent_plug_id=>wwv_flow_imp.id(163529469512317024)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT linevo.division_id,                 ',
'       linevo.prod_trans_id,                 ',
'       linevo.out_subline_id,                 ',
'       linevo.sno,                 ',
'       linevo.line_id,                 ',
'       linevo.subline_type,                 ',
'       linevo.no_machines,                 ',
'       linevo.subline_no,                 ',
'       linevo.operator_abs,                 ',
'       linevo.line_output,                 ',
'       linevo.target_qty,                 ',
'       linevo.balance_qty,                 ',
'       linevo.remarks,                 ',
'       linevo.last_update_date,                 ',
'       linevo.last_updated_by,                 ',
'       linevo.creation_date,                 ',
'       linevo.created_by,                 ',
'       linevo.temp_qty,                 ',
'       linevo.res_post,                 ',
'       linevo.last_update_login,                 ',
'       linevo.attribute1,                 ',
'       linevo.attribute2,                 ',
'       linevo.attribute3,                 ',
'       linevo.attribute4,                 ',
'       linevo.attribute5,                 ',
'       linevo.attribute6,                 ',
'       linevo.attribute7,                 ',
'       linevo.attribute8,                 ',
'       linevo.attribute9,                 ',
'       linevo.attribute10,                 ',
'       linevo.attribute11,                 ',
'       linevo.attribute12,                 ',
'       linevo.attribute13,                 ',
'       linevo.attribute14,                 ',
'       linevo.attribute15,                 ',
'       linevo.size_quantity,                 ',
'       linevo.prod_qty,                 ',
'       linevo.production_quantity,                 ',
'       NULL prv_lineoutput,                 ',
'       pwc_master_tracking_data_func (linevo.tracking_no, ''BUYER_ID'')                 ',
'          buyer_id,                 ',
'       linevo.bpo_no,                 ',
'       linevo.sale_order_id,                 ',
'       pwc_master_tracking_data_func (linevo.tracking_no, ''STYLE_NAME'') style,                 ',
'       pwc_master_tracking_data_func (linevo.tracking_no, ''SEASON_NAME'')                 ',
'          season,                 ',
'       linevo.job_id,                 ',
'       linevo.error_message,                 ',
'       linevo.last_action,                 ',
'       linevo.tracking_no,                 ',
'       pwc_master_tracking_data_func (linevo.tracking_no, ''BUYER_NAME'') buyer_name,                 ',
'       linevo.prod_type,                 ',
'       linevo.tot_rejection,                 ',
'       linevo.day_rejection,                 ',
'       linevo.stn_number,                 ',
'       (SELECT v.wip_entity_name                 ',
'          FROM apps.wip_discrete_jobs_v@adf v                 ',
'         WHERE v.wip_entity_id = linevo.job_id)                 ',
'          job_name,                 ',
'       linevo.day_production,                 ',
'       linevo.total_produetion,                 ',
'       linevo.total_input,                 ',
'       linevo.wip,                 ',
'       linevo.pre_lineoutput,                 ',
'       linevo.color,                 ',
'       linevo.sam,                 ',
'       linevo.prod_stage,                 ',
'       linevo.day_rework,                 ',
'       linevo.osp_production,                 ',
'       linevo.osp_unit,                 ',
'       linevo.merge_bpo_no,                 ',
'       linevo.today_forecast,                 ',
'       linevo.short_excess_production,                 ',
'       NULL current_style,                 ',
'       NULL current_season,                 ',
'       (SELECT DISTINCT ooha.attribute12                  ',
'          FROM apps.oe_order_headers_all@adf ooha                 ',
'         WHERE ooha.header_id = linevo.sale_order_id) replace_bpo,                 ',
'       linevo.child_style_no,                  ',
'       linevo.style_category,                 ',
'        (SELECT DISTINCT ''Move Transaction is in error Please Check Pending Move Transaction Form''                 ',
'            FROM apps.wip_txn_interface_errors@adf wtie, apps.wip_move_txn_interface@adf wmti                 ',
'           WHERE     wmti.transaction_id = wtie.transaction_id                 ',
'                 AND wmti.process_status = 3                 ',
'                 AND wmti.attribute14 = linevo.line_id                 ',
'                 AND wmti.attribute13 = ''AUTO MOVE TXN SEWING'')                 ',
'            move_txn_error,                 ',
'      null                 ',
'          organic_auth,                ',
'          NVL((select DISTINCT ''Y''                 ',
'                    from PWC_MFG_ISSUE_REC_WASH_H H,                ',
'                         PWC_MFG_ISSUE_REC_WASH_L_H TRK ,                ',
'                         PWC_MFG_ISSUE_REC_WASH_D BPO                ',
'                    where H.TRANSACTION_TYPE = ''Receive from Sewing''                ',
'                    --and H.receive_no = ''2022/51''                ',
'                    AND TRK.HEADER_ID = H.HEADER_ID                ',
'                    AND BPO.HEADER_ID = TRK.LINE_ID                ',
'                    AND TRK.TRACKING_NO = linevo.tracking_no                ',
'                    AND BPO.ATTRIBUTE1 = linevo.bpo_no     ',
'                    and 1=2-- 18-JAN-2023 comment for the time being on request of Hassan   ',
'                    AND BPO.ATTRIBUTE3 = linevo.COLOR), ''N'') bpo_del_check ,               ',
'           nvl((select distinct ''Y''               ',
'                    from PWC_MFG_GWPPRODUCTION dtrk,               ',
'                         PWC_MFG_GWPPRODUCTION_BPO_PROD dbpo               ',
'                    where dtrk.tracking_no = linevo.tracking_no                ',
'                    and substr(dbpo.BPO_LINE_NO, 1, length(linevo.bpo_no)) = linevo.bpo_no               ',
'                    and dtrk.PROD_TRANS_ID = dbpo.PROD_TRANS_ID      ',
'                    and dtrk.COLOR = linevo.color     ',
'                    and 1=2-- 18-JAN-2023 comment for the time being on request of Hassan        ',
'                    union              ',
'               select distinct ''Y''             ',
'                    from PWC_MFG_GWPPROD_WET_D wtrk,             ',
'                         PWC_MFG_GWPPROD_WET_BPO_PROD wbpo              ',
'                    where wtrk.TRACKING_NO = linevo.tracking_no             ',
'                    and substr(wbpo.BPO_LINE_NO, 1, length(linevo.bpo_no)) = linevo.bpo_no     ',
'                    and wtrk.COLOR_WASH = linevo.color       ',
'                    and 1=2-- 18-JAN-2023 comment for the time being on request of Hassan        ',
'                    and wtrk.WET_D_TRANS_ID = wbpo.WET_D_TRANS_ID), ''N'') prod_si_upd_check,           ',
'               nvl((select distinct ''Y''            ',
'                    from apps.mtl_material_transactions@adf            ',
'                    where organization_id = 91           ',
'                    and attribute_category = ''Job Issuance Details''           ',
'                    and attribute12 = ''Auto Issuance''           ',
'                    and attribute10 = linevo.bpo_no           ',
'                    and attribute11 = linevo.line_id), ''N'') mat_issu_check ,          ',
'            /************Total Order Qty*******************/          ',
'            (SELECT NVL (SUM (rml.totalpcs), 0)          ',
'                   FROM pwc_mfg_ratioplan rm, pwc_mfg_ratioplan_plyline rml          ',
'                  WHERE     rm.ratioplan_id = rml.ratioplan_id          ',
'                        AND rml.fg_color = linevo.color          ',
'                        AND rm.tracking_no = linevo.tracking_no)          ',
'                 total_order_qty,          ',
'             /**********Color Wise Production*************/          ',
'             (select nvl(sum(LINE_OUTPUT),0)           ',
'                from pwc_mfg_lineoutput_sbline ss          ',
'                where  ss.tracking_no = linevo.tracking_no          ',
'                and ss.color = linevo.color)Color_Wise_Production,          ',
'             /***********WIP Balance**********************/          ',
'             (SELECT NVL (SUM (rml.totalpcs), 0)          ',
'                   FROM pwc_mfg_ratioplan rm, pwc_mfg_ratioplan_plyline rml          ',
'                  WHERE     rm.ratioplan_id = rml.ratioplan_id          ',
'                        AND rml.fg_color = linevo.color          ',
'                        AND rm.tracking_no = linevo.tracking_no)-           ',
'               (select nvl(sum(LINE_OUTPUT),0)           ',
'                from pwc_mfg_lineoutput_sbline ss          ',
'                where  ss.tracking_no = linevo.tracking_no          ',
'                and ss.color = linevo.color) wip_prod_balance ,  ',
'               ( SELECT DISTINCT ''Y''  ',
'  FROM PWC_PR_PROCESS_BARCODE PRB  ',
' WHERE PRB.TRACKING_NO = linevo.tracking_no AND PRB.COLOR = linevo.COLOR    ) BAR_CODE_CHECK         ',
' FROM pwc_mfg_lineoutput_sbline linevo',
' where linevo.prod_trans_id = :P99_PROD_TRANS_ID'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P99_PROD_TRANS_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Line Output Sub Line'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
