,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT AdditionBlockEO.DIVISION_ID, ',
'       AdditionBlockEO.PROD_TRANS_ID, ',
'       AdditionBlockEO.HEADER_ID, ',
'       AdditionBlockEO.SUBLINE_NO, ',
'       AdditionBlockEO.WORKING_HOUR_BASIC, ',
'       AdditionBlockEO.MANPOWER_BASIC, ',
'       AdditionBlockEO.WORKING_HOUR_OVERTIME, ',
'       AdditionBlockEO.MANPOWER_OVERTIME, ',
'       AdditionBlockEO.WORKING_HOUR_EXTRAOT_1, ',
'       AdditionBlockEO.MAN_POWER_EXTRAOT_1, ',
'       AdditionBlockEO.WORKING_HOUR_EXTRAOT_2, ',
'       AdditionBlockEO.MAN_POWER_EXTRAOT_2, ',
'       AdditionBlockEO.ATTRIBUTE9, ',
'       AdditionBlockEO.ATTRIBUTE10, ',
'       pwc_master_tracking_data_func (AdditionBlockEO.tracking_no, ''BUYER_ID'') BUYER_ID, ',
'       pwc_master_tracking_data_func (AdditionBlockEO.tracking_no, ''SEASON_NAME'') SEASON, ',
'       pwc_master_tracking_data_func (AdditionBlockEO.tracking_no, ''STYLE_NAME'') STYLE, ',
'       AdditionBlockEO.COLOR, ',
'       pwc_master_tracking_data_func (AdditionBlockEO.tracking_no, ''BUYER_NAME'') buyer_name, ',
'       NULL CURRENT_STYLE, ',
'       NULL CURRENT_SEASON, ',
'       AdditionBlockEO.CREATION_DATE, ',
'       AdditionBlockEO.CREATED_BY, ',
'       AdditionBlockEO.TRACKING_NO, ',
'       AdditionBlockEO.TARGET_QTY, ',
'       AdditionBlockEO.LAST_UPDATED_BY, ',
'       AdditionBlockEO.LAST_UPDATE_DATE, ',
'       AdditionBlockEO.PRODUCTION_BASIC, ',
'       AdditionBlockEO.PRODUCTION_OVERTIME, ',
'       AdditionBlockEO.PRODUCTION_EXTRAOT_1, ',
'       AdditionBlockEO.PRODUCTION_EXTRAOT_2, ',
'       AdditionBlockEO.TOTAL_ATTENDED_MINS, ',
'       AdditionBlockEO.CHILD_STYLE_NO, ',
'       AdditionBlockEO.STYLE_CATEGORY, ',
'       NULL ORGANIC_AUTH ',
'  FROM PWC_MFG_LINEOUTPUT_ADDITION AdditionBlockEO',
'  where AdditionBlockEO.PROD_TRANS_ID = :P99_PROD_TRANS_ID;'))
