wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(163522531365307748)
,p_name=>'SET CHILD STYLE NO'
,p_event_sequence=>100
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P99_TRACKING_NO'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(163523066502307749)
,p_event_id=>wwv_flow_imp.id(163522531365307748)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P99_CHILD_STYLE_NO'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT mmosl.child_style_no                 ',
'  FROM pwc_mfg_osp_dep_assign mmoda,         ',
'       pwc_mfg_osp_stn_line mmosl,         ',
'       pwc_mfg_osp_header mmoh,         ',
'       pwc_mt_season_details_d d         ',
' WHERE     mmoda.stn_line_id = mmosl.stn_line_id         ',
'       AND mmosl.header_id = mmoh.header_id         ',
'       AND mmoda.final_department = ''Sewing''         ',
'       AND d.tracking_no = mmoh.tracking_no    ',
'       and mmoda.final_mfg_org_id is not null',
'       AND mmoh.tracking_no =:P99_TRACKING_NO;'))
,p_attribute_07=>'P99_TRACKING_NO'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(163523585880307749)
,p_event_id=>wwv_flow_imp.id(163522531365307748)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT ',
'        pwc_master_tracking_data_func (:P99_TRACKING_NO, ''STYLE_NAME'') ,         ',
'        pwc_master_tracking_data_func (:P99_TRACKING_NO, ''SEASON_NAME'') ,         ',
'        pwc_master_tracking_data_func (:P99_TRACKING_NO, ''BUYER_NAME'') ',
'    INTO :P99_VC_STYLE, :P99_VC_SEASON, :P99_VC_BUYER_NAME',
'    FROM DUAL;         ',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P99_VC_STYLE    := NULL;',
'        :P99_VC_SEASON  := NULL;',
'        :P99_VC_BUYER_NAME  := NULL;',
'END;'))
,p_attribute_02=>'P99_TRACKING_NO'
,p_attribute_03=>'P99_TMP_TRACKING_NO,P99_VC_STYLE,P99_VC_SEASON'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(163523920121307750)
,p_name=>'SET DEPEND VALUE'
,p_event_sequence=>110
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P99_COLOR'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(163524450259307750)
,p_event_id=>wwv_flow_imp.id(163523920121307750)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT ordered_qty,           ',
'           wash,            ',
'          inventory_item_id,             ',
'          style_category ',
'          INTO :P99_QUANTITY, :P99_WASH,:P99_INVENTORY_ITEM_ID,:P99_STYLE_CATEGORY',
'    FROM (    ',
'      ',
'    SELECT colour,            ',
'            ordered_qty,           ',
'           wash,            ',
'          inventory_item_id,             ',
'          style_category            ',
'    FROM (',
'        SELECT DISTINCT',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3)) colour,',
'            mmoda.final_mfg_org_id,',
'            ooha.sold_to_org_id,',
'            ooha.shipping_instructions,',
'            ooha.attribute4,',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,2)) wash,',
'            msib.inventory_item_id,',
'            NULL style_category,',
'            (',
'                SELECT NVL(SUM(NVL(oola.ordered_quantity,0)),0)',
'                FROM apps.oe_order_headers_all@adf ooha,',
'                     apps.oe_order_lines_all@adf oola',
'                WHERE ooha.header_id = oola.header_id',
'                  AND ooha.org_id = 85',
'                  AND ooha.attribute4 = :P99_TRACKING_NO',
'                  AND msib.inventory_item_id = oola.inventory_item_id',
'                  AND ooha.attribute3 = ''BPO''',
'                  AND ooha.flow_status_code IN (''ENTERED'')',
'            ) ordered_qty',
'        FROM apps.oe_order_headers_all@adf ooha,',
'             apps.oe_order_lines_all@adf oola,',
'             apps.mtl_system_items@adf msib,',
'             pwc_mfg_osp_dep_assign mmoda,',
'             pwc_mfg_osp_stn_line mmosl,',
'             pwc_mfg_osp_header mmoh',
'        WHERE ooha.header_id = oola.header_id',
'          AND msib.organization_id = pwc_organization_name(''Inventory Master Org'')',
'          AND msib.inventory_item_id = oola.inventory_item_id',
'          AND mmoda.stn_line_id = mmosl.stn_line_id',
'          AND mmosl.header_id = mmoh.header_id',
'          AND mmoda.final_department = ''Sewing''',
'          AND mmosl.color = TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3))',
'          AND ooha.attribute4 = mmoh.tracking_no',
'          AND mmoh.tracking_no = :P99_TRACKING_NO',
'          AND ooha.cust_po_number = mmosl.bpo',
'          AND NOT EXISTS (',
'                SELECT ''X''',
'                FROM PWC_MFG_ROUTING_PLAN fetched',
'                WHERE fetched.TRACKING_NO = mmoh.tracking_no',
'                  AND fetched.process_id = 2',
'                  AND fetched.INVENTORY_ITEM_ID = msib.inventory_item_id',
'                  AND fetched.COLOR = TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3))',
'                  AND fetched.WASH = TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,2))',
'          )',
'        GROUP BY',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,3)),',
'            mmoda.final_mfg_org_id,',
'            ooha.sold_to_org_id,',
'            ooha.shipping_instructions,',
'            ooha.attribute4,',
'            msib.inventory_item_id,',
'            TRIM(REGEXP_SUBSTR(msib.description,''[^:]+'',1,2))',
'    ))',
'    WHERE colour = :P99_COLOR;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P99_QUANTITY    := NULL;',
'        :P99_WASH  := NULL;',
'        :P99_INVENTORY_ITEM_ID  := NULL;',
'        :P99_STYLE_CATEGORY    := NULL;',
'END;'))
,p_attribute_02=>'P99_COLOR'
,p_attribute_03=>'P99_WASH,P99_INVENTORY_ITEM_ID,P99_STYLE_CATEGORY,P99_QUANTITY'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
