,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(875101327023286940)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Addition Line Output'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'        -- INSERT',
'        INSERT INTO PWC_MFG_LINEOUTPUT_ADDITION (',
'            DIVISION_ID,',
'            PROD_TRANS_ID,',
'            SUBLINE_NO,',
'            WORKING_HOUR_BASIC,',
'            MANPOWER_BASIC,',
'            WORKING_HOUR_OVERTIME,',
'            MANPOWER_OVERTIME,',
'            WORKING_HOUR_EXTRAOT_1,',
'            MAN_POWER_EXTRAOT_1,',
'            WORKING_HOUR_EXTRAOT_2,',
'            MAN_POWER_EXTRAOT_2,',
'            ATTRIBUTE9,',
'            ATTRIBUTE10,',
'            COLOR,',
'            TRACKING_NO,',
'            TARGET_QTY,',
'            PRODUCTION_BASIC,',
'            PRODUCTION_OVERTIME,',
'            PRODUCTION_EXTRAOT_1,',
'            PRODUCTION_EXTRAOT_2,',
'            TOTAL_ATTENDED_MINS,',
'            CHILD_STYLE_NO,',
'            STYLE_CATEGORY',
'        )',
'        VALUES (',
'            :DIVISION_ID,',
'            :P99_PROD_TRANS_ID,',
'            :SUBLINE_NO,',
'            :WORKING_HOUR_BASIC,',
'            :MANPOWER_BASIC,',
'            :WORKING_HOUR_OVERTIME,',
'            :MANPOWER_OVERTIME,',
'            :WORKING_HOUR_EXTRAOT_1,',
'            :MAN_POWER_EXTRAOT_1,',
'            :WORKING_HOUR_EXTRAOT_2,',
'            :MAN_POWER_EXTRAOT_2,',
'            :ATTRIBUTE9,',
'            :ATTRIBUTE10,',
'            :COLOR,',
'            :TRACKING_NO,',
'            :TARGET_QTY,',
'            :PRODUCTION_BASIC,',
'            :PRODUCTION_OVERTIME,',
'            :PRODUCTION_EXTRAOT_1,',
'            :PRODUCTION_EXTRAOT_2,',
'            :TOTAL_ATTENDED_MINS,',
'            :CHILD_STYLE_NO,',
'            :STYLE_CATEGORY',
'        ) return header_id into :header_id;',
'',
'    ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'        -- UPDATE',
'        UPDATE PWC_MFG_LINEOUTPUT_ADDITION',
'        SET',
'            SUBLINE_NO = :SUBLINE_NO,',
'            WORKING_HOUR_BASIC = :WORKING_HOUR_BASIC,',
'            MANPOWER_BASIC = :MANPOWER_BASIC,',
'            WORKING_HOUR_OVERTIME = :WORKING_HOUR_OVERTIME,',
'            MANPOWER_OVERTIME = :MANPOWER_OVERTIME,',
'            WORKING_HOUR_EXTRAOT_1 = :WORKING_HOUR_EXTRAOT_1,',
'            MAN_POWER_EXTRAOT_1 = :MAN_POWER_EXTRAOT_1,',
'            WORKING_HOUR_EXTRAOT_2 = :WORKING_HOUR_EXTRAOT_2,',
'            MAN_POWER_EXTRAOT_2 = :MAN_POWER_EXTRAOT_2,',
'            ATTRIBUTE9 = :ATTRIBUTE9,',
'            ATTRIBUTE10 = :ATTRIBUTE10,',
'            COLOR = :COLOR,',
'            TRACKING_NO = :TRACKING_NO,',
'            TARGET_QTY = :TARGET_QTY,',
'            PRODUCTION_BASIC = :PRODUCTION_BASIC,',
'            PRODUCTION_OVERTIME = :PRODUCTION_OVERTIME,',
'            PRODUCTION_EXTRAOT_1 = :PRODUCTION_EXTRAOT_1,',
'            PRODUCTION_EXTRAOT_2 = :PRODUCTION_EXTRAOT_2,',
'            TOTAL_ATTENDED_MINS = :TOTAL_ATTENDED_MINS,',
'            CHILD_STYLE_NO = :CHILD_STYLE_NO,',
'            STYLE_CATEGORY = :STYLE_CATEGORY,',
'            LAST_UPDATE_DATE = SYSDATE,',
'            LAST_UPDATED_BY = :APP_USER',
'        WHERE HEADER_ID = :HEADER_ID;',
'',
'    ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'        -- DELETE',
'        DELETE FROM PWC_MFG_LINEOUTPUT_ADDITION',
'        WHERE HEADER_ID = :HEADER_ID;',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>164204895578384314
);
