'         PwcMfgRoutingPlan.SALESORDER_ID,      ',
'         PwcMfgRoutingPlan.STYLE_ID,      ',
'         PwcMfgRoutingPlan.QUANTITY,      ',
'         PwcMfgRoutingPlan.EFFICIENCY,      ',
'         PwcMfgRoutingPlan.NO_OF_STATIONS,      ',
'         PwcMfgRoutingPlan.POSTED,      ',
'         PwcMfgRoutingPlan.ORD_REF_NO,      ',
'         PwcMfgRoutingPlan.POSTED_DT,      ',
'         PwcMfgRoutingPlan.POSTED_BY,      ',
'         PwcMfgRoutingPlan.POSTED_TERMINAL,      ',
'         PwcMfgRoutingPlan.RATES_FLAG,      ',
'         PwcMfgRoutingPlan.TARGET_PROD,      ',
'         PwcMfgRoutingPlan.REF_PLAN_ID,      ',
'         PwcMfgRoutingPlan.PAY_LINE_ID,      ',
'         PwcMfgRoutingPlan.LINE_NAME,      ',
'         PwcMfgRoutingPlan.CONTACT_PERSON,      ',
'         PwcMfgRoutingPlan.CORDINATE_PERSON,      ',
'         PwcMfgRoutingPlan.CORDINATE_DESIGNATION,      ',
'         PwcMfgRoutingPlan.CORDINATE_DESIG_ID,      ',
'         PwcMfgRoutingPlan.ACC_PROVIDED,      ',
'         PwcMfgRoutingPlan.EXP_DATE,      ',
'         PwcMfgRoutingPlan.TRANS_FLAG,      ',
'         PwcMfgRoutingPlan.DEPART_ID,      ',
'         PwcMfgRoutingPlan.FLOOR_ID,      ',
'         PwcMfgRoutingPlan.LINE_ID,      ',
'         PwcMfgRoutingPlan.LAST_UPDATE_DATE,      ',
'         PwcMfgRoutingPlan.LAST_UPDATED_BY,      ',
'         PwcMfgRoutingPlan.CREATION_DATE,      ',
'         PwcMfgRoutingPlan.CREATED_BY,      ',
'         PwcMfgRoutingPlan.VER_ID,      ',
'         PwcMfgRoutingPlan.VER_DT,      ',
'         PwcMfgRoutingPlan.REMARKS,      ',
'         PwcMfgRoutingPlan.ITEM_CODE,      ',
'         PwcMfgRoutingPlan.POST_DET_STATUS,      ',
'         PwcMfgRoutingPlan.HEADER_ID,      ',
'         PwcMfgRoutingPlan.tracking_no,      ',
'         pwc_master_tracking_data_func(PwcMfgRoutingPlan.tracking_no, ''BUYER_ID'') Customer_Id,      ',
'         pwc_master_tracking_data_func(PwcMfgRoutingPlan.tracking_no, ''STYLE_NAME'') Style,      ',
'         PwcMfgRoutingPlan.Unit,      ',
