'         PwcMfgRoutingPlan.SAM_FINISH_NEW,      ',
'         NULL CURRENT_STYLE,      ',
'         NULL CURRENT_SEASON,      ',
'         PwcMfgRoutingPlan.Wash,      ',
'         PwcMfgRoutingPlan.OPTION_NO,      ',
'         PwcMfgRoutingPlan.VERSION_NO,      ',
'         PwcMfgRoutingPlan.OPERATIN_VERSION_NO,      ',
'         PwcMfgRoutingPlan.INVENTORY_ITEM_ID,      ',
