,p_plug_name=>'Finishing Operation Plan'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PwcMfgRoutingPlan.OPERATION_ID,      ',
'         PwcMfgRoutingPlan.COMPANY_ID,      ',
'         PwcMfgRoutingPlan.DIVISION_ID,      ',
'         PwcMfgRoutingPlan.PROCESS_ID,      ',
'         PwcMfgRoutingPlan.PLAN_ID,      ',
'         PwcMfgRoutingPlan.FROM_DT,      ',
'         PwcMfgRoutingPlan.TO_DT,      ',
'         PwcMfgRoutingPlan.SALESORDER_ID,      ',
'         PwcMfgRoutingPlan.STYLE_ID,      ',
'         PwcMfgRoutingPlan.QUANTITY,      ',
'         PwcMfgRoutingPlan.EFFICIENCY,      ',
'         PwcMfgRoutingPlan.NO_OF_STATIONS,      ',
'         PwcMfgRoutingPlan.POSTED,      ',
'         PwcMfgRoutingPlan.ORD_REF_NO,      ',
'         PwcMfgRoutingPlan.POSTED_DT,      ',
'         PwcMfgRoutingPlan.POSTED_BY,      ',
'         PwcMfgRoutingPlan.POSTED_TERMINAL,      ',
'         PwcMfgRoutingPlan.RATES_FLAG,      ',
'         PwcMfgRoutingPlan.TARGET_PROD,      ',
'         PwcMfgRoutingPlan.REF_PLAN_ID,      ',
'         PwcMfgRoutingPlan.PAY_LINE_ID,      ',
'         PwcMfgRoutingPlan.LINE_NAME,      ',
'         PwcMfgRoutingPlan.CONTACT_PERSON,      ',
'         PwcMfgRoutingPlan.CORDINATE_PERSON,      ',
'         PwcMfgRoutingPlan.CORDINATE_DESIGNATION,      ',
'         PwcMfgRoutingPlan.CORDINATE_DESIG_ID,      ',
'         PwcMfgRoutingPlan.ACC_PROVIDED,      ',
'         PwcMfgRoutingPlan.EXP_DATE,      ',
'         PwcMfgRoutingPlan.TRANS_FLAG,      ',
'         PwcMfgRoutingPlan.DEPART_ID,      ',
'         PwcMfgRoutingPlan.FLOOR_ID,      ',
'         PwcMfgRoutingPlan.LINE_ID,      ',
'         PwcMfgRoutingPlan.LAST_UPDATE_DATE,      ',
'         PwcMfgRoutingPlan.LAST_UPDATED_BY,      ',
'         PwcMfgRoutingPlan.CREATION_DATE,      ',
'         PwcMfgRoutingPlan.CREATED_BY,      ',
'         PwcMfgRoutingPlan.VER_ID,      ',
'         PwcMfgRoutingPlan.VER_DT,      ',
'         PwcMfgRoutingPlan.REMARKS,      ',
'         PwcMfgRoutingPlan.ITEM_CODE,      ',
'         PwcMfgRoutingPlan.POST_DET_STATUS,      ',
'         PwcMfgRoutingPlan.HEADER_ID,      ',
'         PwcMfgRoutingPlan.tracking_no,      ',
'         pwc_master_tracking_data_func(PwcMfgRoutingPlan.tracking_no, ''BUYER_ID'') Customer_Id,      ',
'         pwc_master_tracking_data_func(PwcMfgRoutingPlan.tracking_no, ''STYLE_NAME'') Style,      ',
'         PwcMfgRoutingPlan.Unit,      ',
'         PwcMfgRoutingPlan.Color,      ',
'         pwc_master_tracking_data_func(PwcMfgRoutingPlan.tracking_no, ''SEASON_NAME'') Season,      ',
'         PwcMfgRoutingPlan.Finish_Doc_No,      ',
'         PwcMfgRoutingPlan.qty,      ',
'         (SELECT ooha.ORDER_NUMBER      ',
'            FROM apps.oe_order_headers_all@adf ooha      ',
'           WHERE PwcMfgRoutingPlan.Salesorder_Id = ooha.HEADER_ID)      ',
'            sale_order_number,      ',
'         pwc_master_tracking_data_func(PwcMfgRoutingPlan.tracking_no, ''BUYER_NAME'') Buyer_NAME,      ',
'         PwcMfgRoutingPlan.ATTRIBUTE2,      ',
'         PwcMfgRoutingPlan.ATTRIBUTE3,      ',
'         PwcMfgRoutingPlan.TOTALSAMFINISHING,      ',
'         PwcMfgRoutingPlan.SAM_FINISH,      ',
'         PwcMfgRoutingPlan.SAM_FINISH_NEW,      ',
'         NULL CURRENT_STYLE,      ',
'         NULL CURRENT_SEASON,      ',
'         PwcMfgRoutingPlan.Wash,      ',
'         PwcMfgRoutingPlan.OPTION_NO,      ',
'         PwcMfgRoutingPlan.VERSION_NO,      ',
'         PwcMfgRoutingPlan.OPERATIN_VERSION_NO,      ',
'         PwcMfgRoutingPlan.INVENTORY_ITEM_ID,      ',
'         PwcMfgRoutingPlan.CHILD_STYLE_NO,      ',
'         PwcMfgRoutingPlan.STYLE_CATEGORY,      ',
'         (SELECT fu.user_name      ',
'           FROM Apps.fnd_user@adf fu      ',
'          WHERE fu.user_id = PwcMfgRoutingPlan.CREATED_BY) CREATED_BY_USERNAME,      ',
'         null Organic_Auth, ',
'         nvl((select distinct ''Y''  ',
'                    from PWC_MFG_ROUTING_PLAN_OBDET dd  ',
'                    where dd.header_id = PwcMfgRoutingPlan.header_id), ''N'') head_upd_check  ',
'    FROM PWC_MFG_ROUTING_PLAN PwcMfgRoutingPlan      ',
'   WHERE   1=1      ',
'    and  PwcMfgRoutingPlan.process_id = 004      ',
'         AND PwcMfgRoutingPlan.DIVISION_ID = 85--:p_Org_Id ',
'         ',
'ORDER BY PwcMfgRoutingPlan.HEADER_ID DESC'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
