,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT bpo.OPERATION_ID,      ',
'       bpo.OPERAT_OBLINE_ID,      ',
'       bpo.COMPANY_ID,      ',
'       bpo.DIVISION_ID,      ',
'       bpo.PLAN_ID,      ',
'       bpo.PROCESS_ID,      ',
'       bpo.SO_LINE_ID,      ',
'       bpo.OBS_REFNO,      ',
'       bpo.OB_QTY,      ',
'       bpo.JOB_WORKING,      ',
'       bpo.WARK_AREA,      ',
'       bpo.LAST_UPDATE_DATE,      ',
'       bpo.LAST_UPDATED_BY,      ',
'       bpo.CREATION_DATE,      ',
'       bpo.CREATED_BY,      ',
'       bpo.PROD_TYPE,      ',
'       bpo.GOHEAD_DT,      ',
'       bpo.POST,      ',
'       bpo.INVENTORY_ITEM_ID,      ',
'       bpo.EXTRA_CUT_PERCENT,      ',
'       bpo.EXTRA_OB_QTY,      ',
'       bpo.JOB_STATUS,      ',
'       bpo.WIP_ENTITY_ID,      ',
'       bpo.INSEAM_ID,      ',
'       bpo.PRINTING_STATUS,      ',
'       bpo.EMB_STATUS,      ',
'       bpo.EMB_NO_STITCH,      ',
'       bpo.REC_STATUS,      ',
'       bpo.HEADER_ID,      ',
'       bpo.OB_LINES_ID,     ',
'bpo.Item_Code,     ',
'bpo.Bpo_No,     ',
'bpo.Salesorder_Id,     ',
'bpo.Process_Error_Desc,     ',
' apps.GET_PWC_JOB_NAME@adf((SELECT DISTINCT TRACKING_NO     ',
'                              FROM PWC_MFG_ROUTING_PLAN SMR     ',
'                              WHERE SMR.header_id = bpo.header_id),    ',
'                              bpo.DIVISION_ID,    ',
'                              ''Finishing'',    ',
'                              (SELECT DISTINCT color     ',
'                              FROM PWC_MFG_ROUTING_PLAN SMR     ',
'                              WHERE SMR.header_id = bpo.header_id) ,    ',
'                              (SELECT DISTINCT    ',
'                                      ATTRIBUTE1     ',
'                                    FROM apps.MTL_SYSTEM_ITEMS_KFV@adf MSIK     ',
'                                    WHERE MSIK.INVENTORY_ITEM_ID = bpo.INVENTORY_ITEM_ID) ,   ',
'                                   bpo.header_id    ',
'                              ) job_name,     ',
'       (SELECT DISTINCT ooha.attribute12     ',
