begin
wwv_flow_imp_page.create_page(
 p_id=>102
,p_name=>'Sewing Line Output 1T 2nd IG Populate Sizes Multi Select LOV'
,p_alias=>'SEWING-LINE-OUTPUT-1T-2ND-IG-POPULATE-SIZES-MULTI-SELECT-LOV'
,p_page_mode=>'MODAL'
,p_step_title=>'Populate Sizes'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_dialog_width=>'80%'
,p_dialog_chained=>'N'
,p_protection_level=>'C'
,p_page_component_map=>'21'
,p_last_updated_by=>'SABIR'
,p_last_upd_yyyymmddhh24miss=>'20260420174327'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(619185678344949698)
,p_plug_name=>'Populate Sizes'
,p_region_name=>'SOP_Insert_item_IG'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Select * from (SELECT xts.line_no,                               ',
'       xts.user_item_description,                               ',
'       xts.style,                               ',
'       xts.oc_no,                               ',
'       xts.total_qty,                               ',
'       xts.inseam_size_concat,                               ',
'       xts.inseam,                               ',
'       xts.size_qty,                               ',
'       xts.bel_qty,                               ',
'       xts.prev_rej_qty,                               ',
'       xts.total_qty - NVL (xts.bel_qty, 0) - NVL (xts.prev_rej_qty, 0) wip_qty,                               ',
'       xts.tracking_no,                               ',
'       xts.buyer_id,                               ',
'       xts.season,                               ',
'       xts.color,                               ',
'       xts.prod_stage,                               ',
'       NULL merge_bpo_no,                               ',
'       NULL child_style_no,                               ',
'       ''Normal'' transaction_type                               ',
'  FROM (  SELECT aa.line_no,                               ',
'                 aa.user_item_description,                               ',
'                 pwc_master_tracking_data_func (aa.tracking_no,                               ',
'                                                      ''STYLE_NAME'')                               ',
'                    style,                               ',
'                 aa.oc_no,                               ',
'                 (SELECT SUM (mmcdi.actual_qty)                               ',
'                    FROM pwc_mfg_cutissuance_line mmcli,                               ',
'                         pwc_mfg_cutissuance_szline mmcdi,                               ',
'                         pwc_mfg_cutissuance mmci                               ',
'                   WHERE     1 = 1                               ',
'                         AND mmci.cutissue_id = mmcli.cutissue_id                               ',
'                         AND mmci.issue_to IN                               ',
'                                (--''Receive from Small Parts'',                        ',
'                                --''Receive from Small Parts 4'',           ',
'                                ''Issued to Sewing'',           ',
'                                 ''Receive from Printing'')                               ',
'                         AND mmcli.line_no IS NOT NULL                               ',
'                         AND mmci.tracking_no = aa.tracking_no                               ',
'                         AND mmcli.bpo_no = aa.cust_po_number                               ',
'                         AND mmcdi.inseam = aa.inseam                       ',
'                         AND mmcli.color  = aa.color                      ',
'                         AND mmcli.line_no = aa.line_no                               ',
'                         AND mmcli.prod_stage = aa.prod_stage                               ',
'                         AND mmcli.cutissue_line_id = mmcdi.cutissue_line_id                               ',
'                         AND NVL (                               ',
'                                (SELECT SUBSTR (                               ',
'                                           mmcdi.siz_bnd_id,                               ',
'                                           0,                               ',
'                                           INSTR (mmcdi.siz_bnd_id, ''~'') - 1)                               ',
'                                   FROM DUAL),                               ',
'                                mmcdi.siz_bnd_id) = aa.inseam_size_concat)                               ',
'                    total_qty,                               ',
'                 aa.inseam_size_concat,                               ',
'                 aa.inseam,                               ',
'                 aa.size_qty size_qty,                               ',
'                 (SELECT   SUM (NVL (dd.cutqty, 0))                               ',
'                         + SUM (NVL (dd.osp_production_detail, 0))                               ',
'                    FROM pwc_mfg_lineoutput h,                               ',
'                         pwc_mfg_lineoutput_sbline ll,                               ',
'                         pwc_mfg_lineoutput_detail dd                               ',
'                   WHERE     h.prod_trans_id = ll.prod_trans_id                               ',
'                         AND ll.out_subline_id = dd.out_subline_id                               ',
'                         AND ll.prod_stage = aa.prod_stage                               ',
'                         AND ll.bpo_no = aa.cust_po_number                               ',
'                         AND ll.stn_number = aa.oc_no                               ',
'                         AND ll.sale_order_id = aa.header_id                               ',
'                         AND ll.division_id = aa.org_id                               ',
'                         AND ll.subline_no = aa.line_no                               ',
'                         AND dd.size_val = aa.inseam_size_concat                               ',
'                         AND dd.inseem = aa.inseam                               ',
'                         AND ll.color = aa.color                               ',
'                         AND ll.tracking_no = aa.tracking_no)                               ',
'                    bel_qty,                               ',
'                 (SELECT SUM (NVL (dd.rejection, 0))                               ',
'                    FROM pwc_mfg_lineoutput h,                               ',
'                         pwc_mfg_lineoutput_sbline ll,                               ',
'                         pwc_mfg_lineoutput_detail dd                               ',
'                   WHERE     h.prod_trans_id = ll.prod_trans_id                               ',
'                         AND ll.out_subline_id = dd.out_subline_id                               ',
'                         AND ll.prod_stage = aa.prod_stage                               ',
'                         AND ll.bpo_no = aa.cust_po_number                               ',
'                         AND ll.stn_number = aa.oc_no                               ',
'                         AND ll.sale_order_id = aa.header_id                               ',
'                         AND ll.division_id = aa.org_id                               ',
'                         AND ll.subline_no = aa.line_no                               ',
'                         AND dd.size_val = aa.inseam_size_concat                               ',
'                         AND dd.inseem = aa.inseam                               ',
'                         AND ll.color = aa.color                               ',
'                         AND ll.tracking_no = aa.tracking_no)                               ',
'                    prev_rej_qty,                               ',
'                 aa.tracking_no,                               ',
'                 pwc_master_tracking_data_func (aa.tracking_no,                               ',
'                                                      ''BUYER_ID'')                               ',
'                    buyer_id,                               ',
'                 pwc_master_tracking_data_func (aa.tracking_no,                               ',
'                                                      ''SEASON_NAME'')                               ',
'                    season,                               ',
'                 aa.color,                               ',
'                 aa.PROD_STAGE,                               ',
'                 ''Normal'' transaction_type                               ',
'            FROM (SELECT mmcl.line_no,                               ',
'                         oola.user_item_description,                               ',
'                         mmc.tracking_no,                               ',
'                         mmcl.color,                               ',
'                         ooha.cust_po_number || ''/'' || oola.line_number oc_no,                               ',
'                         size_l.SIZE_VAL inseam_size_concat,                               ',
'                         size_l.INSEAM_VAL inseam,                               ',
'                          size_l.SIZE_QUANTITY size_qty,                                                              ',
'                         ooha.cust_po_number,                               ',
'                         ooha.header_id,                               ',
'                         ooha.org_id,                               ',
'                         mmcl.PROD_STAGE                               ',
'                    FROM apps.oe_order_headers_all@adf ooha,                               ',
'                         apps.oe_order_lines_all@adf oola,                               ',
'                         pwc_mfg_cutissuance mmc,                               ',
'                         pwc_mfg_cutissuance_line mmcl,                               ',
'                         PWC_MFG_CUTISSUANCE_SZLINE mmcs,                               ',
'                         -- cust_pwc_ont_so_obinsline size_d,                               ',
'                         PWC_ONT_WVN_MASTER_BOM_GENRC_D size_l                               ',
'                   WHERE     1 = 1                               ',
'                         AND mmc.cutissue_id = mmcl.cutissue_id                               ',
'                         AND mmcl.bpo_no = ooha.cust_po_number                               ',
'                         -- AND size_l.so_obinsline_id = size_d.so_obinsline_id                               ',
'                         AND size_l.SALE_ORDER_ID = ooha.header_id                               ',
'                         AND mmc.tracking_no = ooha.attribute4                               ',
'                         AND ooha.header_id = oola.header_id                               ',
'                         AND mmcl.STN_NO not LIKE ''%::%''                            ',
'                         and ooha.cust_po_number || ''/'' || oola.line_number = size_l.bpo_line_no                           ',
'                         AND mmcs.CUTISSUE_LINE_ID = mmcl.CUTISSUE_LINE_ID                               ',
'                         AND REPLACE (mmcs.SIZ_BND_ID, ''~'', '''') =                               ',
'                                size_l.SIZE_VAL                               ',
'                         --AND mmc.issue_to = ''Receive from Cutting''                               ',
'                         AND mmcl.color = size_l.COLOUR                         ',
'                         AND mmc.issue_to IN                               ',
'                                (--''Receive from Small Parts'',                        ',
'                                ''Issued to Sewing'',                               ',
'                                 ''Receive from Printing'')                               ',
'                         --                         AND :p_OrgType = ''DENIM''                               ',
'                         AND mmcl.line_no IS NOT NULL                               ',
'                         AND (SELECT DISTINCT oopv.OU_ID                               ',
'                                FROM pwc_mfg_osp_dep_assign mmoda,                               ',
'                                     pwc_mfg_osp_stn_line mmosl,                               ',
'                                     pwc_mfg_osp_header mmoh,                               ',
'                                     inv_org_ou_pwc_v oopv                               ',
'                               WHERE     mmoda.stn_line_id = mmosl.stn_line_id                               ',
'                                     AND mmoh.header_id = mmosl.header_id                               ',
'                                     AND mmoh.tracking_no = ooha.attribute4                               ',
'                                     AND mmosl.color = mmcl.color                               ',
'                                     AND mmosl.stn =                               ',
'                                               ooha.cust_po_number                               ',
'                                            || ''/''                               ',
'                                            || oola.line_number                               ',
'                                     AND mmoda.final_department = ''Sewing''                               ',
'                                     AND mmoh.organization_id =                               ',
'                                            oopv.ORGANIZATION_ID) = :p_Org_Id                  ',
'                                                   ) aa                               ',
'        GROUP BY aa.line_no,                               ',
'                 aa.user_item_description,                               ',
'                 aa.tracking_no,                               ',
'                 aa.oc_no,                               ',
'                 aa.inseam_size_concat,                               ',
'                 aa.inseam,                               ',
'                 aa.size_qty,                               ',
'                 aa.cust_po_number,                               ',
'                 aa.header_id,                               ',
'                 aa.org_id,                               ',
'                 aa.color,                               ',
'                 aa.prod_stage) xts                   ',
'where xts.total_qty - NVL (xts.bel_qty, 0) - NVL (xts.prev_rej_qty, 0) > 0                  ',
'and  NOT EXISTS                               ',
'        (SELECT ''X''                               ',
'           FROM pwc_mfg_lineoutput_sbline bpo,                               ',
'                pwc_mfg_lineoutput_detail sizes                               ',
'          WHERE     1 = 1                              ',
'          and bpo.OUT_SUBLINE_ID = sizes.OUT_SUBLINE_ID                        ',
'                AND bpo.PROD_TRANS_ID =                               ',
'                       sizes.PROD_TRANS_ID                               ',
'                AND bpo.tracking_no =                               ',
'                       xts.tracking_no                               ',
'                AND bpo.stn_no =                               ',
'                       xts.oc_no                               ',
'                AND bpo.COLOR = xts.color                    ',
'                and bpo.SUBLINE_NO = xts.LINE_NO                   ',
'                AND sizes.SIZE_VAL =                               ',
'                       xts.inseam_size_concat                               ',
'                AND sizes.INSEEM =                               ',
'                       xts.inseam                      ',
'                       and sizes.wip = 0 )                             ',
'union all-- merge bpo scenario 21-DEC-2022                               ',
'select xtss.line_no,                               ',
'       xtss.user_item_description,                               ',
'       xtss.style,                               ',
'       xtss.oc_no,                               ',
'       xtss.total_qty,                               ',
'       xtss.inseam_size_concat,                               ',
'       xtss.inseam,                               ',
'       xtss.size_qty,                               ',
'       nvl(xtss.bel_qty,0)        ,                       ',
'       nvl(xtss.prev_rej_qty,0),                               ',
'       nvl(xtss.total_qty,0) - nvl (xtss.bel_qty, 0) - nvl (xtss.prev_rej_qty, 0) - nvl(xtss.production_feeded,0) wip_qty,                               ',
'       xtss.tracking_no,                               ',
'       xtss.buyer_id,                               ',
'       xtss.season,                               ',
'       xtss.color,                               ',
'       xtss.prod_stage,                               ',
'       xtss.merge_bpo_no,                               ',
'       null child_style_no,                               ',
'       ''Merge BPO'' transaction_type                               ',
'  from (  select aa.line_no,                               ',
'                 aa.user_item_description,                               ',
'                 pwc_master_tracking_data_func (aa.tracking_no,                               ',
'                                                      ''STYLE_NAME'')                               ',
'                    style,                               ',
'                 aa.oc_no,                               ',
'                 (select sum (mmcdi.actual_qty)                               ',
'                    from pwc_mfg_cutissuance_line mmcli,                               ',
'                         pwc_mfg_cutissuance_szline mmcdi,                               ',
'                         pwc_mfg_cutissuance mmci                               ',
'                   where     1 = 1                               ',
'                         and mmci.cutissue_id = mmcli.cutissue_id                               ',
'                         and mmci.issue_to in                               ',
'                                (''Issued to Sewing'',                              ',
'                                 ''Receive from Printing'')                               ',
'                         and mmcli.line_no is not null                               ',
'                         and mmci.tracking_no = aa.tracking_no                               ',
'                         and mmcli.bpo_no = aa.cust_po_number                               ',
'                         and mmcdi.inseam = aa.inseam                               ',
'                         and mmcli.line_no = aa.line_no                               ',
'                         and mmcli.color = aa.color                              ',
'                         and mmcli.prod_stage = aa.prod_stage                               ',
'                         and mmcli.cutissue_line_id = mmcdi.cutissue_line_id                               ',
'                   -------------UPDATED IN QUERY FOR SIZES  -30-05-2023---------------------------                ',
'                     and nvl (                               ',
'                                (select substr (                               ',
'                                           mmcdi.siz_bnd_id,                               ',
'                                           0,                               ',
'                                           instr (mmcdi.siz_bnd_id, ''~'') - 1)                               ',
'                                   from dual),                               ',
'                                mmcdi.siz_bnd_id) = aa.inseam_size_concat)                               ',
'                    total_qty,                               ',
'                 aa.inseam_size_concat,                               ',
'                 aa.inseam,                               ',
'                 aa.size_qty size_qty,                           ',
'                  PWC_SLOP_SIZEWISE_PRODUCTION(aa.tracking_no,                           ',
'                                               aa.cust_po_number,                           ',
'                                               aa.color,                           ',
'                                               aa.line_No,                           ',
'                                               aa.INSEAM,                           ',
'                                               aa.INSEAM_SIZE_CONCAT) production_feeded,                             ',
'                                            ',
'                 (select   nvl (sum(dd.cutqty), 0)                               ',
'                         + nvl (sum (dd.osp_production_detail), 0)                               ',
'                    from pwc_mfg_lineoutput h,                               ',
'                         pwc_mfg_lineoutput_sbline ll,                               ',
'                         pwc_mfg_lineoutput_detail dd                               ',
'                   where     h.prod_trans_id = ll.prod_trans_id                               ',
'                         and ll.out_subline_id = dd.out_subline_id                               ',
'                         and ll.prod_stage = aa.prod_stage                               ',
'                         and ll.bpo_no = aa.cust_po_number                               ',
'                         and ll.stn_number = aa.oc_no                               ',
'                         and ll.sale_order_id = aa.header_id                               ',
'                         and ll.division_id = aa.org_id                               ',
'                         and ll.subline_no = aa.line_no                               ',
'                         and dd.size_val = aa.inseam_size_concat                               ',
'                         and dd.inseem = aa.inseam                               ',
'                         and ll.color = aa.color                               ',
'                         and ll.tracking_no = aa.tracking_no)                               ',
'                    bel_qty,                               ',
'                 (select nvl (sum(dd.rejection), 0)                               ',
'                    from pwc_mfg_lineoutput h,                               ',
'                         pwc_mfg_lineoutput_sbline ll,                               ',
'                         pwc_mfg_lineoutput_detail dd                               ',
'                   where     h.prod_trans_id = ll.prod_trans_id                               ',
'                         and ll.out_subline_id = dd.out_subline_id                               ',
'                         and ll.prod_stage = aa.prod_stage                               ',
'                         and ll.bpo_no = aa.cust_po_number                               ',
'                         and ll.stn_number = aa.oc_no                               ',
'                         and ll.sale_order_id = aa.header_id                               ',
'                         and ll.division_id = aa.org_id                               ',
'                         and ll.subline_no = aa.line_no                               ',
'                         and dd.size_val = aa.inseam_size_concat                               ',
'                         and dd.inseem = aa.inseam                               ',
'                         and ll.color = aa.color                               ',
'                         and ll.tracking_no = aa.tracking_no)                               ',
'                    prev_rej_qty,                               ',
'                 aa.tracking_no,                               ',
'                 pwc_master_tracking_data_func (aa.tracking_no,                               ',
'                                                      ''BUYER_ID'')                               ',
'                    buyer_id,                               ',
'                 pwc_master_tracking_data_func (aa.tracking_no,                               ',
'                                                      ''SEASON_NAME'')                               ',
'                    season,                               ',
'                 aa.color,                               ',
'                 aa.prod_stage,                               ',
'                 ''Merge BPO'' transaction_type,                               ',
'                 aa.MERGE_BPO_NO||''::''     MERGE_BPO_NO                          ',
'            from (select mmcl.line_no,                               ',
'                         mmcl.stn_no user_item_description,                               ',
'                         mmc.tracking_no,                               ',
'                         mmcl.color,                               ',
'                         mmcl.stn_no oc_no,                               ',
'                         replace (mmcs.siz_bnd_id, ''~'', '''') inseam_size_concat,                               ',
'                         mmcs.INSEAM inseam,                               ',
'                            (select nvl(sum(mstns.QTY),0)                                ',
'                                    from PWC_MFG_RATIOPLAN rm,                               ',
'                                         PWC_MFG_RATIOPLAN_MERGE_STNS mstn,                               ',
'                                         PWC_MFG_RATIO_MERGE_STNS_SIZES mstns                               ',
'                                    where rm.tracking_no = mmc.tracking_no                               ',
'                                    and rm.ratioplan_id = mstn.header_id                               ',
'                                    and mstns.MERGE_STN_ID = mstn.MERGE_STN_ID                               ',
'                                    and mstn.color = mmcl.color                               ',
'                                    and mstns.SIZE_VAL = replace (mmcs.siz_bnd_id, ''~'', '''')) size_qty,                               ',
'                         mmcl.bpo_no cust_po_number,                               ',
'                         null header_id,                               ',
'                         mmc.ISSUE_TO_ORG org_id,                               ',
'                         mmcl.prod_stage,                               ',
'                         mmcl.MERGE_BPO_NO                               ',
'                    from                                ',
'                         pwc_mfg_cutissuance mmc,                               ',
'                         pwc_mfg_cutissuance_line mmcl,                               ',
'                         pwc_mfg_cutissuance_szline mmcs                               ',
'                   where     1 = 1                               ',
'                         and mmc.cutissue_id = mmcl.cutissue_id                               ',
'                         AND mmcl.STN_NO LIKE ''%::%''                           ',
'                         and ( :p_Org_Id is null or  :p_Org_Id is not null)                               ',
'                         and mmcs.cutissue_line_id = mmcl.cutissue_line_id                               ',
'                         and mmc.issue_to in                               ',
'                                (--''Receive from Small Parts'',                       ',
'                                --''Receive from Small Parts 4'',          ',
'                                ''Issued to Sewing'',          ',
'                                 ''Receive from Printing'')                               ',
'                         and mmcl.line_no is not null                 ',
'                                                   ) aa                               ',
'        group by aa.line_no,                               ',
'                 aa.tracking_no,                               ',
'                 aa.oc_no,                               ',
'                 aa.inseam_size_concat,                               ',
'                 aa.inseam,                               ',
'                 aa.size_qty,                               ',
'                 aa.cust_po_number,                               ',
'                 aa.header_id,                               ',
'                 aa.org_id,                               ',
'                 aa.color,                               ',
'                 aa.prod_stage,                               ',
'                 aa.merge_bpo_no)xtss                  ',
'where xtss.total_qty - nvl (xtss.bel_qty, 0) - nvl (xtss.prev_rej_qty, 0) - nvl(xtss.production_feeded,0) > 1                  ',
'and not exists                            ',
'        (select ''X''                               ',
'           from pwc_mfg_lineoutput_sbline bpo,                               ',
'                pwc_mfg_lineoutput_detail sizes                               ',
'          where     1 = 1                               ',
'                and bpo.OUT_SUBLINE_ID = sizes.OUT_SUBLINE_ID                              ',
'                and bpo.SUBLINE_NO = xtss.line_no                              ',
'                and bpo.prod_trans_id =                               ',
'                       sizes.prod_trans_id                               ',
'                and bpo.tracking_no =                               ',
'                       xtss.tracking_no                               ',
'                and bpo.stn_no =                               ',
'                       xtss.oc_no                               ',
'                and bpo.color = xtss.color                               ',
'                and bpo.SUBLINE_NO = xtss.LINE_NO                    ',
'                and sizes.size_val =                               ',
'                       replace (xtss.inseam_size_concat, ''~'', '''')                               ',
'                and sizes.inseem =                               ',
'                      xtss.INSEAM                             ',
'                and sizes.wip = 0                              ',
'                       ))',
'where tracking_no = :P102_TRACKING_NO;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P102_HEADER_ID,P102_TRACKING_NO,P102_PID'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Generate Purchase Order'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
end;
