wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(165635511753758223)
,p_event_id=>wwv_flow_imp.id(165634066251758220)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'auto save and call ajax'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var region = apex.region("SOP_Insert_item_IG");',
'var ig = region.widget();',
'var gridView = ig.interactiveGrid("getViews", "grid");',
'var model = gridView.model;',
'',
'var selected = model.getSelectedRecords();',
'',
'if (selected.length === 0) {',
'    apex.message.alert("Please select at least one row");',
'    return;',
'}',
'',
'var data = [];',
'',
'selected.forEach(function(rec){',
'    data.push({',
'        INSEAM_SIZE_CONCAT: model.getValue(rec, "INSEAM_SIZE_CONCAT"),',
'        INSEAM: model.getValue(rec, "INSEAM")',
'    });',
'});',
'',
'// Proper JSON output',
'console.log(''json data:'', JSON.stringify(data));',
'',
unistr('// \D83D\DD25 AJAX CALL'),
'apex.server.process(',
'    "INSERT_BULK_ONE_BY_ONE",',
'    {',
'        x01: JSON.stringify(data)',
'    },',
'    {',
unistr('        dataType: "text",   // \2705 plain text expect'),
'',
'        success: function(res){',
'            if (res === "SUCCESS") {',
'                apex.message.showPageSuccess("Inserted Successfully");',
'                region.refresh();',
'            } else {',
'                apex.message.alert(res); // show error text',
'            }',
'        },',
'',
'        error: function(req, status, error){',
'            console.error(error);',
'            apex.message.alert("Technical Error: " + error);',
'        }',
'    }',
');'))
);
