wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(165632731121758210)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_BULK_ONE_BY_ONE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json CLOB := apex_application.g_x01;',
'BEGIN',
'',
'    FOR rec IN (',
'        SELECT *',
'        FROM JSON_TABLE(',
'            l_json,',
'            ''$[*]''',
'            COLUMNS (',
'                SIZE_VAL VARCHAR2(200 BYTE) ',
'                    PATH ''$.INSEAM_SIZE_CONCAT'',',
'                INSEAM     VARCHAR2(200 BYTE)',
'                    PATH ''$.INSEAM''',
'                -- color       VARCHAR2(50) PATH ''$.color'',',
'                -- size_val    VARCHAR2(50) PATH ''$.size_val'',',
'                -- inseam      VARCHAR2(50) PATH ''$.inseam''',
'            )',
'        )',
'    )',
'    LOOP',
'        INSERT INTO PWC_MFG_LINEOUTPUT_DETAIL (',
'            OUT_SUBLINE_ID,',
'            PROD_TRANS_ID,',
'            SIZE_VAL,',
'            INSEEM',
'        )',
'        VALUES (',
'            :P102_PID,',
'            :P102_HEADER_ID,',
'            rec.SIZE_VAL,',
'            rec.INSEAM',
'        );',
'',
'        -- optional: commit per row (NOT recommended normally)',
'         COMMIT;',
'    END LOOP;',
'',
'    COMMIT;',
'    htp.p(''SUCCESS'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        htp.p(''ERROR: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>165632731121758210
);
end;
/
