'        <div class="user-avatar">',
'          <i class="fas fa-user-astronaut"></i>',
'        </div>',
'        <div class="user-details">',
'          <div class="user-name" id="currentUserName">AMIR</div>',
'          <div>',
'            <span class="user-badge" id="userRoleSpan">Authorized User</span>',
'          </div>',
