'    </div>',
'  </div>',
'',
'  <div class="dashboard-footer">',
'    <div class="footer-stat">',
'      <i class="fas fa-shield-alt" style="color:#38bdf8"></i>',
unistr('      <span>Role-based access \00B7 Unrestricted = Green badge</span>'),
'    </div>',
'    <div class="footer-stat">',
'      <i class="fas fa-chart-line" style="color:#facc15"></i>',
unistr('      <span>Click any card \2192 redirects to APEX page (if access granted)</span>'),
'    </div>',
'    <div class="footer-stat">',
'      <i class="fas fa-info-circle" style="color:#f97316"></i>',
'      <span>Use dropdown to switch users & see rights change instantly</span>',
'    </div>',
'  </div>',
'</div>',
'',
'<script>',
'  // ---------- PERMISSION MATRIX ----------',
'  const MODULES = [',
unistr('    { id: "om", name: "Receive from PAD (Finishing)", page: "91", icon: "fas fa-shopping-bag", desc: "Order Management \00B7 Procurement \00B7 Buyer Relations", allowed: ["ZAIN","AMIR","SABIR","NADEEM","SHAHID"] },'),
unistr('    { id: "prod", name: "Operation Plan", page: "100", icon: "fas fa-cogs", desc: "Floor Planning \00B7 WIP \00B7 Stitching Lines", allowed: ["ZAIN","AMIR","NADEEM","SHAHID"] },'),
unistr('    { id: "sample", name: "Finishing Production", page: "104", icon: "fas fa-palette", desc: "Proto Samples \00B7 Fit Samples \00B7 Tech Pack", allowed: ["ZAIN","NADEEM","SHAHID"] },'),
unistr('    /*{ id: "wash", name: "Washing Operation", page: "87", icon: "fas fa-water", desc: "Garment Wash \00B7 Enzyme \00B7 Dry Process", allowed: ["ZAIN","NADEEM","SHAHID"] },'),
unistr('    { id: "finish", name: "Finishing", page: "1", icon: "fas fa-flag-checkered", desc: "Quality Check \00B7 Ironing \00B7 Packing", allowed: ["ZAIN","NADEEM","SHAHID"] },'),
unistr('    { id: "report", name: "Reports & Analytics", page: "63", icon: "fas fa-chart-pie", desc: "KPI Dashboards \00B7 Efficiency Metrics", allowed: ["ZAIN","AMIR","SHAHID"] }*/'),
'  ];',
'',
'  // Complete users list for dropdown with display names',
'  const ALL_USERS = [',
unistr('    { val: ''ZAIN'',  display: ''\D83D\DC51 ZAIN (Full Access)'' },'),
unistr('    { val: ''AMIR'',  display: ''\2B50 AMIR (Full Access)'' },'),
unistr('    { val: ''SABIR'', display: ''\D83D\DD27 SABIR (OM + Merchandizing only)'' },'),
unistr('    { val: ''NADEEM'', display: ''\D83D\DCCA NADEEM (Full Access)'' },'),
unistr('    { val: ''SHAHID'', display: ''\D83D\DCC8 SHAHID (Full Access)'' },'),
unistr('    { val: ''GUEST'', display: ''\D83D\DEAB GUEST (Restricted - No Access)'' },'),
unistr('    { val: ''OTHER'', display: ''\274C OTHER (No Rights)'' }'),
'  ];',
'',
'  let currentSessionUser = "AMIR";',
'',
'  function hasAccess(user, allowedList) {',
'    return allowedList.includes(user);',
'  }',
'',
'  function showToast(message, isError = true) {',
'    let toast = document.getElementById(''globalToast'');',
'    if (!toast) {',
'      toast = document.createElement(''div'');',
'      toast.id = ''globalToast'';',
'      toast.className = ''toast-notify'';',
'      document.body.appendChild(toast);',
'    }',
'    const icon = isError ? ''<i class="fas fa-lock" style="color:#f97316"></i>'' : ''<i class="fas fa-check-circle" style="color:#4ade80"></i>'';',
'    toast.innerHTML = `${icon} ${message}`;',
'    toast.style.opacity = ''1'';',
'    toast.style.display = ''flex'';',
'    setTimeout(() => {',
'      toast.style.opacity = ''0'';',
'      setTimeout(() => {',
'        toast.style.display = ''none'';',
'      }, 300);',
'    }, 2500);',
'  }',
'',
'  // Function to get display name for a user',
'  function getUserDisplayName(username) {',
'    const found = ALL_USERS.find(u => u.val === username);',
'    if (found) {',
'      return found.display;',
'    }',
'    // Agar user ALL_USERS mein nahi hai to default format',
'    return `${username} (Current User)`;',
'  }',
'',
'  // Populate dropdown based on current user',
'  function populateDropdown() {',
'    const switcher = document.getElementById(''userSwitcher'');',
'    if (!switcher) return;',
'    ',
'    switcher.innerHTML = '''';',
'    ',
'    let optionsToShow = [];',
'    ',
'    if (currentSessionUser === ''AMIR'') {',
'      // AMIR ko full list dikhao',
'      optionsToShow = ALL_USERS;',
'    } else {',
'      // Baaki users ke liye sirf unki apni entry',
'      // Current user ko forcefully dikhao chahe woh ALL_USERS mein ho ya nahi',
'      optionsToShow = [{ ',
'        val: currentSessionUser, ',
'        display: getUserDisplayName(currentSessionUser) ',
'      }];',
'    }',
'    ',
'    // Add options to dropdown',
'    optionsToShow.forEach(opt => {',
'      const option = document.createElement(''option'');',
'      option.value = opt.val;',
'      option.textContent = opt.display;',
'      if (opt.val === currentSessionUser) {',
'        option.selected = true;',
'      }',
'      switcher.appendChild(option);',
'    });',
'    ',
'    // Debugging: Console mein check kar sakte hain',
'    console.log(''Dropdown populated for user:'', currentSessionUser);',
'    console.log(''Options shown:'', optionsToShow.length);',
'  }',
'',
'  function navigateTo(pageId, moduleName, allowedUsers) {',
'    if (!hasAccess(currentSessionUser, allowedUsers)) {',
unistr('      showToast(`\26D4 ACCESS DENIED! ${moduleName} requires: ${allowedUsers.join('', '')}`, true);'),
'      return false;',
'    }',
'    const apexUrl = `f?p=&APP_ID.:${pageId}:&SESSION.::&DEBUG.::::`;',
unistr('    showToast(`\2705 ACCESS GRANTED! Redirecting to ${moduleName}...`, false);'),
'    setTimeout(() => {',
'      window.location.href = apexUrl;',
'    }, 300);',
'    return true;',
'  }',
'',
'  function renderDashboard() {',
'    const grid = document.getElementById(''dynamicGrid'');',
'    if (!grid) return;',
'    grid.innerHTML = '''';',
'',
'    const userNameSpan = document.getElementById(''currentUserName'');',
'    const userRoleSpan = document.getElementById(''userRoleSpan'');',
'    if (userNameSpan) userNameSpan.innerText = currentSessionUser;',
'    ',
'    const hasAnyAccess = MODULES.some(mod => hasAccess(currentSessionUser, mod.allowed));',
'    if (userRoleSpan) {',
'      if (currentSessionUser === ''GUEST'' || !hasAnyAccess) {',
unistr('        userRoleSpan.innerText = ''\26A0\FE0F Restricted Access'';'),
'        userRoleSpan.style.background = ''rgba(239,68,68,0.2)'';',
'        userRoleSpan.style.color = ''#fca5a5'';',
'      } else {',
unistr('        userRoleSpan.innerText = ''\2705 Full Access User'';'),
'        userRoleSpan.style.background = ''rgba(34,197,94,0.2)'';',
'        userRoleSpan.style.color = ''#86efac'';',
'      }',
'    }',
'',
'    MODULES.forEach(module => {',
'      const isUnrestricted = hasAccess(currentSessionUser, module.allowed);',
'      const statusText = isUnrestricted ? "UNRESTRICTED" : "RESTRICTED";',
'      const statusClass = isUnrestricted ? "status-unrestricted" : "status-restricted";',
'      const statusIcon = isUnrestricted ? ''<i class="fas fa-unlock-alt"></i>'' : ''<i class="fas fa-ban"></i>'';',
'      ',
'      let cardClass = "card-om";',
'      if (module.id === "prod") cardClass = "card-prod";',
'      else if (module.id === "sample") cardClass = "card-sample";',
'      else if (module.id === "wash") cardClass = "card-wash";',
'      else if (module.id === "finish") cardClass = "card-finish";',
'      else if (module.id === "report") cardClass = "card-report";',
'      ',
'      const card = document.createElement(''div'');',
'      card.className = `module-card ${cardClass}`;',
'      card.onclick = (function(p, n, a) {',
'        return function() { navigateTo(p, n, a); };',
'      })(module.page, module.name, module.allowed);',
'      ',
'      const chipsHtml = module.allowed.map(user => ',
'        `<span class="user-chip"><i class="fas fa-user-check"></i> ${user}</span>`',
'      ).join('''');',
'      ',
'      card.innerHTML = `',
'        <div class="card-header-row">',
'          <div class="card-icon-circle">',
'            <i class="${module.icon}"></i>',
'          </div>',
'          <div class="access-status ${statusClass}">',
'            ${statusIcon} ${statusText}',
'          </div>',
'        </div>',
'        <div class="module-name">${module.name}</div>',
'        <div class="module-desc">',
'          <i class="fas fa-arrow-right" style="font-size: 0.6rem;"></i> ${module.desc}',
'        </div>',
'        <div class="auth-users">',
'          <span style="font-size:0.65rem; opacity:0.9; margin-right:6px;"><i class="fas fa-users"></i> Authorized:</span>',
'          ${chipsHtml}',
'        </div>',
'        <div class="access-footer">',
'          ${isUnrestricted ? ',
unistr('            ''<i class="fas fa-check-circle" style="color:#bbf7d0"></i> <span style="font-weight:600;">\2705 Click to access \2192</span>'' : '),
unistr('            ''<i class="fas fa-lock" style="color:#fecaca"></i> <span>\D83D\DD12 Restricted \00B7 Contact administrator</span>''}'),
'        </div>',
'      `;',
'      grid.appendChild(card);',
'    });',
'  }',
'',
'  function initUserSwitcher() {',
'    const switcher = document.getElementById(''userSwitcher'');',
'    if (!switcher) return;',
'    ',
'    switcher.addEventListener(''change'', (e) => {',
'      const newUser = e.target.value;',
'      currentSessionUser = newUser;',
'      populateDropdown();',
'      renderDashboard();',
unistr('      showToast(`\D83D\DD04 Switched to: ${newUser} \2014 Dashboard updated`, false);'),
'    });',
'  }',
'',
'  // On page load',
'  document.addEventListener(''DOMContentLoaded'', () => {',
'    let apexUser = "&APP_USER.";',
'    if (apexUser && apexUser !== "&APP_USER." && apexUser.trim() !== "") {',
'      currentSessionUser = apexUser.trim().toUpperCase();',
'    } else {',
'      currentSessionUser = "AMIR";',
'    }',
'    ',
'    console.log(''Current User:'', currentSessionUser);',
'    populateDropdown();',
'    renderDashboard();',
'    initUserSwitcher();',
'  });',
'</script>',
'</body>',
'</html>'))
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
end;
/
