,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'   ',
'SELECT fndtl1.LINE_ID,       ',
'       fndtl1.HEADER_ID,       ',
'       fndtl1.LINE_NO,       ',
'       fndtl1.CREATED_BY,       ',
'       fndtl1.CREATION_DATE,       ',
'       fndtl1.LAST_UPDATED_BY,       ',
'       fndtl1.LAST_UPDATE_DATE,       ',
'       fndtl1.BPO_NO,       ',
'       fndtl1.STN_NO,       ',
'       fndtl1.SALE_ORDER_ID,       ',
'       fndtl1.DAY_REJ,       ',
'       fndtl1.TOTAL_REJ,       ',
'       fndtl1.REMARKS,       ',
'       fndtl1.INVENTORY_ITEM_ID,       ',
'       fndtl1.PROD_TYPE,       ',
'       fndtl1.TRACKING_NO,       ',
'       fndtl1.Job_Id,       ',
'       fndtl1.Error_Message,       ',
'       fndtl1.Last_Action,       ',
'       fndtl1.Division_Id,       ',
'       fndtl1.Color,       ',
'       fndtl1.Total_Input,       ',
'       fndtl1.Day_Production,       ',
'       fndtl1.Total_Rejection,       ',
'       fndtl1.Day_Rejection,       ',
'       fndtl1.Wip,       ',
'       fndtl1.Producty_Type,       ',
'       fndtl1.Total_Production,       ',
'       fndtl1.Pre_Lineoutput,       ',
'       fndtl1.Bel_Lineoutout,       ',
'       fndtl1.Working_Hour_Basic,       ',
'       fndtl1.Manpower_Basic,       ',
'       fndtl1.Working_Hour_Overtime,       ',
'       fndtl1.Manpower_Overtime,       ',
'       fndtl1.Working_Hour_Extraot_1,       ',
'       fndtl1.REWORK_PRODUCTION,       ',
'       fndtl1.Man_Power_Extraot_1,       ',
'       fndtl1.Working_Hour_Extraot_2,       ',
'       fndtl1.Man_Power_Extraot_2,       ',
'       fndtl1.SAM,       ',
'       fndtl1.DAY_TARGET,       ',
'       fndtl1.OSP_UNIT,       ',
'       fndtl1.OSP_PRODUCTION,       ',
'       fndtl1.MERGE_BPO_NO,       ',
'       fndtl1.CHILD_STYLE_NO,       ',
'       fndtl1.STYLE_CATEGORY,       ',
'       pwc_master_tracking_data_func(fndtl1.tracking_no, ''BUYER_NAME'') buyer_name,       ',
'       pwc_master_tracking_data_func(fndtl1.tracking_no, ''BUYER_ID'') BUYER_ID,       ',
'       pwc_master_tracking_data_func(fndtl1.tracking_no, ''STYLE_NAME'') STYLE,       ',
'       pwc_master_tracking_data_func(fndtl1.tracking_no, ''STYLE_NO'') STYLE_NO,       ',
'       pwc_master_tracking_data_func(fndtl1.tracking_no, ''SEASON_NAME'') SEASON,       ',
'       NULL CURRENT_STYLE,       ',
'       NULL CURRENT_SEASON,       ',
'       (SELECT DISTINCT ooha.attribute12       ',
'           FROM apps.oe_order_headers_all@adf ooha       ',
'          WHERE ooha.header_id = fndtl1.SALE_ORDER_ID)       ',
'           replace_bpo,       ',
'       (SELECT DISTINCT ''Move Transaction is in error Please Check Pending Move Transaction Form''       ',
'             FROM apps.wip_txn_interface_errors@adf wtie, apps.wip_move_txn_interface@adf wmti, pwc_mfg_finish_prod_h mml       ',
'            WHERE     wmti.transaction_id = wtie.transaction_id       ',
'                  AND wmti.process_status = 3       ',
'                  AND TO_DATE (wmti.attribute10, ''DD-MON-YY'') = TRUNC (mml.doc_date)       ',
'                  AND mml.header_id = fndtl1.HEADER_ID       ',
'                  AND wmti.attribute13 = ''AUTO MOVE TXN FINISHING'')       ',
'             move_txn_error,       ',
'       NULL ORGANIC_AUTH,      ',
'      ',
'             fndtl1.material_issuance_flag mat_issue_check  ,     ',
'        /**************Total Order Quantity***************/     ',
'        (SELECT NVL (SUM (rpd.extra_ob_qty), 0)     ',
'           FROM pwc_mfg_routing_plan rp, pwc_mfg_routing_plan_obdet rpd     ',
'          WHERE     rp.header_id = rpd.header_id     ',
'                AND rp.process_id = 4     ',
'                AND rp.tracking_no = fndtl1.tracking_no     ',
'                AND rp.color = fndtl1.color) total_order_qty,     ',
'         /**************Color Wise Quantity***************/       ',
'         (select sum(DAY_PRODUCTION)     ',
'          from PWC_MFG_FINISH_PROD_L ll     ',
'          where ll.tracking_no = fndtl1.tracking_no     ',
'          and ll.color = fndtl1.color) color_wise_production ,     ',
'         /**************WIP Balance Quantity***************/      ',
'        (SELECT NVL (SUM (rpd.extra_ob_qty), 0)     ',
'           FROM pwc_mfg_routing_plan rp, pwc_mfg_routing_plan_obdet rpd     ',
'          WHERE     rp.header_id = rpd.header_id     ',
'                AND rp.process_id = 4     ',
'                AND rp.tracking_no = fndtl1.tracking_no     ',
'                AND rp.color = fndtl1.color) -     ',
'         (select sum(DAY_PRODUCTION)     ',
'          from PWC_MFG_FINISH_PROD_L ll     ',
'          where ll.tracking_no = fndtl1.tracking_no     ',
'          and ll.color = fndtl1.color) WIP_prod_balance  ,    ',
'          NVL((SELECT  DISTINCT ''Y'' FROM PWC_MFG_PACKING_PROD_L  L   , PWC_MFG_PACKING_PROD_D D WHERE L.LINE_ID = D.LINE_ID --AND L.P_TRACKING_NO = ''OMR-2302-0011''  ',
'AND D.PACKING_PROD_ID IS NOT NULL   ',
'AND L.HEADER_ID = fndtl1.HEADER_ID),''N'') PACKING_PROD_CHECK',
'  FROM PWC_MFG_FINISH_PROD_L fndtl1',
'  WHERE fndtl1.HEADER_ID=:P105_HEADER_ID ----   339;'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Finishing Production'
