'SELECT tb3.ADDITION_ID, ',
'       tb3.HEADER_ID, ',
'       tb3.LINE_NO, ',
'       tb3.TRACKING_NO, ',
'       tb3.COLOR, ',
'       tb3.WORKING_HOUR_BASIC, ',
'       tb3.MANPOWER_BASIC, ',
'       tb3.WORKING_HOUR_OVERTIME, ',
'       tb3.MANPOWER_OVERTIME, ',
'       tb3.WORKING_HOUR_EXTRAOT_1, ',
'       tb3.MAN_POWER_EXTRAOT_1, ',
'       tb3.WORKING_HOUR_EXTRAOT_2, ',
'       tb3.MAN_POWER_EXTRAOT_2, ',
'       tb3.TOTAL_ATTENDED_MINUTES, ',
'       tb3.CREATED_BY, ',
'       tb3.CREATION_DATE, ',
'       tb3.LAST_UPDATED_BY, ',
'       tb3.LAST_UPDATE_DATE, ',
'       tb3.PRODUCTION_BASIC, ',
'       tb3.PRODUCTION_OVERTIME, ',
'       tb3.PRODUCTION_EXTRAOT_1, ',
'       tb3.PRODUCTION_EXTRAOT_2, ',
'       tb3.CHILD_STYLE_NO, ',
'       tb3.STYLE_CATEGORY, ',
'       pwc_master_tracking_data_func(tb3.tracking_no, ''BUYER_NAME'') BUYER, ',
'       pwc_master_tracking_data_func(tb3.tracking_no, ''BUYER_ID'') BUYER_ID, ',
'       pwc_master_tracking_data_func(tb3.tracking_no, ''STYLE_NAME'') STYLE, ',
'       pwc_master_tracking_data_func(tb3.tracking_no, ''SEASON_NAME'') SEASON, ',
'       NULL CURRENT_STYLE, ',
'       NULL CURRENT_SEASON, ',
'  NULL ORGANIC_AUTH ',
'  FROM PWC_MFG_FINISH_PROD_ADDITION tb3',
'  WHERE tb3.HEADER_ID=339'))
