wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(166148697467381378)
,p_plug_name=>'Finishing Production'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--textContent:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(220356929123811014)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PwcMfgFinishProdH.HEADER_ID,         ',
'       PwcMfgFinishProdH.HEADER_NO,         ',
'       PwcMfgFinishProdH.DOC_DATE,         ',
'       PwcMfgFinishProdH.REMARKS,         ',
'       PwcMfgFinishProdH.ORG_ID,         ',
'       PwcMfgFinishProdH.CREATED_BY,         ',
'       PwcMfgFinishProdH.CREATION_DATE,         ',
'       PwcMfgFinishProdH.LAST_UPDATED_BY,         ',
'       PwcMfgFinishProdH.LAST_UPDATED_DATE,         ',
'       PwcMfgFinishProdH.Subinventory,         ',
'       PwcMfgFinishProdH.Posted_Status,         ',
'       PwcMfgFinishProdH.Attribute1,         ',
'       PwcMfgFinishProdH.Attribute2,         ',
'       PwcMfgFinishProdH.TOTAL_ATTENDED,         ',
'       PwcMfgFinishProdH.TOTAL_PRODUCTION,         ',
'       PwcMfgFinishProdH.OFF_STANDARD_MIN,         ',
'       PWC_FINISH_PROD_FUNC(''LINE_NO'', PwcMfgFinishProdH.HEADER_ID)  Line_No,         ',
'       PWC_FINISH_PROD_FUNC(''BUYER'', PwcMfgFinishProdH.HEADER_ID)  Buyer,         ',
'       PWC_FINISH_PROD_FUNC(''TRACKING_NO'', PwcMfgFinishProdH.HEADER_ID)  Tracking_No,         ',
'       PWC_FINISH_PROD_FUNC(''STYLE_NAME'', PwcMfgFinishProdH.HEADER_ID)  Style_Name,         ',
'       PWC_FINISH_PROD_FUNC(''SEASON'', PwcMfgFinishProdH.HEADER_ID)  Season,         ',
'       PWC_FINISH_PROD_FUNC(''COLOR'', PwcMfgFinishProdH.HEADER_ID) Color,         ',
'       TO_CHAR (PwcMfgFinishProdH.DOC_DATE, ''Mon-YYYY'') PRODUCTION_PERIOD,         ',
'       (SELECT fu.user_name         ',
'          FROM apps.fnd_user@adf fu         ',
'         WHERE fu.user_id = PwcMfgFinishProdH.CREATED_BY) CREATED_BY_USERNAME,        ',
'         PwcMfgFinishProdH.SHIFT_FIN_PROD,           ',
'          CASE           ',
'        WHEN EXTRACT(DAY FROM SYSDATE) > 3           ',
'            AND TRUNC(SYSDATE, ''MONTH'') > ADD_MONTHS(TRUNC(DOC_DATE, ''MONTH''), 0)           ',
'            THEN ''Y''     ',
'            WHEN EXTRACT(DAY FROM SYSDATE) <= 3           ',
'            AND TRUNC(SYSDATE, ''MONTH'') > ADD_MONTHS(TRUNC(DOC_DATE, ''MONTH''), 0)+ INTERVAL ''1'' MONTH            ',
'            THEN ''Y''     ',
'        ELSE ''''       ',
'        END     ',
'         DD_FLAG        ',
'  FROM PWC_MFG_FINISH_PROD_H PwcMfgFinishProdH         ',
' WHERE PwcMfgFinishProdH.ORG_ID =85-- :p_Org_Id'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
