prompt --application/pages/page_00106
begin
wwv_flow_imp_page.create_page(
 p_id=>106
,p_name=>'Fill BPOs'
,p_alias=>'FILL-BPOS'
,p_page_mode=>'MODAL'
,p_step_title=>'Fill BPOs'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#:ui-dialog--stretch'
,p_protection_level=>'C'
,p_page_component_map=>'21'
,p_last_updated_by=>'AMIR'
,p_last_upd_yyyymmddhh24miss=>'20260423162516'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(169293224852789289)
,p_plug_name=>'Fill BPOs'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>71
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT xtbb.production_date,     ',
'       xtbb.bpo_no,     ',
'       xtbb.merge_bpo_no,     ',
'       xtbb.header_id,     ',
'       xtbb.org_id,     ',
'       xtbb.tracking_no,     ',
'       xtbb.style_name,     ',
'       xtbb.season,     ',
'       xtbb.cust_account_id,     ',
'       xtbb.known_as,     ',
'       xtbb.organic_auth,     ',
'       xtbb.stn_no,     ',
'       xtbb.inventory_item_id,     ',
'       xtbb.wip_entity_id,     ',
'       xtbb.wip_entity_name,     ',
'       xtbb.color,     ',
'       xtbb.line_no,     ',
'       xtbb.quantity,     ',
'       xtbb.bel_qty,     ',
'       xtbb.rejection_total,     ',
'       xtbb.wip_qty,     ',
'       xtbb.day_target,     ',
'       xtbb.sam,     ',
'       xtbb.production_type,     ',
'       xtbb.current_style,     ',
'       xtbb.current_season,     ',
'       xtbb.replace_bpo,     ',
'       xtbb.child_style_no,     ',
'       xtbb.style_category     ',
'  FROM (  SELECT (SELECT TRUNC (MAX (h.doc_date))     ',
'                    FROM pwc_mfg_finish_prod_h h, pwc_mfg_finish_prod_l ll     ',
'                   WHERE     h.header_id = ll.header_id     ',
'                         AND ll.line_no = aa.line_no     ',
'                         AND ll.sale_order_id = aa.header_id     ',
'                         AND ll.prod_type = production_type     ',
'                         AND ll.color = aa.color     ',
'                         AND ll.tracking_no = aa.tracking_no     ',
'                         AND ll.bpo_no = aa.bpo_no-- AND ll.child_style_no = aa.child_style_no     ',
'                 )     ',
'                    production_date,     ',
'                 bpo_no,     ',
'                 merge_bpo_no,     ',
'                 header_id,     ',
'                 org_id,     ',
'                 tracking_no,     ',
'                 pwc_master_tracking_data_func (tracking_no, ''STYLE_NAME'') style_name,     ',
'                 pwc_master_tracking_data_func (tracking_no, ''SEASON_NAME'') season,     ',
'                 pwc_master_tracking_data_func (tracking_no, ''BUYER_ID'') cust_account_id,     ',
'                 pwc_master_tracking_data_func (tracking_no, ''BUYER_NAME'') known_as,     ',
'                 NULL organic_auth,     ',
'                 stn_no,     ',
'                 inventory_item_id,     ',
'                 wip_entity_id,     ',
'                 wip_entity_name,     ',
'                 color,     ',
'                 line_no,     ',
'                 SUM (quantity) quantity,     ',
'                 NVL (     ',
'                    (SELECT SUM (dd.day_prod)     ',
'                       FROM pwc_mfg_finish_prod_l ll, PWC_MFG_FINISH_PROD_D dd     ',
'                      WHERE     ll.line_id = dd.line_id     ',
'                            AND ll.line_no = aa.line_no     ',
'                            AND ll.sale_order_id = aa.header_id     ',
'                            AND ll.prod_type = aa.production_type     ',
'                            AND ll.color = aa.color     ',
'                            AND ll.tracking_no = aa.tracking_no     ',
'                            AND ll.bpo_no = aa.bpo_no),     ',
'                    0)     ',
'                    bel_qty,     ',
'                 NVL (     ',
'                    (SELECT SUM (NVL (dd.day_rejection, 0))     ',
'                       FROM pwc_mfg_finish_prod_l ll, PWC_MFG_FINISH_PROD_D dd     ',
'                      WHERE     ll.line_id = dd.line_id     ',
'                            AND ll.line_no = aa.line_no     ',
'                            AND ll.sale_order_id = aa.header_id     ',
'                            AND ll.prod_type = aa.production_type     ',
'                            AND ll.color = aa.color     ',
'                            AND ll.tracking_no = aa.tracking_no     ',
'                            AND ll.bpo_no = aa.bpo_no),     ',
'                    0)     ',
'                    rejection_total,     ',
'                   SUM (wip_qty)     ',
'                 - NVL (     ',
'                      (SELECT SUM (dd.DAY_PROD)     ',
'                         FROM pwc_mfg_finish_prod_l ll,     ',
'                              PWC_MFG_FINISH_PROD_D dd     ',
'                        WHERE     ll.line_id = dd.line_id     ',
'                              AND ll.line_no = aa.line_no     ',
'                              AND ll.sale_order_id = aa.header_id     ',
'                              AND ll.prod_type = aa.production_type     ',
'                              AND ll.color = aa.color     ',
'                              AND ll.tracking_no = aa.tracking_no     ',
'                              AND ll.bpo_no = aa.bpo_no),     ',
'                      0)     ',
'                /* - NVL (     ',
'                      (SELECT SUM (dd.day_rejection)     ',
'                         FROM pwc_mfg_finish_prod_l ll,     ',
'                              PWC_MFG_FINISH_PROD_D dd     ',
'                        WHERE     ll.line_id = dd.line_id     ',
'                              AND ll.line_no = aa.line_no     ',
'                              AND ll.sale_order_id = aa.header_id     ',
'                              AND ll.prod_type = aa.production_type     ',
'                              AND ll.color = aa.color     ',
'                              AND ll.tracking_no = aa.tracking_no     ',
'                              AND ll.bpo_no = aa.bpo_no),     ',
'                      0) */    ',
'                    wip_qty,     ',
'                 NVL (     ',
'                    (SELECT SUM (sopdetails.day_target)     ',
'                       FROM pwc_mfg_routing_plan_line_plan sopdetails     ',
'                      WHERE     sopdetails.header_id = aa.op_header_id     ',
'                            AND sopdetails.line_no = aa.line_no),     ',
'                    0)     ',
'                    day_target,     ',
'                 sam,     ',
'                 production_type,     ',
'                 NULL current_style,     ',
'                 NULL current_season,     ',
'                 replace_bpo,     ',
'                 child_style_no,     ',
'                 style_category     ',
'            FROM (SELECT ooha.cust_po_number bpo_no,     ',
'                         mmcl.attribute4 merge_bpo_no,     ',
'                         ooha.header_id,     ',
'                         mmr.header_id op_header_id,     ',
'                         ooha.org_id,     ',
'                         mmc.tracking_no,     ',
'                         ooha.cust_po_number || ''/'' || oola.line_number stn_no,     ',
'                         oola.inventory_item_id,     ',
'                         wdj.wip_entity_id,     ',
'                         wdj.wip_entity_name,     ',
'                         mmr.color color,     ',
'                         mmc.line_no,     ',
'                         mmcl.quantity,     ',
'                         NVL (mmcl.quantity, 0) wip_qty,     ',
'                         (NVL (     ',
'                             (SELECT (NVL (rpln.sam_finish, 0))     ',
'                                FROM pwc_mfg_routing_plan rpln     ',
'                               WHERE     rpln.tracking_no = mmc.tracking_no     ',
'                                     AND rpln.color = mmr.color     ',
'                                     AND ROWNUM = 1),     ',
'                             0))     ',
'                            sam,     ',
'                         mmcl.production_type,     ',
'                         ooha.attribute12 replace_bpo,     ',
'                         mmc.child_style_no,     ',
'                         mmc.style_category     ',
'                    FROM apps.oe_order_headers_all@adf ooha,     ',
'                         apps.oe_order_lines_all@adf oola,     ',
'                         pwc_mfg_issue_to_finish_h mmc,     ',
'                         pwc_mfg_issue_to_finish_l mmcl,     ',
'                         pwc_mfg_routing_plan mmr,     ',
'                         pwc_mfg_routing_plan_obdet mmrsa,     ',
'                         apps.wip_discrete_jobs_v@adf wdj,     ',
'                         pwc_mt_season_details_d d,     ',
'                         inv_org_ou_pwc_v v     ',
'                   WHERE     1 = 1     ',
'                         AND ooha.header_id = oola.header_id     ',
'                         AND mmc.header_id = mmcl.header_id     ',
'                         AND ooha.attribute4 = wdj.attribute2     ',
'                         AND mmc.tracking_no = mmr.tracking_no     ',
'                         --AND mmr.child_style_no = mmc.child_style_no     ',
'                         AND mmc.tracking_no = ooha.attribute4     ',
'                         AND mmr.process_id = 4     ',
'                         AND mmr.header_id = mmrsa.header_id     ',
'                         AND d.tracking_no = mmr.tracking_no     ',
'                         --   AND NVL(d.division, ''DENIM'') = :p_OrgType     ',
'                         AND mmrsa.obs_refno =     ',
'                                ooha.cust_po_number || ''/'' || oola.line_number     ',
'                         AND mmr.color = wdj.attribute4     ',
'                         AND mmr.wash = wdj.attribute5     ',
'                         --AND TO_CHAR (mmr.HEADER_ID) = wdj.attribute6     ',
'                         --  AND mmc.child_style_no = wdj.attribute6     ',
'                         AND wdj.class_code = ''Finishing''     ',
'                         AND wdj.organization_id = v.inv_org     ',
'                         -- AND :p_OrgType <> ''DENIM''     ',
'                         AND v.ou_id = ooha.org_id     ',
'                         AND ooha.org_id = :p106_org_id     ',
'                         AND ooha.cust_po_number || ''/'' || oola.line_number =     ',
'                                mmcl.attribute2     ',
'                         AND mmr.color = mmcl.attribute3     ',
'                         AND EXISTS     ',
'                                (SELECT DISTINCT 1     ',
'                                   FROM pwc_mfg_routing_plan foph,     ',
'                                        pwc_mfg_routing_plan_obdet fopl     ',
'                                  WHERE     foph.process_id = 4     ',
'                                        AND fopl.header_id = foph.header_id     ',
'                                        AND fopl.obs_refno =     ',
'                                                  ooha.cust_po_number     ',
'                                               || ''/''     ',
'                                               || oola.line_number)--                 AND (SELECT DISTINCT mmoda.final_mfg_org_id     ',
'                                                                   --                        FROM pwc_mfg_osp_dep_assign mmoda,     ',
'                                                                   --                             pwc_mfg_osp_stn_line mmosl,     ',
'                                                                   --                             pwc_mfg_osp_header mmoh     ',
'                                                                   --                       WHERE     mmoda.stn_line_id = mmosl.stn_line_id     ',
'                                                                   --                             AND mmoh.header_id = mmosl.header_id     ',
'                                                                   --                             AND mmoh.tracking_no = ooha.attribute4     ',
'                                                                   --                             AND mmosl.child_style_no = mmc.child_style_no     ',
'                                                                   --                             AND mmosl.stn =     ',
'                                                                   --                                       ooha.cust_po_number     ',
'                                                                   --                                    || ''/''     ',
'                                                                   --                                    || oola.line_number     ',
'                                                                   --                             AND mmosl.color = mmr.color     ',
'                                                                   --                             AND mmoda.final_department = ''Finishing''     ',
'                                                                   --                             AND ROWNUM = 1) = :p106_org_id     ',
'     ',
'                 ) AA     ',
'           WHERE 1 = 1     ',
'        -- and quantity <> 0     ',
'        GROUP BY bpo_no,     ',
'                 merge_bpo_no,     ',
'                 header_id,     ',
'                 org_id,     ',
'                 tracking_no,     ',
'                 stn_no,     ',
'                 inventory_item_id,     ',
'                 wip_entity_id,     ',
'                 wip_entity_name,     ',
'                 color,     ',
'                 line_no,     ',
'                 sam,     ',
'                 production_type,     ',
'                 op_header_id,     ',
'                 replace_bpo,     ',
'                 child_style_no,     ',
'                 style_category) xtbb     ',
' WHERE xtbb.wip_qty > 0     ',
'/***********************************************/       ',
'union all   --Merge BPO Scenario       ',
'/***********************************************/       ',
'SELECT xtb.production_date,       ',
'       xtb.bpo_no,       ',
'       xtb.merge_bpo_no,       ',
'       xtb.header_id,       ',
'       xtb.org_id,       ',
'       xtb.tracking_no,       ',
'       xtb.style_name,       ',
'       xtb.season,       ',
'       xtb.cust_account_id,       ',
'       xtb.known_as,       ',
'       xtb.organic_auth,       ',
'       xtb.stn_no,       ',
'       xtb.inventory_item_id,       ',
'       xtb.wip_entity_id,       ',
'       xtb.wip_entity_name,       ',
'       xtb.color,       ',
'       xtb.line_no,       ',
'       xtb.quantity,       ',
'       xtb.bel_qty,       ',
'       xtb.rejection_total,       ',
'       (xtb.wip_qty - xtb.bel_qty /*- xtb.rejection_total*/) wip_qty,       ',
'       xtb.day_target,       ',
'       xtb.sam,       ',
'       xtb.production_type,       ',
'       NULL current_style,       ',
'       NULL current_season,       ',
'       replace_bpo,       ',
'       xtb.child_style_no,       ',
'       xtb.style_category       ',
'  FROM (  SELECT xt.bpo_no,       ',
'                 xt.merge_bpo_no,       ',
'                 xt.header_id,       ',
'                 xt.org_id,       ',
'                 xt.tracking_no,       ',
'                 xt.style_name,       ',
'                 xt.season,       ',
'                 xt.cust_account_id,       ',
'                 xt.known_as,       ',
'                 xt.organic_auth,       ',
'                 xt.stn_no,       ',
'                 xt.inventory_item_id,       ',
'                 xt.wip_entity_id,       ',
'                 xt.wip_entity_name,       ',
'                 xt.color,       ',
'                 xt.line_no,       ',
'                 NVL (SUM (xt.quantity), 0) quantity,       ',
'                 NVL (SUM (wip_qty), 0) wip_qty,       ',
'                 /*NVL (       ',
'                    (SELECT   SUM (NVL (ll.day_production, 0))       ',
'                            + SUM (NVL (ll.osp_production, 0))       ',
'                       FROM pwc_mfg_finish_prod_l ll       ',
'                      WHERE     ll.line_no = xt.line_no       ',
'                            AND ll.prod_type = xt.production_type       ',
'                            AND ll.color = xt.color       ',
'                            AND ll.tracking_no = xt.tracking_no     ',
'                            and ll.bpo_no = xt.bpo_no),       ',
'                    0)       ',
'                    */     ',
'                    NVL (       ',
'                    (SELECT  SUM (dd.DAY_PROD)     ',
'                       FROM pwc_mfg_finish_prod_l ll ,     ',
'                            PWC_MFG_FINISH_PROD_D dd      ',
'                      WHERE  ll.line_id = dd.line_id        ',
'                            and ll.line_no = xt.line_no       ',
'                            AND ll.prod_type = xt.production_type       ',
'                            AND ll.color = xt.color       ',
'                            AND ll.tracking_no = xt.tracking_no     ',
'                            and ll.bpo_no = xt.bpo_no),       ',
'                    0)     ',
'                    bel_qty,       ',
'                 /*NVL (       ',
'                    (SELECT SUM (NVL (ll.day_rejection, 0))       ',
'                       FROM pwc_mfg_finish_prod_l ll       ',
'                      WHERE     ll.line_no = xt.line_no       ',
'                            AND ll.prod_type = xt.production_type       ',
'                            AND ll.color = xt.color       ',
'                            AND ll.tracking_no = xt.tracking_no     ',
'                            and ll.bpo_no = xt.bpo_no),       ',
'                    0)*/      ',
'                    NVL (       ',
'                    (SELECT sum(dd.DAY_REJECTION)     ',
'                       FROM pwc_mfg_finish_prod_l ll  ,     ',
'                            PWC_MFG_FINISH_PROD_D dd      ',
'                      WHERE  ll.line_id = dd.line_id       ',
'                            and ll.line_no = xt.line_no       ',
'                            AND ll.prod_type = xt.production_type       ',
'                            AND ll.color = xt.color       ',
'                            AND ll.tracking_no = xt.tracking_no     ',
'                            and ll.bpo_no = xt.bpo_no),       ',
'                    0)      ',
'                    rejection_total,       ',
'                 (SELECT NVL (SUM (day_target), 0)       ',
'                    FROM pwc_mfg_routing_plan rmf,       ',
'                         pwc_mfg_routing_plan_line_plan rlf       ',
'                   WHERE     1 = 1       ',
'                         AND rmf.process_id = 4                        --finsh       ',
'                         AND rmf.tracking_no = xt.tracking_no       ',
'                         AND rmf.header_id = rlf.header_id)       ',
'                    day_target,       ',
'                 (NVL (       ',
'                     (SELECT (NVL (rpln.sam_finish, 0))       ',
'                        FROM pwc_mfg_routing_plan rpln       ',
'                       WHERE     rpln.tracking_no = xt.tracking_no       ',
'                             AND rpln.color = xt.color       ',
'                             AND rpln.process_id = 4                   --finsh       ',
'                             AND ROWNUM = 1),       ',
'                     0))       ',
'                    sam,       ',
'                 xt.production_type,       ',
'                 xt.current_style,       ',
'                 xt.current_season,       ',
'                 xt.replace_bpo,       ',
'                 xt.child_style_no,       ',
'                 xt.style_category,       ',
'                 (SELECT TRUNC (MAX (h.doc_date))            ',
'                    FROM pwc_mfg_finish_prod_h h, pwc_mfg_finish_prod_l ll            ',
'                   WHERE     h.header_id = ll.header_id            ',
'                         AND ll.line_no = xt.line_no            ',
'                         AND ll.prod_type = xt.production_type            ',
'                         AND ll.color = xt.color            ',
'                         AND ll.tracking_no = xt.tracking_no      ',
'                         and ll.bpo_no = xt.bpo_no                 ',
'                         )            ',
'                    production_date       ',
'            FROM (SELECT l.attribute1 bpo_no,       ',
'                         l.attribute1 merge_bpo_no,       ',
'                         NULL header_id,       ',
'                         h.org_id,       ',
'                         h.tracking_no,       ',
'                         pwc_master_tracking_data_func (h.tracking_no,       ',
'                                                              ''STYLE_NAME'')       ',
'                            style_name,       ',
'                         pwc_master_tracking_data_func (h.tracking_no,       ',
'                                                              ''SEASON_NAME'')       ',
'                            season,       ',
'                         pwc_master_tracking_data_func (h.tracking_no,       ',
'                                                              ''BUYER_ID'')       ',
'                            cust_account_id,       ',
'                         pwc_master_tracking_data_func (h.tracking_no,       ',
'                                                              ''BUYER_NAME'')       ',
'                            known_as,       ',
'                         NULL organic_auth,       ',
'                         l.attribute2 stn_no,       ',
'                         wdj.primary_item_id inventory_item_id,       ',
'                         wdj.wip_entity_id,       ',
'                         wdj.wip_entity_name,       ',
'                         l.attribute3 color,       ',
'                         h.line_no,       ',
'                         l.quantity,       ',
'                         l.quantity wip_qty,       ',
'                         l.production_type,       ',
'                         NULL current_style,       ',
'                         NULL current_season,       ',
'                         NULL replace_bpo,       ',
'                         h.child_style_no,       ',
'                         h.style_category       ',
'                    FROM pwc_mfg_issue_to_finish_h h,       ',
'                         pwc_mfg_issue_to_finish_l l,       ',
'                         apps.wip_discrete_jobs_v@adf wdj,       ',
'                         apps.inv_org_ou_pwc_v@adf v       ',
'                   WHERE     1 = 1       ',
'                         --AND h.tracking_no = ''TOP001-2211-0015''       ',
'                         AND h.header_id = l.header_id       ',
'                         AND wdj.attribute2 = h.tracking_no       ',
'                         and wdj.ATTRIBUTE4 = l.ATTRIBUTE3      ',
'                         AND wdj.class_code = ''Finishing''       ',
'                         --AND wdj.attribute4 = ''ANTIQE_GR''       ',
'                         AND wdj.status_type NOT IN (7, 12)       ',
'                         AND v.ou_id = h.org_id       ',
'                         and l.attribute2 like ''%::%''       ',
'                          --and l.attribute1 = ''56061100-R03::56655600-R03''     ',
'                         AND v.ou_id =   :p106_org_id       ',
'                         AND v.organization_id = wdj.organization_id) xt       ',
'        GROUP BY xt.bpo_no,       ',
'                 xt.merge_bpo_no,       ',
'                 xt.header_id,       ',
'                 xt.org_id,       ',
'                 xt.tracking_no,       ',
'                 xt.style_name,       ',
'                 xt.season,       ',
'                 xt.cust_account_id,       ',
'                 xt.known_as,       ',
'                 xt.organic_auth,       ',
'                 xt.stn_no,       ',
'                 xt.inventory_item_id,       ',
'                 xt.wip_entity_id,       ',
'                 xt.wip_entity_name,       ',
'                 xt.color,       ',
'                 xt.line_no,       ',
'                 xt.production_type,       ',
'                 xt.current_style,       ',
'                 xt.current_season,       ',
'                 xt.replace_bpo,       ',
'                 xt.child_style_no,       ',
'                 xt.style_category) xtb     ',
'where (xtb.wip_qty - xtb.bel_qty) > 0'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_page_header=>'Fill BPOs'
);
wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(169128655662030714)
,p_name=>'APEX$ROW_ACTION'
,p_item_type=>'NATIVE_ROW_ACTION'
,p_display_sequence=>20
);
wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(169128790183030715)
,p_name=>'APEX$ROW_SELECTOR'
,p_item_type=>'NATIVE_ROW_SELECTOR'
,p_display_sequence=>10
,p_attribute_01=>'Y'
,p_attribute_02=>'Y'
,p_attribute_03=>'N'
