wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(166961190279689720)
,p_plug_name=>'Packing Production'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT FINTBL1.LINE_ID,                ',
'       FINTBL1.HEADER_ID,                ',
'       FINTBL1.P_LINE_NO,                ',
'       FINTBL1.P_BPO_NO,                ',
'       FINTBL1.P_TRACKING_NO,                ',
'       FINTBL1.P_STN_NO,                ',
'       FINTBL1.P_SALE_ORDER_ID,                ',
'       FINTBL1.P_REMARKS,                ',
'       FINTBL1.P_INVENTORY_ITEM_ID,                ',
'       FINTBL1.P_PROD_TYPE,                ',
'       FINTBL1.DIVISION_ID,                ',
'       FINTBL1.P_FINISHING_PROD,                ',
'       FINTBL1.P_DAY_PRODUCTION,                ',
'       FINTBL1.P_TOTAL_PRODUCTION,                ',
'       FINTBL1.P_WIP,                ',
'       FINTBL1.P_COLOR,                ',
'       FINTBL1.CREATED_BY,                ',
'       FINTBL1.CREATION_DATE,                ',
'       FINTBL1.LAST_UPDATED_BY,                ',
'       FINTBL1.LAST_UPDATE_DATE,               ',
'       FINTBL1.P_MERGE_BPO_NO,               ',
'       FINTBL1.P_CHILD_STYLE_NO,               ',
'       FINTBL1.P_STYLE_CATEGORY,               ',
'       pwc_master_tracking_data_func(FINTBL1.p_tracking_no, ''BUYER_ID'') BUYER_ID,               ',
'       pwc_master_tracking_data_func(FINTBL1.p_tracking_no, ''STYLE_NAME'') STYLE,               ',
'       pwc_master_tracking_data_func(FINTBL1.p_tracking_no, ''STYLE_NO'') STYLE_NO,               ',
'       pwc_master_tracking_data_func(FINTBL1.p_tracking_no, ''SEASON_NAME'') SEASON,               ',
'       pwc_master_tracking_data_func(FINTBL1.p_tracking_no, ''BUYER_NAME'') buyer_name,               ',
'       (SELECT DISTINCT ooha.attribute12               ',
'          FROM APPS.oe_order_headers_all@ADF ooha               ',
'         WHERE ooha.header_id = FINTBL1.P_SALE_ORDER_ID)               ',
'          p_replace_bpo,               ',
'       (SELECT DISTINCT ''Move Transaction is in error Please Check Pending Move Transaction Form''               ',
'             FROM APPS.wip_txn_interface_errors@ADF wtie, APPS.wip_move_txn_interface@ADF wmti, pwc_mfg_finish_prod_h mml               ',
'            WHERE     wmti.transaction_id = wtie.transaction_id               ',
'                  AND wmti.process_status = 3               ',
'                  AND TO_DATE (wmti.attribute10, ''DD-MON-YY'') = TRUNC (mml.doc_date)               ',
'                  AND mml.header_id = FINTBL1.HEADER_ID               ',
'                  AND wmti.attribute13 = ''AUTO MOVE TXN PACKING'')               ',
'             p_move_txn_error,               ',
'       NULL ORGANIC_AUTH,              ',
'       FINTBL1.CARTON_REQUIRED,              ',
'       FINTBL1.CARTON_PENDING,             ',
'       FINTBL1.SUM_CARTON_PACKED,            ',
'        0 PENDING_CARTON_QTY,          ',
'        0 SUM_OF_CARTON_QTY,     ',
'     FINTBL1.pack_material_issuance_flag line_enable_status   ',
'FROM PWC_MFG_PACKING_PROD_L FINTBL1 ',
' WHERE FINTBL1.header_id=:P108_HEADER_ID'))
,p_plug_source_type=>'NATIVE_IG'
