,p_plug_template=>wwv_flow_imp.id(220304475512810961)
,p_plug_display_sequence=>21
,p_plug_grid_column_span=>5
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT ',
'                ''select'' as id,',
'                bpo.bpo_number,      ',
'                bpo.sale_order_id,      ',
'                NULL child_style_no,      ',
'                ooha.attribute3 classification      ',
'  FROM pwc_ont_wvn_sizewise_details_h sdh,      ',
'       APPS.mtl_system_items@ADF msi,      ',
'       pwc_ont_wvn_master_bom_bpo_l bpo,    ',
'       APPS.oe_order_lines_all@ADF oola,    ',
'       APPS.oe_order_headers_all@ADF ooha      ',
' WHERE     sdh.sales_order_id = bpo.sale_order_id      ',
'       AND ooha.flow_status_code <> ''CANCELLED''      ',
'       AND ooha.header_id = bpo.sale_order_id      ',
'       AND ooha.cust_po_number = bpo.bpo_number    ',
'       AND oola.header_id = bpo.sale_order_id     ',
'       AND oola.inventory_item_id = sdh.inventory_item_id     ',
'       AND ooha.header_id = oola.header_id     ',
'       AND oola.ordered_quantity <> 0  ',
'       AND NVL (bpo.final_order_quantity, 0) > 0  ',
'       AND NVL (oola.attribute2, ''No'') = ''No''   ',
'       AND NVL (oola.attribute6, ''Active'') = ''Active''    ',
'       AND bpo.header_id = :P109_HEADERID      ',
'       AND :P109_TRACKINGMODE = ''MS''      ',
'       AND msi.organization_id = :P109_InvoicingUnitId      ',
'       AND msi.inventory_item_id = sdh.inventory_item_id      ',
'       AND    bpo.sale_order_id      ',
'           || ''::''      ',
'           || REGEXP_SUBSTR (msi.description,      ',
'                             ''[^:]+'',      ',
'                             1,      ',
'                             3) NOT IN      ',
'              (SELECT DISTINCT obline.sale_order_id || ''::'' || obline.colour      ',
'                 FROM pwc_ont_wvn_master_bom_genrc_d obline      ',
'                WHERE obline.line_id = :P109_LineId)      ',
'UNION      ',
'SELECT DISTINCT ',
'                ''select'' as id,',
'                bpo.bpo_number,      ',
'                bpo.sale_order_id,      ',
'                oola.attribute4 child_style_no,      ',
'                ooha.attribute3 classification      ',
'  FROM pwc_ont_wvn_sizewise_details_h sdh,      ',
'       APPS.mtl_system_items@ADF msi,      ',
'       pwc_ont_wvn_master_bom_bpo_l bpo,      ',
'       APPS.oe_order_lines_all@ADF oola,      ',
'       APPS.oe_order_headers_all@ADF ooha      ',
' WHERE     sdh.sales_order_id = bpo.sale_order_id      ',
'       AND oola.header_id = bpo.sale_order_id      ',
'       AND oola.inventory_item_id = sdh.inventory_item_id      ',
'       AND ooha.flow_status_code <> ''CANCELLED''      ',
'       AND ooha.header_id = bpo.sale_order_id      ',
'       AND ooha.cust_po_number = bpo.bpo_number      ',
'       AND ooha.header_id = oola.header_id     ',
'       AND oola.ordered_quantity <> 0      ',
'       AND NVL (oola.attribute2, ''No'') = ''No''   ',
'       AND NVL (bpo.final_order_quantity, 0) > 0  ',
'       AND NVL (oola.attribute6, ''Active'') = ''Active''     ',
'       AND oola.attribute4 = :P109_ChildStyleNo      ',
'       AND bpo.header_id = :P109_HEADERID     ',
'       AND :P109_TRACKINGMODE = ''CS''      ',
'       AND msi.organization_id = :P109_InvoicingUnitId      ',
'       AND msi.inventory_item_id = sdh.inventory_item_id      ',
'       AND    bpo.sale_order_id      ',
'           || ''::''      ',
'           || REGEXP_SUBSTR (msi.description,      ',
'                             ''[^:]+'',      ',
'                             1,      ',
'                             3) NOT IN      ',
'              (SELECT DISTINCT obline.sale_order_id || ''::'' || obline.colour      ',
'                 FROM pwc_ont_wvn_master_bom_genrc_d obline      ',
'                WHERE obline.line_id = :P109_LineId)'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P109_HEADERID,P109_TRACKINGMODE,P109_INVOICINGUNITID,P109_LINEID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
