'                   colour   ',
'  FROM pwc_ont_wvn_sizewise_details_h sdh,   ',
'       APPS.mtl_system_items@ADF msi,   ',
'       pwc_ont_wvn_master_bom_bpo_l bpo,   ',
'       APPS.oe_order_lines_all@ADF oola,   ',
'       APPS.oe_order_headers_all@ADF ooha   ',
' WHERE     msi.organization_id = :p109_InvoicingUnitId   ',
