,p_default_type=>'SQL_QUERY'
,p_default_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    CASE ',
'        WHEN H.FASHION_CATEGOREY = ''Basic'' THEN 18.27',
'        WHEN H.FASHION_CATEGOREY = ''Fashion'' THEN 22.83',
'        WHEN H.FASHION_CATEGOREY = ''Semi Fashion'' THEN 21.49',
'        WHEN H.FASHION_CATEGOREY = ''High Fashion'' THEN 26.10',
'        ELSE L.CUTTING_COST ',
'    END AS CUTTING_COST_VAL',
'FROM PWC_ONT_WVN_PRECOSTING_L L,PWC_ONT_WVN_PRECOSTING_H H',
'    where  H.HEADER_ID = L.HEADER_ID',
'    and h.fashion_categorey=:P112_FASHION_CATEGOREY',
'--and  L.HEADER_ID = :P112_HEADER_ID',
'',
