wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(179418959855382334)
,p_event_id=>wwv_flow_imp.id(179418441254382332)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'COLUMN'
,p_affected_elements=>'PROCESS_ID,PROCESS_RATE,RATE,OVER_HEAD_RATE'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'      SELECT',
'       SUBSTR(QR.CHARACTER6, 2) AS process_id,           ',
'      -- QR.CHARACTER1 AS process_type,                   ',
'       ROUND(QR.CHARACTER12, 3) AS process_rate,',
'       ROUND(QR.CHARACTER12 + (QR.CHARACTER12 * 0.85), 3) AS rate,',
'       ROUND(QR.CHARACTER12 * 0.85, 3) AS over_head_cost',
'FROM apps.QA_RESULTS@adf QR',
'WHERE 1=1',
'      and QR.PLAN_ID = 65130',
'      AND QR.CHARACTER2 = ''Dry Process''',
'      --AND ''Dry'' = :ProcessType ',
'      AND QR.CHARACTER3 = :process_name',
'',
'',
'',
'',
'-- SELECT   ',
'--        --QR.CHARACTER3 process_name, ',
'--         --SUBSTR (QR.CHARACTER6, 2) processs_id,  ',
'--        QR.CHARACTER12 Process_Rate,       ',
'--        (QR.CHARACTER12 + (QR.CHARACTER12 * 0.85)) rate,       ',
'--        (QR.CHARACTER12 * 0.85) OVER_HEAD_COST  ',
'     ',
'',
'--   FROM apps.QA_RESULTS@adf QR, apps.QA_PLANS@adf QP       ',
'--  WHERE     QR.PLAN_ID = QP.PLAN_ID       ',
'--        AND QP.NAME = ''PWC_OPERATION_BULLETIN_DETAILS''       ',
'--       -- AND ''Dry'' = :p_ProcessType       ',
'--        AND QR.CHARACTER1 = ''WASHING''       ',
'--        AND QR.CHARACTER2 = ''Dry Process''',
'--        and QR.CHARACTER3  =  :process_name      ',
'',
'',
'-- SELECT',
'--        ROUND(QR.CHARACTER12, 2) AS process_rate,',
'--        ROUND(QR.CHARACTER12 + (QR.CHARACTER12 * 0.85) ) AS rate,',
'--         ROUND(QR.CHARACTER12 * 0.85 ) AS over_head_cost',
'',
'-- FROM apps.QA_RESULTS@adf QR',
'--      JOIN apps.QA_PLANS@adf QP',
'--        ON QR.PLAN_ID = QP.PLAN_ID',
'-- WHERE QP.NAME = ''PWC_OPERATION_BULLETIN_DETAILS''',
'--   AND QR.CHARACTER1 = ''WASHING''',
'--   AND QR.CHARACTER2 = ''Dry Process''',
'--   AND QR.CHARACTER3 = :process_name;',
''))
,p_attribute_07=>'PROCESS_NAME'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
end;
