 p_id=>wwv_flow_imp.id(179419849988382335)
,p_event_id=>wwv_flow_imp.id(179419371504382334)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_style_name   VARCHAR2(200);',
'    v_season_name  VARCHAR2(200);',
'    v_style_no     VARCHAR2(100);',
'    v_brand_name   VARCHAR2(100);',
'BEGIN',
'    SELECT',
'        sl.style_name,',
'        sd.season_name,',
'        sl.style_number,',
'        bd.brand_description',
'    INTO',
'        v_style_name,',
'        v_season_name,',
'        v_style_no,',
'        v_brand_name',
'    FROM   pwc_mt_season_details_d sd',
'    JOIN   pwc_mt_style_details_l sl',
'           ON sd.style_line_id = sl.style_line_id',
'    JOIN   pwc_mt_brand_details_d bd',
'           ON sl.brand_line_id = bd.brand_line_id',
'    WHERE  sd.tracking_no = :P112_TRACKING_NO;',
'',
'    :P112_STYLE_NAME    := v_style_name;',
'    :P112_SEASON_NAME   := v_season_name;',
'    :P112_STYLE_NUMBER  := v_style_no;',
'    :P112_BRAND_NAME    := v_brand_name;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P112_STYLE_NAME    := NULL;',
'        :P112_SEASON_NAME   := NULL;',
'        :P112_STYLE_NUMBER  := NULL;',
'        :P112_BRAND_NAME    := NULL;',
'END;',
'',
'-- DECLARE',
'--     v_style_name  VARCHAR2(200);',
'--     v_season_name VARCHAR2(200);',
'--     v_style_no    VARCHAR2(100);',
'--     v_brand_name  VARCHAR2(100);',
'-- BEGIN',
'--     SELECT',
'--         pwc_master_tracking_data_func(:P112_TRACKING_NO, ''STYLE_NAME''),',
'--         pwc_master_tracking_data_func(:P112_TRACKING_NO, ''SEASON_NAME''),',
'--         pwc_master_tracking_data_func(:P112_TRACKING_NO, ''STYLE_NO''),',
'--         h.BRAND_NAME',
'--     INTO',
'--         v_style_name,',
'--         v_season_name,',
'--         v_style_no,',
'--         v_brand_name',
'--     FROM PWC_ONT_WVN_PRECOSTING_H h',
'--     WHERE h.TRACKING_NO = :P112_TRACKING_NO;',
'',
'--     -- Assign to page items',
'--     :P112_STYLE_NAME  := v_style_name;',
'--     :P112_SEASON_NAME := v_season_name;',
'--     :P112_STYLE_NUMBER    := v_style_no;',
'--     :P112_BRAND_NAME  := v_brand_name;',
'',
'-- EXCEPTION',
'--     WHEN NO_DATA_FOUND THEN',
'--         :P112_STYLE_NAME  := NULL;',
'--         :P112_SEASON_NAME := NULL;',
'--         :P112_STYLE_NUMBER    := NULL;',
'--         :P112_BRAND_NAME  := NULL;',
'-- END;',
'',
''))
,p_attribute_02=>'P112_TRACKING_NO'
,p_attribute_03=>'P112_STYLE_NUMBER,P112_SEASON_NAME,P112_STYLE_NAME,P112_BRAND_NAME'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
